export default [{"id":2843,"title":"مقتل فتح الدين البققي على الزندقة بمصر .","date":["العام الهجري :701","الشهر القمري : ربيع الأول","العام الميلادي :1301"],"text":"قُتِلَ الفتح أحمدُ بن البققي بالدِّيار المصريَّة في يوم الاثنين الرابعَ والعشرين من ربيع الأول، حَكَم فيه القاضي زين الدين بن مخلوف المالكي بما ثَبَت عنده من تنقيصِه للشَّريعةِ واستهزائِه بالآيات المحكماتِ، ومعارضةِ المُشتَبِهاتِ بَعضِها ببعض، فيُذكَرُ عنه أنه كان يحِلُّ المحَرَّمات من اللواطِ والخمر وغير ذلك، لمن كان يجتَمِعُ به من الفَسَقةِ من الترك وغيرِهم من الجهلة، هذا وقد كان له اشتغالٌ وهيئةٌ جميلة في الظاهر، وبزّتُه ولبستُه جيدة، وقد كان ذكيًّا حاد الخاطِرِ له معرفةٌ بالأدب والعلوم القديمة، فحُفِظَت عنه سقطاتٌ، منها أنه قال: لو كان لصاحِبِ مقامات الحريري حظٌّ لتُلِيَت مقاماتُه في المحاريبِ، وأنَّه كان يُنكِرُ على من يصوم شهر رمضانَ، ولا يصوم هو، وأنه كان إذا تناوَلَ حاجةً مِن الرَّفِّ صَعِدَ بقدميه على الربعةِ، وكان مع ذلك جريئًا بلسانِه، مستخفًّا بالقضاة يَطنُزُ بهم ويستجهِلُهم، ثم أكثَرَ من الوقيعة في حقِّ زين الدين على بن مخلوف قاضي قضاة المالكيَّة وتنَقَّصَه وسَبَّه، فلما بلغه ذلك عنه اشتَدَّ حَنَقُه وقام في أمرِه، فتقَرَّبَ الناس إليه بالشَّهادةِ على ابن البققي، فاستدعاه وأحضَرَ الشهود فشَهِدوا وحكَم بقتله، وأراد مِن ابن دقيق العيد تنفيذَ ما حَكَم به فتوقَّفَ، وقام في مساعدةِ ابن البققي ناصرُ الدين محمد بن الشيخي وجماعةٌ من الكُتَّاب، وأرادوا إثباتَ جنِّه ليُعفى من القتل، فصَمَّمَ ابن مخلوف على قتله، واجتمع بالسلطانِ ومعه قاضي القضاة شمس الدين السروجي الحنفي، وما زالا به حتى أذِنَ في قتله، فنزلا إلى المدرسة الصالحيَّة بين القصرين ومعهما ابن الشيخي والحاجب، وأحضر ابن البققي من السجنِ في الحديد ليُقتَلَ، فصار يصيحُ ويقول: أتقتلون رجلًا أن يقولَ ربِّيَ اللهُ، ويتشَهَّد؟!! فلم يلتَفِتوا إلى ذلك، وضُرِبَ عُنُقُه وطيف برأسِه على رمح، وعُلِّقَ جَسَدُه على باب زويلة، وفيه يقولُ شهاب الدين أحمد بن عبد الملك الأعزازي يحَرِّضُ على قتله، وكتَبَ بها إلى ابنِ دقيق العيد: قل للإمامِ العادل المرتضيوكاشِفِ المُشكِلِ والمبهَمِ لا تمهِلِ الكافِرَ واعمَلْ بما قد جاء في الكافِرِ عن مُسلمِ ومن شعر ابن البققي ما كتب به إلى القاضي المالكي من السجن، وهو من جملةِ حماقاته: يا لابسًا لي حُلَّةً مِن مَكْرِهبسلاسة نعمت كلمس الأرقماعتد لي زردًا تضايقَ نَسجُهوعلى خرق عيونها بالأسهم فلما وقف عليهما القاضي المالكي، قال: نرجو أنَّ اللهَ لا يُمهِلُه لذلك."},{"id":2844,"title":"وفاة الخليفة العباسي الحاكم بأمر الله وتولى الخلافة ابنه أبو الربيع .","date":["العام الهجري :701","الشهر القمري : جمادى الأولى","العام الميلادي :1302"],"text":"هو أميرُ المؤمنينَ الخليفةُ الحاكِمُ بأمر الله أبو العباس أحمد بن المسترشد بالله الهاشمي العباسي البغدادي المصري، بويِعَ بالخلافة بالدَّولةِ الظاهرية في أول سنة 661، فاستكمل أربعينَ سنةً في الخلافة، وتوفِّيَ ليلة الجمعةِ ثامن عشر جمادى الأولى، وصُلِّيَ عليه بجامع ابن طولون، ودُفِنَ بجوار المشهد النفيسي وقتَ صلاةِ العَصرِ بسوق الخيل، وحَضَر جنازته الأعيانُ والدولةُ كُلُّهم مُشاةً، وكان قد عَهِدَ بالخلافة إلى وَلَدِه أبي الربيع سليمان، وتلقَّبَ بالمستكفي باللهِ، وقرئ كتاب تقليدِه بالخلافة بحَضرةِ السلطان المَلِك الناصر محمد بن قلاوون والدَّولة يوم الأحد عشرين من ذي الحجة مِن هذه السنة، وخُطِبَ له على المنابِرِ بالبلادِ المصريَّة والشاميَّة، وسارت بذلك البريديَّةُ إلى جميع البلاد الإسلاميَّة."},{"id":2845,"title":"فتنة الأعراب في صعيد مصر .","date":["العام الهجري :701","الشهر القمري : جمادى الآخرة","العام الميلادي :1302"],"text":"كثُرَ فَسادُ العُربان بالوجه القبلي، وتعَدَّى شَرُّهم في قَطعِ الطَّريقِ إلى أن فَرَضوا على التجَّار وأرباب المعايش بأسيوط ومنفلوط فرائِضَ جَبَوها شبه الجماليَّة، واستخَفُّوا بالولاة ومنعوا الخراجَ، وتَسَمَّوا بأسماء الأمراء، وجعلوا لهم كبيرينِ أحدهما سَمَّوه بيبرس، والآخر سلار، ولبسوا الأسلحةَ وأخرجوا أهلَ السُّجونِ بأيديهم، فاستدعى الأمراءُ القُضاةَ والفُقَهاءَ، واستفتَوهم في قتالِهم، فأفتَوهم بجواز ذلك، فاتَّفَق الأمراء على الخروج لقتالِهم وأخْذِ الطرق عليهم، لئلا يمتَنِعوا بالجبالِ والمفاوزِ فيَفوتَ الغَرَضُ فيهم، فاستدعَوا الأمير ناصر محمد بن الشيخي متولي الجيزية, وغيرَه من ولاة العمل، وتقَدَّموا إليه بمنع الناسِ بأَسرِهم من السفر إلى الصعيدِ في البَرِّ والبحر، ومَن ظَهَر أنه سافر كانت أرواحُ الولاة قبالةَ ذلك، فاشتَدَّ حِرصُهم، وأشاع الأمراءُ أنَّهم يريدون السَّفَرَ إلى الشام، وكُتِبَت أوراق الأمراء المسافرين، وهم عشرونَ مُقَدَّمًا بمضافيهم، وعيَّنوا أربعة أقسام: قسمٌ يتوَجَّهُ في البر الغربي من النيلِ، وقِسمٌ في البَرِّ الشرقي، وقِسمٌ يركب النيل، وقِسمٌ يمضى في الطريق السالكةِ، وتوجه الأميرُ شمس الدين سنقر الأعسر إلى جهة ألواح في خمسةِ أمراء، وقرر أن يتأخَّرَ مع السلطان أربعةُ أمراء من المقَدَّمين، وتقَدَّمَ إلى كُلِّ مَن تعَيَّنَ لجهة أن يضَعَ السَّيفَ في الكبير والصَّغيرِ والجليل والحقير، ولا يُبقُوا شيخًا ولا صبيًّا، ويحتاطوا على سائِرِ الأموال، وسار الأميرُ سلار في رابع جمادى الآخرة ومعه جماعةٌ من الأمراء في البر الغربي، وسار الأميرُ بيبرس بمن معه في الحاجر في البر الغربي على طريق الواحات، وسار الأميرُ بكتاش أميرُ سلاحٍ بمن معه إلى الفيوم وسار الأميرُ بكتمر الجوكندار بمن معه في البرِّ الشرقي، وسار قتالُ السبع وبيبرس الدوادار وبلبان الغلشي وعرب الشرقية إلى السويس والطور، وسار الأميرُ قبجق ومن معه إلى عقبةِ السَّيل، وسار طقصبا والي قوص بعرب الطاعةِ وأخذ عليهم المفازاتِ، وضَرَبَ الأمراءُ على الوجه القبلي حلقةً كحلقةِ الصيدِ، وقد عُمِّيَت أخبارُهم على أهل الصعيد، فطَرَقوا البلادَ على حينِ غَفلةٍ مِن أهلها، ووضَعوا السيفَ في الجيزيَّة بالبر الغربيِّ والإطفيحية من الشرق، فلم يتركوا أحدًا حتى قَتَلوه، ووسطوا نحو عشرة آلاف رجلٍ، وما منهم إلَّا من أخذوا مالَه وسَبَوا حريمه، فإذا ادَّعى أحدٌ أنَّه حَضَريٌّ قيل له قل: دقيق، فإن قال بقاف العَرَبِ قُتِلَ، ووقع الرعبُ في قلوبِ العُربان حتى طَبَّق عليهم الأمراءُ، وأخَذوهم مِن كُلِّ جِهةٍ فَرُّوا إليها، وأخرَجوهم من مخابِئِهم حتى قَتَلوا مَن بجانبي النيلِ إلى قوص، وجافت الأرضُ بالقتلى، واختفى كثيرٌ منهم بمغائِرِ الجبالِ، فأُوقِدَت عليهم النيرانُ حتى هلكوا عن آخِرِهم، وأُسِرَ منهم نحوُ ألف وستمائة لهم فلاحات وزروع، وحَصَل من أموالهم شيءٌ عَظيمٌ جدًّا تفَرَّقَتْه الأيدي، وأُحضِرَ منه للديوان ستة عشر ألف رأسٍ من الغنم، من جملةِ ثمانين ألف رأسٍ ما بين ضأن وماعز، ونحو أربعةِ آلاف فرس واثنين وثلاثين ألف جمل، وثمانية آلاف رأس من البقر، غيرَ ما أُرصِدَ في المعاصر، ومن السِّلاحِ نحو مائتين وستين حملًا ما بين سيوف ورماح، ومن الأموالِ على بغالٍ مُحَمَّلة مائتين وثمانين بغلًا، ثم عاد العسكَرُ في سادس عشر رجب، وقد خلت البلادُ بحيث كان الرجلُ يمشي فلا يجِدُ في طريقه أحدًا، وينزِلُ بالقرية فلا يرى إلا النِّساءَ والصِّبيانَ والصِّغارَ، فأفرجوا عن المأسورينَ وأعادوهم لحِفظِ البلاد، وكان الزَّرعُ في هذه السنة بالوجه القبلي عظيمًا إلى الغاية، تحصَّلَ منه ما لم يُقدَرْ قَدرُه كَثرةً."},{"id":2846,"title":"اتهام شيخ الإسلام ابن تيمية بالتعدي على حدود السلطان .","date":["العام الهجري :701","الشهر القمري : جمادى الآخرة","العام الميلادي :1302"],"text":"وفي هذا الشَّهرِ ثار جماعةٌ مِن الحَسَدةِ على الشيخِ تَقيِّ الدين بن تيمية وشَكَوا منه أنَّه يقيمُ الحُدودَ ويُعَزِّرُ ويَحلِقُ رؤوس الصبيان، وتكلَّمَ هو أيضًا فيمن يشكو منه ذلك، وبيَّنَ خَطأَهم، فسَكَنَت الأمورُ."},{"id":2847,"title":"اليهود بدمشق يزورون كتابا على رسول الله صلى الله عليه وسلم بوضع الجزية عنهم .","date":["العام الهجري :701","الشهر القمري : جمادى الآخرة","العام الميلادي :1302"],"text":"عُقِدَ مجلِسٌ لليهود الخيابرة وأُلزِموا بأداءِ الجزية أسوةَ أمثالهم من اليهود، فأَحضروا كتابًا معهم يزعُمونَ أنَّه من رسولِ الله صلى الله عليه وسلم بوضعِ الجِزيةِ عنهم، فلما وقف عليه الفُقَهاءُ تَبَيَّنوا أنَّه مكذوب مُفتَعَلٌ لما فيه من الألفاظِ الركيكة، والتواريخِ المحبطة، واللَّحنِ الفاحش، وحاقَقَهم عليه شيخُ الإسلام ابن تيميَّةَ، وبيَّنَ لهم خطأَهم وكَذِبَهم، وأنَّه مُزَوَّرٌ مكذوب، فأنابوا إلى أداءِ الجزية، وخافوا من أن تُستعادَ منهم الشؤون الماضية، وقال ابن كثير: \"وقد وقفتُ أنا على هذا الكتابِ فرأيتُ فيها شهادةَ سَعدِ بن معاذٍ عام خيبر، وقد توفِّيَ سعد قبل ذلك بنحوٍ مِن سنتين، وفيه: وكتَبَ عليُّ بن أبي طالب، وهذا لحنٌ لا يَصدُرُ عن أميرِ المؤمنين عليٍّ رضي الله عنه\"."},{"id":2848,"title":"تمرد أهل سيس ومحاربتهم .","date":["العام الهجري :701","الشهر القمري : ذي القعدة","العام الميلادي :1302"],"text":"ورد الخبَرُ من حلب بأن تكفور الأرمني متمَلِّكَ سيس منع الحَملَ وخرَجَ عن الطاعةِ وانتمى لغازان، فرسم بخروجِ العسكر لمحاربته، وخرج الأميرُ بدر الدين بكتاش الفخري أميرُ سلاح والأمير عز الدين أيبك الخازندار بمضافيهما من الأمراءِ والمفاردة في رمضانَ وساروا إلى حماة، فتوجَّهَ معهم العادل كتبغا في الخامِسَ عشر من شوال، وقَدِموا حلب في أوَّلِ ذي القَعدةِ ورحَلوا منها في ثالِثِه، ودخلوا دربند بغراس في سابعه، وانتَشَروا في بلاد سيس، فحَرَقوا المزروع وانتهبوا ما قدروا عليه، وحاصروا مدينةَ سيس وغَنِموا مِن سَفحِ قَلعتِها شيئًا كثيرًا من جفال الأرمن، وعادوا من الدربند إلى مرج أنطاكية، فقَدِموا حلب في السابع عشر، ثم نزلوا حماة في التاسع عشر."},{"id":2849,"title":"وفاة العلامة شيخ الإسلام تقي الدين بن دقيق العيد .","date":["العام الهجري :702","الشهر القمري : صفر","العام الميلادي :1302"],"text":"هو الإمامُ العلَّامةُ شَيخُ الإسلام تقيُّ الدين أبو الفتح محمد بن علي بن وهب بن مطيع القشيري المصري المنفلوطي، المالكيُّ الشافعي، أحَدُ الأعلام وقاضي القضاة, المعروفُ بابن دقيق العيد. وُلِدَ يوم السبت الخامس والعشرين من شعبان سنة 625 بساحل مدينة ينبع من أرض الحجاز، تفقَّهَ على والده بقوص, وكان والِدُه مالكيَّ المذهب، ثم تفقَّه على الشيخ عزِّ الدِّين بن عبد السلام الشافعي، فحقَّق المذهبَين، وأفتى فيهما، سَمِعَ الكثير ورحل في طلب الحديثِ وخرج وصَنَّفَ فيه إسنادًا ومتنًا مُصَنَّفات عديدة، فريدةً مفيدة، وانتهت إليه رياسةُ العلم في زمانه، وفاقَ أقرانه ورحل إليه الطَّلَبةُ ودرَّسَ في أماكن كثيرة، ولي قضاءَ الديار المصرية، وكان وقورًا قليل الكلام غزيرَ الفوائِدِ كثيرَ العُلومِ، فيه ديانةٌ ونزاهة، وله شعرٌ رائق، كما كان بارعًا في الفقه والأصول، له مصنَّفاتٌ عديدة، منها: الإلمام في أحاديث الأحكام، وله إحكام الأحكام شرح عمدة الأحكام، وله شرح الأربعين النووية، وغيرها، وله خُطَبٌ بليغة مشهورة، أنشأها لَمَّا كان خطيبًا بقوص. قال الذهبي في معجمه: \"هو قاضي القضاة بالدِّيارِ المصرية، وشيخُها وعالِمُها، الإمامُ العلَّامة، الحافِظُ القدوة الوَرِع، شيخُ العصر. كان علَّامةً في المذهبين، عارفًا بالحديثِ وفنونه، سارت بمصنَّفاته الرُّكبان. ولي القضاءَ ثمانيَ سنين\", وبسط السبكيُّ ترجمته في الطبقاتِ الكبرى قال: \"لم ندرِكْ أحدًا من مشايخنا يختَلِفُ في أنَّ ابنَ دقيق العيد هو العالمُ المبعوثُ على رأس السَّبعمائة\". وقال عنه ابنُ كثير في طبقاته: \"أحدُ عُلماء وقته، بل أجلُّهم وأكثَرُهم عِلمًا ودِينًا، وورَعًا وتقشُّفًا، ومداومةً على العلم في ليلِه ونهاره، مع كِبَرِ السِّنِّ والشُّغلِ بالحكم. وله التصانيف المشهورة والعلوم المذكورة. برع في علومٍ كثيرة لا سيما في علم الحديث، فاق فيه على أقرانِه وبرز على أهل زمانِه، رحلت إليه الطلبة من الآفاق، ووقع على عِلمِه ووَرَعِه وزُهدِه الاتِّفاق\". توفي يوم الجمعة حادي عشر شهر صفر، وصُلِّيَ عليه يوم الجمعة بسوق الخيل، وحضر جنازته نائب السلطنة والأمراء، ودفن بالقرافة الصغرى."},{"id":2850,"title":"فتح الناصر قلاوون جزيرة أرواد وطرد الصليبيين منها .","date":["العام الهجري :702","الشهر القمري : صفر","العام الميلادي :1302"],"text":"قَدِمَ البريد من طرابلس بأن الفرنجَ أنشؤوا جزيرةً تجاه طرابلس تُعرَفُ بجزيرة أرواد، وعَمَروها بالعدد والآلات وكثُرَ فيها جمعُهم، وصاروا يركَبونَ البحر ويأخذون المراكِبَ، فرسم للوزير بعمارةِ أربعة شواني حربية، فشرَعَ في ذلك، ثمَّ في صفر هذه السنة توجَّهَ كهرداش إلى جزيرة أرواد، وهى بقُرب طرطوس، وصبَّحَهم في غفلةٍ وأحاط بهم وقاتلَهم ساعةً، فنصره اللهُ عليهم وقَتَلَ منهم كثيرًا، وسألوا الأمانَ فأُخِذوا أسرى في يوم الجمعة ثامِنَ عشرى صفر، واستولى كهرداش على سائِرِ ما عندهم، وعاد إلى طرابلس وأخرجَ الخُمُسَ من الغنائم لتُحمَلَ إلى السلطان، وقَسَمَ ما بَقِيَ فكانت عِدَّةُ الأسرى مائتينِ وثمانينَ، فلَمَّا قَدِمَ البريد من طرابلس بذلك دُقَّت البشائِرُ بالقلعة، وكان فتحُها من تمام فتح السواحِلِ، وأراح اللهُ المسلمينَ مِن شَرِّ أهلِها."},{"id":2851,"title":"وقعة عرض بين التتار والمماليك .","date":["العام الهجري :702","الشهر القمري : رجب","العام الميلادي :1303"],"text":"وقعة عَرض- وهي من أعمال حلب بين الرصافة وتدمر- وذلك أنَّه التقى جماعةٌ من أمراء الإسلام فيهم استدمر وبهادر أخي وكجكن وغرلو العادلي، وكلٌّ منهم سيفٌ من سيوف الدين في ألفٍ وخمسمائة فارس، وكان التتارُ في سبعةِ آلاف فاقتتلوا وصبر المسلمون صبرًا جيدًا، فنصرهم الله وخذلَ التَّتَر، فقتلوا منهم خلقًا وأسروا آخرينَ، ووَلَّوا عند ذلك مُدبِرينَ، وغَنِمَ المسلمون منهم غنائِمَ، وعادوا سالمين لم يُفقَدْ منهم إلا القليلُ مِمَّن أكرمه الله بالشهادة، ووقعت البطاقةُ بذلك، ثم قَدِمَت الأسارى يوم الخميس نصفَ شعبان."},{"id":2852,"title":"وقعة شقحب بين التتار والمسلمين ومعهم شيخ الإسلام ابن تيمية .","date":["العام الهجري :702","الشهر القمري : رمضان","العام الميلادي :1303"],"text":"في ثامِنَ عشر رجب قَدِمَت طائفة كبيرة من جيش المصريِّين فيهم الأمير ركن الدين بيبرس الجاشنكير، والأميرُ حسام الدين لاجين المعروف بالاستادار المنصوري، والأميرُ سيف الدين كراي المنصوري، ثم قدمت بعدهم طائفةٌ أخرى فيهم بدر الدين أمير سلاح وأيبك الخزندار فقَوِيَت القلوبُ واطمأنَّ كثير من الناس، وكان الناسُ في حفل عظيم من بلاد حلب وحماة وحمص وتلك النواحي، وتقهقر الجيشُ الحلبي والحموي إلى حمص، ثم خافوا أن يدهَمَهم التتر فجاؤوا فنزلوا المرجَ يوم الأحد خامس شعبان، ووصل التتارُ إلى حمص وبعلبك وعاثوا في تلك الأراضي فسادًا، وقَلِقَ الناس قلقًا عَظيمًا، وخافوا خوفًا شديدًا، واختبطَ البَلَدُ لتأخُّرِ قدوم السلطان ببقيَّة الجيش، وقال النَّاسُ: لا طاقة لجيشِ الشام مع هؤلاء المصريين بلقاءِ التتار لكثرَتِهم، وإنما سبيلُهم أن يتأخَّروا عنهم مرحلةً مرحلة، وتحَدَّث الناسُ بالأراجيف فاجتمع الأمراءُ في يوم الأحد خامس شعبان بالميدان وتحالَفوا على لقاء العدو، وشَجَّعوا أنفُسَهم، ونودِيَ بالبلد أنْ لا يرحل أحدٌ منه، فسكن النَّاسُ وجلس القضاةُ بالجامِعِ وحَلَّفوا جماعة من الفقهاء والعامَّة على القتال، وتوجَّهَ الشيخ تقي الدين ابن تيميَّة إلى العسكَرِ الواصِلِ من حماة فاجتمع بهم في القطيعةِ فأعلَمَهم بما تحالف عليه الأمراءُ والنَّاسُ من لقاء العدو، فأجابوا إلى ذلك وحَلَفوا معهم، وكان الشيخ تقي الدين ابن تيمية يَحلِفُ للأمراءِ والنَّاسِ إنَّكم في هذه الكَرَّة منصورون، فيقولُ له الأمراء: قل إن شاء الله، فيقولُ: إن شاء الله تحقيقًا لا تعليقًا، وكان يتأوَّلُ في ذلك أشياءَ مِن كتاب اللهِ منها قَولُه تعالى: {ذَلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِ ثُمَّ بُغِيَ عَلَيْهِ لَيَنْصُرَنَّهُ اللَّهُ إِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ} [الحج: 60] ولَمَّا كان يوم الرابع والعشرين من شعبان خرجت العساكِرُ الشاميَّة فخَيَّمَت على الجسورة من ناحية الكسوة، ومعهم القضاةُ، فصار الناسُ فيهم فريقين: فريقٌ يقولونَ إنَّما ساروا ليختاروا موضِعًا للقتالِ؛ فإنَّ المرج فيه مياهٌ كثيرة فلا يستطيعون معها القتال، وقال فريق: إنما ساروا لتلك الجهة لِيَهرَبوا وليلحقوا بالسلطان، فلما كانت ليلةُ الخميس ساروا إلى ناحية الكسوة فقَوِيَت ظنون الناسُ في هَرَبِهم، وقد وصلت التتارُ إلى قارة، وبلغ الأمراءَ قُدومُ السلطانِ فتَوَجَّهوا إليه من مَرجِ راهط، فلَقُوه على عقبة الشحورا في يومِ السبت ثانيَ عَشَر رمضان، ثمَّ وَرَدَ عند لقائِهم به الخبَرُ بوصول التتار في خمسينَ ألفًا مع قطلوشاه نائب غازان، فلبس العسكَرُ بأجمعه السلاح، واتَّفَقوا على قتال التتار بشقحب تحت جبل غباغب (وهي من الطرف الشمالي لمرج الصفر)، فلما تمَّ الترتيبُ زَحَفت كراديس التتار كقِطَع الليل، وكان ذلك وقتَ الظهر من يوم السبتِ ثاني رمضان, وأقبل قطلوشاه بمن معه من الطوامين، وحملوا على الميمنة فثَبَتَت لهم الميمنة وقاتلوهم أشدَّ قِتالٍ، ثم قُتِلَ مِن الميمنة الكثيرُ فأدركَتْهم الأمراءُ مِن القَلبِ ومِن المَيسَرة واستمَرُّوا في القتال إلى أن كَشَفوا التتارَ عن المسلمينَ واستمَرَّ القتالُ بين التتار والمسلمينَ إلى أن وقفَ كل من الطائفتينِ عن القتال، ومال قطلوشاه بمن معه إلى جبَلٍ قريب منه، وصَعِدَ عليه وفي نفسه أنَّه انتصر، وأن بولاي في أثر المنهزمينَ مِن المسلمين، فلمَّا صَعِدَ الجبَلَ رأى السَّهلَ والوَعرَ كُلَّه عساكِرَ، والميسرةَ السُّلطانيةَ ثابتةً وأعلامها تخفُق، فبُهِتَ قطلوشاه وتحيَّرَ واستمَرَّ بمَوضِعِه حتى كَمُلَ معه جمعُه وأتاه مَن كان خلف المنهزمينَ مِن الميمنةِ السُّلطانيَّة ومعهم عِدَّةٌ من المسلمينَ قد أسروهم، فعند ذلك جمَعَ قطلوشاه أصحابَه وشاوَرَهم فيما يفعَلُ، وإذا بكوسات- قطعتان من نحاس تشبهان الترسَ الصغير يدقُّ بأحدها على الآخِرِ بإيقاعٍ مخصوص- السُّلطانِ والبوقات قد زَحَفَت وأزعجت الأرضَ وأرجفت القلوبَ بحِسِّها، فلم يثبت بولاي وخرج من تجاهِ قطلوشاه في نحوِ العشرين ألفًا من التتار، ونزل مِن الجَبَل بعد المغرب ومَرَّ هاربًا، وبات السلطانُ وسائِرُ عساكره على ظهور الخيل والطبولُ تُضرَبُ، وتلاحقَ بهم من كان انهَزَمَ شيئًا بعد شيءٍ، وهم يَقصِدونَ ضَربَ الطبول السلطانيَّة والكوسات؛ وأحاط عسكَرُ السُّلطانِ بالجبَلِ الذي بات عليه التتارُ وشرع قطلوشاه في ترتيبِ مَن معه، ونزلوا مشاةً وفرسانًا وقاتلوا العساكِرَ، فبرزت المماليكُ السلطانية بمقَدَّميها إلى قطلوشاه وجوبان، وعمِلوا في قتالهم عملًا عظيمًا، فصاروا تارةً يرمونهم بالسِّهامِ وتارة يواجهونَهم بالرماح، واشتغل الأمراء أيضًا بقتال من في جهتِهم، وصاروا يتناوبون في القتال أميرًا بعد أمير، وألحَّت المماليك السلطانيَّةُ في القتال وأظهروا في ذلك اليوم من الشجاعةِ والفروسية ما لا يوصَفُ، حتى إن بعضَهم قُتِلَ تحته الثلاثةُ من الخيل، وما زال الأمراءُ على ذلك حتى انتصف نهارُ الأحد، صعد قطلوشاه الجبل وقد قُتِلَ من عسكره نحو ثمانين رجلًا، وجُرح الكثير واشتَدَّ عَطَشُهم، واتفق أنَّ بعضَ من كان أسَرَه التتار هرب ونزل إلى السلطان، وعَرَّفه أنَّ التتارَ قد أجمعوا على النزولِ في السَّحَرِ لمصادمة العساكرِ السُّلطانية، وأنَّهم في شدة من العَطَشِ، فاقتضى الرأيُ أن يُفرِجَ لهم عند نزولِهم ويركَبَ الجيشُ أقفيتَهم، فلما باتوا على ذلك وأصبحوا نهارَ الاثنين، ركب التتارُ في الرابعة من النَّهارِ ونزلوا من الجبل فلم يتعَرَّض لهم أحدٌ وساروا إلى النهر فاقتَحَموه، فعند ذلك رَكِبَهم بلاءُ الله من المسلمين وأيَّدَهم الله تعالى بنَصرِه حتى حَصَدوا رؤوسَ التتار عن أبدانِهم ووضعوا فيهم السَّيفَ ومَرُّوا في أثرهم قتلًا وأسرًا إلى وقت العصر، وعادوا إلى السُّلطانِ وعَرَّفوه بهذا النصر العظيم، واستمَرَّت الأمراء وبَقِيت العساكرُ في طلب التتار إلى القريتينِ، وقد كَلَّت خيولُ التتار وضَعُفَت نفوسُهم وألقَوا أسلحَتَهم واستسلموا للقَتلِ، والعساكِرُ تقتلُهم بغير مدافعةٍ، حتى إن أراذِلَ العامَّة والغِلمان قتلوا منهم خلقًا كثيرًا وغَنِموا عندئذ غنائِمَ، وقتل الواحِدُ من العسكر العشرينَ من التتار فما فوقها، ثم أدركت عُربانُ البلاد التتارَ وأخذوا في كيدهم، فيجيء منهم الاثنانُ والثلاثة إلى العِدَّة الكثيرة من التتار، كأنهم يهدونَهم إلى طريقٍ قريبةٍ مفازة، فيوصلونهم إلى البَرِّيَّة ويتركونهم بها فيموتون عطشًا، ومنهم من دار بهم وأوصلوهم إلى غوطة دمشق، فخرجت إليهم عامَّةُ دِمشقَ فقَتَلوا منهم خلقًا كثيرًا، وفي يوم الاثنين رابع الشهر رجع الناس من الكسوة إلى دمشق فبَشَّروا النَّاسَ بالنصرِ."},{"id":2853,"title":"وفاة الأمير زين الدين كتبغا المنصوري .","date":["العام الهجري :702","الشهر القمري : ذي الحجة","العام الميلادي :1303"],"text":"هو الأميرُ زين الدين كتبغا المنصوري، نائِبُ السَّلطنة بحماة، كان من مماليكِ السلطان المَلِك المنصور سيف الدينِ قلاوون الصالحي, وأصلُه من أسرى التَّتار اشتراه السلطانُ قلاوون ثمَّ ترقَّى حتى تسلطنَ، وتلقَّب بالمَلِك العادل، وملَك ديارَ مِصرَ والشام في سنة 694، ثم خلَعَه نائبُه لاجين، وأعطاه صرخد في سنة ستٍّ وتسعين، واستمَرَّ مُقيمًا بصرخد إلى أن اندفَعَ المسلمون من التَّتَر على حمص، فوصل كتبغا من صرخد إلى مصر، وخرج مع سلار والجاشنكير إلى الشام، فقَرَّره نائبًا بحماة، في سنة تسع وتسعين وستمائة، ثم أغار على بلاد سيس، فلمَّا عاد إلى حماة مَرِضَ قبل دخوله إلى حماة، وطال مرَضُه، ثمَّ حَصَل له استرخاءٌ، وبقي لا يستطيعُ أن يحَرِّكَ يديه ولا رِجلَيه، وبَقِيَ كذلك مُدَّةً، وسار من حماة إلى قريبِ مِصر جافلًا بين يدَي التتر، لما كان المصاف على مرج الصفر، ثم عاد إلى حماة وأقام بها مدةً يسيرة، وتوفِّيَ في هذه السنة."},{"id":2854,"title":"غزو سيس وتل حمدون .","date":["العام الهجري :703","الشهر القمري : رمضان","العام الميلادي :1304"],"text":"سارت العساكِرُ من القاهرة للغارة على الأرمن في بلاد سيس، وعليهم الأميرُ بدر الدين بكتاش أمير سلاح، ومعه الأميرُ علم الدين سنجر الصوابي والأميرُ شمس الدين سنقر شاه المنصوري ومضافيهم، وكتب إلى طرابلس وحماة وصفد وحلب بخروج العساكِرِ إليها، فوصل الأميرُ بدر الدين بكتاش إلى دمشقَ في ثاني عشر رمضان، وخرج منها بعسكرِ دمشق، فسار إلى حَلَب وأتته عساكِرُ البلاد، فافتَرَقوا فرقتينِ فِرقةً سارت صحبة قبجق إلى ناحية ملطية، وقلعة الروم، والفِرقة الأخرى صحبة قراسنقر حتى دخلوا الدربنداتِ وحاصروا تلَّ حمدون فتسَلَّموه عَنوةً في ثالث ذي القعدة بعد حصارٍ طويل، وحرقوا مزارعَ سيس وخَرَّبوا الضياعَ وأسَروا أهلَها، ونازلوا تلَّ حمدون وقد امتنع بقلعَتِها جماعةٌ كثيرة من الأرمن، فقاتلوهم حتى فُتِحَت بالأمان، وأخذوا منها ستةَ ملوك من ملوك الأرمن، فشَقَّ ذلك على تكفور ملك سيس، وقصد نكايةَ الملوك على تسليمِهم قلعة تل حمدون بالأمان، وكتب إلى نائِبِ حلب بأنَّ ملوك القلاع هم الذين كانوا يمنعون مِن حَملِ الخراج، فلا تُفرِجوا عن أحدٍ منهم، فليس عندي من يَزِنُ المال سواهم، فأمر النائِبُ بقَتلِهم، فضُرِبَت رقابُ ملوك خمسة منهم، وسَلِمَ منهم صاحب قلعة نجيمة والتزم بأخذ سيس ووقع مع صاحِبِ سيس على أن يكون للمسلمينَ مِن نهر جيهان إلى حَلَب وبلاد ما وراء النهر إلى ناحيتهم لهم، وأن يعَجِّلوا حملَ سَنَتين، ووقعت الهدنةُ على ذلك، فحمل إلى مصر وكتب صحبته بعودِ العساكر بالغنائم، فسُرَّ الأمراءُ والسلطان بذلك، وأكرم صاحب قلعة نجيمة، وكتب بعَودِ العساكر."},{"id":2855,"title":"وفاة قازان محمود بن أرغون بن أبغا ملك التتار وتولي أخيه خدابندا .","date":["العام الهجري :703","الشهر القمري : شوال","العام الميلادي :1304"],"text":"هو المَلِكُ محمود غازان ويقال (قازان) بن القان أرغون بن أبغا بن هولاكو بن تولي بن جنكزخان المغولي ملك التتار العراقين وخراسان وفارس وأذربيجان والروم؛ ولد سنة 670. كان شابًّا عاقلًا شجاعًا مهيبًا مليحَ الشكلِ، وكان جلوسه على تخت الملك سنة 693. ذكر الذهبي إسلامَه فقال: \"دخل قازان الإسلامَ بوساطة نوروز التركي وزيرِه ونائِبِه ومدبِّر مملكته وزَوجِ عَمَّتِه. أسلم في شعبان سنة694 بخراسان على يد الشيخ الكبير المحدث صدر الدين إبراهيم بن الشيخ سعد الدين بن حمويه الجويني. وذلك بقُربِ الري بعد خروجه من الحمام، وجلس مجلسًا عامًّا فتلَفَّظ بشهادة الحق وهو يبتَسِمُ ووجهه يستنير ويتهَلَّل, وكان شابًّا أشقر مليحا، له إذ ذاك بضعٌ وعشرون سنة. وضج المسلمون حوله عندما أسلم ضجَّةً عَظيمةً مِن المغول والعجم وغيرهم، ونثر على الخلق الذهب واللؤلؤ. وكان يومًا مشهودًا. وفشا الإسلامُ في جيشه بحصر نوروز؛ فإنَّه كان مسلمًا خَيِّرًا صحيح الإسلام، يحفظُ كثيرًا من القرآن والرقائق والأذكار, ثم شرع نوروز يلقِّن الملك غازان شيئًا من القرآن ويجتهد عليه. ودخل رمضان فصامه، ولولا هذا القَدرُ الذي حصل له من الإسلام وإلَّا كان قد استباح الشامَ لَمَّا غلب عليه، فلله الحمد والمنَّة\" كان لقازان خبرةٌ بسياسة الأمور وتدبير الملك، وكان قد التحق في أفعالِه بجَدِّه الأكبر هولاكو، لكِنْ كانت هيبته قويَّةً ورعيتُه في زمانه آمنةً، أظهر غازان العدل، وتسمى بمحمود، ومَلَك العراقين وخراسان وفارس والجزيرة والروم، وتسمَّى بالقان، وأفرد نفسَه بالذِّكرِ في الخطبة، وضرب السكَّة، ولم يسبِقْه أحد من آبائه إلى هذا، فاقتدى به من جاء بعده، وكان من أجَلِّ ملوك بيت هولاكو، إلَّا أنه كان يبخَلُ بالنسبة إليهم, وطرد نائِبَه نوروز من بلادِه ثمَّ أمر بقَتلِه. مات بقرب همذان، ولم يتكَهَّل، ونقل إلى تبريز، ودفن بتربته، ويقال إنه مات مسمومًا، واشتهر أنَّه سُمَّ في منديل تمسَّحَ به بعد الجِماعِ، فتعلَّ ومات, ثم قام في المُلكِ بعده أخوه خدبندا محمد بن أرغون، وخُطِبَ له على منابر العراق وخراسان وتلك البلاد، وتلقَّب بغياث الدين محمد، وكتب إلى السلطان بجلوسِه، وطلبه للصُّلحِ وإخماد الفتنة، وسَيَّرَ إليه رسله."},{"id":2856,"title":"نزوح كثير من عائلات التتار المسلمة إلى مصر .","date":["العام الهجري :704","الشهر القمري : جمادى الأولى","العام الميلادي :1304"],"text":"حضر جماعةٌ من المغول وافدينَ إلى بلاد الإسلام بعد إسلامِهم، نحو مائتي فارس بنسائِهم وأولادهم، وفيهم عِدَّةٌ من أقارب غازان وبعض أولاد سنقر الأشقر، الذي كتب يحُثُّ على إكرامهم، فقَدِموا إلى القاهرة في جمادى الأولى وقَدِمَ معهم أخوا سلار، وهما فخر الدين داود، وسيف الدين جبا، وقَدِمَت أيضًا أم سلار، فرُتِّبَت لهم الرواتب، وأُعطوا الإقطاعات، وفُرِّق جماعةٌ منهم على الأمراء، وأنشأ سلار لأمِّه دارًا بإسطبل الجوق الذي عَمِلَه العادل كتبغا ميدانًا، ثم عرف بحكر الخازن، ورقَّى أخويه وأعطاهما الإمريات، وقدم الأمير حسام الدين أزدمر المجيري، وعماد الدين على بن عبد العزيز بن عبد الرحمن بن عبد العلي بن معرف بن السكري، من بلاد الشرق إلى دمشقَ في الرابع عشر من شعبان، ودخلا القاهرةَ أول رمضان، ومعهما كتابُ خربندا وهديته، فتضَمَّن كتابُه جلوسَه على تخت الملك بعد أخيه محمود غازان، وخاطب السلطانَ بالأخوة، وسأل إخماد الفتن، وطلب الصلحَ، وقال في آخر كلامه: {عَفَا اللَّهُ عَمَّا سَلَفَ وَمَنْ عَادَ فَيَنْتَقِمُ اللَّهُ مِنْهُ}، فأُجيبَ وجُهِّزَت له الهَديَّةُ، وأُكرِمَ رَسولُه."},{"id":2857,"title":"شيخ الإسلام ابن تيمية يهدم الصخرة المزعوم أن فيها أثر النبي صلى الله عليه وسلم .","date":["العام الهجري :704","الشهر القمري : رجب","العام الميلادي :1305"],"text":"سار الشيخُ تقي الدين ابن تيمية إلى مسجدِ النارنج وأمر أصحابَه ومعهم حجَّارونَ بقَطعِ صَخرةٍ كانت هناك بنهر قلوط تزارُ ويُنذَرُ لها، ويقولون إن الأثَرَ الذي بها هو قَدَمُ النبيِّ صلَّى الله عليه وسلم، فبَيَّنَ أن ما يفعَلُه الناس من التبرك به وتقبيلِه لا يجوز، فقَطَع الصخرةَ في سادس عشر رجب، وقد أنكر عليه الناسُ ما فعله فأُجيبَ إن كان الأمرُ على ما زعم فقد فعل الخيرَ وأزال بدعة، وإن كان الأمرُ بخلاف ما قال فإذا تبيَّنَ صِحَّتُه يقابَلُ على ما فَعَله، فقطعها وأراح المسلمينَ منها ومن الشِّركِ بها، فأزاح عن المسلمينَ شُبهةً كان شَرُّها عظيمًا، وبهذا وأمثالِه حَسَده بعضُ العلماءِ وأبرزوا له العداوة، وكذلك كلامُه في ابن عربي وأتباعِه، فحُسِدَ على ذلك وعُودِي، ومع هذا لم تأخُذْه في اللهِ لومة لائمٍ، ولا بالى، ولم يَصِلوا إليه بمكروهٍ، وأكثَرُ ما نالوا منه الحبسُ، مع أنه لم ينقَطِعْ في بحثٍ لا بمصرَ ولا بالشامِ!"},{"id":2858,"title":"مسير شيخ الإسلام ابن تيمية مرة ثانية إلى كسروان الدروز والروافض .","date":["العام الهجري :704","الشهر القمري : ذي الحجة","العام الميلادي :1305"],"text":"في مستهَلِّ ذي الحجَّة ركبَ الشيخ تقي الدين ابن تيمية ومعه جماعةٌ من أصحابه إلى جبل الجرد والكسروانيين ومعه نقيبُ الأشراف زين الدين بن عدنان، فاستتابوا خلقًا من الرافضة والدروز وألزَموهم بشرائِعِ الإسلامِ، ورجع مُؤيَّدًا منصورًا."},{"id":2859,"title":"مدينة سبتة بين بني مرين وبين بني الأحمر .","date":["العام الهجري :705","العام الميلادي :1305"],"text":"استولى السلطانُ محمد الثالث الملَقَّب بالمخلوع بن محمد الثاني الملقَّب بالفقيه على مدينة سبتة، ولكنَّ السلطانَ محمد بن الأحمر توجَّه بأسطول فاسترَدَّ سبتة من بني مرين."},{"id":2860,"title":"محاربة الأرمن أهل سيس .","date":["العام الهجري :705","الشهر القمري : محرم","العام الميلادي :1305"],"text":"أخَّر متمَلِّكُ سيس الحملَ الجاريَ به العادة، فبعث إليه نائِبُ حلب أستاداره قشتمر الشمسي أحدَ مقدَّمي حلب على عسكرٍ نحو الألفين، وفيهم الأميرُ شمس الدين أقسنقر الفارسي والأميرُ فتح الدين صبرة المهمندار- الذي يتلقَّى الرسُلَ والمبعوثين- والأمير قشتمر النجيبي، وقشتمر المظفري، فشنوا الغاراتِ على بلاد سيس، ونهبوا وحَرَّقوا كثيرًا من الضياع، وسَبَوا النساءَ والأطفال في المحَرَّم، وكان قد وصل إلى سيس طائفةٌ من التتار في طلب المال، فركِبَ التتار مع صاحِبِ سيس، وملَكوا رأس الدربند، فركب العسكرُ لقتالهم وقد انحصروا، فرمى التتارُ عليهم بالنشاب والأرمن بالحجارة، فقُتِلَ جماعةٌ وأُسِرَ من الأمراءِ ابن صبرة، وقشتمر النجيبي، وقشتمر المظفري، في آخرينَ مِن أهل حلب، وخَلُصَ قشتمر مُقَدَّم العسكر، وآقسنقر الفارسي، وتوجَّه التتار بالأسرى إلى خربندا بالأردن، فرسم عليهم, وبلَغَ نائبَ حلب خبَرُ الكسرة، فكتب بذلك إلى السلطانِ الناصر والأمراء، فرسم بخروجِ الأمير بكتاش أمير سلاح، وبيبرس الدوادار وأقوش الموصلي فتال السبع، والدكن السلاح دار، فساروا من القاهرة في نصف شعبان على أربعة آلاف فارس، فبعث متمَلِّك سيس الحمل، واعتذر بأنَّ القتالَ لم يكن منه وإنما كان من التتر، ووعده بالتحَيُّل في إحضار الأمراء المأسورين، فرجع الأميرُ بكتاش بمن معه من غَزَّة."},{"id":2861,"title":"محاربة أهل الكسروان والجرد .","date":["العام الهجري :705","الشهر القمري : صفر","العام الميلادي :1305"],"text":"خرج نائِبُ السلطنة بمن بقي من الجيوشِ الشاميَّة، وقد كان تقَدَّمَ بين يديه طائفةٌ من الجيش مع ابن تيميَّة في ثاني المحرم، فساروا إلى بلاد الجرد والرَّفضِ والتيامنة والدروز فخرج نائبُ السلطنة الأفرم بنفسه بعد خروجِ الشيخ لغزوهم، فنصَرَهم الله عليهم وأبادوا خلقًا كثيرًا منهم ومِن فِرقَتِهم الضالَّة، ووَطِئوا أراضيَ كثيرةً مِن صُنعِ بلادهم، وعاد نائِبُ السلطنة إلى دمشقَ في صحبته الشَّيخُ ابن تيمية والجيش، وقد حصل بسبَبِ شهود الشيخ هذه الغزوةَ خَيرٌ كثيرٌ، وأبان الشيخ علمًا وشجاعةً في هذه الغزوة، وقد امتلأت قلوبُ أعدائه حسدًا له وغَمًّا."},{"id":2862,"title":"مناظرة شيخ الإسلام ابن تيمية للصوفية .","date":["العام الهجري :705","الشهر القمري : جمادى الأولى","العام الميلادي :1305"],"text":"حضر جماعةٌ كثيرة من الفقراء الأحمدية في يوم السبت تاسع جمادى الأولى إلى نائب السَّلطنةِ بالقصر الأبلق وحضر الشيخُ تقي الدين ابن تيمية فسألوا من نائب السلطنةِ بحَضرةِ الأمراء أن يكُفَّ الشيخ تقي الدين إمارتَه عنهم، وأن يسَلِّمَ لهم حالهم، فقال لهم الشيخ: هذا ما يمكِنُ، ولا بُدَّ لكل أحد أن يدخُلَ تحت الكتاب والسنة، قولًا وفعلًا، ومن خرج عنهما وجب الإنكارُ عليه، فأرادوا أن يفعلوا شيئًا من أحوالِهم الشيطانيَّة التي يتعاطَونَها في سماعاتهم، فقال الشيخ: تلك أحوالٌ شيطانيَّةٌ باطلة، وأكثَرُ أحوالهم من باب الحِيَل والبهتان، ومن أراد منهم أن يدخُلَ النارَ فليدخُلْ أوَّلًا إلى الحَمَّامِ وليغسل جسَدَه غَسلًا جَيِّدًا ويَدلكَه بالخَلِّ والأُشنان ثم يدخُل بعد ذلك إلى النَّارِ إن كان صادقًا، ولو فرض أن أحدًا من أهل البِدَعِ دخل النار بعد أن يغتَسِلَ فإن ذلك لا يدُلُّ على صلاحِه ولا على كرامتِه، بل حالُه من أحوال الدَّجاجِلة المخالِفة للشريعة إذا كان صاحِبُها على السُّنَّة، فما الظنُّ بخلاف ذلك؟! فابتدر شيخُ المنيبع الشيخُ الصالح وقال: نحن أحوالُنا إنما تَنفُق عند التتر ليست تَنفُق عند الشرع، فضبط الحاضرونَ عليه تلك الكلمة، وكثُرَ الإنكار عليهم من كل أحدٍ، ثم اتفق الحالُ على أنهم يخلعون الأطواقَ الحديدَ مِن رقابهم، وأنَّ من خرج عن الكتابِ والسنة ضُرِبَت عنقه، وصنَّف الشيخُ جزءًا في طريقة الأحمدية، وبيَّنَ فيه أحوالهم ومسالِكَهم وتخيُّلاتِهم، وما في طريقتِهم من مقبولٍ ومَردودٍ بالكتاب، وأظهر اللهُ السنة على يديه وأخمد بدعتَهم، ولله الحمدُ والمِنَّة."},{"id":2863,"title":"محنة شيخ الإسلام ابن تيمية وحبسه في القاهرة بسبب الاعتقاد .","date":["العام الهجري :705","الشهر القمري : رجب","العام الميلادي :1306"],"text":"حضر القضاةُ والعُلَماءُ وفيهم الشيخُ تقيُّ الدين ابن تيمية في يوم الاثنين ثامِنَ رجب عند نائب السلطنةِ بالقَصرِ، وقُرئت عقيدةُ الشيخ تقي الدين ابن تيمية الواسطيَّة، وحصل بحثٌ في أماكِنَ منها، وأُخِّرَت مواضِعُ إلى المجلس الثاني، فاجتمعوا يومَ الجمعة بعد الصلاة في الثاني عشر من هذا الشهر, وحضر الشيخُ صفي الدين الهندي، وتكلَّمَ مع الشيخِ تقيِّ الدين كلامًا كثيرًا، ولكِنَّ ساقِيَتَه لاطمت بحرًا، ثم اصطلحوا على أن يكون الشيخُ كمال الدين بن الزملكاني هو الذي يحاقِقُه من غيرِ مُسامحة، فتناظرا في ذلك، وشكر النَّاسُ من فضائل الشيخِ كمال الدين بن الزملكاني وجَودةِ ذِهنِه وحُسنِ بحثِه حيث قاومَ ابن تيميَّة في البحث، وتكَلَّم معه، ثم انفصل الحالُ على قبول العقيدة، وعاد الشيخُ إلى منزله مُعَظَّمًا مُكَرَّمًا، وكان الحامِلُ على هذه الاجتماعات كتابًا ورد من السلطان في ذلك، كان الباعِثُ على إرسالِه قاضي المالكيَّة ابن مخلوف، والشَّيخ نصر المنبجي شيخ الجاشنكير وغيرهما من أعدائه، وذلك أنَّ الشيخ تقي الدين ابن تيمية كان يتكَلَّم في المنبجي وينسِبُه إلى اعتقادِ ابن عربي، وكان للشيخِ تقي الدين من الفُقَهاءِ جماعة يحسُدونَه لتقَدُّمِه عند الدولة، وانفرادِه بالأمر بالمعروف والنهيِ عن المنكر، وطاعةِ الناس له ومحبَّتِهم له، وكثرةِ أتباعِه، وقيامه في الحق، وعِلمِه وعَمَلِه، ثم وقع بدمشقَ خَبطٌ كثير وتشويشٌ بسبب غيبةِ نائب السلطنة، وطَلَب القاضي جماعةً من أصحاب الشيخ وعَزَّرَ بَعضَهم ثمَّ اتفق أن الشيخ جمال الدين المِزِّي الحافظ قرأ فصلًا بالردِّ على الجهميَّة من كتابِ أفعال العباد للبخاريِّ تحت قبة النسر بعد قراءة ميعاد البخاري بسبب الاستسقاء، فغضب بعضُ الفقهاء الحاضرين وشكاه إلى القاضي الشافعي ابن صصرى، وكان عدوًّا للشيخ تقي الدين ابن تيمية, فسَجَن المزِّي، فبلغ الشيخَ تقي الدين فتألَّم لذلك وذهب إلى السجنِ فأخرجه منه بنَفسِه، وراح إلى القصرِ فوجد القاضيَ ابن صصرى هنالك، فتقاولا بسبب الشيخِ جمالِ الدين المزِّي، فحلف ابن صصرى لا بد أن يعيدَه إلى السجن وإلَّا عزل نفسَه فأمر النائِبُ بإعادتِه تطييبًا لقلب القاضي فحَبَسه عنده في القوصيَّة أيامًا ثم أطلقه، ولما قدم نائبُ السلطنة ذكر له الشيخُ تقي الدين ابن تيمية ما جرى في حقِّه وحَقِّ أصحابه في غيبته، فتألم النائِبُ لذلك ونادى في البلدِ ألَّا يتكلم أحدٌ في العقائِدِ، ومن عاد إلى تلك حَلَّ مالُه ودَمُه ورُتِّبَت داره وحانوته، فسكنت الأمور، ثم عُقِدَ المجلس الثالث في يوم سابع شعبان بالقصرِ واجتمع جماعةٌ على الرضا بالعقيدة الواسطية, وفي هذا اليوم عزلَ ابنُ صصرى نفسَه عن الحكم بسبب كلامٍ سمعه من بعض الحاضرينَ في المجلس، وهو من الشيخِ كمال الدين بن الزملكاني، ثم جاء كتابُ السلطان في السادس والعشرين من شعبان فيه إعادةُ ابن صصرى إلى القضاء، وذلك بإشارةِ المنبجي، وفي الكتابِ: إنا كنا سمعنا بعقدِ مَجلِسٍ للشيخ تقي الدين ابن تيمية، وقد بلَغَنا ما عُقِدَ له من المجالس، وأنه على مذهب السَّلَفِ، وإنما أردنا بذلك براءةَ ساحتِه مِمَّا نسب إليه، ثم جاء كتابٌ آخر في خامس رمضان يوم الاثنين وفيه الكشفُ عن ما كان وقع للشيخِ تقي الدين ابن تيمية في أيَّام جاغان، والقاضي إمام الدين القزويني، وأن يُحمَلَ هو والقاضي ابن صصرى إلى مصر، فتوجَّها على البريد نحو مصر، وخرج مع الشيخِ خَلقٌ من أصحابه وبَكَوا وخافوا عليه من أعدائه، وأشار عليه نائبُ السلطنة ابن الأفرم بترك الذَّهابِ إلى مصر، وقال له: أنا أكاتِبُ السلطان في ذلك وأصلِحُ القضايا، فامتنع الشيخُ من ذلك، وذكَرَ له أن في توجُّهِه لمصر مصلحةً كبيرة، ومصالحَ كثيرة، فلما كان يومُ السبت دخل الشيخُ تقيُّ الدين غزَّةَ فعَمِلَ في جامعها مجلسًا عظيمًا، ثم دخلا معا إلى القاهرة والقلوبُ معه وبه متعلِّقة، فدخلا مصر يوم الاثنين الثاني والعشرين من رمضان، وقيل إنَّهما دخلاها يوم الخميس، فلما كان يومُ الجمعة بعد الصلاة عقد للشيخ مجلس بالقلعة اجتمع فيه القضاةُ وأكابر الدولة وأراد أن يتكَلَّم على عادته فلم يتمكَّن من البحث والكلامِ، وانتدب له الشَّمسُ ابن عدنان خصمًا احتسابًا، وادَّعى عليه عند ابن مخلوف المالكي أنَّه يقول: إنَّ الله فوق العَرشِ حَقيقةٌ، وأنَّ الله يتكَلَّمُ بحَرفٍ وصَوتٍ، فسأله القاضي جوابَه فأخذ الشيخُ في حمد اللهِ والثناء عليه، فقيل له: أجِبْ، ما جئنا بك لتخطب! فقال: ومن الحاكِمُ فيَّ؟! فقيل له: القاضي المالكي، فقال له الشَّيخُ: كيف تحكمُ فيَّ وأنت خصمي، فغضب غضبًا شديدًا وانزعج وأقيمَ مَرسمٌ عليه وحُبِسَ في برج أيامًا، ثم نقِلَ منه ليلة العيد إلى الحبس المعروفِ بالجُبِّ، هو وأخوه شرف الدين عبد الله، وزين الدين عبد الرحمن، وأما ابن صصرى فإنه جُدِّدَ له توقيعٌ بالقضاء بإشارة المنبجي شيخ الجاشنكير حاكم مصر، وعاد إلى دمشقَ يوم الجمعة سادس ذي القعدة والقلوبُ له ماقتة، والنفوسُ منه نافرة، وقرئ تقليدُه بالجامع، وبعده قرئ كتابٌ فيه الحطُّ على الشيخ تقي الدين ابن تيميَّة ومخالفته في العقيدة، وأن ينادى بذلك في البلاد الشاميَّة، وألزِمَ أهلُ مذهبه بمخالفتِه، وكذلك وقع بمصر، قام عليه جاشنكير وشيخُه نصر المنبجي، وساعدهم جماعةٌ كثيرةٌ من الفقهاء والصوفيَّة وجرت فِتَنٌ كثيرة منتشرة، نعوذُ بالله من الفتن، وحصل للحنابلةِ بالديار المصرية إهانةٌ عظيمة كثيرة، وذلك أنَّ قاضِيَهم كان قليلَ العِلمِ مُزجَى البضاعةِ، وهو شرف الدين الحراني، فلذلك نال أصحابُهم ما نالهم، وصارت حالُهم حالًا مؤلمة."},{"id":2864,"title":"قدوم وفد من الصوفية من التتار إلى دمشق .","date":["العام الهجري :706","الشهر القمري : جمادى الأولى","العام الميلادي :1306"],"text":"وَفَدَ لدمشق رجلٌ من بلاد التتار يقال له الشيخُ براق الرومي- كان في الأصل مريدًا لبعض الشيوخِ في البلاد الروميَّة- في تاسع جمادى الأولى، ومعه جماعةٌ من الفقراء نحو المائة لهم هيئةٌ عجيبةٌ، وعلى رؤوسِهم كلاوت لباد مقصَّصة بعمائِمَ فوقها، وفيها قرونٌ من لباد شبه قرون الجاموس فيها أجراسٌ، ولِحاهم مُحَلَّقة دون شواربهم خلافًا للسنَّة، ولُبسُهم لبابيدُ بيضاء، وقد تَقَلَّدوا بحبالٍ منظومة بكعاب البقر، وكلٌّ منهم مكسور الثنية العُليا، وشيخُهم من أبناء الأربعين سنة، وفيه إقدامٌ وجرأة وقوَّةُ نفس وله صولة، ومعه طبلخاناه- فرقة الطبول والأبواق- تدق له نوبة، وله محتَسِبٌ على جماعته يؤدِّبُ كُلَّ من ترك شيئًا من سُنَّتِه بضرب عشرينَ عصًا تحت رجلَيه، وهو ومن معه ملازِمونَ التعبُّدَ والصلاة، وأنه قيل له عن زِيِّه، فقال: أردتُ أن أكونَ مَسخرةَ الفُقراءِ، وذكر أن غازان لما بلغه خَبَرُه استدعاه وألقى عليه سَبُعًا ضاريًا، فزجره فهرب منه السَّبُع، فجَلَّ في عين غازان ونثر عليه عشرة آلاف دينار، وطلب دخولَ مصرَ لكِنَّه مُنِعَ من ذلك، فسار إلى القدسِ، ثم رجع إلى بلاده لأنَّه لم يلقَ قَبولًا في دمشق، وبراق هذا أصلُه من الروم."},{"id":2865,"title":"وفاة أبي يعقوب يوسف المريني ملك المغرب .","date":["العام الهجري :706","الشهر القمري : ذي القعدة","العام الميلادي :1307"],"text":"هو السُّلطانُ أبو يعقوب يوسُفُ بن يعقوب بن عبد الحَقِّ بن محيو بن أبي بكر بن حمامة ملك المغرب. وثب عليه سعادةُ الخَصِيُّ أحدُ مواليه في بعضِ حُجَرِه، وقد خَضَّب رجلَيه بالحنَّاء وهو مُستلقٍ على قَفاه، فطعنه طعناتٍ قطَعَ بها أمعاءه، وخرج فأُدرِكَ وقُتِلَ، فمات السلطانُ آخِرَ يوم الأربعاء سابع ذي القعدة، وأقيم بعده حفيدُه أبو ثابت عامر ابن الأمير أبي عامر بن السلطان أبي يعقوب يوسف بن يعقوب بن عبد الحق، وكانت مُدَّةُ حُكمِه إحدى وعشرين سنةً."},{"id":2866,"title":"قتل برلغوا المغولي المسلم ملك سيس هيتوم .","date":["العام الهجري :707","العام الميلادي :1307"],"text":"قُتِلَ هيتوم متمَلِّكُ سيس على يد بعضِ أمراء المغول؛ وذلك أنَّ هيتوم كان يحمِلُ القطعيَّة إلى المغول كما يحمِلُها إلى مصر، ويحضُر إلى كلِّ سنة أميرٌ من أمرائهم حتى يتسَلَّم الحَملَ، فحضر إليه من أمراء المغول برلغوا، وقد أسلَم وحَسُن إسلامُه، فعزم على بناءِ جامعٍ بسيس يعلَنُ فيه بالأذان، كما تجهَرُ هناك النصارى بضرب النواقيس، فشَقَّ ذلك على هيتوم، وكتب إلى خدبندا بأنَّ برلغوا يريد اللَّحاقَ بأهلِ مصر، وبناء جامع بسيس، فبعث خدبندا بالإنكارِ على برلغوا، وتهدَّدَه وألزمه بالحضورِ، فغضب برلغوا من هيتومِ، وصنع طعامًا ودعاه، ولم يكُنْ عنده عِلمٌ بأنَّ برلغوا اطَّلَع على شكواه منه لخدبندا، فحضر وهو آمِنٌ في جماعةٍ مِن أكابر الأرمنِ وإخوان له، فعندما مدُّوا أيديهم إلى الطعام أخذَتهم السيوفُ مِن كُلِّ جانب، فقُتِلوا عن آخِرِهم، ولم ينجُ سوى أخوه ليفون في نفَرٍ قليل، فلَحِقَ بخدبندا وأعلَمَه بقتل برلغوا لأخيه هيتوم وأمرائِه، وقَدِمَ عليه أيضًا برلغوا، فقَتَله بقَتلِه هيتوم."},{"id":2867,"title":"حرب بين التتار وبين أهل كيلان .","date":["العام الهجري :707","الشهر القمري : محرم","العام الميلادي :1307"],"text":"وقعت حربٌ بين التتار وبين أهلِ كيلان غربي طبرستان؛ وذلك أنَّ مَلِكَ التتار خربندا طلب منهم أن يجعلوا في بلادهم طريقًا إلى عسكره فامتنعوا من ذلك، فأرسل خربندا جيشًا كثيفًا ستين ألفًا من المقاتِلة؛ أربعين ألفًا مع قطلوشاه وعشرين ألفًا مع جوبان، فأمهلهم أهلُ كيلان حتى توسَّطوا بلادهم، ثم أرسلوا عليهم خليجًا من البحرِ ورَموهم بالنِّفطِ فغَرِقَ كثيرٌ منهم واحترق آخرونَ، وقَتَلوا بأيديهم طائفةً كثيرة، فلم يُفلِتْ منهم إلَّا القليل، وكان فيمن قُتِلَ أميرُ التتار الكبيرُ قطلوشاه، فاشتد غضَبُ خربندا على أهل كيلان، ولكنه فَرِحَ بقتل قطلوشاه فإنَّه كان يريدُ قَتلَ خربندا، فكفى أمره عنهم، ثمَّ قُتِلَ بعده بولاي، ثمَّ إن خربندا أرسل الشيخَ براق الرومي الصوفي الخرافي إلى أهلِ كيلان يبلِغُهم عنه رسالةً فقَتَله أهلُ كيلان وأراحوا الناسَ منه ومن ضلالاتِه، وبلادُهم من أحصَنِ البِلادِ وأطيبِها لا تُستطاعُ، وهم أهلُ سُنَّة وأكثَرُهم حنابلةٌ لا يستطيعُ مُبتَدِعٌ أن يسكُنَ بين أظهُرِهم."},{"id":2868,"title":"وقوع خلاف بين السلطان الناصر وبين الأميرين بيبرس وسلار .","date":["العام الهجري :707","الشهر القمري : محرم","العام الميلادي :1307"],"text":"في أوائل المحَرَّم أظهر السلطانُ المَلِكُ الناصر الغَضَبَ على الأمير سيف الدين سلار المغولي وبيبرس الجاشنكير، وامتنع من العلامة- العلامة: هي ما يكتُبُه السلطانُ بخطِّه على صورة اصطلاحيَّة، وكان لكل سلطانٍ علامة وتوقيع- وأغلق القلعةَ وتحَصَّن فيها، ولزمَ الأميران بيوتهما، واجتمع عليهما جماعةٌ من الأمراء وحُوصِرَت القلعة، وغُلِّقَت الأسواق، ثم راسلوا السلطانَ فتأطَّدت الأمور وسكنت الشرور على دخَنٍ وتنافُرِ قلوبٍ، وقوي الأميران أكثَرَ مما كانا قبل ذلك. وركب السلطانُ ووقَعَ الصلحُ على دخَنٍ."},{"id":2869,"title":"خروج الشيخ تقي الدين ابن تيمية من السجن .","date":["العام الهجري :707","الشهر القمري : ربيع الأول","العام الميلادي :1307"],"text":"اجتمع القضاةُ بالشيخِ تقي الدين ابن تيميَّة في دار الأوحدي من قلعةِ الجبل بمصر، وطال بينهما الكلامُ ثمَّ تفَرَّقا قبل الصلاة، والشيخُ تقيُّ الدين مُصَمِّمٌ على عدم الخروجِ من السجن، فلما كان يومُ الجمعة الثالث والعشرين من ربيع الأوَّل جاء الأميرُ حسام الدين مهنا بن عيسى مَلِك العرب إلى السجنِ بنَفسِه وأقسم على الشيخِ تقي الدين ليخرجَنَّ إليه، فلما خرجَ أقسَمَ عليه ليأتيَنَّ معه إلى دار نائبِ السلطانِ الأميرِ سيف الدين سلار المغولي، فاجتمعَ به بعضُ الفقهاء بدار سلار وجَرَت بينهم بحوثٌ كثيرة، ثم فَرَّقَت بينهم الصلاة، ثم اجتمعوا إلى المغربِ وبات الشيخ تقي الدين عند سلار، ثم اجتمعوا يومَ الأحد بمرسومِ السلطان جميعَ النهار، ولم يحضُرْ أحدٌ من القضاة بل اجتمع من الفقهاءِ خلقٌ كثير، أكثَرُ من كل يوم، منهم الفقيه نجم الدين بن رفع، وعلاء الدين التاجي، وفخر الدين ابن بنت أبي سعد، وعز الدين النمراوي، وشمس الدين بن عدنان، وجماعة من الفقهاء، وطلبوا القضاةَ فاعتذروا بأعذار، بعضُهم بالمرض، وبعضُهم بغيره؛ لمعرفتهم بما ابنُ تيميَّة منطوٍ عليه من العلومِ والأدلَّةِ، وأنَّ أحدًا من الحاضرين لا يطيقُه، فقَبِلَ عذرَهم نائِبُ السلطنةِ ولم يكَلِّفْهم الحضورَ بعد أن رسم السلطانُ بحضورهم أو بفَصلِ المجلس على خير، وبات الشيخُ عند نائب السلطنة، وجاء الأميرُ حسام الدين مهنا يريد أن يستصحِبَ الشيخ تقي الدين معه إلى دمشق، فأشار سلار بإقامةِ الشيخِ بمصر عنده ليرى الناسُ فَضلَه وعِلمَه، وينتَفِعَ الناسُ به ويشتغلوا عليه، فكتب الشيخُ كتابًا إلى الشام يتضَمَّنُ ما وقع له من الأمورِ."},{"id":2870,"title":"حبس شيخ الإسلام ابن تيمية مرة أخرى بمصر .","date":["العام الهجري :707","الشهر القمري : شوال","العام الميلادي :1308"],"text":"وفي شوال مِن هذه السنة شكا الصوفيَّةُ بالقاهرة على الشيخِ تقيِّ الدين ابن تيميَّةَ, وكلامه في ابنِ عربي وغيرِه إلى الدولة، فردُّوا الأمرَ في ذلك إلى القاضي الشافعيِّ ابن صصرى، فعُقِد له مجلسٌ وادعى عليه ابنُ عطاء بأشياءَ فلم يثبُتْ عليه منها شيءٌ، لكنَّه قال: لا يُستغاثُ إلَّا بالله، لا يُستغاثُ بالنبيِّ صلَّى الله عليه وسلَّم؛ فالاستغاثةُ بمعنى العبادة، فبعضُ الحاضرين قال: ليس عليه في هذا شَيءٌ, ورأى القاضي بدر الدين بن جماعة أنَّ هذا فيه قِلَّةُ أدَبٍ!! فحضرت رسالةٌ إلى القاضي أن يعملَ معه ما تقتضيه الشريعةُ، فقال القاضي: قد قلتُ له ما يقالُ لِمِثله، ثمَّ إنَّ الدولة خيَّروه بين أشياء إمَّا أن يسيرَ إلى دمشقَ أو الإسكندريةِ بشُروطٍ أو الحبسِ، فاختار الحبسَ فدخل عليه جماعةٌ في السَّفَرِ إلى دمشق ملتَزِمًا ما شُرِط، فأجاب أصحابَه إلى ما اختاروا جبرًا لخواطِرِهم، فركب خَيلَ البريد ليلة الثامِنَ عشر من شوال ثم أرسلوا خلفَه من الغَدِ بريدًا آخرَ، فردوه وحضر عند قاضي القضاة ابنِ جماعة وعنده جماعةٌ مِن الفقهاء، فقال له بعضُهم: إن الدولةَ ما ترضى إلا بالحبسِ، فقال القاضي: وفيه مَصلحةٌ له، واستناب شمسُ الدين التونسي المالكي وأذِنَ له أن يحكُمَ عليه بالحبسِ فامتنع، وقال: ما ثبت عليه شيءٌ، فأذن لنور الدين الزواوي المالكي فتحَيَّرَ، فلما رأى الشيخُ توقُّفَهم في حبسه قال: أنا أمضي إلى الحبسِ وأتَّبِعُ ما تقتضيه المصلحةُ، فقال نور الدين الزواوي: يكون في موضعٍ يصلُحُ لمِثلِه، فقيل له: الدولة ما ترضى إلا بمسمَّى الحبس، فأُرسِلَ إلى حبس القضاةِ في المكان الذي كان فيه تقي الدين ابن بنت الأعزِّ حين سُجن، وأُذِنَ له أن يكون عنده من يخدُمُه، وكان ذلك كلُّه بإشارة نصر المنبجي لوجاهته في الدولةِ، فإنَّه كان قد استحوذ على عَقلِ بيبرس الجاشنكير الذي تسلطن فيما بعدُ، وغيرِه من الدولة، والسلطانُ مقهورٌ معه، واستمر الشيخُ في الحبس يُستفتى ويقصِدُه الناسُ ويزورونه، وتأتيه الفتاوى المُشكِلة التي لا يستطيعُها الفُقَهاءُ من الأمراءِ وأعيانِ النَّاسِ، فيكتُب عليها بما يحيرُ العُقولَ من الكتاب والسنَّة، ثم عُقِدَ للشيخ مجلسٌ بالصالحية بعد ذلك كُلِّه، ونزل الشيخُ بالقاهرة بدار ابن شقير، وأكَبَّ الناس على الاجتماعِ به ليلًا ونهارًا."},{"id":2871,"title":"فتنة العبيد بمكة مع الأمير سيف الدين نوغاي القبجاقي .","date":["العام الهجري :707","الشهر القمري : ذي الحجة","العام الميلادي :1308"],"text":"قام الأميرُ سيف الدين نوغاي القبجاقي التتري أميرُ ركب الحاجِّ بمحاربة العبيدِ بمكَّةَ، وذلك أنهم كثُرَ تخطُّفُهم أموالَ التجَّار، وأخْذُهم من الناسِ بالغَصبِ ما أرادوا، فلما وقف بعضُهم على تاجرٍ ليأخُذَ قماشَه منَعَه، فضربه ضربًا مُبَرِّحًا، فثار الناسُ وتصايحوا، فبعث نوغاي مماليكَه إلى العبيد فأمسَكوا بعضَهم وفَرَّ باقيهم بعدما جُرِحوا، فرَكِبَ الشريفُ حميضة بن أبي نُمَي بالأشراف والعبيد للحَربِ، وركب نوغاي بمن معه، ونادى ألا يخرُجَ أحدٌ من الحاجِّ ولْيحفَظْ متاعَه، وساق فإذا طائفةٌ من السرويين قد فرُّوا من الخوف إلى الجبل، فقَتَل نوغاي منهم جماعة ظنًّا أنهم من العبيد، فكفَّ حميضة عن القتال."},{"id":2872,"title":"ورود الخبر بتحرك الفرنج لغزو دمياط وبناء جسر هائل عليها .","date":["العام الهجري :708","العام الميلادي :1308"],"text":"ورد الخبَرُ بأن متمَلِّكَ قُبرُص اتَّفق مع جماعة من ملوك الفرنج على عمارةِ ستين سفينة لغزو دمياط، فجمع السلطانُ الناصر بن قلاوون الأمراءَ وشاوَرَهم، فاتَّفَقوا على عمل جسرٍ مادٍّ مِن القاهرة إلى دمياط خوفًا من نزولِ الفرنج أيَّامَ النيل، وندب لذلك الأمير جمال الدين أقوش الرومي الحسامي، وأمر ألا يراعي أحدًا من الأمراءِ في تأخيرِ رجالِ بلاده، ورسَمَ للأمراء أن يُخرِجَ كُلٌّ منهم الرجالَ والأبقار، وكتب إلى الولاةِ بالمساعدة والعمل، وأن يخرُجَ كُلُّ والٍ برِجاله، وكان أقوش مَهيبًا عبوسًا قليلَ الكلام، له حُرمةٌ في قلوب الناس، فلم يصل إلى فارس كور حتى وجد ولاةَ العَمَل قد نصبوا الخِيَم وأحضروا الرجالَ، فاستدعى المهندسينَ ورَتَّب العمل، فاستقَرَّ الحال على ثلاثمائة جرَّافة بستمائة رأس بقر وثلاثين ألف رجل، وأحضر إليه نوَّابُ جميع الأمراء، فكان يركب دائمًا لتفقُّد العمل واستحثاث الرِّجال، بحيث إنَّه فقد بعضَ الأيام شادي الأمير بدر الدين الفتاح ورجالَه، فلما أتاه بعد طَلَبِه ضَرَبه نحو الخمسمائة عصاةً، فلم يغِبْ عنه بعد ذلك أحَدٌ، ونكَّلَ بكثيرٍ مِن مشايخ العربان، وضَرَبهم بالمقارعِ وخَزَم آنافَهم وقطَعَ آذانهم، ولم يكَدْ يسلَمُ منه أحد من أجناد الأمراءِ ومنشدي البلاد، وما زال يجتَهِدُ في العمل حتى أُنجِزَ الجسر في أقَلَّ مِن شهر، وكان ابتداؤُه من قليوب وآخره بدمياط، يسيرُ عليه الراكِبُ يومين، وعَرضُه من أعلاه أربعُ قَصَبات، ومن أسفَلِه ستُّ قصبات، يمشي ستة فرسان صَفًّا واحدًا، وعَمَّ النفع به، فإنَّ النيل كان في أيام الزيادة يعلو حتى تنقَطِعَ الطُّرُقاتُ ويمتَنِعَ الوصول إلى دمياط، وحضَرَ بعد فراغه الأميرُ أقوش إلى القاهرة، وخُلِعَ عليه وشُكِرَت هِمَّتُه، ووقع الاتفاقُ على عمل جسر آخَرَ بطريق الإسكندرية، ونُدِبَ لعمله الأمير سيف الدين الحرمكي، فعمر قناطِرَ الجيزة إلى آخر الرمل تحت الهَرَمين، وكانت تهَدَّمت، فعم النفعُ بعمارتِها."},{"id":2873,"title":"خلع محمد الثالث ملك بني نصر وتولي أخيه نصر بن محمد الثاني .","date":["العام الهجري :708","الشهر القمري : شوال","العام الميلادي :1309"],"text":"قام نصرُ بنُ محمد الثاني الملَقَّب بأبي الجيوش ابن السلطان الأحمر الأنصاري المغربي بالخروجِ على أخيه أبي عبد الله محمَّد الثالث وخَلَعه واستولى على الحُكمِ، ونفى أخاه المخلوعَ إلى حِصنِ المنكِبِ حتى توفِّيَ فيه عام 713."},{"id":2874,"title":"خلع السلطان محمد بن قلاوون نفسه وتنصيب بيبرس الجاشنكير .","date":["العام الهجري :708","الشهر القمري : ذي القعدة","العام الميلادي :1309"],"text":"لمَّا استقَرَّ الملك ناصر بالكرك وعَزَم على الإقامة بها بعد أن خرج من مصرَ على أنَّه يريد الحَجَّ، كتب كتابًا إلى الديار المصرية يتضَمَّنُ عَزلَ نَفسِه عن المملكة، فأثبت ذلك على القُضاةِ بمصر، وكان قد اشتَدَّ حَنَقُه، وصار في غاية الحَصرِ مِن تحَكُّم بيبرس الجاشنكيري- متذوِّق طعام السلطان- وسيف الدين سلار المغولي عليه، وعَدَم تصَرُّفِه ومَنْعه من كلِّ ما يريد، حتى إنه ما يصِلُ إلى ما يشتهي أكلَه لقِلَّةِ المُرَتَّب، فلولا ما كان يتحَصَّلُ له من أوقاف أبيه لما وجد سبيلًا إلى بلوغِ بعض أغراضِه، فكانت مُدَّةُ سلطنة الملك الناصر هذه عشر سنين وخمسة أشهر وسبعة عشر يومًا، ثم نفذَ على قضاة الشامِ وبُويِعَ الأمير ركن الدين بيبرس الجاشنكير في السلطنةِ في الثالث والعشرين من شوَّال يوم السبت بعد العصر، بدار الأمير سيف الدين سلار، اجتمع بها أعيانُ الدولة من الأمراء وغيرهم وبايعوه وخاطبوه بالمَلِك المظَفَّر، ورَكِبَ إلى القلعة ومَشَوا بين يديه، وجلس على سريرِ المَملكة بالقلعة، ودُقَّت البشائِرُ وسارت البريدية بذلك إلى سائِرِ البلدان، وفي مستهَلِّ ذي القعدة وصل الأميرُ عز الدين البغدادي إلى دمشق فاجتمع بنائِبِ السلطنة والقضاة والأمراء والأعيان بالقَصرِ الأبلقِ، فقرأ عليهم كتابَ الناصر إلى أهل مصر، وأنَّه قد نزل عن الملك وأعرض عنه، فأثبَتَه القضاة وامتنع الحنبليُّ من إثباته وقال: ليس أحدٌ يترُكُ المُلكَ مُختارًا، ولولا أنَّه مُضطهدٌ ما تركه، فعُزِلَ وأقيم غيره، واستحلَفَهم للسلطانِ الملك المظفر ركن الدين بيبرس، وكُتِبَت العلامة على القلعة، وألقابُه على محالِّ المملكة، ودُقَّت البشائِرُ وزُيِّنَت البلد، ولما قرئَ كتاب الملك الناصر على الأمراءِ بالقصر، وفيه: إني قد صَحِبتُ الناس عشر سنين ثم اخترت المقامَ بالكرك، تباكى جماعةٌ من الأمراء وبايعوا كالمُكرَهين، وتولى مكانَ الأمير ركن الدين بيبرس الجاشنكير الأميرُ سيف الدين بن علي، ويُذكَرُ أن أصل بيبرس هذا من مماليكِ الملك المنصور قلاوون البرجية، وكان شركسي الجِنسِ، ولم نعلم أحدًا ملَكَ مِصرَ مِن الشراكسة قبله إن صَحَّ أنه كان شَركسيًّا."},{"id":2875,"title":"إظهار خدبندا ملك التتار الرفض في بلاده .","date":["العام الهجري :709","العام الميلادي :1309"],"text":"أظهر خدبندا ملك التتر الرَّفضَ في بلاده، وأمر الخطباءَ أوَّلًا ألَّا يذكُروا في خُطبتِهم إلَّا عليَّ بنَ أبي طالب رضي اللهُ عنه وأهلَ بيته، ولما وصل خطيبُ بلاد الأزج إلى هذا الموضِعِ مِن خُطبتِه بكى بكاءً شديدًا وبكى الناسُ معه، ونزل ولم يتمكَّنْ من إتمام الخطبة، فأقيم مَن أتَمَّها عنه وصلَّى بالناس وظَهَر على الناسِ بتلك البلاد من أهل السُّنَّة أهلُ البدعةِ!"},{"id":2876,"title":"إنشاء المدرسة الطيبرسية في الجامع الأزهر .","date":["العام الهجري :709","العام الميلادي :1309"],"text":"أنشأها علاءُ الدين طيبرس الخازندار نقيبُ الجيوشِ بالدِّيارِ المصريةِ، وهي على يمينِ الداخِلِ من باب الجامِعِ الأزهرِ المعروفِ بباب المزينين، وتمَّ الانتهاءُ مِن بنائها في عهد السلطانِ الناصر محمد بن قلاوون، فكانت من المدارس الملحَقة بالأزهر، وعُرِفت بالمدرسة الطيبرسية نسبةً إلى علاء الدين مؤسِّسِها الذي قرَّر أن يُدرِّسَ فيها درسًا للفقهاء الشافعية. وأنشأ بجوارِها مِيضأةً وحوضَ ماء سبيل ترِدُه الدواب، وتأنَّقَ في رخامها وتذهيبِ سقوفِها."},{"id":2877,"title":"استيلاء الأسبان على جبل طارق .","date":["العام الهجري :709","العام الميلادي :1309"],"text":"فرديناند الرابع ملك قشتالة وخايمي ملك أرغون يستوليانِ على جبل طارق، لِمَنع اتِّصالِ مَملكةِ بني مرين بالمَغربِ بمَملكة بني الأحمر بغِرناطة."},{"id":2878,"title":"خلع الملك المظفر الجاشنكيري وعودة السلطان الناصر قلاوون .","date":["العام الهجري :709","الشهر القمري : رمضان","العام الميلادي :1310"],"text":"لم يكتَفِ بيبرسُ الجاشنكيري بمُلكِ مِصرَ، بل ذهب يطلُبُ مِن الملك الناصِرِ المخلوعِ ما بيَدِه في الكرك، وذلك بتحريضِ وتخويفِ الأمراء له من الناصِرِ، فأصبح يريدُ أن يجرِّدَ النَّاصِرَ مِن كُلِّ شَيءٍ، فكان هذا من أسبابِ عَودةِ النَّاصِرِ لطَلَبِ المُلك، حيث حَبَس الناصِرُ مغلطاي رسولَ المظَفَّر بيبرس الذي جاء لأخذِ باقي أموالِ ومماليك الناصِرِ من الكرك، فخاف المظَفَّر بيبرس من ذلك، واشتهر بالدِّيارِ المِصريَّة حركةُ الملك الناصر محمَّد وخروجه من الكرك، فماجت النَّاسُ، وتحرك الأميرُ نوغاي القبجاقي، وكان شجاعًا مِقدامًا حادَّ المزاجِ قَوِيَّ النفس، وكان من ألزامِ الأمير سلار النائب، وتواعَدَ مع جماعةٍ مِن المماليك السلطانية أن يَهجُمَ بهم على السُّلطانِ الملك المظَفَّر إذا رَكِبَ ويَقتُلَه، فلما ركبَ المظَفَّر ونزل إلى بركةِ الجُبِّ استجمع نوغاي بمن وافقه يريدون الفَتكَ بالمظَفَّر في عودِه من البركة، وتقرب نوغاي من السلطانِ المظَفَّر بيبرس قليلًا قليلًا، وقد تغيَّرَ وجهُه وظهر فيه أماراتُ الشَّرِّ، ففطن به خواصُّ المظفر وتحَلَّقوا حول المظفر، فلم يجِدْ نوغاي سبيلًا إلى ما عزم عليه، وعاد المَلِكُ المظفر إلى القلعة فعَرَّفه ألزامه ما فَهِموه من نوغاي، وحَسَّنوا له القبضَ عليه وتقريرَه على من معه، فاستدعى المَلِكُ المظفَّر الأميرَ سلار وعرَّفه الخبَرَ، وكان نوغاي قد باطَنَ سلار بذلك، فحَذَّر سلار المَلِكَ المظَفَّر وخَوَّفَه عاقبةَ القَبضِ على نوغاي، وأن فيه فسادَ قلوب جميع الأمراء، وليس الرأيُ إلَّا الإغضاء فقط، وقام سلار عنه، فأخذ البرجيَّة بالإغراء بسلار وأنه باطَنَ نوغاي، ومتى لم يقبِضْ عليه فسد الحالُ، وبلغ نوغاي الحديثُ، فواعد أصحابَه على اللَّحاقِ بالملك الناصر، وخرج هو والأميرُ مغلطاي القازاني الساقي ونحو ستين مملوكًا وقت المغرب عند غَلقِ باب القلعة في ليلةِ الخميس خامس عشر جمادى الآخرة من هذه السنة، وقيلَ في أمر نوغاي وهروبِه وجهٌ آخَرُ، ثم أرسل خَلفَهم المَلِكُ المظَفَّر بيبرس مَن يعيدُهم، ولكن لم يَقدِروا عليهم وعادوا إلى مصر، أمَّا هؤلاء لَمَّا وصلوا إلى الناصر محمد وأعلموه بالأمرِ قَوِيَ في نفسه الرجوعُ للمُلكِ، فكاتب النوابَ فأجابوه بالسَّمعِ والطَّاعةِ، وأخذ المَلِكُ النَّاصِرُ في تدبيرِ أمرِه، وبينما المظَفَّر في ذلك ورد عليه الخبَرُ من الأفرم بخروجِ المَلِك الناصِرِ مِن الكرك، فقَلِقَ المظَفَّر من ذلك وزاد توَهُّمه؛ ونفَرَت قلوبُ جماعةٍ مِن الأمراء والمماليك منه، وخَشُوا على أنفُسِهم، واجتمع كثيرٌ من المنصوريَّة والأشرفيَّة والأويراتية وتواعدوا على الحَربِ، وأمَّا الملك المظَفَّر بيبرس هذا فإنَّه أخذ في تجهيزِ العساكِرِ إلى قتال المَلِك الناصِرِ محمد بن قلاوون حتى تمَّ أمرُهم وخرجوا مِن الدِّيارِ المِصريَّة في يوم السَّبتِ تاسِعَ شهر رجب وعليهم خمسةُ أمراء من مُقَدَّمي الألوفِ، فلم يكُنْ إلَّا أيامٌ وورد الخبر ثانيًا بمسير الملك الناصِرِ محمد من الكرك إلى نحو دمشق، فتجهَّزَت عسكر المظَفَّر بيبرس في أربعة آلاف فارس وخرجوا من القاهرة في العشرين من شعبان إلى العبَّاسة، ثمَّ إنَّ المظَفَّر أخذَ عَهدًا من الخليفة العباسي بمصر أنَّه هو السلطانُ، ولكن قَدِمَ عليه الخبَرُ في خامس عشرين شعبان باستيلاء الملك الناصر على دِمشقَ بغيرِ قِتالٍ، فعَظُمَ ذلك على المَلِك المظفَّر وأظهر الذِّلَّة، وخرجت عساكِرُ مِصرَ شيئًا بعد شيءٍ تريد المَلِكَ الناصِرَ حتى لم يبقَ عنده بالدِّيارِ المصريَّة سوى خواصِّه من الأمراء والأجناد، فلما كان يوم الثلاثاء سادس عشر رمضان استدعى الملِكُ المظَفَّر الأمراءَ كُلَّهم واستشارهم فيما يفعل، فأشار الأمير بيبرس الدوادار المؤرخ والأمير بهادر آص بنزوله عن المُلكِ والإشهادِ عليه بذلك كما فعله المَلِكُ الناصر، وتسير إلى الملك الناصر بذلك وتَستَعطِفُه، وتخرُجُ إلى إطفيح بمن تثِقُ به، وتقيمُ هناك حتى يَرِدَ جوابُ الملك الناصِرِ عليك فأعجبه ذلك، وقام ليجَهِّزَ أمْرَه، وبعث بالأميرِ بيبرس الدوادار إلى المَلِك الناصر محمد يُعَرِّفه بما وقع، وقيل إنه كتب إلى الملك الناصر يقولُ: \" والذي أعَرِّفُك به أني قد رجعت أقلِّدُك بغيك؛ فإن حبستَني عددتُ ذلك خلوةً، وإن نفيتَني عددتُ ذلك سياحةً، وإن قتلتَني كان ذلك لي شهادةً\" فلما سمع الملك الناصر ذلك، عَيَّنَ له صهيون ثمَّ اضطربت أحوالُ المظَفَّر بيبرس وتحَيَّرَ، وقام ودخل الخزائِنَ، وأخذ من المال والخيل ما أحَبَّ، وخرج من يومِه مِن باب الإسطبل في مماليكِه وعِدَّتُهم سبعُمائة مملوك، ومعه من الأمراءِ عِدَّةٌ، وعَلِمَت العوام بذلك فأخذوا باللَّحاقِ بهم وضَرْبِهم، وفي يوم الجمعة تاسع عَشَرِه خُطِبَ على منابر القاهرة ومِصرَ باسمِ الملك الناصر، وأُسقِطَ اسمُ الملك المظفر بيبرس هذا وزال مُلكُه، ولما فارق القلعةَ أقام بإطفيح يومين؛ ثم اتَّفَق رأيه ورأي أيدمر الخطيري وبكتوت الفتاح إلى المسير إلى بُرقة، وقيل بل إلى أسوان، ثم أمر الناصِرُ بإحضاره."},{"id":2879,"title":"فتنة بين القيسية واليمانية بحوران .","date":["العام الهجري :709","الشهر القمري : شوال","العام الميلادي :1310"],"text":"في سادَسَ عَشَر شوال وقع بين أهلِ حوران من قيس ويَمَن فقتل منهم مقتلةٌ عَظيمةٌ جِدًّا، قُتِلَ مِن الفريقينِ نحوٌ من ألف نفسٍ بالقُربِ من السويداء (جنوبي سوريا)، وكانت الكسرةُ على يمن، فهربوا من قيس حتى دخل كثيرٌ منهم إلى دمشقَ في أسوأ الحال وأضعفِه، وهَرَبت قيس خوفًا من الدولةِ، وبَقِيَت القُرى خاليةً والزُّروعُ سائبةً."},{"id":2880,"title":"مقتل الملك المظفر بيبرس الجاشنكيري المخلوع .","date":["العام الهجري :709","الشهر القمري : ذي القعدة","العام الميلادي :1310"],"text":"هو المَلِكُ المظَفَّر رُكنُ الدين بيبرس البرجي الجاشنكير- متذوِّق طعام السلطان- المنصوري. كان يُعرَف بالعثماني كان أبيضَ أشقرَ مُستدير اللحية، فيه عقل ودِينٌ، وله أموالٌ لا تحصى، وله إقطاعٌ كبيرٌ فيه عدَّة إقطاعات لأمراءَ، كان أستاذ دار الملك الناصر محمد بن قلاوون وسلار نائبًا فحَكَما في البلاد وتصَرَّفا في العباد، وللسُّلطانِ الاسمُ لا غير، وكان نواب الشام خوشداشية- زملاء مهنته- الجاشنكير وحزبه من البرجيه قويًّا، فلما توجه الملك الناصر إلى الحجاز ورَدَّ من الطريق إلى الكرك وأقام بها، لَعِبَ الأميرُ سيف الدين سلار بالجاشنكير وسَلْطَنَه وسُمِّيَ بالملك المظَفَّر، وفَوَّضَ الخليفةُ إليه ذلك وأفتى جماعةٌ من الفقهاء له بذلك، وكُتِبَ تقليدُه وركب بخِلعةِ الخلافةِ السَّوداء والعمامة المدوَّرة والتقليد على رأسِ الوزير، وناب له الأمير سيف الدين سلار واستوسق له الأمر، فأطاعه أهل الشام ومصر وحلفوا له في شوال سنة ثمانٍ وإلى وسط سنة تسع، فغضب منه الأمير سيف الدين برلغي وجماعةٌ من الخاصكية نحو المائة وخامروا عليه إلى الكرك، فخرج السلطان الناصر بن قلاوون المخلوع من الكرك وحضر إلى دمشقَ وسار في عسكر الشام إلى غزَّة، فجَهَّز المظفر يزكا- طلائع- قَدَّمَ عليهم الأميرَ سيفَ الدين برلغي فخامر إلى الناصر فذَلَّ المظَفَّر وهرب في مماليكه نحو الغرب, فلما خرج الأميرُ سيف الدين قراسنقر المنصوري من مصر متوجِّهًا إلى نيابة الشام عِوَضًا عن الأفرم، فلمَّا كان بغزَّة في سابع ذي القعدة ضرب حلقةً لأجل الصيد، فوقع في وسَطِها بيبرس الجاشنكير في ثلاثمائةٍ من أصحابه فأُحيطَ بهم وتفَرَّقَ عنه أصحابه فأمسكوه ورجع معه قراسنقر وسيف الدين بهادر على الهجن، فلما كان بالخطارة تلقَّاهم استدمر فتسَلَّمَه منهم، ورجعا إلى عسكَرِهم، ودخل به استدمر على السُّلطانِ فعاتبه ولامه، وكان آخِرَ العهد به، فقُتِلَ ودُفِنَ بالقرافة ولم ينفَعْه شَيءٌ ولا أمواله، بل قُتِلَ شَرَّ قِتلةٍ، حيث أحضره السلطانُ فقَرَّره بكلِّ ما فعله من شنائِعَ على السلطان وهو يقِرُّ بذلك، ثمَّ أمَرَ به فخُنِقَ بين يديه بوَتَرٍ حتى كاد يَتلَف، ثمَّ سَيَّبَه حتى أفاق، وعنَّفَه وزاد في شَتمِه، ثم خنَقَه ثانيًا حتى مات، وأنزل على جنوية إلى الإسطبل السلطاني فغُسِّلَ ودُفِنَ خلف قلعةِ الجبل، وذلك في ليلةِ الجمعة خامس عشر ذي القعدة، وكانت أيام المظفَّر هذا في سلطنة مصر عشرة أشهر وأربعة وعشرين يومًا لم يتهَنَّ فيها من الفِتَنِ والحركةِ!!"},{"id":2881,"title":"السلطان الناصر محمد بن قلاوون يقبض على العديد من الأمراء .","date":["العام الهجري :710","العام الميلادي :1310"],"text":"بعد أن رجع الناصِرُ محمَّد إلى السلطنة وقَتَل المظَفَّر بيبرس الجاشنكيري، بقِيَ هناك الكثيرُ مِن الأمراء الذين كان يتخَوَّفُ منهم فبدأ بالقَبضِ عليهم فاستدعى من دمشقَ سبعةً من الأمراء واعتقَلَهم وحبَسَهم عنده، وفي مِصرَ قَبَض على أربعةَ عَشرَ أميرًا وحَبَسَهم، ومنهم من قُتِلَ وأُخِذَت إقطاعاته، وقُبض أيضًا على مماليك المظَفَّر بيبرس، ولكِنَّه تَرَكهم رحمة لهم، ثم إنَّه كان يهتَمُّ أكثَرَ شَيء ٍلأمرِ الأمير سيف الدين سلار المغولي الذي كان نائِبَ السلطان بيبرس الجاشنكيري، فهو الذي كان الآمِرَ الناهيَ في الدولة، وهو الذي حَرَّض بيبرسَ على كلِّ الأفعال التي صدرت منه وخاصةً مُصادرة أموال الناصر، وكان سلار قد هرب إلى الشوبك، ثمَّ إنَّه قَرَّر الحضورَ إلى السلطانِ النَّاصر، فلمَّا حضر حبَسَه وبقي محبوسًا شَهرًا حتى مات في سِجنِه جُوعًا وعَطَشًا، وقد استُخرِجَت منه كلُّ أمواله وإقطاعاته، فكانت كثيرة جدًّا بما لا يُحَدُّ ولا يوصَفُ من الذهب والفضَّة والجواهر الثمينة من الياقوت والزمُرُّد واللؤلؤ وغير ذلك من الأموال والأراضي والحيوانات الشيء المهول، ويُذكَرُ أنَّ سلار أصله من المماليك التتار الأويراتية، وصار إلى الملك الصالحِ عليِّ بن قلاوون، وبقِيَ بعد موته في خدمة الملك المنصورِ قلاوون حتى مات، ثم دخل في خدمةِ الملك الأشرف خليل بن قلاوون، وحَظِي عنده، فلما قُتِلَ حظي عند لاجين لمودَّة كانت بينهما، وترقى إلى أن صار نائِبَ السلطنة بديار مصرَ للسُّلطانِ المظَفَّر بيبرس."},{"id":2882,"title":"وفاة نجم الدين ابن الرفعة الفقيه الشافعي .","date":["العام الهجري :710","الشهر القمري : رجب","العام الميلادي :1310"],"text":"هو الشَّيخُ نجم الدين أبو العبَّاس أحمد بن محمد بن علي بن مرتفع بن حازم، الأنصاري المصري، المعروف بابن الرفعة. فقيه شافعيٌّ. تفقه على الظهير والشريف العباسي، وسَمِعَ الحديث من محيي الدين الدميري، وعُيِّنَ مدرسًا بالمدرسة المعزية. كان محتَسِبَ القاهرة وناب في الحكم, ومن كتبه: \"المطلب في شرح الوسيط\"، \"الكفاية في شرح التنبيه\" وغير ذلك."},{"id":2883,"title":"أسر الفرنج لرسل السلطان الناصر .","date":["العام الهجري :711","العام الميلادي :1311"],"text":"قَدِمَ الخبَرُ من سيس بأنَّ فِرنجَ جزيرة المصطكى أسَروا رسُلَ السلطان الناصر إلى المَلِك طقطاي، ومن معهم من رسل طقطاي وعِدَّتُهم ستون رجلًا، فبعث الملك طقطاي في فدائِهم ستين ألفَ دينار ليتَّخِذَ بذلك يدًا عند السلطانِ، فلم يمكِّنوه منهم، فكتب إلى الإسكندريَّة ودمياط بالحوطة على تجَّار الفرنج واعتقالِهم كُلِّهم، فأُحيطَ بحواصِلِهم وحُبِسوا بأجمَعِهم، وحضر أحَدُ تجَّار الجنوية فضَمِنَ إحضار الرسُل وما معهم، فمُكِّنَ من السَّفَر."},{"id":2884,"title":"وفاة ابن منظور صاحب لسان العرب .","date":["العام الهجري :711","العام الميلادي :1311"],"text":"هو الإمامُ اللُّغويُّ الحُجَّةُ مُحمَّدُ بنُ مكرم بن علي بن منظور الخزرجي الأنصاري الرويفعي الإفريقي، من ولد رُويفِع بن ثابت الأنصاري, وهو صاحِبُ (لسان العرب) ولِدَ بمصر سنة 630 ونشأ فيها وتعَلَّم. كان أديبًا وشاعرًا، وعالِمًا باللغة والنحو والتاريخ، وخَدَم في ديوان الإنشاء بالقاهرة, ثم وَلِيَ القضاء في طرابلس, وعاد إلى مصر فتوفِّيَ فيها، وقد ترك بخَطِّه نحوَ خمسمائة مجَلَّد، وعَمِيَ في آخر عمره. كان له حب في اختصار الكُتُب الطوال، فاختصر كتاب الأغاني للأصفهاني، وكتاب العِقدِ الفريد لابن عبد ربه، والذخيرة لابن بسام، ومفردات ابن البيطار، ويتيمة الدهر للثعالبي، وتاريخ مدينة دمشق لابن عساكر، وصفة الصفوة لابن الجوزي، وغيرها من الكتب، أما أشهر كتبه على الإطلاق وأنفَعُها فهو كتابُ (لسان العرب) وهو مُعجَمٌ لُغويٌّ لا يزال يُعتبَر المرجِعَ الأُمَّ من بين المعاجِمِ اللغوية. توفِّيَ في القاهرة عن 81 عامًا."},{"id":2885,"title":"إقامة الخطبة للسلطان الناصر في طرابلس الغرب .","date":["العام الهجري :711","الشهر القمري : رجب","العام الميلادي :1311"],"text":"أقيمَت الخُطبةُ للمَلِك الناصر بطرابلس الغرب، أقامها له الشيخُ أبو يحيى زكريا بن أحمد بن محمد بن يحيى بن عبد الواحد بن حفص عمر اللحياني، لما جهزه السلطان إليها بالصناجِقِ وبعِدَّةٍ من الأجناد، وكان ذلك في شَهرِ رَجَب، وكان الأجنادُ قد قَدِموا مع بيبرس، بعدما قَدَّمَها أبو يحيى من مِصرَ في جُمادى الأولى."},{"id":2886,"title":"هروب بعض الأمراء إلى التتار .","date":["العام الهجري :712","العام الميلادي :1312"],"text":"قدم البريدُ مِن حَلَب بعبور قرا سنقر ومن معه من الأمراء إلى بلاد التتار، وأنهم بَعَثوا بأولادهم وحريمهم إلى مصر، فكان مِن خَبَرِهم أنهم لما وصلوا إلى الرحبة انقطع كثيرٌ ممن تَبِعَهم من المماليك والتركمان، فبعث قرا سنقر ولَدَه الأمير فرجًا، وبعث الأفرم ولده موسى مع بعض من يُوثَقُ به، وأُمِرَا بتقبيلِ الأرض بين يَدَيِ السلطان، وأنْ يُبَلِّغاه أنَّ الأمراء ما حملَهم على دخولِ بلاد العدو إلَّا الخوفُ، وأن الأولادَ والحريمَ وداعه، فلْيَفعَلِ السلطان معهم ما يليقُ به، فقَدِما إلى القاهرة، وبَقِيَا في الخدمة، وسار الأمراءُ إلى ماردين، وكتبوا إلى خربندا بقُدومِهم، فبعث أكابِر المغول إلى لقائهم، وتقَدَّم إلى ولاة الأعمال بخِدمتِهم والقيامِ لهم بما يليق بهم، فلما قاربوا الأرد وركب خربندا وتلقاهم، وترجَّل لهم لَمَّا ترجلوا له، وبالغ في إكرامِهم وسار بهم إلى مخيَّمِه، وأجلسهم معه على التخت، وضَرَبَ لكُلٍّ منهم خركاه- خيمة- ورَتَّب لهم الرواتب السَّنيَّة، ثم استدعاهم بعد يومين، واختلا بقرا سنقر، فحَسَّنَ له عبورَ الشَّام، وضَمِنَ له تسليمَ البلاد بغير قتال، ثم خلا بالأفرم فحَسَّنَ له أيضًا أخْذَ الشام، إلَّا أنَّه خَيَّلَه من قوة السلطان وكثرةِ عساكره، فأقطع خربندا مراغة لقرا سنقر، وأقطع همذان للأفرم، واستمَرُّوا هكذا."},{"id":2887,"title":"وفاة الملك المنصور صاحب ماردين وتولي ابنه بعده .","date":["العام الهجري :712","الشهر القمري : ربيع الآخر","العام الميلادي :1312"],"text":"هو المَلِكُ المنصور صاحب ماردين أبو الفتح نجم الدين غازي بن المَلِك المظَفَّر قرارسلان بن الملك السعيد نجم الدين غازي بن الملك المنصور ناصر الدين أرتق بن غازي بن المني بن تمرتاش بن غازي بن أرتق أصحاب ماردين من عِدَّة سنين، كان شيخًا حسنًا مَهيبًا كامِلَ الخلقة بدينًا سمينًا، إذا ركب يكون خلْفَه محَفَّة، خوفًا من أن يمسَّه لُغوبٌ فيركب فيها، توفِّيَ في تاسع ربيع الآخر ودُفِنَ بمدرسته تحت القلعة، وقد بلغ من العمر فوق السبعين، ومكث في الملك قريبًا من عشرين سنة، وقام مِن بَعدِه في المُلْكِ وَلَدُه العادل فمكث سبعة عشر يومًا، ثم مَلَك أخوه المنصور."},{"id":2888,"title":"محاصرة خدابندا التتري الرحبة ورجوعهم خاسرين .","date":["العام الهجري :712","الشهر القمري : رجب","العام الميلادي :1312"],"text":"ورد الخبَرُ في أول رجب بحركة خدابندا (ويقال له خربندا) وسبب ذلك رحيلُ بعض الأمراء إليه هاربين من السلطان الناصر منهم قراسنقر وغيره وإقامتُهم عنده، وتقويةُ عَزمِه على أخذ الشام، وكان السلطانُ تحت الأهرام بالجيزة، فقَوِيَ عزمُه على تجريد العساكر، ولم يزل هناك إلى عاشِرِ شعبان، فعاد إلى القلعة، وكتب إلى نوَّاب الشام بتجهيز الإقامات، وعرض السلطانُ العسكر، وترحَّلوا شيئًا بعد شيء، من أوَّل رمضان إلى الثامن عشر منه، حتى لم يبقَ بمِصرَ أحد من العسكر، وخرج السلطانُ في ثاني شوال، ونزل مسجِدَ تبر خارج القاهرة، ورحل في يوم الثلاثاء ثالثَه، ورتَّب بالقلعة سيف الدين أيتمش المحمدي، فلما كان ثامنه قَدِمَ البريد برحيل التتر ليلة سادس عشر رمضان من الرحبة، وكان من أمرهم فيها أنَّه لما وصل التتر إلى الرحبة فحاصروها عشرين يومًا وقاتلهم نائبُها الأمير بدر الدين موسى الأزدكشي خمسة أيام قتالًا عظيما، ومنعهم منها، فأشار رشيد الدولة بأن ينزلوا إلى خِدمةِ السلطان خربندا ويُهدُوا له هدية ويطلبون منه العفوَ، فنزل القاضي نجم الدين إسحاق وأهدَوا له خمسةَ رؤوس خيل، وعشرة أباليجَ سكر، فقَبِلَ ذلك, وأخذ الرحبةَ منهم بالأمان وعَفَا عن أهلها ولم يسفِكْ فيها دمًا، وبات بها ليلة الأربعاء في الخامس والعشرين من رمضان, فلما أصبح ارتحل وترك لأهلِ الرحبة أشياءَ كثيرةً مِن أثقال مناجيق وغيرها وكان معه يومئذٍ قرا سنقر والأفرم وسليمان بن مهنا، وكان أهلها قد حلفوا لخربندا فلمَّا ارتحل عنها واستقر الأمر التمس قاضيها ونائبُها وطائفةٌ حلفت لخربندا عَزْلهم من السلطانِ لمكان اليمينِ له فعَزَلهم, وكانت بلادُ حلب وحماة وحمص قد أجلَوا منها وخَرب أكثَرُها ثم رجعوا إليها لما تحققوا رجوع التتر عن الرحبة، وطابت الأخبار وسكنت النفوس ودَقَّت البشائر وتَرَكت الأئمَّةُ القنوت، وخَطَب الخطيبُ يوم العيد وذكَّر الناسَ بهذه النعمة، وكان سبب رجوع التتر قِلَّة العَلَف وغلاء الأسعار وموت كثير منهم، وأشار على سلطانِهم خربندا بالرجوعِ الرشيد وجوبان،، وعودهم إلى بلادِهم بعدما أقاموا عليها من أول رمضان، ففَرَّق السلطانُ الناصر العساكِرَ في قانون وعسقلان، وعزم على الحَجِّ، ودخل السلطانُ دمشق في التاسع عشر، وخرج منها ثاني ذي القعدة إلى الكرك، ويذكر أن شيخ الإسلام ابن تيمية كان مِمَّن قَدِمَ ورجع إلى دمشق بصُحبةِ السلطان، فكان يومًا مشهودًا خرج الناس لرؤيتِه."},{"id":2889,"title":"إرسال جيش إلى مكة بسبب ظلم أميرها وتمرده .","date":["العام الهجري :713","العام الميلادي :1313"],"text":"توجَّهت تجريدة- خَيْلٌ لا رَجَّالة فيها- إلى مكَّة صحبة الأمير سيف الدين طقطاي الناصري والي قوص، وسيف الدين بيدوا، وعلاء الدين أيدغدي الخوارزمي، وصاروجا الحسامي، وتوجه دمشق سيف الدين بلبان البدري مع الركب، وأضيف إليهم عِدَّةٌ من الأجناد، وذلك بسَبَبِ الشريف حميضة بن أبي نمي، فإنَّه كَثُرَ ظُلمُه، ثم قَدِمَ الخبر من مكة بقَتلِ أبي الغيث في حَربٍ مع أخيه حميضة، وأنَّ العسكرَ المجرَّد إلى مكة الذي وصل إليها في رجب واقع حميضة وقَتَل عِدَّةً من أصحابه، فانهزم حميضة وسار يريد بلاد خربندا، فتلَقَّاه خدبندا وأكرمه، وأقام حميضة عنده شهرًا، وحَسَّن له إرسال طائفةٍ مِن المغول إلى بلاد الحجاز لِيَملِكَها، ويخطب له على منابرها، وكان السلطانُ الناصر قد أنعم على محمد بن مانع بإمرةِ مهنا، فشَنَّ حميضة الغارات على مكَّة وأخذ جمالَ مهنا وطرده، فسار مهنا أيضًا إلى خدبندا، فسُرَّ به وأنعم عليه."},{"id":2890,"title":"قيام دولة بني المظفر بفارس .","date":["العام الهجري :713","العام الميلادي :1313"],"text":"مع ضَعفِ الدولة الإيلخانية المغوليَّة وانهيارها بعد وفاة السلطان أبي سعيد ولا وريث له، والفوضى قائمة، فكان نتيجة ذلك اقتسام البلاد، فكانت كرمان وجنوبي فارس وكردستان من نصيب شَرفِ الدين المظَفَّر الذي كان هو حاكِمَها، ثم صار ابنه مبارز الدين محمد حاكمًا لمدينة يزد سنة 718 الذي وسَّع المملكة بحروبه مع بني أينجو في فارس، فبدأت دولةُ بني المظفَّر فيها."},{"id":2891,"title":"الإغارة على بلاد ماردين وقتال التتار .","date":["العام الهجري :713","العام الميلادي :1313"],"text":"توجَّهَ من حلب ستُّمائة فارس عليهم الأميرُ شهاب الدين قرطاي للغارة على بلاد ماردين ودنيسر لقلة مراعاة صاحب ماردين لِما يُرسَم به، فشَنَّ قرطاي الغارةَ على بلاد ماردين يومين، فصادف التتارَ قد قَدِموا إلى ماردين على عادتهم كلَّ سَنةٍ لجباية القطيعة، وهم في ألفي فارس، فحارَبَهم قرطاي وقتل منهم ستَّمائة رجل، وأسَرَ مائتين وستين، وقَدِمَ بالرؤوس والأسرى إلى حلب، ومعهم عِدَّةُ خُيولٍ."},{"id":2892,"title":"ثورة على نصر بن محمد الثاني في غرناطة .","date":["العام الهجري :713","العام الميلادي :1313"],"text":"ثار أبو سعيدٍ فَرَجُ بن إسماعيل بن يوسف بن نصر الأحمري صاحِبُ مالقة على ابنِ عَمِّه نصر بن محمد الثاني واستولى على المرية وبلش، وهزم قوات نصر؛ مما اضطر نصرًا إلى التنازل له عن العَرشِ والخروج من غرناطة إلى وادي آش ومبايعة أبي الوليد إسماعيل بن فرج من أسرة بني نصر خلفًا له."},{"id":2893,"title":"وفاة ملك القفجاق طقطغاي خان .","date":["العام الهجري :713","الشهر القمري : رمضان","العام الميلادي :1314"],"text":"هو مَلِكُ القفجاق المسمَّى طقطغاي بن منكوتمر بن طغان بن باطو بن جوجي، بن جنكيزخان، وكان له في المُلكِ ثلاث وعشرون سنة، وكان عمرُه ثمانية وثلاثين سنة، وكان شهمًا شجاعًا على دين التتر في عبادة الأصنام والكواكب، يُعَظِّمُ المجسِّمة والحكماء والأطباء، ويُكرِمُ المسلمين أكثَرَ من جميع الطوائف، كان جيشُه هائلًا لا يَجسُرُ أحد على قتاله لكثرة جيشِه, وقوَّتِهم وعدَدِهم، ويقال إنه جرَّد مرةً تجريدةً من كل عشرةٍ مِن جيشه واحدًا فبلغت التجريدة مائتي ألف وخمسينَ ألفًا! توفي في رمضان, وقام في المُلكِ من بعده ابنُ أخيه أزبك خان بن طغرل بن منكوتمر بن طغان، وكان مسلمًا فأظهر دين الإسلام ببلادِه، وقتل خلقًا من أمراء الكَفَرة وعَلَت الشرائِعُ المحمَّديَّة على سائر الشرائع هناك، ولله الحمد والمنة على الإسلامِ والسُّنَّة."},{"id":2894,"title":"إنكار البكري على السلطان الناصر بن قلاوون في شأن النصارى .","date":["العام الهجري :714","الشهر القمري : محرم","العام الميلادي :1314"],"text":"في نصف المحرَّمِ اتَّفَق أنَّه كان للنصارى مجتَمَعٌ بالكنيسة المعَلَّقة بمصر، واستعاروا من قناديلِ الجامِعِ العتيق جملةً، فقام في إنكارِ ذلك الشيخ نور الدين علي بن عبد الوارث البكري (وهو من أعداء شيخِ الإسلامِ ابنِ تيميَّة الذين كانوا قد سَعَوا في أذاه، مع أنَّ شيخَ الإسلام شَفَع فيه أيضًا لما طُلب من جهته)، وجمَعَ مِن البكريَّة وغيرِهم خلائِقَ، وتوجَّه إلى المعلقة وهَجَم على النصارى وهم في مجتَمَعِهم وقناديلُهم وشموعُهم تُزهِرُ، فأخرقَ بهم وأطفأ الشموعَ وأنزل القناديلَ، وعاد البكريُّ إلى الجامع، وقصد القومةَ، وجمع البكريُّ الناسَ معه على ذلك، وقصد الإخراقَ بالخطيب، فاختفى منه وتوجَّه إلى الفخر ناظِرِ الجيش وعَرَّفه بما وقع، وأنَّ كريمَ الدين أكرم هو الذي أشار بعاريَّة القناديلِ، فلم يَسَعْه إلَّا موافقَتُه، فلمَّا كان الغَدُ عرَّفَ الفَخرُ السلطانَ بما كان، وعَلِمَ البكري أنَّ ذلك قد كان بإشارة كريم الدين، فسار بجَمعِه إلى القلعة واجتمع بالنائِبِ وأكابر الأمراء، وشَنَّع في القول وبالغَ في الإنكار، وطلب الاجتماعَ بالسلطان، فأحضر السُّلطانُ القضاة والفُقهاءَ وطلب البكريَّ، فذكر البكريُّ من الآيات والأحاديث التي تتضَمَّنُ معاداة النَّصارى، وأخذ يحُطُّ عليهم، ثم أشار إلى السلطانِ بكلامٍ فيه جفاءٌ وغِلظةٌ حتى غَضِبَ منه عند قولِه: أفضَلُ المعروفِ كَلِمةُ حَقٍّ عند سلطان جائر، وأنت وَلَّيت القبطَ المسالمةَ، وحَكَّمْتَهم في دولتك وفي المسلمين، وأضعْتَ أموال المسلمين في العمائِرِ والإطلاقاتِ التي لا تجوز، إلى غير ذلك، فقال السلطانُ له: ويلك! أنا جائِرٌ؟ فقال: نعم! أنت سَلَّطتَ الأقباط على المسلمين، وقَوَّيت دينَهم، فلم يتملَّكِ السلطانُ نفسَه عند ذلك، وأخذ السَّيفَ وهَمَّ بضربه، فأمسك الأميرُ طغاى يده، فالتَفَت السلطان إلى قاضي القضاة زين الدين بن مخلوف، وقال: هكذا يا قاضي يتجَرَّأُ عليَّ؟ أيش يجبُ أفعل به؟ قل لي!، وصاح به، فقال له ابن مخلوف: ما قال شيئًا يُنكَرُ عليه فيه، ولا يجِبُ عليه شيء، فإنه نقل حديثًا صحيحًا، فصرخ السلطانُ فيه وقال: قمْ عني!، فقام مِن فَورِه وخرج، فقال صدر الدين بن المرحل- وكان حاضرًا- لقاضي القضاة بدر الدين محمد بن جماعة الشافعي: يا مولانا! هذا الرجل تجرَّأ على السلطانِ، وقد قال الله تعالى آمرًا لموسى وهارون حين بعَثَهما إلى فرعون {فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى} فقال ابن جماعة للسلطان: قد تجرَّأَ ولم تبقَ إلَّا مَراحِمُ مولانا السُّلطان، فانزعج السلطانُ انزعاجًا عظيمًا، ونهض عن الكرسي، وقَصَد ضربَ البكريِّ بالسَّيف، فتقدَّم إليه طغاي وأرغون في بقية الأمراء، وما زالوا به حتى أمسك عنه، وأمر بقَطعِ لسانه، فأخرج البكريُّ إلى الرحبة، وطُرِحَ إلى الأرض، والأميرُ طغاي يشير إليه أن يستغيثَ، فصرخ البكريُّ وقال: أنا في جيرةِ رسول الله، وكررها مرارًا حتى رقَّ له الأمراء، فأشار إليهم طغاي بالشَّفاعة فيه، فنهضوا بأجمَعِهم وما زالوا بالسلطانِ حتى رسم بإطلاقِه وخروجِه مِن مصر، وأنكر الأميرُ أيدمر الخطيري كونَ البكري قوى نفسَه أولًا في مخاطبة السلطان، ثمَّ إنَّه ذل بعد ذلك، ونسب إلى أنَّه لم يكن قيامُه خالصًا لله."},{"id":2895,"title":"وفاة ملك شمس الدين دوباج صاحب كيلان  .","date":["العام الهجري :714","الشهر القمري : رمضان","العام الميلادي :1315"],"text":"هو المَلِكُ شمس الدين دوباج بن ملكشاه بن رستم صاحب كيلان. خرج قاصدًا الحجَّ في هذا العام، فلمَّا كان بغباغب أدركَته منيَّتُه يوم السبت السادس والعشرين من رمضان, فحُمِلَ إلى دمشق وصُلِّي عليه ودفن بتربته المشهورة بسفح قاسيون في خامس شوال، اشتريت له وتممت وجاءت حسنةً وهي مشهورة عند المكارية شرقيَّ الجامع المظفري، وكان له في مملكة كيلان خمس وعشرون سنة، وعمر أربعًا وخمسين سنة، وأوصى أن يحُجَّ عنه جماعة ففُعِلَ ذلك."},{"id":2896,"title":"وفاة الشيخة الواعظة فاطمة بنت عياش البغدادية  .","date":["العام الهجري :714","الشهر القمري : ذي الحجة","العام الميلادي :1315"],"text":"هي الشيخةُ العاملةُ الفقيهة الزاهدة القانتة الواعظة سيدة نساء زمانها: أم زينب فاطمة بنت عياش بن أبي الفتح البغدادية، كانت تفقه الفقه جيدًا, وانتفع بها خلقٌ من نساء أهل دمشق لصِدقِها في وعظها، ثم تحولت إلى القاهرة فحصل بها النفع وارتفع قدرُها وبعُدَ صيتُها، وكانت قد تفقهت عند المقادسة، كالشيخ ابن أبي عمر وغيره. كانت وافرة العلم، فائقة قانعة باليسير، حريصة على النفع والتذكير، ذات إخلاص وخشية، انصلح بها نساء دمشق، ثم نساء مصر، وكان لها قبول زائد، ووقْع في النفوس, وقل من أُنجِبَ من النساء مثلها. قال ابن كثير: \"كانت من العالِمات الفاضلات، تأمر بالمعروف وتنهى عن المنكر، وتقوم بالاحتساب على الأحمدية في مواخاتهم النساء والمردان، وتنكر أحوالَهم وأصول أهل البدع وغيرهم، وتفعل من ذلك ما لا يقدر عليه الرجال، وقد كانت تحضر مجلس الشيخ تقي الدين ابن تيمية، فاستفادت منه ذلك وغيره، وقد سمعتُ الشيخ تقي الدين يثني عليها ويصفها بالفضيلة والعلم، ويذكر عنها أنها كانت تستحضر كثيرًا من المغني أو أكثره، وأنه كان يستعد لها من كثرة مسائلِها وحسن سؤالاتها وسرعة فهمها، وقد ختم لديها نساء كثيرًا القرآن، منهن أم زوجتي عائشة بنت صديق، زوجة الشيخ جمال الدين المِزِّي، وهي التي أقرأت ابنَتَها زوجتي أَمَة الرحيم زينب\" ماتت فاطمة ليلة عرفة عن نيف وثمانين سنة، وشيَّعها خلائق."},{"id":2897,"title":"فتح مدينة ملطية .","date":["العام الهجري :715","الشهر القمري : محرم","العام الميلادي :1315"],"text":"كانت ملطيَّة إقطاعًا للجوبان أطلقها له ملك التتر فاستناب بها رجلًا كرديًّا يقال له مندوه فتعدى وأساء وظلم، وكاتب أهلُها السلطانَ الناصر بن قلاوون وأحبُّوا أن يكونوا من رعيَّتِه، فلمَّا ساروا إليها وأخذوها وفعلوا ما فعلوا فيها جاءها بعد ذلك الجوبان فعمَرها وردَّ إليها خلقًا من الأرمن وغيرِهم، وكان سبَبُ غزو ملطيَّة أن السلطان بعث فداوية من أهل مصياف لقتلِ قرا سنقر، فكان مندوه الكرديُّ يدل على قصاد السلطانِ فأخذ منهم جماعةً، فشق ذلك على السُّلطانِ، وأخذ في العَمَلِ عليه، فبلغه مندوه أنه صار يجني خراجَ ملطية، وكان نائبُها من جهة جوبان يقال له بدر الدين ميزامير بن نور الدين، فخاف من مندوه أن يأخُذَ منه نيابة ملطية، فما زال السلطانُ يتحَيَّل حتى كاتَبَه ميزامير، وقرَّرَ معه أن يسَلِّمَ البلد لعساكره، فجهَّزَ السلطانُ العساكر، وورَّى أنَّها تقصِدُ سيس حتى نزلت بحلب، وسارت العساكِرُ منها مع الأمير تنكز على عينتاب إلى أن وصل الدرنبد، فألبس الجميعَ السلاحَ وسلك الدرنبد إلى أن نزل على ملطية يوم الثلاثاء ثالث عشريه، وحاصرها ثلاثةَ أيام، فاتَّفق الأمير ميزامير مع أعيان ملطية على تسليمها، وخرج في عِدَّة من الأعيان إلى الأمير تنكز، فأمَّنَهم وألبسهم التشاريفَ السلطانيَّةَ المجهَّزة من القاهرة، وأعطى الأميرَ ميزامير سنجقًا- راية- سلطانيًّا، ونودي في العسكر ألا يدخُلَ أحد إلى المدينة، وسار الأمير ميزامير ومعه الأمير بيبرس الحاجب والأمير أركتمر حتى نزل بداره، وقبض على مندوه الكردي، وتكاثر العَسكرُ ودخلوا إلى المدينة ونهبوها، وقتَلوا عِدَّة من أهلها، فشَقَّ ذلك على الأمير تنكز، وركِبَ معه الأمراء، ووقف على الأبواب وأخذ النهوبَ مِن العسكر، ورحل من الغد وهو الرابع عشر من محرم بالعسكر، وترك نائِبَ حلب مقيمًا عليها لهدم أسوارها، ففَرَّ مندوه قبل الدخول إلى الدربند وفات أمرُه، فلما قطعوا الدربند أُحضِرَت الأموال التي نُهِبَت والأسرى، فسُلِّمَ من فيهم من المسلمين إلى أهله، وأُفرِدَ الأرمن، فلما فُتِحَت ملطية سار الأمير قجليس إلى مصر بالبشارة، فقَدِمَ يوم الخميس ثالث صفر، ودُقَّت البشائر بذلك، وتبعه الأمير تنكز بالعساكر- ومعه الأمير ميزامير وولده- حتى نزل عينتاب ثم دابق، فوجد بها تسعة عشر ألف نولٍ تُعمَل الصوف، وتُجلَبُ كُلُّها إلى حلب، ثم سار تنكز، فقَدِمَ دمشق في سادس عشر ربيع الأول، وسير ميزامير وابنه في ثلاثين رجلًا مع العسكر المصري إلى القاهرة فقَدِموا في خامس ربيع الآخر."},{"id":2898,"title":"السلطان الناصر بن قلاوون يغير ملك النوبة وما حصل من القتال .","date":["العام الهجري :716","العام الميلادي :1316"],"text":"رأى السلطانُ الناصر بن قلاوون أن يُقَدم برشنبو النوبي، وهو ابنُ أخت داود ملك النوبة، فجَهَّز صحبته الأميرَ عِزَّ الدين أيبك على عسكر، فلما بلغ ذلك كرنبس ملك النوبة بعَث ابن أختِه كنز الدولة بن شجاع الدين نصر بن فخر الدين مالك بن الكنز يسألُ السلطانَ في أمره، فاعتقل كنز الدولة، ووصل العسكَرُ إلى دنقلة، وقد فَرَّ كرنبس وأخوه أبرام، فقُبِضَ عليهما وحُملا إلى القاهرة، فاعتُقِلا، ومَلَك عبد الله برشنبو دنقلةَ، ورجع العسكَرُ في جمادى الأولى سنة سبع عشرة، وأفرج عن كنز الدولة، فسار إلى دنقلة وجمع النَّاسَ وحارب برشنبو، فخذله جماعتُه حتى قُتِلَ، وملك كنزُ الدولة، فلما بلغ السلطانَ ذلك أطلق أبرام وبعَثَه إلى النوبة، ووَعَدَه إنَّ بعث إليه بكنز الدولة مقيَّدًا أفرج عن أخيه كرنبس، فلما وصل أبرام خرج إليه كنز الدولة طائعًا، فقبض عليه ليرسِلَه، فمات أبرام بعد ثلاثة أيام من قَبضِه، فاجتمع أهلُ النوبة على كنزِ الدولة ومَلَّكوه البلادَ."},{"id":2899,"title":"خبر جيش التتار المتوجه إلى مكة .","date":["العام الهجري :716","الشهر القمري : رجب","العام الميلادي :1316"],"text":"كان صاحِبُ مكَّة الأمير حميضة بن أبي نمي الحسني، قد قصد مَلِكَ التتر خربندا لينصُرَه على أهل مكة فساعده الروافِضُ هناك وجَهَّزوا معه جيشًا كثيفًا من خراسان، فلما مات خربندا بطل ذلك بالكلية، وعاد خميصة خائبًا خاسئًا. وفي صحبته أميرٌ من كبار الروافض من التتر يقال له الدلقندي، وقد جمع لخميصة أموالًا كثيرة ليقيم بها الرَّفضَ في بلاد الحجاز، فوقع بهما الأميرُ محمد بن عيسى أخو مهنا، وقد كان في بلاد التتر أيضًا ومعه جماعة من العرب، فقهرهما ومن كان معهما، ونهب ما كان معهما من الأموال وحضرت الرجالُ، وبلغت أخبارُ ذلك إلى الدولة الإسلامية فرَضِيَ عنه الملك الناصِرُ وأهل دولته، وغسل ذلك ذَنبَه عنده، فاستدعى به السلطانُ إلى حضرته فحضر سامعًا مطيعًا، فأكرمه نائِبُ الشام، فلما وصل إلى السلطانِ أكرمه أيضًا، ثم إنه استفتى الشيخَ تقي الدين بن تيميَّةَ، وكذلك أرسل إليه السلطانُ يسأله عن الأموالِ التي أخذت من الدلقندي، فأفتاهم أنها تُصرَفُ في المصالح التي تقَوِّي المسلمين؛ لأنها كانت مُعَدَّة لعنادِ الحَقِّ ونُصرةِ أهل البدعة على السُّنَّة."},{"id":2900,"title":"وفاة السلطان خربندا بن أرغون الرافضي ملك التتار .","date":["العام الهجري :716","الشهر القمري : رمضان","العام الميلادي :1316"],"text":"هو مَلِكُ التتارِ خَرْبَندا- بفتح الخاء المعجمة وسكون الراء وفتح الباء الموحدة وسكون النون- بن أرغون بن أبغا بن هولاكو بن تولو بن جنكيزخان السلطان غياث الدين، ملك العراق وخراسان وعراق العجم والروم وأذربيجان والبلاد الأرمينية وديار بكر، ومن الناسِ من يسَمِّيه خُدابَندا بضم الخاء المعجمة والدال المهملة وخدابندا: معناه عبد الله بالفارسي، غير أنَّ أباه لم يسمه إلَّا خربندا، وهو اسمٌ مُهمَل معناه: عبد الحمار، وسبب تسميتِه بذلك أنَّ أباه كان مهما ولِدَ له ولد يموت صغيرًا، فقال له بعض الأتراك: إذا جاءك ولد سمِّه اسمًا قبيحًا يَعِشْ، فلما ولد له هذا سماه خربندا في الظاهرِ واسمه الأصلي أبحيتو، وكان شابًّا مليحًا، لكنه كان أعور جوادًا لعَّابًا, ولما كبر خربندا وملك البلادَ بعد أخيه غازان كَرِهَ هذا الاسم واستقبحه فجعله خدابندا، ومشى ذلك بمماليكِه، وهَدَّد من قال غيره، ولم يُفِدْه ذلك إلَّا من حواشيه خاصة، ولَمَّا ملك خربندا أسلَمَ وتَسَمَّى بمحمد، واقتدى بالكتاب والسنَّة، وحاصر الرحبة سنة 712 وأخذها بالأمان وعفا عن أهلِها ولم يسفك فيها دمًا, وكان محبًّا لأهل الدين والصلاح، وضرب على الدرهم والدينار اسمَ الصَّحابة الأربعة الخلفاء، حتى اجتمع بتاج الدين الآوي الرافضي، وكان خبيثَ المذهب، فما زال بخربندا، حتى جعله رافضيًّا وكتب إلى سائِرِ مماليكه يأمُرُهم بالسبِّ والرفضِ! ووقع له بسبَبِ ذلك أمور، فقد صَمَّم أهل باب الأزج على مخالفتِه فما أعجبه ذلك وتنَمَّرَ ورسم بإباحةِ مالهم ودمهم فعُوجِلَ بعد يومين بهيضة مزعجة داواه الرشيدُ فيها بمُسَهِّل منظف فخارت قواه وتوفِّيَ. قال النويري: \"كان خربندا قبل موته بسبعة أيام قد أمر بإشهارِ النداء ألا يذكَرَ أبو بكر وعمر رضي الله عنهما، وعزم على تجريد ثلاثة آلاف فارس إلى المدينةِ النبوية لينقُلَ أبا بكر وعمر رضي الله عنهما من مَدفَنِهما، فعَجَّلَ الله بهلاكِه\" وكان موتُه في السابع والعشرين من شهر رمضان بمدينته التي أنشأها وسماها السلطانيَّة في أرض قنغرلان بالقرب من قزوين، وكانت دولتُه ثلاث عشرة سنة, وتسلطن بعده ولده بوسعيد في الثالث عشر من شهر ربيع الأول من سنة 717؛ لأنَّه كان في مدينة أخرى، وأُحضِرَ منها وتسلطَنَ، وأبو سعيد له إحدى عشرة سنة، ومدَبِّرُ الجيوش والممالك له الأمير جوبان، واستمَرَّ في الوزارة على شاه التبريزي، وأخذ أهلَ دولته بالمصادرة وقَتَل الأعيانَ مِمَّن اتهَمَهم بقتل أبيه مسمومًا، ولعب كثيرٌ من الناس به في أوَّلِ دولته، ثم عدل أبو سعيد إلى العَدلِ وإقامة السُّنَّة، فأمر بإقامة الخطبة بالترضِّي عن الشيخينِ أوَّلًا ثم عثمان ثمَّ علي رضي الله عنهم، ففرح الناسُ بذلك، وسكنت بذلك الفِتَنُ والشرور والقتال الذي كان بين أهل تلك البلاد وبهراة وأصبهان وبغداد وإربل وساوه وغير ذلك."},{"id":2901,"title":"الأعراب يقطعون الطريق على رسل السلطان من اليمن .","date":["العام الهجري :716","الشهر القمري : شوال","العام الميلادي :1317"],"text":"أخذ عَرَبُ برية عيذاب رسُلَ صاحب اليمن وعِدَّة من التجار وجميع ما معهم، فبعث السلطانُ الناصر محمد بن قلاوون العسكَرَ وهم خمسمائة فارس، عليهم الأميرُ علاء الدين مغلطاي بن أمير مجلس، في العشرين من شوال، فساروا إلى قوص، ومَضَوا منها في أوائل المحرم سنة سبع عشرة إلى صحراء عيذاب، ومضوا إلى سواكِنَ حتى التَقَوا بطائفةٍ يقال لها حيُّ الهلبكسة، وهم نحو الألفي راكب على الهجن بحِرابٍ ومزاريقَ، في خلقٍ مِن المشاة عرايا الأبدان، فلم يثبتوا لدقِّ الطبول ورمي النشَّاب، وانهزموا بعد ما قُتِلَ منهم عدد كبير، وسار العسكَرُ إلى ناحية الأبواب، ثم مَضَوا إلى دنقلة، وعادوا إلى القاهرة تاسع جمادى الآخرة سنة سبع عشرة، وكانت غيبتهم ثمانيةَ أشهُرٍ."},{"id":2902,"title":"وفاة الشيخ ابن المرحل شيخ الشافعية .","date":["العام الهجري :716","الشهر القمري : ذي الحجة","العام الميلادي :1317"],"text":"هو الشيخُ أبو عبد الله محمد بن الشيخ المفتي زين الدين عمر بن مكي بن عبد الصمد المعروف بابن المرحل وبابن الوكيل شيخِ الشافعية في زمانه، وأشهَرُهم في وقته بكثرة الاشتغالِ والمطالعة والتحصيل والافتنان بالعلوم العديدة، وقد أجاد معرفةَ المذهب والأصلين، ولم يكن بالنحوِ بذاك القويِّ، وكان يقع منه اللَّحنُ الكثير، مع أنه قرأ منه المفَصَّل للزمخشري، وكانت له محفوظاتٌ كثيرة، ولد في شوال سنة 665، وسمِعَ الحديث على المشايخ، من ذلك مسند أحمد على ابن علان، والكتب الستَّة، وكان يتكَلَّم على الحديث بكلام مجموعٍ من علوم كثيرة، من الطبِّ والفلسفة وعلم الكلام، وليس ذلك بعلمٍ، وعلوم الأوائل، وكان يكثر من ذلك، وكان يقول الشعرَ جَيِّدًا، وله ديوانٌ مجموع مشتَمِلٌ على أشياء لطيفة، وكان له أصحابٌ يحسدونه ويحبُّونه، وآخرون يحسدونه ويُبغِضونه، وكانوا يتكَلَّمون فيه بأشياء ويرمونه بالعظائِمِ، وقد كان مسرفًا على نفسِه، قد ألقى جلبابَ الحياءِ فيما يتعاطاه من القاذورات والفواحش، وكان أحَدَ خصومِ شَيخِ اسلام ابن تيمية ينصِبُه العداوة ويناظِرُه في كثير من المحافل والمجالس، وكان يعترف للشيخ تقي الدينِ بالعلوم الباهرةِ ويُثني عليه، ولكِنَّه كان يجاحِفُ عن مذهبه وناحيته وهواه، وينافِحُ عن طائفته، وقد كان شيخُ الإسلام ابن تيمية يثني عليه وعلى علومِه وفضائِلِه ويشهَدُ له بالإسلامِ إذا قيل له عن أفعالِه وأعماله القبيحة، وكان يقول: \"كان مخَلِّطًا على نفسِه مُتَّبِعًا مراد الشيطان منه، يميلُ إلى الشهوة والمحاضرة، ولم يكنْ كما يقول فيه بعضُ أصحابه ممن يحسده ويتكَلَّم فيه هذا أو ما هو في معناه، وحين بلغ شيخَ الإسلام ابن تيمية وفاتُه قال: أحسن الله عزاء المسلمين فيك يا صدرَ الدينِ\" وقد درَّس بعِدَّة مدارس بمصر والشام، ودرس بدمشق بالشاميتين والعذراوية ودار الحديث الأشرفية، وولي في وقت الخطابة أيامًا يسيرة، ثم قام الخلقُ عليه وأخرجوها من يَدِه، ولم يَرْقَ مِنبَرَها، ثم خالط نائِبَ السلطنة الأفرم فجَرَت له أمور لا يمكِنُ ذِكرُها ولا يحسن من القبائحِ، ثم آل به الحالُ على أن عزم على الانتقالِ مِن دمشق إلى حلب لاستحواذه على قلب نائبِها، فأقام بها ودرَّس، ثم استقر به المنزل بمصر ودرس فيها بمشهد الحسين إلى أن توفي بها بكرة نهار الأربعاء رابع عشرين ذي الحجة بداره قريبا من جامع الحاكم، ودفن من يومه قريبا من الشيخ محمد بن أبي جمرة بتربة القاضي ناظر الجيش بالقرافة، ولما بلغت وفاته دمشق صلي عليه بجامعها صلاة الغائب, ورثاه جماعة منهم ابن غانم علاء الدين، والقجقازي والصفدي، لأنهم كانوا من عشرائه."},{"id":2903,"title":"هروب أمير مكة رميثة أبو نمي من أخيه حميضة الموالي للتتار .","date":["العام الهجري :717","العام الميلادي :1317"],"text":"رجع الشَّريفُ حميضة بن أبي نمي من العراق إلى مكة، ومعه نحو الخمسين من المغول، فمنعه أخوه رميثة من الدخولِ إلَّا بإذن السلطان الناصِرِ ابن قلاوون، فكتب بمَنْعِه من ذلك ما لم يَقدَم إلى مِصرَ، ثم قدم الشريفُ رميثة أمير مكة فارًّا من أخيه حميضة، وأنه ملك مكَّةَ وخطَبَ لأبي سعيد بن خربندا وأخذ أموالَ التجَّار، فرسم بتجريدِ الأمير صارم الدين أزبك الجرمكي، والأمير سيف الدين بهادر الإبراهيمي في ثلاثمائة فارس من أجنادِ الأمراء، مع الرَّكبِ إلى مكَّة."},{"id":2904,"title":"منع النصيرية في الشام من تلقين الغلمان عقائدهم الباطلة .","date":["العام الهجري :717","العام الميلادي :1317"],"text":"بعد قَتلِ مُدَّعي النُّصَيرية المهديَّة بساحل الشامِ رسم أن يُبنى بقرى النصيريَّة في كل قريةٍ مَسجِدٌ، وتُعمَل له أرضٌ لعمل مصالحه، وأن يُمنَعَ النُّصيريَّة من الخطابِ وهو أن الصبيَّ إذا بلغ الحُلُمَ عندهم عُمِلَت له وليمةٌ، فإذا اجتمع الناسُ وأكلوا وشَرِبوا حلَّفوا الصبيَّ أربعين يمينًا على كتمانِ ما يُودَعُ مِن المذهب، ثم يُعلِمونَه مذهَبَهم وهو إلهيَّةُ علي بن أبي طالب، وأن الخمر حلالٌ، وأن تناسخ الأرواحِ حَقٌّ، وأن العالمَ قديمٌ، والبعث بعد الموت باطل، وإنكار الجنَّة والنار، وأن الصَّلواتِ خَمسٌ، وهي إسماعيل وحسن وحسين ومحسن وفاطمة، ولا غُسلَ من جنابة، بل ذِكرُ هذه الخمسة يغني عن الغسل وعن الوضوء! وأن الصيام عبارة عن ثلاثين رجلًا وثلاثين امرأة ذَكَروهم في كتبهم، وأنَّ إلهَهم علي بن أبي طالب خلق السموات والأرض، وهو الربُّ، وأن محمدًا هو الحجاب، وسلمان هو الباب، إلى غير ذلك من عقائدهم الفاسدةِ المعروفة في كُتُبِهم وكُتُبِ غَيرِهم ممن كَشَف حقائقَهم!"},{"id":2905,"title":"ابن خربندا ملك التتار يطلب الصلح من الناصر بن قلاوون .","date":["العام الهجري :717","العام الميلادي :1317"],"text":"قَدِمَ كتاب المجد إسماعيل بن محمد بن ياقوت السلامي بإذعان المَلِك أبي سعيد بن خربندا، ووزيره خواجا علي شاه، والأمير جوبان، والأمراء أكابر المغول للصُّلحِ مع السلطان الناصِرِ ابنِ قلاوون، ومعه هديَّةٌ من جهةِ خواجا رشيد الدين، فجُهِّزَت إلى أبي سعيدٍ هدية جليلة من جملتها فرس وسيف وقرفل."},{"id":2906,"title":"دخول أهالي النوبة بالسودان في الإسلام  .","date":["العام الهجري :717","العام الميلادي :1317"],"text":"في حينَ كان التفاعُلُ بين الإسلام والنوبة يأخُذُ دَورَه في أسوان وجنوبها حيث انتشرت اللغةُ العربيَّةُ وكثُرَت المساجِدُ وكان ملوكُ النوبة يفرَحونَ للهَجَماتِ الصليبية على مصر، ثمَّ لما جاء عهد المماليك خضعت النوبة تحت حكمِهم، فكان أهلُها يؤدُّونَ الجِزيةَ السَّنَويَّةَ ولكِنَّهم كانوا يمتنعون أحيانًا، فحصلت بينهم حروبٌ، ثم لما كان كرنبس الذي حاول التمَرُّدَ على المماليك فأرسلوا جيشًا يرافقه أمير نوبي مسلم اسمه عبدالله برشنبو، فنصبوه على عرش النوبة سنة 716 وحاول كرنبس المفاوضةَ لتنصيب ابن أخيه المسلِم كنز الدولة شجاع الدين لكِنَّهم رفضوا فصارت النوبة في قبضة المسلِمِ، فكان من نتيجة ذلك انتشار الإسلام والعربية بين النوبيِّينَ، فبدأت تتحَوَّل الكنائِسُ إلى جوامِعَ وأشهرُها الكنيسةُ الكبرى في دنقلة، ثم تولى كنز الدولة, ولم يتسلم الحكمَ بَعدَه على النوبةِ أيُّ نَصرانيٍّ."},{"id":2907,"title":"ظهور رجل يدعي أنه محمد بن الحسن المهدي من فرقة النصيرية .","date":["العام الهجري :717","الشهر القمري : ذي القعدة","العام الميلادي :1318"],"text":"ظهر في سابع عشر ذي القعدة رجلٌ من أهل قرية قرطياوس من أعمالِ جبلة بساحل الشامِ زَعَم أنه محمد بن الحسن المهديُّ، وأنَّه بينما هو قائِمٌ يَحرُث إذ جاءه طائرٌ أبيضُ فنَقَب جنْبَه وأخرج روحَه وأدخل في جَسَدِه روحَ محمد بن الحسن، فاجتمع عليه من النصيريَّة القائلين بإلهيَّةِ عليِّ بن أبي طالب نحو الخمسة آلاف، وأمرهم بالسجودِ له فسجدوا، وأباح لهم الخَمرَ وتَرْك الصلوات وصَرَّحَ بأن لا إله إلا عليّ ولا حجاب إلا محمد، ورفع الراياتِ الحُمرَ، وشمعة كبيرة توقَدُ بالنَّهارِ ويَحمِلُها شابٌّ أمرَدُ زعم أنه إبراهيم بن أدهم، وأنه أحياه، وسمَّى أخاه المقداد بن الأسود الكنديَّ، وسمى آخَرَ جبريل، وصار يقول له: اطلع إليه وقُلْ كذا وكذا، ويشيرُ إلى الباري سبحانه وتعالى، وهو بزَعمِه علي بن أبي طالب، فيخرج المسمَّى جبريل ويغيب قليلًا، ثم يأتي ويقول: افعَلْ رأيك، ثم جمعَ هذا الدعِيُّ أصحابَه وهجم على المسلمينَ بجَبَلة يوم الجمعة العشرين منه، فقَتَل وسبى وأعلن بكُفرِه، وسبَّ أبا بكر وعمر رضي الله عنهما، فجرَّدَ إليه نائب طرابلس الأميرُ شهاب الدين قرطاي الأميرَ بدر الدين بيليك العثماني المنصوري على ألفِ فارسٍ فقاتلهم إلى أن قُتِلَ الدعيُّ، وكانت مُدَّةُ خروجه إلى قَتلِه خمسةُ أيام، فتمزقت جماعةُ هذا الثائر بجَبَلة، وكان قد ادَّعى أنَّ دينَ النُّصيريَّة حَقٌّ، وأن الملائكة تَنصُرُه!"},{"id":2908,"title":"جماعة من التتار تقتل تجارا قادمين إلى الشام مع أطفالهم .","date":["العام الهجري :717","الشهر القمري : ذي القعدة","العام الميلادي :1318"],"text":"اتَّفَق أنَّه في هذا الشهر تجمَّع جماعة من التجار بماردين وانضاف إليهم خلقٌ من الجفال من الغلا قاصدين بلاد الشام، حتى إذا كانوا بمرحلتين من رأس العين لحِقَهم ستون فارسًا من التتار فمالوا عليهم بالنشاب وقتلوهم عن آخرهم، ولم يبقَ منهم سوى صبيانِهم نحو سبعين صبيًّا، فقالوا من يقتل هؤلاء؟ فقال واحد منهم: أنا بشَرطِ أن تنَفِّلوني بمالٍ من الغنيمة، فقتلهم كلَّهم عن آخرهم، وكان جملةُ من قُتِل من التجَّار سِتَّمائة، ومن الجفلان ثلاثمائة، فإنَّا لله وإنا إليه راجعون، وردموا بهم خمسَ صهاريج هناك حتى امتلأت بهم رحمهم الله، ولم يسلَمْ من الجميع سوى رجل واحد تركماني، هرب وجاء إلى رأس العينِ فأخبَرَ الناس بما رأى وشاهد من هذا الأمر الفظيع المؤلمِ الوجيع، فاجتهد متسَلِّمُ ديار بكر سوياي في طلب أولئك التتر حتى أهلَكَهم عن آخرهم، ولم يبقِ منهم سوى رجلَينِ."},{"id":2909,"title":"انقراض دولة بني قطلمش ملوك قونية .","date":["العام الهجري :718","العام الميلادي :1318"],"text":"انقَرَضت دولةُ بني قطلمش ملوك قونية، وذلك أنَّ عِزَّ الدين اسيكاوس بن كيخسرو لما مات سنة 677 ترك ابنَه مسعودًا، فولَّاه أبغا بن هولاكو سيواس وغيرها، واستبَدَّ معين الدين سليمان برواناه على ركن الدين قلج أرسلان ابن كيخسرو بقيصرية ثم قتَلَه، ونصب ابنَه غياث الدين كيخسرو، فعزله أرغون بن أبغا، وولي ابن عمه مسعود بن كيكاوس، فأقام مسعودٌ حتى انحل أمره وافتقر، وبقي المُلكُ بالروم للتتر إلَّا ملك بني أرتنا، فإنه بقيَ بسيواس."},{"id":2910,"title":"قحط وفناء عظيم في بلاد الجزيرة والموصل .","date":["العام الهجري :718","الشهر القمري : محرم","العام الميلادي :1318"],"text":"وصَلَت الأخبارُ في المحَرَّم من بلاد الجزيرة وبلاد الشرق سنجار والموصل وماردين وتلك النواحي بغلاء عظيمٍ وفناء شديدٍ وقِلَّة الأمطار، والخوف من التتار، وعدمِ الأقواتِ وغلاءِ الأسعار، وقِلَّة النفقات، وزوال النِّعَم، وحلولِ النِّقَم، بحيث إنهم أكلوا ما وجدوه من الجماداتِ والحيواناتِ والميتاتِ، وباعوا حتى أولادَهم وأهاليهم، فبِيعَ الولد بخمسينَ دِرهمًا وأقل من ذلك، حتى إنَّ كثيرًا كانوا لا يشترون من أولادِ المسلمين، وكانت المرأةُ تُصَرِّحُ بأنها نصرانيَّة لِيُشتَرى منها ولَدُها لتنتَفِعَ بثَمَنِه ويحصُل له من يُطعِمُه فيَعيش، وتأمَن عليه من الهلاكِ، فإنا لله وإنا إليه راجعون، ووقعت أحوالٌ صعبة يطول ذِكرُها، وتنبو الأسماعُ عن وصفها، وقد ترَحَّلت منهم فرقة قريب الأربعمائة إلى ناحية مراغة فسقط عليهم ثلجٌ أهلَكَهم عن آخِرِهم، وصَحِبَت طائفةٌ منهم فِرقةً من التتار، فلما انتَهَوا إلى عقبة صعدها التتارُ ثم منعوهم أن يصعدوها لئلا يتكَلَّفوا بهم فماتوا عن آخِرِهم، فلا حولَ ولا قوَّةَ إلا بالله العزيزِ الحكيمِ."},{"id":2911,"title":"وقعة مع الأعراب ببرقة بسبب الزكاة .","date":["العام الهجري :719","العام الميلادي :1319"],"text":"جهز الأميرُ أيتمش المحمدي على عسكرٍ إلى برقة، ومعه فايد وسليمان أمراءُ العُربان لجباية زكاةِ الأغنام على العادة، فسار في ثلاثمائةِ فارسٍ من أجناد الحلقة ومعه من الأمراءِ عِدَّةٌ، وذلك في آخِرِ يومٍ من المحرَّم، ونزل بالإسكندرية، ثم سار أيتمش يريدُ بلاد جعفر بن عمر من برقة، ومسافتُها من الإسكندرية على الجادة نحو شهرين، فدَلَّه بعض العرب على طريقٍ مسافتُها ثلاثة عشَرَ يَومًا يُفضي به إلى القَومِ مِن غيرِ أن يعلموا به، وطَلَب في نظير دَلالتِه على هذه الطريقِ مائةَ دينار وإقطاعاتٍ مِن السلطانِ بعد عودِ العسكرِ إلى القاهرة، فعَجَّل له أيتمش المائة، والتزم له بالإقطاعِ مِن السلطان، وكتب له بعشرةِ أرادِبَ قمحًا لعياله، وأركبه ناقةً، وكتم ذلك كلَّه عن العسكَرِ مِن الأمراء والأجناد والعُربان، وسار بمسيرِه، حتى إذا مضت ثلاثَ عشرة ليلة أشرف على منازِلِ جَعفرِ بنِ عمر وعُرْبانه، فدُهِشوا لرؤيةِ العَسكَرِ، وأرسل إليهم أيتمش بسليمان وفايد يدعوهم إلى الطاعةِ، فأجابوا مع رسُلِهم: إنَّا على الطاعةِ، ولكن ما سبب قدومُ هذا العسكرِ على غفلةٍ مِن غير أن يتقَدَّمَ لنا به علمٌ؟ فقال لهم أيتمش: حتى يحضُرَ الأمير جعفر ويسمَعَ مَرسومَ السلطان، وأعادهم، وتَقَدَّم أيتمش إلى جميع من معه ألَّا ينزِل أحدٌ عن فرسه طولَ ليلتِه، فباتوا على ظهورِ الخيل، فلما كان الصباحُ حضر أخو جعفر ليسمَعَ المرسوم، فنهَرَه أيتمش وقال له ولمن معه: ارجعوا إلى جعفرٍ فإن كان طائعًا فلْيَحضُر، وإلَّا فلْيُعَرِّفْني، وبعث معه ثلاثةً مِن مُقَدَّمي الحلقة، فامتنع جعفرٌ من الحضور، فللحالِ لَبِسَ العسكر السلاحَ وتَرَتَّب، وأفرد سليمان وفايد، بمن معهما من العسكرِ ناحية، واستعد جعفرٌ أيضًا وجمع قومَه وحمل بهم على العَسكَر، فرموهم بالنشَّاب فلم يبالُوا به، ودقُّوا العسكرَ برماحِهم، وصَرَعوا الأميرَ شُجاعَ الدين غرلوا الجوكندار بعدما جَرَحوه ثلات جراحات، فتداركه أصحابُه وأركبوه، وحملوا على العرب فكانت بين الفريقينِ تِسعَ عشرة وقعة آخِرُها انهزم العربُ إلى بيوتهم، فقاتلهم العسكرُ عند البيوتِ ساعةً وهزموهم إليها، وكانت تلك البيوتُ في غابةِ قَصَب، فكفَّ العسكَرُ عن الدخول إليهم، ومنعهم أيتمش عن التعرُّضِ إلى البيوتِ وحماها، وأباح لهم ما عداها، فامتَدَّت الأيدي، وأُخِذَت من الجمالِ والأغنامِ ما لا ينحَصِرُ عدده، وبات العسكَرُ محترسين، وقد أَسَروا نحوَ السِّتِّمائة رجل سوى من قُتِل، فلما أصبح الصبحُ منَّ أيتمش على الأسرى وأطلَقَهم، وتفَقَّد العسكرَ فوجد فيه اثني عشر جريحًا، ولم يُقتَل غيرُ جندي واحد، فرحل عائدًا عن البيوتِ بأنعامٍ تَسُدُّ الفضاء، وبِيعَ ما معهم فيما بينهم الرأسُ الغَنَمُ بدِرهمٍ، والجَمَلُ ما بين عشرين إلى ثلاثين درهمًا، وسار أيتمش ستةَ أيام في الطريق التي سلكها والعسكَر بالسِّلاح، خشيةً مِن عَودِ العرب إليهم، وبعث أيتمش بالبشارةِ إلى السلطان الناصر محمد بن قلاوون، فبعث الأميرَ سيفَ الدين ألجاي الساقي لتلَقِّي العسكر بالإسكندرية وإخراج الخُمُس مِمَّا معهم للسلطان، وتَفرِقة ما بَقِيَ فيهم، فخُصَّ الجنديُّ ما بين أربعةِ جمالٍ وخمسةٍ، ومِنَ الغَنَم ما بين العشرينَ إلى الثلاثين، وحَضَروا إلى القاهرة، فخَلَع السلطان على أيتمش، وبعد حضورهم بأسبوع قدم جعفرُ بنُ عمر إلى القاهرة، ونزل عند الأمير بكتمر الساقي مُستجيرًا، فأكرمه ودخل به على السلطانِ، فاعترف بالخطأِ، وسأل العفوَ، وأن يقَرِّرَ عليه ما يقومُ به، فقَبِلَ السلطانُ قَولَه وعفا عنه، وخلع عليه ومضى، وصار يحمِلُ القودَ في كلِّ سَنَةٍ."},{"id":2912,"title":"وقعة عظيمة بين ملك التتار أبي سعيد بن خربندا ونائبه جوبان .","date":["العام الهجري :719","العام الميلادي :1319"],"text":"كانت وقعةٌ عظيمةٌ بين التتار بسَبَبِ أنَّ مَلِكَهم أبا سعيد بن خربندا كان قد ضاق ذرعًا بنائبه الأمير جوبان وعجَزَ عن مَسكِه، فانتدب له جماعةً من الأمراء عن أمرِه، منهم أبو يحيى خال أبيه، ودقماق وقرشي وغيرُهم من أكابر الدولة، وأرادوا كبسَ جوبان فهرب وجاء إلى السلطانِ الناصر محمد بن قلاوون, فأنهى إليه ما كان منهم، وفي صُحبتِه الوزير علي شاه، ولم يزل بالسلطانِ حتى رضي عن جوبان وأمَدَّه بجيشٍ كثيف، ورَكِبَ السلطان معه أيضًا والتقوا مع أولئك فكسروهم وأسروهم، وتحَكَّم فيهم جوبان فقَتَل منهم إلى آخِرِ هذه السنة نحوًا من أربعين أميرًا."},{"id":2913,"title":"وقعة ألبيرة في غرناطة .","date":["العام الهجري :719","العام الميلادي :1319"],"text":"حشد الفِرنجُ وأقبلوا يريدونَ استئصالَ المسلمين من الأندلس في غرناطةَ في عدَدٍ لا يُحصى، فيه خمسة وعشرونَ ملكًا بزعامة ألفونسو الحادي عشر ملك قشتالة، فقَلِقَ المسلمون بغرناطة ومَلِكُها الغالب بالله أبو الوليد إسماعيل بن فرج بن نصر من بني الأحمر، واستنجدوا بالمريني مَلِك فاس فلم يُنجِدْهم، فلجؤوا إلى الله وحارَبوهم في الألبيرة وهم نحو ألف وخمسمائة فارس وأربعة آلاف راجل، فقتلوا الفرنجَ بأجمَعِهم، وأقلُّ ما قيل إنَّه قُتِلَ منهم خمسون ألفًا، وأكثَرُ ما قيل ثمانون ألفًا، ولم يُقتَلْ من المسلمين سوى ثلاثةَ عشر فارسًا، وغَنِمَ المسلمون ما لا يدخُلُ تحت حصر، وسُلِخَ الملكُ دون بتروا وحُشِيَ قُطنًا، وعُلِّقَ على بابِ غرناطة، فطَلَب الفرنجُ الهُدنةَ فعُقِدَت، وبَقِيَ دون بتروا مُعَلَّقًا عدَّةَ سنينَ."},{"id":2914,"title":"السلطان الناصر يرسل الفداوية لقتل قراسنقر الذي هرب إلى التتار .","date":["العام الهجري :720","العام الميلادي :1320"],"text":"بعث السُّلطانُ الناصر محمد بن قلاوون ثلاثينَ فداويًّا من أهل قلعةِ مصياف للفَتكِ بالأمير قراسنقر، فعندما وصلوا إلى تبريز نمَّ بعضُهم لقراسنقر عليهم، فتَتَبَّعَهم وقبضَ على جماعة منهم، وقَتَلهم، وانفرد به بعضُهم وقد ركب من الأردو، فقفز عليه فلم يتَمَكَّنْ منه، وقُتِلَ، واشتَهَر في الأردو خبَرُ الفداوية، وأنهم حضروا لقَتلِ السلطان أبي سعيد وجوبان والوزير علي شاه وقراسنقر وأمراء المغول، فاحتَرَسوا على أنفسهم، وقبضوا عدَّة فداوية، فتحيل بعضُهم وعَمِلَ حمَّالًا، وتبع قراسنقر ليقفِزَ عليه فلم يلحَقْه، ووقع على كفلِ الفَرَسِ فقُتِل، فاحتجب أبو سعيد بالخركاه- بالخيمة- أحد عشر يومًا خوفًا على نفسِه، وطلب المجد إسماعيل، وأنكر عليه جوبان وأخرق به، وقال له: أنت كلَّ قليل تُحضِرُ إلينا هديةً، وتريد منا أن نكون متَّفِقينَ مع صاحب مصر، لتمكُرَ بنا حتى تقتُلَنا الفداوية والإسماعيليَّة، وهدَّدَه أنه يقتُلُه شَرَّ قِتلةٍ، ورسم عليه، فقام معه الوزيرُ علي شاه حتى أفرج عنه، ثم قَدِمَ الخبر من بغداد بأن بعض الإسماعيلية قفز على النائبِ بها ومعه سكينٌ فلم يتمكَّنْ منه، ووقعت الضربةُ في أحد أمراء المغول، وأن الإسماعيليَّ فَرَّ، فلما أدركه الطلبُ قَتَل نفسَه، فتنَكَّر جوبان لذلك، وجهَّزَ المجد السلامي إلى مصر ليكشِفَ الخبر، وبعثوا في أثره رسولًا بهديَّةٍ."},{"id":2915,"title":"نهاية الدولة الخلجية في الهند وقيام دولة بني تغلق .","date":["العام الهجري :720","العام الميلادي :1320"],"text":"قام ناصِرُ الدين خسروخان بقتل قُطبِ الدين الخلجي لَمَّا خاف منه، فقام هو بأمر الدولةِ، وكان يميل إلى الهنادك؛ لذا فإن المُسلِمينَ كَرِهوه وتمنَّوا الخلاص منه، ثم بايعه الأمراءُ إلَّا تغلق شاه في السند فإنه أعلن الخلافَ، وسار إليه وقَتَله أيضًا فلم يَدُمْ في ملكه سوى أربعة أشهر، فكان خسروخان هذا آخِرَ ملوك الخلجيين، وكان تغلق هذا استعان بكشلوخان أمير الملتان ضِدَّ الجيش الذي أرسله خسروخان ضده فانهزم جيشُ خسروخان وتسَلَّم تغلق المُلكَ وتلقَّبَ بغياث الدين، فكان أول ملوك دولة آل تغلق."},{"id":2916,"title":"أبو سعيد ملك التتار يمنع الخمور وبيوت الفواحش في العراق .","date":["العام الهجري :720","العام الميلادي :1320"],"text":"قَدِمَ الخبَرُ بأنَّ أبا سعيد بن خربندا مَلِك التتار بالعراق أراق الخُمورَ في سائر مملكته، وأبطل منها بيوتَ الفواحش، وأبعد أربابَ الملاهي، وأغلق الخاناتِ، وأبطل المكوسَ التي تُجبى من التجارة الواردة إليهم من البلاد، وهَدَّم كنائسَ بالقرب من توريز، ورفع شهادةَ الإسلام، ونشر العَدَل، وعَمَر المساجِدَ والجوامع، وقَتَل من وَجَد عنده الخمرَ بعد إراقته، فكتب السلطانُ الناصر محمد بن قلاوون لسائِرِ نواب الشام بإبطالِ ضَمانِ الخمَّارات وإراقةِ الخُمور، وغَلقِ الحانات، واستتابةِ أهلِ الفواحِشِ، فعُمِلَ ذلك في سائر مدن البلاد الشاميَّةِ."},{"id":2917,"title":"الصلح بين السلطان الناصر وبين أبي سعيد ملك المغول في العراق .","date":["العام الهجري :720","العام الميلادي :1320"],"text":"قَدِمَ المجدُ السلامي على البريدِ مِن عند الملك أبي سعيد بن خربندا في طلب الصُّلحِ، فخرج القاضي كريم الدين الكبير إلى لقائه، وصَعِدَ به إلى القلعة، فأخبر المجد السلامي برغبةِ جوبان وأعيان دولة أبي سعيد في الصلحِ، وأنَّ الهديَّةَ تَصِلُ مع الرسل، فكَتَب إلى نائبي حلب ودمشق بتلقِّي الرسُلِ وإكرامِهم، فقدم البريدُ بأن سليمان بن مهنا عارض الرُّسُل، وأخذ جميعَ ما معهم من الهَديَّة، وقد خرج عن الطاعةِ لإخراجِ أبيه مهنَّا من البلاد وإقامةِ غيرِه في إمرة العرب، ثمَّ قَدِمَت الرسل بعد ذلك بالكُتُب، وفيها طلب الصلحِ بشُروطٍ: منها ألا تدخُلَ الفداوية إليهم، وأنَّ مَن حضر من مصر إليهم لا يُطلَبُ، ومن حضر منهم إلى مصرَ لا يعود إليهم إلَّا برضاه، وألَّا يُبعَث إليهم بغارة من عَرَب ولا تُركمان، وأن تكون الطريقُ بين المملكتين مفتوحةً تسير تجارُ كُلِّ مملكة إلى الأخرى، وأن يسيرَ الركبُ من العراق إلى الحجاز في كلِّ عامٍ بمَحمَلٍ ومعه سنجق فيه اسمُ صاحِبِ مِصرَ مع سنجق أبي سعيد ليتجَمَّلَ بالسنجق السلطانيِّ، وألا يُطلَب الأميرُ قراسنقر، فجمع السلطانُ الأمراءَ واستشارهم في ذلك بعدما قرأ عليهم الكتاب، فاتفق الرأي على إمضاءِ الصلحِ بهذه الشروط، وجُهِّزَت الهدايا لأبي سعيدٍ, وفيها خِلعةٌ أطلس باولي زركش، وقباءٌ تتَرِيٌّ وقرقلات وغير ذلك، ممَّا بلغت قيمته أربعين ألف دينار، وأعيد الرسُلُ بالجوابِ، وفيه ألَّا يُمكَّنَ عَرَبُ آل عيسى من الدخول إلى العراق، فإنَّ العَسكَرَ واصِلٌ لقتالهم، وسافر السلامي على البريد يُبَشِّرُ بعود الرسُلِ بالهَديَّة."},{"id":2918,"title":"وقعة عظيمة ببلاد المغرب بين المسلمين والفرنجة وانتصار المسلمين .","date":["العام الهجري :720","العام الميلادي :1320"],"text":"كانت وقعةٌ عظيمة ببلاد المغرب بين المسلمين والفرنجِ، فنصر الله المسلمينَ على أعدائِهم، فقتلوا منهم خمسينَ ألفًا وأَسَروا خمسةَ آلاف، وكان في جملةِ القَتلى آلاف من ملوك الفرنج، وغنموا شيئًا كثيًرا من الأموال، يقالُ: كان من جملة ما غنموا سبعون قنطارًا من الذهب والفضة، وإنما كان جيشُ الإسلام يومئذ ألفين وخمسَمائة فارس غير الرماة، ولم يُقتَلْ منهم سوى أحد عشر قتيلًا، وهذا من غريبِ ما وقع وعجيبِ ما سُمِع!"},{"id":2919,"title":"الإغارة على بلاد الأرمن وتل حمدان وسيس .","date":["العام الهجري :720","الشهر القمري : جمادى الآخرة","العام الميلادي :1320"],"text":"اجتمعت جُيوشُ السلطان الناصر بأرض حلَب نحوًا من عشرين ألفًا، عليهم كلِّهم نائبُ حلب الطنبغا وفيهم نائب طرابلس شهاب الدين قرطبة، فدخلوا بلاد الأرمن من إسكندرونة ففتحوا الثَّغرَ ثمَّ تل حمدان ثم خاضوا نهر جاهان فغَرِقَ منهم جماعة، ثم سلَّم اللهُ من وصلوا إلى سيس فحاصروها وضَيَّقوا على أهلها وأحرَقوا دارَ المَلِك التي في البلد، وقَطَعوا أشجارَ البساتين وساقوا الأبقارَ والجواميسَ والأغنام وكذلك فَعَلوا بطرسوس، وخَرَّبوا الضياعَ والأماكِنَ وأحرقوا الزروعَ ثمَّ رَجَعوا فخاضوا نهر جاهان, فلم يغرق منهم أحد، وأخرجوا بعد رجوعِهم مهنا وأولادَه من بلادهم وساقوا خَلفَه إلى عانة وحديثه، ثم بلغ الجيوشَ موتُ صاحب سيس وقيامُ ولده من بعده، فشَنُّوا الغارات على بلاده وتابعوها وغَنِموا وأسَروا إلَّا في المرة الرابعة فإنه قُتِلَ منهم جماعة."},{"id":2920,"title":"حبس شيخ الإسلام تقي الدين ابن تيمية في القلعة .","date":["العام الهجري :720","الشهر القمري : رجب","العام الميلادي :1320"],"text":"في يومِ الخميس الثاني والعشرين من رجب عُقِدَ مجلس بدار السعادة للشَّيخِ تقي الدين ابن تيمية بحضرة نائب السَّلطنةِ، وحضر فيه القضاةُ والمُفتُونَ من المذاهب، وحضر الشيخُ وعاتبوه على العَودِ إلى الإفتاء بمسألةِ الطلاقِ، ثمَّ حُبِسَ في القلعةِ فبَقِيَ فيها خمسة أشهر وثمانية عشر يومًا، ثمَّ ورد مرسوم من السلطانِ بإخراجه يوم الاثنين يوم عاشوراء من سنةِ إحدى وعشرين، وكان الشيخُ قد عُقِدَ له أكثَرُ من مجلسٍ ومُنِعَ من الإفتاء في هذه المسألة في الطلاقِ، وهو أنَّ مَن حلف بالطلاقِ غَيرَ ناوٍ للطلاقِ فإنَّه لا يَقَعُ، ومسألة طلاقِ الثلاثِ في مجلسٍ واحدٍ تُعتبَرُ طلقةً واحدة، وقد أُصدِرَ مرسومٌ من السلطان بمَنعِه من الفتوى بهذه المسألةِ، وكان قد امتنع أوَّلًا، ثم في هذه السنة حصل اعتقالُه."},{"id":2921,"title":"وفاة شمس الدين محمد الهمذاني السكاكيني متشيع .","date":["العام الهجري :721","الشهر القمري : صفر","العام الميلادي :1321"],"text":"هو الشيخُ شمس الدين محمد بن أبي بكر بن أبي القاسم الهمذاني ثم الدمشقي السكاكيني المتشيِّع، ولِدَ سنة 635 بدمشق، وطلب الحديثَ وتأدَّبَ وسَمِعَ وهو شابٌّ من إسماعيل بن العراقي والرشيد بن مسلمة، ومكي بن علان في آخرين، وتلا بالسبع، ومن مسموعاته مُسنَدُ أنس للحنيني على إسماعيل عن السلفي، ومن فوائد أبي النرسي بالسند عنه روى عنه البرزالي والذهبي وآخرون، من آخرهم أبو بكر بن المحب، وبالإجازة برهانُ الدين التنوخي. رُبِّي يتيمًا فأُقعِدَ في صناعة السكاكين عند شيخ رافضيٍّ فأفسد عقيدتَه, ثم أخذ عن جماعةٍ مِن الإمامية وله نظمٌ وفضائِلُ وردٌّ على العفيف التلمساني في الاتحاد، وأَمَّ بِقَريةِ جسرينَ مُدَّةً، وأقام بالمدينةِ النبويَّة عند أميرها منصور ابن جماز مدةً طويلةً، ولم يُحفَظْ له سبٌّ في الصحابةِ، بل له نظم في فضائِلِهم إلَّا أنه كان يناظر على القَدَرِ ويُنكِرُ الجَبْرَ وعنده تعبُّدٌ وسَعةُ عِلمٍ. قال الذهبي: \"كان حلوَ المجالسة ذكيًّا عالِمًا فيه اعتزالٌ، وينطوي على دينٍ وإسلام وتعبُّدٍ، سَمِعْنا منه وكان صديقًا لأبي، وكان ينكر الجبرَ ويناظرُ على القَدَر\" قال الصفدي: \"وترَفَّضَ به أناسٌ من أهل القرى؛ لذا قال تقيُّ الدينِ ابنُ تيميَّة: \"هو ممَّن يتسَنَّنُ به الشيعيُّ، ويتشَيَّعُ به السُّنيُّ!\" وكان يجتَمِعُ به شيخُ الإسلام كثيرًا، وقيل إنَّه رجع في آخِرِ عُمُرِه ونسخ صحيحَ البخاري، وجد بعد موته بمدة في سنه 750 بخطٍّ يشبه خَطَّه كتابٌ يسمَّى الطرائف في معرفة الطوائف يتضمَّنُ الطعن على دين الإسلام وأورد فيه أحاديثَ مُشكِلة وتكلَّم على متونِها بكلامِ عارفٍ بما يقولُ إلَّا أنَّ وضعَ الكتابِ يدُلُّ على زندقةٍ فيه، وقال في آخره: وكتبه مصنِّفُه عبد الحميد بن داود المصري، وهذا الاسمُ لا وجود له، وشَهِدَ جماعة من أهل دمشق أنَّه خطُّه فأخذه تقي الدين السبكي عنده وقطَّعَه في اللَّيلِ وغَسَلَه بالماء، ونَسَب إليه عمادُ الدين ابن كثير الأبياتَ التي أوَّلُها: يا معشر الإسلام ذمي دينكم... الأبيات. مات شمس الدين في صفر في هذه السنة. وابنُه حسن نشأ في الرفضِ، فثبت عليه ذلك عند القاضي شرف الدين المالكي بدمشق وثبت عليه أنَّه يكَفِّرُ الشيخين وقَذَف ابنَتَيهما ونَسَب جبريل إلى الغلط في الرِّسالة، فحكم بزندقته وبِضَرب عُنُقِه فضُرِبَت سنة 744."},{"id":2922,"title":"هدم العامة كنائس النصارى بمصر وحرق بعضها .","date":["العام الهجري :721","الشهر القمري : ربيع الآخر","العام الميلادي :1321"],"text":"ثارت العامَّةُ يدًا واحدةً في يوم الجمعة تاسِعَ ربيع الآخر، وهَدَموا كنيستينِ مُتقابلتَينِ بالزهري، وكنيسة بستان السكري، وتعرف بالكنيسة الحمراء، وبعض كنيستين بمصرَ، ففي هذا اليوم الجمعة تاسع ربيع الآخر بطل العَمَلُ وقتَ الصلاةِ لاشتغالِ الأمراء بالصلاةِ، اجتمع من الغلمانِ والعامَّة طائفةٌ كبيرة، وصرخوا صوتًا واحدًا: اللهُ أكبر، ووقعوا في أركانِ الكنيسة بالمساحي والفُؤوسِ حتى صارت كُومًا، ووقع مَن فيها من النصارى، وانتهب العامَّةُ ما كان بها، والتفَتوا إلى كنيسة الحمراء المجاورة لها، وكانت من أعظَمِ كنائس النصارى، وفيها مالٌ كبير، وعِدَّةٌ من النَّصارى ما بين رجالٍ ونساءٍ مُتَرَهِّبات، فصعدت العامَّةُ فوقها، وفتحوا أبوابَها ونهبوا أموالَها وخُمورَها، وانتقلوا إلى كنيسةِ بومنا بجوار السبع سقايات، وكانت مَعبدًا جليلًا من معابد النصارى، فكَسَروا بابَها ونهبوا ما فيها، وقَتَلوا منها جماعة، وسَبَوا بنات كانوا بها تزيد عِدَّتُهن على ستين بكرًا، فما انقضت الصلاة حتى ماجت الأرضُ، فلما خرج الناسُ من الجامع رأوا غبارًا ودخانَ الحريق قد ارتفعا إلى السَّماءِ، وما في العامَّةِ إلَّا من بيده بنتٌ قد سباها أو جَرَّة خمرٍ أو ثوب أو شيء من النهب، فدُهِشوا وظنُّوا أنها الساعة قد قامت، وقَدِمَ مملوك والي مصر وأخبر بأن عامَّتَها قد تجمَّعَت لهدم كنيسة المعلَّقة حيث مسكَنُ البطرقِ وأموال النصارى، ويَطلُبُ نجدة، فلِشِدَّةِ ما نزل بالسلطان من الغَضَبِ هَمَّ أن يركَبَ بنَفسِه، ثم أردف أيدغمش بأربعةِ أمراء ساروا إلى مصر، وبعث بيبرس الحاجِبَ، وألماس الحاجب إلى موضع الحفر، وبعث طينالَ إلى القاهرة، ليضعوا السيف فيمن وَجَدوه، فقامت القاهرةُ ومصر على ساق، وفَرَّت النهَّابة، فلم تُدرِك الأمراءُ منهم إلا من غلب على نفسِه بالسُّكرِ مِن الخمر، وأدرك الأميرُ أيدغمش والي مصر وقد هزمته العامَّةُ من زقاق المعلقة، وأنكَوا مماليكَه بالرَّميِ عليهم، ولم يبقَ إلَّا أن يحرقوا أبوابَ الكنيسة، فجَرَّد هو ومن معه السيوفَ ليفتِكَ بهم، فرأى عالَمًا عظيمًا لا يحصيهم إلَّا خالِقُهم، فكفَّ عنهم خوفَ اتِّساعِ الخَرقِ، ونادى مَن وقَفَ فَدَمُه حلالٌ، فخافت العامَّةُ أيضًا وتفَرَّقوا، ووقف أيدغمش يحرُسُ المعَلَّقة إلى أن أُذِّنَ بالعصر، فصلى بجامع عمرو بن العاص، وعيَّنَ خمسينَ حارِسًا للمَبيتِ مع الوالي على بابِ الكنيسة، وعاد. وقيل كأنَّما نودي في إقليم مصر بهدمِ الكنائس، وأوَّل ما وقع الصوتُ بجامع قلعة الجبل, وذلك أنَّه لما انقضت صلاةُ الجمعة صرخ رجلٌ مُولَهٌ في وسط الجامع: \"اهدِموا الكنيسةَ التي في القلعةِ\"، وخرج في صراخه عن الحَدِّ واضطرب، فتعجَّب السلطانُ والأمراء منه، ونُدِبَ نقيب الجيش والحاجب لتفتيش سائر بيوت القلعة، فوجدوا كنيسةً في خرائب التتر قد أُخفِيَت، فهدموها، وما هو إلَّا أن فرغوا من هَدمِها والسلطانُ يتعَجَّبُ إذ وقع الصراخُ تحت القلعة، وبلغه هدمُ العامَّة للكنائس، وطُلِبَ الرجُلُ المُولَهُ فلم يُوجَدْ، وعندما خرج الناسُ من صلاة الجمعة بالجامع الأزهر من القاهرة رأوا العامةَ في هرج عظيم، ومعهم الأخشابُ والصُّلبان والثياب وغيرها، وهم يقولون: \"السلطانُ نادى بخراب الكنائس\"، فظنُّوا الأمر كذلك، وكان قد خُرِّبَ من كنائس القاهرة سوى كنيستي حارة الروم وحاره زويلة وكنيسة بالبندقانيين كنائس كثيرة، ثم تبيَّنَ أنَّ ذلك كان من العامة بغير أمر السلطان، فلما كان يومُ الأحد الحادي عشر سقط الطائِرُ من الإسكندرية بأنَّه لَمَّا كان الناس في صلاة الجمعة تجمَّع العامَّةُ وصاحوا هُدِمَت الكنائس، فركب الأميرُ بدر الدين المحسني متولي الثغر بعد الصلاةِ لِيُدرِك الكنائس، فإذا بها قد صارت كُومًا، وكانت عِدَّتُها أربع كنائس، ووقعت بطاقةٌ من والي البحيرة بأنَّ العامَّةَ هَدَمت كنيستين في مدينة دمنهور، والنَّاسُ في صلاة الجمعة، ثمَّ ورد مملوكُ والي قوص في يوم الجمعة السابع عشر، وأخبر بأنه لما كان يوم الجمعة هدم العامَّةُ سِتَّ كنائس بقوص في نحو نصف ساعة، وتواترت الأخبار من الوجه القبلي والوجه البحري بهدم الكنائس وقت صلاةِ الجمعة، فكثُرَ التعَجُّبُ من وقوع هذا الاتِّفاق في ساعةٍ واحدة بسائر الأقاليم، وكان الذي هُدِمَ في هذه الساعة من الكنائِسِ سِتُّونَ كَنيسةً!!"},{"id":2923,"title":"حرائق هائلة بالقاهرة من قبل النصارى ردا على هدم كنائسهم .","date":["العام الهجري :721","الشهر القمري : جمادى الأولى","العام الميلادي :1321"],"text":"كان عَقيبَ هَدمِ الكنائِسِ وقوعُ الحريق بالقاهرة ومصر، فابتدأ يومَ السبت خامس عشر جمادى الأولى، وتواتَرَ إلى آخره، بدأ الحريقُ في رَبعٍ من أوقاف المارستان المنصوري، واشتد الأمرُ، والأمراءُ تُطفِئُه إلى عصر يوم الأحد، فوقع الصوتُ قبل المغرب بالحريقِ في حارة الديلم بزُقاق العريسة، قريب من دار كريم الدين الكبير، ودخل الليلُ واشتد هبوب الرياح، فسَرَت النار في عِدَّة أماكن، وبعث كريمُ الدين بولده علم الدين عبد الله إلى السلطان يُعَرِّفُه، فبعث عِدَّةً من الأمراء والمماليك لإطفائِه خوفًا على الحواصِلِ السلطانية ثم تفاقم الأمرُ، واحتاج أقسنقر شاد العمائر إلى جمع سائرِ السائقينَ والأمراء، ونزلت الحُجَّاب وغيرهم، والنار تَعظُمُ طُولَ نهار الأحد، وباتوا على ذلك، وأصبحوا يوم الاثنينِ والنار تُتلِفُ ما تمُرُّ به، والهَدٌّ واقع في الدور التي تجاور الحريق خشيةً مِن تعَلُّقِ النار فيها وسَرَيانها في جميع دور القاهرة، فلما كانت ليلة الثلاثاء خرج أمر الحريقِ عن القُدرة البَشَرية، وخرجت ريحٌ عاصِفةٌ ألقت النخيلَ وغَرَّقت المراكب، ونَشَرت النار، فنزل النائب بسائر الأمراء وجميعِ مَن في القلعة وجميعِ أهل القاهرة، ونُقِل الماءُ على جمال الأمراء، ولحِقَه الأمير بكتمر الساقي وأُخرِجَت جمالُ القرى السلطانية، ومُنِعَت أبواب القاهرة أن يخرج منها سقاء، ونُقِلَت المياه من المدارس والحمَّامات والآبار، وجُمِعَت سائر البنائين والنجارين، فهُدَّت الدور من أسفلِها والنار تحرِقُ في سقوفها، وعَمَل الأمراء الألوف وعِدَّتُهم أربعة وعشرون أميرًا بأنفُسِهم في إطفاء الحريقِ، بحيث صار من باب زويلة إلى حارة الروم بحرًا، ثم خَمِدَت النار وعاد الأمراء، فوقع الصياحُ في ليلة الأربعاء بربع الملك الظاهِرِ خارج باب زويلة وبقيسارية الفقراء، وهبَّت الرياح مع ذلك، فرَكِبَ الحُجَّاب والوالي وعملوا في إطفائها إلى بعد الظهر من يوم الأربعاء وهدموا دورًا كثيرةً مِمَّا حوله، فما كاد أن يفرغ العَمَلُ من إطفاء النار حتى وقعت النارُ في بيت الأمير سلار بخط القصرين، فأقبلوا إليه وإذا بالنار ابتدأت من أعلى البادهنج- المنفذ الذي يجيء منه الريح- وكان ارتفاعُه من الأرض زيادة على مائة ذراع- بذراع العمل- ورأوا فيه نِفطًا قد عُمِلَ فيه فتيلة كبيرة، فما زالوا بالنار حتى أُطفِئَت، من غير أن يكون لها أثرٌ كبير، ونُودِيَ بأن يُعمَلَ بجانِبِ كُلِّ حانوت بالقاهرةِ ومصرَ زيرُ ودن ملآن ماء، وكذلك بسائر الحارات والأزقَّة، فلما كانت ليلة الخميس: وقع الحريق بحارة الروم وبخارج القاهرة، وتمادى الحالُ كذلك، ولا تخلو ساعة من وقوعِ الحريق بموضع من القاهرة ومصر، وامتنع والي القاهرةِ والأمير بيبرس الحاجب من النَّومِ، فشاع بين الناس أنَّ الحريق من جهة النصارى لَمَّا أنكاهم هدم الكنائس ونهبها، وصارت النيرانُ توجَدُ تارة في منابر الجوامِعِ وتارة في حيطان المدارسِ والمساجد، ووُجِدَت النار بالمدرسة المنصورية، فزاد قلقُ النَّاسِ وكَثُر خوفهم، وزاد استعدادُهم بادِّخار الآلات المملوءة ماء في أسطُحِ الدور وغيرها، وأكثر ما كانت النارُ توجد في العلو، فتقع في زروب الأسطح والبادهنجانات، ويُوجَدُ النِّفطُ قد لُفَّ في الخِرَق المبَلَّلة بالزيت والقطران، فلما كانت ليلةُ الجمعة الحادي عشر جمادى الأولى قُبِضَ على راهِبَينِ خرجا من المدرسة الكهاريَّة بالقاهرة، وقد أضرما النارَ بها، وأُحضِرا إلى الأمير علم الدين سنجر الخازن والي القاهرة، فشَمَّ منهما رائحة الكبريت والزيت، فأحضرهما من الغدِ إلى السلطان، فأمر بعقوبتِهما حتى يعترفا، فلما نزل الأميرُ علم الدين بهما وجد العامَّةَ قد قبضت على نصرانيٍّ مِن داخل باب جامِعِ الظاهر بالحُسَينية، ومعه كعكة خِرَق بها نفط وقطران، وقد وضعها بجانِبِ المنبر، فلما فاح الدخانُ أنكروه, ووجدوا النصرانيَّ وهو خارج والأثَرُ في يديه، فعُوقِبَ قبل صاحبيه، فاعترف النصرانيُّ أنَّ جماعة من النصارى قد اجتمعوا وعَمِلوا النفط، وفَرَّقوه على جماعة ليَدورُوا به على المواضع، ثم عاقَبَ الأمير علم الدين الراهبينِ، فأقرا أنَّهما من دير البغل، وأنهما هما اللذانِ أحرقا سائر الأماكن التي تقَدَّمَ ذِكرُها، وذلك أنَّه لَمَّا مر بالكنائس ما كان، حَنِقَ النصارى من ذلك وأقاموا النياحةَ عليها، واتَّفَقوا على نكاية المسلمين، وعملوا النفطَ وحَشَوه بالفتائِلِ وعَمِلوها في سهامٍ ورَموا بها، فكانت الفتيلة إذا خرجت من السَّهمِ تقَعُ على مسافة مائة ذراع، فلما أنفقوا ذلك فَرَّقوه في جماعة، فصاروا يدورون في القاهرة بالليل، وحيث وجدوا فرصة انتهزوها وألقَوا الفتيلةَ، حتى كان ما كان، فطالع الأميرُ علم الدين السلطانَ بذلك، واتَّفَق وصول كريم الدين الكبير ناظر الخاص من الإسكندريَّة، فعَرَّفه السلطان ما وقع من القَبضِ على النصارى، فقال البطرق: هؤلاء سُفَهاءُ قد فعلوا كما فَعَل سُفَهاؤُكم، والحُكمُ للسلطان، وأقام البطركُ ساعةً، وقام فرَكِبَ بغلةً كان قد رُسِمَ له منذ أيام بركوبِها، فشَقَّ ذلك على الناس، وهَمُّوا به لولا الخوف ممن حوله من المماليك، فلما رَكِب كريم الدين من الغد صاحت العامَّةُ به: \"ما يحِلُّ لك يا قاضي تحامي للنصارى، وقد أخربوا بيوت المسلمين، وتُركِبُهم البغال، فانتكى كريمُ الدين منهم نكايةً بالغةً، وأخذَ يُهَوِّنُ من أمر النصارى الممسوكين ويَذكُرُ أنَّهم سفهاء، وعرف السلطان ما كان من أمْرِ البُطرُقِ، وأنه اعتُنيَ به، فأمر السلطانُ الواليَ بعقوبة النصارى، فأقروا على أربعة عشر راهبًا بدير البغل، فقُبِضَ عليهم من الدير، وعُمِلَت حفيرةٌ كبيرة بشارع الصليبة، وأُحرِقَ فيها أربعة منهم في يوم الجمعة، وقد اجتمع من الناس عالمٌ عظيم، فاشتدت العامَّةُ عند ذلك على النصارى، وأهانوهم وسَلَبوهم ثيابَهم، وألقَوهم من الدوابِّ إلى الأرض، وركب السلطانُ إلى الميدان يوم السبت الثاني عشر من جمادى الآخر، وقد اجتمع عالمٌ عظيم، وصاحوا: \"نصر اللهُ الإسلامَ، انصر دينَ محمَّد بن عبد الله\"، فلما استقَرَّ السلطان بالميدان حتى أَحضَرَ له الخازنُ والي القاهرة نصرانيَّينِ قد قُبِضَ عليهما، فأُحرِقا خارجَ الميدان، وخرج كريم الدين الكبير من الميدان وعليه التشريفُ، فصاحت به العامة: \"كم تحامي للنصارى\"، وسَبُّوه ورموه بالحجارة، فعاد إلى الميدان، فشَقَّ ذلك على السلطان، واستشار الأمراءَ في أمر العامة، فأشار عليه الأميرُ جمال الدين أقوش نائِبُ الكرك بعزل الكُتَّاب النَّصارى، فإنَّ النَّاسَ قد أبغضوهم، فلم يُرضِه ذلك، وتقَدَّمَ السلطان إلى ألماس الحاجب أن يَخرُجَ في أربعة أمراء ويضَعَ السَّيفَ في العامَّةِ حتى ينتهيَ إلى باب زويلة، ويمُرَّ إلى باب النصرِ وهو كذلك ولا يرفَع السَّيفَ عن أحد، وأمرَ والي القاهرة أن يتوجَّهَ إلى بابِ اللوق والبحر، ويَقبِضَ من وجده، ويحمِلَهم إلى القلعة، وعَيَّن لذلك مماليكَ تَخرُجُ من الميدان، فبادر كريمُ الدين وسأل السلطانَ العَفوَ، فقَبِلَ شَفاعتَه، ورسم بالقبضِ على العامَّةِ مِن غَيرِ قَتلِهم، وكان الخبَرُ قد طار، ففَرَّت العامَّةُ حتى الغلمان، وصار الأميرُ لا يجِدُ مَن يُركِبُه، وانتشر ذلك، فغُلِّقَت جميعُ أسواق القاهرة، فما وصل الأمر إلى باب زويلة حتى لم يجِدوا أحدًا، وشَقُّوا القاهرةَ إلى باب النصر، فكانت ساعةً لم يمُرَّ بالناس أعظَمُ منها، ومَرَّ الوالي إلى باب اللوق وبولاق وباب البحر، وقبض كثيرًا من الكلابزة- من يتولَّى تربية الكلاب وبَيعَها- والنواتية –الملَّاحين- وأراذل العامَّة، بحيث صار كلُّ من رآه أخَذَه، وجفَل الناسُ مِن الخوف، وعَدوا في المراكب إلى بر الجيزة، فلما عاد السلطانُ إلى القلعة لم يجد أحدًا في طريقه، وأحضر إليه الوالي بمن قبض عليه وهم نحو المائتين، فرسم أن يُصلَبوا، وأفرد جماعةً للشَّنقِ وجماعةً للتوسيطِ، وجماعةً لقطع الأيدي، فصاحوا: \"يا خوند- يا سيد- ما يحِلُّ لك، فما نحن الغُرَماء\"، وتباكوا فَرَّقَ لهم بكتمر الساقي، وقام معه الأمراءُ، وما زالوا بالسلطان حتى رسم بصَلبِ جماعةٍ منهم على الخَشَبِ من باب زويلة إلى سوقِ الخَيلِ، وأن يُعَلَّقوا بأيديهم، فأصبحوا يومَ الأحدِ صفًّا واحدًا من بابِ زويلة إلى سوقِ الخيل تحت القلعة، فتوجَّعَ لهم الناس، وكان منهم كثيرٌ مِن بياض الناس، ولم تُفتَح القاهرة، وخاف كريم الدين على نفسِه، ولم يَسلُكْ من باب زويلة، وصَعِدَ القلعة من خارج السور، فإذا السلطانُ قد قَدَّم الكلابزة وأخَذَ في قطع أيديهم، فكشف كريم الدين رأسَه وقَبَّل الأرض، وباس رِجلَ السُّلطانِ، وسأله العفو، فأجابه السلطانُ بمساعدة الأمير بكتمر، وأمَرَ بهم فقُيِّدوا وأُخرِجوا للعَمَلِ في الحفير بالجيزة، ومات ممَّن قُطِعَ يَدَه رَجُلان، وأُمِرَ بحَطِّ من عُلِّقَ على الخَشَب، فللحالِ وقع الصوتُ بحريقِ أماكِنَ بجوار جامع ابن طولون، وبوقوعِ الحريق في القلعةِ، وفي بيت الأحمدي بحارة بهاء الدين من القاهرة، وبفُندق طرنطاي خارج باب البحر، فدُهِشَ السلطان، وكان هذا الفندق برسم تجارِ الزيت الوارد من الشام، فعَمَّت النار كلَّ ما فيه حتى العُمُد الرُّخام، وكانت ستة عشر عمودًا، طولُ كل منها ستة أذرع، ودوره نحو ذراعين، فصارت كلُّها جيرًا، وقُبِضَ فيه على ثلاثة نصارى معهم فتائِلُ النفط، اعتَرَفوا أنهم فعلوا ذلك، فخاف السلطانُ الفتنةَ ورجع إلى مداراتِهم، وتقَدَّم إلى الحاجِبِ بأن يخرُجَ وينادي: \"من وجد نصرانيًّا فدَمُه ومالُه حلالٌ\"، فلما سمعوا النداءَ صرخوا صوتًا واحدًا: \"نصرك الله يا ناصِرَ دين الإسلام\"، فارتجَّت الأرض، ونودِيَ عَقيبَ ذلك بالقاهرة ومصر: \"من وُجِدَ من النصارى بعمامةٍ بَيضاءَ حَلَّ دمه، ومن وُجِدَ من النصارى راكبًا باستواءٍ حَلَّ دمه\" وكُتِبَ مرسومٌ بلُبس النصارى العمائِمَ الزرق، وألَّا يركبوا فَرَسًا ولا بغلًا، وأن يركبوا الحميرَ عَرضًا، ولا يدخلوا الحَمَّام إلَّا بجَرَس في أعناقهم، ولا يتزَيَّوا بزيِّ المسلمين هم ونساؤُهم وأولادهم، ورُسِمَ للأمراء بإخراج النصارى من دواوينِهم ومن دواوين السلطان، وكُتِبَ بذلك إلى سائر الأعمال، وغُلِّقَت الكنائس والأديرة، وتجرَّأت العامة على النصارى، بحيث إذا وجدوهم ضربوهم وعَرَّوهم ثيابَهم، فلم يتجاسَرْ نصرانيٌّ أن يخرُجَ من بيته، ولم يُتحَدَّثْ في أمرِ اليهودِ، فكان النصرانيُّ إذا طرأ له أمرٌ يتزيَّا بزيِّ اليهودِ، ويلبَس عمامة صفراءَ يكتريها من يهوديٍّ ليخرُجَ في حاجتِه! واحتاج عِدَّةٌ من النصارى إلى إظهارِهم الإسلام، فأسلم السني ابن ست بهجة في يوم الثلاثاء سابع عشر جمادى الآخرة، وخُلِعَ عليه، وأسلم كثيرٌ منهم، واعترف بعضُهم على راهب بدير الخندق أنه كان يُنفِقُ المالَ في عَمَل النفطِ للحريق ومعه أربعة، فأُخِذوا وسُمِّروا."},{"id":2924,"title":"وفاة الملك المؤيد هزبر الدين التركماني ملك اليمن وتولي ابنه بعده .","date":["العام الهجري :721","الشهر القمري : ذي الحجة","العام الميلادي :1322"],"text":"هو المَلِكُ المؤيَّد هزبر الدين داودُ بن الملك المظفَّر يوسف بن عمر بن رسول التركماني الأصل اليمني المولِد والمنشأ والوفاة صاحِبُ ممالك اليمن، تسلطنَ بعد أخيه في المحرَّم سنة 696 فملَك نيفًا وعشرينَ سنة، وكان قبل سلطنته تفَقَّه وحَفِظَ كفايةَ المتحَفِّظ، ومُقَدِّمة ابن بابشاذ، وبحث التنبيه وطالعَ وفضل وسمع الحديث، وجمعَ الكتب النفيسةَ في سَلطنَتِه، حتى قيل إن خزانةَ كُتُبِه اشتملت على مائة ألف مجلَّد، وكان مشكور السيرة محبًّا لأهل الخير وكانت وفاتُه في ذي الحجة، وتولى بعده ابنه الملك المجاهد علي، واضطربت ممالِكُ اليمن بعد موتِه، وتولَّى عِدَّةُ سلاطينَ."},{"id":2925,"title":"فتح إياس من بلاد الأرمن .","date":["العام الهجري :722","الشهر القمري : ربيع الأول","العام الميلادي :1322"],"text":"في ربيع الأول تكامل فتح إياس (من بلاد الأرمن على ساحل البحرِ) ومعامَلتها وانتزاعُها من أيدي الأرمن، وأُخِذَ البرج الأطلس- وهو أحدُ ثلاثة أبراج وهي الأطلس والشمعة والإياس- بينه وبينها في البحر رميةٌ ونصف، فأخذه المسلمونَ بتوفيق الله وخَرَّبوه، وكانت أبوابُه مَطليَّةً بالحديد والرصاص، وعَرضُ سُورِه ثلاثة عشر ذراعًا، وغنم المسلمونَ غنائِمَ كثيرةً جدًّا، وحاصروا كوارَه فقوي عليهم الحَرُّ والذباب، فرسم السلطانُ بعَودِهم، فحرقوا ما كان معهم من المجانيقِ وأخذوا حديدَها وأقبلوا سالمين غانمينَ، وكان معهم خلقٌ كثيرٌ من المتطوعين."},{"id":2926,"title":"الإغارة على بلاد سيس .","date":["العام الهجري :722","الشهر القمري : جمادى الأولى","العام الميلادي :1322"],"text":"في مُستَهَلِّ جمادى الأولى قَدِمَ البريد بأن العسكَرَ أغار على بلاد سيس، وأخرَبَ وغَنِمَ وقتل جماعة، وأنَّ أوشين متمَلِّكَ سيس هلك، وقام مِن بعدِه ابنُه ليفون، وله من العُمرِ نحو اثنتي عشرة سنة، وأن العساكِرَ نازلت إياسَ وأخذوها عَنوةً بعد حصار، وقتلوا أهلَها وخَرَّبوها، وعادوا على الأرمن فغَنِموا وأسَروا منهم كثيرًا، وتوجَّهوا عائدين، فقَدِمَ الأمير جمال الدين أقوش بالعسكرِ إلى القاهرة في السابع عشر جمادى الآخرة، وخُلِع عليه."},{"id":2927,"title":"وفاة قاضي القضاة نجم الدين ابن صصرى الشافعي .","date":["العام الهجري :723","الشهر القمري : ربيع الأول","العام الميلادي :1323"],"text":"هو الإمامُ العلَّامة الحافِظُ قاضي القضاة نجمُ الدين أبو العباس أحمد بن محمد بن سالم بن أبي المواهب، الربعي الثعلبي الدمشقي الشافعي، الشهيرُ بابن صصرى قاضي القُضاة بالشام، وُلِدَ في ذي القعدة سنة 655، ووالدتُه هي شاه ست بنت أبي الغنائم المسلم بن محمد بن المسلم بن علان القيسية الدمشقية، ذكرها الذهبي في معجم الشيوخ الكبير. كان في ابتداء أمرِه كتب في الإنشاء، وكان له نظمٌ ونثرٌ ومُشاركة في فنونٍ كثيرة، فصيحَ العبارة، قادرًا على الحفظ، يحفظُ أربعة دروس في اليوم، سمِعَ ابن صصرى الحديثَ واشتغل وحَصَّل وكتَبَ عن القاضي شمس الدين بن خَلِّكان وفياتِ الأعيان، وسَمِعَها عليه، وتفقَّه بالشيخ تاج الدين الفزاري، وعلى أخيه شرف الدين في النَّحو، وكان له يدٌ في الإنشاء وحُسن العبارة. درَّس بالعادلية الصغيرة سنةَ ثنتين وثمانين، وبالأمينية سنة تسعين، وبالغزالية سنة أربع وتسعين، وتولى قضاء العساكر في دولة العادل كتبغا، ثم تولَّى قضاء الشام سنة ثنتين وسبعمائة، بعد ابنِ جماعة حين طُلِبَ لقضاء مصر بعد ابن دقيق العيد، ثم أضيف إليه مشيخةُ الشيوخ مع تدريس العادلية والغزالية والأتابكية، في يوم الثلاثاء سابِعَ شعبان عَزَل نجم الدين بن صصرى نفسه عن الحُكمِ بسبب كلامٍ سمعه من الشيخ كمال الدين بن الزملكاني. كان نجم الدين ابن صصرى من خصومِ شيخ الإسلام ابن تيمية, ففي الثاني عشر رجب سنة 698 قرأ المِزِّي فصلًا من كتاب أفعال العباد للبُخاري في الجامع، فسَمِعَه بعض الشافعية فغضِبَ، وقالوا: نحن المقصودون بهذا ورفعوه إلى القاضي الشافعي فأمر بحبسه، فبلغ ابن تيمية فتوجَّهَ إلى الحبس فأخرجه بيده، فبلغ القاضي ابن صصرى فطلع إلى القلعة فوافاه ابن تيميَّةَ فتشاجرا بحضرة النائِبِ، واشتطَّ ابن تيمية على القاضي لِكَونِ نائبه جلال الدين آذى أصحابَه في غَيبة النائب، فأمر النائب من ينادي أنَّ من تكلَّمَ في العقائد فُعِلَ كذا به، وقصد بذلك تسكينَ الفتنة. وفي خامس رمضان بطلب القاضي والشيخ وأن يرسلوا بصورةِ ما جرى للقاضي نجم الدين ابن صصرى، ثم وصل مملوك النائب وأخبر أن الجاشنكير والقاضي المالكي قد قاما في الإنكارِ على الشيخ ابن تيمية، وأنَّ الأمرَ اشتَدَّ بمصر على الحنابلة، حتى صفع بعضهم، ثم توجه القاضي ابن صصرى وشيخ الإسلام إلى القاهرة ومعهما جماعةٌ فوصلا في العشر الأخير من رمضان، وعُقِدَ مجلس في ثالث عشر منه بعد صلاة الجمعة، فادعى على ابن تيميَّةَ عند المالكي، فقال: هذا عدوِّي ولم يجِبْ عن الدعوى، فكرر عليه فأصَرَّ، فحكم المالكيُّ بحبسِه، فأقيم من المجلسِ وحُبِسَ في برجٍ، ثم بلغ المالكي أن الناس يترددون إليه، فقال: يجب التضييقُ عليه إنْ لم يُقتَل وإلَّا فقد ثبت كفرُه، فنقلوه ليلة عيد الفطر إلى الجبِّ، وعاد القاضي ابن صصرى الشافعي إلى ولايتِه، ونودي بدمشق من اعتقد عقيدةَ ابن تيمية حَلَّ دَمُه ومالُه خصوصًا الحنابلة، فنودي بذلك وقرئ المرسوم. توفي ابن صصرى فجأةً ببستانه بالسَّهمِ ليلة الخميس سادس عشر ربيع الأول عن ثمان وستين سنة وصُلِّيَ عليه بالجامع المظفري، وحضر جنازتَه نائب السلطنة والقضاة والأمراء والأعيان، وكانت جنازتُه حافلةً ودُفِنَ بتربتهم عند الركنية."},{"id":2928,"title":"الإغارة على بلاد النوبة .","date":["العام الهجري :723","الشهر القمري : ذي الحجة","العام الميلادي :1323"],"text":"في أوَّلِ ذي الحِجَّة خرج الأمير علاء الدين علي بن قراسنقر، والأمير سيف الدين أيدمر الكبكي، والأمير طقصباي المرتبة فديته بقوص، وخمسمائة من أجناد الحلقة إلى بلاد النوبة، ومعهم كرنبس، فانتهوا إلى دنقلة، وكان قد تغَلَّب كنزُ الدولة عليها، ونَزَع كرنبس، ففَرَّ كَنزُ الدولة منهم، وجلس كرنبس على سريرِ مُلكِه وعادوا، فحارب كنزُ الدولة كرنبس بعد عود العسكر، ومَلَك منه البلادَ."},{"id":2929,"title":"فتنة وقتل وقحط بأصبهان وأمراض وموت بالشام ومصر والصعيد .","date":["العام الهجري :724","العام الميلادي :1323"],"text":"وقعت فِتنةٌ بأصبهان قُتِلَ بسَببِها ألوفٌ من أهلها، واستمَرَّت الحربُ بين أهلها شهورًا، وقَحَطَت بلادُ الشرق، فقَدِمَت طوائف إلى بلاد الشام، وكان الجراد قد أتلف زُروعَها، فجهز الأمراءُ مِن مِصرَ الغِلالَ الكثيرةَ في البحر إلى بيروت وطرابلس، فكان ما حُمِلَ من جهة السلطان الناصر محمد بن قلاوون والأمراء نحو عشرين ألف أردب سوى ما حمله التجَّار، فانحَطَّ السِّعرُ وكُتِبَ بإبطال مُكسِ الغَلَّة بالشام، وفَشَت الأمراضُ في الناس بالشام ومصر والصعيد، وكثر الموت السريعُ، ومَرِضَ السلطانُ ثمانية عشر يومًا وعُوفِيَ."},{"id":2930,"title":"وفاة الشيخ البكري الشافعي .","date":["العام الهجري :724","الشهر القمري : ربيع الآخر","العام الميلادي :1324"],"text":"هو نور الدين أبو الحسن علي بن يعقوب بن جبريل البكري المصري الشافعيُّ، له تصانيفُ، وقرأ مسند الشافعي على وزيرة بنت المنجا، ثمَّ إنه أقام بمصر، وقد كان في جملةِ خُصومِ شَيخِ الإسلام ابن تيمية، أراد بعضُ رجال الدولة قَتْلَه فهرب واختفى عند ابن تيميَّة لَمَّا كان مقيمًا بمصر، وما مثالُه إلَّا مثالُ ساقيةٍ ضعيفةٍ كَدِرة لاطمت بحرًا عظيمًا صافيًا، أو رملةٍ أرادت زوال جبل، وقد أضحك العقلاءَ عليه، وقد أراد السلطانُ قَتْلَه فشَفِعَ فيه بعض الأمراء، ثم أنكر مرَّةً شيئًا على الدولةِ فنُفِيَ من القاهرة إلى بلدةٍ يقال لها: ديروط، فكان بها حتى توفِّيَ يوم الاثنين سابع ربيع الآخر، ودفن بالقرافة، وكانت جنازتُه مشهورةً غيرَ مشهودة، وكان شيخُه ينكِرُ عليه إنكارَه على ابن تيمية، ويقولُ له أنت لا تحسِنُ أن تتكَلَّم، ولشيخ الإسلام الردُّ المشهور عليه المعروف باسم الردِّ على البكري أو الاستغاثةِ."},{"id":2931,"title":"وفاة الباجربقي المنحرف صاحب الملحمة الباجربقية .","date":["العام الهجري :724","الشهر القمري : ربيع الآخر","العام الميلادي :1324"],"text":"هو الزاهِدُ محمد بن عبد الرحيم بن عمر الجزري، ابن المفتي الكبير جمال الدين الباجربقي، نسبةً إلى باجربق قرية بين النهرين، هو رأسُ الفرقة الضالة المعروفة بالباجربقيَّة، كان والده فاضلًا عالِمًا، انتقل إلى دمشق وجلس للإفادةِ والإفتاء. نشأ ابنُه محمد هذا بدمشق، فاشتغل أولًا بالفقه، ثم عدل إلى السلوكِ فتزهَّدَ وحصل له حالٌ وكَشفٌ، وبدأ ينحَرِفُ حتى أنكر وجود الله تعالى، ثم انقطع فصَحِبَه جماعةٌ من الرذالة، وهَوَّن لهم أمرَ الشَّرائِعِ وأراهم بوارِقَ شيطانيَّة، وكان له قوةُ تأثير، وقد ألَّفَ كتابه المعروف بالملحمة الباجربقيَّة ونُقل عنه انتقاصُه للأنبياء صلواتُ الله عليهم، وتَرْكُ الشرائع، فحكم عليه القاضي الزواوي المالكي بإراقةِ دَمِه، فهرب إلى الشرقِ، ثمَّ أثبت أنَّ بينه وبين الشهود عداوةً، فحُقِنَ دَمُه بذلك فرجع إلى دمشق وبَقِيَ في القابون إلى أن توفي فيها ليلة الأربعاء سادس عشر ربيع الآخر، ودفن بالقرب من مغارة الدم بسفح قاسيون في قبة في أعلى ذيل الجبل تحت المغارة، وله من العمر ستون سنةً."},{"id":2932,"title":"استيلاء أبي الوليد ملك غرناطة على مدينتي بياسة ومرتش الإسبانية .","date":["العام الهجري :724","الشهر القمري : رجب","العام الميلادي :1324"],"text":"بعد أن انتصر ملِكُ غرناطة أبو الوليد إسماعيل في موقعة ألبيرة قَوِيَ شأنُه أكثَرَ، فتعاقَبَت غزواتُه في أراضي النصارى وممتلكاتِهم، فزحف على مدينةِ بياسة الحصينة فحاصَرَها حتى استسلَمَت، ثمَّ استولى عَنوةً على مدينة مرتش وغَنِمَ منها الكثيرَ."},{"id":2933,"title":"هدم الكنائس التي جددت في منية بني خصيب (محافظة المنيا بمصر) .","date":["العام الهجري :724","الشهر القمري : رجب","العام الميلادي :1324"],"text":"توجَّهَ الأمير أرغون النائب إلى منية بني خصيب، فشكا أهلُها من مُباشريهم، فلم يسمَعْ لهم وأمر بضَربِهم، فرَجَموه بالحجارةِ وأنكَوا في مماليكِه وغِلمانِه، فرَكِبَ عليهم أرغون ليفتِكَ بهم، ففَرُّوا من عند الوطاق خارج البلد إلى داخِلِ البلد، فأخذ مماليكُه من عمائِمِ الهاربين ما يزيدُ على ثلاثمائة وستين عمامة زرقاء من عمائِمِ النصارى، فلما استكثَرَ ذلك قيل له إنَّ بها كثيرًا من النصارى، ولهم خَمسُ كنائس، فهَدَمَها في ساعةٍ واحدة، ورسَمَ ألَّا يُستخدَمَ نَصرانيٌّ في ديوانِه، وكان النصارى قد جَدَّدوا عمارة ما خُرِّبَ من الكنائس بالصعيد، فهُدِّمَت أيضًا."},{"id":2934,"title":"اجتماع عدة رسل في مصر عند السلطان .","date":["العام الهجري :725","العام الميلادي :1324"],"text":"اتفق في هذا العام أن اجتمع للسُّلطانِ الناصر محمد بن قلاوون بمصرَ مِن رُسُلِ الملوك ما لم يجتَمِعْ مثلُهم في دولة المماليك التركية، وهم: رسلُ صاحِبِ اليَمَنِ، ورسُلُ صاحبِ إسطنبول، ورسل الأشكري، ورسل متملِّك سيس، ورسُلُ أبي سعيد بن خربندا التتري، ورسُلُ ماردين، ورسُلُ ابن قرمان، ورُسُل ملك النوبة، وكُلُّهم يبذلونَ الطاعةَ للسُّلطانِ!"},{"id":2935,"title":"غرق بلاد مصر والعراق بسبب أمطار غزيرة .","date":["العام الهجري :725","الشهر القمري : جمادى الأولى","العام الميلادي :1325"],"text":"وقع بمصرَ مَطَرٌ لم يُسمَعْ بمِثلِه بحيث زاد النيلُ بسببه أربعَ أصابع، وتغيَّرَ أيامًا، وكذلك زادت دجلةُ ببغداد حتى غَرِقَت ما حول بغداد وانحصر الناسُ بها ستَّةَ أيام لم تُفتَحْ أبوابها، وبَقِيَت مثل السفينة في وسط البحر، وغَرِقَ خَلقٌ كثير من الفلَّاحين وغيرِهم، وتَلِفَ للنَّاسِ ما لا يعلَمُه إلا الله، وودَّعَ أهلُ البلد بعضُهم بعضًا، ولجؤوا إلى الله تعالى وحَمَلوا المصاحِفَ على رؤوسهم في شِدَّةِ الشوق في أنفُسِهم حتى القُضاة والأعيان، وكان وقتًا عجيبًا، ثم لطَفَ الله بهم فغِيضَ الماءُ وتناقَصَ، وتراجَعَ النَّاسُ إلى ما كانوا عليه من أمورِهم الجائرةِ وغير الجائرةِ، وذكر بعضُهم أنَّه غَرِقَ بالجانب الغربي نحوٌ من ستة آلاف وستمائة بيت."},{"id":2936,"title":"السلطان الناصر يرسل جيشا إلى اليمن لاسترداده .","date":["العام الهجري :725","الشهر القمري : جمادى الآخرة","العام الميلادي :1325"],"text":"سأل المَلِكُ المجاهِدُ صاحِبُ اليمن إنجادَه بعسكَرٍ من مصر، وأكثَرَ من ترغيب السلطان الناصر محمد بن قلاوون في المالِ الذي باليمن، وكان قدومُ رُسُلِه في مستَهَلِّ صفر، فرسم السلطانُ بتجهيز العسكر صحبة الأمير ركن الدين بيبرس الحاجب، وهو مُقَدَّم العسكر، فسار إلى مكَّةَ، فوصل في السادس والعشرين من جمادى الأولى، ودخلها وأقامَ بها حتى قَدِمَت المراكِبُ بالغلال وغيرِها من مصر إلى جُدَّة، وتقَدَّم الخادِمُ كافور الشبيلي خادِمُ الملك المجاهد إلى زَبيد لِيُعلِمَ مولاه بالعساكر، وكتب الأميرُ ركن الدين بيبرس بن الحاجب، وهو مُقَدَّم العسكر إلى أهل حلي بني يعقوب بالأمان، وأن يجلِبوا البضائِعَ للعسكَرِ، ورحل العسكَرُ في خامس جمادى الآخرة من مكَّة، ومعه الشَّريفُ عطفة والشريف عقيل، وتأخَّر الشريف رميثة، فوصل العسكَرُ إلى حلي بني يعقوب في اثني عشر يومًا، فتلقَّاهم أهلُها، ودُهِشوا لرؤية العساكر، فنودي فيهم بالأمانِ، ورحل العسكَرُ بعد ثلاثة أيام في العشرين منه، فقَدِمَت الأخبار باجتماعِ رأي أهل زبيد على الدخولِ في طاعة المَلِك المجاهد خوفًا من مَعَرَّة قدوم العسكر المصري، وأنهم ثاروا بالمتمَلِّك عليهم وهو المَلِك الظاهِر، ونهبوا أموالَه ففَرَّ عنهم، وكتَبوا إلى المجاهد بذلك، فقَوِيَ ونزل من قلعة تعز يريدُ زبيدَ، فكتب أمراءُ العسكر المصري إليه، وهم قُربَ حدود اليمن، بأن يكون على أُهْبةِ اللقاء، ونزل العسكَرُ على زبيد، ووافاهم المجاهِدُ بجُندِه، فسَخِرَ منهم الناسُ من أجل أنَّهم عراةٌ، وسلاحُهم الجريدُ والخَشَبُ، وسيوفُهم مشدودةٌ على أذرِعَتِهم، ويقادُ للأميرِ فَرَسٌ واحِدٌ مُجَلَّل، وعلى رأسِ المجاهِدِ عِصابةٌ مُلَوَّنةٌ فوقَ العمامة، وعندما عاين المجاهِدُ العساكِرَ المصريَّةَ وهي لابسةٌ آلة الحَربِ رُعِبَ، ومضى العسكَرُ صَفَّين والأمراءُ في الوسط حتى قَرُبوا منه، فألقى المجاهِدُ نَفسَه ومن معه إلى الأرضِ، وترجل له أيضًا الأمراء وأكرموه وأركبوه في الوَسَطِ، وساروا إلى المخَيَّم، وألبسوه تشريفًا سلطانيًّا وقُرِئَ كتاب السلطان، فقَبَّلوا بأجمعِهم الأرض، وقالوا سمعًا وطاعةً، وكتب الأميرُ بيبرس الحاجِبُ لممالك اليمَنِ بالحضور، فحضروا، ولم يُجَهِّز المَلِكُ المجاهد للعسكَرِ شيئًا من الإقامات، وعَنَّفه الأمير بيبرس على ذلك، فاعتذر بخرابِ البلاد، وكَتَب لهم على البلاد بغنمٍ وأذرة، وسار المجاهِدُ إلى تعز لتجهيز الإقاماتِ، ومعه الأميرانِ سيف الدين ططر العفيفي السلاح الدار وسيف الدين قجمار في مائتي فارس، وتأخَّر العسكر بزبيد، وعادت قُصَّاد الأمراء بغير شيءٍ فرحل العسكَرُ من زبيد في نصف رجب يريدون تعز، فتلقَّاهم المجاهد، ونزلوا خارجَ البلد، وشكَوا ما هم فيه من قِلَّة الإقامات، فوعد بخير، وكتب الأمراءُ إلى الملك الظاهر المقيم بدملوة، وبعَثوا إليه الشريفَ عطفة أميرَ مكَّةَ وعِزَّ الدين الكوندكي، وكتب إليه المجاهِدُ أيضًا يحُثُّه على الطاعة، وأقام العسكَرُ في جَهدٍ، فأغاروا على الضياع، وأخذوا ما قَدَروا عليه، واتُّهِم أن ذلك بمواطأة المجاهِد خوفًا من العسكَرِ أن يَملِكَ منه البلاد، ثمَّ إنَّ أهل جبل صبر قطَعوا الماء عن العسكر، وتخَطَّفوا الجمال والغِلمان، وزاد أمرُهم إلى أن ركب العسكَرُ في طَلَبِهم، فامتنعوا بالجَبَلِ، ورموا بالمقاليعِ على العسكر، فرَمَوهم بالنشاب، وأتاهم المجاهِدُ فخَذَّلَهم عن الصُّعودِ إلى الجبل، فلم يعبؤوا بكلامه، ونازلوا الجبَلَ يَومَهم، ففُقِدَ من العسكر ثمانيةٌ من الغلمان، وبات العسكَرُ تحته، فبلغ الأميرَ بيبرس أن المجاهدَ قَرَّر مع أصحابه بأن العسكرَ إذا صَعِدَ الجَبَل يُضرِمونَ النار في الوطاقِ وينهبون ما فيه، فبادر بيبرس وقَبَض على بهاء الدين بهادر الصقري وأخذ موجودَه، ووسَّطَه قطعتينِ وعَلَّقه على الطريق، ففَرِحَ أهل تعز بقَتلِه، وكان بهادر قد تغَلَّب على زبيد، وتسَمَّى بالسلطنة، وتلَقَّب بالملك الكامل، وظَلَّ متسَلِّطًا عليها، حتى طرده أهلُها عند قدوم العسكر، وقَدِمَ الشريف عطفة والكوندكي من عند الملك الظاهر صاحب دملوة، وأَخبَرا بأنَّه في طاعة السلطان الناصر ابن قلاوون، وطلب بيبرس من المجاهِدِ ما وَعَد به السلطان، فأجاب بأنه لا قُدرةَ له إلا بما في دملوة فأشهَدَ عليه بيبرس قضاةَ تَعز بذلك، وأنه أذِنَ للعسكر في العود، لخرابِ البلاد وعَجْزِه عمَّا يقومُ به للسُّلطانِ، وأنَّه امتَنَع بقلعة تعز، ورحل العسكَرُ إلى حلي بني يعقوب، فقَدِمَها في تاسع شعبان، ورحلوا منها أوَّلَ رمضان إلى مكَّة، فدخلوها في حادي عشره بعد مشقةٍ زائدة، وساروا من مكَّةَ يوم عيد الفطرِ."},{"id":2937,"title":"وفاة السلطان إسماعيل بن الأحمر ملك دولة بني نصر في الأندلس .","date":["العام الهجري :725","الشهر القمري : رجب","العام الميلادي :1325"],"text":"هو إسماعيلُ بن فرج بن إسماعيل بن يوسف بن نصر بن الأحمر، أبو الوليد، السلطانُ الغالِبُ بالله أميرُ المؤمنينَ، خامِسُ ملوك دولة بني نصر بن الأحمر بغرناطة في الأندلس، كانت لأبيه ولايةُ مالقة وسبتة، فتولَّاهما من بعده. وكان الملك بغرناطة أبو الجيوش نصرُ بن محمد الفقيه، وهو موصوف بالضَّعفِ، فثار عليه إسماعيلُ وزحف من مالقة إلى غرناطة سنة 713 فبويع فيها، وخرج نصرٌ إلى وادي آش. وأراد بطرس الأوَّلُ بن ألفونس الحادي عشر أحد ملوك الإسبان أن يستفيدَ مِن فرصة الفتنة في غرناطة فاقتحم الحصونَ يُريدُها، فكانت بين جيشِه وجَيشِ إسماعيل وقائعُ هائلة انتهت سنة 717 بمَقتَلِ بطرس. وفي سنة 724 تحَرَّك إسماعيل للجِهادِ، فامتَلَك بعضَ الحصون، وعاد إلى غرناطة ظافِرًا. وكان حازمًا مِقدامًا جميل الطلعةِ جهيرَ الصوت كثيرَ الحياء بعيدًا عن الصبوة، تميز عهده بالاستقرارِ وحُسنِ السياسةِ وإحياء فريضة الجهاد، ومحاربةِ الفَسادِ والبِدَع. اغتاله ابنُ عَمٍّ له اسمه محمد بن إسماعيل بطعنة خنجر في غرناطة في 26 رجب من هذه السنةِ."},{"id":2938,"title":"رسل أزبك خان ملك التتار يطلبون من السلطان كتب حديث وفقه .","date":["العام الهجري :725","الشهر القمري : رمضان","العام الميلادي :1325"],"text":"في يَومِ السبت العشرينَ مِن رمضان قَدِمَ الأمير سيف الدين بكمش الجمدار الظاهريُّ والأمير بدر الدين بيليك السيفي السلاري المعروف بأبي غُدَّة من بلاد أزبك خان مَلِك التتار المُسلِم بهَدِيَّة، ومعهما كتابه، وهو يسأل أن يجهَّزُ له كتابُ (جامِع الأصول في أحاديث الرسول)، وكتاب (شرح السنة) و(البحر) للروياني في الفقه، وعِدَّةُ كُتُبٍ طَلَبها، فجُهِّزَت له."},{"id":2939,"title":"وفاة ابن المطهر الحلي الشيعي .","date":["العام الهجري :726","الشهر القمري : محرم","العام الميلادي :1326"],"text":"جمالُ الدين أبو منصور حسن بن يوسف بن مُطَهَّر الحلي العراقي الشيعي المعتزلي، شيخُ الروافض بتلك النواحي وفقيهُهم، وله التصانيفُ الكثيرة، يقال تزيدُ على مائة وعشرين مجلدًا، وعِدَّتُها خمسةٌ وخمسون مصنَّفًا، في الفقه والنحو والأصول والفلسفة والرفض، وغير ذلك من كبارٍ وصغار، وله كتابُ منهاج الاستقامة في إثبات الإمامة، خبط فيه في المعقول والمنقول، ولم يدرِ كيف يتوجه، إذ خرج عن الاستقامةِ، وقد انتدب في الرَّدِّ عليه الشيخ الإمام العلامة شيخ الإسلام تقي الدين أبو العباس ابنُ تيمية في كتابه منهاج السنَّة، أتى فيها بما يُبهِرُ العقول من الأشياء المليحة الحسنة، وكان شيخُ الإسلام يسمِّيه ابن المُنَجَّس, وله كتابُ تبصرة المتعلمين في أحكام الدين، وله قواعد الأحكام في معرفة الحلال والحرام، وتهذيب طريق الوصول إلى علم الأصول، وإرشاد الأذهان إلى أحكام القرآن، وتحرير الأحكام الشرعية على مذهب الإمامية، وله خلاصة الأقوال في الرجال، وكشف اليقين في فضائل أمير المؤمنين، وغيرها من الكتب في علم الكلام والعقائد، وُلِدَ ابن المطَهَّر الذي لم تُطهَّر خلائقُه ولم يتطَهَّر من دَنَسِ الرفض ليلة الجمعة سابع عشرين رمضان سنة 648، وتوفي ليلة الجمعة عشرين محرم من هذه السنة، وكان اشتغالُه ببغداد وغيرها من البلاد، واشتغل على نصير الطوسي، وعلى غيره، ولَمَّا تَرَفَّض الملك خربندا حَظِيَ عنده ابن المطَهَّر وساد جدًّا وأقطعه بلادًا كثيرة."},{"id":2940,"title":"ملك الحبشة يتهدد السلطان الناصر إن لم يعد بناء الكنائس .","date":["العام الهجري :726","الشهر القمري : محرم","العام الميلادي :1326"],"text":"في يومِ الاثنين سادس عشر المحَرَّم ورَدَت رسُلُ مَلِكِ الحبشة بكتابِه يتضَمَّنُ أمْرَه بإعادة ما خُرِّبَ من كنائِسِ النصارى بمصر, ومعامَلَتِهم بالإكرامِ والاحترامِ، ويهَدِّدُ بأنَّه يُخَرِّبُ ما عنده من مساجدِ المسلمين، ويَسُدُّ النيلَ حتى لا يَعبُرَ إلى مصر، فسَخِرَ السلطان الناصر محمد بن قلاوون منه، ورَدَّ رُسُلَه!!"},{"id":2941,"title":"إجراء عين باذان إلى مكة .","date":["العام الهجري :726","الشهر القمري : جمادى الأولى","العام الميلادي :1326"],"text":"في أوَّلِ رمضان وصَلَت الأخبار إلى دمشق أنه أُجرِيَت عينُ ماء إلى مكَّةَ شَرَّفَها اللهُ وانتفَعَ الناس بها انتفاعًا عظيما، وهذه العين تُعرِفُ قديمًا بعين باذان، أجراها الأميرُ سيف الدين جوبان المغولي نائب السلطان أبي سعيد بن خربندا مَلِك التتار من بلادٍ بعيدة حتى دخَلَت إلى نفس مكة، ووصلت إلى عند الصَّفا وباب إبراهيم، واستقى الناسُ منها فقيرُهم وغَنِيُّهم وضعيفُهم وشريفُهم، كلُّهم فيها سواء، وارتفق أهلُ مكة بذلك رفقًا كثيرًا،ولله الحمد والمنَّة، وكانوا قد شرعوا في حَفرِها وتجديدها في أوائِلِ هذه السنة إلى العشر الأخير من جمادى الأولى، واتَّفَق أن في هذه السنة كانت الآبارُ التي بمكة قد يَبِسَت وقلَّ ماؤها، وقَلَّ ماء زمزم أيضًا، فلولا أنَّ الله تعالى لطَفَ بالنَّاسِ بإجراء هذه القناة لنزح عن مكَّةَ أهلُها، أو هلَكَ كَثيرٌ مِمَّا يقيمُ بها."},{"id":2942,"title":"اعتقال شيخ الإسلام ابن تيمية وتلميذه ابن قيم الجوزية .","date":["العام الهجري :726","الشهر القمري : شعبان","العام الميلادي :1326"],"text":"وفي يومِ الجُمُعةِ العاشِرَ من شعبان قُرِئَ بالجامع الكتابُ السلطانيُّ الوارِدُ باعتقال شيخ الإسلامِ ابن تيمية، وهذه الواقِعةُ سَببُها فُتيا وُجِدَت بخطِّه في السَّفَرِ وإعمالِ المطِيِّ إلى زيارةِ قُبورِ الأنبياء عليهم الصلاة والسلام، وقبورِ الصالحين، وفي يوم الأربعاء مُنتصَفَ شعبان أمر قاضي القضاة الشافعي في حبسِ جماعةٍ مِن أصحاب الشيخِ تقي الدين ابن تيمية في سِجنِ الحكم، وذلك بمرسومِ نائب السلطنة وإذنِه له فيه، فيما تقتضيه الشريعةُ في أمرهم، وعُزِّرَ جماعة منهم على دوابَّ، ونودي عليهم ثمَّ أُطلِقوا، سوى شمسِ الدين محمد بن قيِّم الجوزيَّة؛ فإنَّه حُبِسَ بالقلعة، وفي يوم الاثنين عند العصر سادس عشر شعبان تم اعتقال الشيخ الإمام العالم العلَّامة تقيُّ الدين ابن تيمية بقلعة دمشق، حضَرَ إليه من جهة نائب السلطنة تنكز وابن الخطيري أحد الحجاب بدمشق، وأخبراه أنَّ مرسومَ السلطان ورد بذلك، وأحضرا معهما مركوبًا لِيَركَبَه، وأظهر السرورَ والفرح بذلك، وقال: أنا كنت منتَظِرًا لذلك، وهذا فيه خير كثيرٌ ومصلحة كبيرة، وركبوا جميعًا من داره إلى بابِ القلعة، وأُخلِيَت له قاعة وأجري إليها الماءُ ورُسِمَ له بالإقامةِ فيها، وأقام معه أخوه زين الدين يخدُمُه بإذن السلطانِ، ورُسِمَ له ما يقومُ بكفايته، والسَّبَبُ في كل ذلك هو أنَّ شيخ الإسلام ابن تيمية حَرَّم إعمالَ المطِيِّ لزيارة القبورِ بناءً على قَولِه صلَّى الله عليه وسلم: ((لا تُشَدُّ الرِّحالُ إلَّا إلى ثلاثةِ مَساجِدَ)) ثم إنَّ مُناوئي الشيخ وأعداؤه أشاعوا عنه أنَّه يقول بحُرمةِ زيارة القبور عمومًا، والشيخُ كما هو معلوم من فتاويه وكُتُبِه أنَّه لا يقولُ بحُرمةِ الزيارةِ مُطلقًا إنَّما يقول: يحرُمُ شَدُّ الرَّحلِ والسَّفَرُ لأجلِ زيارة القبور، أمَّا زيارتها من غير سَفَرٍ ولا شَدِّ رَحلٍ فيقولُ بسُنِّيَّتِه."},{"id":2943,"title":"وفاة عثمان بن أرطغرل مؤسس الدولة العثمانية وتولي ابنه أورخان .","date":["العام الهجري :726","الشهر القمري : رمضان","العام الميلادي :1326"],"text":"هو أبو الملوكِ السلطانُ الغازي فخرُ الدين عثمانُ بك خان الأول بن أرطغرل بن سليمان شاه القايوي التُركماني، لما توفِّيَ أرطغرل سنة 687 هـ ( 1288م) تولى عُثمانُ زعامةَ القبائِلِ التُّركمانيَّة في المقاطعة التي منحهم إيَّاها السلطان علاء الدين السلجوقي والتي كانت قريبةً من بحر مرمرة التابع للبحرِ الأسود بالقُربِ من مدينة بورصة، كان عثمان قد تمكَّن في البلاد حتى إنَّه بدأ يدعو أمراءَ الروم في آسيا الصغرى إلى الإسلامِ أو الجزيةِ أو الحَربِ؛ ممَّا أدى إلى استعانتهم بالمغول للقضاءِ عليه، ولكنَّه كان قد هيأ جيشًا بإمرة ابنه أورخان فسَيَّرَه لقتال المغول فشَتَّت شَملَهم وعاد فاتَّجَه إلى بورصة فاستطاع أن يدخُلَها عام 717, وكانت بورصة تعَدُّ من الحصون الروميَّة المهمَّة في آسيا الصغرى، فأمَّنَ أهلَها وأحسَنَ إليهم فدفعوا له ثلاثين ألفًا مِن عملتهم الذهبيَّة وأسلمَ حاكِمُها أفرينوس فمنحه عثمانُ لَقَب بيك، وأصبحَ مِن القادة البارزين، ثمَّ إن عثمان توفي في 21 رمضان من هذه السنة بعد معاناتِه من مرض النقرس، وكان قد عَهِدَ لابنه أورخان بالحكم وكان عمرُه تسعة وثلاثين عامًا وليس هو بأكبر أولادِ عثمان، وكان أكبَرُهم علاء الدين الذي رضي بأن يكون وزيرًا لأخيه فاهتَمَّ بالشؤون الداخليَّة وأما أورخان فاهتَمَّ بالشؤون الخارجيَّة."},{"id":2944,"title":"وفاة الغالب بالله ملك غرناطة وتولي ابنه بعده .","date":["العام الهجري :726","الشهر القمري : ذي القعدة","العام الميلادي :1326"],"text":"هو السلطانُ الغالب بالله أبو الوليد إسماعيل بن الفرج بن إسماعيل بن يوسف بن نصر صاحِبُ غرناطة والأندلس من بلاد المغرب، وكان مولده سنة 680، وكان من أجَلِّ ملوك المغرب، واستولى على الأندلُسِ ثلاث عشرة سنة، وملك البلادَ في حياة أبيه الفرج، وكان أبوه متوليًا إذ ذاك لمالقةَ، فلما أراد إسماعيلُ هذا الخروجَ لامَه أبوه، فقبض إسماعيلُ على أبيه، وعاش أبوه في سلطنتِه بعد ذلك عزيزًا مُبَجَّلًا إلى أن مات في ربيع الأول سنة 720 بعد أن شاخ. وقد كان الذي نهض بتمليك إسماعيل هو أبو سعيد ابن أبي العلاء المريني وابن أخيه أبو يحيى، وكان أبو الوليد سلطانًا مَهيبًا شُجاعًا حازِمًا ناهِضًا بأعباءِ المُلكِ عديمَ النظير عظيمَ السطوة، هزم الله جيوش الكفر على يده سنة تسع عشرة وأباد ملوك دين الصليب، ثم وثب عليه ابنُ عَمِّه فقتله في ذي القعدة، ثم قُتِلَ قاتِلُه وأعوانُه في يومهم وذلك سنة 726 وتملك بعده ولَدُه محمد أعوامًا."},{"id":2945,"title":"تنكز نائب السلطان بدمشق يشتري أسرى مسلمين من تجار الفرنج .","date":["العام الهجري :727","العام الميلادي :1326"],"text":"قَدِمَ إلى ميناء بيروت من سواحِلِ الشام تجار الفرنج بمائة وأربعين من أسارى المسلمين، قد اشتَرَوهم من الجزائر، فاشتراهم الأميرُ تنكز، وأفاد التجَّارَ في كل أسيرٍ مائة وعشرين درهمًا على ما اشتراه به، وكسا تنكز الجميعَ وزَوَّدَهم، وحَمَلَهم إلى مصر، فسُرَّ المسلمون بقدومِهم، وجَدَّ تجارُ الفرنج في شراءِ الأسرى رغبةً في الفائدةِ."},{"id":2946,"title":"فتنة بالإسكندرية بين الفرنج والمسلمين .","date":["العام الهجري :727","الشهر القمري : رجب","العام الميلادي :1327"],"text":"في يومِ الخميس خامِس رجب كانت الفتنةُ بالإسكندرية وملَخَّصُها أنَّ بعض تجار الفرنج فاوض رجلًا من المسلمينَ وضَرَبه بخُفٍّ على وجهه، فثار المسلمون بالإفرنجيِّ وثار الفرنجُ لتحميه، فوقع الشَّرُّ بين الفريقين، واقتتلوا بالسلاحِ، فركب ركن الدين الكركي متولِّي الثغر، فإذا النَّاسُ قد تعصبوا وأخرجوا السلاحَ، وشهدوا على الفرنجيِّ ممَّا يوجب قَتْلَه، وحملوه إلى القاضي وغُلِّقَت أسواق المدينة وأبوابها، فلما كان بعد عشاء الآخرة فُتِحَت الأبواب ليدخُلَ من كان خارِجَ البلد، فمِن شِدَّة الزحام قُتِلَ عَشرةُ أنفس، وتَلِفَت أعضاء جماعة، وذهبت عمائمُ وغيرها لكثير منهم، وتبيَّنَ للكركي تحامُلُ الناس على الفرنج، فحمَلَ بنفسه وأجنادِه عليهم ليدفَعَهم عن الفرنج، فلم يندفِعوا وقاتلوه إلى أن هَزَموه، وقصدوا إخراج الأمراء المعتَقَلين بالثغر، بعدما سُفِكَت بينهما دماءٌ كثيرة، فعند ذلك بادر الكركي بمطالعة السلطانِ بهذه الحادثة، فسَرَّح الطائر بالبطائِقِ يُعلِمُ السلطان، فاشتَدَّ غضبه، وخشي السلطانُ خُروجَ الأمراءِ مِن السجن، وأخرج السلطانُ الوزير مغلطاي الجمال وطوغان شاد الدواوين، وسيف الدين ألدمر الركني أمير جندار، في جماعةٍ مِن المماليك السلطانيَّة، ومعهم ناظر الخاص إلى الإسكندرية، ومعهم تذاكِرُ مما يُعمَلُ مِن تتَبُّع أهل الفساد وقَتْلِهم، ومُصادرة قَومٍ بأعيانهم، وتغريمِ أهل البلد المالَ، والقبض على أسلحة الغزاة، ومَسْك القاضي والشهود، وتجهيز الأمراء المسجونين إلى قلعة الجَبَل، فساروا في عاشِرِه، ودخلوا المدينة، وجلس الوزيرُ والناظر بديوان الخُمُس وفرض الوزيرُ على الناس خمسَمائة ألف دينار، وقَبَض على جماعةٍ مِن أذلهم ووسطِهم، وقطع أيديَ بَعضِهم وأرجُلَهم، وتطَلَّب ابن رواحة كبيرَ دار الطراز ووسطه، من أجلِ أنَّه وُشِيَ به أنه كان يُغري العامَّةَ بالفرنج ويَمُدُّهم بالسلاح والنفقة، فحَلَّ بالناس من المُصادرة بلاء عظيم، وكتب السلطانُ كتُبًا ترد شيئًا بعد شيءٍ تتضَمَّنُ الحثَّ على سفك دماء المفسدين وأخذ الأموال، والوزير يجيبُ بما يُصلِحُ أمْرَ الناس، ثم استدعى الوزير بالسلاح المعَدِّ للغزاة، فبلغ ستةَ آلاف عدة، وضعها كُلَّها في حاصل وخَتَم عليها، واستمَرَّ نحو العشرين يومًا في سَفكِ دماء وأخذِ أموال، حتى جمع ما يُنَيِّف على مائتين وستين ألف دينار، وقُدِّمَ الوزير عماد الدين محمد بن إسحاق بن محمد البلبيسي قاضي الإسكندرية لِيُشنَق، ثم أخره، وكاتب السلطانَ بأنه كَشَف عن أمرِه فوجد ما نُقِلَ عنه غيرُ صحيح، وبعث الوزير المسجونينَ إلى قلعة الجبل في طائفةٍ معهم لحِفظِهم، فقَدِموا في الثامن عشر، وقدم الوزيرُ من الإسكندرية بالمال، وجلس في آخر رجب بالمال بقاعةِ الوزارة المستجَدَّة بالقلعة، وقد سكنها، وحفر النظار والمستوفون من خارج الشباك، فنفذ الوزيرُ الأمور، وصرفَ أحوال الدولة، وفي أول شعبان قَدِمَت رسل بابا الفرنج من مدينةِ رومة بهديَّة، وكتاب فيه الوصيَّةُ بالنصارى وأنَّه مهما عُمِلَ بهم بمصرَ والشام عاملوا مَن عندهم من المسلمين بمِثلِه، فأجيبوا وأُعيدوا، ولم تَقدَمْ رسُلٌ من عند البابا إلى مصر منذ أيام الملك الصالحِ نجمِ الدين أيوب."},{"id":2947,"title":"وفاة ابن الزملكاني الشافعي .","date":["العام الهجري :727","الشهر القمري : رمضان","العام الميلادي :1327"],"text":"هو أبو المعالي محمَّدُ بن علي بن عبد الواحد بن عبد الكريم، الزملكاني الأنصاري السماكي الدمشقي الشافعي قاضي قضاة دمشق، انتهت إليه رياسةُ المذهب تدريسًا وإفتاء ومناظرة، ويقالُ في نسبه السماكي نسبة إلى أبي دجانة سماك بن خَرشة، وُلِدَ ليلة الاثنين ثامن شوال 666، وسمع الكثير واشتغل على الشيخ تاج الدين الفزاري، وفي الأصولِ على القاضي بهاء الدين بن الزكي، وفي النحوِ على بدر الدين بن ملك وغيرهم، وكان من خصومِ شَيخِ الإسلام ابن تيمية؛ قال ابن كثير: \"برع وحَصَّل وساد أقرانَه من أهل مذهبه، وحاز قَصَب السَّبقِ عليهم بذِهنِه الوقَّاد, وعبارتِه التي هي أشهى من كلِّ شيء مُعتاد، وخَطِّه الذي هو أنضَرُ مِن أزاهير الوِهاد، وقد درَّسَ بعِدَّة مدارس بدمشق، وباشر عِدَّةَ جِهات كبار، كنظر الخزانة، ونظر المارستان النوري، وديوان الملك السعيد بن الظاهر بيبرس، ووكالة بيت المال، له تعاليقُ على قطعة كبيرة من شرح المنهاج للنووي، ومجلَّد في الرد على الشيخ تقي الدين ابن تيمية في مسألة الطلاق، ومسألة زيارة القبور، وغير ذلك، وأما دروسُه في المحافل فلم أسمع أحدًا من الناس درَّس أحسن منه ولا أحلى من عبارته، وحُسن تقريره، وجودةِ احترازاته، وصِحَّة ذهنه وقوَّة قريحتِه وحُسن نَظْمه، وقد درَّسَ بالشاميَّة البرَّانية والعذراوية الجوَّانية والرواحية والمسرورية، فكان يعطي كلَّ واحدة منهن حقها بحيث كان يكاد ينسَخُ بكل واحد من تلك الدروس ما قبله مِن حُسنِه وفصاحته، ولا يهيلُه تَعدادُ الدروس وكثرة الفقهاء والفضلاء، بل كلما كان الجمعُ أكثَرَ والفضلاءُ أكبَرَ، كان الدرس أنضرَ وأبهر وأحلى وأنصح وأفصَحَ, ثم لما انتقل إلى قضاء حلب وما معه من المدارس العديدة عامله معاملةً مثلها، وأوسع بالفضيلةِ جميعَ أهلها، وسَمِعوا من العلوم ما لم يسمعوا هم ولا آباؤهم, ثم طُلب إلى الديار المصرية ليولَّى الشامية دار السنة النبويَّة فعاجلته المنيَّةُ قبل وصوله إليها، فمَرِضَ وهو سائر على البريد تسعةَ أيام، ثم عقب المرض بحراق الحِمامِ فقَبَضه هادمُ اللذات، وحال بينه وبين سائر الشَّهوات والإرادات، والأعمالُ بالنيَّات, وكان من نيَّتِه الخبيثة إذا رجع إلى الشَّامِ متَوَلِّيًا أن يؤذِيَ شيخَ الإسلام ابن تيمية فدعا عليه، فلم يبلغ أمَلَه ومُرادَه، فتوفِّيَ في سحر يوم الأربعاء سادس عشر شهر رمضان بمدينة بلبيس، وحُمِلَ إلى القاهرة ودُفِنَ بالقرافة ليلة الخميس جوار قبة الشافعي تغَمَّده الله برحمتِه\""},{"id":2948,"title":"قدوم دمرداش بن جوبان إلى مصر ثم قتله فيها .","date":["العام الهجري :728","الشهر القمري : ربيع الأول","العام الميلادي :1328"],"text":"قَدِمَ دمرداش بن جوبان بن تلك بن تداون المغولي مصرَ في سابع ربيع الأول، وسَبَبُ ذلك أن القان أبا سعيد بن خربندا المغولي لَمَّا مَلَك أقبلَ على اللهو، فتحَكَّم الأميرُ جوبان بن تلك على الأردو، وقام بأمر المملكة، واستناب ولدَه خواجا رمشتق بالأردو، وبعث ابنَه دمرداش إلى مملكة الروم، فانحصر أبو سعيد بن خربندا إلى أن تحَرَّك بعض أولاد كبك بجهة خراسان، وخرج عن الطاعةِ، فسار جوبان لحَربِه في عسكرٍ كبير، فما هو إلَّا أن بَعُد عن الأردو قليلًا حتى رجع العدوُّ عن خراسان، وقصد جوبان العودَ، وكان قد قبض أبو سعيدٍ على خواجا رمشتق، وقتَلَه بظاهر مدينة السلطانيَّة في شوال من السنة الماضية، وأتبَعَ به إخوتَه ونَهَب أتباعهم، وسَفَك أكثَرَ دمائهم، وكتب إلى من خرج من العسكَرِ مع جوبان بما وقع، وأمَرَهم بقبضه، وكتب إلى دمرداش أن يحضُرَ إلى الأردو، وعَرَّفه شَوقَه إليه، ودَسَّ مع الرسول إليه عِدَّة ملطفات إلى أمراء الروم بالقَبضِ عليه أو قَتْلِه، وعَرَّفَهم ما وقع، وكان دمرداش قد مَلَك بلاد الروم جميعَها وجبالَ ابن قرمان، وأقام على كلِّ دربند جماعةً تحفَظُه، فلا يمُرُّ أحد إلا ويعلم به خوفًا على نفسِه من السلطان الملك الناصر أن يبعَثَ إليه فداويًّا لقتلِه، بسبب ما حصل بينهما من المواحَشةِ التي اقتضت انحصارَ السلطان منه، وأنَّه منع التجارَ وغَيرَهم مِن حَملِ المماليكِ إلى مصر، وإذا سمِعَ بأحد من جهة صاحِبِ مصر أخرق به، فشَرَعَ السلطان يخادِعُه على عادته، ويهاديه ويتَرَضَّاه، وهو لا يلتَفِتُ إليه، فكتب إلى أبيه جوبان في أمْرِه حتى بعث ينكِرُ عليه، فأمسك عمَّا كان فيه قليلًا، ولَبِسَ تشريف السلطان، وقَبِلَ هَدِيَّته وبعث عِوَضَها، وهو مع هذا شديدُ التحَرُّز، فلما قَدِمَت رسل أبي سعيد بطَلَبِه فتَّشَهم الموكَّلون بالدربندات، فوجدوا الملطفات، فحملوهم وما معهم إلى دمرداش، فلما وقف دمرداش عليهما لم يزَلْ يعاقِبُ الرسُلَ إلى أن اعترفوا بأنَّ أبا سعيد قَتَل خواجا رمشتق وإخواته ومن يلوذُ بهم، ونهب أموالَهم، وبعث بقتل جوبان، فقَتَل دمرداش الرسُلَ، وبعث إلى الأمراء أصحابِ الملطفات فقَتَلَهم أيضًا، وكتب إلى السلطانِ الملك الناصر يَرغَبُ في طاعته، ويستأذِنُه في القدوم عليه بعساكر الروم، ليكون نائبًا عنه بها، فسُرَّ السلطان بذلك، وكان قد ورد على السلطانِ كتابُ المجد السلامي من الشرق بقَتلِ خواجا رمشتق وإخوته، وكتاب أبي سعيد بقَتلِ جوبان، وطلب ابنه دمرداش، وأنه ما عاق أبا سعيد عن الحركة إلا كثرةُ الثلج وقُوَّة الشتاء، فكتب السلطانُ الناصر جواب دمرداش يَعِدُه بمواعيد كثيرة، ويُرَغِّبُه في الحضور، فتحَيَّرَ دمرداش بين أن يقيم فيأتيه أبو سعيد، أو يتوجَّه إلى مصر فلا يدري ما يتَّفِقُ له، ثم قَوِيَ عنده المسير إلى مصر، وأعلَمَ أمراءَه أنَّ عسكَرَ مِصرَ سار ليأخُذَ بلاد الروم، وأنه قد كتب إليه المَلِكُ الناصر يأمره أن يكون نائِبَه، فمشى عليهم ذلك وسَرَّهم، فلمَّا قدم دمرداش إلى القاهرة في سابع ربيع الأول أتاه الأميرُ طايربغا وأحضره إلى السلطانِ بالجيزة، فقَبَّل الأرض ثلاثَ مرات، فترحَّبَ السلطان به وأجلَسَه بالقرب منه، وأكرمه وبالغ في ذلك واجتَمَعَ دمرداش بالسلطانِ وفاوضه في أمرِ بلاد الروم، وأن يجهِّزَ إليها عسكرًا، فأشار السلطانُ بالمهلة حتى يَرِدَ البريد بخبر أبيه جوبان مع أبي سعيد، فاستأذن دمرداش في عَودِ مَن قَدِمَ معه إلى بلادِهم، فأذِنَ له في ذلك، فسار كثيرٌ منهم، ثم جاء كتابٌ فيه بيان أحوال دمرداش هذا وأنَّه سفك دماءً كثيرة، وقَتَل من المسلمين عالَمًا عظيمًا، وأنَّه جَسورٌ وما قصد بدخولِه مِصرَ إلا طمعًا في مُلكِها، وبعث ابن قرمان الكتابَ صحبة نجم الدين إسحاق الرومي صاحب أنطالية، وهي القلعة التي أخذها منه دمرداش وقَتَل والِدَه، وأنَّه قَدِمَ ليطالِبَه بدَمِ أبيه، فلما وقف السلطانُ على الكتاب تغيَّرَ، وطلب دمرداش وأعلَمَه بما فيه، وجمع السلطانُ بينه وبين إسحاق، فتحاقَقا بحضرة الأمراء، فظهر أنَّ كُلًّا منهما قتَلَ لصاحِبِه قتيلًا، فكتب جواب ابن قرمان معه وأُعيد، وقد تبَيَّن للسلطان خُبثُ نية دمرداش، فقبضه ومن معه واعتقل دمرداش ببرج السباعِ مِن القلعة، وفَرَّق البقية في الأبراج، وفُرِّقَت مماليكُه على الأمراء، ورُتِّبَ له ما يكفيه، وكان للقبضِ على دمرداش أسباب: منها أنه كان قد أخذ يوقِعُ في الأمراء والخاصكية، ويقول: هذا كان كذا، وهذا كان كذا، وهذا ألماس الحاجب كان حمَّالًا، فما حمل السلطان هذا منه، فلما كان في ليلة الخميس رابع شوال من هذه السنة أُخرِجَ دمرداش من مُعتَقَلِه بالبرج، وفُتِحَ باب السِّرِّ من جهة القرافة وأُخرِجَ منه وهو مُقَيَّدٌ مَغلول، وشاهَدَه رسُلُ الملك أبي سعيد وهو على هذه الحالِ، ثم خُنِقَ دمرداش، وشاهده الرسُلُ بعد موته، وقُطِعَ رأسُه وسُلِخَ وصُبِرَ وحُشِيَ، وأرسل السلطانُ الرأسَ إلى أبي سعيد، ودُفِنَ الجسَدُ بمكانِ قَتْلِه."},{"id":2949,"title":"تنكز نائب السلطان على دمشق يجري عينًا في القدس .","date":["العام الهجري :728","الشهر القمري : ربيع الأول","العام الميلادي :1328"],"text":"كان قبل سنتين أمَرَ تنكز نائبُ السلطان على دمشقَ بإجراء عينٍ إلى القدس، حيث قلَّ الماءُ فيها كثيرًا وبلغه ما فعله جابان بإجراءِ عَينٍ في مكَّةَ، فأراد أن يكون له أيضًا شَرَفُ ذلك، وفي هذه السنة كَمُلت العينُ التي أجراها الأمير تنكز بالقدس، بعد ما أقام الصنَّاعُ فيها مُدَّةَ سنة، وبنى لها مصنعًا- خزانًا- سعته نحو مائتي ذراع مرخَّم بين الصخرة والمسجد، وركَّب في الجبل مجاريَ نَقَب لها في الحَجَرِ حتى دخل الماءُ إلى القدس، فكان لها يومٌ مشهودٌ، وأنشأ تنكز بالقدسِ أيضًا خانكاه وحمام وقيسارية –سوق كبير- فعَمرَت القُدسُ."},{"id":2950,"title":"منع شيخ الإسلام ابن تيمية من الكتابة في السجن .","date":["العام الهجري :728","الشهر القمري : جمادى الآخرة","العام الميلادي :1328"],"text":"في يومِ الاثنين تاسِعَ جمادى الآخرة أُخرِجَ ما كان عند الشيخِ تقي الدينِ ابن تيميَّةَ من الكتُبِ والأوراقِ والدواةِ والقلم، ومُنِعَ من الكُتُبِ والمطالعة، وحُمِلَت كتُبُه في مُستهَلِّ رَجَب إلى خزانةِ الكتُبِ بالعادليَّة الكبيرة، وكانت نحو ستين مجلَّدًا، وأربع عشرة ربطةَ كراريس، فنظر القضاةُ والفُقهاءُ فيها وتفَرَّقوها بينهم، وكان سبَبَ ذلك أنَّه أجاب لما كان ردَّ عليه التقيُّ ابنُ الأخنائي المالكي في مسألة الزيارة، فرَدَّ عليه الشيخ تقي الدين واستجهَلَه وأعلَمَه أنَّه قليل البضاعة في العلم، فطَلَع الأخنائيُّ إلى السلطان وشكاه، فرسم السلطانُ عند ذلك بإخراجِ ما عنده من ذلك، وكان ما كان."},{"id":2951,"title":"وفاة الأمير جوبان نائب السلطان أبو السعيد بن خربندا المغولي .","date":["العام الهجري :728","الشهر القمري : شوال","العام الميلادي :1328"],"text":"هو الأميرُ الكبير الأمير سيفُ الدين جوبان بن تلك بن تداون المغولي نائبُ السلطانِ أبي سعيدِ بن خربندا المغولي مَلِك التَّتار، وجوبان هذا هو الذي ساق قناةَ الماء الواصِلةَ إلى المسجد الحرام، وقد غَرِمَ عليها أموالًا جزيلة كثيرة، وله تربةٌ بالمدينة النبوية، ومدرسةٌ مشهورة، وله آثارٌ حَسَنة، وكان جيِّدَ الإسلامِ، له همَّة عالية، وقد دبَّرَ الممالِكَ في أيام السلطان أبي سعيد مُدَّةً طويلة على السداد، ثم أراد أبو سعيد مَسكَه والتخلُّصَ منه فقَتَل ابنه خواجا رمشتق في السنة الماضية، وفر ابنُه الآخر دمرداش هاربًا إلى سلطان مصر، ثمَّ قَتَلَ أبو سعيد نائبَه جوبان بعد ابنه بقليلٍ، وكان من أسباب قتل جوبان أنَّه كان يريد أن يتفَرَّد بالمُلكِ مِن دون أبي سعيدٍ، فقد أصبح كلُّ شَيءٍ في يَدِه من أمرٍ ونهيٍ، وولَّى أولادَه الإقطاعاتِ والولاياتِ، فكان هذا من أسبابِ حَنَق أبي سعيد عليه وقَتْلِه، ففي يوم الجمعة آخِرَ شَهرِ ربيع الآخر من السنة التالية أُنزِلَ الأميرُ جوبان وولده من قلعة المدينة النبوية وهما ميِّتان مُصبران في توابيتِهما، فصُلِّيَ عليهما بالمسجد النبويِّ، ثم دفنا بالبقيعِ عن مرسومِ السلطان، وكان مرادَ جوبان أن يُدفَنَ في مدرسته، فلم يُمكَّنْ من ذلك."},{"id":2952,"title":"حدوث سيل عظيم في مدينة عجلون .","date":["العام الهجري :728","الشهر القمري : ذي القعدة","العام الميلادي :1328"],"text":"جاء إلى مدينة عجلون سيلٌ عظيم من أوَّل النهار إلى وقتِ العصر، فهدَمَ مِن جامعِها وأسواقِها ورِباعِها ودُورِها شيئًا كثيرًا، وغَرِقَ سَبعة نَفَرٍ، وهلك للناس شيءٌ كثير من الأموال والغلات والأمتعة والمواشي ما يقارب قيمتُه ألف ألف درهم."},{"id":2953,"title":"وفاة شيخ الإسلام تقي الدين ابن تيمية .","date":["العام الهجري :728","الشهر القمري : ذي القعدة","العام الميلادي :1328"],"text":"هو الشَّيخُ الإمامُ العالمُ العَلَمُ العلَّامةُ الفقيهُ الحافِظُ الزاهِدُ العابِدُ القدوةُ شيخُ الإسلامِ: تقيُّ الدين أبو العباس أحمد بن شهاب الدين أبي المحاسن عبد الحليم بن أبي البركات عبد السلام بن عبد الله بن أبي القاسم محمد بن الخضر بن محمد ابن الخضر بن علي بن عبد الله بن تيمية الحراني ثمَّ الدمشقي، وكان مولِدُه يومَ الاثنين عاشر ربيع الأول بحران سنة 661، وقَدِمَ مع والده وأهلِه إلى دمشقَ وهو صغير، فسَمِعَ الحديثَ وقرأ بنفسِه الكثيرَ، وطلب الحديثَ وكُتُبَ الطبقاتِ والأثباتِ، ولازم السَّماعَ بنفسه مُدَّةَ سنين، وقَلَّ أن سَمِعَ شَيئًا إلَّا حَفِظَه، ثم اشتغل بالعلومِ، وكان ذكيًّا كثيرَ المحفوظ، فصار إمامًا في التفسير وما يتعلَّق به عارفًا بالفقه، فيقال: إنه كان أعرَفَ بفقه المذاهِبِ مِن أهلِها الذي كانوا في زمانِه وغيره، وكان عالِمًا باختلاف العلماء، عالِمًا في الأصول والفروعِ، والنحو واللغة، وغير ذلك من العلوم النَّقليَّة والعقلية، وما قُطع في مجلسٍ، ولا تكَلَّمَ معه فاضِلٌ في فنٍّ مِن الفنونِ إلَّا ظَنَّ أنَّ ذلك الفَنَّ فَنُّه، ورآه عارفًا به متقِنًا له، وأما الحديثُ فكان حامِلَ رايتِه حافظًا له مميِّزًا بين صحيحِه وسقيمِه، عارفًا برجاله متضَلِّعًا من ذلك، وله تصانيفُ كثيرة وتعاليقُ مُفيدة في الأصولِ والفروع، كمُلَ منها جملةٌ وبُيِّضَت وكُتِبَت عنه وقُرِئَت عليه أو بَعضُها، وجملةٌ كبيرةٌ لم يُكمِلْها، وأثنى عليه وعلى علومِه وفضائِلِه جماعةٌ من عُلَماءِ عَصرِه، وأمَّا أسماءُ مُصَنَّفاتِه وسيرته وما جرى بينه وبين الفُقَهاءِ والدولة وحَبسُه مراتٍ وأحوالُه، فلا يُحتَمَلُ ذِكرُ جَميعِها في هذا الموضِعِ، توفِّيَ في ليلة الاثنين والعشرين من ذي القعدة بقلعةِ دمشق بالقاعةِ التي كان محبوسًا بها، وحضر جمعٌ كثيرٌ إلى القلعة، وأُذِنَ لهم في الدخول عليه، وجَلَس جماعة عنده قبل الغُسلِ واقتصروا على مَن يُغَسِّلُه، فلما فُرِغَ مِن غُسلِه أُخرِجَ ثم اجتمع الخَلقُ بالقلعة والطريقِ إلى الجامعِ، وامتلأ بالجامع أيضًا وصَحنِه والكلاسة وباب البريد وباب الساعات إلى باب اللبادين والغوارة، وحضرت الجنازةُ في الساعة الرابعة من النهار أو نحو ذلك ووُضِعَت في الجامع، والجندُ قد احتاطوا بها يحفَظونَها من النَّاسِ مِن شِدَّة الزحام، وصُلِّيَ عليه أولًا بالقلعة، تقدَّمَ في الصلاة عليه أولًا الشيخ محمد بن تمام، ثم صُلِّيَ عليه بالجامِعِ الأمويِّ عَقيبَ صلاة الظهر، وقد تضاعَفَ اجتِماعُ الناس ثم تزايد الجَمعُ إلى أن ضاقت الرِّحابُ والأزِقَّة والأسواق بأهلِها ومَن فيها، ثم حُمِلَ بعد أن صُلِّيَ عليه على الرؤوس والأصابع، وخرج النَّعشُ به من باب البريد واشتدَّ الزحامُ وعَلَت الأصواتُ بالبُكاء والنَّحيب والترحُّم عليه والثَّناء والدعاء له، وألقى الناسُ على نعشِه مناديلَهم وعمائِمَهم وثيابَهم، وذهبت النِّعالُ مِن أرجُلٍ, وبالجملةِ كان يومُ جنازته يومًا مشهودًا لم يُعهَدْ مثلُه بدمشقَ إلَّا أن يكون في زمَنِ بني أمية حين كان الناسُ كثيرين، وكانت دار الخلافة، ثم دُفِنَ عند أخيه قريبًا من أذان العصر على التحديد، ولا يمكِنُ أحدًا حصرُ من حضر الجِنازةَ، وتقريبُ ذلك أنَّه عبارةٌ عمَّن أمكنه الحضورُ من أهل البلَدِ وحواضِرِه ولم يتخلَّفْ مِن الناس إلا القَليلُ مِن الصغار والمخَدَّرات، وما تخلَّفَ أحدٌ من أهل العلمِ إلَّا النفرُ اليسير تخلَّف عن الحضور في جنازته، وهم ثلاثةُ أنفس: وهم ابنُ جملة، والصدر، والقفجاري، وهؤلاء كانوا قد اشتهروا بمعاداتِه فاختَفَوا من الناس خوفًا على أنفُسِهم، بحيث إنَّهم علموا متى خرجوا قُتِلوا وأهلَكَهم الناس، ورُئيَت له مناماتٌ صالحةٌ عَجيبةٌ، ورُثِيَ بأشعارٍ كثيرة وقصائِدَ مُطَوَّلة جدًّا، وقد أُفرِدَت له تراجِمُ كثيرة، وصَنَّف في ذلك جماعةٌ من الفضلاء وغيرهم، ويدُلُّ على علمِه وفَضلِه مُصَنَّفاتُه، كالتفسير، ومنهاج السنة، ودرء تعارض العقل والنقل، وفتاويه التي جُمِعَت، وغيرها كثير، كان جريئًا قويًّا لا يخاف في الله لومةَ لائم، حثَّ الناسَ والأمراء على جهاد التتار، بل ذهب بنفسه لمقابلةِ مَلِكهم قازان حين جاء ليدخُلَ دمشق وقال له: أنت تدعي أنك مسلم فلمَ جئت تغزو بلاد الإسلامِ؟ وغير ذلك من المواقف المشَرِّفة، مثل وقت استفتاه السلطان الناصر محمد بن قلاوون في قَتْلِ الفقهاء والقضاة الذين كانوا ضِدَّه يومَ خَلَع نفسَه وكانوا مع المظفَّر بيبرس، وكان منهم من آذى الشيخَ نَفسَه، فلم يُفْتِ له الشيخُ بأذِيَّتِهم، بل بيَّنَ له حُرمةَ وقَدرَ العُلَماءِ، وقال: إنَّه لا ينتصر لنفسِه، وكلُّ من آذاه فهو في حِلٍّ، وهذا من تمامِ فَضلِه وحُسنِ خُلُقِه، وله الأثرُ الكبيرُ في مُناظرة أهلِ البِدَع والعقائِدِ الفاسدة بما أحيا اللهُ على يديه ممَّا اندرس بين النَّاسِ منها، فكان بحَقٍّ مُجَدِّدًا للدين، فرحمه الله تعالى وجزاه عن الإسلامِ والمسلمين خيرًا."},{"id":2954,"title":"إطلاق سراح الإمام ابن قيم الجوزية .","date":["العام الهجري :728","الشهر القمري : ذي الحجة","العام الميلادي :1328"],"text":"في يومِ الثلاثاء عشرينَ ذي الحجة أُفرِجَ عن الشيخ الإمامِ العالم العلَّامة أبي عبد الله شمس الدين بن قيم الجوزية، وكان معتقَلًا بالقلعة أيضًا مع الشيخ تقي الدين من شعبان سنة ست وعشرين إلى هذا الحينِ."},{"id":2955,"title":"بناء أول جيش عثماني نظامي .","date":["العام الهجري :729","العام الميلادي :1328"],"text":"بعد أن انتقل أورخان بن عثمان إلى بورصة وجعَلَها عاصمَتَه وضَرَبَ العملةَ الفضيَّة والذهبيَّة ثمَّ بدأ بتأسيسِ جيشِ يني تشري- يعني الجيش الجديد الذي عرف فيما بعد بالإنكشارية- الذي كانت نَواتُه أبناءَ الأَسرى والصِّغار الذين يَقَعون في الأسرِ فيُرَبَّونَ في ثُكناتِ عَسكريَّة تربيةً إسلاميَّةً ويُدَرَّبونَ تَدريبًا عسكريًّا ويتخَرَّجونَ لا يَعرِفونَ إلَّا القتالَ والحياةَ العَسكريَّة والإسلامَ والجِهادَ في سبيلِ الله، وليس الرَّوابط القَبَليَّة والعشائريَّة؛ إذ لا يعرفون إلا السُّلطانَ سَيِّدًا لهم وقائدًا، فكانوا بذلك أكبَرَ قُوَّة ساهمت في ضرب خُصومِ العُثمانيين ومَدَّت الفتوحاتِ في البلاد."},{"id":2956,"title":"مملوك يدعي أنه المهدي بمصر .","date":["العام الهجري :729","الشهر القمري : ذي القعدة","العام الميلادي :1329"],"text":"في يومِ الجمعة سادس ذي القعدة بعد أذان الجُمُعةِ صَعِدَ إلى منبر جامِعِ الحكم بمصر شخصٌ من مماليك الجاولي يقالُ له أرصى، فادَّعى أنَّه المهدي وسَجَع سجعاتٍ يسيرةً على رأيِ الكُهَّان، فأُنزِلَ في شرخيبة، وذلك قبل حضورِ الخطيب بالجامِعِ المذكور."},{"id":2957,"title":"الفرنج يطلبون تسليم القدس وبلاد الساحل .","date":["العام الهجري :730","الشهر القمري : ربيع الآخر","العام الميلادي :1330"],"text":"في خامِس عشر ربيع الآخر قَدِمَت رسل ريدافرنس في طَلَبِ القُدسِ وبلادِ الساحل، وعِدَّتُهم مائة وعشرون رجلًا، فأنكَرَ السلطانُ الناصِرُ محمد بن قلاوون عليهم وعلى مُرسِلِهم وأهانَهم، ثمَّ رسم بِعَودِهم إلى بلادهم، وقال لهم: لولا أنَّ الرُّسُلَ لا تُقتَلُ لقَتَلْتُكم جميعًا."},{"id":2958,"title":"يوسف الكيمياوي النصراني يخدع السلطان الناصر بصناعة الذهب .","date":["العام الهجري :730","الشهر القمري : رمضان","العام الميلادي :1330"],"text":"قَدِمَ يوسفُ الكيمياوي إلى مِصرَ في يوم الخميس سابعَ عشر رمضان، وكان من خبَرِ هذا الرجل أنه كان نصرانيًّا من أهل الكرك فأسلم، ومضى إلى دمشقَ بعدما خَدَع بمدينة صفد الأميرَ بهادر التقوى حتى انخدع له وأتلَفَ عليه مالًا جزيلًا، فلما ظهَرَ له أمْرُه سَجَنه مُدَّةً، ثم أفرج عنه، فاتصَلَ يوسف بالأمير تنكز نائب الشام، وقَصَد خديعته فلم ينخَدِعْ له، وأمر والي دمشق بشَنقِه، فصاح وقال: أنا جيت للسُّلطانِ حتى أملأَ خِزانَتَه ذهبًا وفِضَّة، فلم يجِدْ تنكز بدًّا من إرساله إلى السلطان، فقَيَّده وأركَبَه البريدَ مع بعض ثقاتِه، وكتب بخَبَرِه وحَذَّر منه، فلما اجتمع يوسفُ بالسلطان مال إلى قَولِه، وفَكَّ قَيدَه، وأنزله عند الأمير بكتمر الساق وأجرى عليه الرواتِبَ السَّنِيَّة، وأقام له عِدَّةً مِن الخدم يتولَّون أمره، وخلع عليه، وأحضر له ما طلَبَ من الحوائج لتدبيرِ الصَّنعةِ، حتى تمَّ ما أراده، فحضر يوسف بين يدي السلطان، وقد حضر الفخر ناظِرُ الجيش والتاج إسحاق وابن هلال الدولة والأمير بكتمر الساقي في عِدَّةٍ من الأمراء، والشيخ إبراهيم الصائغ وعِدَّة من الصواغ، فأوقدوا النَّارَ على بوطقة قد مُلِئَت بالنُّحاسِ والقصدير والفضة حتى ذاب الجميعُ، فألقى عليه يوسفُ شيئًا من صنعته، وساقوا بالنَّارِ عليها ساعةً، ثم أفرغوا ما فيها فإذا سبيكةُ ذَهَبٍ كأجوَدِ ما يكونُ، زِنَتُها ألفُ مثقالٍ، فأعجَبَ السلطانَ ذلك إعجابًا كثيرًا، وسُرَّ سرورًا زائدًا، وأنعم على يوسف بهذه الألفِ مِثقالٍ، وخلع عليه خِلعةً ثانية، وأركبه فرسًا مُسرَجًا مُلَجَّمًا بكنبوش حرير، وبالغ في إكرامِه، ومكَّنَه من جميع أغراضه، فاتصل به خُدَّام السلطان، وقَدَّموا له أشياء كثيرة مستحسنة، فاستخَفَّ عُقولَهم حتى ملكها بكَثرةِ خُدَعِه، فبذلوا له مالًا جزيلًا، ثم سَبَك يوسف للسلطان سبيكةً ثانية من ذهب، فكاد يطيرُ به فرحًا، وصار يستحضِرُه بالليل ويحادِثُه، فيزيده طَمَعًا ورغبة فيه، فأذِنَ له أن يركب من الخيولِ السُّلطانيَّة ويمضي حيث شاء من القاهرةِ ومصر، فركب وأقبَلَ على اللهو، وأتاه عِدَّةٌ من الناس يسألونَه في أخذِ أموالهم، طمعًا في أن يُفيدَهم الصَّنعةَ أو يُغنيهم منها، فمَرَّت له أوقاتٌ لا يتهيَّأُ لكلِّ أحَدٍ مِثلُها مِن طِيبتِها، ثم إنَّه سأل أن يتوجَّه إلى الكرك لإحضارِ نبات هناك، فأركبه السلطانُ البريد، وبعث معه الأميرَ طقطاي مُقَدَّم البريدية، بعدما كتب إلى نائب غَزَّة ونائب الكرك بخدمتِه وقضاء ما يُرسَم به والقيام بجميع ما يحتاجُ إليه من ديوان الخاص، فمضى يوسفُ إلى الكرك وأبطأ خبَرُه، ثم قَدِمَ وقد ظهر كَذِبُه للسلطان، فضَيَّق عليه وحبسه في القاهرة، ثم إنَّه في عام 731 هرب من السجنِ ثمَّ بعد عدة أشهر وُجِدَ في أحميم فمَثُلَ بين يدي السلطان فسأله عن المال، فقال: عَدِمَ مني، فسأله السلطانُ عن صناعته فقال: كُلُّ ما كنتُ أفعَلُه إنما هو خِفَّةُ يدٍ، فعوقب عُقوبةً شديدة بالضرب، ثم حُمِلَ إلى خزانة شمائل سجن أرباب الجرائم بجوار باب زويلة من القاهرة، فمات ليلة الأحد خامس عشر ذي الحجة، فسُمِّرَ وهو ميت وطيف به القاهرة على جملٍ في يوم الأحَدِ."},{"id":2959,"title":"فتنة العبيد بمكة وقتل الأمير الدمر جاندار .","date":["العام الهجري :730","الشهر القمري : ذي الحجة","العام الميلادي :1330"],"text":"قُتِلَ الأميرُ الدمر جاندار بمكَّةَ في يوم الجمعة رابع عشر ذي الحجة، وكان مِن خَبَرِه أنَّ أميرَ الرَّكبِ العراقيِّ في هذه السنة كان من أهل توريز يُعرَفُ بمحمد الحجيج، وكان يتقَرَّب من أولاد جوبان، فترقَّى بهم إلى معرفةِ السلطان أبو سعيد بن خربندا ملك التتار بالعراق، فعَظُمَ أمرُه وجعَلَه من نُدَمائِه، وبَعَثَه رسولًا إلى مصرَ غَيرَ مَرَّة، فأُعجِبَ به السلطانُ الناصِرُ ولاق بخاطِرِه إلى أن بلغه عنه أنَّه تعَرَّض في مجلس أبي سعيد لشيءٍ ذكر مما يكرَهُه السلطان، فتنكَّرَ له وأسَرَّ ذلك في نفسِه، فلمَّا بلَغَه أنَّه سار أميرُ الركب العراقي كتب إلى الشَّريفِ عُطَيفة بن أبي نمي سرًّا أن يتحَيَّلَ في قتله، فلم يجِدْ عطيفة بدًّا من امتثال ما أُمِرَ به، وأطلَعَ ولده مبارك بن عطيفة ومن يثِقُ به على ذلك، وتقَدَّم إليهم بإعمال الحيلة فيه، فلما قضى الحاجُّ النُّسُكَ عاد منهم الأمير علم الدين سنجر الجاولي إلى مصر ومعه جماعةٌ في يومِ الأربعاء ثاني عشر ذي الحجة، وتأخَّرَ الأمير سيف الدين خاص ترك أمير الحاج، والأميرُ الدمر جاندار، والأمير أحمد ابن خالة السلطان، ليُصَلُّوا بمكَّةَ صلاة الجمعة، ومعهم بقيَّةُ حجَّاج مصر، فلما حضروا للجمعة وصَعِدَ الخطيب المنبر، أراد الشَّريفُ عَمَل ما رُسِمَ له به، وأخَذَ العبيدُ في إثارةِ الفِتنةِ بين الناس ليحصُلَ الغَرَضُ بذلك، وأوَّل ما بدؤوا به أن عبثوا ببعضِ حاجِّ العراق، وخطفوا شيئًا من أموالِهم، وكان الشريفُ عطيفة جالسًا إلى جانب الأمير خاص ترك أميرِ الركب، فصرخ النَّاسُ بالأمير الدمر وليس عندَه عِلمٌ بما كَتَب به السلطانُ إلى الشَّريفِ عُطَيفة، وكان مع ذلك شُجاعًا حادَّ المزاجِ قَويَّ النفس، فنهض ومعه من المماليكِ، وقد تزايد صراخُ النَّاسِ، وأتى الشَّريفَ وسَبَّه، وقَبَض بعضَ قُوَّادِه وأخرَقَ به، فلاطفه الشريفُ فلم يَلِنْ، واشتد صياحُ الناس، فركب الشريف مبارك بن عطيفة في قوَّادِ مكة بآلة الحَربِ، وركب جندُ مِصرَ، فبادر خليلٌ ولد الأمير الدمر وضرب أحدَ العبيد، فرماه العبدُ بحَربةٍ فقَتَله، فاشتَدَّ حنَقُ أبيه وحَمَل بنفسه لأخذ ثأرِ ولَدِه فقُتِلَ هو أيضًا، ويقال بل صادف الشريف مبارك بن عطيفة، وقد قصد ركبَ العراق وعليه آلةُ حَربِه، فقال له: \"ويلك تريدُ أن تثيرَ فِتنةً، وهمَّ أن يَضرِبَه بالدبوس، فضربَه مبارك بحَربةٍ كانت في يده أنفَذَها من صدره فخَرَّ صريعًا، وقُتِلَ معه رجلان من جماعته، فركب أميرُ الركب عند ذلك ونجا بنَفسِه، ورُمِيَ مُبارك بن عطيفة بسَهمٍ في يده فشُلَّت، واختبط الناسُ بأسرهم، وركب أهلُ مكة سطحَ الحَرَم، ورموا الأميرَ أحمد ابن خالة السلطان ومن معه بالحجارة، وقد أفرغ نشَّابه بين يديه هو ومن معه، ورمى بها حتى خلَصَ أيضًا، وفَرَّ أمير ركب العراق وتحيَّرَ الشريف عطيفة في أمره، وما زال يداري الأمرَ حتى خرج الحاجُّ بأجمعهم من مكة، وتوجَّهوا إلى بلادِهم، وتراجع الأمراءُ المصريُّونَ إلى مكة لطَلَبِ بعض الثأر فلم يُنتِجْ أمرُهم وعادوا فارِّينَ، ثم أمَرَ أمير المصريين بالرَّحيل، وعادوا إلى القاهرة وأخبروا المَلِكَ الناصر محمد بن قلاوون، فجهَّزَ إلى مكة عسكرًا كثيفًا وعليه جمعٌ من الأمراء، فتوَجَّهوا وأخفَوا بثأرِ أيدمر وابنه، وقتلوا جماعةً كثيرةً مِن العبيد وغيرهم، وأسرفوا في ذلك وخرجوا عن الحَدِّ إلى الغاية، وتشَتَّت أشرافُ مَكَّة والعبيد عن أوطانِهم وأُخِذَت أموالهم، وحَكَمَت التركُ مَكَّةَ من تلك السنة، وزال منها سَطوةُ أشراف مكة الرَّافضة والعبيد، وانقَمَع أهلُها وارتدعوا، وكَرِهَهم المَلِكُ الناصر ومَقَتَهم وأقصاهم، حتى إنَّه لما حج بعد ذلك كان إذا أتاه صاحِبُ مكَّة لا يقومُ له مع تواضُعِ المَلِك الناصِرِ للفقهاء والأشراف والصُّلَحاءِ وغَيرِهم."},{"id":2960,"title":"تغيير أمير مكة بسبب فتنة العبيد .","date":["العام الهجري :731","الشهر القمري : جمادى الآخرة","العام الميلادي :1331"],"text":"بعد ما كان من الفِتنةِ بمكَّةَ العامَ السَّابِقَ وانزعاج السلطانِ الناصر محمد بن قلاوون كثيرًا لذلك، ففي المحَرَّم هذا العام قَدِمَ الحاجُّ، وأخبروا بكثرةِ الفِتَن بمكَّةَ بين الشريفين عُطيفة ورُميثة، وقُوَّة رُمَيثة على عُطَيفة ونهْبِه مكَّة وخروجه عن الطاعة، وأنه لم يلقَ رَكبَ الحُجَّاج، فكتب بحضورِه، فلما ورد المرسومُ بطلب الشريفينِ إلى مصر اتَّفَقا وخرجا عن الطاعة، فشقَّ ذلك على السلطان، وعَزَم على إخراج بني حسَن من مكة، وتقَدَّم السلطان إلى الأمير سيف الدين أيتمش أن يَخرُجَ بعسكرٍ إلى مكة، وقال له بحضرة القضاة: \"لا تدع في مكَّةَ أحدًا من الأشرافِ ولا من القُوَّاد ولا مِن عَبيدِهم، ونادِ بها من أقام منهم حَلَّ دَمُه، ثم أحرِقْ جَميعَ وادي نخلةَ، وألقِ في نَخلِها النَّارَ حتى لا تدَعَ شَجرةً مُثمِرةً ولا دِمنةً- آثار الديار- عامرةً، وخَرِّبْ ما حول مكَّةَ من المساكن، وأخرِجْ حَرَم الأشرافِ منها، وأقِمْ بها بمن معك حتى يأتيك عسكَرٌ آخرُ\"، فقام في ذلك قاضي القضاة جلال الدين محمد القزويني ووعَظَ السُّلطانَ وذَكَّره بوجوبِ تَعظيمِ الحَرَمِ، إلى أن استقَرَّ الأمر على أن كُتِبَ لرُمَيثة أمانٌ وتقليد بإمرة مكَّة، وسار العسكر من ظاهر القاهرة في نصف صفر، وعِدَّتُهم سبعمائة فارس، وفي سابع جمادى الآخرة قدم الأمير أيتمش بالعسكر المجرَّد إلى مكة، وكان الشريفُ رُمَيثة قد جمع عربًا كثيرةً يريدُ محاربتهم، فكتب إليه الأميرُ أيتمش يُعَرِّفُه بأمان السلطان له وتقليدِه إمرةَ مَكَّة، ويحثُّه على الحضور إليه ويرَغِّبُه في الطاعة، ويحَذِّرُه عاقبةَ الخلاف ويهدده على ذلك، ويُعَرِّفُه بما أمر به السلطانُ من إجلاء بني حسن وأتباعِهم عن مكة، فلما وقف رُمَيثةُ على ذلك اطمأَنَّ إلى الأمير أيتمش وأجابه بما كان قد عزم عليه من الحربِ لو أنَّ غَيرَه قام مقامَه، وطلب منه أن يحلِفَ هو ومن معه ألَّا يَغدِرَ، وأن يُقرِضَه مبلغ خمسين ألف درهم يتعَوَّضُها من إقطاعِه، فتقَرَّر الحال على أن يبعثَ إليه الأمير أيتمش عشرةَ أحمال من الدقيق والشعير والبقسماط وغيره، ومبلغ خمسة ألاف درهم، فقَدِمَ حينئذ، فلما قارب رُمَيثة مكة رَكِبَ الأمير أيتمش بمن معه إلى لقائِه، فإذا عِدَّةٌ من قواده مع وزيره قد تقَدَّموه ليحَلِّفوا له العسكر، فعادوا بهم إلى الحَرَمِ وحلفوا له أيمانًا مؤكَّدة، ثم ركبوا إلى لقائِه وقابَلوه بما يليقُ به من الإكرام، فلَبِسَ رميثة تشريفَ السلطان، وتقَلَّد إمارةَ مكَّة، وعَزَم على تقدمة شيءٍ للأمراء، فامتنعوا أن يقبلوا منه هَدِيَّةً، وكتبوا إلى السلطانِ بعَودِ الشريف إلى الطاعةِ."},{"id":2961,"title":"ملك أبي الحسن علي بن أبي سعيد المريني مدينة فاس بعد أبيه .","date":["العام الهجري :731","الشهر القمري : ذي القعدة","العام الميلادي :1331"],"text":"ملَكَ أبو الحَسَنِ علي بن أبي سعيد عثمان بن يعقوب بن عبد الحَقِّ المريني المنصور بالله مدينةَ فاس من بلادِ المغرب، بعد مَوتِ أبيه بعَهدٍ منه، وعُرِفَ بالسلطانِ الأكحَلِ لسُمرةِ لَونِه، فقد كانت أمُّه حَبشيَّةً."},{"id":2962,"title":"وفاة الملك المؤيد عماد الدين الأيوبي صاحب حماة وتولي ابنه بعده .","date":["العام الهجري :732","الشهر القمري : محرم","العام الميلادي :1331"],"text":"هو المَلِكُ المؤيَّد صاحب حماة عماد الدين إسماعيل بن الملك الأفضل نور الدين علي بن الملك المظفر تقي الدين محمود بن الملك المنصور ناصر الدين محمد بن الملك المظفر تقي الدين عمر بن شاهنشاه بن أيوب، كانت له فضائلُ كثيرةٌ في علوم متعَدِّدة منها الفِقهُ والهيئة والطب، وله مُصَنَّفات عديدة، منها تاريخٌ حافِلٌ في مجلَّدين كبيرين، وله نَظمُ الحاوي وغير ذلك، وكان يحِبُّ العلماءَ ويُشارِكُهم في فنون كثيرة، وكان من فُضَلاءِ بني أيوب، ولي مُلكُ حماة من سنة إحدى وعشرين إلى هذا العام، وكان السلطان الناصر بن قلاوون يُكرِمُه ويُعَظِّمُه، ووَلِيَ بعدَه ولدُه الأفضل علي، توفِّيَ في سحر يوم الخميس ثامن عشرين المحرم، ودُفِنَ ضَحوةً عند والديه بظاهِرِ حماة."},{"id":2963,"title":"الفرنج يهمون باستئناف الحروب الصليبية .","date":["العام الهجري :733","العام الميلادي :1332"],"text":"فيليب السَّادِسُ مَلِكُ فرنسا يُعلِنُ عَزمَه على القيامِ بحَملةٍ صَليبيَّةٍ جَديدةٍ، لكِنَّه ينثني عنها بدخولِه حِلفًا ضِدَّ الأتراك العُثمانيِّين واشتراك جيوشِه في الإغارة على أزمير سنة 735، ولكِنَّ نجاحَه في هذه المعركة أعاد له العزمَ على مشروع الحَربِ الصَّليبيَّة، ولكِنْ لم يلبث أن أغارت إنكلترا عليه فانصرَفَ نهائيًّا عن فِكرةِ الحرب الصليبيَّة؛ لدوام حربه مع إنكلترا بما يُعرَفُ اليوم بحرب المائة عامٍ."},{"id":2964,"title":"استعادة محمد الرابع بن إسماعيل ملك غرناطة ثغر جبل طارق .","date":["العام الهجري :733","العام الميلادي :1332"],"text":"استنجد محمَّدُ الرابع بن إسماعيل مَلِكُ غرناطة بأبي الحَسَنِ علي بن عثمان مَلِك بني مرين لاستردادِ ثَغرِ جبل طارق من الأسبان الذين استولوا عليه سنة 709 فاستجاب أبو الحسَنِ لهذه الدعوة وأرسل جَيشًا بقيادةِ ابنه أبي مالك، فحصَلَت معركةٌ بَحَريَّةٌ أمام جبل طارق هُزِمَ فيها القشتاليون واستسلمت حاميةُ الجبل فاسترَدَّها المسلمون من الأسبان، ثم بعد فترة تم اغتيال محمد الرابع بن إسماعيل بتحريضٍ من مُنافِسيه في المُلكِ، فتَمَّ استخلاف أخيه أبي الحَجَّاج يوسف الأول بن أبي الوليد إسماعيل، وهو فتى في السادسة عشرة من عُمُرِه."},{"id":2965,"title":"وفاة قاضي القضاة بدر الدين ابن جماعة .","date":["العام الهجري :733","الشهر القمري : جمادى الأولى","العام الميلادي :1333"],"text":"قاضي القُضاةِ العالِمُ شَيخُ الإسلام بدر الدين أبو عبد الله محمد بن الشيخِ الإمام الزاهد أبي إسحاق إبراهيم بن سعد الله بن جماعة بن حازم بن صخر الكناني الحموي الأصل، وُلِدَ ليلة السبت رابع ربيع الآخر سنة 639 بحماة، وسَمِعَ الحديثَ واشتغل بالعلم، وحصَّل علومًا متعَدِّدة، وتقَدَّم وساد أقرانَه، وباشر تدريسَ القيمرية، ثم وليَ الحُكمَ والخَطابة بالقُدسِ الشريف، ثم نُقِلَ منه إلى قضاء مصر في الأيام الأشرفية، ثم وليَ قضاء الشامِ وجُمِعَ له معه الخطابةُ ومشيخةُ الشيوخِ وتدريسُ العادليَّة وغيرها مدة طويلة، كل هذا مع الرياسةِ والديانةِ والصِّيانةِ والوَرَع، وكَفِّ الأذى، وله التصانيفُ الفائقة النافعة، أشهَرُها تذكِرةُ السامع والمتكَلِّم في أدب العالم والمتعلم، وله غرر البيان في مبهمات القرآن، والمنهل الرَّوِيِّ في الحديث النبويِّ، وغيرها، وجمع له خطباً كان يخطُبَ بها، ثم نقل إلى قضاء الديار المصرية بعد وفاة الشيخ تقي الدين بن دقيق العيد، فلم يَزَل حاكِمًا بها إلى أن كُفَّ بَصَرُه وكَبِرَ وضَعُفَت أحواله، فاستقال فأقيل، ورُتِّبَت له الرَّواتِبُ الكثيرة الدارَّة إلى أن توفي ليلة الاثنين بعد عشاء الآخرة حادي عشرين جمادى الأولى، وقد أكمل أربعًا وتسعين سنة وشهرًا وأيامًا، وصُلِّيَ عليه من الغَدِ الظهر بالجامع الناصري بمصر، ودُفِنَ بالقرافة، وكانت جنازتُه حافلةً هائلةً رحمه الله."},{"id":2966,"title":"السلطان الناصر محمد بن قلاوون يمنع رمي البندق  .","date":["العام الهجري :733","الشهر القمري : رجب","العام الميلادي :1333"],"text":"رسم السُّلطانُ النَّاصِرُ محمَّدُ بن قلاوون بالمنعِ مِن رَميِ البُندُق، وألَّا تُباعَ قِسِيُّها ولا تُعمَل، وذلك لإفسادِ رُماةِ البندق أولادَ الناس، وأنَّ الغالِبَ على من تعاطاه اللُّواطُ والفِسقُ وقِلَّةُ الدين، ونودِيَ بذلك في البلادِ المصريَّة والشاميَّة."},{"id":2967,"title":"السلطان الناصر محمد بن قلاوون يأمر بضرب المنجمين وحبسهم .","date":["العام الهجري :733","الشهر القمري : شعبان","العام الميلادي :1333"],"text":"رسم السُّلطانُ النَّاصِرُ محمد بن قلاوون بتسليم المنَجِّمينَ إلى والي القاهرة فضُرِبوا وحُبِسوا؛ لإفسادهم حالَ النِّساءِ، فمات منهم أربعةٌ تحت العقوبة، وثلاثةٌ من المسلمين ونصرانيٌّ."},{"id":2968,"title":"السلطان الناصر محمد بن قلاوون يعمل بابًا جديدا للكعبة .","date":["العام الهجري :733","الشهر القمري : ذي القعدة","العام الميلادي :1333"],"text":"عَمِلَ السُّلطانُ النَّاصِرُ محمد بن قلاوون بابًا من خَشَبِ السنط الأحمر، وصَفَّحه بفِضَّة زِنتُها خمسة وثلاثون ألفَ درهم وثلاثمائة درهم، ومضى به الأميرُ سيف الدين برسبغا الساقي إلى مكَّة، فقُلِعَ باب الكعبة العتيق، ورُكِّبَ هذا الباب وأخذ بنو شيبةَ الباب العتيق، وكان من خَشَبِ الساسم المصَفَّح بالفِضَّة، فوجدوا عليه ستين رطلًا من فِضَّة تقاسَموها فباعوها كلُّ دِرهمٍ بدرهمين، لأجلِ التبَرُّك، (وهذا خطأٌ من وجهَينِ: الأول: أنَّه رِبًا. والثاني: أنَّه لا يُتبَرَّكُ بمثل هذه الأشياءِ، وإن كانت بابًا للكعبة!) وتُرِكَ خَشَبُ ذلك الباب داخِلَ الكعبة، وعليه اسمُ صاحِبِ اليمن في الفردتين، واحدةٌ عليها: اللهُمَّ يا وليُّ يا عليُّ، اغفِرْ ليوسُفَ بنِ عُمَرَ بنِ عليٍّ."},{"id":2969,"title":"سيل عظيم بالمدينة النبوية .","date":["العام الهجري :734","العام الميلادي :1333"],"text":"جاء بالمدينةِ النبَويَّة سَيلٌ عَظيمٌ أخَذَ جِمالًا كثيرةً وعشرين فَرَسًا، وخُرِّبَت عِدَّةُ دُورٍ."},{"id":2970,"title":"إلزام اليهود والنصارى بلباس خاص ببغداد .","date":["العام الهجري :734","العام الميلادي :1333"],"text":"ألزم صاحِبُ بغدادَ النصارى أن يلبَسوا العمائمَ الزُّرقَ، واليَهودَ أن يَلبَسوا العمائِمَ الصُّفرَ يُمَيِّزُهم عن المسلمينَ؛ اقتداءً بالسلطان المَلِك الناصِرِ بهذه السُّنَّة الحَسَنة."},{"id":2971,"title":"وفاة الحافظ العلامة ابن سيد الناس .","date":["العام الهجري :734","الشهر القمري : شعبان","العام الميلادي :1334"],"text":"هو الحافِظُ العلَّامة البارع، فتحُ الدين بن أبي الفتح محمد بن الإمام أبي عمرو محمد بن الحافظ أبي بكر محمد بن أحمد بن عبد الله بن محمد بن يحيى بن سيد الناس الربعي اليعمري الإشبيلي ثم المصري، وُلِدَ في العشر الأُوَل من ذي الحجة سنة 671، كان حافِظًا بارعًا أديبًا بليغًا مُتَرَسِّلًا، حَسَن المحاوَرةِ لَطيفَ العبارة، فصيحَ الألفاظ كامِلَ الأدوات لا تُمَلُّ مُحاضَرتُه، كريم الأخلاق زائِدَ الحياء، حسَن الشكل والعمَّة، وهو من بيتِ رياسة وعلم، وسَمِعَ الكثير وأجاز له الروايةَ عنهم جماعاتٌ من المشايخ، ودخل دمشقَ سنة تسعين فسَمِعَ من الكندي وغيره، واشتغل بالعِلمِ فبرع وساد أقرانَه في علوم شتى من الحديث والفقه والنحو من العربية، وعِلْم السير والتواريخ، وغير ذلك من الفنون، وقد جمع سيرةً حَسَنةً في مجَلَّدين المعروف باسم: عيون الأثر في فنون المغازي والسِّيَر، وشرح قطعة حسنة من أوَّلِ جامعِ التِّرمذي المعروف باسم النفح الشَّذِي في شرح جامع الترمذي، وله الشِّعرُ الرائق والفائق، والنَّثر الموافق، والبلاغةُ التامة، وحسن الترصيف والتصنيف، وله العقيدةُ السلفيَّة الموضوعة على الآيِ والأخبار والآثار والاقتفاء بالآثار النبوية، وله مدائِحُ في رسول الله صلى الله عليه وسلم حِسانٌ، منها: كتاب بشرى اللبيب في ذكر الحبيب، وله كتاب تحصيل الإصابة في تفضيل الصحابة، وكان شيخَ الحديثِ بالظاهرية بمصر، ولم يكُنْ في مصر في مجموعها مثلُه في حفظ الأسانيدِ والمتون والعِلَل والفِقهِ والمُلَح والأشعار والحكايات، توفِّيَ فجأة يوم السبت حادي عشر شعبان، وصلِّيَ عليه من الغد، وكانت جنازتُه حافلة."},{"id":2972,"title":"مقتل ياسور أحد ملوك المغول في الحج .","date":["العام الهجري :734","الشهر القمري : ذي الحجة","العام الميلادي :1334"],"text":"قُتِلَ ياسور أحَدُ ملوك المغول وقتَ رَميِ الجمرات، وكان من خَبَرِه أنَّ مَلِكَ الشرق أبا سعيد بن خربندا المغولي لما قُتِل جوبان أراد إقامةَ ياسور لأنه من عظماء القان التتر، فخُوِّفَ من شجاعته، وأنَّ جوبان كان يريد إقامتَه في الملك، فنَفَر منه أبو سعيد، ثم إنَّه استأذنه في الحَجِّ فأَذِنَ له، وقام له بما يليقُ به، ثم طلب أبو سعيد من المجدِ السلامي وكتب إلى السلطانِ يُعَرِّفُه بأمر ياسور، ويخوِّفُه منه أن يجتَمِعَ عليه المغول، ويسألُه قَتْلَه، فدفع السلامي كتاب أبي سعيد إلى مملوكِه قطلوبك السلامي فقَدِمَ على السلطان أول ذي القعدة من السنة الماضية، فأركَبَه السلطان النجيبَ في عاشِرِه إلى مكة، ومعه كتابٌ إلى الأمير برسبغا الحاجب وقد حَجَّ من مصر بطَلَبِ الشريف رُمَيثة وموافقته سرًّا على قتل ياسور، فقَدِمَ قطلوبك مكة أول ذي الحجة، فلم يوافِقْ رُمَيثة على ذلك، واعتذر بالخوفِ، فأعد برسبغا بعضَ نجابته من العُربان لذلك، ووعده بما ملأ عينَه، فلما قضى الحاجُّ النُّسُكَ من الوقوف والنحر، ورَكِبَ ياسور في ثاني يوم النحر لرميِ الجمار، ركب برسبغا أيضًا فعندما قارب ياسور الجَمرةَ وثب عليه النجاب، وضَرَبه فألقاه إلى الأرضِ، وهرب نحو الجَبَل، فتبعه مماليكُ برسبغا وقتلوه أيضًا، خشيةً مِن أن يَعتَرِفَ عليه، فاضطرب حجَّاجُ العراق وركبت فرسانُهم وأخذوا ياسور قتيلًا في دمائه، وساروا إلى برسبغا منكرينَ ما حلَّ بصاحِبِهم، فتبرَّأَ برسبغا من ذلك وأظهر الترحُّمَ عليه، وقَرَّر عندهم أن هذا الذي قتَلَ هو مَن له عليه ثأرٌ أو أحَدُ غرمائه، وإنكم كُفِيتُم أمْرَه، فإني أخذتُ لكم بثأرِه وقَتْلِ قاتله \"، فانصرفوا عنه وفي نفوسِهم منه شيء، وما زالوا له بالمرصاد وهو منهم محتَرِزٌ منهم حتى افترق ركبُ الحاجِّ العراقيين من المصريِّين بالمدينة النبوية، فأمِنَ برسبغا على نفسِه."},{"id":2973,"title":"قتل وتخريب بطرطوس وإياس على أيدي جيش حلب .","date":["العام الهجري :735","العام الميلادي :1334"],"text":"رجع جيشُ حلب إلى مدينة حلب بعد غَزوِهم بلادَ أذنة وطرسوس وإياس، وكان عَدَدُهم عشرةَ آلاف سوى من تَبِعَهم من التركمان، وقد خَرَّبوا وقَتَلوا خلقًا كثيرًا، ولم يعدم منهم سوى رجلٍ واحد غَرِقَ بنهر جاهان، ولكِنْ كان قَتْلُ الكُفَّار مَن كان عندهم من المسلمينَ في تلك البلاد نحوًا من ألف رجل، يوم عيد الفطرِ، فإنَّا لله وإنَّا إليه راجعونَ."},{"id":2974,"title":"وباء ومرض بالمدينة المنورة .","date":["العام الهجري :735","العام الميلادي :1334"],"text":"وقع بالمدينةِ النبويَّةِ وَبَاءٌ، فكان يموتُ في كُلِّ يَومٍ خَمسةَ عشر بمَرَض الخوانيق- داء يعسُرُ معه التنفس- ولم يُعهَدْ مثلُ هذا بالمدينةِ الشَّريفةِ."},{"id":2975,"title":"وفاة الشيخ صفي الدين إسحاق الأردبيلي مؤسس الطريقة الصفوية .","date":["العام الهجري :735","الشهر القمري : محرم","العام الميلادي :1334"],"text":"هو الشيخُ صفيُّ الدين إسحاقُ بن جبريل الأرْدَبيلي، ويقال: إنَّ نسبَه يرجعُ إلى موسى الكاظم, وهو مؤسِّسُ الطريقة الصفويَّة. ولِدَ صفيُّ الدين بأردبيل سنة 650. درس في مطلع ِحياتِه العلومَ الدينيَّةَ والعقليَّةَ في أردبيل. ثم صار واعظًا صوفيًّا في مدينة أردبيل، ثم أسَّس فرقةً صوفيةً تُسمَّى الإخوان، وقد كثُرَت هذه الفرقةُ في إقليم أذربيجان, ولَمَّا أدركته الجذبة- الجذبُ: مصطلحٌ صوفي يعني: حالًا من أحوالِ النفس يغيبُ فيها القلبُ عن عِلمِ ما يجري من أحوالِ الخَلقِ، ويتصِلُ فيها بالعالَمِ العلويِّ- رحل إلى شيراز، فنزل بخانقاه الشيخِ خفيفِ الشيرازي، واشتغل هناك مُدَّةً، ولقيَ الشيخَ سعدي الشيرازي، فاستفاد منه وسمع هناك خبَرَ الشيخِ زاهد الكيلاني، فقصد الرحلةَ إليه، فأخذ عنه الطريقةَ القادريَّةَ، ثمَّ عاد إلى بلَدِه، ثم إليه واشتغَلَ في خدمة الشيخ تاج الدين الكردي من أصحابِه مدةً إلى أن بلغ رتبةَ الإرشادِ وتزوَّج ابنتَه، ثم أجاز له بالرجوعِ إلى وطنه، فعاد وجلس على سجادة الإرشاد، فأقبل عليه أهلُ السلوك واجتمع عنده جمعٌ كثيرٌ من الأقطار، فبنى زاويةً مشهورةً به. ولَمَّا مَرِضَ شَيخُه بكيلان ذهب إلى عيادته فشَهِدَ جنازتَه وبنى على قبره، ثم عاد وأقام بزاويته مُرشدًا داعيًا مدة ثلاثين سنة، ثم قضى نحْبَه ودُفن بزاويته. وجلس مكانَه ابنُه صدر الدين موسى، وصفيُّ الدين هذا هو جَدُّ الصفويَّة المشهورةِ بقزلباش، وكان كثيرَ الأتباع جدًّا من الدراويش والمُريدين. وقيل: تشَيَّع صفيُّ الدين أو ابنُه صدرُ الدين موسى, وكان أتباعُ صفي الدين من السُّنَّة الشافعية ثم انقلبوا إلى شيعة؛ بسبب شيوخهم صفي الدين وأولاده وأحفاده، وقد قَوِيت طريقة صفي الدين وكثُر أتباعها في زمن أحفاده حتى استطاع أحدُهم وهو إسماعيل بن حيدر أن يتملَّك إيران سنة 907 ويؤسِّس فيها الدولة الصفوية الشيعية. توفي صفي الدين بأردبيل في محرَّم من هذه السنة."},{"id":2976,"title":"تعاقب أحفاد الأردبيلي في رئاسة الطريقة الصفوية إلى قيام دولتهم .","date":["العام الهجري :735","الشهر القمري : محرم","العام الميلادي :1334"],"text":"بعد وفاة صفي الدين الأرْدَبيلي مؤسِّس الطريقة الصفوية خلَفَه في مشيخة الطريقة ابنه صدر الدين موسى مدةً طويلة بلغت تسعًا وخمسين عامًا, وكانت السلاطين تعتقِدُ فيه وتزوره، وممن زاره والتمس بركته تيمورلنك، فسأله أن يطلبَ منه أي شيء، فقال له موسى: أطلب منك أن تطلِقَ كل من أخذته من بلاد الروم من التركِ، فأجابه إلى سؤاله فأطلقَ جميع أسرى الترك، فصار أهل الروم يعتقدون في الشيخ صدر الدين والمشايخ من ذريتِه، ولما توفي صدر الدين تولى ابنُه خواجة علي مشيخةَ الطريقة مدة 36 سنة، وكان الخواجة علي يميل للتشييع, ولما مات سنة 830 تولى بعده ابنُه إبراهيم الذي كان تشيُّعه واضحًا، فقد أدخل أتباعَه بصراعات مع أهل السنة في داغستان, ولَمَّا توفي سنة 851 خلفَه ابنه الأصغر جنيد، وكان شيعيًّا جَلْدًا متعصبًا للشيعة الإمامية, فلمَّا كثر مريدوه وأتباعه خافه السلطان جهانشاه التركماني صاحب أذربيجان، فأخرجهم من أردبيل فتوجَّه جنيد مع بعض مريديه إلى ديار بكر، وقُتِلَ جنيد في إحدى حروبه في مدينة شيروان سنة 861، وخلَفه ابنه حيدر الذي تزوَّج من بنت حسن أوزون الطويل, وكانت أمُّها كاترينا ابنة كارلو يوحنا ملك مملكة طرابزون اليونانية النصرانية, وحيدر هذا هو أوَّلُ من أمر أتباعَ الطريقة الصفوية أن يضعوا على رؤوسِهم قلنسوة مخروطية الشكل مصنوعة من الجوخ الأحمر، وسُمُّوا بقزلباش، وهي كلمة تركية تعني الرأس الأحمر, ولما قتل حيدر سنة 893 كان له ثلاثة أولاد: علي، إبراهيم، وإسماعيل، سجنهم الأمير يعقوب أمير آق قونيلو، ثم أُطلِقَ سراحهم بعد وفاة يعقوب، فذهب إسماعيل بن حيدر إلى مدينة كيلان على بحر قزوين، وحاول منذ صِغَره تجميع الصوفية والقزلباشية حوله؛ من أجل الانتقام مِن قتَلَة أبيه وجده، فتوجه إلى أمير دولة التركمان \"آق قونيلو\" سنة 907، وقتله وجلس على ملكِه بعد أن بايعته كلُّ قبائل التركمان، وأعلن دولته الصفويَّة."},{"id":2977,"title":"نائب طرابلس يطلب الإقالة بسبب حرامي بحري .","date":["العام الهجري :735","الشهر القمري : جمادى الآخرة","العام الميلادي :1335"],"text":"قُبِضَ على الأمير جمال الدين آقوش الأشرفي المعروفِ بنائب الكرك في يوم الخميس نصف جمادى الآخرة، وهو يومئذٍ نائِبُ طرابلس وسُجِنَ بقلعة صرخد، ثم نقِلَ في مستهل شوال إلى الإسكندرية فسُجِنَ بها، ونزل النشو إلى بيتِه بالقاهرة، وأخذ موجودَه كُلَّه وموجودَ حَريمِه، وعاقَبَ أستادراه، واستقَرَّ عِوَضَه في نيابة طرابلس الأميرُ طينال على عادته، ونُقِلَ بكتمر العلائي إلى نيابة حمص، عوضًا عن بشاش المتوفى، وسبب ذلك كلِّه أنَّه تراءى بطرابلس مرَكبٌ للفرنج في البحر، فرَكِبَ العسكر إلى الميناء، فدفعت الريحُ المركَبَ عن الميناء ثم أخذ الأميرُ آقوش في تجديد عمارة مركب هناك، وأنفق فيه من مالِه أربعينَ ألف درهم، فقَدِمَت مركب الفرنج، فركب العسكَرُ في المركب المستجَدِّ، وقاتلوا الفرنجَ، فقتلوا منهم جماعةً وغَنِموا مركَبَهم بما فيها، فادَّعى صاحِبُها أنَّه تاجِرٌ قَدِمَ بتجارته، فنُهِبَت أموالُه وقُتِلَت رجالُه، وذُكِرَ عنه بعضُ التجَّار أنه متحَرِّم لا تاجر، وأنَّه قَدِمَ في السنة الماضية إلى ميناء طرابلس وأخَذَ منها مركبًا، فكتب آقوش بذلك إلى السلطان، فأجيب بالشُّكرِ وحَمْل الفرنجي إلى السلطان، فحَمَله آقوش مقيدًا على البريد، فأكثَرَ الفرنجيُّ من التظلم، وتبرأ من التحَرُّم في البحر، وأنه قَدِمَ بتجارة وهدية للسُّلطانِ، فظَلَمَه نائب طرابلس وأخذ ما كان معه من التحَفِ وغيرها، فصَدَّقه السلطان، وكتب بإعادة مركَبِه إليه وجميعِ ما أُخِذ له، فأجاب النائبُ بأن المذكور حرامي يقطع الطريقَ على المسلمين، فلا يَسمَع السلطانُ قَولَه، وكتب إليه بالتأكيدِ في رَدِّ المركب عليه، فرَدَّها النائب عليه، وشَقَّ ذلك عليه، ثمَّ طلب آقوش الإعفاءَ من نيابة طرابلس فأُجيبَ بتخييره بين نيابةِ صرخد وبعلبك، وبَعَث السلطان إليه الأمير برسبعا الحاجب، فسار به إلى دمشق، فقَبَض عليه تنكز بدار السعادة، وحَمَلَه إلى صرخد."},{"id":2978,"title":"إسلام سديد الدولة اليهودي من نواب ملك المغول .","date":["العام الهجري :736","العام الميلادي :1335"],"text":"مَرَّ سديدُ الدولة ديانُ اليهودي بقارئٍ يقرأ قَولَه تعالى: {يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا} [النساء: 1], فوَقَف سديدُ الدولة واستعاده قراءتَها، وبكى بكاءً شَديدًا، وقد اجتمَعَ عليه الناسُ، ثم أعلن بكلمةِ الإسلام، فارتَجَّت بغداد لإسلامه، وغُلِّقَت أسواقُها، وخرج النِّساء والأولاد، فأسلم بإسلامِه سِتَّةٌ من أعيان اليهود، وسارعت العامَّةُ ببغداد إلى كنائِسِ اليهود، فخَرَّبوها ونَهَبوا ما فيها، وسديدُ الدولة هذا هو من نوابِ الملك المغولي أبو سعيدٍ."},{"id":2979,"title":"وفاة الملك أبي سعيد المغولي ملك التتار واضطراب أمر المغول بعده  .","date":["العام الهجري :736","الشهر القمري : ربيع الآخر","العام الميلادي :1335"],"text":"هو القانُ أبو سعيدٍ بهادِرُ بن القان محمد خربندا بن أرغون بن أبغا بن هولاكو المغولي ملك التتار، صاحِبُ العراق والجزيرة وأذربيحان وخراسان والروم. كان من خيارِ مُلوك التَّتار وأحسَنِهم طريقةً وأثبَتِهم على السنَّةِ وأقوَمِهم بها، وقد عَزَّ أهلُ السنة بزمانِه وذَلَّت الرافضة، بخلاف دولةِ أبيه، أبطَلَ عِدَّة مُكوس، وأراق الخمورَ ومَنَع مِن شُربِها، وهَدَم كنائِسَ بغداد ووَرَّث ذوي الأرحام، فإنَّه كان على مذهب أبي حنيفة، وكانت وفاتُه في الأردو بأذربيجان في ربيع الآخر من هذه السنة، وقد أناف على الثلاثين، وكانت دولته عشرين سنة، كان جلوسُه على التخت في أول جمادى الأولى سنة 717، وكانت وفاتُه بدار السلطنة بقراباغ، وهي منزِلُهم في الشتاء، ثم نُقِلَ إلى تربته بمدينته التي أنشأها قريبًا من السلطانيَّة بالقُربِ مِن جبالِ كيلان مدينة أبيه، وعُمُره إحدى عشرة سنة، ثم لم يقُمْ بعده للتتارِ قائِمةٌ، بل اختَلَفوا وتفَرَّقوا شَذَر مَذَر، وكان القائمُ من بعده بالأمرِ أربا كاؤن من ذرية أبغا، ولم يستمِرَّ له الأمرُ إلَّا قليلًا."},{"id":2980,"title":"أحوال مُلك التتار في الشرق بعد وفاة الملك أبي سعيد بن خربندا .","date":["العام الهجري :736","الشهر القمري : جمادى الأولى","العام الميلادي :1336"],"text":"بعد وفاةِ أبي سعيد بن خربندا مَلِك التتار قام بَعدَه أربا كاؤن بن صوصا بن سنجقان بن ملكتمر بن أريغبغا أخي هولاكو بمساعدة الوزير غياث الدين بن رشيد الدين, فلم يوافِقْه علي بادشاه حاكِمُ بغداد في الباطن، واستمال أولادَ سونتاي فلم يوافِقوه، فجمع علي بادشاه المغولَ عليه، وكتب إلى السلطانِ الناصر يَعِدُه بأنه يسَلِّمُ له بغداد ويكونُ نائبًا عنه بها، وسأله في إعانتِه بنجدة على أولاد سونتا تكون مقيمةً على الفرات، ففَرِحَ السلطان بذلك وأجابه بالشُّكرِ، وبعث إليه خمسةَ قواقل وخمسة سيوف، فقَوِيَ عزم علي بادشاه، وركِبَ إلى أولاد سونتاي، فاجتمعوا على الشيخ حسن بن أقبغا أيلخان سِبطِ أرغون بن أبغا بن هولاكو المعروف بالشيخ حَسَن بك الكبير النوين- بالأردو، وعرَّفوه انتماء علي بادشاه لصاحِبِ مِصرَ ونُصرتِه له، فكتب الشيخ حسن الكبير إلى السلطان يرَغِّبُه في نصرته على علي بادشاه، ويمُتُّ إليه بقرابتِه مِن أمِّه، فمطل بالجوابِ رجاءَ حُضورِ خَبَرِ علي بادشاه، فقَدِمَ الخبر بأن علي بادشاه لَمَّا ركب لحرب أولاد سونتاي بلغه اجتماعُهم والشيخ حسن مع عِدَّة من الأمراء، وأنَّ أربا كاؤن هرب لتفَلُّلِ أصحابه عنه، وأشِيعَ عنه أنه قُتِلَ، وقَوِيَ علي بادشاه بمن انضَمَّ إليه من المغول، فسار أولادُ سونتاي والشيخ حسن إلى جهة الروم، وانفرد علي بادشاه بالحُكمِ في الأردو، وأقام موسى بن علي بن بيدو بن طرغاي بن هولاكو على تخت الملك."},{"id":2981,"title":"اعتقال السلطان الناصر للخليفة العباسي المستكفي بالله .","date":["العام الهجري :736","الشهر القمري : ذي القعدة","العام الميلادي :1336"],"text":"أمر السُّلطانُ النَّاصِرُ محمَّد بن قلاوون في ثالث عشر ذي القعدة بنَقلِ الخليفة المستكفي بالله أبو الربيع سليمان مِن سَكَنِه بمناظر الكبش إلى قلعةِ الجبل، وأُنزِلَ حيث كان أبوه الحاكِمُ نازلًا، فسكن برج السباع دائمًا بعيالِه، ورُسِمَ على الباب جاندار بالنوبة، وسَكَن ابنُ عَمِّه إبراهيم في برج بجوارِه ومعه عياله، ورُسِمَ عليه جاندار الباب، ومُنِعا من الاجتماعِ بالنَّاسِ."},{"id":2982,"title":"استيلاء بني مرين على تلمسان وانتهاء دولة بني زيان .","date":["العام الهجري :737","العام الميلادي :1336"],"text":"توجَّه أبو الحَسَنِ علي بن عثمان المريني من فاس على رأسِ جَيشٍ واستولى على تلمسان التي كانت تحتَ حكم آل زيان، والقضاء على أبي تاشفين عبد الرحمن بن موسى خامس ملوك آل زيان من بني عبد الواد، وبذلك انتهى حكمُ بني زيان وامتَدَّ سلطان المرينيين إلى المغرِبِ الأوسَطِ."},{"id":2983,"title":"نهاية الدولة الإيلخانية وقيام الدولة الجلائرية الشيعية .","date":["العام الهجري :737","العام الميلادي :1336"],"text":"بعد مَوتِ أبي سعيد تولى أربا كاؤن معز الدين لكنَّه لم يدُمْ سوى ثلاثة أشهر، حيث كان حَسَنُ بن حسين بن أقبغا بن هولاكو معتقَلًا في بلاد آسيا الصغرى، فأُطلِقَ سَراحُه بعد موت أبي سعيد فانطلق إلى بغداد فخلع أربا كاؤن هذا وجرت بينهم حروبٌ كثيرة كان نهايتها خلع أربا كاؤن وتنصيب محمد بن عنبرجي الإيلخاني، وتمكَّن حسن بن حسين من بغداد وتبريز وأسَّسَ الدولة الجلائرية، ثمَّ إنَّ حسن بن دمرداش سار من آسيا الصغرى فغلب على تبريز وقَتَل محمد بن عنبرجي، فسار حَسَنُ بن حسين الجلائري إلى بغداد واستقَرَّ بها، واستقر ابن دمرداش في تبريز ونَصب صاتبيك أختَ أبي سعيد سلطانةً على تبريز وزَوَّجَها أحد أسباط هولاكو واسمُه سليمان، ثم إنَّ أولاد جوبان الذي كان نائبًا لأبي سعيد استولَوا على أذربيجان وتبريز."},{"id":2984,"title":"إنشاء أول جامعة عثمانية (مدرسة) في أزمير التي فتحها أورخان  .","date":["العام الهجري :737","العام الميلادي :1336"],"text":"كان سلاطينُ العُثمانيِّينَ حَريصينَ على أن يَبنُوا في كُلِّ بَلَدٍ يَفتَحونَه مَسجِدًا، ويُخَصِّصونَ له الأئمَّة والفقهاء، وينشرون الإسلامَ بين أهل هذا البلد، وكان أوَّلُ مسجد أمر ببنائه سنة 687 في عهد أرطغرل والد عثمان، وكان ذلك قبل إعلانِ الدولة رسميًّا. وفى عهد أورخان بن عثمان تم تشييدُ مسجد بورصة، وألحق به بناءًا كبيرًا ليكونَ مَدرسةً للعُلومِ الشَّرعية. وفي سنة 737 سَقَطت مدينةُ أزميت في يد العثمانيين, فبنوا فيها مسجدًا كبيرًا، وبجواره مدرسةٌ ضخمة لتدريس العلوم وعُهد بإدارتها للشيخِ داوود القصيري الذي تعلَّم في مصر، واعتَبَرَ بعض المؤرخين الغربيين هذه المدرسةَ أوَّلَ جامعةٍ عُثمانية."},{"id":2985,"title":"الإفراج عن الخليفة العباسي ثم نفيه إلى بلاد قوص .","date":["العام الهجري :737","الشهر القمري : ربيع الأول","العام الميلادي :1336"],"text":"أُفرِجَ عن الخليفة من سِجنه بالقلعة يوم الأربعاء من ربيع الأول، فكانت مُدَّةُ اعتقاله خمسة أشهر وسبعة أيام، ثم أُمِرَ به فأخرج إلى قوص، ومعه أولادُه وابنُ عَمِّه، وكُتِبَ لوالي قوص أن يحتَفِظَ بهم، وكان سَبَبُ ذلك أن السلطان لما نزل عن المُلكِ في سنة 708، وحصل الاجتماعُ على المظَفَّر بيبرس وقَلَّدَه المستكفي بالسلطنة، نَقَمَها عليه السلطانُ النَّاصِرُ وأسَرَّها له، ثم لما قام السلطانُ لاسترجاع مُلكِه، جَدَّد المستكفي للمظَفَّر الولاية، ونُسِبَت في السلطان أقوالٌ إليه حَمَلت السلطان على التحامُل عليه، فلما عاد السلطانُ إلى الملك في سنة 709 أعرض عن المستكفي كلَّ الإعراض، ولم يزَلْ يكَدِّرُ عليه المشارب حتى تَرَكه في برج بالقلعة في بَيتِه وحَرَمِه وخاصَّتِه، فقام الأميرُ قوصون في أمره، وتلَطَّف بالسلطان إلى أن أنزله إلى داره، ثم نُسِبَ إلى ابنه صَدَقة أنه تعَلَّق ببعض خاصة السلطان، وأن ذلك الغلام يتردَّدُ إليه، فنُفِيَ الغلام وبلغ السلطان أنَّه هو يكثر من اللهو في داره التي عَمَرها على النيل بخَطِّ جزيرة الفيل، وأن أحد الجمدارية- حامل ملابس السلطان- يقال له أبو شامة جميل الوجهِ ينقطع عنده ويتأخَّرُ عن الخدمة، فقُبِضَ على الجمدار وضُرب، ونفي إلى صفد، وضُرِبَ رجل من مؤذني القلعة- اتُّهِمَ أنه كان السفير بين الجمدار وبين الخليفة- حتى مات، واعتُقِلَ الخليفة، ثمَّ لَمَّا أُفرِجَ عنه اتُّهِمَ أنه كتب على قصة رُفِعَت إليه \"يحمل مع غريمه إلى الشرع\"، فأحضره السلطان إلى القلعة ليجتَمِعَ به بحضرة القضاء، فخيله قاضي القضاة جلال الدين القزويني من حضوره أن يَفرُطَ منه كلامٌ في غَضَبِه يَصعُبُ تَدارُكُه، فأعجَبَ السلطان ذلك، وأمر به أن يخرُجَ إلى قوص، فسار بصحبة الأمير سيف الدين قطلوا تمرقلي في يوم السبت تاسع عشر ذي الحجة، بجميع عيالِه وهم مائة شخص، وكان مُرَتَّبُه في كل شهر خمسة آلاف درهم، فعُمِلَ له بقوص ثلاثة آلاف درهم، ثم استقَرَّ ألف درهم، فاحتاج حتى باع نساؤُه ثيابَهنَّ."},{"id":2986,"title":"وفاة الشيخ العالم الزاهد ابن الحاج المالكي  .","date":["العام الهجري :737","الشهر القمري : جمادى الأولى","العام الميلادي :1337"],"text":"هو الشَّيخُ الزَّاهِدُ أبو عبد الله محمد بن محمد بن محمد بن الحاج الفاسي المغربي نزيلُ مِصرَ العَبدري الفقيه المالكي عُرِفَ بابنِ الحاجِّ، وأخذ عن جماعةٍ منهم الشيخ أبو عبد الله محمد بن سعيد بن أبي جمرة، قَدِمَ القاهرة وسَمِعَ بها الحديث وحَدَّث بها وهو أحدُ المشايخ المشهورين بالزُّهدِ والخير والصلاح، صَحِبَ جماعة من الصلحاء أربابِ القلوب وتخَلَّق بأخلاقهم وأخذ عنهم الطريقةَ, وصَنَّف كتابه المشهور \"المدخل إلى تنمية الأعمال بتحسين النيات والتنبيه على بعض البدع والعوائد التي انتحلت وبيان شناعتها وقبحها\" قال عنه ابن حجر: \" جمع ابن الحاجِّ كتابًا سَمَّاه المدخَل كثير الفوائد كشف فيه من معايبَ وبِدَع يفعلها الناسُ ويتساهلون فيها، وأكثَرُها مما ينكَرُ وبَعضُها مما يُحتَمَل\". #قال الألباني عن هذا الكتاب ما نصه: \"قولُ بَعضِهم: إنه ينبغي ألَّا يذكُرَ حوائِجَه ومغفرةَ ذُنوبِه بلِسانِه عند زيارةِ قَبرِه صَلَّى الله عليه وآله وسلم لأنَّه أعلَمُ منه بحوائِجِه ومصالحه! ومما يؤسَفُ له أن هذه البدعة واللتين بعدها قد نقلتها من «كتاب المدخل» لابن الحاج (1/ 259، 264) حيث أوردها مسلِّمًا بها كأنَّها من الأمور المنصوصِ عليها في الشِّريعةِ، وله من هذا النحو أمثلة كثيرة سبق بعضُها دون التنبيه على أنها منه، وسنذكر قسمًا كبيرًا منها في الكتابِ الخاصِّ بالبدع إن شاء الله تعالى، وقد تعجَّبَ من ذلك لِما عُرِف أن كتابه هذا مَصدرٌ عظيم في التنصيص على مفردات البدع، وهذا الفصل الذي خَتَمتُ به الكتاب (أحكام الجنائز) شاهِدٌ عدل على ذلك، ولكِنَّك إذا علمت أنَّه كان في عِلمِه مُقَلِّدًا لِغَيره، ومتأثرًا إلى حد كبير بمذاهِبِ الصوفية وخُزَعبلاتها، يزول عنك العَجَبُ وتزداد يقينًا على صِحَّةِ قول مالك: \"ما مِنَّا من أحد إلا رَدَّ ورُدَّ عليه الا صاحِبُ هذا القبر\" صلَّى الله عليه وآله وسلم, و قوله- ابن الحاج-: لا فَرقَ بين موتِه صَلَّى الله عليه وآله وسلم وحياتِه في مشاهدتِه لأُمَّتِه ومعرفتِه بأحوالِهم ونيَّاتِهم وتحَسُّراتهم وخواطِرِهم! قال شيخ الإسلام في \"الرد على البكري\" (ص 31): \"ومنهم من يظنُّ أن الرَّسولَ أو الشيخَ يَعلَمُ ذنوبه وحوائِجَه وإن لم يذكُرْها، وأنه يَقدِرُ على غفرانِها وقضاء حوائجه ويَقدِرُ على ما يقدِرُ الله، ويَعلَمُ ما يعلم الله، وهؤلاء قد رأيتُهم وسَمِعتُ هذا منهم وعنهم شيوخٌ يقتدى بهم، ومُفتون وقضاة ومدرسون! والله المستعان، ولا حول ولا قوة إلا بالله\" توفي ابن الحاج عن بضع وثمانين، وكانت وفاته في العشرين من جمادى الأولى، ودُفِنَ بالقرافة وقد عَلَت سِنُّه وكُفَّ بَصَرُه، وكانت جنازتُه عظيمةً."},{"id":2987,"title":"مطر عظيم بمكة يغمر الكعبة .","date":["العام الهجري :738","الشهر القمري : جمادى الأولى","العام الميلادي :1337"],"text":"في عاشر جمادى الأولى استهَلَّ الغيث بمكَّةَ مِن أول الليل، فلما انتصف الليلُ جاء سيلٌ عظيمٌ هائِلٌ لم يُرَ مِثلُه من دهر طويل، فخَرَّب دورا كثيرةً نَحوًا من ثلاثين أو أكثر، وغَرِقَ جماعة وكَسَرَ أبواب المسجد، ودخل الكعبةَ وارتفع فيها نحوًا من ذراعٍ أو أكثر."},{"id":2988,"title":"تسيير جيش إلى سيس .","date":["العام الهجري :738","الشهر القمري : شعبان","العام الميلادي :1338"],"text":"توجَّهت تجريدةٌ- جيش لا رجَّالةَ فيه- في خامس عشر شعبان إلى بلاد سيس، وسبَبُ ذلك وصول رسول القان موسى وعلي بادشاه بطلب النَّجدة على الشيخ حسن الكبير وطغاي بن سونتاي وأولاد دمرداش ليكون علي بادشاه نائب السلطنة ببغداد، فاستشار السلطانُ نائب الشام والأمراء، واستقَرَّ الرأي على تجريد العسكر نحو سيس؛ فإن تكفور نقض الهُدنةَ بقَبضِه على عِدَّة مماليك وإرسالِهم إلى مدينة إياس، فلم يُعلَمْ خَبَرُهم وقَطَع الحَملَ المقَرَّر عليه، ويكون في ذلك إجابةُ علي بادشاه إلى ما قَصَده من نزول العسكر قريبًا من الفرات، مع معرفة الشيخ حسن بأنا لم نساعِدْ علي بادشاه عليه، وإنما بعثنا العسكرَ لغزو سيس، وعَمِلَ مُقَدَّم العسكر الأمير أرقطاي ويكون في الساقة، ويتقَدَّم الجاليش صحبة الأمير طوغاي الطبَّاخ ومعهما من الأمراء قباتمر وبيدمر البدري وتمر الموساري وقطلوبغا الطويل، وجوكتمر بن بهادو وبيبغا تتر حارس الطير، ومن أمراء الشَّام قطلوبغا الفخري مُقَدَّم الجيش الشامي، وكتب بخروجِ عَسكَرِ دِمشقَ وحماة وحلب وحمص وطرابلس إلى ناحية جعبر، فإذا وصل عسكرُ مصر إلى حلب عادت عساكر الشامِ ثم مَضَوا جميعًا إلى سيس، فيكون في ذلك صِدقُ ما وعد به علي بادشاه، وبلوغ الغَرَض من غزو سيس فسار العسكرُ من القاهرة في ثاني عشر شعبان، وتوجه الأمير تنكز إلى محل ولايته."},{"id":2989,"title":"فتح قلعة إياس من بلاد سيس .","date":["العام الهجري :738","الشهر القمري : شوال","العام الميلادي :1338"],"text":"لما سار الجيش الذي قَدِمَ من القاهرة في ثاني عشر شعبان، وقَدِموا دمشق تلقَّاهم الأمير تنكز، ولم يعبأْ تنكز بالأمير أرقطاي مُقَدَّم العسكر لِما في نفسه منه، ومَضَوا إلى حلب، فقدموها في رابع عشر رمضان، وأقاموا بها يومين فقدم الأمير قطلوبغا الفخري بعساكرِ الشام، وقد وصل إلى جعبر ثمَّ ساروا جميعًا يومَ عيد الفطر، ومعهم الأميرُ علاء الدين ألطبغا نائب حلب، وهو مُقَدَّم على العسكر جميعًا، حتى نزلوا على الإسكندرونة أوَّلَ بلاد سيس، وقد تقَدَّمَهم الأمير مغلطاي الغزي إليها بشهرينِ حتى جهَّزَ المجانيق والزحَّافات والجسور الحديد والمراكِبَ وغير ذلك لعبور نهر جهان، فقَدِمَ عليهم البريد من دمشق بأن تكفور وعَدَ بتسليم القلاع للسلطان، فلْتُرَدَّ المجانيق وجميع آلات الحصار إلى بغراس، ولْيَقُمِ العسكر على مدينة إياس حتى يَرِدَ مرسوم السلطان بما يُعتَمَدُ في أمرهم وكانت التراكمين قد أغاروا على بلاد سيس، ومعهم عسكَرُ ابن فرمان فتركوها أوحشَ مِن بطن حمار، فبعث تكفور رسُلَه في البحر إلى دمياط، فلم يأذَن السلطان لهم في القدومِ عليه، من أجل أنهم لم يعلموا نائِبَ الشام بحضورِهم، فعادوا إلى تكفور، فبعث تكفور بهديَّة إلى تنكز نائب الشام، وسأله مَنْعَ العسكر من بلاده، وأنه يسَلِّمُ القلاع التي من وراء نهر جهان جميعًا للسلطان، فكاتب تنكز السلطانَ بذلك، وبعث أوحَدَ المهمندار إلى الأمير علاء الدين ألطبغا نائِبِ حلب وهو المقَدَّم على العسكر جميعًا بمَنعِ الغارة ورَدِّ الآلات إلى بغراس، فردَّها ألطبغا وركب بالعسكَرِ إلى إياس، فقَدِمَها يوم الاثنين ثاني عشر شوال، وكانت إياس قد تحصَّنت، فبادر العسكَرُ وزحف عليها بغير أمرِه، فكان يومًا مهولًا، جُرح فيه جماعة كثيرة، واستمَرَّ الحِصارُ إلى يوم الخميس خامس عشره، وأحضر نائب حلب خمسين نجارًا وعَمِلَ زحافتين وستارتين ونادى في الناس بالركوبِ للزحف، فاشتد القتالُ حتى وصلت الزحَّافات والرجال إلى قريب السورِ، بعدما استُشهِدَ جماعة كثيرة، فترجَّلَ الأمراء عن الخيول لأخذِ السور، وإذا بأوحد المهمندار ورسل تكفور قد وافَوا برسالة نائِبِ الشام، فعادُوا إلى مخَيَّمِهم فبلَّغَهم أوحَدُ المهنمدار أن يكفوا عن الغارة، فلم يوافقوه على ذلك، واستقر الحالُ على أن يسلموا البلادَ والقلاع التي شرقي نهر جهان، فتسَلَّموا منهم ذلك، وهو مُلكٌ كبير، وبلادٌ كثيرة، كالمصيصة، وكويرا، والهارونية، وسرفندكار، وإياس، وباناس، وبخيمة، والنقبر، وغير ذلك. وعلى أن تُسَلَّم إياس بعد ثمانية أيام، فلما كان اليومُ الثامن أرسل تكفور مفاتيحَ القلاع، على أن يُرَدَّ ما سُبِيَ ونُهِبَ من بلاده، فنُودِيَ بِرَدِّ السَّبيِ، فأُحضِرَ كثير منه، وأخرب الجسر الذي نُصِبَ على نهر جهان، وتوجَّه الأمير مغلطاي الغزي فتسَلَّمَ قلعة كوارة وكانت من أحصن قلاع الأرمن، ولها سورٌ مساحته فدان وثلث وربع فدان، وارتفاعه اثنان وأربعون ذراعًا بالعَمَل، وأنفق تكفور على عمارته أربعَمائة ألف وستين ألف دينار، وتسَلَّم العسكر إياس، وهدم البرج الأطلس في ثمانية أيام، بعدما عَمِلَ فيه أربعون حَجَّارًا يومين وليلتين حتى خرج منه حجَرٌ واحد، ثمَّ نُقِبَ البرج وعُلِّقَ على الأخشاب، وأُضرِمَت فيه النار، فسَقَط جميعه، وكان برجًا عظيمًا، بلغ ضمانُه في كل شهر لتكفور مبلغ ثلاثين ألف دينار حسابًا عن كلِّ يومٍ ألف دينار سوى خَراجِ الأراضي، وكان ببلدة إياس أربعمائة خمَّارة وستمائة بَغِيٍّ، وكان بها في ظاهرها ملَّاحة تضمن كل سنة بسبعمائة ألف درهم، ولها مائتان وستة عشر بستانًا تغرس فيها أنواع الفواكه، ودور سورها فدانان وثلثا فدان، ثم رحل العسكَرُ عن إياس بعدما قاموا عليها اثنين وسبعين يومًا، فمر نائِبُ حلب على قلعة نجيمة وقلعة سرفندكار وقد أخربهما مغلطاي الغزي حتى عبَرَ بالعسكر إلى حلب في الرابع عشر من ذي الحجة."},{"id":2990,"title":"وفاة الحافظ المؤرخ علم الدين البرزالي  .","date":["العام الهجري :739","الشهر القمري : ذي الحجة","العام الميلادي :1339"],"text":"هو الحافِظُ المؤَرِّخ عَلَم الدين القاسم بن محمد بن يوسف بن محمد البرزالي الأشبيلي الشافعي، وُلِدَ بدمشق سنة 665, من أُسرةٍ عِلميَّة جاءت من المغرب، وكانت أسرتُه قد نزلت إشبيليَّةَ، ثم رَحَلت إلى الشام وبرزالة: قبيلة قليلة جدًّا، كان البرزالي محدِّثًا حافظًا فاضلًا، سَمِعَ الكثير ورحل إلى البلاد وحصَّل ودأب وسَمِعَ خلائِقَ كثيرةً تزيد عِدَّتُهم على ألفي شيخ، وحَدَّث وخرَّج وأفاد وأفتى وصَنَّف تاريخًا على السنين، رحل إلى بعلبك وحلب ومصر، تولى مشيخة دار الحديث بدمشق ومعها المدرسة النورية، قال ابن كثير: \"قرأ شيئًا كثيرًا، وأسمع شيئًا كثيرًا، وكان له خَطٌّ حَسَن، وخُلُق حسن، وهو مشكورٌ عند القضاة ومشايخه أهل العلم. سمعت العلامة ابن تيمية يقول: نَقْلُ البرزالي نَقْرٌ في حَجَر, وكان أصحابُه من كل الطوائف يحبُّونه ويكرمونه، وكان له أولادٌ ماتوا قبله، وكَتَبَت ابنته فاطمة البخاريَّ في ثلاثة عشر مجلَّدًا فقابله لها، وكان يقرأُ فيه على الحافظ المِزِّي تحت القبة، حتى صارت نسختُها أصلًا مُعتَمَدًا يكتب منها الناس، وكان شيخَ حديث بالنورية، وفيها وَقَف كُتُبَه بدار الحديث السنية، وبدار الحديث القوصية وفي الجامع وغيره، وعلى كراسي الحديث، وكان متواضِعًا مُحَبَّبًا إلى الناس، متودِّدًا إليهم، له مُصَنَّف المعجم الكبير في الحديث. وكتاب \"المقتفى على كتاب الروضتين\"، توفي بخليص وهو مُحرِم في رابع ذي الحجة عن أربع وسبعين سنة, فغُسِّلَ وكُفِّنَ ولم يُستَرْ رأسُه، وحمله الناسُ على نعشِه وهم يبكون حولَه، وكان يومًا مشهودًا."},{"id":2991,"title":"حسن الجلائري يطلب من السلطان الناصر عسكرا لاستلام بغداد .","date":["العام الهجري :740","العام الميلادي :1339"],"text":"قَدِمَ رَسولُ الشيخ حسن بن الأمير حسين بن آقبغا بن أيدكين سبط القان أرغون أبغا بن هولاكو بن طولي بن جنكيزخان متولي العراق، بكتابه يتَضَمَّنُ طَلَبَ عسكر يتسَلَّمُ بغداد والمَوصِل وعراق العجم ليقامَ بها الدعوةُ للسلطان الناصر محمد بن قلاوون، وسأل أن يَبعَثَ السلطان إلى طغاي بن سونتاي في الصلحِ بينه وبين الشيخ حسن، فأجيب إلى ذلك، ووُعِدَ بتجهيز العسكر، ورَكِبَ أمير أحمد قريب السلطان إلى طغاي ومعه هدية لينظم الصلحَ بينه وبين الشيخِ حسن."},{"id":2992,"title":"إنشاء المدرسة الأقبغاوية في الجامع الأزهر .","date":["العام الهجري :740","العام الميلادي :1339"],"text":"أنشأها الأمير علاء الدين أقبغا عبد الواحد، مقدَّم المماليك في عهد السلطان الناصر محمد بن قلاوون. وكان موضِعُ هذه المدرسة دارًا للأمير الكبير عز الدين أيدمر الحلي. وعندما تمَّ بناءُ المدرسة قرَّر فيها الأميرُ أقبغا درسًا للشافعية، ودرسًا للحنفية، ورتَّب لها ما يلزمُها من المستخدَمين. وظلَّت هذه المدرسة عامرةً إلى سنة 845 هـ / 1442م, ويشغلُها الآن جزءٌ من مكتبةِ الجامع الأزهر."},{"id":2993,"title":"توالي غزوات الأسبان على غرناطة .","date":["العام الهجري :740","العام الميلادي :1339"],"text":"والى ألفونسو الحادي عشر مَلِكُ قشتالة غزواتِه على مملكةِ غرناطة؛ مما اضطر أبا الحَجَّاج يوسف ملك غرناطة أن يستنجِدَ بملك بني مرين أبي الحَسَنِ علي بن عثمان، فأرسل إليه الأخيرُ جَيشًا بقيادة ابنه أبي مالك، فواجه هذا الجيشُ جيش ثلاث دول هي قشتالة وأراغون والبرتغال، فكانت نهايةُ المعركة موتَ أبي مالك وانهزام الجيش المُسلِم."},{"id":2994,"title":"وفاة النشو القبطي ناظر الخاص للسلطان بعد أن كثر ظلمه للرعية .","date":["العام الهجري :740","الشهر القمري : ربيع الآخر","العام الميلادي :1339"],"text":"هو شَرَفُ الدين عبد الوهاب بن التاج فضل الله المعروف بالنشو القبطي ناظِرُ الخاص للسلطان، كان أبوه يكتُبُ عند الأمير بكتمر الحاحب وهو ينوب عنه، ثم انتقل إلى مباشرةِ ديوان الأمير أركتمر الجمدار، وعندما جمَعَ السلطان الناصر كتَّاب الأمراء, فرآه وهو واقِفٌ وراء الجميعِ وهو شابٌّ طويل نصراني حلوُ الوجه فاستدعاه وقال: أيش اسمك؟ قال: النشو، فقال: أنا أجعلك نشوي، ثمَّ إنه رتَّبَه مستوفيًا في الجيزية، وأقبلت سعادته، فأرضاه فيما يندبه إليه وملأ عينيه, ثم نقله إلى استيفاء الدولة فباشر ذلك مدة، ثم نقل إلى نظر الخاص مع كتابة ابن السلطان، وحَجَّ مع السلطان في تلك السنة وهي سنة 732 ولما كان في الاستيفاء وهو نصراني, وكانت أخلاقُه حسنة وفيه بِشرٌ وطلاقة وجه وتسَرُّع إلى قضاء حوائج الناس، وكان الناس يحبونه، فلما تولى الخاص وكثُرَ الطلب عليه من السلطان, و أُكرِهَ حتى أظهَرَ الإسلام, فبلغ ما لم يبلُغْه أحَدٌ من الأقباط في دولة الترك- المماليك- وتقَدَّمَ عند السلطان على كل أحد، وخَدَمه جميع أرباب الأقلام، وزاد السلطانُ في الإنعامات والعمائر عليه, وزَوَّج بناته واحتاجَ إلى الكُلَف العظيمة المُفرِطة الخارجة عن الحَدِّ، فساءت أخلاقُه وأنكر مَن يَعرِفُه، وفُتِحَت أبواب المصادرات للكتَّاب ولِمَن معه مال, وكان محضرَ سوءٍ لم يشتَهِرْ عنه بعدها شيءٌ من الخير، وجمع من الأموال ما لم يجمَعْه وزير للدولة التركية، وكان مُظَفَّرًا، ما ضرب على أحدٍ إلا ونال غَرَضَه منه بالإيقاع به وتخريبِ دياره، وقُتِلَ على يديه عِدَّةٌ من الولاة والكتَّاب، واجتهد غايةَ جُهدِه في قتل موسى بن التاج إسحاق، وعاقبه ستَّة أشهر بأنواع العقوبات، من الضَّربِ بالمقارع والعَصرِ في كعابه وتسعيطِه - الاستنشاق بالأنف- بالماء والملح وبالخل والجير وغير ذلك، مع نحافة بدنه ومرضه بالربو والحمى، فلم يَمُت، وعاش التاج موسى هذا ثلاثين سنة بعد هلاك النشو، وكان النشوُ هذا بلغ منه في أذيَّة الناس بالمُصادَرات والضرائب الشيء الكثير الكثير، مِمَّا كاد أن يخرب الديارَ كُلَّها، فشكا منه كُلُّ أحد: الفقير والغني، والأمير والحقير، فلم يسلَمْ مِن ظُلمِه وأخْذِ المال منه أحدٌ، وكل ذلك يدَّعي الفَقرَ وقِلَّة المال وأنه لا يأخُذُ لِنَفسِه شيئًا، ولما مات بعد أن اعتُقِلَ لكثرة الشكاوى والتحريضات حُصِّلَت أمواله فكانت خارجةً عن الحصر، ولو كتبت لخرجت عن الحد المعهودِ، فهي تحتاج إلى عِدَّة صفحات مِمَّا كان له من مالٍ عَينٍ وبضائِعَ وإقطاعاتٍ وحواصِلَ وحيواناتٍ وغَيرِها من الجوهر واللؤلؤ ما يفوق الحَصرَ، توفي في يوم الأربعاء ثاني ربيع الآخر، ثم إنَّه بعد موته وُجِدَ أنه ما يزال غير مختونٍ، فدُفِنَ بمقابر اليهودِ."},{"id":2995,"title":"وفاة الخليفة العباسي المستكفي بالله بمصر وخلفه الواثق بالله إبراهيم .","date":["العام الهجري :740","الشهر القمري : شعبان","العام الميلادي :1340"],"text":"هو الخليفةُ المستكفي بالله أبو الربيع سليمان ابن الخليفة الحاكِمُ بأمر الله أبو العباس أحمد بن الحسن بن أبي بكر بن أبي علي بن الحسن العباسي، توفِّيَ بمدينة قوص في منفاه، عن ست وخمسين سنة وستة أشهر وأحد عشر يومًا، في خامِس شعبان، وكانت خلافتُه تسعًا وثلاثين سنة وشهرين وثلاثة عشر يومًا، ثم خُطِبَ للخليفة الواثق بالله إبراهيم بن محمد المستمسك بن أحمد الحاكم بأمر الله، وذلك أنَّ الخبَرَ قَدِمَ في يوم الجمعة ثاني عشر شعبان بموت الخليفة المستكفي بالله أبي الربيع سليمانَ بقَوصٍ بعد موتِ ابنه صدقة بقليلٍ، وأنه اشتَدَّ جزعه عليه، وأنه قد عَهِدَ لولده أحمد بشهادةِ أربعين عَدلًا وأثبَتَ قاضي قوص ذلك، فلم يُمضِ السُّلطانُ عَهدَه."},{"id":2996,"title":"أخذ السلطان الناصر البيعة بالخلافة لإبراهيم الواثق بالله .","date":["العام الهجري :740","الشهر القمري : شعبان","العام الميلادي :1340"],"text":"كان الخليفةُ المستكفي بالله قد أوصى بالخلافةِ مِن بعده لابنه أحمد، لكِنَّ السلطانَ النَّاصِرَ لم يُمضِ للسلطان عهده, وكان قد بايع لإبراهيمَ بن محمد المستمسك بن أحمد الحاكم بأمر الله ولَقَّبَه بالواثق بالله, وفي يوم الاثنين خامس عشر شعبان طلب الناصِرُ إبراهيمَ الواثق بالله، وأجلسه بجانِبِه وحادَثَه، ثم قام إبراهيم وخرج معه الحُجَّاب بين يديه، ثم طلع إلى السلطانِ في يوم الاثنين ثالث عشر رمضان، وقد اجتمع القضاةُ بدار العدل على العادة، فعَرَّفَهم السلطان بما أراد من إقامةِ إبراهيم في الخلافةِ وأمَرَهم بمبايعته، فأجابوا بعَدَمِ أهليَّتِه، وأنَّ المستكفيَ عَهِدَ إلى ولده أحمَدَ بشَهادةِ أربعين عدلًا وحاكِمِ قوص، ويحتاج إلى النَّظَرِ في عهده، فكتب السلطانُ بطلب أحمد وعائلةِ أبيه، وأقام الخُطَباء بديار مِصرَ والشام نحو أربعة أشهر لا يذكُرونَ في خُطَبِهم الخليفة، فلما قَدِمَ أحمد من قوص لم يُمضِ السُّلطانُ عَهْدَه، وطلب إبراهيمَ وعَرَّفَه قُبحَ سِيرتِه، فأظهَرَ التوبةَ منها والتزم بسلوكِ طَريقِ الخير، فاستدعى السلطانُ القضاةَ في يوم الاثنين وعَرَّفَهم أنه أقام إبراهيم في الخلافة، فأخذ قاضي القضاة عز الدين عبد العزيز بن جماعة يُعَرِّفُه سوءَ أهليَّتِه للخلافة، فأجاب بأنه قد تاب، والتائِبُ من الذنبِ كَمَن لا ذَنبَ له، وقد ولَّيتُه فاشهَدوا عليَّ بولايتِه، ورتَّبَ له السلطانُ ما جرت به العادة، وهو ثلاثة آلاف وخمسمائة وستون درهمًا وتسعة عشر أردب شعير في كل شهر، فلم يعارِضْه أحَدٌ، وخُطِبَ له في يوم الجمعة سادس ذي القعدة، ولُقِّبَ بالواثق بالله أبي اسحاق، فكانت العامَّةُ تسميه المستعطي؛ فإنَّه كان يستعطي من النَّاسِ ما يُنفِقُه، وشُهِرَ بارتكابٍ أمورٍ غَيرِ مَرضِيَّة."},{"id":2997,"title":"جماعة من النصارى يحرقون المسجد الأموي وسوقًا كبيرًا بدمشق .","date":["العام الهجري :740","الشهر القمري : شوال","العام الميلادي :1340"],"text":"اجتمَعَ جماعةٌ من رؤوس النصارى في كنيستِهم وجَمَعوا من بينهم مالًا جزيلًا فدَفَعوه إلى راهبينِ قَدِما عليهما من بلاد الروم، يُحسِنانِ صَنعةَ النِّفطِ، اسم أحدِهما ملاني، والآخر عازر، فعملا كحطًا من نفط، وتلطَّفا حتى عملاه لا يظهَرُ تأثيرُه إلا بعد أربع ساعات وأكثر من ذلك، فوُضِعا في شقوق دكاكين التجَّار بسوق الرجال في عدَّة دكاكين من آخِرِ النهار، بحيث لا يشعُرُ أحَدٌ بهما، وهما في زي المُسلِمينَ، فلما كان في أثناء الليل لم يشعُرِ النَّاسُ إلا والنَّارُ قد عَمِلَت في تلك الدكاكين حتى تعلَّقَت في درابزينات المأذنة الشرقيَّة المتَّجِهة للسوق المذكور، وأحرَقَت الدرابزينات، وجاء نائب السلطنة تنكز والأمراء أمراء الألوف، وصَعِدوا المنارة وهي تشتَعِلُ نارا، واحترسوا عن الجامِعِ فلم ينَلْه شيءٌ من الحريق ولله الحمد والمنة، وأمَّا المئذنة فإنها تفَجَّرت أحجارُها واحترقت السقَّالات التي تدُلُّ السلالم وأعيدَ بناؤها بحجارةٍ جُدُدٍ، وهي المنارة الشرقية التي جاء في الحديثِ أنَّه يَنزِلُ عليها عيسى بن مريم، والمقصودُ أنَّ النصارى بعد ليالٍ عَمَدوا إلى ناحية الجامع من المغرب إلى القيسارية بكمالِها، وبما فيها من الأقواس والعُدَد، وتطاير شَرَرُ النار إلى ما حول القيسارية- السوق الكبير- من الدُّورِ والمساكن والمدارِس، واحترق جانِبٌ من المدرسة الأمينية إلى جانب المدرسة المذكورة وما كان مقصودُهم إلَّا وصول النار إلى مَعبَد المسلمين، فحال اللهُ بينهم وبين ما يرومون، وجاء نائبُ السلطنة والأمراء وحالوا بين الحريقِ والمسجِدِ، جزاهم اللهُ خَيرًا، ولَمَّا تحقق نائِبُ السَّلطنةِ أنَّ هذا مِن فِعلِهم أمَرَ بمَسكِ رؤوس النصارى فأَمسَكَ منهم نحوًا من ستين رجلًا، فأُخِذوا بالمُصادَرات والضَّربِ والعقوبات وأنواع المَثُلاتِ، ثمَّ بعد ذلك صُلِبَ منهم أزيدُ مِن عَشرةٍ على الجمال، وطاف بهم في أرجاءِ البلاد وجَعلوا يتماوتون واحِدًا بعد واحد، ثمَّ أُحرِقوا بالنارِ حتى صاروا رمادًا لَعَنَهم اللهُ."},{"id":2998,"title":"مقتل الأمير سيف الدين تنكز نائب السلطان الناصر على دمشق .","date":["العام الهجري :741","العام الميلادي :1340"],"text":"هو الأميرُ الكبيرُ المَهيبُ سَيفُ الدين أبو سعيد تنكز نائِبُ السلطنة بالشام، جُلِبَ إلى مصر وهو حَدَثٌ، فنشأ بها، وكان أبيض يميل إلى السمرة، رشيق القَدِّ، مليح الشَّعر، خفيف اللحية قليل الشَّيب، حَسَن الشَّكلِ، جلبه الخواجا علاء الدين السيواسي، فاشتراه الأمير حسام الدين لاجين، فلما قُتِلَ لاجين في سلطنته صار من خاصكية السلطان الناصر، وشهد معه وقعة وادي الخزندار ثم وقعة شقحب، سمع صحيح البخاري غير مرة من ابن الشحنة، وسمع كتاب الآثار للطحاوي، وصحيح مسلم. تولى نيابةَ السلطان بدمشق في شهر ربيع الآخر سنة 712 وتمكَّن في النيابة, وسار بالعساكِرِ إلى ملطية فافتتحها وعظُمَ شأنُه وهابه الأمراءُ بدمشق ونوَّاب الشام، وأمِنَ الرعايا به ولم يكُنْ أحدٌ من الأمراء ولا من أربابِ الجاه يَقدِرُ يظلِمُ أحدًا ذِمِّيًّا أو غيره خوفًا منه؛ لبطشه وشِدَّة إيقاعه, ثمَّ تغير السلطان الناصر على تنكز, وكان سَبَبُ تغير الحال بينهما- مع أن السلطان متزوج من بنته وأراد كذلك تزويجَ ولديه من بناته- لَمَّا قَتَل تنكز جماعةً من النصارى بسَبَبِ افتعالهم الحريقَ بدمشق، عَنَّف عليه السلطان، وأن في ذلك سببًا لقتل المسلمين في القُسطنطينية، وزاد الأمرَ أنَّه أمَرَه بإحضار الأموال المتحَصَّلة من جرَّاء هذه الحادثة وأن يجهِّزَ بناتِه، فاعتذر تنكز بانشغالِه بعمارةِ ما أكَلَه الحريقُ وأنَّه أنفق تلك الأموالَ في ذلك، وزاد الأمرَ كذلك سعايةُ بعض الحاسدين عليه لدى السلطانِ حتى أمر السلطان بإحضارِه إلى مصر، فخرج جيشٌ من مصر لإحضاره من دمشقَ، وكان تنكز قد عرف بالأمرِ، فخرج وأخرج أموالَه وأهله، فوصلَ إليه الأمراء من القاهرةِ وعَرَّفوه مرسومَ السلطان وأخَذوه وأركبوه إكديشًا- حصانًا غير أصيل يُستخدَم في حمل الآلات والعدَّة- وساروا به إلى نائب صفد، وأمر طشتمر بتنكز فأُنزِلَ عن فرسه على ثوب سرج، وقيده قرمجي مملوكُه، وأخذه الأمير بيبرس السلاح دار، وتوجَّه به إلى الكسوة، فحدث له إسهالٌ ورِعدةٌ خيفَ عليه منه الموتُ، وأقام بها يومًا وليلة، ثم مضى به بيبرس إلى القاهرة, وفي يومِ الثلاثاء سابِعَ المحرم وصل الأمير سيف الدين تنكز نائِبُ الشام وهو متضَعِّفٌ، بصحبة الأمير بيبرس السلاح دار، وأُنزِلَ من القلعة بمكانٍ ضَيقٍ حَرَجٍ، وقَصَد السلطان ضَرْبَه بالمقارعِ، فقام الأميرُ قوصون في الشفاعة له حتى أجيبَ إلى ذلك، وبعث إليه السلطان يُهَدِّدُه حتى يعترف بما له من المالِ، ويَذكُر من كان موافِقًا على العصيان من الأمراء، فأجاب تنكز بأنَّه لا مال له سوى ثلاثين ألف دينار وديعةً عنده لأيتامِ بكتمر الساقي، وأنكر أن يكون خرجَ عن الطاعة، فأمر السلطانُ في الليلِ فأُخرِجَ مع ابن صابر المقَدَّم وأمير جندار، وحُمِلَ في حراقة –سفينة- بالنيل إلى الإسكندرية، فقَتَلَه بها إبراهيم بن صابر المقَدَّم في يوم الثلاثاء خامس عشر ودفنوه بالإسكندرية، وقد جاوز الستينَ، ثم نقل من الإسكندرية بعد ثلاث سنين ونصف أو أكثر، بشفاعةِ ابنتِه زوجة السُّلطانِ الناصر، فأَذِنَ في ذلك وأرادوا أن يُدفَنَ بمدرسته بالقدس الشريف، فلم يُمكِنْ، فجيء به إلى تربته بدمشق وقيل: كانت وفاتُه بقلعة إسكندرية مسمومًا، وتأسَّفَ الناسُ عليه كثيرًا، وطال حُزنُهم عليه، وفي كل وقتٍ يتذكَّرون ما كان منه من الهَيبةِ والصيانةِ والغَيرةِ على حريمِ المسلمينَ ومحارم الإسلام، ومن إقامتِه على ذَوي الحاجاتِ وغَيرِهم؛ يشتَدُّ تأسفهم عليه. ويُذكَرُ أنَّ لتنكز هذا أوقافًا كثيرة، من ذلك مرستان بصفد، وجامع بنابلس وعجلون، وجامع بدمشق، ودار الحديث بالقدس ودمشق، ومدرسة وخانقاه بالقدس، ورباط وسوق موقوف على المسجد الأقصى، وتُتبِّعَت أموال تنكز، فوجِدَ له ما يجِلُّ وَصفُه واشتملت جملةُ ما بيع له على مائتي ألف دينار، فكان جملةُ العين ستمائة ألف دينار وأربعمائة دينار، ومع ذلك كان له أعمالٌ جدية في دمشق فأزال المظالمَ، وأقام منارَ الشَّرعِ، وأمَرَ بالمعروف، ونهى عن المنكر، وأزال ما كان بدمشق وأعمالها من الفواحِشِ والخانات والخَمَّارات، وبالغ في العقوبةِ على ذلك حتى قَتَل فيه، وغيرها من عمارة المدارس والأوقاف والمساجد."},{"id":2999,"title":"هزيمة المسلمين في وقعة طريف بالأندلس  .","date":["العام الهجري :741","العام الميلادي :1340"],"text":"قام المَلِكُ أبو الحَسَن علي بن عثمان مَلِكُ بني مرين باجتيازِ البحرِ على رأسٍ جيشٍ كثيفٍ لمحاربةِ المتحالفين من قشتالة والبرتغال وأراغون، فجَرَت بينهم معركةٌ قُربَ مدينة طريف انكسَرَ فيها جيشُ المسلمين المكَوَّن من جيش بني مرين وجيش غرناطة، وسَقَط معسكرُ الملك المريني بيد الأسبان فذبحوهم بأجمَعِهم واستطاع المَلِكُ المريني عبورَ البحر إلى المغرب مع بعضِ فلول جيشِه، وانهزم مَلِكُ غرناطة إلى غرناطة بأسوأ حالٍ شَهِدَه المسلمون منذ وقعة العقاب، واستولى الأسبانُ على طريف والجزيرة الخضراء وجبل طارق، ويُذكَرُ أن المسلمين استعملوا في هذه الحربِ آلاتٍ تُشبِهُ المدافع كانت تسمَّى الأنفاط، وكانت هي أساسًا لاختراع المدافِعِ فيما بعد."},{"id":3000,"title":"مقتل عثمان الدكاكي على الزندقة بدمشق .","date":["العام الهجري :741","الشهر القمري : شوال","العام الميلادي :1341"],"text":"هو الصوفيُّ الاتحادي عثمان الدكاكي الدمشقي, خالطَ الصوفية ودعاةَ وَحدةِ الوجودِ، فتأثَّرَ بهم حتى ادَّعى الألوهيَّةَ وانتَقَص من الأنبياء, فعُقِدَ له مجلسٌ في دار العدل بدار السعادة في يوم الثلاثاء آخر شَهرِ شوال واجتَمَع القضاة والأعيانُ على العادة وأُحضِرَ يومئذ عثمان الدكاكي، وادُّعِيَ عليه بعظائمَ من القول لم يؤثَرْ مِثلُها عن الحلَّاجِ ولا عن ابن أبي الغدافر السلقماني، وقامت عليه البيِّنةُ بدعوى الإلهية- لعنه الله- وأشياءَ أُخَر من التنقيص بالأنبياء ومخالطته أرباب الرَّيبِ من الباجريقية وغيرهم من الاتحادية- عليهم لعائن الله- ووقع منه في مجلسٍ من إساءة الأدب على القاضي الحنبلي، وتضَمَّنَ ذلك تكفيرُه من المالكية أيضًا، فادعى أنَّ له دوافِعَ وقوادِحَ في بعض الشهود، فرُدَّ إلى السجنِ مُقَيَّدًا مغلولًا مقبوحًا، ثم لما كان يوم الثلاثاء الحادي والعشرين من ذي القعدة أُحضِرَ عثمان الدكاكي إلى دار السعادة وأُقيمَ بين يدي الأمراء والقُضاة وسُئِلَ عن القوادح في الشهودِ فعَجَز فلم يقدِرْ، وعجز عن ذلك فتوَجَّهَ عليه الحُكم، فسئل القاضي المالكي الحُكمَ عليه، فحَمِدَ الله وأثنى عليه وصلَّى على رسولِه، ثمَّ حكم بإراقة دَمِه وإن تاب، فأُخِذَ الدكاكيُّ فضُرِبَت رَقَبتُه بدمشق بسوقِ الخيل، ونودي عليه: هذا جزاءُ مَن يكون على مَذهَبِ الاتحاديَّة، وكان يومًا مشهودًا بدار السعادة، حضَرَ خلقٌ من الأعيان والمشايخِ."},{"id":3001,"title":"تجهيز عساكر إلى توريز لتسلُّمِها من حكامها التتار .","date":["العام الهجري :741","الشهر القمري : ذي القعدة","العام الميلادي :1341"],"text":"كتب السُّلطانُ النَّاصِرُ بتَجهيزِ عساكِرِ دمشق وحَلَب وغيرهما للتجريدةِ إلى توريز، صحبة الأمير طشتمر نائب حلب، ويكونُ معه عامَّةُ أمراء التركمان والعربان، فتجَهَّزَ الأمراء والأجناد بمماليك الشام، وبَرَز نائب حلب بمخيَّمِه إلى ظاهر المدينة وأقام ينتَظِرُ قدومَ عساكِرِ مصر، فأصبح السلطان في مستهَلِّ ذي الحجة وبه وَعكٌ من قرف حدث عنه إسهالٌ لزم منه الفِراشَ خمسةَ أيام، فتصَدَّقَ بمال جزيل، وأفرَجَ عن المسجونينَ بسِجنِ القُضاة والولاة بالقاهرة ومصر وسائر الأعمال، ثم قَدِمَ إدريس القاصد بصُحبة مملوك صاحب ماردين بكتابِه يتضَمَّنُ أن أولاد دمرداش بن جوبان بن تلك المغولي لَمَّا بلغهم طلَبُ الشيخ حسن الكبير بن أقبغا أيلخان سبط أرغون المغولي وطغاي بن سونتاي المغولي من السلطان أن يجَهِّزَ لهم عسكرًا ليأخُذَ البلاد، وأنَّهما حلفا له وحلفا أهلُ البلاد وخَطَبا باسمه على منابر بغداد والموصل، وركبوا إلى محاربتِهما، فطَلَب منهم الشيخ حسن الكبير الصُّلحَ، وحلف لهم وسار إليها طائعًا، فأكرموه وكتبوا لطغاي بن سونتاي أمانًا، واتَّفَقوا على أن يعدوا الفرات إلى الشام، وأشار صاحب ماردين ألا تخرُجَ التجريدة إلى توريز؛ فإنَّه ليس لِسَيرِها فائدة، فتفَرَّقت الأجنادُ من القلعة بغيرِ عرض، وبَعَث السلطان من ليلته بجوابِ صاحب ماردين، واقتضى رأيُه أن يكشِفَ عما ذكره، فإنَّ برهشين بن طغاي اتَّهَمه في ذلك، ثم قَدِمَ البريد من حلب بصحَّة الخبر بصُلح الشيخ حسن الكبير وطغاي مع أولاد دمرداش، فانزعَجَ السلطان لذلك انزعاجًا شديدًا، واضطرب مزاجُه."},{"id":3002,"title":"وفاة السلطان الناصر محمد بن قلاوون وتولي ابنه المنصور بعده .","date":["العام الهجري :741","الشهر القمري : ذي الحجة","العام الميلادي :1341"],"text":"هو السلطانُ الملك الناصر، ناصر الدين أبو الفتح محمد ابن السلطان الملك المنصور سيف الدنيا والدين قلاوون، وُلِدَ الملك الناصر سنة 684، وكان قد أقيمَ النَّاصِرُ في السلطنة بعد أخيه الملك الأشرف خليل سنة 693، وعُمُرُه تسع سنين ثمَّ خُلِعَ في سادس عشر المحرم سنة أربع وتسعين، وأُرسِلَ إلى الكرك, ثمَّ أعيد إلى المُلكِ ثانيًا وعمره خمس عشرة سنة، فأقام في المُلك إلى سنة 708، وخرج يريدُ الحَجَّ، فتوجه إلى الكرك متبرمًا من سلار وبيبرس الجاشنكير أستاذ الدار وحَجْرِهما عليه ومَنْعِهما له من التصَرُّف، فأعرض الناصِرُ عن مصر، فوثب الجاشنكير على السلطنة وتسلطَنَ، ثم اضطربت أموره، وقَدِمَ الناصر من الشام إلى مصر، فمَلَكَ مَرَّةً ثالثة في شوال سنة 709 واستبَدَّ الناصر من حينئذ بالأمرِ مِن غير معارضٍ مدة اثنتين وثلاثين سنة وشهرين وخمسة وعشرين يومًا، كانت له فيها سِيَرٌ وأنباء، وكان الناصِرُ أطولَ ملوك زمانه عُمُرًا وأعظَمَهم مهابةً, ودانت له البلادُ ومَلَك الأطرافَ بالطاعة، لما زاد مرض السلطان بالإسهال وخارت قواه، أشار عليه بعضُ الأمراء أن يَعهَدَ بالمُلكِ إلى أحد أولادِه، فأجاب إلى ذلك فجعل ابنَه أبا بكر سلطانًا بعده، وأوصاه بالأمراءِ، وأوصى الأمراءَ به، وعَهِدَ إليهم ألا يُخرِجوا ابنَه أحمد من الكَركِ وحَذَّرَهم من إقامته سُلطانًا، وجعل قوصون وبشتاك وصِيَّيه، وإليهما تدبيرُ ابنِه أبي بكر وحلَّفَهما، ثمَّ حَلَّفَ السلطانُ الأمراءَ والخاصكية، وأكَّدَ على ولده في الوصيَّة بالأمراء، وأفرج عن الأمراءِ المسجونين بالشام، وهم طيبغا حاجي وألجيبغا العادلى وصاروجا، ثم قام الأمراء، فبات السلطانُ ليلة الثلاثاء، وأصبح وقد تخَلَّت عنه قوته، وأخذ في النزعِ يوم الأربعاء، فاشتَدَّ عليه كَربُ الموتِ حتى مات أول ليلة الخميس الحادي عشر من ذي الحجة، وله من العُمُرِ سبع وخمسون سنة وأحد عشر شهرًا وخمسة أيام, ودُفِنَ بالمدرسة المنصورية بين القصرين، أما السلطان الجديد فلقَّبَه الأمراء الأكابِرُ بالملك المنصور، وجَلَسوا حوله، واتَّفَقوا على إقامة الأمير سَيفِ الدين طقزدمر الحموي- زوج أمه- نائِبَ السُّلطةِ بديار مصر، وأن يكون الأميرُ قوصون مدبِّرَ الدولة ورأس المشورة، ويشارِكه في الرأي الأميرُ بشتاك."},{"id":3003,"title":"وفاة الملك أزبك خان ملك التتار المسلم في منطقة الروم وتولي ابنه بعده .","date":["العام الهجري :742","العام الميلادي :1341"],"text":"هو المَلِكُ أزبك خان بن طغرلجا بن منكوتمر بن طغان بن باطو بن دوشي خان بن جنكز خان ملك التتار، وكان أسلَمَ وحَسُنَ إسلامُه وحَرَّض رعيَّتَه على الإسلام، فأسلم بعضهم، ولم يلبَسْ أزبك خان بعد أن أسَلَم السراقوجات- لباس الرأس عند التتار- وكان يلبس حياصةً من فولاذ ويقول: لبسُ الذَّهَبِ حرامٌ على الرجال، وكان يميلُ إلى دينٍ وخَيرٍ، ويتردَّدُ إلى الفقراء، وكان عنده عَدلٌ في رعيته، وتزوَّجَ الملك الناصِرُ محمد بابنَتِه، وكان أزبك شُجاعًا كريمًا مليحَ الصورة ذا هيبةٍ وحُرمة، ومملكتُه مُتَّسِعة، وهي من بحر قسطنطيينة إلى نهر إرتش مَسيرةَ ثمانمائة فرسخ، لكِنَّ أكثر ذلك قرًى ومراعي، ومات أزبك خان بعد أن مَلَك نحوًا من ثلاثينَ سنة، ووَلِيَ المُلكَ بعده ابنُه: جاني بك خان."},{"id":3004,"title":"خلع الخليفة العباسي الواثق وتولية الحاكم بأمر الله أحمد المستكفي .","date":["العام الهجري :742","الشهر القمري : محرم","العام الميلادي :1341"],"text":"كان السُّلطانُ مُحمَّدُ بن قلاوون قَبلَ وَفاتِه أوصى بأن يُعادَ أحمدُ بنُ سُليمان للخلافةِ على ما كان أبوه عَهِدَ إليه، وأشهد على ذلك أربعين عَدلًا وقاضيَ قوصٍ وغيرَه من الفقهاء والقُضاة، ففي أوَّلِ هذه السنة أحضر السلطانُ المنصورُ بن محمد بن قلاوون الخليفةَ الواثِقَ إبراهيمَ وخَلَعَه بناءً على وصيَّةِ المستكفي لابنِه أحمد، وبايع القُضاةُ والسلطانُ أحمدَ بنَ سليمان المستكفي ولقَبَّه الحاكِمَ بأمر الله."},{"id":3005,"title":"وفاة الحافظ أبي الحجاج المِزِّيِّ .","date":["العام الهجري :742","الشهر القمري : صفر","العام الميلادي :1341"],"text":"هو الشيخُ الإمامُ العلَّامة الحافِظُ حُجَّة العصرِ، ومحَدِّثُ الشام ومصر وخاتمةُ الحُفَّاظ جمال الدين أبو الحجاج يوسف بن الزكي عبد الرحمن بن يوسف بن علي بن عبد الملك بن أبي الزهر القضاعي الكلبي المزِّي الحلبي المولد، وُلِدَ بظاهر حَلَب في عاشر ربيع الآخر سنة 654، وكان إمامَ عَصرِه وأحَدَ الحُفَّاظ المشهورين، نشأ بالمزَّة بالقُربِ مِن دمشق, فحَفِظَ القرآن الكريم وعُنِيَ باللغةِ وبَرَع فيها وأتقَنَ النحو والتصريف، ثمَّ طلب الحديث سنة 675، فما ونى وما فَتَر ولا لها ولا قَصَّر، في الطلب والاجتهاد والرواية, وصَنَّف وأفاد، وكتب الكثير، لَمَّا وَلِيَ دار الحديث الأشرفي تمذهَبَ للشافعيِّ وأُشهِدَ عليه بذلك. وكان فيه حياءٌ وسكينة، وحِلمٌ واحتمال وقناعة، واطِّراحُ تكَلُّف وتَركُ التجَمُّل والتودُّد والانجماع عن الناسِ وقلة الكلام، إلا أنَّه يُسأل فيُجيب ويجيد، وكلَّما طالت مجالسةُ الطالب له ظهر له فضلُه. وكان لا يتكَثَّر بفضائله، كثيرَ السكوت لا يغتابُ أحدًا. وكان معتَدِلَ القامة مُشرَبًا بحُمرةٍ، قَوِيَّ التركيب مُتِّعَ بحواسِّه وذهنه. وكان قَنوعًا غيرَ متأنقٍ في ملبَسٍ أو مأكلٍ، يصعَدُ إلى الصالحية وغيرها ماشيًا وهو في عشر التسعينَ, وأما معرفته بالرجال فإليه تُشَدُّ الرِّحال؛ فإنه كان الغاية وحامِلَ الراية. ولما ولي دارَ الحديث قال الشيخ تقي الدين ابن تيمية: \"لم يَلِ هذه المدرسةَ مِن حين بنائِها وإلى الآن أحَقُّ منه بشرطِ الواقِفِ، وقد وَلِيَها جماعة كبار مثل: ابن الصلاح، ومحيي الدين النواوي، وابن الزبيدي، لأنَّ الواقِفَ قال: فإن اجتمَعَ مَن فيه الروايةُ ومن فيه الدرايةُ قُدِّمَ مَن فيه الدرايةُ؛ قال الشيخ شمس الدين: لم أرَ أحفَظَ منه، ولم يَرَ هو مثلَ نَفسِه, ولم يسألْني ابن دقيق العيد إلَّا عنه. وكان قد اغتَرَّ في شبيبته وصَحِبَ عفيف الدين التلمساني، فلما تبيَّنَ له مذهبُه هَجَره وتبرَّأ منه, ثم قال الشيخ شمس الدين: قرأت بخطِّ الحافظ فتح الدين ابن سيد الناس: ووجدت بدمشقَ الحافِظَ المقَدَّم، والإمامَ الذي فاق من تأخَّر وتقدم، أبا الحجَّاج المزِّيَّ؛ بحرَ هذا العلم الزاخر، القائِلَ من رآه: كم ترك الأوائِلُ للأواخِر، أحفَظَ النَّاسِ للتراجم، وأعلَمَهم بالرواة من أعارِبَ وأعاجم، لا يخصُّ بمعرفته مصرًا دون مصر، ولا ينفَردُ علمُه بأهل عصر دون عصر، معتمدًا آثارَ السلف الصالح، مجتهدًا فيما نِيطَ به في حفظ السنة من النصائح، مُعرِضًا عن الدنيا وأشباهِها، مُقبِلًا على طريقته التي أربى بها على أربابها، لا يبالي بما ناله من الأزل، ولا يخلط جِدَّه بشَيءٍ مِن الهَزل، وكان بما يصنعه بصيرًا، وبتحقيق ما يأتيه جديرًا، وهو في اللغة إمام، وله بالقريض إلمام\". من أهم مُصَنَّفاتِه تهذيب الكمال في أسماء الرجال في أربعة عشر مجلدًا، كشَفَ به الكتب القديمة في هذا الشأن، وسارت به الرُّكبان، واشتهر في حياته، وهو كتابٌ نافِعٌ جدًّا ليس له نظيرٌ في فنه، وألف كتاب \" أطراف الكُتُب الستة \" في تسعة أسفار, وكان سبَبُ موته هو أنه أصابه طاعون فمَرِضَ عِدَّة أيام حتى إذا كان يوم السبت من الثاني عشر من صفر توفِّيَ بعد صلاة الظهر، فلم يمكن تجهيزُه تلك الليلة، فلما كان من الغدِ يومَ الأحد ثالث عشر صفر صبيحة ذلك اليوم، غُسِّلَ وكُفِّنَ وصُلِّيَ عليه بالجامع الأموي، وحضر القضاةُ والأعيان وخلائِقُ لا يُحصَونَ كثرةً، وخرج بجنازته من باب النصر فصَلَّوا عليه خارج باب النصر، أمَّهم عليه القاضي تقي الدين السبكي الشافعي، وهو الذي صلى عليه بالجامِعِ الأموي، ثم ذهب به إلى مقابر الصوفية، فدفن هناك إلى جانب زوجتِه المرأةِ الصالحة الحافظةِ لكتاب الله: عائشةَ بنتِ إبراهيم بن صديق، غربيَّ قَبرِ شَيخِ الإسلام تقي الدين بن تيمية- رحمهم الله أجمعين."},{"id":3006,"title":"خلع السلطان المنصور أبي بكر وتولية أخيه الأشرف كجك .","date":["العام الهجري :742","الشهر القمري : صفر","العام الميلادي :1341"],"text":"لَمَّا تَسلطَنَ المَلِكُ المنصور أبو بكر، أصبح همُّه ملذَّات نفسِه، فأصبح هذا شيئًا شائعًا عنه يعرِفُه القاصي والداني، حتى أصبح معروفًا بالشرب وجَلْب المغنيات إلى قَصرِه، حتى قال الأميرُ قوصون الناصري: أهكذا يكون أمرُ سُلطان المسلمين؟! أهكذا كان أبوه يفعَلُ؟! وكانت هذه الكَلِمةُ منه سببًا في الوحشة التي حَصَلت بعد ذلك، ثمَّ لَمَّا استفحل هذا الأمرُ مِن السلطان، قرَّر الأمراءُ خَلْعَه وإخراجَه وإخوتِه من القلعة، فتوجَّه برسبغا في جماعةٍ إلى القلعة، وأخرج المنصورَ وإخوته، وهو سابِعُ سَبعةٍ، ومع كل منهم مملوكٌ صغيرٌ وخادِمٌ وفَرَسٌ وبقجة قماش، وأركبهم برسبغا إلى شاطئ النيل، وأنزلهم في الحراقة، وسافر بهم جركتمر بن بهادر إلى قوص، واتَّفَق الأمراء على إقامة كجك بن محمد بن قلاوون، فكانت مدةُ سلطنة المنصور أبي بكر تسعة وخمسين يومًا، ومن حين قلَّدَه الخليفةُ أربعين يومًا، ومن الاتِّفاق العجيب أنَّ المَلِكَ الناصِرَ أخرج الخليفةَ أبا الربيع سليمان وأولاده إلى قوص مُرَسَّمًا عليهم، فقُوصِصَ بمثلِ ذلك!! وأخرج الله أولادَه مُرَسَّمًا عليهم إلى قوص على يد أقرَبِ الناس إليه، وهو قوصون مملوكِه وثِقَتِه ووصِيِّه على أولاده، ثمَّ في يوم الاثنين حادي عشر صفر أقيم المَلِكُ الأشرف علاء الدين كجك بن الناصر محمد بن قلاوون سُلطانًا، ولم يَكمُلْ له من العمر خمس سنين، وقيل: كان عمره دون سبع سنين، ولَمَّا تم أمرُه في السلطنة جلس الأمراء وتشاوروا فيمن يُقيموه في نيابةِ السَّلطنةِ فرُشِّحَ الأمير أيدغمش أمير آخور، فامتنعَ أيدغمش من ذلك، فوقع الاتفاقُ على الأمير قوصون الناصري، فأجاب وشَرَط على الأمراء أن يقيمَ على حاله في الأشرفيَّة من القلعة ولا يخرُج منها إلى دار النيابةِ خارِجَ باب القلة من القلعة، فأجابه الأمراءُ إلى ذلك، فاستقَرَّ من يومه في النيابة، وتصَرَّف في أمورِ الدولة."},{"id":3007,"title":"وفاة الملك الأفضل صاحب حماة وتولي ابنه بعده .","date":["العام الهجري :742","الشهر القمري : ربيع الآخر","العام الميلادي :1341"],"text":"هو الملِكُ الأفضَلُ علاء الدين عليُّ ابنُ المَلِك المؤيَّد عماد الدين إسماعيل ابن الملك الأفضل علي ابن الملك المظفر محمود ابن الملك المنصور محمد ابن الملك المظفر تقي الدين عمر بن شاهنشاه ابن الأمير نجم الدين أيوب بن شادي الأيوبي صاحِب حماة وابن صاحبها، مات بدمشقَ، وهو من جملةِ أمرائها بعدما باشر سلطنةَ حماة عشرينَ سَنةً إلى أن نقَلَه قوصون إلى إمرة الشام؛ وولِيَ نيابةَ حماة بعده الأميرُ طقزدمر الحموي، وكانت وفاتُه في ليلة الثلاثاء حادي عشر ربيع الآخر عن ثلاثينَ سنة."},{"id":3008,"title":"خلع السلطان الأشرف كجك وتولية أخيه الناصر أحمد .","date":["العام الهجري :742","الشهر القمري : شعبان","العام الميلادي :1342"],"text":"في يومِ الخَميسِ أول شعبان خُلِعَ السُّلطانُ المَلِكُ الأشرف علاء الدين كجك من السُّلطة، وكانت مدته خمسة أشهر وعشرة أيام لم يكُنْ له فيها أمرٌ ولا نهي، وتدبيرُ أمورِ الدَّولةِ كُلِّها إلى قوصون، وكان إذا حضرت العلائِمُ أعطِيَ السُّلطانُ قَلمًا في يده وجاء فقيهُه المغربيُّ الذي يقرئ أولادَ السلطان ويكتبُ العلامةَ والقَلمُ في يد السلطانِ علاء الدين، فلما استولى الأميرُ أيدغمش على الدَّولةِ بعد قوصون، وقَرَّر مع الأمراء خَلْعَ الأشرف كجك في يوم الخميس أوَّلَ شعبان، بعث الأميرُ جنكلي بن البابا، والأميرُ بيبرس الأحمدي، والأمير قماري أمير شكار إلى السُّلطانِ أحمد بن النَّاصِر محمد بن قلاوون بالكرك بكُتُب الأمراءِ يُخبِرونَه بما وقع، ويستدعونَه إلى تخت مُلكِه، فلمَّا كان يومُ الأربعاء سابع عشر رمضان قَدِمَ قاصِدُ السلطان إلى الأمير أيدغمش بأنَّ السلطان يأتي ليلًا من باب القرافة، وأمَرَه أن يفتح له بابَ السِّرِّ حتى يعبُرَ منه، ففتحه، وجلس أيدغمش وألطنبغا المارداني حتى مضى جانِبٌ من ليلة الخميس الثامن عشر منه، أقبل السُّلطانُ في نحو العشرةِ رجالٍ من أهل الكرك، وقد تلَثَّمَ وعليه ثيابٌ مُفَرَّجة، فتلَقَّوه وسلموا عليه، فلم يقِفْ معهم، وأخذ جماعَتَه ودخل بهم، ورجع الأمراءُ وهم يتعَجَّبون من أمرِه، وأصبحوا فدُقَّت البشائِرُ بالقلعة، وزُيِّنَت القاهرةُ ومصر، فلما كان يوم الاثنين عاشر شوال أُلبِسَ السلطان، وجلس على تخت الملك، وقد حضر الخليفةُ الحاكِمُ بأمرِ الله وقضاة مصر الأربعة، وقُضاة دمشق الأربعة، وجميع الأمراء والمقدمين، وعهد إليه الخليفة، وقَبَّل الأمراء الأرض على العادة."},{"id":3009,"title":"الحرب بين ملك قشتالة وملك بني مرين .","date":["العام الهجري :743","العام الميلادي :1342"],"text":"بعد هزيمةِ جَيشِ مَلِك المرينيين أمام تحالُفِ الأسبان، تشَجَّع مَلِكُ قشتالةَ للعَودِ إلى غزو غرناطةَ فتابعَ حُروبَه عليها واستولى على قلعةِ بني سعيدٍ، فأثار هذا الحميَّةَ لدى مَلِك بني مرين أبي الحَسَن علي بن عثمان، فأراد الانتقامَ مِن هزيمتِه الماضية، فأرسل أسطولًا بحريًّا إلى بحرِ الزقاق من مضيقِ جَبل طارق، فالتقى بجيش قشتالة في معركةٍ بحرية كانت فيها هزيمةُ جيش مَلِك بني مرين مرة أخرى، وتمَزُّق أسطوله الذي أرسله، ثم توجَّه الجيش الفرنجي إلى غرناطة فنَصَبوا عليها أكثَرَ مِن عَشرةِ مجانيق حتى صالحهم مَلِكُ غرناطة على مالٍ يؤدِّيه كُلَّ عام، وأن يكون الصلحُ بينهم عشرَ سنين."},{"id":3010,"title":"خلع السلطان الناصر أحمد وتولية أخيه الصالح إسماعيل .","date":["العام الهجري :743","الشهر القمري : محرم","العام الميلادي :1342"],"text":"أهلَّت هذه السَّنةُ والنَّاسُ في أمرٍ مَريجٍ؛ لغيبة السلطانِ النَّاصِرِ أحمد بالكرك، وعند الأمراءِ تشوُّش كبير، ثمَّ قَدِمَ كِتابُ السلطان إلى الأمراءِ يُطَيِّبُ خواطِرَهم، ويُعَرِّفُهم أنَّ مِصرَ والشام والكرك له، وأنَّه حيث شاء أقام، ورسم أن تُجهَّزَ له الأغنامُ مِن بلاد الصعيد، وأكَّد في ذلك، وأوصى آقسنقر بأن يكون مُتَّفِقًا مع الأمراءِ على ما يكون من المصالحِ، فتنكَّرَت قلوبُ الأمراء ونفَرَت خواطرهم، واتَّفَقوا على خَلعِ السلطان وإقامة أخيه إسماعيل في يومِ الأربعاء حادي عشر المحرم، فكانت مدة ولايته ثلاثةَ أشهر وثلاثة عشر يومًا، منها مدَّةُ إقامته بالكرك ومراسيمُه نافذة بمصرَ أحد وخمسون، وإقامته بمصرَ مدة شهرين وأيام، وكانت سيرتُه سيئة، نَقَم الأمراءُ عليه فيها أمورًا، منها أنَّ رُسُلَه التي كانت تَرِدُ مِن قِبَلِه إلى الأمراء برسائِلِه وأسرارِه أوباشُ أهل الكرك، فلما قَدِموا معه إلى مصر أكثَروا من أخذِ ولاياتٍ ومِناصِبَ وهم غيرُ أهل لها، ومنها تحكُّمهم على الوزيرِ وغَيرِه، وحَجْبُهم السلطانَ حتى عن الأمراءِ والمماليك وأربابِ الدولة، فلا يمكِنُ أحدًا من رؤيتِه سوى يومي الخميس والاثنين نحو ساعة، ومع ذلك فإنَّه جمع أموالَ أبيه وغيرها من الأموال والحيواناتِ والمتاع ونَقَله كُلَّه إلى الكرك، ثم جلس السلطانُ الجديدُ الصالحُ إسماعيلُ على تخت الملك يوم الخميسِ ثاني عشر المحرم، بعد خَلْعِ أخيه باتِّفاقِ الأمراء على ذلك؛ لأنَّه بلَغَهم عنه أنَّه لَمَّا أخرجه الأميرُ قوصون فيمن أُخرِجَ إلى قوص أنَّه كان يصومُ يومي الاثنين والخميس، ويشغَلُ أوقاته بالصَّلاةِ وقراءة القرآن، مع العِفَّة والصيانة عمَّا يُرمَى به الشباب من اللهو واللعب، وحَلَف له الأمراءُ والعساكر، وحَلَف لهم السلطانُ ألَّا يؤذيَ أحدًا، ولا يقبِضَ عليه بغير ذنب يُجمَعُ على صِحَّتِه، ودُقَّت البشائِرُ، ولُقِّبَ بالملك الصالح عماد الدين، ونودي بالزِّينة."},{"id":3011,"title":"محاصرة الجيوش المصرية والشامية حصن الكرك .","date":["العام الهجري :743","الشهر القمري : جمادى الآخرة","العام الميلادي :1342"],"text":"لَمَّا خُلِعَ السلطانُ الناصِرُ تحصَّن بالكركِ، فرَسَم السلطانُ الصَّالِحُ إسماعيلُ بإحضار المجرَّدين إلى الكرك وعيَّنَ عِوَضَهم تجريدةً أخرى إلى الكرك، وهي التجريدةُ السابعة، فيها الأميرُ بيبرس الأحمدي، والأمير كوكاي، وعشرون أمير طبلخاناه، وستة عشر أمير عشرة، وكتب بخروج عسكرٍ أيضًا من دمشق ومعهم المنجنيق والزحَّافات، وأرسل أيضًا مع الأحمدي أربعةَ آلاف دينار لِمن عساه ينزِلُ إليه من قلعة الكركِ طائعًا، وجهَّزَ معه تشاريفَ كثيرةً، وعُيِّنَت لهم الإقاماتُ، وكان الوقتُ شِتاءً، فقاسَوا من الأمطار مشقاتٍ كثيرة، وأقاموا نحو شهرين، فاستعَدَّ لهم المَلِكُ الناصر، وجمع الرجالَ وأنفق فيهم مالًا كثيرًا، وفَرَّق فيهم الأسلحةَ المُرصَدة بقلعة الكرك، ورَكِبَ المنجنيق الذي بها، ووقَعَ بينهم القتالُ والحصارُ، واشتَدَّ الحصارُ على المَلِك الناصر بالكرك، وضاقت عليه هو ومن معه لقِلَّة القوت، وتخلَّى عنه أهل الكرك، وضَجِروا من طولِ الحصار، ووعَدوا الأمراءَ بالمساعدة عليه، فحُمِلَت إليهم الخِلَع ومبلغَ ثمانين ألف درهم، هذا وقد استهَلَّ السلطان في أول سنة 745 بتجريدةٍ ثامنة إلى الكرك، وعيَّنَ فيها الأمير منكلي بغا الفخري والأميرَ قماري والأمير طشتمر طلليه؛ ولم يجِد السلطانُ في بيت المال ما ينفِقُه عليهم، فأخذ مالًا من تجارِ العَجَم ومن بنت الأمير بكتمر الساقي على سبيل القَرضِ، وأنفق فيهم، وخرج المجرَّدون في يوم الثلاثاء حادي عشر المحرم سنة 745، وهؤلاء نجدة لمن توجَّه قبلهم خوفًا أن يمَلَّ مَن كان توجَّه من القتال، فيجِدَ النَّاصِرُ فرجًا بعَودِهم عنه، وقُطِعَت الميرة عن الملك الناصر، ونَفِدَت أموالُه من كثرة نفقاته، فوقع الطَّمَعُ فيه، وأخَذَ بالغ- وكان أجَلَّ ثقات الناصر- في العمل عليه، وكاتَبَ الأمراء ووعدهم بأنه يُسَلِّمَ إليهم الكرك، وسأل الأمانَ، فكُتِب إليه من السلطانِ أمانٌ، وقَدِمَ إلى القاهرة ومعه مسعودٌ وابن أبي الليث، وهما أعيانُ مشايخ الكرك، فأكرمهم السلطان وأنعم عليهم، وكتب لهم مناشيرَ بجميع ما طلبوه من الإقطاعاتِ والأراضي، وكان من جملة ما طلبه بالِغ وحده نحو أربعمائة وخمسين ألف درهم في السنة، وكذلك أصحابُه، ثم أعيدوا إلى الكركِ بعدما حلفوا، ثم ركب العسكر للحرب، وخرج الكركيون فلم يكن غيرُ ساعة حتى انهزموا منهم إلى داخِلِ المدينة، فدخل العسكر أفواجًا واستوطنوها، وجَدُّوا في قتال أهل القلعةِ عِدَّة أيام، والناسُ تَنزِلُ إليهم منها شيئًا بعد شيءٍ حتى لم يبقَ عند الملك الناصر أحمد بقلعةِ الكرك سوى عشرة أنفُس، فأقام يرمي بهم على العسكر وهو يجِدُّ في القتال ويرمي بنفسِه، وكان قويَّ الرميِ شُجاعًا، إلى أن جُرِحَ في ثلاثة مواضع، وتمكَّنَت النقابة من البرج وعَلَّقوه وأضرموا النار تحته، حتى وقع، وكان الأميرُ سنجر الجاولي قد بالغ أشَدَّ مبالغة في الحصار، وبذل فيه مالًا كثيرًا، ثم هجم العسكرُ على القلعة في يوم الاثنين الثاني والعشرين من صفر سنة 745 فوجدوا الناصِرَ قد خرج من موضِعٍ وعليه زردية، وقد تنكَّب قَوسَه وشَهَر سَيفَه، فوقفوا وسَلَّموا عليه، فردَّ عليهم وهو متجَهِّم، وفي وجهِه جرحٌ وكَتِفُه أيضًا يسيلُ دمًا، فتقَدَّم إليه الأمير أرقطاي والأمير قماري في آخرين، وأخذوه ومَضَوا به إلى دهليز الموضِعِ الذي كان به وأجلَسوه، وطَيَّبوا قلبه وهو ساكِتٌ لا يجيبهم، فقَيَّدوه ووكَلوا به جماعة، ورتَّبوا له طعامًا، فأقام يومَه وليلته، ومن باكِرِ الغد يُقَدَّمُ إليه الطعام فلا يتناوَلُ منه شيئًا إلى أن سألوه أن يأكُلَ، فأبى أن يأكُلَ حتى يأتوه بشابٍّ يقال له عثمان، كان يهواه، فأتوَه به فأكل عند ذلك، وخرج الأميرُ ابن بيبغا حارس طير بالبشارةِ إلى السلطانِ الملك الصالح، وعلى يَدِه كتب الأمراء، فقَدِمَ قلعة الجبل في يوم السبت ثامن عشرين صفر، فدُقَّت البشائِرُ سبعة أيام، وأخرج السلطانُ منجك اليوسفي الناصريَّ السلاح دار ليلًا من القاهرة لقَتلِ الملك الناصر أحمد من غير مشاورةِ الأمراء في ذلك، فوصل إلى الكرك وأُدخِلَ على الملك الناصر وأخرَجَ الشابَّ مِن عنده، ثم خنَقَه في ليلة رابع شهر ربيع الأول، وقَطَع رأسه، وسار من ليلته ولم يَعلَمِ الأمراءُ ولا العسكَرُ بشيء من ذلك، حتى أصبحوا وقد قطع منجك مسافة بعيدةً، وقدم منجك بعد ثلاثةِ أيام قلعة الجبل ليلًا، وقَدَّم الرأسَ بين يدي السلطان- وكان ضخمًا مهولًا له شعر طويل- فاقشعَرَّ السلطان عند رؤيته وبات مرجوفًا، وطلب الأمير قبلاي الحاجب، ورسم له أن يتوجَّهَ لحفظ الكرك إلى أن يأتيَه نائبٌ لها، وكتب السلطانُ بعود الأمراء والعساكر المجردين إلى الكرك، فكانت مُدَّةُ حصار الملك الناصر بالكرك سنتين وشَهرًا وثلاثةَ أيام."},{"id":3012,"title":"فتنة الأعراب في الحج .","date":["العام الهجري :743","الشهر القمري : ذي الحجة","العام الميلادي :1343"],"text":"في يومِ عَرَفةَ بعَرَفةَ وقعت فتنةٌ بين العَرَبِ والحُجَّاج من قَبلِ الظُّهرِ إلى غروبِ الشَّمسِ، قُتِلَ فيها جماعةٌ، وسَبَبُها أنَّ الشَّريفَ رُميثة بن أبي نُمي أميرَ مكَّةَ شكا من بني حَسَن إلى أميرِ الحاجِّ، فركِبَ أميرُ الحاجِّ في يوم عرفة بعرفة لحَربِهم، وقاتَلَهم وقَتَلَ مِن التُّركِ سِتَّة عشر فارسًا، وقَتَل من جماعةِ بني حسن عِدَّة، وانهزم بقيَّتُهم، فنفر النَّاسُ مِن عَرَفةَ على تخوُّف، ولم يُنهَبْ لأحدٍ شَيءٌ، ولا تزال بنو حَسَن بمِنًى، ثمَّ رحل الحاجُّ بأجمَعِهم يومَ النَّفرِ الأوَّل، ونزلوا الزاهِرَ خارجَ مكة، وساروا منه ليلًا إلى بطنِ مرو، وقيل غير ذلك، فقيل إنه لما كان يومُ عرفة تنافر أشرافُ مكَّةَ مع الأجناد من مِصرَ، فركبوا لحَربِهم بُكرةَ النهار، ووقفوا للحَربِ صَفَّين، فمشى الشريفُ عجلان بينهم، فلم تُطِعْه الأشرافُ، وحملوا على الأجنادِ وقاتلوهم، فقُتِلَ منهم ومن العامَّة جماعة، وأبلى الشريفُ عجلان بن عقيل وأبلى كذلك الأميرُ أيدمر بلاءً عظيمًا، فعاتبه بعضُ مماليك الأمير بشتاك، ورماه بسَهمٍ في صدره ألقاه عن فَرَسِه، وقُتِلَ معه أيضًا جماعة، وآلَ الأمرُ إلى نهبِ شيءٍ كثير، ثم تراجَعَ عنهم الأشرافُ."},{"id":3013,"title":"خلع نائب السلطان الأمير أقسنقر السلاري وتولية الأمير الحاج .","date":["العام الهجري :744","العام الميلادي :1343"],"text":"كان الأميرُ أقسنقر السلاري في نيابتِه لا يَرُدُّ قصَّةً تُرفَعُ إليه، فقصده الناسُ مِن الأقطار وسألوه الرِّزقَ والأراضيَ التي أنْهَوا أنها لم تكنْ بيَدِ أحَدٍ، وكذلك نيابات القلاع وولايات الأعمالِ والرواتب وإقطاعات الحلقة. فلم يرُدَّ أحدًا سأله شيئًا من ذلك سواءٌ كان ما أنهاه صحيحًا أم باطلًا. فإذا قيل له: هذا الذي أنهاه يحتاجُ إلى كَشفٍ، تغَيَّرَ وَجهُه وقال: ليش تقطع رزق الناسِ؟ فإذا كتَبَ بالإقطاعِ لأحدٍ وحضَرَ صاحِبُه مِن سَفَرِه أو تعافى مِن مَرَضِه وسألَه في إعادتِه، قال له: رحْ خذ إقطاعَك، أو يقول له: نحن نعَوِّضُك. ففسدت الأحوالُ ولا سيَّما بالمملكة الشاميَّة، فكتب النوابُ بذلك للسُّلطانِ، فكَلَّمه السلطانُ فلم يرجِعْ وقال: كلُّ من طلب مني شيئًا أعطيتُه وما أردُّ قَلمي عن أحدٍ، بحيث إنَّه كانت تُقَدَّمُ له القصَّةُ وهو يأكُلُ فيترُكُ أكلُه ويكتُبُ عليها من غيرِ أن يعرِفَ ما فيها، فأغلظَ له بسَبَبِ ذلك آقسنقر الناصري أمير أخور. واتَّفَق مع ذلك أنَّه وشى به أنه يباطنُ للنَّاصِرِ أحمد ويواصِلُ كُتُبَه إليه، فقرر أرغون العلائي مع السلطانِ مَسْكَه، فمُسِكَ هو وحاشيتُه، وفي يوم الجمعة ثاني عَشَرِه خَلَعَ السلطانُ آقسنقرَ السلاري. وكان العلائيُّ قد قرَّرَ مع السلطانِ أن يَعرِضَ على الأمراءِ نيابةَ السلطنة، فأوَّلُ مَن عُرِضَت عليه الأميرُ بدر الدين جنكلي بن البابا فامتنع، فقالوا بعده للأميرِ الحاج آل ملك الجوكندار، فأظهر البِشْرَ وأجاب لها إن قُبِلَت شُروطُه، فلما طلع الأميرُ الحاج آل ملك لصلاة الجمعةِ على العادة اشترط على السلطانِ ألَّا يفعَلَ شَيئًا في المملكة إلَّا برأيه وأنه يَمنَعُ الخمرَ مِن البيعِ ويُقيمُ مَنارَ الشَّرعِ، وأنَّه لا يُعارَضُ فيما يفعَلُه، فقَبِلَ السلطان شروطَه ولبس الأميرُ الحاج آل ملك تشريفَ النيابة بجامِعِ القلعة بعد صلاة الجمعة. وأنعم عليه السلطانُ زيادةً على إقطاعِ النيابة بناحيتي المطرية والخصوص ومتحَصَّلهما أربعمائة ألف وخمسين ألف درهم. وفي يوم السبت ثالث عَشَرِه: خلع السلطانُ علي منكلي بغا الفخري واستقَرَّ أمير جندار عوضًا عن بيغرا. وفيه فتح شباك النيابة وجَلَس فيه الأمير الحاج آل ملك للمُحاكَماتِ."},{"id":3014,"title":"فتنة الناس بوجود قبر صحابي في القاهرة وبيان دجل هذه الإشاعة .","date":["العام الهجري :744","العام الميلادي :1343"],"text":"اتَّفَق بظاهِرِ القاهرةِ أمرٌ اعتُنِي بضَبطِه، وهو أنَّه كان بناحية اللوق كوم يُعرفُ بكوم الزل يأوي إليه أهلُ الفسوق من أوباشِ العامَّة، فأخذ بعضُهم منه مَوضِعًا ليبنيَ له فيه بيتًا، فشَرَع في نقل الترابِ منه، فبينا هو يحفِرُ إذ ظهر له إناءُ فخَّار فيه مكاتيبُ دار كانت في هذا البُقعةِ، وتدُلُّ على أنه كان به أيضًا مَسجِدٌ، ورأى آثار البنيان، فأشاع أحدُ شياطينِ العامَّة- وكان يقال له شُعَيبٌ- أنَّه رأى في نَومِه أنَّ هذا البنيان على قَبرِ بعض الصحابة رَضِيَ الله عنهم، وأنَّ مِن كراماتِه أنَّه يُقيمُ المُقعَد ويَرُدُّ بصَرَ الأعمى، وصار يصيحُ ويُهَلِّلُ ويُظهِرُ اختلالَ عَقلِه، فاجتمَعت عليه الغوغاء، وأكثروا مِن الصياح، وتناولوا تلك الأرضَ بالحَفرِ حتى نزلوا فيها نحوَ قامتينِ، فإذا مَسجِدٌ له محرابٌ، فزاد نشاطُهم، وفَرِحوا فرحًا كبيرًا، وباتوا في ذِكرٍ وتَسبيحٍ، وأصبَحوا وجَمَعَهم نحو الألف إنسان، فشالوا ذلك الكوم، وساعَدَهم النساء، حتى إنَّ المرأة كانت تشيل الترابَ في مقنَعِها، وأتاهم الناسُ مِن كل أَوبٍ، ورفعوا معهم الترابَ في أقبِيَتِهم وعمائِمِهم، وألقَوه في الكيمان، بحيث تهيَّأَ لهم في يومٍ واحدٍ ما لا تفي مُدَّةُ شَهرٍ بنَقلِه، وحَفَر شُعَيبٌ حُفرةً كبيرة، وزعم أنَّها مَوضِعُ الصحابي، فخرج إليه أهلُ القاهرة ومصر أفواجًا، وركِبَ إليه نِساءُ الأمراءِ والأعيان، فيأخُذُهنَّ شُعَيبٌ ويُنزِلُهنَّ تلك الحفرة لزيارتِها، وما منهنَّ إلَّا من تدفَعُ الدنانيرَ والدَّراهم، وأشاع شُعَيبٌ أنه أقام الزَّمنى، وعافى المرضى، وردَّ أبصارَ العِميانِ، في هذه الحُفرة، وصار يأخذُ جماعةً مِمَّن يُظهِرُ أنَّه من أهل هذه العاهات، ويَنزِلُ بهم إلى الحُفرةِ، ثم يُخرِجُهم وهم يُسَبِّحونَ: الله أكبر الله أكبر، ويزعُمونَ أنَّهم قد زال ما كان بهم، فافتَتَن الناس بتلك الحُفرة، ونزلت أمُّ السلطانِ لزيارتها، ولم تبقَ امرأةٌ مشهورة حتى أتتها، وصار للنَّاسِ هناك مجتَمَعٌ عظيم، بحيث يُسرَجُ به كلَّ ليلة نحو مائتي قنديل، ومن الشُّموعِ الموكبيَّة شيءٌ كثير، فقامت القضاةُ في ذلك مع الأميرِ أرغون العلائي والأمير الحاج آل ملك نائب السُّلطان، وقَبَّحوا هذا الفِعلَ، وخَوَّفوا عاقبَتَه، حتى رُسِمَ لوالي القاهرة أن يتوجَّهَ إلى مكان الحفرة ويكشِفَ أمْرَها، فإن كان فيها مقبورٌ يُحمَلُ إلى مقابِرِ المُسلِمينَ ويُدفَنُ به سِرًّا، ثمَّ يُعفى الموضِعُ، فلما مضى إليه ثارت به العامَّةُ تُريدُ رَجْمَه، وصاحوا عليه بالإنكارِ الشَّنيعِ حتى رماهم الجُندُ بالنشَّاب، فتفَرَّقوا، وهَرَب شُعَيبٌ ورفيقه العجوي، وما زال الحفَّارون يعملون في ذلك المكانِ إلى أن انتَهَوا فيه إلى سرابِ حمام، ولم يجدوا هناك قبرًا ولا مَقبورًا، فطَمُّوه بالتراب، وانصَرَفوا، وقد انحَلَّت عزائِمُ النَّاسِ عنه، بعدما فُتِنوا به، وضَلُّوا ضلالًا بعيدًا، وجَمَع شُعَيبٌ ورفيقه كثيرًا من المالِ والثيابِ شيئًا طائلًا!!"},{"id":3015,"title":"والي القاهرة يخرب سجن الأسارى ويمنع الخمور في البلاد .","date":["العام الهجري :744","الشهر القمري : محرم","العام الميلادي :1343"],"text":"أمر نائِبُ السُّلطانِ الأميرُ الحاج آل ملك والي القاهرة بأن يُنزَل إلى خزانة البنود بالقاهرة، ويُحتاطَ على ما بها من الخَمرِ والبغايا، ويخرج مَن فيها من النَّصارى الأسرى، ويريق ما هناك من الخُمور، ويخرِّبها حتى يجعَلَها دكًّا، وسبَبُ ذلك أنَّ خِزانةَ البنود كانت يومئذٍ حانةً، بعدما كانت سجنًا يُسجَنُ فيه الأمراءُ والجُندُ والمماليك، كما أنَّ خِزانةَ شمائِل سجنٌ لأرباب الجرائِمِ من اللصوصِ وقُطَّاع الطريق، فلما كانت دولةُ السلطان الملك الناصر محمَّد بن قلاوون بعد عَودِه من الكرك، وشُغِفَ بكثرةِ العماراتِ، اتَّخَذ الأسرى وجَلَبَهم إلى مصر من بلاد الأرمن وغيرها، وأنزَلَ عِدَّةً كثيرةً منهم بقلعة الجبل، وجماعةً كثيرة بخزانة البنود، فملأ أولئك الأرمن خزانةَ البنود حتى بطل السِّجنُ بها، وعَمَرها السلطانُ الناصر مساكِنَ لهم، وتوالدوا بها، وعَصَروا الخمورَ بحيث إنَّهم عصروا في سنة واحدة اثنتين وثلاثين ألف جَرَّة، باعوها جِهارًا، وكان لحمُ الخنزير يُعَلَّقُ عندهم على الوضم، ويباعُ مِن غيرِ احتشامٍ، واتَّخَذوا عندهم أماكِنَ لاجتماع النَّاسِ على المحَرَّمات، فيأتيهم الفُسَّاق ويظَلُّونَ عندهم الأيامَ على شُربِ الخُمورِ ومُعاشرة الفواجِر والأحداثِ، ففَسَدت حُرَمٌ كثيرةٌ من الناسِ وكثيرٌ مِن أولادِهم وجماعةٌ مِن مماليك الأمراءِ فسادًا شَنيعًا، حتى إنَّ المرأةَ إذا تركت أهلَها أو زوجَها، أو الجاريةَ إذا تركت مواليَها، أو الشَّابَّ إذا ترك أباه، ودخل عند الأرمن بخزانةِ البنودِ، لا يقدِرُ أن يأخُذه منهم، ولو كان مَن كان! فقام الأميرُ الحاج آل ملك في أمرِهم، وفاوض السُّلطانَ المَلِكَ الناصِرَ محمدَ بن قلاوون في فسادِهم غيرَ مرة، فلم يجِبْه إلى أن أكثَرَ عليه، فغَضِبَ السلطان عليه، وقال له: يا حاج! كم تشتكي مِن هؤلاء، إن كان ما يُعجِبُك مُجاوَرَتَهم انتَقِلْ عنهم! فشَقَّ ذلك عليه، وركِبَ إلى ظاهر الحُسَينية واختار مكانًا، وعَمَره دارًا، وأنشأ بجانِبِها جامعًا، وحَمَّامًا ورَبْعًا وحوانيت، وبَقِيَت في نفسِه حزازاتٌ حتى أمكنَتْه القدرةُ منهم، وانبسَطَت يدُه فيهم بكونِه نائِبَ السُّلطانِ، فنزل والي القاهرةِ ومعه الحاجِبُ وعِدَّةٌ من أصحاب النائِبِ، وهجموا خزانةَ البنود، وأخرجوا جميعَ سُكَّانِها، وكَسَروا أوانيَ الخَمرِ، فكانت شيئًا يجِلُّ وَصفُه كثرةً، وهدموها واشترى أرضَها الأميرُ قماري مِن بيت المالِ، وتقَدَّمَ إلى الضياء المحتَسِب أن يناديَ بتَحكيرِها، فرَغِبَ النَّاسُ في أرضها واحتكَروها، وبَنَوها دُورًا وطواحينَ وغَيرَها، فكان يومُ هَدمِ خزانة البنود يومًا مَشهودًا من الأيامِ المشهورةِ المذكورة، عَدَلَ هَدْمُها فتحَ طرابلُس وعكا؛ لكثرةِ ما كان يُعمَلُ فيه بمعاصي اللهِ! ثمَّ طلب النائِبُ الأميرُ الحاج واليَ القلعةِ، وألزَمَه أن يفعَلَ ذلك ببيوت الأسرى من القلعةِ، فمضى إليها وكَسَّر جِرارَ الخَمرِ التي بها، وأنزلهم من القلعةِ، وجعَلَهم مع نصارى خزانةِ البنود في مَوضِعٍ بجوار الكوم، فيما بين جامِعِ ابن طولون ومصر، فنزلوه واتخَذوا به مساكِنَهم، وكانت الأسرى التي بالقلعة من خواصِّ الأسرى، وعليهم كان يعتَمِدُ السلطان المَلِكُ الناصر محمد بن قلاوون في أمر عمائِرِه، وكانوا في فَسادٍ كبيرٍ مع المماليكِ وحرَمِ القلعةِ، فأراح الله منهم، ثم رسم الأميرُ الحاج آل ملك النائب بتتَبُّع أهل الفساد، فمَنَع الناسَ مِن ضَربِ الخِيَم على شاطئ النيلِ بالجزيرةِ وغَيرِها للنُّزهة، وكانت محلَّ فَسادٍ كبيرٍ؛ لاختلاطِ الرِّجالِ فيها بالنِّساءِ، وتعاطيهم المُنكَرات."},{"id":3016,"title":"إسلام ملك الهند وطلبه إرسال فقهاء ليعلموهم أمور دينهم .","date":["العام الهجري :744","الشهر القمري : صفر","العام الميلادي :1343"],"text":"وصَلَت رسُلُ مَلِك الهند بهَديَّة فيها فصان ياقوت، ومعهم كتابٌ يتضَمَّنُ السلام والمودَّة، وأنَّهم لم يكونوا يَعرِفونَ الإسلامَ حتى أتاهم رجلٌ عَرَّفَهم ذلك، وذكرَ لهم أنَّ ولاية المَلِك لا بُدَّ أن تكون من الخليفةِ، وسأل مَلِكُ الهند أن يُكتَبَ له تقليدٌ مِن جهة الخليفة بولايةِ مَملكةِ الهند ليكونَ نائبًا عن السلطانِ بتلك البلاد، وأن يَبعَثَ السُّلطانُ إليهم رجلًا يعَلِّمُهم شرائِعَ الإسلام من الصَّلاةِ والصيامِ ونحو ذلك، فأُكرِمَت الرسُلُ، وطلب من الخليفةِ أن يكتُبَ تقليدًا لمُرسِلِهم بسلطنة الهند، فكُتِبَ له تقليدٌ جليلٌ، ورَسَم بسَفَرِ ركن الدين الملطي شيخِ الخانكاه الناصريَّة بسرياقوس مع الرُّسُل."},{"id":3017,"title":"وفاة الشيخ الإمام ابن عبدالهادي الحنبلي .","date":["العام الهجري :744","الشهر القمري : جمادى الأولى","العام الميلادي :1343"],"text":"هو الشَّيخُ الإمامُ العلَّامة الناقِدُ في فنون العلوم: شمس الدين أبو عبد الله محمد بن الشيخ عماد الدين أحمد بن عبد الهادي بن عبد الحميد بن عبد الهادي بن يوسف بن محمد بن قدامة المقدسي الحنبلي، من تلاميذ شيخِ الإسلامِ ابنِ تيميَّةَ. كان مولِدُه في رجب سنة 705. توفي ولم يبلغِ الأربعين، وكان قد حَصَّل من العلومِ ما لا يَبلُغُه الشُّيوخُ الكبار، وتفَنَّنَ في الحديث والنحو والتصريف والفقه والتفسير والأصلين، والتاريخ والقراءات، وله مجاميعُ وتعاليقُ مُفيدة كثيرة, وكان حافِظًا جيِّدًا لأسماءِ الرجال وطُرُقِ الحديث، عارفًا بالجَرحِ والتعديل، بصيرًا بعِلَلِ الحديث، حَسَن الفَهمِ له، جَيِّد المذاكرة، صَحيحَ الذِّهنِ مُستقيمًا على طريقةِ السَّلَفِ، واتِّباع الكِتابِ والسنَّة، مثابرًا على فِعلِ الخيرات، ومن مصنَّفاته كتاب العلل، وهو مؤلِّفُ كِتاب العقود الدريَّة في مناقب شيخِ الإسلامِ ابنِ تيميَّة، وله كتاب قواعد أصول الفقه، وفضائل الشام، والأحكام في الفقه، وغيرها كثير, وكان قد مَرِضَ قريبًا من ثلاثة أشهر بقُرحة وحُمَّى سُل، ثم تفاقم أمرُه وأفرط به إسهالٌ، وتزايد ضَعفُه إلى أن توفِّيَ يوم الأربعاء عاشرَ جمادى الأولى قبل أذانِ العصر، وكان آخِرَ كلامِه أنْ قال: أشهَدُ أنْ لا إلهَ إلَّا اللهُ وأشهَدُ أنَّ مُحمَّدًا رَسولُ الله، اللهُمَّ اجعَلْني من التوَّابينَ واجعَلْني من المتطَهِّرينَ، فصُلِّيَ عليه يومَ الخميس بالجامِعِ المظفري وحضر جنازتَه قُضاةُ البلد وأعيانُ الناس من العلماء والأمراء والتجَّار والعامة، وكانت جنازتُه حافلةً، ودُفِن بالروضة."},{"id":3018,"title":"مقتل حسن السكاكيني على الرفض الدال على الكفر المحض .","date":["العام الهجري :744","الشهر القمري : جمادى الأولى","العام الميلادي :1343"],"text":"هو حَسَنُ بن الشيخ محمد السكاكيني، كان والده الشيخ محمد السكاكيني يَعرِفُ مَذهَب الرافِضةِ الشِّيعةِ جَيِّدًا، وكانت له أسئلةٌ على مذهب أهلِ الجَبْرِ، ونَظَم في ذلك قصيدةً أجابه فيها شيخُ الإسلامِ ابنُ تيميَّةَ رحمه الله، وذكر غيرُ واحدٍ مِن أصحابِ الشَّيخِ أنَّ السكاكيني ما مات حتى رجع عن مذهَبِه، وصار إلى قَولِ أهلِ السنَّةِ، فالله أعلم، وقيل إنَّ وَلَدَه حَسَنًا هذا القبيحَ، كان قد أراد قَتْلَ أبيه لما أظهر السُّنَّةَ. قُتِلَ حَسَن بسوق الخيل في صبيحة يوم الاثنين الحادي والعشرين من جمادى الأولى على ما ظهَرَ منه من الرَّفضِ الدَّالِّ على الكُفرِ المَحضِ، بعد أن شُهِدَ عليه عند القاضي شرف الدين المالكي بشهاداتٍ كثيرةٍ تدُلُّ على كُفرِه، وأنَّه رافِضيٌّ جَلْدٌ، فمن ذلك تكفيرُ الشَّيخينِ- رَضِيَ اللهُ عنهما- وقَذْفُه أمَّيِ المُؤمِنينَ عائشةَ وحفصةَ- رَضِيَ اللهُ عنهما- وزَعَم أنَّ جبريلَ غَلطَ فأوحى إلى محمَّدٍ، وإنَّما كان مُرسَلًا إلى عليٍّ! وغيرُ ذلك من الأقوالِ الباطلة القبيحةِ- قَبَّحَه اللهُ."},{"id":3019,"title":"فتنة الأعراب بصعيد مصر والشام .","date":["العام الهجري :745","العام الميلادي :1344"],"text":"قَدِمَ الخَبَرُ بنفاقِ عُربان الوجه القبلي، وقَطْعِهم الطُّرُقات على الناس، وامتدادِ الفِتَن بينهم نحو شهرينِ قُتِلَ فيها خلقٌ عظيم، وأنَّ عَربَ الفيومِ أغار بعضُهم على بعض، وذبحوا الأطفالَ على صدورِ أمَّهاتهم، فقُتِلَ بينهم قتلى كثيرٌ، وأخربوا ذاتَ الصفا، ومنعوا الخراجَ في الجبال، وقطعوا المياهَ حتى شَرِقَ أكثَرُ بلاد الفيوم، فلم يلتَفِت أمراءُ الدولة لذلك؛ لشُغلِهم بالصَّيدِ ونحوه، وفيه قَدِمَ الخَبَرُ بكثرة فساد العشير ببلاد الشام، وقَطْعِهم الطرقات؛ لقلة حُرمةِ الأمير طقزدمر نائب الشام، فانقطعت طرقات طرابلس وبعلبك، ونُهِبَت بلادهما، وامتَدَّت الفتنةُ بين العشير زيادة على شهر، قُتِلَ فيها خلق كثير، وأضرموا النارَ على موضع احترقَ فيه زيادةٌ على عشرين امرأة."},{"id":3020,"title":"نساء السلطان وجواريه يبتدعن لباسا مترفا ثم يمنعن من لبسه .","date":["العام الهجري :745","العام الميلادي :1344"],"text":"أبطل نائِبُ السُّلطانِ الأميرُ الحاج آل ملك ما أحدَثَه النِّساءُ مِن مَلابسِهنَّ، وذلك أنَّ الخواتينَ نساءَ السُّلطانِ وجواريَهنَّ أحدَثْنَ قُمصانًا طِوالًا تخبُّ أذيالها على الأرضِ، بأكمامٍ سَعةِ الكُمِّ منها ثلاثةُ أذرع، فإذا أرخَتْه الواحدةُ منهن غطَّى رِجْلَها، وعُرِفَ القَميصُ منها فيما بينهنَّ بالبهطلة، ومَبلَغُ مَصروفِه ألفُ درهم ممَّا فوقها! وتشَبَّه نِساءُ القاهرة بهن في ذلك، حتى لم يبقَ امرأةٌ إلَّا وقميصُها كذلك، فقام الوزيرُ منجك في إبطالها، وطَلَب والي القاهرة ورسمَ له بقَطعِ أكمامِ النِّساءِ، وأخْذ ما عليهن، ثم تحدَّثَ منجك مع قاضي القضاة بدار العدلِ يوم الخِدمةِ بحضرةِ السُّلطانِ والأمراء فيما أحدثه النِّساءُ من القمصان المذكورة، وأنَّ القَميصَ منها مبلغُ مصروفه ألف درهم، وأنهنَّ أبطَلْنَ لِبسَ الإزار البغدادي، وأحدَثْنَ الإزار الحرير بألفِ درهم، وأنَّ خُفَّ المرأة وسرموزتَها بخمسمائة درهم، فأفتوه جميعُهم بأنَّ هذا من الأمور المحرمة التي يجِبُ منعُها، فقَوِيَ بفَتواهم، ونزل إلى بيتِه، وبعث أعوانَه إلى بيوت أربابِ الملهى، حيث كان كثيرٌ من النساء، فهَجَموا عليهنَّ، وأخذوا ما عندهنَّ من ذلك، وكَبَسوا مناشِرَ الغسَّالينَ ودكاكين البابية، وأخذوا ما فيها من قُمصان النساء، وقَطَّعَها الوزير منجك، ووكل الوزيرُ مماليكَه بالشوارِعِ والطُّرُقات، فقَطَّعوا أكمامَ النساء، ونادى في القاهرةِ ومصر بمنع النِّساءِ مِن لبس ما تقدَّم ذِكرُه، وأنَّه متى وُجِدَت امرأةٌ عليها شيءٌ مِمَّا مُنِعَ، أُخرِقَ بها وأُخِذَ ما عليها، واشتَدَّ الأمر على النساء، وقُبِضَ على عِدَّةٍ منهن، وأُخِذَت أقمِصَتُهنَّ، ونُصِبَت أخشابٌ على سورِ القاهرة بباب زويلة وباب النصر وباب الفتوح، وعُلِّقَ عليها تماثيلُ مَعمولةٌ على سور النِّساءِ، وعليهن القُمصانُ الطوالُ، إرهابًا لهن وتخويفًا، وطُلِبَت الأساكِفةُ، ومُنِعوا من بَيعِ الأخفافِ والسراميز المذكورة، وأن تُعمَلَ كما كانت أولًا تُعمَل، ونودي من باع إزارًا حريرًا أُخِذَ جميعُ مالِه للسُّلطان، فانقطع خروجُ النساءِ إلى الأسواق، وركوبهنَّ حمير المكارية، وإذا وُجِدَت امرأةٌ كُشِفَ عن ثيابِها، وامتنع الأساكِفةُ مِن عَمَلِ أخفاف النساء وسراميزهن المُحدَثة، وانكَفَّ التجَّار عن بيع الأُزُر الحريرِ وشرائِها، حتى إنَّه نُودِيَ على إزارٍ حريرٍ بثمانينَ درهمًا فلم يَلتَفِتْ له أحدٌ، فكان هذا مِن خيرِ ما عُمِلَ."},{"id":3021,"title":"وفاة الشيخ الإمام أثير الدين أبو حيان الغرناطي .","date":["العام الهجري :745","الشهر القمري : ربيع الأول","العام الميلادي :1344"],"text":"هو الشَّيخُ العلَّامةُ الإمامُ الحافِظُ فَريدُ العَصرِ وشَيخُ الزَّمانِ، وإمامُ النُّحاةِ: أثيرُ الدين أبو حيَّان محمَّد بن يوسف بن علي بن يوسف بن حيان الغرناطي المغربي المالكيُّ ثمَّ الشافعيُّ شَيخُ البلاد المصريَّة، مَولِدُه بغرناطة في أُخريات شوال سنة 654. قرأ القرآنَ بالرِّوايات، واشتغَلَ وسَمِعَ الحديثَ بالأندلس وإفريقيَّة والإسكندريَّة والقاهرة والحجاز، وحصَّل الإجازاتِ من الشام والعراق، واجتهد في طَلَب العلم، حتى بَرَع في النحو والتصريفِ، وصار فيهما إمامَ عَصرِه، وشارَكَ في علوم كثيرة، وكان له اليَدُ الطولى في التفسيرِ والحديثِ، والشروط والفروع، وتراجم الناس وطبقاتهم وتواريخهم، خصوصًا المغاربةَ، وهو الذي جسَّرَ النَّاسَ على مُصَنَّفاتِ ابنِ مالك، ورَغَّبَهم في قراءتِها، وشَرَحَ لهم غوامِضَها، ومن أشهر مُصَنَّفاته: البحر المحيط وهو تفسيره للقرآن، ثم اختصره وسَمَّاه النهر، وله كتاب في التراجم اسمه مجاني العصر، وله تحفة الأريب في غريب القرآن، وله طبقات نحاة الأندلس، توفِّيَ في القاهرة عن 91 عامًا، وهو غيرُ أبي حيان التوحيدي الفيلسوف الصوفي المُلحِد الذي توفِّيَ سنة 414."},{"id":3022,"title":"مطر وثلج وهبوب ريح حارة شديدة بدمشق ومصر .","date":["العام الهجري :745","الشهر القمري : رمضان","العام الميلادي :1345"],"text":"كثُرَ سُقوطُ الثَّلجِ بدِمشقَ حتى خرج عن العادةِ، وأنفقوا على إزالته من الأسطحِ ما ينيفُ على ثمانين ألف درهم؛ فإنَّه أقام يسقط أسبوعين، وفي هذه السنة تواتَرَ سُقوطُ البرد بأرض مصرَ، مع ريحٍ سوداء، وشَعَث عظيمٍ، وبَرقٍ ورَعدٍ سهول، ثم أعقب ذلك عامٌ شديد الحر، بحيث تطاير منها شَرَرٌ أحرق رؤوسَ الأشجار، وزريعة الباذنجان وبعض الكتَّان، حتى اشتد خوف الناس، وضجُّوا إلى الله تعالى، وجاء مطرٌ غزير، ثم بَرْدٌ فيه يبس لم يُعهَدْ مِثلُه، فكانت أراضي النواحي تُصبِحُ بيضاءَ من كثرة الجليد، وهَلَك من شدَّة البرد جماعةٌ من بلاد الصعيد وغيرها، وأمطرت السماءُ خمسةَ أيام متواليةً حتى ارتفع الماءُ في مزارعِ القصب قَدْرَ ذراعٍ، وعَمَّ ذلك أرض مصر قَبليَّها وبحريَّها، ففسدت بالريحِ والمطر مواضِعُ كثيرة، وقلَّت أسماكُ بحيرة نستراوة وبحيرة دمياط، والخلجان وبركة الفيل وغيرها؛ لِمَوتها من البرد، فتَلِفَت في هذه السنة بعامَّةِ أرض مصر وجميع بلاد الشام- بالأمطار والثلوج والبرد، وهبوب السمائم وشدة البرد- من الزُّروعِ والأشجار، والبائهم والأنعام والدور؛ ما لا يدخُلُ تحتَ حَصرٍ، مع ما ابتليَ به أهل الشام من تجريد عساكِرِها وتسخيرِ أهلِ الضياع وتسَلُّط العربان والعشير، وقِلَّة حُرمة السلطنة مصرًا وشامًا، وقطع الأرزاق وظُلم الرعيَّة."},{"id":3023,"title":"اعتنق أهل سومطرة بإندونيسيا الإسلام وتولى الملك عليهم مسلم  .","date":["العام الهجري :746","العام الميلادي :1345"],"text":"ذكَرَ الرحَّالةُ ابنُ بطُّوطة عن مشاهدتِه لجزيرة سومطرة والإسلام فيها، ووصَفَ سُلطانَها قائِلًا: \"وهو السلطانُ المَلِكُ الظاهر من فُضَلاءِ الملوك، شافعيُّ المذهب محِبٌّ للفقهاء، يحضرون مجلِسَه للقراءة والمذاكرة، وهو كثيرُ الغزو والجهاد ومتواضِعٌ يأتي إلى صلاة الجمعة ماشيًا على قَدَميه وأهل بلاده شافعيَّةٌ محبُّون للجهاد يخرجون معه تطوعًا، وهم غالبون على من يليهم من الكُفَّار والكُفَّارُ يعطون الجزيةَ على الصُّلحِ\"، وقد ذكر ماركو بولو الذي جاء إلى هذه الجزيرةِ قبل ابن بطوطة بأقَلَّ مِن خمسين سنة، حيث كان فيها سنة 692, وقال عنها: إنَّ جميع سكان البلاد عبدةُ أوثانٍ اللهُمَّ إلَّا في مملكة برلاك الصغيرة الواقعة في الزاوية الشماليَّة الشرقية من الجزيرة؛ حيث سكان المدن وَحدَهم مُسلمون، أمَّا سكان المرتفعات فكُلُّهم وثنيُّونَ أو مُتَوحِّشونَ يأكلونَ لحومَ البَشَرِ. ولا يُعقَلُ في أنه في أقل مِن خمسين سنة ينتَشِرُ الإسلام في كل الجزيرةِ على ما وصَفَه ابن بطوطة، ولكن يبدو أنَّ ماركو بولو أراد من ذلك الوصفِ شَيئًا آخَرَ، والله أعلم، ويُذكَرُ أنَّ الإسلامَ دخَلَ إلى هذه الجُزُر عن طريق التجَّار المسلمين، وعن طريق رحلةِ كثيرٍ مِن السكان إلى بلادِ الإسلامِ للتجارة وعودتهم إلى بلادِهم دُعاةً للإسلامِ."},{"id":3024,"title":"وفاة السلطان الصالح إسماعيل بن الناصر وتولي أخيه الكامل شعبان .","date":["العام الهجري :746","الشهر القمري : ربيع الأول","العام الميلادي :1345"],"text":"هو السُّلطانُ عِمادُ الدين المَلِكُ الصَّالحُ إسماعيل بن الناصر محمد بن المنصور قلاوون؛ في ربيع الأول اشتَدَّ مَرَضُ الملك الصالح إسماعيل فدخل عليه زَوجُ أمِّه ومُدَبِّرُ مَملكتِه الأمير أرغون العلائي في عِدَّة من الأمراء لِيَعهَدَ الملك الصالحُ إسماعيل بالمُلكِ لأحدٍ مِن إخوته, وكان أرغون العلائي غَرَضُه عند أخيه شعبان؛ لكونه أيضًا ربيبَه ابنَ زوجتِه, فعارضه في شعبانَ الأميرُ آل ملك نائِبُ السلطنة، إلى أن اتَّفَق المماليك والأمراء على توليةِ شعبان، وحضروا إلى بابِ القلعة واستدعَوه، وألبَسُوه أبَّهةَ السلطنة وأركبوه بشِعارِ الملك، ومَشَت الأمراء بخدمته، والجاوشيَّة تَصيحُ بين يديه على العامَّة، ولَمَّا طَلَع إلى الإيوان وجلس على الكرسيِّ وقَبَّل الأمراءُ له الأرضَ وأحضروا المُصحَفَ لِيَحلِفوا له، فحَلَف هو أولًا أنَّه لا يؤذيهم، ثم حَلَفوا له بعد ذلك على العادة، ولُقِّبَ بالملك الكامِلِ سيف الدين أبي الفتوح شعبان, ودُقَّت البشائِرُ بسَلطنتِه بمصرَ والقاهرة، وخُطِبَ له من الغَدِ على منابِرِ مِصرَ والقاهرة، وكُتِبَ بسلطنته إلى الأقطار مِصرًا وشامًا، ثم في يوم الاثنين ثامِنَ شَهرِ ربيع الآخر جلس الملك الكامل بدارِ العدل، وجُدِّدَ له العَهدُ من الخليفةِ بحَضرةِ القضاة والأمراء، وخَلَعَ على الخليفةِ وعلى القضاة والأمراء، وكانت مدة سلطنة الصالح إسماعيل ثلاث سنين وشهرين وأحد عشر يومًا."},{"id":3025,"title":"خراب سيس بسبب ظلمهم .","date":["العام الهجري :746","الشهر القمري : شوال","العام الميلادي :1346"],"text":"قَصَد نائِبُ حَلَب سيس لطَلَب الحملِ، وقد كان تكفور صاحِبُها قد كتب في الصالحِ إسماعيل بأنَّ بلادَه خَرِبَت، فسُومِحَ بنِصفِ الخراج، فلمَّا وصل إليه قاصِدُ نائب حلب جَهَّز الحمل، وحضر كبيرُ دولته ليحَلِّفوه أنَّه ما بقى أسيرٌ مِن المسلمين في مملكتِه، كما جَرَت العادة في كل سنةٍ بتَحليفِه على ذلك، وكان في أيديهم عِدَّةٌ من المسلمين أسرى، فبَيَّتَ مع أصحابِه قَتْلَهم في الليلةِ التي تكونُ خلفه في صبيحتِها، فقَتَل كُلُّ أحدٍ أسيرَه في أوَّلِ اللَّيلِ، فما هو إلَّا أن مضى ثلثا الليلِ فخرجت في الثلث الأخير من تلك الليلة ريحٌ سوادء، معها رعدٌ وبَرقٌ أرعَبَ القلوب، وكان من جملةِ الأسرى عجوزٌ من أهل حلب في أسرِ المنجنيقيِّ، ذبَحَها عند المنجنيق، وهي تقول: \" اللهُمَّ خُذِ الحَقَّ منهم \" فقام المنجنيقيُّ يشرَبُ الخَمرَ مع أهله بعد ذَبحِها، حتى غلَبَهم السُّكرُ وغابوا عن حِسِّهم، فسَقَطَت الشمعةُ وأحرَقَت ما حولها، حتى هَبَّت الريحُ، فتطاير شَرَرُ ما احترق من البيت حتى اشتعَلَ بما فيه، وتعلقت النيران مما حوله حتى بلَغَت مَوضِعَ تكفور، ففَرَّ بنفسه، واستمَرَّت النار مدة اثني عشَرَ يومًا، فاحترق أكثَرُ القلعة، وتلف المنجنيقُ كُلُّه بالنار، وكان هو حصن سيس، ولم يُعمَلْ مِثلُه، واحترق المنجنيقي وأولادُه الستَّة وزوجته، واثنا عشر رجلًا من أقاربه، وخَرِبَت سيس، وهُدِّمَ سُورُها ومساكِنُها، وهلك كثيرٌ مِن أهلِها، وعَجَز تكفور عن بنائِها."},{"id":3026,"title":"فتنة الأعراب بالصعيد .","date":["العام الهجري :747","الشهر القمري : ربيع الآخر","العام الميلادي :1346"],"text":"اشتَدَّ فسادُ العُربان بالصعيد والفيوم والإطفيحيَّة، فأخرج الأميرُ غرلو إلى إطفيح فأمَّنَ غرلو شيخَ العربان مغنى، وأخذ في التحيُّل على نُمَي حتى قَبَض عليه، وسَلَّمَه لمغنى، فعذبه عذابًا شديدًا، فثار أصحابُه، وكبسوا الحيَّ وتلك النواحيَ، وكَسَروا عرب المغنى، وقتلوا منهم ثلاثمائةِ رَجُل وستين امرأة، وذبحوا الأطفالَ، ونهبوا الأجرانَ وهدموا البيوت، ولَحِقوا بعربان الصعيد والفيوم فكانت عِدَّةُ مَن قُتِلَ منهم في هذه السنة نحو الألفي إنسان، لم يُفَكِّر أحدٌ في أمرهم، ولا فيما أفسدوه!"},{"id":3027,"title":"خروج يلبغا اليحياوي نائب دمشق عن طاعة السلطان شعبان .","date":["العام الهجري :747","الشهر القمري : جمادى الأولى","العام الميلادي :1346"],"text":"انشغل السُّلطانُ المَلِكُ الكامِلُ شَعبان بملذَّاته وملاهيه وأعرض عن تدبيرِ الأمور، فتمَرَّدَت المماليكُ، وأخذوا حرم النَّاسِ، وقطعوا الطريقَ، وفَسَدت عِدَّةٌ من الجواري، وكَثُرَت الفِتَنُ بسَبَبِ ذلك حتى بلغ السلطانَ، فلم يعبأ بهذا، وقال: \" خلُّوا كُلَّ أحد يعمَلُ ما يريدُ!!\"، وقد تظاهر الناسُ بكلِّ قَبيحٍ، فاشتَدَّ الأمرُ على الناس بديار مصر وبلاد الشام، وكَثُرَ دعاؤهم لما هم فيه من السُّخر والمغارم، وتنكَّرت قلوب الأمراء، وكَثُرت الإشاعة بتنكُّر السلطان على الأميرِ يلبغا اليحياوي نائِبِ الشام، وأنه يريد مَسْكَه حتى بلغه ذلك فاحتَرَز على نفسه وبلغ الأمير يلبغا اليحياوي قَتْلُ يوسف أخي السلطان، وقُوَّة عزم السلطان على سَفَر الحجاز موافقةً لأغراض نسائه، فجمَعَ يلبغا أمراء دمشق، وحَلَّفَهم على القيام معه، وبرز إلى ظاهِرِ دمشق في نصف جمادى الأولى وأقام هناك وحَضَر إليه الأميرُ طرنطاي البشمقدار نائبُ حمص، والأمير أراق الفتاح نائب صفد، والأمير أستدمر نائب حماة، والأمير بيدمر البدري نائب طرابلس، فاجتمعوا جميعًا ظاهِرَ دمشق مع عسكرها، وكتبوا بخَلعِ الملك الكامل، وظاهروا بالخروجِ عن طاعته، وكتب الأميرُ يلبغا اليحياوي نائِبُ الشام إلى السلطان: \" إني أحَدُ الأوصياء عليك، وإن ممَّا قاله الشهيد رحمه الله لي وللأمراء في وصيته: إذا أقمتم أحدًا من أولادي ولم ترتَضوا سيرتَه جُرُّوه برِجْلِه، وأخرِجوه وأقيموا غيره، وأنت أفسَدْتَ المملكة، وأفقَرْت الأمراء والأجناد، وقَتَلْت أخاك، وقبَضْتَ على أكابر أمراء السلطان الشهيدِ، واشتغَلْت عن المُلْك، والتهيتَ بالنساء وشُربِ الخمر، وصِرْتَ تبيع أخيارَ الأجناد بالفِضَّة \" وذكر الأميرُ يلبغا اليحياوي له أمورًا فاحِشةً عَمِلَها، فقَدِمَ كتابه في يوم الجمعة العشرين من جمادى الأولى، فلمَّا قرأه السلطان الكامل تغيَّرَ تغيرًا زائدًا، وكتب الكامِلُ الجوابَ يتضَمَّنُ التلطُّفَ في القول، وأخرجَ الأميرَ منجك على البريد إلى الأمير يلبغا اليحياوي في الثاني عشر، ليَرجِعَه عمَّا عزم عليه، فكَثُرَت القالةُ بين الناس بخروجِ نائِبِ الشَّامِ عن الطاعةِ حتى بلغ الأمراءَ والمماليكَ، فطلب الأمراءَ إلى القلعة وأخَذَ رأيَهم، فوقع الاتفاقُ على خروج العسكر إلى الشامِ مع الأمير أرقطاي، وقَدِمَ كتاب نائب الشامِ أيضًا، وفيه خطُّ أمير مسعود بن خطير، وأمير علي بن قراسنقر، وقلاوون، وحسام الدين البقشمدار- يتضمن: \"أنك لا تصلُحُ للمُلكِ، وأنَّك إنما أخَذْتَه بالغَلَبة من غير رضا الأمراء\"، وعَدَّد ما فعله، ثم قال: \"ونحن ما بَقِينا نَصلُحُ لك، وأنت فما تصلُحُ لنا، والمصلحةُ أن تَعزِلَ نَفسَك\"، فاستدعى السلطان الكامل الأمراءَ، وحَلَّفهم على طاعته، ثم أمَرَهم بالسفر إلى الشام، فخرجوا من الغد، ثم إنَّ منجك ساعةَ وصولِه دمشق قَبَضَ عليه يلبغا اليحياوي نائِبُ الشام، وسَجَنه بالقلعة، فبعث السلطانُ الطواشي سرور الزينى لإحضارِ أخويه حاجي وأمير حسين، فاعتذرا بوَعْكِهما، وبعثت أمهاتُهما إلى الأمير أرغون العلائي والأمير الحجازي يسألانِهما في التلطُّفِ مع السلطانِ في أمرهما، ثم عرف الأمير أرغون العلائي والأمير ملكتمر الحجازي بما جرى للسلطانِ من تخوُّفِه منهما فتوحَّشَ خاطِرُ كُلٍّ منهما، وانقطع العلائي عن الخدمة وتعَلَّل، وأخَذَت المماليكُ أيضًا في التنكُّر على السلطان، وكاتَبَ بَعضُهم الأمير يبلغا اليحياوي نائِبَ الشام، واتَّفقوا بأجمعهم حتى اشتَهَر أمْرُهم وتحَدَّثَت به العامة، ووافقهم الأميرُ قراسنقر."},{"id":3028,"title":"وفاة الأمير الحاج سيف الدين آل ملك الجوكندار الناصري .","date":["العام الهجري :747","الشهر القمري : جمادى الآخرة","العام الميلادي :1346"],"text":"هو الأميرُ الكبيرُ سَيفُ الدين الحاج آل ملك الجوكندار الناصري، نائِبُ السَّلطنة بالديار المصرية، أصله من كسب الأبلستين في الأيام الظاهريَّة بيبرس في سنة 676، واشتراه قلاوون ومعه سلَّار النائب، فأنعم بسلار على ولَدِه علي، وأنعم بآل ملك هذا على ولَدِه الآخر, وقيل قدَّمَه لصِهْرِه الملك السعيد بركة خان ابن الملك الظاهر بيبرس، فأعطاه الملك السعيد لكوندك, وترقَّى آل ملك في الخَدَم إلى أن صار من جملةِ أمراء الديار المصرية. وتردَّد للملك الناصر محمد بن قلاوون في الرسليَّة لَمَّا كان بالكرك من جهة المَلِك المظفَّر بيبرس الجاشنكير، فأَعجَبَ الملِكَ الناصِرَ عَقلُه وكلامُه، فلمَّا أن عاد الملك الناصر إلى مُلكِه رقَّاه وولَّاه الأعمالَ الجليلة إلى أن وَلِيَ نيابة السلطنة بديار مصر في دولة الملك الصالح إسماعيلَ بعد أن شَرَط على السلطان ألا يفعَلَ شيئًا في المملكة إلا برأيِه وأنه يمنَعَ الخَمرَ مِن البيع ويقيم منار الشَّرعِ وأنَّه لا يعارَضُ فيما يفعَلُه. فقَبِلَ السلطان شروطه، فكانت له أيادٍ بيضاءُ في الاحتسابِ وإقامةِ مَنارِ الشَّرعِ في مِصرَ والشَّامِ, وأنشأ المدرسة الملكية سنة 719 بالقاهرة وتُعرَفُ بجامع الجوكندار, فلمَّا وليَ الملك الكامل شعبان عَزَله من نيابة مصر, وأخرجه لنيابة صفد، ثمَّ طَلَبه وقَبَض عليه وقتَلَه. وقيل وُجِدَ مقتولًا بالإسكندرية، وأُحضِرَ مَيِّتًا إلى القاهرة في يوم الجمعة تاسِعَ عشر جمادى الآخرة."},{"id":3029,"title":"خلع السلطان الكامل شعبان وقتله وتولية أخيه المظفر حاجي  .","date":["العام الهجري :747","الشهر القمري : جمادى الآخرة","العام الميلادي :1346"],"text":"إنَّ الأمراءَ كُلَّهم تنكَّروا للسلطان الملك الكامل شعبان لِما ظهر منه من أمورٍ استوجَبَت بُغضَهم له، فألحَّ السلطان في طَلَبِ أخويه المسجونَينِ حسن وحاجي، ثم حصلت بذلك فِتنةٌ وآلت إلى الحرب بين الأمراء، وطَلَب السلطانُ الأميرَ أرغون العلائي واستشاره، فأشار عليه بأن يركَبَ بنَفسِه إليهم، فركِبَ ومعه الأمير أرغون العلائي وقطلوبغا الكركي وتمر الموساوي، وعِدَّة من المماليك، وأمر السلطانُ فدُقَّت الكوسات حربيًّا، ودارت النقباءُ على أجناد الحلقة والمماليك ليركبوا، فركب بعضُهم وسار السلطانُ في ألف فارس حتى قابَلَ الأمراء، فانسَلَّ عنه أصحابُه، وبَقِيَ في أربعمائة فارس، فبَرَز له آقسنقر ووقف معه، وأشار عليه أن ينخَلِعَ من السلطنةِ، فأجابه إلى ذلك وبكى، فتركه آقسنقر وعاد إلى الأمراء، وعَرَّفَهم ذلك، فلم يَرْضَ أرغون شاه، وبدَرَ ومعه قرابغا وصمغار وبزلار وغرلو في أصحابِهم حتى وصلوا إلى السلطان، وسَيَّروا إلى الأمير أرغون العلائي أن يأتيَهم؛ ليأخذوه إلى عند الأمراء، فلم يوافِقِ الأميرُ أرغون العلائي على ذلك، فهَجَموا عليه، وفَرَّقوا من معه، وضربوه بدبوس حتى سَقَط إلى الأرص، فضربه يلبغا أروس بسيف قطَعَ خَدَّه، وأُخِذَ أسيرًا، فسُجِنَ في خزانة شمايل، وفَرَّ السلطان الكامل شعبان إلى القلعة، واختفى عند أمِّه زوجة الأمير أرغون العلائي، وسار الأمراءُ إلى القلعة، وأخرجوا أميرَ حاجي وأمير حسين من سجنِهما، وقَبَّلوا يدَ حاجي، وخاطبوه بالسلطنة، ثم طلبوا الكامِلَ شعبان وسَجَنوه، حيث كان أخواه مَسجونَينِ، ثمَّ قُتِلَ شعبان في يوم الأربعاء وقتَ الظهر، ودُفِنَ عند أخيه يوسف ليلة الخميس فكانت مدة حكمه سنة وثمانية وخمسين يومًا، وجلس حاجي على سريرِ الملك، في يوم الاثنين مستهَلَّ جمادى الآخرة، ولُقِّبَ حاجي بالمَلِك المظَفَّر، وله مِن العمر خمس عشرة سنة، وقَبَّل الأمراءُ الأرض بين يديه، وحَلَف لهم أولًا أنَّه لا يؤذي أحدًا منهم، ولا يخَرِّبُ بَيتَ أحدٍ، وحلفوا له على طاعتِه، وركب الأميرُ بيغرا البريد ليبشِّرَ الأمير يلبغا اليحياوي نائِبَ الشام، ويحَلِّفَه وأمراءَ الشام."},{"id":3030,"title":"المرينيون يحتلون تونس وينهون دولة الحفصيين فيها .","date":["العام الهجري :748","العام الميلادي :1347"],"text":"بعد وفاةِ أبي يحيى المتوكِّل أبي بكر الحفصي ظهَرَت فِتَنٌ أثارها أمراءُ البيت الحفصي؛ ممَّا أتاح الفرصةَ أمام بني مرين بزعامة مَلِكِهم أبي الحسن علي بن عثمان للانقضاضِ على دولتِهم، فسار إلى تونس واستولى عليها، وفَرَّ أبو الحسن بن أبي حفص عمر الثاني ملك الحفصيينَ، ثمَّ قبض عليه بعد ذلك وقُتِل، فتمَّ للمرينيين مُلكُ المغرب كلِّه الأقصى والأوسط والأدنى."},{"id":3031,"title":"وقعة بين الأرمن والمسلمين في كوار .","date":["العام الهجري :748","الشهر القمري : محرم","العام الميلادي :1347"],"text":"قَدِمَ البريدُ مِن حَلَب بأنَّ صاحِبَ سيس جهَّزَ مائتي أرمني إلى ناحية أياس، فلما قَرُبوا من كوار ليهجُموا على قلعتها، قاتَلَهم أربعون من المسلمين، فنصرهم الله على الأرمن، وقَتَلوا منهم خمسينَ، وأسروا ثلاثينَ، وهزموا باقيَهم، فقُتِلَ بكوار عِدَّةٌ مِمَّن أُسِر، وحُمِلَ بقيَّتُهم إلى حلب، فكُتِبَ بالإحسانِ إلى أهل كوار والإنعامِ عليهم."},{"id":3032,"title":"السلطان المظفر حاجي قتل نائبه بالشام يلبغا اليحياوي .","date":["العام الهجري :748","الشهر القمري : جمادى الآخرة","العام الميلادي :1347"],"text":"لَمَّا كَثُرَ قَتلُ السلطانِ المظَفَّر حاجي للأمراءِ، أثار حفيظةَ نائِبِ السلطان بالشَّامِ مَلِكِ الأمراء يلبغا اليحياوي عليه، فعَمِلَ على مراسلةِ نائب صفد ونائبِ حماة على أن يتَّفِقوا على قتل السُّلطانِ المظَفَّر كما قَتَل الأمراء؛ حيث زاد شَرُّه وكَثُر الفسادُ، فوافقه نائِبُ حماة في الظاهر، وأوصل الخبَرَ إلى مصر، فسَيَّرَ السلطان جيشًا مع بعض الأمراءِ للقَبضِ على يلبغا وتوليةِ غَيرِه إمرةَ دِمشق، فعَلِمَ بذلك يلبغا فهرب هو وبعضُ مماليكه حتى وصل إلى حماة فاستقبَلَه نائِبُها على أنَّه معه، ولكِنَّه قبض عليه وسجَنَه عنده، ثمَّ في يوم الجمعة العاشر من جمادى الآخر قتَلَه نائبُ حماة وجهَّزَ رأسَه وأرسَلَه إلى القاهرة للسُّلطانِ المظَفَّر حاجي، وقيل: قُتِلَ يلبغا فيما بين قاقون وغبرة، وكذلك قُتِلَ بغبرة الأمراءُ الثلاثة الذين خرجوا من مِصرَ وحاكمُ الوزير ابن سرد ابن البغدادي، والدوادار طغيتمر وبيدمر البدري، أحد المقَدَّمين، كان قد نَقَم عليه السلطان ممالأةَ يلبغا، ثم أُخِذَت رؤوسهم إلى السلطان، وقَدِمَ أميران من الديار المصرية بالحوطة على حواصل يلبغا وطواشي من بيت المملكة، فتسَلَّم مصاغًا وجواهر نفيسة جدًّا، ورسم ببيع أملاكِه وما كان وقَفَه على الجامِعِ الذي كان قد شرع بعمارته بسوق الخيلِ، ثم طُلِبَ بقيَّةُ أصحابه من حماة فحُمِلوا إلى الديار المصرية وعَدِمَ خَبَرُهم، فلا يُدرى على أيِّ صفة هلكوا, وأصبح نائبًا عن السلطان في دمشقَ الأميرُ سيف الدين أرغون شاه."},{"id":3033,"title":"اغتيال السلطان المظفر حاجي وتولية أخيه حسن ناصر الدين .","date":["العام الهجري :748","الشهر القمري : رمضان","العام الميلادي :1348"],"text":"هو السُّلطانُ المَلِكُ المظَفَّر سيف الدين حاجي بن الناصر محمد بن قلاوون، تولَّى السلطنةَ بعد قَتْلِ أخيه السلطان الكامل شعبان، وعُمُرُه خمس عشرة سنة، وقد حلف للأمراءِ ألَّا يؤذيَهم وحَلَفوا له على الطاعةِ، لكِنْ لَمَّا كَثُرَ اشتِغالُه في اللَّعِبِ بالحَمامِ وتقريب الأوباش واللعَّابين وغيرِهم من أرباب الملاهي والفساد، أنكر عليه الأمراءُ أكثَرَ مِن مَرَّة، حتى حصل بينه وبينهم جفاءٌ, وعمل السلطان على التدبيرِ لقَتلِ بَعضِهم، وهم كذلك عَمِلوا على تدبير قَتْلِه، فتحادث الأمراءُ فيما بينهم واتفقوا وتواكدوا جميعًا في يوم الخميس تاسِعَ رمضان على الركوبِ في يوم الأحد ثاني عشر، فما ارتفع النهار حتى وقفوا بأجمَعِهم لابسين آلةَ الحرب، عند قُبَّة النصر ومعهم النائِبُ أرقطاي، فأرسل السلطان المظفَّر الرَّسولَ إليهم يستخبِرُه عمَّا يريدونَه منه حتى يفعَلَه لهم، فأعادوا جوابَه أنَّهم لا بُدَّ أن يُسلطِنوا غيره، فقال: ما أموتُ إلَّا على ظَهرِ فَرسي، فقَبَضوا على رسولِه، وهمُّوا بالزحف إليه، فمنعهم الأميرُ أرقطاي النائب، فبادر السلطانُ بالركوب إليهم، وأقام أرغون الكاملي وشيخو في الميسرة، وأقام عِدَّةَ أمراء في الميمنة، وسار بمماليكِه حتى وصل إلى قريبِ قُبَّة النصر، فكان أوَّلَ من تركه الأمير أرغون الكاملي والأمير ملكتمر السعيدي، ثمَّ الأمير شيخو، وأتوا الأمير أرقطاي النائب والأمراء، وبقي السلطانُ في نحو عشرين فارسًا، فبَرَز له الأميرُ بيبغا روس والأمير ألجيبغا، فولى فرَسَه وانهزم عنهم، فأدركوه وأحاطوا به، فتقَدَّمَ إليه بيبغا روس، فضربه السلطانُ بطير، فأخذ الضربةَ بتُرسِه، وحمل عليه بيبغا بالرمح، وتكاثروا عليه حتى قَلَعوه مِن سَرجِه، فكان بيبغا روس هو الذي أرداه، وضرَبَه طنيرق فجرح وجهَه وأصابِعَه، وساروا به على فَرَسٍ إلى تربة آقسنقر الرومي تحت الجبل، وذبَحوه من ساعته قبل العَصرِ، وكانوا لَمَّا أنزلوه وأرادوا ذبحه توسَّل إلى الأمراء، وهو يقول: بالله لا تستعجِلوا على قتلي، وخَلُّوني ساعة، فقالوا: فكيف استعجَلْتَ على قتل الناس، لو صَبَرْتَ عليهم صبَرْنا عليك، وصَعِدَ الأمراء إلى القلعة في يومِهم، ونادوا في القاهرة بالأمانِ والاطمئنان، وباتوا بها ليلةَ الاثنين، وقد اتفقوا على مكاتبةِ الأمير أرغون شاه نائب الشام بما وقع، وأن يأخذوا رأيَه فيمن يقيمونَه سلطانًا، فأصبحوا وقد اجتمع المماليكُ على إقامة حسن بن الناصر محمد بن قلاوون في السلطة، ووقعت بينه وبينهم مُراسَلات، فقَبَض الأمراء على عِدَّةٍ مِن المماليك، ووكلوا الأميرَ طاز بباب حسن، حتى لا يجتَمِعَ به أحد، وغَلَّقوا باب القلعة، وهم بآلة الحرب يومَهم وليلة الثلاثاء، وقَصَد المماليك إقامةَ الفتنة، فخاف الأمراء تأخير السلطة حتى يستشيروا نائِبَ الشام أن يقَعَ مِن المماليك ما لا يُدرَكُ فارِطُه، فوقع اتفاقُهم عند ذلك على حسن بن الناصر محمد بن قلاوون، فتَمَّ أمره، فكانت مُدَّةُ المظَفَّر حاجي سنة وثلاثة أشهر واثني عشر يومًا، وعُمُره نحو عشرينَ سنة، فقام الأمراءُ بسلطنة حسن هذا، وأركبوه بشعار السلطنة في يوم الثلاثاء رابع عشر رمضان، سنة 748، وأجلسوه على تخت الملك بالإيوان، ولَقَّبوه بالملك الناصر سيفِ الدين قمارى، فقال السلطان للأمير أرقطاى نائب السلطة: يا بة! ما اسمي قمارى، إنَّما اسمي حسن، فقال أرقطاى: يا خوند- يا سيد- واللهِ، إن هذا اسم حَسَنٌ على خيرة الله، فاستقرت سلطنتُه، وحلف له الأمراء على العادة، وعمره يومئذ إحدى عشرة سنة."},{"id":3034,"title":"وفاة الإمام العلامة الحافظ شمس الدين الذهبي .","date":["العام الهجري :748","الشهر القمري : ذي القعدة","العام الميلادي :1348"],"text":"هو الشَّيخُ الإمامُ العلَّامة الحافِظُ شَمسُ الدين أبو عبد الله محمد بن أحمد بن عثمان بن قايماز الذهبي خاتمةُ الحُفَّاظ، كان من أسرة تُركمانيَّة الأصل، تنتهي بالولاءِ إلى بني تميم، سكنت مدينة ميافارقين من أشهَرِ مدن ديار بكر، ولِدَ في كفر بطنا قرب مدينة دمشق في شهرِ ربيع الآخر سنة 673, وهو حافِظٌ لا يُجارَى ولافِظٌ لا يُبارى، أتقَنَ عِلمَ الحديث ورجالَه، ونظَرَ عِلَلَه وأحوالَه، وعرف تراجم الناس وأزال الإبهام في تواريخهم, واشتهَرَ بالعِلمِ والورع؛ قال السيوطي: \"حُكِيَ عن شيخ الإسلام أبي الفضلِ ابنِ حَجَر أنَّه قال: شَرِبتُ ماء زمزم لأصِلَ إلى مرتبة الذهبيِّ في الحفظِ, ثم قال السيوطي: والذي أقولُه: إن المحَدِّثين عيالٌ الآن في الرجالِ وغَيرِها من فنونِ الحديث على أربعةٍ: المِزِّي، والذَّهَبي، والعِراقي، وابن حجر\" ومُصَنَّفاته كثيرةٌ جِدًّا تُنبِئ عن عِلمِه الزاخر في الحديث والرجال والتاريخ، فله كتب مشهورة، منها: كتاب تاريخ الإسلام وطبقات مشاهير الأعلام، وكتاب سير أعلام النبلاء، وله في الرجال كتب كثيرة أشهرها: ميزان الاعتدال في أحوال الرجال، وتذكرة الحُفَّاظ، وطبقات القُراء، وله تعليقات على المستدرك، وله كتاب الكبائر، والطب النبوي، وغيرها كثير يصعُب حَصرُه هنا، وقف الشيخ كمال الدين ابن الزملكاني على تاريخه الكبير المسمى بتاريخ الإسلام جزءًا بعد جزء إلى أن أنهاه مطالعةً وقال: \"هذا كتابُ عَلَمٍ اجتمَعْتُ به وأخذتُ عنه وقرأتُ عليه كثيرًا من تصانيفه، ولم أجِدْ عنده جمودَ المحدِّثين، ولا كَودَنة النَّقلة، بل هو فقيهُ النَّظَر، له دُربة بأقوالِ النَّاسِ ومذاهِبِ الأئمة من السلف وأرباب المقالاتِ، وأعجبني منه ما يعانيه في تصانيفِه مِن أنه لا يتعدى حديثًا يورده حتى يبيِّنَ ما فيه من ضَعفِ مَتنٍ أو ظَلامِ إسنادٍ أو طَعنٍ في رواتِه، وهذا لم أرَ غَيرَه يراعي هذه الفائدةَ فيما يورده. توفي في ليلة الاثنين ثالث شهر ذي القعدة، وصُلِّيَ عليه يوم الاثنين صلاة الظهر في جامع دمشق ودُفِنَ بباب الصغير."},{"id":3035,"title":"أوضاع دولة الترك في مصر والشام مع مطلع هذا العام .","date":["العام الهجري :749","العام الميلادي :1348"],"text":"استهل هذا العامُ وسُلطان البلاد المصرية والشاميَّة الملك الناصر ناصر الدين حسن بن الملك الناصر محمد بن قلاوون، ونائِبُه بالديار المصريَّة الأميرُ سَيفُ الدين يلبغا، ووزيرُه منجك، وقضاتُه عز الدين بن جماعة الشافعي، وتقي الدين الأخنائي المالكي، وعلاء الدين بن التركماني الحنفي، وموفَّق الدين المقدسي الحنبلي، وكاتِبُ سِرِّه القاضي علاء الدين بن محيي الدين بن فضل الله العمري، ونائب الشام المحروس بدمشق الأمير سيف الدين أرغون شاه الناصري، وحاجب الحجَّاب الأمير طيردمر الإسماعيلي، والقضاة بدمشق قاضي القضاة تقي الدين السبكي الشافعي، وقاضي القضاة نجم الدين الحنفي، وقاضي القضاة جلال الدين المسلاتي المالكي، وقاضي القضاة علاء الدين بن منجا الحنبلي، وكاتب سِرِّه القاضي ناصر الدين الحلبي الشافعي، وهو قاضي العساكر بحلب، ومدرس الأسديَّة بها أيضًا، مع إقامته بدمشق المحروسة."},{"id":3036,"title":"وفاة الشيخ عبد الله بن رشيق المغربي كاتب شيخ الإسلام ابن تيمية .","date":["العام الهجري :749","العام الميلادي :1348"],"text":"هو الشَّيخُ عبد الله بن رشيق المغربي، كاتِبُ مُصَنَّفات العلَّامة ابن تيمية، كان أبصَرَ بخَطِّ الشيخ منه، إذا عَزَب شيءٌ منه على الشيخِ استخرجه عبدُ الله هذا، وكان سريعَ الكتابةِ لا بأس به، دَيِّنًا عابدًا كثيرَ التلاوة حَسَن الصلاة، له عيالٌ وعليه ديونٌ."},{"id":3037,"title":"الفتنة بالكرك بين بني نمير وبني ربيعة .","date":["العام الهجري :750","العام الميلادي :1349"],"text":"اشتَدَّت الفتنة في بلاد الكرك بين بني نمير وبني ربيعة، فإن المَلِكَ الناصر محمد بن قلاوون كان لَمَّا أعياه أمرُهم وتحصُّنُهم بجبالهم المنيعة، أخذ في الحيلة عليهم، وتقَدَّم إلى شطي أمير بني عقبة، وإلى نائب الشام ونائب غزة ونائب الكرك، بأن يدخُلوا إلى البرية كأنهم يصطادونَ ويوقعونَ بهم، فقبضوا على كثيرٍ منهم، وقَتَلوا في جبالهم خلقا كثيرًا منهم، وحَبَسوا باقيَهم حتى ماتوا، فسَكَن الشرُّ بتلك الجهات إلى أن كانت فتنةُ الناصر أحمد بن محمد بن قلاوون بالكرك سنة 743، عاد بنو نمير وبنو ربيعة إلى ما كانوا عليه من الفسادِ، وقَوِيَ أمرهم، فلما كان هذا العام رَكِبَ إليهم الأمير جركتمر نائب الكرك، وطلع إليهم فقاتلوه، وقتلوا من أصحابِه عشرة، وكسروه أقبحَ كَسرةٍ، فكتب لنائب الشام الأمير أرغون شاه بتجهيز عسكرٍ لقتالِهم."},{"id":3038,"title":"وفاة الشيخ علاء الدين المارديني التركماني الحنفي .","date":["العام الهجري :750","الشهر القمري : محرم","العام الميلادي :1349"],"text":"هو الإمامُ الشيخ علاءُ الدين علي ابنُ القاضي فخر الدين عثمان بن إبراهيم بن مصطفى المارديني الحنفي المعروف بالتركماني، ومولِدُه في سنة 683، كان إمامًا فقيهًا بارعًا نحويًّا أصوليًّا لغويًّا، أفتى ودرَّس واشتغل وألَّف وصَنَّف، وكان له معرفةٌ تامَّةٌ بالأدب وأنواعه، وله نظمٌ ونَثرٌ، كان إمامَ عَصرِه لا سيَّما في العلوم العقلية والفقه أيضًا والحديث، وتصدى للإقراءِ عِدَّة سنين، وتولى قضاء الحنفيَّة بالديار المصرية في شوال سنة 748، عوضًا عن قاضي القضاة زين الدين البسطامي، وحسُنَت سيرته، ودام قاضيًا إلى أن مات، وتولى عِوَضَه ولده جمال الدين عبد الله، من مصَنَّفاته كتاب بهجة الأريب في بيان ما في كتاب الله العزيز من الغريب، والمنتخب في علوم الحديث، والمؤتلف والمختلف، والضعفاء والمتروكون، والدر النقي في الرد على البيهقي، ومختصر المحصل في الكلام، ومقدمة في أصول الفقه، والكفاية في مختصر الهداية، ومختصر رسالة القشيري، وغير ذلك. توفِّيَ يوم الثلاثاء عاشرَ المحَرَّم بالقاهرة."},{"id":3039,"title":"قتال العشير والعربان بسبب كثرة فسادهم ببلاد القدس ونابلس .","date":["العام الهجري :750","الشهر القمري : جمادى الآخرة","العام الميلادي :1349"],"text":"في عاشر جمادى الآخرة خرجت التجريدة- جيش بدون رجالة- من مصرَ إلى قتال العشير والعُربان، وسببه كثرةُ فسادهم ببلاد القُدس ونابلس، وكان قد قُبِضَ على أدى بن فضل أمير جرم، وسُجِن بقلعة الجبل، ثم أُفرِجَ عنه بعناية الوزير منجك، فجمع أدى وقاتل سنجر بن علي أمير ثعلبة، فمالت حارثة مع أدى، ومالت بنو كنانة مع سنجر، وجرت بينهم حروبٌ كثيرة، قُتِلَ فيها خلائق، وفسدت الطرقاتُ على المسافرين، فخرجت إليهم عساكِرُ دمشق، فلم يَعبؤوا بهم، فلمَّا وَلِيَ الأمير يلجك غزة استمال أدى بعد أيام، وعَضَّده على ثعلبة، واشتدت الحروب بينهم، وفسدت أحوالُ الناس، فركب يلجك بعسكر غزة ليلًا، وطرَقَ ثعلبة، فقاتلوه وكَسَروه كسرةً قبيحة، وألقَوه عن فرسه إلى الأرض، وسَحَبوه إلى بيوتهم فقام سنجر بن علي أمير ثعلبة عليهم حتى تركوا قَتْلَ يلجك، بعد أن سَلَبوا ما عليه، وبالَغوا في إهانته، ثم أفرجوا عنه بعد يومينِ، فعاد يلجك إلى غزة، وقد اتَّضَع قَدرُه وتَقَوَّى العشير بما أخذوه من عسكره، وعَزَّ جانبهم، فقصدوا الغور، وكبسوا القصيرَ المعيني، وقتلوا به جماعةً كثيرة من الجبلية وعمال المعاصر، ونهَبوا جميعَ ما فيه من النقود والأعمال والعسكر وغيره، وذبحوا الأطفالَ على صدر الأمهات، وقطعوا الطُّرُقات، فلم يَدَعوا أحدًا يمر من الشام إلى مصر حتى أخَذوه، وقصدوا القدس، فخلى الناسُ منه ثم قصدوا الرملةَ ولِدَّ فانتهبوها، وزادوا في التعدي، وخرجوا عن الحد، فوقع الاتفاقُ على ولاية الأمير سيف الدين دلنجي نيابة غزة، وأبقى على إقطاعه بمصر، وخلع عليه وأخرج إليها وكَتَب بخروج ابن صبح من دمشق على ألفي فارس، وتجهَّز الوزير منجك ومعه ثلاثةُ أمراء من المقَدَّمين في يوم السبت الرابع عشر، وبينما الوزير ومن معه في أُهبة السفر إذ قدم الخبر أن الأمير قطيلجا توجَّه من حماة إلى نيابة حلب، عوضًا عن الأمير أرقطاي, وقد قَدَّم الوزير النجابةَ لكشف أخبار العشيرة، فلما رحل عن بلبيس عادت نجابتُه بأن ثعلبة ركبت بأجمعها، ودخلت بريَّة الحجاز، لَمَّا بلَغَهم مسير العسكر إليهم، فنهب أدى بن فضل كثيرًا منهم، وانفرد في البلاد بعشيرة، فعاد الوزيرُ بمن معه، وعبَرَ القاهرة في الثاني عشر بعد أربعة أيام، ثم في مستهَلِّ رجب قَدِمَ الخبر بأن الأمير دلنجي نائب غزة بلغه كثرةُ جميع العشيرة، وقَصْدهم نهب لد والرملة، فركب إليهم ولقيهم قريبًا من لد، منزل تجاههم، وما زال يراسِلُهم ويخدعهم حتى قدم إليه نحو المائتين من أكابِرِهم، فقبضهم وعاد إلى غزة، وقد تفَرَّق جمعهم، فقدم الأمير قبلاي غزة، واحتال على أدى حتى قدم عليه، فأكرمه وأنزله، ثم ردَّه بزوادة إلى أهلِه فاطمأنت العشرات والعُربان لذلك، وبقُوا على ذلك إلى أن أهلَّ رمضان، ثم حضر أدى في بنى عَمِّه لتهنئة قبلاي بشهر الصومِ، فساعة وصوله إليه قُبِضَ عليه وعلى بني عمه الأربعة، وقَيَّدَهم وسَجَنَهم، وكتب إلى سنجر بن علي: \"بأني قد قبضت على عدوِّك ليكونَ لي عندك يدٌ بيضاء، فسُرَّ سنجر بذلك، وركب إلى قبلاي، فتلقَّاه وأكرمه، فضَمِنَ له سنجر درك البلاد، ورحل قبلاي من غده ومعه أدى وبنو عمه يريد القاهرة، فقدم في يوم الاثنين حادي عشر، فضربوا على باب القلة بالمقارع ضَربًا مبرحًا وألزم أدى بألفِ رجل ومائتي ألف درهم، فبَعَث إلى قومه بإحضارها، فلما أُخِذَت سُمِّرَ هو وبنو عمه في يوم الاثنين خامس عشر وقت العصر، وسُيِّروا إلى غزة صحبة جماعةٍ من أجناد الحلقة، فوُسِّطوا- قُتلوا- بها، فثار أخو أدى، وقَصَد كبس غزة، فخرج إليه الأميرُ دلنجي ولَقِيَه على ميل من غزة، وحاربه ثلاثة أيام، وقتَلَه في اليوم الرابع بسَهمٍ أصابه، وبعث دلنجي بذلك إلى القاهرة، فكتب بخروج نائب صفد ونائب الكرك لنجدته."},{"id":3040,"title":"معركة بين بني مرين وبني عبد الواد بنو زيان .","date":["العام الهجري :751","العام الميلادي :1350"],"text":"بعد أن خرج أبو الحسن المريني من تونُسَ وعاد الحفصيُّون إلى تمَلُّكِها، رَكِبَ أبو الحسين الزيان البحر يريد الجزائرَ ومعه ستمائة سفينة، وفي الطريق غرقت أكثر السفن من الرياح والأمواج العالية، فوصل بعدد قليلٍ إلى الجزائر، وكانت بنو عبد الواد بنو زيان قد تجهزت لاسترداد ملكهم من بني مرين الذين استولوا على الجزائر من سنة 748 وحاول أبو الحسن هذا أن يصدَّهم عنها مستعينًا بقلة ممن نجا معه من الرجال فجرت بين الفريقين حروبٌ هُزم فيها أبو الحسن وولَّى هاربًا بعد أن قُتِلَ ابنه الناصر في هذه الحروب."},{"id":3041,"title":"وفاة ابن قيم الجوزية .","date":["العام الهجري :751","الشهر القمري : رجب","العام الميلادي :1350"],"text":"هو الشَّيخُ الإمامُ العلَّامةُ أبو عبد الله شمس الدين محمد بن أبي بكر بن أيوب الزرعي الدمشقي الحنبلي المعروفُ بابن قَيِّم الجوزيَّة، فهو إمامُ الجوزيَّة، وابنُ قَيِّمِها، ولِدَ بدمشق في سابع صفر سنة 691, وسَمِعَ الحديث واشتغل بالعلم، وبَرَع في العلوم المتعَدِّدة، لا سيما علم التفسير والحديث والأصلين، ولَمَّا عاد الشيخ تقي الدين بن تيمية من الديار المصرية في سنة 712 لازَمَه إلى أن مات الشيخُ، فأخذ عنه علمًا جَمًّا لازمه قرابة 16 عامًا وتأثَّر به, وسُجِنَ في قلعة دمشق في أيام سجنِ ابن تيمية، وخرج بعد أن توفِّيَ شيخه عام 728 ولم يخَلِّفِ الشيخُ العلَّامة تقي الدين ابن تيميَّة مِثلَه، ومع ما سَلَف له من الاشتغال، صار فريدًا في بابِه في فنونٍ كثيرة، مع كثرةِ الطَّلَب ليلًا ونهارًا، وكثرة الابتهال، وكان حَسَن القراءة والخُلُق، كثيرَ التودد لا يحسُد أحدًا ولا يؤذيه، ولا يستعيبُه ولا يحقِدُ على أحد؛ قال ابن رجب: \"كان ذا عبادةٍ وتهَجُّد وطولِ صلاةٍ إلى الغاية القصوى، وتألُّه ولَهَج بالذكر، وشَفَف بالمحبة والإنابة والاستغفار، والافتقار إلى الله والانكسار له، والاطِّراح بين يديه على عتبة عبوديته، لم أشاهِدْ مِثلَه في ذلك، ولا رأيتُ أوسَعَ منه علمًا، ولا أعرَفَ بمعاني القرآن والسنَّة وحقائق الإيمان منه، وليس هو المعصومَ، ولكن لم أرَ في معناه مِثلَه، وقد امتُحِنَ وأوذيَ مَرَّات، وحُبِسَ مع الشيخ تقي الدين في المرَّة الأخيرة بالقلعة، منفرِدًا عنه، ولم يُفرَجْ عنه إلَّا بعد موت الشيخ, وكان في مُدَّة حبسه مشتغلًا بتلاوة القرآن بالتدبر والتفكر، ففُتِحَ عليه من ذلك خير كثير، وحصل له جانِبٌ عظيم من الأذواق والمواجيد الصحيحة، وتسَلَّط بسبب ذلك على الكلام في علومِ أهل المعارف، والدُّخولِ في غوامِضِهم، وتصانيفه ممتلئةٌ بذلك، وحَجَّ مرات كثيرة، وجاور بمكَّةَ، وكان أهلُ مكة يذكرون عنه من شِدَّة العبادة، وكثرة الطواف أمرًا يُتعَجَّب منه. ولازمت مجالِسَه قبل موته أزيدَ مِن سنة، وسَمِعتُ عليه قصيدته النونية الطويلة في السنة، وأشياء من تصانيفه، وغيرها \" وقال ابنُ كثير: \" كنتُ مِن أصحَبِ النَّاسِ له وأحَبِّهم إليه، ولا أعرف في هذا العالَمِ في زماننا أكثَرَ عبادةً منه، وكانت له طريقةٌ في الصلاة يطيلها جِدًّا ويمُدُّ ركوعَها وسجودَها، ويلومه كثيرٌ من أصحابه في بعضِ الأحيانِ، فلا يرجِعُ ولا ينزِعُ عن ذلك- رحمه الله\" وقال ابن حجر العسقلاني: \" كان إذا صلَّى الصبح جلس مكانَه يذكُرُ الله حتى يتعالى النَّهارُ، ويقول: هذه غَدوتي لو لم أقعُدْها سَقَطَت قُوايَ، وكان يقولُ: بالصبر واليقين تُنال الإمامةُ في الدين، وكان يقول: لا بد للسَّالك من همَّة تُسيِّرُه وترَقِّيه، وعلمٍ يُبَصِّرُه ويهديه. وكان مُغرًى بجمع الكتب فحصَّل منها ما لا يُحصَرُ حتى كان أولادُه يبيعون منها بعد موتِه دهرًا طويلًا سوى ما اصطَفَوه منها لأنفُسِهم\" وله من التصانيف الكبار والصغار شيءٌ كثير، وهي أكثَرُ مِن أن تُحصَرَ هنا، ولكن من أشهرها: زاد المعاد في هَدْي خير العباد، وإعلام الموقعين عن ربِّ العالمين، ومدارج السالكين، وبدائع الفوائد، وطريق السعادتين، وشرح منازل السائرين، والقضاء والقدر، وجلاء الأفهام في الصلاة والسلام على خير الأنام، ومصايد الشيطان، ومفتاح دار السعادة، والروح، وحادي الأرواح، ورفع اليدين، والصواعق المرسلة على الجهمية والمعطلة، وتصانيف أخرى كثيرة؛ قال ابن حجر: \"وكلُّ تصانيفه مرغوبٌ فيها بين الطوائف، وهو طويلُ النَّفَسِ فيها يتعانى الإيضاحَ جُهدَه، فيُسهِبُ جدًّا، ومعظمها من كلام شيخِه يتصَرَّفُ في ذلك، وله في ذلك مَلَكَة قويَّة، ولا يزال يدندِنُ حولَ مُفرداتِه ويَنصُرُها ويحتَجُّ لها\" ومن نَظْمِه قصيدة تبلغ ستة آلاف بيت سمَّاها الكافية في الانتصار للفرقة الناجية. ومن تلاميذه ابنه برهان الدين إبراهيم، والإمام ابن رجب الحنبلي، والحافظ ابن كثير، والحافظ ابن عبد الهادي، والإمام الذهبي، والفيروزآبادي صاحب القاموس. توفِّيَ رحمه الله في دمشق ليلة الخميس ثالث عشر رجب وقتَ أذان العشاء وصُلِّيَ عليه بعد صلاة الظهر من الغد بالجامِعِ الأموي، ودفن عند والدته بمقابر الباب الصغير، وقد كانت جنازته حافلةً، شهدها القضاة والأعيان والصالحون من الخاصة والعامة، وتزاحم الناسُ على حمل نعشه، وكَمُل له من العمر ستون سنةً."},{"id":3042,"title":"إبطال إحياء ليلة النصف من شعبان بالجامع الأموي بدمشق .","date":["العام الهجري :751","الشهر القمري : شعبان","العام الميلادي :1350"],"text":"قال ابنُ كثير: من العجائب والغرائب التي لم يتَّفِقْ مِثلُها ولم يقَعْ مِن نحو مائتي سنة وأكثر، أنَّه بطل الوقيدُ بجامع دمشق في ليلة النصف من شعبان، فلم يَزِدْ في وقيده قنديلٌ واحد على عادة لياليه في سائر السنة، ولله الحمد والمنة. وفرح أهلُ العلم بذلك، وأهلُ الديانة، وشكَرَ الله تعالى على تبطيل هذه البدعة الشنعاء، التي كان يتولَّدُ بسببها شرور كثيرة بالبلد، والاستئجار بالجامع الأموي، وكان ذلك بمرسومِ السلطان الملك الناصر حسن بن الملك الناصر محمد بن قلاوون"},{"id":3043,"title":"عودة الحفصيين إلى تونس بعد خروج بني مرين منها .","date":["العام الهجري :751","الشهر القمري : ذي القعدة","العام الميلادي :1351"],"text":"عاد أبو العبَّاس الفضل بن أبي بكر بن يحيى بن إبراهيم بن عبد الواحد بن أبي حفص في ذي القعدة ليملِكَ تونس مرة أخرى، وكان قد قَدِمَ إلى تونس السلطانُ أبو الحسن علي بن أبي سعيد عثمان بن يعقوب بن عبد الحق ملك بني مرين صاحب فاس، وملك تونس وإفريقيَّة ثم سار منها للنصف من شوال، واستخلف ابنَه أبا العباس الفضل."},{"id":3044,"title":"الفتنة بمنى بين المصريين واليمنيين .","date":["العام الهجري :751","الشهر القمري : ذي الحجة","العام الميلادي :1351"],"text":"في العاشِرِ مِن ذي الحجة قُبِضَ على صاحب اليمن المَلِك المجاهد علي بن المؤيد داود بن المظفر أبو سعيد المنصوري عمر بن رسول, وسَبَبُ ذلك أن الشريف ثقبة بن رميثة لَمَّا بلَغَه استقرار أخيه الشريف عجلان في إمرة مكَّة، توجَّهَ إلى اليمن، وأغرى المَلِكَ المجاهد علي صاحب اليمن بأخذِ مَكَّة وكسوةِ الكَعبةِ، فتجَهَّز المجاهد، وسار يريد الحَجَّ في جحفل كبير بأولادِه وأمه حتى قَرُب من مكة، وقد سبق حاجُّ مصر، فلَبِسَ عجلان آلة الحرب، وعَرَّف أمراءَ مِصرَ ما عزم عليه صاحِبُ اليمن، وحَذَّرَهم غائلَتَه، فبعثوا إليه بأنَّ \"من يريدُ الحَجَّ إنما يدخُلُ مكَّةَ بذِلَّةٍ ومسكنة، وقد ابتَدَعْتَ من ركوبك والسِّلاحُ حولك بدعةً لا يمكِنُك أن تدخُلَ بها، وابعَثْ إلينا ثقبة ليكونَ عندنا حتى تنقَضِيَ أيام الحج، ثم نُرسِلُه إليك\" فأجاب المجاهِدُ إلى ذلك، وبعث ثقبةَ رهينةً، فأكرمه الأمراء، وأركبوا الأميرَ طقطاي في جماعة إلى لقاء المجاهد، فتوجَّهوا إليه ومنعوا سلاحداريته من المشيِ معه بالسلاح، ولم يمكِّنوهم من حَملِ الغاشية، ودخَلوا به مكة، فطاف وسَمَّى، وسَلَّم على الأمراء واعتذر إليهم، ومضى إلى منزلِه وصار كل منهم على حَذَرٍ حتى وقفوا بعرفةَ، وعادوا إلى الخيفِ مِن مِنًى، وقد تقرَّر الحال بين الشريف ثقبة وبين المجاهِدِ عليٍّ أنَّ الأمير طاز إذا سارا من مكة أوقعاه بأميرِ الركبِ ومن معه، وقبضا على عجلان، وتسَلَّمَ ثُقبةُ مكَّةَ، فاتَّفَق أن الأمير بزلار رأى وقد عاد من مكَّة إلى منًى خادِمَ المجاهِدِ سائرًا، فبعث يستدعيه فلم يأتِه، وضرب مملوكَه- بعد مفاوضةٍ جَرَت بينهما- بحربةٍ في كتِفِه فماج الحاجُّ، وركب بزلار وقتَ الظهر إلى طاز فلم يَصِلْ إليه حتى أقبَلَت الناس جافلةً تُخبِرُ بركوب المجاهد بعسكَرِه للحرب، وظهرت لوامِعُ أسلحتهم، فركب طاز وبزلار والعسكَرُ، وأكثَرُهم بمكة، فكان أوَّلُ من صدم أهلَ اليمن الأميرَ بزلار وهو في ثلاثين فارسًا، فأخذوه في صدورِهم إلى أن أرمَوه قُربَ خَيمةٍ، ومَضَت فرقةٌ منهم إلى جهة طاز، فأوسع لهم، ثم عاد عليهم، ورَكِبَ الشريف عجلان والناس، فبعث طاز لعجلان \"أنِ احفَظِ الحاجَّ، ولا تدخل بيننا في حَربٍ، ودَعْنا مع غريمنا\"، واستمَرَّ القتال بينهم إلى بعد العصر، فركِبَ أهلَ اليَمَنِ الذلَّةُ، والتجأ المجاهِدُ إلى دهليزه، وقد أحيط به وقُطِعَت أطنابه، وألقَوه إلى الأرضِ، فمَرَّ المجاهِدُ على وجهِه ومعه أولادُه، فلم يجِدْ طريقًا، وعاد بمن معه وهم يصيحونَ: \"الأمانَ يا مسلمين\" فأخذوا وزيره، وتمَزَّقَت عساكره في تلك الجبال، وقُتِلَ منهم خلق كثير، ونُهِبَت أموالهم وخيولُهم حتى لم يبقَ لهم شيء، وما انفصل الحالُ إلى غروب الشمس، وفَرَّ ثُقبة بعُربه، وأخذ عبيدُ عجلان جماعةً من الحجَّاج فيما بين مكَّةَ ومِنًى، وقتلوا جماعةً، فلما أراد الأميرُ طاز الرحيل من مِنًى سَلَّمَ أم المجاهد وحريمه لعجلان، وأوصاه بهِنَّ وركب الأمير طاز ومعه المجاهِدُ مُحتَفظًا به، وبالغَ في إكرامِه، وصَحِبَ معه أيضًا الأمير بيبغا روس مقيدًا، وبعث الأمير طنطاي مبشرًا، ولَمَّا قدم الأمير طاز المدينةَ النبويةَ قَبَضَ على الشريفِ طفيل."},{"id":3045,"title":"خروج أحمد الساقي أمير صفد عن الطاعة .","date":["العام الهجري :751","الشهر القمري : ذي الحجة","العام الميلادي :1351"],"text":"سَبَبُه أنَّه لَمَّا قُبِضَ على الوزير منجك، خرج الأميرُ قمارى الحموي، وبيده ملطفات لأمراء صفد بالقَبضِ على أحمد، فبلغه ذلك من هجان جَهَّزه إليه أخوه، فندب الأمير أحمد الساقي طائفةً من مماليكه لتلَقِّي قمارى، وطلب نائب قلعة صفد وديوانه، وأمره أن يقرأَ عليه كم له بالقلعة من غَلَّة، فأمر لمماليكه منها بشيءٍ فَرَّقه عليهم إعانةً لهم على ما حصَل من المحْلِ في البلاد، وبعثهم ليأخذوا ذلك، فعندما طلعوا القلعة شَهَروا سيوفهم ومَلَكوها، فقَبَض الأمير أحمد الساقي على عِدَّة من الأمراء، وطلع بحريمِه إلى القلعة وحَصَّنَها، وأخذ مماليكُه قمارى، وأتوه به فكتب السلطان لنائب غزة ونائب الشام تجريدَ العسكر إليه، ورسَمَ بالإفراج عن فياض بن مهنا وعيسى بن حسن الهجان أمير العايد، وخلَعَ عليه وجهَّزه، وأخذت الهجن من جمال الدين بقر أمير عرب الشرقية، وأعيدت إلى علي بن حسن، وكانت الأراجيفُ قد كثرت بأن الأمير طاز قد تحالف هو والأمير بيبغا روس بعقبة أيلة، فخرج الأمير فياض وعيسى بن حسن أمير العايد؛ ليقيما على عقبة أيلة، بسبب بيبغا روس، وكتب لعرب شطي وبني عقبة وبني مهدي بالقيامِ مع الأمير فضل، وكتب لنائب غزَّة بإرسال السوقة إلى العقبة."},{"id":3046,"title":"الإغارة على الموصل .","date":["العام الهجري :751","الشهر القمري : ذي الحجة","العام الميلادي :1351"],"text":"قَدِمَ الخَبَرُ بأنَّ هند وهو أحَدُ الأكراد استولى على بلاد الموصل، وصار في جمعٍ كبير يقطَعُ الطريقَ، والتحق به نجمة التركماني، فاستنابه وتقوَّى به وركب من مندر إلى سنجار وتحصَّن بها، وأغار على الموصِلِ ونَهَب وقتل، ومضى إلى الرَّحبة وأفسَدَ بها، ومشى على بلاد ماردين ونهبها، فخرجت إليه عساكِرُ الشام، وحصروه بسنجار ومعهم عسكر ماردين، ونصبوا عليها المنجنيقَ مدَّة شهر حتى طلب هند الأمانَ، على أنه يقيمُ الخُطبةَ للسلطان، ويبعث بأخيه ونجمة في عَقدِ الصلح، وبقَطعِ قطيعة يقومُ بها كل سنة، فأمَّنَه العسكر، وسَرَوا عنه بأخيه ونجمة إلى حلب، فحُمِلَ نجمة ورفيقه إلى مصر، فلما نزلا منزلةَ قانون هرب نجمةُ."},{"id":3047,"title":"عزل السلطان الناصر بن قلاوون وتولية أخيه الصالح صلاح الدين .","date":["العام الهجري :752","الشهر القمري : جمادى الآخرة","العام الميلادي :1351"],"text":"توعَّكَ السلطانُ المَلِكُ الناصر حسن بن محمد بن قلاوون ولَزِمَ الفراشُ أيامًا، فبلغ الأميرَ طاز ومغلطاي ومنكلي بغا أنَّه أراد بإظهار توعُّكِه القَبضَ عليهم إذا دخلوا إليه، وأنَّه قد اتَّفَقَ مع قشتمر وألطنبغا الزامر وملكتمر المارديني وتنكز بغا على ذلك، وأن ينعِمَ عليهم بإقطاعاتِهم وإمراتهم، فواعدوا أصحابَهم، واتَّفَقوا مع الأمير بيبغا ططر حارس الطير النائب، والأمير طيبغا المجدي والأمير رسلان بصل، وركبوا يوم الأحدِ سابِعَ عشر جمادى الآخرة بأطلابِهم، ووقفوا عند قبة النصر، فخرج السلطانُ إلى القصر الأبلق، وبعث يسألُهم عن سبب ركوبهم، فقالوا: \"أنت اتفقت مع مماليكِك على مَسْكِنا، ولا بدَّ من إرسالهم إلينا، فبعث السلطانُ إليهم تنكز بغا وقشتمر وألطنبغا الزامر وملكتمر، فعندما وصلوا إليهم قَيَّدوهم، وبَعَثوهم إلى خزانة كايل، فسُجِنوا بها، فشَقَّ ذلك على السلطان، وقال: \" قد نزلت عن السَّلطنةِ \"، وسير إليهم النمجاة، فسلَّموها للأمير طيبغا المجدي، وقام السلطانُ إلى حريمه، فبعث الأمراءُ الأمير صرغتش، ومعه الأمير قطلوبغا الذهبي وجماعة؛ ليأخُذَه ويحبِسَه، فأخرجه صرغتمش وقد غطَّى وجهه إلى الرحبة، فلما رآه الخدام والمماليك تباكَوا عليه بكاءً كثيرًا، وطلع صرغتمش به إلى رُواق فوق الإيوان، ووكَلَ به من يحفَظُه، وعاد إلى الأمراء، وكانت مُدَّتُه ثلاث سنين وتسعة أشهر وأربعة عشر يومًا، منها مُدَّة الحجر عليه ثلاث سنين، ومدة استبداده تسعة أشهر، وكان القائِمُ بدولته الأمير شيخو رأس نوبة، ثم تولَّى صلاح الدين صالح بن الناصر محمد بن قلاوون حيث أقيمَ سُلطانًا بعد خَلْعِ أخيه الناصر حسن، وكان عمره أربع عشرة سنة، في يوم الاثنين ثامن عشر جمادى الآخرة، وذلك أنَّ الأمراء لَمَّا حُمِلَت إليهم النمجاة، باتوا ليلة الاثنين بإسطبلاتهم، وبكَّروا يوم الاثنين إلى القلعة، واجتمعوا بالرحبة داخل باب النحاس، وطلَبوا الخليفةَ والقضاة وسائر أهل الدولة، واستدعَوا به، فلمَّا خرج إليهم ألبَسوه شِعارَ السلطنة، وأركبوه فرسَ النوبة من داخل باب الستارة، ورُفِعَت الغاشية بين يديه، وكان الأميرُ طاز والأمير منكلي بغا الفخري آخذَينِ بشكيمةِ الفَرَسِ حتى جلس على التخت، وحَلَفوا له، وحلَّفوه على العادة، ولقَّبوه بالملك الصالح، ونودِيَ بسَلطنتِه في القاهرة ومصرَ."},{"id":3048,"title":"احتراق باب جيرون أحد الأبواب المشهورة لمدينة دمشق .","date":["العام الهجري :753","الشهر القمري : صفر","العام الميلادي :1352"],"text":"في ليلة الاثنين سادس عشر صفر في هذه السنة وقَعَ حَريقٌ عظيم عند باب جيرون شرقيَّه فاحترق به دكان القفاعي الكبيرة المزخرفة وما حولها، واتَّسع اتساعًا عظيمًا، واتَّصَل الحريق بالباب الأصفر من النحاس، فبادر ديوان الجامع إليه فكَشَطوا ما عليه من النحاس ونقلوه من يومه إلى خزانة الحاصل، بمقصورة الحلبية، بمشهد علي، ثم عَدَوا عليه يكَسِّرون خشبه بالفؤوس الحداد، والسواعد الشداد، وإذا هو من خشب الصنوبر الذي في غاية ما يكونُ مِن القوة والثبات، وتأسَّفَ الناس عليه؛ لكونه كان من محاسِنِ البلد ومعالمه، وله في الوجودِ ما ينَيِّفُ عن أربعة آلاف سنة، وباب جيرون المشهور بدمشق هو باب سر في جامع دمشق لم يُرَ باب أوسع ولا أعلى منه، فيما يُعرَفُ من الأبنية في الدنيا، وله عَلَمان من نحاس أصفر بمسامير نحاس أصفر أيضًا بارزة، من عجائبِ الدنيا، ومحاسن دمشق ومعالِمها، وقد تم بناؤها، وقد ذكَرَته العَرَبُ في أشعارها والناس، وهو منسوب إلى ملك يقال له جيرون بن سعد بن عاد بن عوص بن إرم بن سام بن نوح، وهو الذي بناه، وكان بناؤه له قبل الخليلِ عليه السلام، بل قبل ثمود وهود أيضًا، على ما ذكره الحافِظُ ابن عساكر في تاريخه وكان فوقه حصنٌ عظيم، وقَصرٌ منيف، ويقال: بل هو منسوب إلى اسم المارد الذي بناه لسليمان عليه السلام، وكان اسمُ ذلك المارد جيرون، والأولُ أظهَرُ وأشهَرُ، فعلى الأول يكونُ لهذا الباب من المُدَد المتطاولة ما يقارب خمسة آلاف سنة، ثم كان انجعاف هذا الباب لا من تلقاء نفسِه بل بالأيدي العاديةِ عليه، بسبب ما ناله من شَوطِ الحريق، وذكر ابن كثير: \"أن أبواب دمشق كانت سبعةً كُلٌّ منها يُتَّخَذُ عنده عيدٌ لهيكل من الهياكل السبعة، فبابُ القمر باب السلامة، وكانوا يسمونَه باب الفراديس الصغير، ولعطارد باب الفراديس الكبير، وللزهرة باب توما، وللشمس الباب الشرقي، وللمريخ باب الجابية، وللمشتري باب الجابية الصغير، ولزحل باب كيسان\""},{"id":3049,"title":"استيلاء بني مرين على تلمسان .","date":["العام الهجري :753","الشهر القمري : ربيع الأول","العام الميلادي :1352"],"text":"استولى أبو عنان فارس المتوكِّل المريني على تلمسان حاضرة بني عبد الواد، وذلك بعد معركةٍ جَرَت بينه وبين السلطانِ أبي سعيد عثمان الثاني سلطان بني زيان، وكان من نتائِجِ هذه المعركة أسْرُ أبي سعيد ثم قتله بعد ذلك، ثم استولى أبو عنان على بجاية أيضًا."},{"id":3050,"title":"خروج بيبغا روس نائب حلب عن طاعة السلطان وتسلطنه بحلب .","date":["العام الهجري :753","الشهر القمري : رجب","العام الميلادي :1352"],"text":"اتفَقَ الأمير بيبغا روس نائِبُ حلب مع الأمير أحمد الساقي نائب حماة، والأمير بكلمش نائب طرابلس على العصيان، فجُرِّدَ في يوم السبت سابع عشر رجب جماعةٌ من الأمراء وأجناد الحلقة إلى الصعيد، منهم عمر شاه الحاجب، وقماري الحاجب، ومحمد بن بكتمر الحاجب، وشعبان قريب يلبغا، وكتب لبيبغا روس نائب حلب بالحضور إلى مصر، على يَدِ سنقر وطيدمر من مماليك الحاج أرقطاي، وكتب معهما ملطفات لأمراء حلب تتضَمَّنُ أنَّه إن امتنع عن الحضور فهو معزولٌ، ورسم لهما أن يُعلِمَا بيبغا بذلك أيضًا مُشافهةً بحَضرةِ الأمراء، فقَدِمَ البريد من دمشق، بموافقة ابنِ دلغادر لبيبغا روس، وأنه تسلطن بحلب، وتلَقَّبَ بالملك العادل، وأظهر أنَّه يريد مصر لأخذِ غُرَمائِه، وهم طاز وشيخو وصرغتمش وبزلار وأرغون الكاملي نائب الشام، ثم قَدِمَ البريد بأن قراجا بن دلغادر قَدِمَ حَلَب في جمع كبير من التركمان، فركب بيبغا روس وقد واعد نائِبَ حماة ونائب طرابلس على مسيرة أول شعبان، وأنَّهم تلقوه بعساكرهم على الدستن، فركب الأمير أرقطاى الدوادار الكبير البريد، بملطفاتٍ لجميع أمراء حلب وحماة ونائب طرابلس، فقَدِمَ دمشق وبعث بالملطفات لأصحابِها، فوجد أمر بيبغا روس قد قَويَ، ووافقه النواب والعساكر والأمير زين الدين قراجا بن دلغادر تركمانه وكسابته، وجبار بن مهنا بعُربانه، فكتب الأمير أرغون الكاملي نائب الشامِ بأنَّ سَفَر السُّلطانِ لا بُدَّ منه، \"وإلا خرح عنكم جميعُه\"، فاتفق رأي الأمراء على ذلك، وخرج الأمير طاز في يوم الخميس ثالث شعبان، ومعه الأميرُ بزلار، والأمير كلتاي أخو طاز، وفارس الدين ألبكي، ثمَّ خرج الأمير طيبغا المجدي وابن أرغون النائب، ثمَّ إنَّ بيبغا روس حاول أخْذَ دمشق وحاصرها واشتَدَّ الأمر على أهل دمشق وامتنعوا عليه، فأمر بنهب البلد من الضياع والبساتينِ، ثم إن عسكر مصر بقيادة طاز وصل إلى دمشقَ فهرب بيبغا إلى حلب، ثم لجأ منها إلى ابن دلغادر ذو القدر أمير ألبستان وملاطية، ولكِنْ لم يلبَثْ الأمر كثيرًا حتى كان القبضُ عليه ومن معه من أعوانِه ثمَّ تمَّ قَتلُه بعد ذلك في السنة التالية بحَلَب؛ حيث سلَّمَه الأمير ابن دلغادر إلى نائب حلب الجديد أرغون الكاملي بعد أن حَلَفَ له الأخيرُ أنه لا يحارِبُه، ثمَّ يوم الاثنين ثامن عشر ذي الحجة قدم البريدُ مِن حَلَب بأخذ أحمد الساقي نائب حماة، وبكلمش نائب طرابلس، من عند ابن دلغادر، وقد قبَضَهما، فدخلا حلب في الحادي عشر، وسُجِنا بقلعَتِها، فأجيب الأميرُ أرغون الكاملي نائب حلب بالشكر والثناء، وأنَّه يشهر المذكورين بحلب، ويقتُلُهما، وجَهَّزَ لنائب حلب خِلعةً."},{"id":3051,"title":"وفاة الخليفة العباسي الحاكم بأمر الله وتولية أخيه أبي بكر المعتضد .","date":["العام الهجري :753","الشهر القمري : ذي الحجة","العام الميلادي :1353"],"text":"الحاكِمُ بأمر الله أبو العباس أحمد بن المستكفي بالله أبي الربيع سليمان بن الحاكم بأمر الله أبي العباس أحمد الهاشمي العباسي، كان بويِعَ بالخلافة بعد وفاةِ والده بقوص في العشرين من شعبان سنة 741، فلم يُمضِ له السُّلطانُ المَلِكُ الناصر محمد بن قلاوون ما عَهِدَه أبوه؛ لِما كان في نفسِه من والده المستكفي بالله مِن مَيلِه للمَلِكِ المظَفَّر بيبرس الجاشنكير، وأراد أن يولِّيَ الخلافة لبعض أقارِبِه، بل أحضَرَه وخَلَع عليه، ثمَّ مات المَلِكُ الناصر بعد ذلك بمُدَّة يسيرة، فتَمَّت بموتِه خلافةُ الحاكِمِ هذا إلى أن مات في هذه السَّنةِ بسَبَبِ الطاعونِ، والمتولِّي يومئذ لأمور الدِّيار المصرية الأميرُ شيخون والأمير طاز والأمير صرغتمش ونائب السلطنة الأمير قبلاي، والسُّلطان الملك الصالح، وكان الحاكِمُ مات ولم يَعهَدْ بالخلافة لأحد، فجَمَع الأمراءُ القُضاةَ، وطُلِب جماعةٌ من بني العباس، حتى وقع الاختيارُ على أبي بكر بن المستكفي بالله أبي الربيع سليمان فبايعوه ولقَّبوه بالمُعتَضِد بالله، فكانت مُدَّةُ خلافة الحاكم بأمر الله قرابة العَشرِ سنوات ونصف."},{"id":3052,"title":"خروج قراجا بن دلغادر أمير ألبستان عن طاعة السلطان ثم قتاله .","date":["العام الهجري :754","الشهر القمري : ربيع الأول","العام الميلادي :1353"],"text":"خرج عن الطاعةِ قراجا بن دلغادر أمير ألبستان وكان ممن ساعد الأمير بيبغا روس نائب حلب على الخروج أولًا ثمَّ سَلَّمه بنفسِه، وكان نائب حلب الجديد أرغوان الكاملي قد حلف له أنَّه لا يقاتِلُه إن سَلَّم له بيبغا، فلما طلب من أرغون المسيرَ إلى قراجا للقضاء عليه لعصيانِه امتنع واعتذر بأنَّه حلف له ألَّا يُقاتِلَه، ثم ألزم الأمير أرغون الكاملي نائِبَ حلب حتى سار لحرب ابن دلغادر وأتاه نوابُ القلاع حتى صار في عشرة آلاف فارس، سوى الرَّجَّالة والتركمان، ونزل الأميرُ أرغون الكاملي على الأبلستين، فنهبها وهدمها، وتوجَّه إلى قراجا بن دلغادر، وقد امتنع بجبلٍ عالٍ، فقاتلوه عشرين يومًا، فقُتِلَ فيها وجُرِحَ عدد كثير من الفريقين، فلما طال الأمرُ نزل إليهم قراجا بن دلغادر، وقاتَلَهم صدرًا من النهار قتالًا شديدًا، فاستمَرَّ القتل في تركمانه، وانهزم إلى جهة الروم، فأُخِذَت أمواله ومواشيه، وصَعِدَ العسكر إلى جبل، فوجدوا فيه من الأغنام والأبقار ما لا يكاد ينحَصِرُ، فاحتووا عليها، بحيث ضاقت أيديهم عنها، وبِيعَ الرأسُ من البقر بعشرينَ إلى ثلاثين درهمًا، والرأسُ من الضأن بثلاثةِ دراهم، والإكديش- حصان غير أصيل، أبوه من جنسٍ وأمُّه من جنس- من أربعين إلى خمسين درهمًا، وسُبِيَت نساؤه ونِساءُ تركمانه وأولاده، وبِيعوا بحَلَب وغيرها بالهوان، فكانت خيارُ بناته تباع بخمسمائة درهم، وظَفِروا بدفائنَ فيها مال كبير، وكان ابن دلغادر لَمَّا انهزم تبعه العسكر، وأسروا ولَدَيه ونحو الأربعين من أصحابِه، ونجا بخاصَّة نفسه إلى ابن أرتنا، وقد سبق الكتابُ إليه بإعمال الحيلة في قبضِه، فأكرَمَه ابن أرتنا وأواه، ثم قبض عليه وحمله إلى حلب، فدخلها وسُجِنَ بقلعتها في ثاني عشر شعبان، فكتب السلطانُ إلى الأمير أرغون الكاملي نائب حلب بحَملِه إلى مصر، وأنعم عليه بخمسمائة ألف درهم، منها ثلاثمائة ألف من مالِ دمشق، وباقيه من مال حلب، وأعفيَ الأمير أرغون من تسيير القَوَد الذي جرت عادةُ نواب حلب بحَملِه إلى السلطان من الخَيلِ والجِمال البخاتي والهجن والعراب، ومن البغال والقماش والجواري والمماليك، وقيمتُه خمسمائة ألف درهم، فعَظُم بذلك شأن الأمير أرغون الكاملي نائبُ حلب، فإنَّه مع صِغَرِ سِنِّه كان له أربعة مماليك أمراء، وله ولد عمره ثلاث سنين أميرُ مائة مقَدَّم ألف، فلما مات هذا الولد أضيفت تقدمتُه إلى إقطاع النيابة، وكان لأربعة من أخوته القادمين من البلاد وأقاربه أربع إمرات، وفي يوم الخميس خامس عشر رمضان وصل مقدم التركمان الأمير قراجا بن دلغادر، وهو مقيَّدٌ في زنجير، فأقيم بين يدى السلطان، وعُدِّدَت ذنوبه، ثم أُخرِجَ إلى الحبس، فلم يَزَل به إلى أن قَدِمَ البريد من حلب بأن جبار بن مهنا استدعى أولادَ ابن دلغادر في طائفةٍ كبيرة من التركمان، ليُنجِدوه على سيف، وكان سيف قد التجأ إلى بني كلاب، فالتقى الجمعانِ على تعبئة، فانكسر التركمانُ وقُتِلَ منهم نحو سبعمائة رجل، وأُخِذَ منهم ستمائة إكديش، فكتب السلطان من سرياقوس-وكان بها- إلى النائب قبلاي بقتل ابن دلغادر، فأخرجه من السجنِ إلى تحت القلعة ووسَّطه-قتله- في يوم الاثنين رابع عشر ذي القعدة، بعد ما أقام مسجونًا ثمانية وأربعين يومًا."},{"id":3053,"title":"فتنة العربان بالصعيد بقيادة الأحدب بن واصل .","date":["العام الهجري :754","الشهر القمري : جمادى الآخرة","العام الميلادي :1353"],"text":"كَثُرَ عَبَثُ العُربان ببلاد الصعيد بقيادة الأحدب محمد بن واصل شيخ عرك، فجمع جمعًا كبيرًا، وتسمَّى بالأمير، فقَدِمَ الخبر في شعبان بأنهم كَبَسوا ناحيةَ ملوي، وقتلوا بها نحو ثلاثمائة رجل، ونهبوا المَعاصِرَ، وأخذوا حواصِلَها وذَبحوا أبقارَها، وأنَّ عَرَب منفلوط والمراغة وغيرهم قد نافقوا، وقَطَعوا بعض الجسور بالأشمونين، فوقع الاتفاقُ على الركوب عليهم بعد تخضيرِ الأراضي بالزراعة، وكُتِبَ إلى الولاة بتجهيز الإقامات برًّا وبحرًا، فأخذَ العرب حِذْرَهم، فتفَرَّقوا واختَفَوا، وقَدِمَت طائفة منهم إلى مصر، فأُخِذوا، وكانوا عشرة، فقُبِضَ ما وجد معهم من المال، وحَمل الأمير جندار، فإنهم كانوا فلَّاحيه، وأُتلِفوا، فلما برز الحاجُّ إلى بركة الحجَّاج ركب الأمير شيخو، وضرب حلقةً على الركب، ونادى مَن كان عنده بدويٌّ وأخفاه، حَلَّ دَمُه، وفَتَّش الخيام وغيرها، فقَبض على جماعة، فقتل بعضهم وأفرج عن بَعضٍ، ثمَّ لما عاد السلطان إلى الجيزة كُبِسَت تلك النواحي، وحُذِّرَ الناس من إخفاء العربان، فأُخِذَ البحري والبري، وقُبِضَت خيول تلك النواحي وسيوفُ أهلها بأسْرِها، وعُرِضَت الرجال، فمن كان معروفًا أُفرج عنه، ومن لم يعرف أقِرَّ في الحديد وحُمِل إلى السجنِ، ورُسِمَ أنَّ الفلاحين تبيعُ خُيولَهم بالسوق، ويوردون أثمانَها ممَّا عليهم من الخراجِ فبِيعَت عِدَّةُ خيول، وأُورِدَ أثمانها للمُقطِعين، والفَرَس الذي لم يُعرَف له صاحِبٌ حُمِلَ إلى إسطبل السلطان، وكُتِبَ للأمير عز الدين أزدمر، الكاشِفِ بالوجه البحري، أن يركَبَ ويكبِسَ البلادَ التي لأرباب الجاه، والتي يأويها أهلُ الفسادِ، فقَبَض على جماعةٍ كثيرة ووسَّطَهم، وساق منهم إلى القاهرةِ نحو ثلاثمائة وخمسين رجلًا، ومائة وعشرين فرسًا، وسلاحًا كثيرًا، ثم أحضَرَ الأميرُ أزدمر من البحيرة ستمائة وأربعين فرسًا، فلم يبقَ بالوجه البحري فرس، ورُسِمَ لقضاة البر وعُدولِه بركوب البغال والأكاديش، ثم كُبِسَت البهنسا وبلاد الفيوم، فركِبَ الأميران طاز وصرغتمش، بمن معهما إلى البلاد، وقد مَرَّ أهلها، واختفى بعضهم في حفائِرَ تحت الأرض، فقبضوا النِّساء والصبيان، وعاقبوهم حتى دلوهم على الرجال، فسَفَكوا دماء كثيرين، وعُوِقَب كثيرٌ من الناس بسبب من اختفى، وأُخِذَت عدة أسلحة، فحَشَد الأحدب بن واصل شيخ عرك جموعَه، وصَمَّم على لقاء الأمراء، وحَلَف أصحابه على ذلك، وقد اجتمع معه عرَبُ منفلوط، وعَرَبُ المراغة وبني كلب وجهينة وعرك، حتى تجاوزت فرسانُه عشرة آلاف فارس تحمِلُ السلاح، سوى الرجَّالة المعَدَّة، فإنَّها لا تعَدُّ ولا تحصى لكثرتِها، ثم رحل الأمير شيخو عن أسيوط، وبعث الأمير مجد الدين الهذبانى ليؤمِّنَ بنى هلال أعداء عرك، ويُحضِرَهم ليقاتلوا عرك أعداءَهم، فانخدعوا بذلك، وفَرِحوا به، وركبوا بأسلحتِهم، وقَدِموا في أربعمائة فارس، فما هو إلا أن وصلوا إلى الأمير شيخو فأمر بأسلحَتِهم وخيولهم فأُخِذَت بأسْرِها، ووضَعَ فيهم السَّيفَ، فأفناهم جميعًا، ثم قاتلوا العَرَبَ الباقين على دفَعات يقتلونهم، وأسَروا منهم الكثيرَ واستَرَقُّوا الأولادَ والحريم، وهلك من العرب خلائقُ بالعطش، ما بين فرسان ورجَّالة وجَدَّ المجَرَّدون في طلبهم، فسَلَبوهم، وصَعِدَ كثيرٌ منهم إلى الجبال، واختَفَوا في المغائر، فقَتَلَ العسكرُ وأَسَر، وسبى عددًا كثيرًا، وارتَقَوا إلى الجبال في طَلَبِهم، وأضرَموا النيران في أبواب المغائر، فمات بها خلقٌ كثير من الدخان، وخرج إليهم جماعةٌ، فكان فيهم من يُلقي نَفسَه من أعلى الجبل ولا يُسَلِّم نَفسَه، ويرى الهلاكَ أسهَلَ مِن أخذ العدوِّ له، فهلك في الجبالِ أُمَمٌ كثيرة وقُتِلَ منهم بالسيف ما لا يُحصى كثرةً، حتى عُمِلَت عدة حفائر ومُلِئَت من رمَمِهم، وأَنتَنَت البرِّيَّةُ من جِيَفِ القتلى ورِمَمِ الخَيلِ، وكان الأحدَبُ قد نجا بنفسِه، فلم يُقدَرْ عليه، ومن حينئذ أَمِنَت الطرقات برًّا وبحرًا، فلم يُسمَعْ بقاطع طريق بعدها، ووقع الموتُ فيمن تأخَّرَ في السجون من العُربان، فكان يموتُ منهم في اليوم من عشرين إلى ثلاثين، حتى فَنُوا إلا قليلًا، وفي شهر ربيع الأول قَدِمَ الأحدب محمد بن واصل، شيخ عرك من بلاد الصعيد، طائعًا، وكان من خَبَرِه أنه لما نجا وقت الهزيمة، وأُخِذَت أمواله وحَرَمُه، ترامى بعد عَودِ العسكر على الشَّيخِ المعتقد أبى القاسم الطحاوي، فكتب الشيخ في أمره إلى الأمير شيخو، يسأل العفوَ عنه وتأمينَه، على أنَّه يقومُ بدَركِ البلاد، ويلتَزِمُ بتحصيل جميع غِلالِها وأموالِها، وما يحدُثُ بها من الفَسادِ فإنَّه مُؤاخَذٌ به، وأنَّه يقابِلُ نواب السلطان من الكُشَّاف والولاة، فكُتِب له أمانٌ سُلطاني، وكُوتِبَ بتطييب خاطِرِه وحضوره آمنًا، فسار ومعه الشيخ أبو القاسم، فأكرم الأمراءُ الشَّيخَ، وأكرموا لأجله الأحدَبَ، وكان دخولُه يومًا مشهودًا، وتمثَّل الأحدَبُ بين يدي السلطان، وأنعم عليه السلطانُ وألبسه تشريفًا وناله من الأمراءِ إنعامٌ كثيرٌ، وضَمِنَ منهم درك البلاد على ما تقدَّمَ ذِكرُه، فرُسِمَ له بإقطاعٍ، وعاد الأحدب إلى بلاده بعد ما أقام نحو شهرٍ."},{"id":3054,"title":"أسر الشريف ثقبة وإقرار الشريف عجلان على إمرة مكة .","date":["العام الهجري :754","الشهر القمري : ذي القعدة","العام الميلادي :1353"],"text":"أَسرَّ السلطانُ والأمراء مدَبِّرو الدولة إلى أمير الحاجِّ ومَن بصحبته من الأمراء أن يقبضوا على الشَّريفِ ثُقبة، ويقَرِّروا الشريفَ عَجلان بمُفردِه على إمارة مكَّة، فلمَّا قَدِمَ الحاج بطن مر، ومضى عجلانُ إلى لقائهم، شكا إلى الأمراءِ من أخيه ثقبة، وذكر ما فعلَه معه، وبكى، فطَمَّنوا قَلْبَه، وساروا به معهم حتى لَقِيَهم ثقبة في قوَّاده وعبيده، فألبسوه خِلعةً على العادة، ومَضَوا حافِّينَ به نحو مكَّةَ، وهم يحادثونَه في الصلح مع أخيه عجلان، ويحَسِّنونَ له ذلك، وهو يأبى موافقَتَهم حتى أيِسُوا منه، فمَدَّ الأمير كشلى يده إلى سَيفِه فقَبَض عليه، وأشار إلى من معه فألقَوه عن فرَسِه، وأخذوه ومعه ابنٌ لعُطَيفة، وآخَرُ من بني حسن، وكبَّلوهم بالحديد، ففَرَّ القوَّادُ والعبيد، وأُحضِرَ عَجلانُ، وأُلبِسَ التشريف، وعبروا به إلى مكة، فلم يختلف عليهم اثنانِ، وسُلِّمَ ثُقبةُ للأمير أحمد بن آل ملك، فسُرَّ الناس بذلك، وكَثُرَ جَلبُ الغلال وغيرها، فانحَلَّ السِّعرُ وقُبِضَ على إمام الزيدية أبي القاسم محمد بن أحمد اليمني، وكان يصَلِّي في الحرم بطائفَتِه ويتجاهَرُ، ونَصَب له منبرًا في الحَرَمِ يخطُبُ عليه يوم العيد وغيره، بمَذهبِه، فضُرِبَ بالمقارع ضربًا مبَرِّحًا ليرجِعَ عن مذهبه، فلم يرجِعْ وسُجِنَ، ففَرَّ إلى وادي نخلة، فلما انقضى موسِمُ الحاجِّ حُمِل الشريف ثقبة مُقَيَّدًا إلى مصرَ."},{"id":3055,"title":"إقامة الحد على رافضي شتم الصحابة .","date":["العام الهجري :755","العام الميلادي :1354"],"text":"قَدِمَ دمشقَ عليُّ بن الحسن بن أبي الفضل بن جعفر بن محمد بن كثير الحلبي الرافضيُّ، وأقام بها سنواتٍ، فاتفق أنَّه شَقَّ الصفوف والناسُ في صلاةِ جنازةٍ بالجامِعِ الأمويِّ وهو يلعَنُ ويسُبُّ من ظَلَم آلَ مُحمَّدٍ، فانتَهَره عمادُ الدين ابنُ كثيرٍ، وأغرى به العامَّةَ، وقال: إنَّ هذا يسُبُّ الصحابةَ، فحملوه إلى القاضي تقي الدين السبكي فاعترف بسَبِّ أبي بكر وعمر، فعَقَدوا له مجلسًا، فحكَم نائِبُ المالكي بضَربِ عُنُقِه بعد أن كُرِّرَت عليه التوبةُ ثلاثةَ أيامٍ، فأصَرَّ فضُرِبَت عُنُقُه بسوق الخيلِ وحَرَق العوامُّ جَسَده"},{"id":3056,"title":"محاولة قتل أمير المدينة الشريف فضل بن قاسم .","date":["العام الهجري :755","العام الميلادي :1354"],"text":"قَدِمَ الخَبَرُ مِن المدينةِ النبويَّةِ أنَّ الشَّريفَ مانع بن علي بن مسعود بن جماز وأولاد طفيل جَمَعوا ونازلوا المدينةَ، يُريدونَ قَتْلَ الشَّريفِ فَضلِ بنِ قاسم بن قاسم بن جماز فامتنَعَ بها، وهم يحاصِرونَه اثني عشر يومًا مَرَّت بينهم فيها حروب، فانهَزموا ومضَوا من حيثُ أتوا."},{"id":3057,"title":"فتنة أهل الذمة بمصر وإلزامهم بالشروط العمرية .","date":["العام الهجري :755","الشهر القمري : جمادى الآخرة","العام الميلادي :1354"],"text":"تعاظم أمرُ النَّصارى بمصر, فتباهَوا بالملابِسِ الفاخرة، وبَنَوا الأملاكَ الجليلة في مصرَ والقاهرة، واقتَنَوا الجواريَ الجميلةَ مِن الأتراك والمولَّدات، واستولَوا على دواوينِ السلطان والأمراء، وزادوا في الحُمقِ والرَّقاعة، وتعَدَّوا طَورَهم في الترفُّع والتعاظم، وأكثروا من أذى المسلمينَ وإهانتهم، وتحرَّكت الناسُ في أمر النصارى وماجوا، وانتَدَب عِدَّةٌ من أهل الخير لذلك، وصاروا إلى الأمير طاز الشريف أبى العباس الصفراوي، وبلَّغوه ما عليه النصارى مما يوجِبُه نَقضُ عَهدِهم، وانتَدَبوه لنصرة الإسلام والمسلمين، فانتفَضَ الأمير طاز لذلك، وحَدَّثَ الأميرين شيخو وصرغتمش وبقية الأمراء في ذلك بين يدي السلطانِ، فوافقوه جميعًا، وكان لهم يومئذٍ بالإسلامِ وأهلِه عِنايةٌ، ورَتَّبوا قِصَّةً على لسان المسلمين، قُرِئَت بدار العَدلِ على السلطانِ بحَضرةِ الأمراء والقُضاة وعامة أهل الدولة، فرَسَمَ بعَقدِ مَجلِسٍ للنَّظَرِ في هذا الأمر؛ لِيُحمَلَ النصارى واليهود على العهدِ الذي تقَرَّرَ في خلافة أمير المؤمنين عمر بن الخطاب رضي الله عنه، وطُلِبَ بطرك النصارى ورئيس اليهود، وحَضَرت قضاة القضاة وعلماء الشريعة، وأمراءُ الدولة، وجيء بالبطرك والرئيس، فوقفا على أرجُلِهما وقرأ العلائيُّ علي بن فضل الله كاتِبُ السر نسخةَ العهد الذي بين المسلمين وبين أهل الذمة، بعد ما أُلزِموا بإحضاره، وهو ألَّا يُحدِثوا في البلاد الإسلامية وأعمالها دِيرًا ولا كنيسةً ولا صومعةً، ولا يجَدِّدوا منها ما خَرِبَ، ولا يَمنَعوا من كنائِسِهم التي عاهدوا عليها أن يَنزِلَ بها أحدٌ مِن المسلمين ثلاثَ ليالٍ يُطعِمونَه، ولا يكتموا غشًّا للمسلمين، ولا يعَلِّموا أولادَهم القرآنَ، ولا يمنعوهم من الإسلامِ إن أرادوا، وإن أسلم أحدُهم لا يردُّوه، ولا يتشَبَّهوا بشيءٍ مِن ملابِسِ المسلمين ويلبَسُ النصرانيُّ منهم العمامةَ الزرقاءَ عَشرَ أذرُعٍ فما دونَها، واليهوديُّ العِمامةَ الصفراء كذلك، ويُمنَع نساؤُهم من التشبُّه بنساء المسلمين، ولا يتسَمَّوا بأسماءِ المُسلِمين، ولا يكتَنُوا بكُناهم، ولا يتلقَّبوا بألقابهم، ولا يركبوا على سَرجٍ، ولا يتقَلَّدوا سيفًا، ولا يركبوا الخيلَ والبِغالَ، ويركبون الحميرَ عَرضًا بالكَفِّ مِن غيرِ تزيينٍ ولا قيمةٍ عظيمة لها، ولا ينقُشوا خواتمهم بالعربيَّة، وأن يَجُزُّوا مقادِمَ رُؤوسهم، والمرأةُ من النصارى تلبَسُ الإزارَ المصبوغ أزرق، والمرأةُ مِن اليهود تلبَسُ الإزار المصبوغ بالأصفر، ولا يدخل أحَدٌ منهم الحمامِ إلَّا بعلامة ممَيِّزة عن المسلم في عُنُقِه، من نحاسٍ أو حديد أو رصاصٍ أو غير ذلك، ولا يستخدموا مُسلِمًا في أعمالهم، وتلبَسُ المرأة السائرةُ خُفَّين أحدهما أسود والآخر أبيض، ولا يجاوروا المسلمينَ بموتاهم، ولا يرفَعوا بناءَ قُبورهم، ولا يعلُوا على المسلمين في بناءٍ، ولا يضربوا بالنَّاقوسِ إلَّا ضربًا خفيفًا، ولا يرفَعوا أصواتَهم في كنائِسِهم، ولا يشتَرُوا من الرقيقِ مُسلمًا ولا مُسلِمةً، ولا ما جَرَت عليه سهامُ المسلمين، ولا يمشُوا وسَطَ الطريق توسِعةً للمُسلمين، ولا يَفتِنوا مُسلِمًا عن دينه، ولا يدُلُّوا على عوراتِ المسلمين، ومن زنى بمُسلمةٍ قُتِل، ومن خالف ذلك فقد حَلَّ منه ما يحِلُّ مِن أهل المعانَدةِ والشِّقاقِ، وكلُّ من مات من اليهود والنصارى والسامرة، ذكرًا كان أو أنثى، يَحتاطُ عليه ديوانُ المواريثِ الحَشريَّة، بالديارِ المصريَّة وأعمالِها وسائِرِ الممالك الإسلامية، إلى أن يُثبِتَ ورَثَتُه ما يستحقُّونه بمقتضى الشرع الشريف، فإذا استحَقَّ يعطونه بمقتضاه، وتُحمَلُ البقيَّةُ لبيت مال المسلمين، ومن مات منهم ولا وارِثَ له يُحمَلُ موجوده لبيتِ المال، ويُجرى على موتاهم الحوطةُ من ديوان المواريث ووكلاء بيت المال مجرى من يموتُ من المسلمين، إلى أن تُبَيَّن مواريثهم، وكان هذا العهدُ قد كتب في رجب سنة 700 في الأيام الناصريَّة محمد بن قلاوون، فلمَّا انتهى العلائي علي بن فضل الله كاتِبُ السرِّ مِن قراءته، تقلد بطركُ النصارى وديان اليهود حُكمَ ذلك، والتَزَما بما فيه، وأجابا بالسَّمع والطاعة، ثم جال الحديثُ في أمر اليهود والنصارى وإعادةِ وقائِعِهم الماضية، وأنهم بعد التزامِهم أحكام العهد يعودونَ إلى ما نُهُوا عنه، فاستقَرَّ الحال على أنهم يُمنَعونَ مِن الخِدَم في جميع الأعمال، ولا يُستخدَمُ نصراني ولا يهودي في ديوانِ السلطان، ولا في شيءٍ مِن دواوين الأمراء، ولو تلفَّظ بالإسلامِ، على أنَّ أحدًا منهم لا يُكرَهُ على الإسلام، فإن أسلم برِضاه، لا يدخُلُ مَنزِلَه، ولا يجتَمِعُ بأهله إلَّا إن اتَّبَعوه في الإسلام، ويُلزَمُ أحدُهم إذا أسلم بملازمة المساجد والجوامع، وكُتِبَ بذلك كُلِّه مراسيم سلطانية سار بها البريدُ إلى البلاد الإسلامية، فكان تاريخُها ثاني عشر جمادى الآخرة، وقُرئ منها مرسومٌ بمجلس السلطان في يوم الخميس خامس عشر، وركب من الغد يوم الجمعة سادس عشر الأميرُ سيف الدين قشتمر الحاجب، ومعه الشريف شهاب الدين المنشئ بالمراسيم السلطانيَّة إلى البلاد الإسلامية، وقُرئ مرسومٌ بجامع عمرو بن العاص من مدينة مصر، وآخَرُ بجامع الأزهر من القاهرة، فكان يومًا عظيمًا هاجت فيه حفائِظُ المسلمين، وتحَرَّكت سواكِنُهم؛ لِما في صدورهم من الحَنَق على النصارى، ونهضوا من ذلك المجلس بعد صلاة الجمعة، وثاروا باليهودِ والنصارى، وأمسكوهم من الطرقات، وتتَبَّعوهم في المواضِعِ وتناولوهم بالضرب، ومَزَّقوا ما عليهم من الثياب، وأكرهوهم على الإسلام، فيَضطرُّهم كثرةُ الضرب والإهانة إلى التلفظ بالشهادتينِ خوفَ الهلاك، فإنَّهم زادوا في الأمر حتى أضرموا النيران، وحملوا اليهود والنصارى، وألقَوهم فيها، فاختَفَوا في بيوتهم، حتى لم يوجَدْ منهم أحد في طريق ولا ممر، وشربوا مياه الآبار لامتناعِ السقَّائين مِن حَمل ِالماء من النيل إليهم، فلما شنع الأمر نُودِيَ في القاهرة ومصر ألا يُعارَضَ أحدٌ مِن النصارى أو اليهود، فلم يرجِعوا عنهم، وحَلَّ بهم من ذلك بلاءٌ شديد، كان أعظَمَه نكايةً لهم أنَّهم منعوا مِن الخِدَم بعد إسلامِهم، فإنهم كانوا فيما مضى من وقائِعِهم إذا مُنِعوا من ذلك كادوا المُسلمين بإظهارِ الإسلام، ثمَّ بالغوا في إيصال الأذى لهم بكلِّ طريق، بحيث لم يبقَ مانع يمنَعُهم لأنه صار الواحِدُ منهم فيما يظهَرُ مُسلِمًا ويَدُه مبسوطةٌ في الأعمال، وأمْرُه نافذٌ، وقولُه مُمتَثَل، فبطل ما كانوا يعملونَ، وتعطَّلوا عن الخِدَم في الديوان، وامتنع اليهودُ والنصارى من تعاطي صناعة الطب، وبذل الأقباط جُهدَهم في إبطال ذلك، فلم يجابُوا إليه، ثمَّ لم يكْفِ الناس من النصارى ما مَرَّ بهم حتى تسَلَّطوا على كنائسهم ومساكِنِهم الجليلة التي رفعوها على أبنيةِ المسلمين، فهدموها، فازداد النصارى واليهودُ خوفًا على خوفهم، وبالغوا في الاختفاءِ، حتى لم يظهَرْ منهم أحدٌ في سوق ولا في غيره، ثم وقعت قِصَصٌ على لسان المسلمين بدار العدل تتضَمَّنُ أنَّ النصارى استَجَدُّوا في كنائِسِهم عُمالًا، ووسعوا بناءها، وتجَمَّع من الناس عدد لا ينحصر، واستغاثوا بالسلطانِ في نصرة الإسلام، وذلك في يوم الاثنين رابع عشر رجب، فرسم لهم أن يَهدِموا الكنائِسَ المُستَجَدَّة، فنزلوا يدًا واحِدةً وهم يضِجُّون، وركب الأميرُ علاء الدين علي بن الكوراني والي القاهرة ليكشِفَ عن صحة ما ذكروه، فلم يتمَهَّلوا بل هجموا على كنيسةٍ بجوار قناطر السباع، وكنيسة للأسرى في طريق مصر، ونهبوهما وأخذوا ما فيهما من الأخشاب والرخام وغير ذلك، ووقع النهبُ في دير بناحية بولاق الدكرور، وهَجَموا على كنائس مصر والقاهرة، وأخربوا كنيسةً بحارة الفهادين من الجوانية بالقاهرة، وتجمعوا لتخريب كنيسة بالبندقانيين من القاهرة، فركب والي القاهرة وما زال حتى ردَّهم عنها، وتمادى هذا الحالُ حتى عجَزَت الحكَّامُ عن كفهم، وكثُرَت الأخبار من الوجه القبلي والوجه البحري بدخولِ النصارى في الإسلامِ، ومُواظبتِهم المساجِدَ، وحِفظِهم للقرآن، حتى إنَّ منهم من ثبتت عدالتُه وجلس مع الشهودِ، فإنه لم يبقَ في جميع أعمال مصر كُلِّها قِبليِّها وبحريِّها كنيسةٌ حتى هُدِمت، وبُني مواضِعَ كثيرٍ منها مساجد، فلما عَظُم البلاء على النصارى، وقَلَّت أرزاقهم، رأوا أن يدخلوا في الإسلام، ففشا الإسلامُ في عامَّة نصارى أرض مصر، حتى إنه أسلم من مدينة قليوب خاصة في يوم واحد أربعمائة وخمسون نفرًا! وممَّن أسلم في هذه الحادثة الشمس المقسي، جدُّ بني المقسي الذي منهم التاج ناظر الخواصِّ، والهيصم جدُّ بني الهيصم الوزراء, وحمَلَ كثيرٌ من الناس فِعْلَهم هذا على أنه من جملةِ مَكْرِهم؛ لكثرةِ ما شنَّعَ العامة في أمرهم، فكانت هذه الواقعةُ أيضًا من حوادث مصر العظيمة، ومن حينئذ اختلطت الأنسابُ بأرض مصر، فنكح هؤلاء الذين أظهروا الإسلامَ بالأرياف المُسلِماتِ، واستولدوهنَّ، ثمَّ قَدِمَ أولادُهم إلى القاهرة، وصار منهم قضاةٌ وشهود وعلماء، ومَن عَرَف سيرتَهم في أنفُسِهم، وفيما وَلُوه من أمور المسلمين، تفطَّنَ لِما لا يمكِنُ التصريحُ به."},{"id":3058,"title":"إبطال عيد الشهيد بمصر .","date":["العام الهجري :755","الشهر القمري : رجب","العام الميلادي :1354"],"text":"بعد ما حدث بمصرَ مِن فتنة أهل الذمَّةِ وما جرى من إلزامِهم بالشروط العُمَريَّة وزيادةٍ، وما جرى من هدمٍ للكنائس المُحدَثة وغيرها، فلما كان في أُخرَيات رجب بلغ الأميرَ صرغتمش أنَّ بناحية شبرا الخيام كنيسةً فيها أصبع الشهيدِ التي ترمى كلَّ سنةٍ في النيل زعمًا منهم أنَّها تعمل على زيادةِ الخير والماء فيه، ويعملون في هذا اليوم عيدًا معروفًا بعيد الشهيد يحدُثُ فيه من المُنكرَات والفواحِش الكثير ممَّا يُستحيا مِن ذِكرِه، فتحدَّث مع السلطان فيه، فرسم بركوبِ الحاجِبِ والوالي إلى هذه الكنيسةِ وهَدْمِها، فهُدِمَت ونُهِبَت حواصِلُها، وأخِذَ الصندوق الذي فيه أصبعُ الشهيد، وأُحضِرَ إلى السلطان وهو بالميدان الكبير قد أقام به فأُضرِمَت النارُ، وأُحرِقَ الصندوق بما فيه، ثم ذرى رماده في البحر، وكان يومَ رُمِي هذا الأصبع في النيلِ مِن الأيام المشهودة؛ فإن النصارى كانوا يجتمعون من جميعِ الوجه البحري ومن القاهرة ومصر في ناحية شبرا، وتركَبُ الناس المراكِبَ في النيل، وتُنصَب الخيم التي يتجاوَزُ عَدَدُها الحَدَّ في البر، وتُنصَب الأسواق العظيمة، ويُباع من الخَمرِ ما يؤدُّون به ما عليهم من الخَراج، فيكونُ من المواسم القبيحة، وكان المظفَّرُ بيبرس قد أبطله أيام سَلطنَتِه، فأكذب اللهُ النصارى في قولِهم أنَّ النيل لا يزيدُ ما لم يُرمَ فيه أصبعُ الشهيد، وزاد تلك السنة حتى بلغ إلى أصبعٍ مِن ثمانية عشر ذراعًا، ثم سعت الأقباطُ حتى أعيدَ رَميُه في الأيام الناصرية، فأراح اللهُ منه بإحراقه، وأَخَذ عبَّاد الصليب في الإرجاف بأنَّ النيل لا يزيد في هذه السنة، فأظهر الله تعالى قُدرَتَه، وبيَّن للنَّاسِ كَذِبَهم، بأن زاد النيلُ زيادة لم يُعهَدْ مِثلُها قبل ذلك، فإنه انتهى في الزيادة إلى أصابع من عشرين ذراعًا، فقيل خمسة، وقيل سبعة، وقيل عشرون أصبعًا، من عشرين ذراعًا، ففسدت الأقصابُ والنيلة ونحوها من الزراعات، وفَسَدت الغلال التي بالمطامير والأجران والمخازن، وتقطَّعت الجسور التي بجميع النواحي؛ قبليِّها وبحريها، وتعطَّلت أكثَرُ الدواليب وتهَدَّمت دور كثيرة مما يجاوِرُ النيل والخلجان، وغَرِقَت البساتين، وفاض الماء حتى بلغ قنطرة قديدار، فكانت المراكِبُ تَصِلُ من بولاق إليها، ويركب الناسُ في المراكب من بولاق إلى شبرا ودمنهور."},{"id":3059,"title":"وفاة أمير غرناطة السلطان أبو الحجاج يوسف وتولي ابنه بعده .","date":["العام الهجري :755","الشهر القمري : شوال","العام الميلادي :1354"],"text":"توفي السلطانُ أبو الحجَّاج يوسف بن إسماعيل بن فرج من بني نصر؛ صاحِبُ غرناطة وما والاها، طُعِنَ بخنجَرٍ في جبينِه في يوم عيد الفطر، فمات منه، وتسَلْطَن بعده ابنُه أبو عبد الله محمد بن يوسف، وتلقَّبَ بالغني بالله."},{"id":3060,"title":"خلع السلطان الصالح صلاح الدين وإعادة السلطان الناصر حسن .","date":["العام الهجري :755","الشهر القمري : شوال","العام الميلادي :1354"],"text":"بعد أن اتَّفَق الأمراءُ بأن يكون الأمرُ كُلُّه للسلطان وأنَّه هو الذي يديرُ السَّلطنةَ بنَفسهِ مِن رأيه، استبَدَّ بالأمر وقَرَّبَ إليه الأمير طاز، وكان قد شُغِفَ بأخيه جنتمر كثيرًا، واستبعد الأميرَ شيخون كليًّا، بل زاد الأمرُ أنَّ السلطان قد اتفق مع إخوة طاز على أن يقبِضَ عليه وعلى صرغتمش يومَ العيد، وكان طاز قد توجَّه إلى البُحيرة في هذه الأيام للصيدِ، بعد ما قرر مع السلطان ما ذُكر، فركب السلطانُ في يوم الأحد أوَّلَ شوال لصلاة العيد في الإسطبل على العادةِ، وقَرَّر مع كلتاي وجنتمر وأصَرَّ على ما يفعلونَه، وأمَرَ بمائة فرس فشُدَّت وأوقِفَت، فلم يحضُرْ شيخو صلاةَ العيد، وكان قد بلغه جميعُ ما تقرر من نيَّة السلطان القبضَ عليه، فباتوا ليلة الاثنين على حَذَر، وأصبحوا وقد اجتمع مع الأميرِ شيخو من الأمراء صرغمتش وطقطاي، ومَن يلوذ بهم، وركبوا إلى تحت الطبلخاناه، ورسموا للآصر علم بضَرب الكوسات، فضُرِبت حربيًّا، فركب جميعُ العسكر تحت القلعة بالسلاحِ وصَعِدَ الأمير تنكربغا والأمير أسنبغا المحمودي إلى القلعة، وقبضا على السلطانِ الصالح صلاح الدين وسَجَناه مقيَّدًا، فزال ملكُه في أقل من ساعةٍ، وصَعِدَ الأمير شيخو ومن معه من الأمراء إلى القلعة، وأقامت أطلابُهم على حالها تحت القلعة، وقَبَضَ الأميرُ شيخو على إخوة الأمير طاز، واستشار فيمن يقيمُه للسلطنة، وصَرَّح هو ومن معه بخلع المَلِك الصالح صلاح الدين، فكانت مدة سلطنته ثلاث سنين وثلاثة أشهر وثلاثة أيام، فاقتضى رأي الأمير شيخو وسائر الأمراء إعادة السلطان الناصر حسن؛ لِما كان يبلغُهم عنه من ملازمتِه في مُدَّةِ حَبسِه للصلوات الخمس والإقبال على الاشتغالِ بالعِلم ِ،حتى إنَّه كتب بخَطِّه كِتابَ دلائل النبوة للبيهقي، فاستدَعَوا الخليفة وقُضاة القضاة، وأحضَروا السلطان من مَحبَسِه، وأركَبوه بشعار المملكة، ومشى الأمراء كلهم وسائر أرباب الدولة في رِكابِه، حتى جلَسَ على تخت الملك، وبايعه الخليفةُ، فقَبَّلوا له الأرضَ على العادة، وذلك في يوم الاثنين ثاني شهر شوال، وبات الأمراءُ في الأشرفية من القلعة، وسُجِنَ المَلِكُ الصَّالِحُ صلاح الدين حيث كان أخوه الملك الناصر حسن مَسجونًا!!"},{"id":3061,"title":"طلب البيزنطيين من العثمانيين المساعدة .","date":["العام الهجري :756","العام الميلادي :1355"],"text":"طلَب إمبراطورُ بيزنطة يوحنا الخامِسُ من الغازي أورخان بن عُثمانَ مُساعَدتَه ضِدَّ إمبراطور الصرب: اصطفان دوشان، الملقب بالقوي، الذي تحالف مع البندقيَّة والإمارات الصربية للهُجومِ على القسطنطينية، ووعد بأن يزوِّجَه ابنة الوصي على العرش يوحنا كانتا كوزين التي تزوج هو أختها الأخرى، لِيُصبِحا عَديلينِ، وأرسل له أورخان الجندَ، غير أن اصطفان دوشان قد أدركه الموتُ وتوقَّف الاستعدادُ، وعاد الجنود العثمانيون إلى بلادِهم دون قتال، وتزوج أورخان ابنة الوصي، وكانت هذه الحادثة قد أشعرت أورخان بضَعفِ الدولة البيزنطيَّة."},{"id":3062,"title":"وفاة الطبيب الرئيس جمال الدين ابن المغربي طبيب السلطان الناصر .","date":["العام الهجري :756","العام الميلادي :1355"],"text":"هو الطبيبُ الرئيسُ الحكيمُ جمال الدين أبو إسحاق إبراهيمُ بن شهاب الدين أحمد، المعروف بابن المغربي: رئيس الأطباء بالديار المصرية والممالك الشامية، ذو الرُّتبة المنيعة والمكانة العالية والوَجاهة في الدولة والحُرمة عند الناس، خصوصًا في أيام الملك الناصر محمد بن قلاوون؛ لِقُربه من السلطان وخِدمة أكابر الأمراء والوزراء في مواطِنَ كثيرة سرًّا وجهرًا، وكان ممن خرج صحبة الركاب الناصري سنة 708 وأقام معه بالكرك، وتردد في الدخولِ إليه مع من كان يدخُلُ إليه من ذوي الخِدَم، ثمَّ تفَرَّد بذلك مع الخاصكية، فصارت له بهذا خصوصيَّة ليست لأحَدٍ، وكان السلطانُ يَعرِفُ له حَقَّ ذلك ويرعاه ويطمَئِنُّ إليه ويعَوِّلُ دون كلِّ أحد عليه، وكان أبوه شهاب الدين أوحَدَ أهل زمانه في الطبِّ وأنواع الفضائل، وقرأ جمال الدين على مشايخ الأطباءِ وأخذ عن أبيه الطبَّ والنجامة إلى غير ذلك، وكان أبوه كثير السرورِ به والرضا عنه، وكان قد فَرَّق أبوه مالًا على بنيه ثم تركهم مُدَّةً وطلب منهم المالَ، فأحضر إليه جمالُ الدين المالَ وقد نَمَّاه وثَمَّرَه ولم يُحضِرْ غَيرُه المال لتفريطٍ حصل فيه، فازداد جمال الدين مكانة من خاطره، ورَدَّ عليه المالَ ومِثلَه معه، وكان إذا رآه قال: هذا إبراهيم سعيد، وكان الأمرُ على ما ذكَرَه وصَدَقَت فِراسَتُه, فخدم السلطانَ في حياة أبيه، وتقَدَّم لديه وباشَرَ المارستان وفُوِّضَت إليه الرياسةُ مُطلقًا، ثم أخذ في الترقي إلى أن عُدَّ من أعيان الدولة وأكابر أرباب المراتِبِ، والتحق بدرجةِ الوُزَراء وذوي التصَرُّف، بل زاد عليهم لإقبالِ السلطان عليه وقُربِه منه، وكان أول داخل إليه يدخُلُ كُلَّ يوم قبل كل ذي وظيفةٍ برانية من أرباب السيوفِ والأقلامِ، فيسأل جمال الدين السلطان عن أحوالِه وأحوالِ مَبيتِه وأعراضِه في ليلتِه، فيُحَدِّثُه في ذلك، ثمَّ أمور بقيَّة المرضى من أهل السُّلطان والأمراء ومماليك السلطان وأرباب وظائِفِ وسائر الناس، ويسأله السلطان عن أحوال البلد ومَن فيه من القضاة والمحتَسِب ووالي البلد، وعَمَّا يقوله العوامُّ ويستفيضُ فيه الرعيَّة، ومن لعَلَّه وقع في تلك الليلة بخِدمةٍ أو أمسك بجزيرة، أو أخذ بحَقٍّ أو ظلم؛ ولهذا كان يُخشى ويُرجى وتُقبَلُ شفاعاتُه وتُقضى حاجاتُه، وكان يجِدُ سبيله إذا أراد لغيبةِ أرباب الوظائفِ السلطانيَّة، ولا يجدون سبيلًا لهم عليه؛ إذ تناط بهم أمورٌ مِن تصَرُّفٍ في مالٍ أو عَزلٍ وولايةٍ يقال في ذلك بسَبَبِهم ولا يناطُ به شَيءٌ مِن ذلك يقالُ فيه بسَبَبِه؛ فلهذا طال مكثُه ودامت سعادتُه ولم يغَيِّرْ عليه مُغَيِّرٌ ولا استحال عليه السلطانُ، وحصَّل النِّعَم العظيمةَ والأموال الوافرة والسعادة المتكاثرة؛ قال القاضي شهاب الدين أحمد بن فضل الله: \" لقد حرص النشو على رميِه مِن عَينِ السلطان بكلِّ طريقٍ فلم يقدِرْ، حتى إنه عمل أوراقًا بما على الخاصِّ مِن المتأخِّراتِ مِن زمانِ مَن تقَدَّمَه وذكر فيها جملةً كثيرة ثمَن صِنفٍ أظنُّه رصاصًا بِيعَ مِن جمال الدين، ثم قرأ الأوراقَ على السلطان ليُعلِمَه أنَّ له أموالًا واسعةً يتكَسَّبُ فيها ويتاجِرُ على السلطان، وهو يعيد ذِكرَ جمال الدين مراتٍ ويَرفَع صَوتَه ثمَّ يَسكُت ليفتَحَ السلطانُ معه بابًا فيه، فيقول: فماذا يريد؟ فما زاد السلطانُ على أن قال: هذا لا تؤخِّرْه، روح الساعةَ أعطِه مالَه، ولا تؤخِّرْ له شيئًا\" فقد كان السلطانُ عارفًا بما لجمال الدين من المنافِعِ مِمَّا يحصل له من الخِلَع الكوامل والبِغال المُسرَجة المُلجَمة والتعابي والقماش والإنعامات من الآدر السلطانية والأمراء, وكان الطبيبُ الرئيس يلازم الخدمةَ سفرًا وحَضَرًا ويتجَمَّلُ في ملبوسِه ومركوبِه وحَشَمِه وداره وجواريه وخَدَمِه مِن غير إسرافٍ ولا تكثُّر، وكان السلطان لا يقول له إلَّا يا إبراهيمُ، وربما قال: يا حكيم إبراهيم، ولقد قال مرة: إبراهيم صاحبنا- يعني جمال الدين- وكان غايةً منه في قُربِ المحَلِّ والأمنِ إليه! وله مع هذا خصوصية ببكتمر الساقي أنَّه إلى جانب السلطان أميَلُ، وعلى رضاه أحَلُّ، وجمال الدين على إفراطِ هذا العلو وقُرْبِ هذا الدنو لا يتكبَّرُ ولا يرى نفسَه إلا مثل بعضِ الأطباء توقرًا لجماعة رُفقَتِه كُلِّهم ويجلُّ أقدار ذوي السنِّ منهم وأهل الفضل ويخاطِبُهم بالأدب، ويحَدِّثُهم بالحسنى ويأخذُ بقلب الكبير منهم والصغير والمُسلِم والذمِّي، وكان يكره صلاح الدين بن البرهان ويُكرِمُه، ويبغض ابن الأكفاني ويعَظِّمُه ويحفظُ بكُلِّ طَريقٍ لِسانَه، ويتقصد ذِكرَ المحاسِنِ والتعامي من المعائب، وله الفضيلة الوافرة في الطب علمًا وعملًا، والخَوض في الحُكميات والمشاركة في الهيئة والنجامة، كل هذا إلى حُسنِ العقل المعيشي ومصاحبة الناس على الجميل، وكان لا يعود مريضًا إلَّا من ذوي السلطانِ، ولا يأتيه في الغالب إلَّا مَرَّةً واحدة، ثمَّ يقَرِّرُ عنده طبيبًا يكون يعوده ويأتيه بأخباره، ثم إذا برأ ذلك المريض استوجب عليه جمال الدين ما يستوجِبُه مِثلُه، فإذا خلع عليه أو أنعم عليه بشيءٍ دخل إلى السلطانِ وقَبَّل الأرض لديه فيُحيطُ عِلمًا بما وصل إليه, ولما أُثقِلَ السلطان في المرض نوبةَ موته، كان جمال الدين مريضًا ولم يَحضُرْه, وقيل: إنما تمارض بعد أمْنِ التُّهَم, وتوفِّيَ الرئيس جمال الدين هذا العامَ."},{"id":3063,"title":"وفاة تقي الدين السبكي الشافعي\n(الأب) .","date":["العام الهجري :756","الشهر القمري : جمادى الآخرة","العام الميلادي :1355"],"text":"هو تقيُّ الدين أبو الحسن علي بن زين الدين عبد الكافي بن علي بن تمام بن يوسف بن موسى بن تمام بن حامد بن يحيى بن عمر بن عثمان بن علي بن سوار بن سليم الأنصاري السبكي الشافعي، توفِّيَ بشاطئ النيل في ليلة الاثنين رابع جمادى الآخرة؛ ومولِدُه في شهر صفر سنة 683 بسبك الثلاث، وهي قرية بالمنوفية من أعمال الديار المصريَّة بالوجه البحري، كان إمامًا عالِمًا بالفقه والأصلينِ، والحديث والتفسير، والنحو والأدب، ولِيَ الإفتاء والقضاء بالقاهرة ثم انتقل إلى دمشق، فلما اعتَلَّ عاد إلى القاهرة، وهو والد تاج الدين السبكي, وله من المصنَّفات مختصر طبقات الفقهاء، ومجموع فتاوى، والابتهاج شرح المنهاج، ورفع الشقاق في مسألة الطلاق، وقد تناظر فيها كثيرًا مع ابن القيم، وكان بينهم بسبب ذلك مناظرات، وله كشف الغمة في ميراث أهل الذمة، وله كشف الدسائس في هدم الكنائس، وغيرها."},{"id":3064,"title":"وفاة حسن الجلائري مؤسس الدولة الجلائرية المغولي بالعراق .","date":["العام الهجري :757","العام الميلادي :1356"],"text":"هو تاجُ الدين الشيخُ حسن بزرك بن حسين بن أقبغا بن أيلكان التتري، سِبطُ أرغون بن أبغا بن هولاكو بن طولون بن جنكيزخان ملك التتار صاحب \" الياسق \" والأحكام التركية، وهو والِدُ أويس، وكان يقال له حسن الكبير؛ تمييزًا له عن حسن بن تمرتاش, وهو أوَّلُ حُكَّام آل جلائر, كان حَسَنٌ الكبير زوجَ خاتون بغداد بنت الجوبان، فلم يزل بوسعيد إلى أن طلقها وأخذها منه قهرًا وأبعده، فلما مات بوسعيد عاد فمَلَك بغداد وأقام بها وجرت له مع التتارِ حروبٌ كثيرة ومع أولاد تمرتاش النصر فيها, ووقع في ولايته على بغداد الغلاءُ المفرط حتى بيع الخبزُ بصنج الدراهم، ونزح الناس عن بغداد، وقام هو بالمُلكِ أحسَنَ قيامٍ، ونشر العدل إلى أن تراجعَ الناس إليها، ولما كان في سنة 749 توجَّهَ إلى تُستَر ليأخُذَ من أهلها قطيعةً قَرَّرها عليهم فأخذها وعاد فوجد نوَّابه في بغداد قد وجدوا في رواق الغزر ببغداد ثلاثة قدورٍ مثل قدور الهريسة طول كل جبٍّ منها نحو ذراعين ونصف، والثلاثة مملوءة ذهبًا مِصريًّا وصوريا ويوسيفا وفي بعض سكة الناصر البغدادي، فيقال: جاء وزن ذلك أربعين قنطارًا بالبغدادي، ومات الشيخ حسن في سنة 757 وكان سياسيًّا وحكيمًا، فلم يُعلِنْ نَفسَه سلطانًا في العراق بل أعلن ولاءه لسلطان المماليك في مصر؛ لِيَضمَنَ حمايتَهم له من أي عدوان قد يتعرض له من المغول المجاورين لدولته من جهة الشرق، وكانت مدته سبع عشرة سنة، ثم قام بالأمر بعده ابنُه أويس بهادر خان خلفًا له."},{"id":3065,"title":"هجوم الفرنج على شواطئ صفد .","date":["العام الهجري :757","الشهر القمري : جمادى الأولى","العام الميلادي :1356"],"text":"في السابِعِ والعشرين من جمادى الأولى ورَدَ الخبَرُ إلى دمشق بأن الفرنجَ استحوذوا على مدينة صفد، قدموا إليها في سبعة مراكب وقتلوا طائفةً مِن أهلها ونهبوا شيئًا كثيرًا وأسَرُوا أيضًا، وهجموا على الناس وقت الفجرِ يوم الجمعة، وقد قَتَل منهم المسلمون خلقًا كثيرًا وكَسَروا مركبًا من مراكبهم، وجاء الفرنجُ في عشية السبت قبل العصر، وقَدِمَ الوالي وهو جريحٌ مُثقَلٌ، وأمر نائِبَ السلطنة عند ذلك بتجهيز الجيش إلى تلك الناحية، فساروا تلك الليلة ولله الحمد، وتقَدَّمهم حاجب الحجاب وتحدَّر إليه نائب صفد الأمير شهاب الدين بن صبح، فسبق الجيشُ الدمشقيُّ، ووجد الفرنجَ قد برزوا بما غَنِموا من الأمتعة والأسارى إلى جزيرةٍ تِلقاءَ صيدا في البحر، وقد أسر المسلمونَ منهم في المعركة شيخًا وشابًّا من أبناء أشرافهم، وهو الذي عاقهم عن الذَّهاب، فراسلهم الجيشُ في انفكاك الأُسارى من أيديهم، فبادرهم عن كلِّ رأس بخمسمائة فأخذوا من ديوان الأسارى مبلغ ثلاثين ألفًا، ولم يبقَ معهم- ولله الحمد- أحَدٌ، واستمر الصبيُّ من الفرنج مع المسلمين، وأسلم ودفَعَ إليهم شيخ الجريح، وعطش الفرنج عطشًا شديدًا، وأرادوا أن يرووا من نهر هناك فبادرهم الجيش إليه، فمنعوهم أن ينالوا منه قطرة واحدةً، فرحلوا ليلة الثلاثاء منشمرينَ بما معهم من الغنائم، وبُعِثَت رؤوس جماعة من الفرنج ممَّن قتِلَ في المعركة فنُصِبَت على القلعة بدمشق، وجاء الخبَرُ في هذا الوقت بأن إيناس قد أحاط بها الفرنج، وقد أخذوا الربيضَ وهم محاصِرونَ القلعة، وفيها نائب البلد، وذكروا أنهم قتلوا خلقًا كثيرًا من أهلها وذهب صاحِبُ حلب في جيشٍ كثيف نحوَهم، وفي يوم السبت رابع جمادى الآخرة قَدمَ رؤوس من قتلى الفرنج على صيدا، وهي بضعٌ وثلاثون رأسًا، فنُصِبَت على شرافات القلعة، ففرح المسلمون بذلك، ولله الحمد."},{"id":3066,"title":"حريق هائل في بلاد كسروان وطرابلس .","date":["العام الهجري :757","الشهر القمري : ذي القعدة","العام الميلادي :1356"],"text":"جرى في بلاد سواحِلِ الشام حريقٌ مِن بلاد طرابلس إلى آخِرِ معاملة بيروت إلى جميع كسروان، أحرق الجبالَ كُلَّها ومات الوحوش كلُّها، مثل النمور والدب والثعلب والخنزير من الحريق، ما بقي للوحوشِ مَوضِعٌ يهربون فيها، وبقي الحريقُ عليه أيامًا، وهرب الناس إلى جانب البحر خوفًا من النار، واحترق زيتون كثير، فلما نزل المطرُ أطفأه بإذن الله تعالى، ومن العجب أن ورقة من شجرةٍ وقعت في بيتٍ مِن مدخنته، فأحرقت جميع ما فيه من الأثاث والثياب وغير ذلك، ومن حلية حرير كثير، وغالب هذه البلاد للدروز والرَّافضة."},{"id":3067,"title":"العثمانيون يعبرون مضيق الدردنيل .","date":["العام الهجري :758","العام الميلادي :1356"],"text":"لما طلب البيزنطيون المساعدةَ من العثمانيين ضِدَّ الصرب، أدرك بذلك العثمانيون ضَعفَ البيزنطيين، فرأى أورخان سلطانُ العثمانيين أن ينتَقِلَ إلى الضفة الغربية من مضيقِ الدردنيل ليتقَدَّمَ بعدها إلى أوروبا فيتمَكَّنَ من الإحاطة بالقسطنطينية والهجومِ عليها من الغرب؛ حيث عجز المسلمون عن فتحها من الشرقِ، فأرسل ابنه الكبير سليمان لدراسة هذه الخطة، وفي هذا العام اجتاز سليمانُ مضيق الدردنيل ليلًا مع أربعين رجلًا من أبطالِه، ولما وصلوا إلى الضفة الغربية استولوا على الزوارق الروميَّة الراسية هناك وعادوا بها إلى الضفة الشرقيَّة؛ إذ لم يكن للعثمانيين أسطول، ثم انتقلوا إلى الشاطئِ الأوربيِّ فاحتلوا قلعة تزنب وغاليبولي التي فيها قلعة جنا- القلعة المشهورة- وأبسالا ورودستو، وهذه كلها تقع على مضيق الدردنيل من الجنوب إلى الشمال حتى تصبح رودستو على بحر مرمرة."},{"id":3068,"title":"استيلاء بني مرين على تونس والجزائر .","date":["العام الهجري :758","العام الميلادي :1356"],"text":"استولى أبو عنان فارس سلطان بني مرين على الجزائر، ثم استولى على قسنطينة وعنابة وتونس، واستسلم له السلطان الحفصي أبو العباس أحمد المتوكل، مريدًا بذلك توحيد إفريقيا الشمالية، ولكنَّ قبائل الأعراب ثارت على أبي عنان لِمَنعه عنهم بعض الأداءاتِ الموظَّفة لهم على عادة الأعراب، وعجَزَ الجيش المريني عن مطاردة الأعرابِ وإخماد عصيانهم، وعاد أبو عنان إلى فاس ومعه جيشُه."},{"id":3069,"title":"اغتيال سلطان بني مرين أبي عنان وتغلب أخيه على الملك .","date":["العام الهجري :759","العام الميلادي :1357"],"text":"هو السُّلطانُ أبو عنان فارس بن أبي الحسن علي: حاكِمُ دولة بني مرين في أفريقية، اغتاله وزيرُه الحسن بن عمر الفودوي، ثم تولى بعدَه ابنُه أبو بكر محمد السعيد خلفًا لأبيه وله من العمر فقط خمس سنوات، وكان أبو سالم إبراهيم أخو أبي عنان منفيًّا في الأندلس عند بني الأحمر، فلما علم بما حصل لأخيه طلب من سلطانِ بني الأحمر مساندَتَه، فلم يجِبْه، فطلب من مَلِك قشتالة الأسباني فأنجده بأسطولٍ اجتاز به البحر إلى المغرب، وتمكَّنَ بمن تبعه من أنصاره من الاستيلاءِ على المُلْك، وخَلَعَ ابن أخيه محمد السعيد ونفاه إلى الأندلس التي لم يصِلْ إليها، بل غَرِقَ في البحر في الطريقِ."},{"id":3070,"title":"اغتيال أمير المدينة مانع بن علي الحسيني .","date":["العام الهجري :759","الشهر القمري : ذي الحجة","العام الميلادي :1358"],"text":"هو الشَّريفُ مانعُ بن علي بن مسعود بن جماز بن شيحة الحسيني: صاحِبُ المدينة النبويَّة، وقد ذُكِرَت عنه أمورٌ شنيعة بَشِعةٌ مِن غُلُوِّه في الرَّفضِ المُفرِط، ومن قَولِه: إنه لو تمكن أخرج الشيخين من الحُجرة! وغير ذلك من عبارات مؤدية لعدم إيمانِه إن صح عنه، والله أعلم، وفي السابع والعشرين من ذي الحجَّة عدا عليه فداويان عند لُبسِه خِلعةَ السلطان، وقت دخول المَحمَل إلى المدينة الشريفة، فقتلاه، فعَدَت عبيدُه على الحجيج الذين هم داخِلَ المدينة فنهبوا من أموالِهم وقَتَلوا بعضَهم وخرجوا، وكانوا قد أغلقوا أبوابَ المدينة دون الجيشِ فأُحرِقَ بعضُها، ودخل الجيشُ السلطاني فأنقذوا النَّاسَ من أيدي الظالمين، ودخل المَحمَل السلطانيُّ إلى دمشق يوم السبت العشرين من شهر محرَّم على عادته إلى دمشق، وبين يدي المَحمَل الفداويان اللذان قَتَلا صاحب المدينة، ويُذكَرُ أنَّه تولى المدينةَ الشَّريفةَ بعده ابنُ عَمِّه فضل بن القاسم."},{"id":3071,"title":"عزل الشريف عجلان عن إمرة مكة .","date":["العام الهجري :760","العام الميلادي :1358"],"text":"كان الشَّريفُ عجلان قد قَدِمَ مِن مكَّةَ لمِصرَ، فعزله السلطان عن إمارتها، وولَّى عِوَضَه الشريفان محمد بن عطفة وسند بن رميثة، وقواهما بالأمير جركتمر الحاجب والأمير قطلوبغا المنصوري، وناصر الدين أحمد بن أصلم؛ ليقيموا بمكة حتى يأتيهم البَدَلُ مِن مِصرَ."},{"id":3072,"title":"إخماد الثورات ضد إمبراطورية المغول  .","date":["العام الهجري :760","العام الميلادي :1358"],"text":"بعد أن توفِّيَ سلطان المغول بردي بك خان سنة 759 وقع الاختلالُ في دولة التتار ببلاد الشمال وكَثُرَ الهَرجُ والمرج، وكان ابنُه محمد بردي قد تسَلَّم السَّلطنةَ بعد أبيه الذي استطاع بجبروتِه وقوَّتِه أن يُخمِدَ هذه الثورات وأن يسيطِرَ أيضًا على حُكَّام الروس في موسكو وغيرها، كما قام توقتاميش أيضًا بمثل هذا الإخضاعِ."},{"id":3073,"title":"فتنة الأعراب بحوران .","date":["العام الهجري :760","الشهر القمري : رجب","العام الميلادي :1359"],"text":"كانت قريةٌ بحوران- وهي خاص لنائب الشام وهم حلبية يمن، ويقال لهم بنو لبسة وبنو ناشي- وهي حصينة منيعة يضوي إليها كلُّ مُفسدٍ وقاطع ومارق، ولجأ إليهم أحَدُ شياطين رويمن العشير، وهو عمر المعروف بالدنيط، فأعدوا عددًا كثيرة ونهبوا ليغنَموا العشير، وفي هذا الحين بدَرَهم والي الولاة المعروف بشنكل منكل، فجاء إليهم ليرُدَّهم ويهديهم، وطلب الوالي منهم تسليمَ عمر الدنيط، فأبوا عليه وراموا مقاتلَتَه، وهم جمع كثير وجَمٌّ غفير، فتأخَّرَ عنهم وكتب إلى نائب السلطنة ليمُدَّه بجيشٍ عونًا له عليهم وعلى أمثالهم، فجهَّزَ له جماعة من أمراء الطبلخانات والعشراوات ومائة من جند الحلقة الرماة، فلمَّا بغَتَهم في بلدهم تجمَّعوا لقتال العسكر ورموه بالحجارة والمقاليع، وحَجَزوا بينهم وبين البلد، فعند ذلك رمَتْهم الأتراك بالنبال من كل جانب، فقتلوا منهم فوق المائة، فَفَرُّوا على أعقابهم، وأَسَر منهم والي الولاة نحوًا من ستين رجلًا، وأمر بقطع رؤوس القتلى وتعليقها في أعناق هؤلاء الأَسرى، ونُهِبَت بيوت الفلَّاحين كلهم، وسُلِّمَت إلى مماليك نائب السلطنة، لم يفقَدْ منها ما يساوي ثلاثمائة درهم، وكرَّ راجِعًا إلى بصرى وشيوخ العشيرات معه، فأخبر ابن الأمير صلاح الدين ابن خاص ترك، وكان من جملةِ أمراء الطبلخانات الذين قاتلوهم بمبسوط ما يخصُّه، وأنه كان إذا أعيا بعض تلك الأسرى من الجرحى أمر المشاعلي بذبحِه وتعليق رأسِه على بقية الأسرى، وفعل هذا بهم غيرَ مَرَّة حتى إنه قطع رأس شاب منهم وعَلَّقَ رأسه على أبيه، شيخٍ كبير، حتى قَدِمَ بهم بصرى، فشنكل طائفة من أولئك المأسورين، وشنكل آخرين، وقتل الآخرين وحبس بعضهم في القلعة، وعلَّق الرؤوسَ على أخشابٍ نَصَبها حول قلعة بصرى، فحصل بذلك تنكيلٌ شديد لم يقع مثلُه في هذا الأوان بأهل حوران، وهذا كلُّه سُلِّطَ عليهم بما كسَبَت أيديهم، وما ربُّك بظَلَّامٍ للعبيدِ!"},{"id":3074,"title":"مطر عظيم بمصر بعد جفاف .","date":["العام الهجري :761","العام الميلادي :1359"],"text":"وقعَ مَطَرٌ عظيمٌ في أوَّلِ هذا الشَّهرِ بمصر، وهو شهرُ فبراير، وثلجٌ عظيمٌ، فرَوِيَت البساتينُ التي كانت لها عن الماءِ عِدَّةُ شهور، ولا يحصلُ لأحدٍ مِن الناس سَقيٌ إلا بكلفة عظيمة ومشقَّة، ومبلغ كثير، حتى كاد الناسُ يقتتلون عليه بالأيدي والدبابيس وغير ذلك من البَذلِ الكثير، وذلك في شهورِ ديسمبر والثاني، وأول فبراير؛ وذلك لقِلَّةِ مياه الأنهار وضَعفِها، وكذلك بلادُ حوران أكثَرُهم يروون من أماكنَ بعيدة في هذه الشهور، ثمَّ مَنَّ الله تعالى فجَرَت الأوديةُ وكَثُرت الأمطارُ والثلوج، وغَزُرت الأنهار, وتوالت الأمطارُ، فكأنه حصل السيلُ في هذه السَّنةِ مِن كانون إلى فبراير."},{"id":3075,"title":"وفاة أورخان بن عثمان ثاني سلطان العثمانيين وتولي ابنه مراد الأول .","date":["العام الهجري :761","العام الميلادي :1359"],"text":"هو الغازي بك شُجاعُ الدين والدنيا السلطانُ أورخان خان بن عثمان بن أرطغرل بن سليمان ثاني سلاطين بني عثمان، وُلِدَ في مدينة سُكود عاصمة إمارة والده سنة 687 هـ الموافق (1281م) ولِيَ سنة 726 بعد وفاةِ والده السلطان عثمان أوَّلِ ملوك بني عثمان، وكانت ولايةُ أورخان في أيام السلطان حسن بن محمد بن قلاوون صاحِبِ مصر، كان أورخان شديدًا على الكفَّارِ ففاق والِدَه في الجهاد، وفتح البلاد فافتتح قلاعًا كثيرة وحصونًا منيعة، وفتح بروسة –بورصة- وجعلها مقَرَّ سَلطَنَتِه, شهد عهدُه توسُّعَ الإمارة العثمانيَّة، وضَمَّ جميع أراضي الدولة البيزنطيَّة في آسيا الصُغرى لحُكمِه, وأُنشئ في عهده جيشُ الإنكشارية الذي كانت نواتُه أبناء الأَسْرى, توفِّيَ أورخان عن عمر 81 سنة ودُفِنَ في مدينة بورصة في تربة والده عثمان، وامتَدَّ حُكمُه خمسًا وثلاثين سنة, وكان أولًا في ولاية عهده ابنُه سليمان، ولكنه توفي عام 760 في غاليبولي ودُفِنَ فيها، وقد حزن عليه والده حزنًا شديدًا، ثم أصبح في ولاية العهد ابنُه مراد الأول الذي ولد عام 726 فلما توفي أورخان تولى هو من بَعدِه، وكان له من العمر ستًّا وثلاثين سنة."},{"id":3076,"title":"فتح مراد الأول مدينة أنقرة .","date":["العام الهجري :761","العام الميلادي :1359"],"text":"بعد وفاة أورخان وتولِّي ابنِه مراد الأول أراد أميرُ القرمان في أنقرة علاءُ الدين خليل بن محمود أن يستَغِلَّ هذه الفرصة ظنًّا منه أنَّه يقضي على العثمانيِّينَ فاستنهضَ هِمَمَ الأمراء المستقِلِّينَ في آسيا الصغرى للقتال، وعَمِلَ على تجميعهم، غيرَ أنَّه تفاجأ بجيش مراد الأول الحاكِمِ الجديدِ، وهي محيطةٌ بمدينة أنقرة، ودخلها فاتحًا، فاضطر علاءُ الدين لِعَقدِ الصلح معه وتنازل عن أنقرة، واعترف السلطانُ مراد بالأميرِ علاء الدين أميرًا على بقية أملاك دولةِ القرمان، وتزوَّجَ مراد من ابنةِ علاء الدين."},{"id":3077,"title":"وفاة الحافظ الفقيه صلاح الدين العلائي .","date":["العام الهجري :761","الشهر القمري : محرم","العام الميلادي :1359"],"text":"هو الحافِظُ الفقيه أبو سعيد صلاح الدين العلائي خليل بن كيكلدي الدمشقي سِبطُ البرهان الذهبي الحافظ. مولِدُه سنة 694، حَفِظَ القرآن والسنة والنحو وغير ذلك، وسَمِعَ الكثير، وهو معدود في الأذكياء، ودَرَّس وأفتى وناظر، وكان مدَّة مقامه مدرسًا بالمدرسة الصلاحية بالقدس وشيخًا بدار الحديث السكرية ثلاثين سنة، وقد صَنَّف وألف وجمع وخَرَّج، وكانت له يدٌ طولى بمعرفة العالي والنازل، وتخريج الأجزاء والفوائد، وله مشاركةٌ قوية في الفقه واللغة والعربية والأدب، وله عدة مصنفات وقَفَها على الخانقاه السمساطية بدمشق، ومن مصنفاته: جامع التحصيل في أحكام المراسيل، وتحقيق منيف الرتبة لمن ثبت له شريف الصحبة، والنقد الصحيح لما اعترض عليه من أحاديث المصابيح، والتنبيهات المجملة على المواضع المشكلة، وتلقيح المفهوم في تنقيح صيغ العموم، وتحقيق المراد في أن النهي يقتضي الفساد، وجزء في تصحيح حديث القلتين والكلام على أسانيده، وإجمال الإصابة في أقوال الصحابة، وغيرها. توفي بالقدس الشريف ليلة الاثنين ثالث المحرم، وصلِّيَ عليه من الغدِ بالمسجد الأقصى بعد صلاة الظهر، ودُفِن بمقبرة نائب الرحبة، وله من العُمرِ ست وستون سنة."},{"id":3078,"title":"غزو بلاد سيس .","date":["العام الهجري :761","الشهر القمري : جمادى الآخرة","العام الميلادي :1360"],"text":"في مُستَهَلِّ جمادى الآخرة رَكِبَ الأميرُ سَيفُ الدين بيدمر نائب حلب لقصد غزو بلاد سيس في جيش، وفي يوم الاثنين سابع عشر جاء الأمير تاج الدين جبريل مِن عند الأميرِ سيف الدين بيدمر نائب حلب، وقد فتحَ بلدين من بلاد سيس، وهما طرسوس وأذنة، وأرسل مفاتيحَهما صحبة الأمير تاج الدين جبريل إلى السلطان، ثم افتتح حصونًا أخرى كثيرةً في أسرع مدة، وأيسَرِ كُلفة، وخطب القاضي ناصرُ الدين كاتِبُ السر خطبةً بليغة حسنة، وقد حُمِلَت أبواب كنيسة أذنة إلى الديار المصريَّة في المراكِبِ، وهذه هي أبوابُ الناصريَّة التي بالسَّفحِ، كان قد أخذها سيس عام قازان، وذلك في سنة 699، فاستنقذت في هذه السنةِ."},{"id":3079,"title":"عصيان خيار بن مهنا أمير العرب بين العراق وسوريا وقتاله .","date":["العام الهجري :761","الشهر القمري : شعبان","العام الميلادي :1360"],"text":"وصل تقليدُ الأمير سيف الدين بيدمر بنيابة دمشق، ورُسِمَ له أن يركَبَ في طائفةٍ مِن جيش حَلَب ويقصد الأميرَ خيار بن مهنا ليُحضِرَه إلى خدمة السلطان، وكذلك رُسِمَ لنائب حماة وحمص أن يكونا عونًا للأمير سيف الدين بيدمر في ذلك، فلمَّا كان يومُ الجمعة رابِعَ هذا الشهر التَقَوا مع خيار عند سلمية، فكانت بينهم مناوشات، فأحاط الأعرابُ بسيف الدين بيدمر ومَن معه من الترك من كل جانبٍ؛ وذلك لكثرة العرب وكانوا نحو الثمانمائة، وكانت التركُ مِن حماة وحمص وحلب مائةً وخمسين، فرَمَوا الأعراب بالنشَّاب فقتلوا منهم طائفةً كثيرةً، ولم يُقتَلْ من الترك سوى رجلٍ واحد، رماه بعضُ الترك ظانًّا أنه من العرب بناشجٍ فقَتَله، ثم حجز بينهم الليل، وخرجت التركُ مِن الدائرة، ونُهِبَت أموالٌ من الترك ومِن العَرَب، وجرت فتنةٌ وجُرِّدَت أمراء عدة مِن دمشق لتدارُكِ الحال، وأقام نائِبُ السلطنة هناك ينتَظِرُ ورودهم، وقَدِمَ الأمير عمر الملقب بمصمع بن موسى بن مهنا من الديار المصرية أميرًا على الأعراب وفي صُحبَتِه الأمير بدر الدين بن جماز أميرانِ على الأعراب، فنزل مصمع بالقَصرِ الأبلق، ونزل الأميرُ رملة بالتوزية على عادته ثم توجَّها إلى ناحية خيار بن مهنا بمن معهما من عرب الطاعةِ مِمَّن أضيف إليهم من تجريدة دمشق ومَن يكون معهم من جيش حماة وحمص؛ لتحصيل الأمير خيار، وإحضاره إلى الخدمة الشريفةِ."},{"id":3080,"title":"وفاة ابن هشام الأنصاري النحوي .","date":["العام الهجري :761","الشهر القمري : ذي القعدة","العام الميلادي :1360"],"text":"هو جمالُ الدين أبو محمَّدٍ عبدُ اللهِ بنُ يوسُفَ بنِ أحمد بن هشام الأنصاري الحنبلي النحويُّ. وُلِدَ وتوفِّيَ بمصر, كان بارعًا في عدة علوم، لا سيما العربية؛ فإنه كان فارِسَها ومالِكَ زِمامِها، وعُدَّ مِن كبار أئمَّةِ النحو، وله فيه الأبحاث العجيبة، والنكات الغريبة، والأنظار الدقيقة، حتى قيل عنه: أنحى مِن سيبويه, وهو صاحِبُ الشَّرحِ على ألفية ابن مالك في النحو، المسمى أوضح المسالك إلى ألفية ابن مالك، وشرح أيضًا البردة، وشرح بانت سعاد، وكتاب المغني، وله شذور الذهب في معرفة كلام العرب، وله قَطْر الندى وبَلُّ الصَّدى، والإعراب وقواعد الإعراب، وغير ذلك، وكان أولًا حنفيًّا ثم استقَرَّ حنبليًّا وتنَزَّل في دروس الحنابلة. توفِّيَ في ليلة الخامس من ذي القعدة، ومات عن بضعٍ وخمسين سنة، ودفن بعد صلاة الجمعة بمقابر الصوفيَّة خارج باب النصر من القاهرة."},{"id":3081,"title":"فتح مراد الأول مدينة أدرنة الأوروبية وجعلها عاصمة الدولة العثمانية .","date":["العام الهجري :762","العام الميلادي :1360"],"text":"فتح العُثمانيون في هذه السنة مدينةَ أدرنة بعد أن حاصَروها، فسَلَّمَها القائِدُ الرومي بعد أن يَئِسَ من المقاومةِ، فنقل مراد الأوَّلُ عاصِمَتَه إليها لتكونَ على مقربة من أوروبا، وليكون الهجومُ على القُسطنطينية من جهة الغربِ، وكانت العاصمة قبل ذلك هي مدينة بورصة، وبَقِيَت هذه المدينة أدرنة عاصِمةً للعثمانيين حتى تمَّ فَتْح القسطنطينية عام 857هـ كما تمَّ الاستيلاءُ على مدُن أوروبية أخرى مثل فيلبه قاعدة بلاد الرومللي الشرقي جنوبي بلغاريا اليوم."},{"id":3082,"title":"اغتيال السلطان الناصر حسن وتولية ابن أخيه المنصور حاجي .","date":["العام الهجري :762","الشهر القمري : جمادى الأولى","العام الميلادي :1361"],"text":"كان زوالُ مُلكِه في ليلة الأربعاء تاسع جمادى الأولى، وذلك أنَّه بلغه وهو بمنزِلِه بكوم برا أنَّ الأمير يلبغا الخاصكي يريدُ قَتْلَه، وأنه لا يدخُلُ إلى الخدمة إلَّا وهو لابِسٌ آلةَ الحَربِ مِن تحت ثيابِه فاستدعى به، وهو مع حريمه في خَلوةٍ، وأمر فنُزِعَت عنه ثيابُه كُلُّها، ثمَّ كُتِّفَت يداه، فشَفَعت فيه إحدى حظايا السلطان، حتى خَلَّى عنه وخلع عليه، واعتذر إليه بأنَّه بلغه عنه أنه لا يدخُلُ إلا بالسلاحِ مخفي في ثيابِه، فخرج إلى مخيَّمِه وقد اشتَدَّ حَنَقُه، فلم يمضِ سوى ثلاثة أيام وبلغ السلطانَ أن يلبغا قد خامر وأظهر العِصيانَ، وألبس مماليكَه آلةَ الحرب، فبادر للركوبِ في طائفةٍ مِن مماليكه ليكبِسَه على بغتة، ويأخُذَه من مخيمه، فسبق ذلك إلى يلبغا من الطواشي بشير الجمدار، فركب بمماليكِه مِن فَورِه بالسلاح يوم الاثنين ثامن جمادى الأولى بعد العصر، ولقي السلطانَ وهو سائِرٌ إليه، وتوافقا حتى غَرَبت الشمس، فحَمَل يلبغا بمن معه يريد السُّلطانَ فانهزم مِن غير قتال، ومعه الأميرُ عِزُّ الدين أيدمر الدوادار، فتفَرَّقَت مماليكه في كلِّ جِهةٍ، وتمادى السلطانُ في هزيمتِه إلى شاطىء النيل، وركِبَ هو وأيدمر فقط في بعضِ المراكب، وترك ركوبَ الحرَّاقة السلطانية، وصَعِدَ قلعة الجبل، وألبَسَ مَن بها من المماليك، فلم يجِدْ في الإسطبل خيولًا لهم، فاضطرب ونزل من القلعةِ ومعه أيْدَمُر وقد تنكَّرا ليسيرا إلى الشامِ فعَرَفَهما بعضُ المماليك، فأنكر حالهما، وأخذهما ومضى بهما إلى بيت الأمير شرف الدين موسى بن المازْكَشي، فآواهما هذا وقد مضى يلبغا وقت هزيمةِ السلطان في إثره فلم يظفَرْ به، فركب الحراقة ومنع أن يعدى مركِبٌ بأحد من المماليك السلطانيَّة إلى بر مصر، وعدَّى بأصحابه في الليل إلى البر، فلَقِيَه الأمير ناصر الدين محمد بن المحسني، والأمير قشتمر المنصوري في عدة وافرة، فحاربهما وهزَمَهما، وتقَدَّمَ فهزم طائفةً بعد طائفة، ثم وجد الأميرَ أسنبغا ابن البوبكري في عِدَّة وافرة فقاتله قريبًا من قنطرة قديدار قتالًا كبيرًا، جرح فيه أسنبغا وانهزم من كان معه، ومضى يلبغا حتى وقف تحت القلعة، فبلغه نزولُ السلطان وأيدمر منكسرينِ، وبينما هو مفكِّرٌ فيما يفعله، إذ أتاه قاصِدُ ابن الأزْكَشي وأخبَرَه بأن السلطان وأيدمر عنده، فسار بعسكَرِه إلى بيت ابن الأزْكَشي بالحُسَينية، وأحاط به، وأخذ السلطانَ والأمير أيدمر ومضى بهما إلى داره، قُرْبَ جبل الكبش فحَبَسَهما بها، ووكَلَ بهما من يثِقُ به، ثم عاد إلى القلعة وقد امتنع بها طائفةٌ مِن مماليك السلطان، ورَمَوه بالنشاب، فأعلمهم بأنه قد قبض على السلطانِ وسَجَنَه في داره، فانحَلَّت عزائِمُهم، وفتحوا باب القلعة، فصَعِدَ يلبغا ومن معه إليها وملكها وأقام في السلطنةِ محمَّدَ بن المظفر حاجي بن محمد بن قلاوون ولَقَّبَه بالمنصور، وكان عمره أربعة عشر عامًا، ولم يُوقَفْ للسلطان حسن على خبر، فقيل إنه عاقبه عقوبةً شديدة حتى مات ودفنه في مصبطة كان يركَبُ عليها من داره بالكبش، وقيل دفنه بكيمان مضر وأَخفى قبره، فكان عمره دون الثلاثين سنة، منها مدة سلطنته هذه الثانية ست سنين وسبعة أشهر وسبعة أيام، وأمَّا السلطان الجديد المنصور فإنه استدعى الخليفةَ وقُضاة القضاة، وأحضر المنصور ففَوَّضَ الخليفة إليه أمورَ الرعيَّة، وركب والكافَّةُ بين يديه من باب الدار إلى الإيوان، حتى جلس على تخت الملك، وحَلَف له الأمراء على العادة، وهو لابِسٌ الثوب الخليفتي، وذلك في يوم الأربعاء تاسِعَ جمادى الأولى، ولُقِّب بالملك المنصور صلاح الدين، وهو أوَّلُ من تسلطن من أولاد أولاد الملك الناصر محمد، فقام الأمير يلبغا بتدبير الدولة، ولم يبقَ للمنصور سوى الاسم، والأميرُ قَشتمر المنصوري نائِبُ السلطنة، ودُقَّت البشائر، ونودي بالقاهرة ومِصرَ بسَلطنةِ الملك المنصور، وكُتِبَ إلى الأعمال بذلك، فسارت البريدية."},{"id":3083,"title":"خروج الأمير بيدمر أمير دمشق عن الطاعة .","date":["العام الهجري :762","الشهر القمري : رجب","العام الميلادي :1361"],"text":"خرج الأميرُ بَيدمر نائِبُ الشام عن الطاعة، وبموافقةِ جماعةٍ مِن الأمراء له على ذلك، منهم أسَنْدَمر أخو يَلبغا اليحياوي، والأمير مَنجَك وجماعة، وأنه قام لأخذ ثأر السُّلطانِ حسن، وأفتاه جماعةٌ من الفقهاء بجواز قتال قاتِلِه الذي تغَلَّب على المُلك- يعني الأمير يَلْبُغا- ومنع البريدَ أن يمُرَّ مِن الشام، وجَهَّزَ الأمير مَنجَك والأمير أَسَندَمُر الزيني في عسكَرٍ إلى غزة، فحاربوا نائِبَها ومَلَكوها، فنصب الأميرُ يَلبُغا السَنْجقَ السلطاني، وتقَدَّمَ إلى الأمراء بالتجهيز للسفر، وأخرج الأميرَ قَشَتمر نائب السلطة إلى جهة الصعيد في عسكَرس ليحفظ تلك الجِهةَ في مُدَّة الغيبة بالشام، وأُقيم الأمير شرف الدين موسى بن الأزْكَشي نائب الغيبة، وخَرَجت طلابُ الأمراء شيئًا بعد شيءٍ، وركب السلطانُ في أول شهر رمضانَ مِن قلعة الجبل، ونزل خارِجَ القاهرة، ثم رحل وصحبته الخليفةُ والأمراء، وتاج الدين محمد بن إسحاق المناوي قاضى العسكر، وسراج الدين عمر الندى قاضي العسكر، فرحل الأميرُ منجَك بمن معه من غَزَّة، عائدًا إلى دمشق، فنزل بها السلطانُ بعساكره وجلس الأميرُ يلبغا لعَرضِ العسكر، ثم ساروا جميعًا إلى دمشق، وخيَّموا بظاهرها، فخرج إليهم أكثَرُ أمراء دمشق وعسكَرُها راغبين في الطاعة، حتى لم يبقَ مِن الأمراء مع بيدمر سوى مَنجَك وأسندمر- وقد امتنعوا بالقلعة- فترددت القضاةُ بين الفريقين في الصُّلحِ حتى تقرر، وحَلَف لهم الأميرُ يَلُبغا على ذلك، فاطمأنُّوا إليه ونزلوا من القلعة، فركبَ السلطانُ بعساكره صبحَ يوم الاثنين تاسع عشرين شهر رمضان، ودخَلَ إلى دمشق وقبض على الأمير بيدمر والأمير منجك والأمير أسندمر، وقُيِّدوا، فأنكر ذلك جمال الدين يوسف بن محمد المرداوي الحنبلي قاضي دمشق، وصار إلى الأمير يَلْبُغا، وقال له: لم يقع الصلحُ على هذا فاعتذر بأنَّه ما قصد إلا إقامةَ حُرمةِ السلطان، ووعد بالإفراجِ عنهم، فلما انصرف بعث بهم إلى الإسكندريَّة، فسُجِنوا بها، وصَعِدَ السلطان إلى قلعة دمشق، وسكَنَها، واستبد الأميرُ يَلْبُغا بتدبير الأمورِ في الشام، على عادتِه في مصر، واستقَرَّ الأمير علاء الدين أمير علي نائب الشام عوضًا عن الأمير بَيدمر، واستقر الأميرُ قطْلُوبُغا الأحمدي رأس نوبة في نيابة حلب عوضًا عن الأمير أحمد بن القَشتمري، ثم سار السلطانُ بعساكره من دمشق في يوم الأحد، فلمَّا قرب من القاهرة دُقَّت البشائر بقلعة الجبل، وزُيِّنَت القاهرة ومصر زينة عظيمة، وصعد إلى قلعته في يوم الاثنين عشرين شوال، وفيه قدم الأمير قَشْتَمُر النائبُ مِن الوجه القبلي."},{"id":3084,"title":"محاولة انقلاب فاشلة على السلطان المنصور صلاح الدين حاجي .","date":["العام الهجري :762","الشهر القمري : رمضان","العام الميلادي :1361"],"text":"اتَّفَق الأميرُ حُسين بن محمد بن قلاوون مع الطواشي جوهر الزمردي نائِبِ مُقَدَّم المماليك على أن يُلبِسَ المماليكَ السُّلطانية آلةَ الحرب ويتسَلْطَن، وكان السفيرُ بينهما نصرَ السليماني أحَدَ طواشية الأمير حسين، فوشَى بذلك إلى الأمراء، وكان السلطانُ بالشام، فبادر الأميرُ أَيْدَمُر الشمسي نائب الغيبة والأمير موسى بن الأزْكَشي وقبضا على جوهر ونصر وسُجِنا بخزانة شمايل بالقاهرة، فلمَّا قَدِمَ السلطان والأمير يلبغا سُمِّرا وشُهِرا، ثم نُفِيَا إلى قوص في ذي القعدة."},{"id":3085,"title":"اغتيال السلطان المريني أبي سالم إبراهيم وتولية محمد الثاني .","date":["العام الهجري :762","الشهر القمري : ذي القعدة","العام الميلادي :1361"],"text":"كان أبو سالم إبراهيمُ المريني منفيًّا في الأندلس، ثم عاد وتمَلَّك بعد أن خَلَع ابن أخيه محمد السعيد الذي جلس بعد اغتيالِ أبيه، ثمَّ في هذه السنة قام الوزيرُ عمر بن عبد الله الفودودي بخلع السلطانِ أبي سالم إبراهيم وقَتَله وولِيَ السلطنة تاشفين بن أبي الحسن علي أخي السلطان المخلوع، وكان تاشفين موسوسًا مختل العقل، ولم يرضَ بنو مرين عما فعله الوزيرُ فخلعوا تاشفين وأتوا بابنِ أخٍ له يدعى محمد الثاني بن أبي الحسن علي المريني فبايعوه وولوه المُلك ولَقَّبوه المنتصر."},{"id":3086,"title":"غارات على بلاد الروم .","date":["العام الهجري :763","العام الميلادي :1361"],"text":"استقَرَّ الأميرُ أَسندمر الطازي في نيابة ملطيَّة فأكثر من الغارات على بلاد الروم، وأسَرَهم وقتَلَهم، فبعث إليه الأمير محمد بن أَرتَنَا صاحِبُ قيصرية الروم عسكرًا مع ابن دُلغَادر، فكبَسَه وهو يتصَيَّد فقاتله قتالًا شديدًا، ونجا بنَفسِه إلى ملطية، فكتب السلطانُ والأمير يلبُغا بخروج عساكِرِ دمشق وطرابلس وحماة وحلب بآلات الحرب والحصار، صحبة الأمير قطْلُوبغا نائب حلب، فخرج من دمشق خمسةُ آلاف فارس، ومن بقيَّة البلاد الشامية سبعة آلاف فارس، وتوجَّه نائب حلب في اثني عشر ألفًا ومعه المجانيق والنقابون، وجميع ما يُحتاج إليه، فشَنُّوا الغاراتِ على بلاد الروم، ثم عادوا بغير طائلٍ!"},{"id":3087,"title":"وفاة الخليفة العباسي المعتضد بالله وتولية ابنه محمد المتوكل على الله .","date":["العام الهجري :763","الشهر القمري : جمادى الأولى","العام الميلادي :1362"],"text":"هو الخليفةُ المُعتَضِد بالله أبو الفتح، واسمُه أبو بكر بن المستكفي بالله أبي الربيع سليمان بن الحاكم بأمر الله أبي العباس أحمد بن الحسن بن أبي بكر بن أبي علي بن الحسن بن الخليفة الراشد بن المسترشد، توفِّيَ يوم الثلاثاء عاشر جمادى الأولى ومدة خلافتِه عشرة أعوام، وعهد إلى ابنه محمد قبل وفاته بقليل، فاستدعي أبو عبد الله محمد ابن الخليفة المعتضد بالله أبي بكر، في يوم الخميس ثاني عشر جمادى الأولى إلى قلعة الجبل، وجلس مع السلطانِ بالقصر، وقد حضر الأمراءُ فأقيمَ في الخلافةِ بعد وفاة أبيه، ولقِّبَ بالمتوكل على الله، وخُلِعَ عليه، وفُوِّضَ له نظَرُ المشهَدِ النَّفيسي؛ ليستعينَ بما يُحمَلُ إليه من النُّذورِ على حالِه، وركِبَ إلى منزله، وهنَّأَه الناسُ بالخلافةِ."},{"id":3088,"title":"مقتل الملك إسماعيل ملك بني نصر وتولي محمد السادس الملك .","date":["العام الهجري :763","الشهر القمري : جمادى الآخرة","العام الميلادي :1362"],"text":"قام أميرٌ مِن أمراء بني نصر يُدعى أبا سعيد محمد، وكان زوجَ أخت السلطان إسماعيل الثاني، فثار على صهره إسماعيلَ وقَتَله وأعلن نفسَه مَلِكًا باسم محمد السادس، ولكنه لم يلبَثْ أن ثار عليه أهلُ غرناطة فخلعوه فهَرَب من غرناطة إلى ملك قشتالة ولم يلبث أن قُتِلَ هناك، ثمَّ إن الوزير المريني عمر الفودودي جهَّزَ محمد الخامس الغني بالله بقوَّة فجاز بها إلى الأندلُسِ مع وزيره لسان الدين ابن الخطيب ودخل غرناطة واسترَدَّ مُلكَه بعد هروب محمد السادس، وعَهِدَ بالوزارة إلى ابن الخطيب."},{"id":3089,"title":"وفاة القاضي الإمام ابن مفلح الحنبلي .","date":["العام الهجري :763","الشهر القمري : رجب","العام الميلادي :1362"],"text":"هو القاضي الإمامُ العالم شمسُ الدين محمد بن مفلح المقدسي الحنبلي الصالحي الراميني الأصل, وُلِدَ ونشأ في بيت المقدس. وكان بارعًا فاضلًا مُتفَنِّنًا في علوم كثيرة، ولاسيما علم الفروع، وكان نائبًا لمشيخة قاضي القضاة جمال الدين يوسف بن محمد المقدسي الحنبلي، وزَوجَ ابنته، وهو أعلَمُ أهل عصره بمذهب الإمام أحمد بن حنبل؛ لذا كان غايةً في نقل مذهب الإمام أحمد، وجمَعَ مصنفات كثيرة منها: كتاب المقنع، وعلق على محفوظة أحكام الشيخ مجد الدين بن تيمية مجلدين، وله الآداب الشرعية، وأصول الفقه، وله غير ذلك من الفوائد والتعليقات رحمه الله، توفي بصالحيةِ دِمشقَ في ثاني رجب عن نحو خمسين سنة، وصُلِّيَ عليه بعد الظهرِ مِن يوم الخميس ثاني الشهر بالجامع المظفري، ودُفِنَ بمقبرة الشيخ الموفق، وكانت له جنازةٌ حافلة حضرها القضاةُ كُلُّهم، وخَلقٌ من الأعيان."},{"id":3090,"title":"خلع السلطان المنصور صلاح الدين حاجي وتولية ابن عمه شعبان .","date":["العام الهجري :764","الشهر القمري : شعبان","العام الميلادي :1363"],"text":"في يومِ الاثنينِ رابِعَ عشر شعبان اقتضى رأيُ الأمير يَلبغَا خَلْعَ السلطان، فوافقه الأمراء على ذلك، فخلعوه من الغدِ لاختلال عَقلِه، وسجنوه ببعضِ الدُّورِ السُّلطانية من القلعة، فكانت مُدَّةُ سلطنته سنتين وثلاثة أشهر وستة أيام، لم يكُنْ له سوى الاسم فقط، وتولى بعده السلطانُ الملك الأشرف زين الدين أبو المعالي شعبان بن الأمجد حسين بن الناصر محمد بن قلاوون السلطنة وعمره عشر سنين، ولم يَلِ أحَدٌ من بني قلاوون وأبوه لم يَلِ السَّلطنةَ سِواه، وكان من خَبَرِه أنَّ الأمير يلبغا جمعَ الأمراء بقلعة الجبل، حتى اتفقوا على خَلعِ السلطان المنصور، ثمَّ بَكَّروا في يوم الثلاثاء النصف من شعبان إلى القلعة وأحضروا الخليفةَ أبا عبد الله محمد المتوكل على الله وقضاة القضاة الأربع، وأعلموهم باختلالِ عَقلِ المنصور وعَدَمِ أهليَّتِه للقيام بأمور المملكة، وأنَّ الاتفاقَ وقع على خلعه فخلعوه، وأحضروا شعبانَ بن حسين وأفاضوا عليه خِلعةَ السلطنة، ولَقَّبوه بالملك الأشرف زين الدين أبي المعالي، وأركبوه بشِعارِ السلطة، حتى جلس على تخت الملك وحَلَفوا له، وقَبَّلوا الأرض على العادة، وكُتِبَ إلى الأعمال بذلك فسارت البُرُدُ في أقطار المملكة، وخُلِعَ على أرباب الوظائف."},{"id":3091,"title":"وفاة المؤرخ ابن شاكر الكتبي .","date":["العام الهجري :764","الشهر القمري : رمضان","العام الميلادي :1363"],"text":"هو المؤرِّخُ صلاح الدين محمد بن شاكر بن أحمد، المعروف بابن شاكر الكتبي، الداراني، الدمشقي. أحَدُ أعلام المؤرخين في القرن الثامن الهجري. كان باحثًا عارفًا بالأدب. ولِدَ في داريا (من قرى دمشق) ونشأ وتوفِّيَ بدمشق. كان فقيرًا جِدًّا، واشتغل بتجارة الكُتُب، فربح منها مالًا طائلًا. له مؤلَّفات مثل: كتاب \"عيون التواريخ\"، و \"فوات الوفيات\". قال ابن كثير: \"في يوم السبت حادي عشر رمضان صَلَّينا بعد الظهر على الشيخ صلاح الدين محمد بن شاكر الكتبي، تفَرَّد في صناعته، وجمع تاريخًا مُفيدًا نحوًا مِن عشر مجلدات، وكان يحفَظُ ويذاكِرُ ويُفيد\""},{"id":3092,"title":"وفاة الأديب المؤرخ خليل بن أيبك الصفدي .","date":["العام الهجري :764","الشهر القمري : شوال","العام الميلادي :1363"],"text":"هو الأديبُ المؤرِّخُ صلاحُ الدين أبو الصفاء، خليل ابن الأمير عز الدين أيبك بن عبد الله الألبكي الصفدي, ولد سنة 696 في صفد بفلسطين، وإليها نُسِبَ، وكان والِدُه أحد أمراء المماليك، وكان إمامًا بارعًا كاتبًا ناظمًا ناثرًا شاعرًا، له مصنفات كثيرة في التاريخ والأدب والبديع وغير ذلك، وتاريخه المسمى: الوافي بالوفيات، وهو مشهورٌ مُعتَمَد، وله تاريخ آخر أصغر من هذا سماه أعوان النصر في أعيان العصر، وله شَرحُ لامية العَجَم، ونكت الهميان في نكت العميان، وكتاب جناس الأجناس، وغيرها من كتب اللغة والتاريخ. توفي بدمشق في ليلة الأحد عاشر شوال."},{"id":3093,"title":"وفاة الملك الصالح شمس الدين صالح ملك ماردين .","date":["العام الهجري :765","العام الميلادي :1363"],"text":"توفِّيَ السلطانُ المَلِكُ الصالح شمس الدين صالح ابن الملك المنصور نجم الدين غازي ابن الملك المظفَّر قرا أرسلان ابن الملك السعيد غازي بن أرتق بن أرسلان بن إيل بن غازي بن ألبي بن تمرداش بن إيل بن غازي بن أرتق الأرتقي صاحب ماردين بها، وقد ناهز السبعينَ سنةً مِن العمر، بعد أن دام في سلطنة ماردين أربعًا وخمسين سنة، وتولَّى ماردين بعده ابنُه الملك المنصور أحمد، وكان المَلِكُ الصالح من أجَلِّ ملوك بني أرتق حزمًا وعزمًا ورأيًا وسؤددًا وكرمًا ودهاءً وشجاعة وإقدامًا، وكان يحِبُّ الفقهاء والفضلاء وأهل الخير، وكان له فضلٌ وفَهمٌ وذوق للشعر والأدب، وكان يحِبُّ المديح ويجيز عليه بالجوائزِ السَّنِيَّة."},{"id":3094,"title":"حرب صليبية ضد العثمانيين ووقعة ماريتزا .","date":["العام الهجري :765","العام الميلادي :1363"],"text":"بعد فَتحِ العُثمانيين أدرنةَ وغيرَها من المدن الأوروبية، خاف الأمراءُ الأوربيون فكتبوا إلى ملوك أوروبا الغربيَّة وإلى البابا يستنجدون بهم ضِدَّهم، حتى إمبراطور القسطنطينية ذهب إلى بابا الفاتيكان في روما وركع أمامَه وقَبَّل يديه ورجليه ورجاه الدعمَ رَغْمَ الخلاف المذهبي بينهما، فلبَّى البابا النداء وكُتِبَ إلى ملوك أوروبا عامة يُطلَبُ منهم الاستعدادُ للقيام بحرب صليبية جديدة حفاظًا على النصرانيَّة من التقَدُّم الإسلامي الجديد، ولكِنَّ ملك الصرب أورك الخامس الذي خلف اصطفان دوشان لم يتوقَّعْ هذا الدعم السريع من البابا وملوك أوروبا؛ لذا استنهض همَّة الأمراء المجاورين له والذين أصبحوا على مقربةٍ مِن الخطر على حَدِّ زَعمِهم، فلبى دعوتَه أمراءُ البوسنة والأفلاق جنوبي رومانيا وأعداد من الجند المرتزقة، مستغلِّينَ انشغال مراد الأول ببعض حُروبِه في آسيا الصغرى، غيرَ أن الجيش العثماني قد أسرع للقاء أعدائِه فاصطدم بهم على نهرِ مارتيزا غربيَّ بلغاريا فهزمهم هزيمةً مُنكَرةً ولَّوا فيها الأدبارَ لا يَلوُون على شيءٍ! واضطرت إمارةُ نصرانية صغيرة على بحر الإدرياتيك على ساحل يوغوسلافيا اليوم وهي إمارة راجوزه أن ترسِلَ وفدًا إلى السلطان وتعقِدَ معه صلحًا تدفع الإمارةُ بموجبه للدولة العثمانيَّة خمسمائة دوكا ذهبيَّة كجِزيةٍ سَنَوية."},{"id":3095,"title":"فتوحات العثمانيين في أوروبا .","date":["العام الهجري :766","العام الميلادي :1364"],"text":"بعد انتِصارِ مُراد الأول في وقعة ماريتزا على التحالُفِ الصليبي العامَ الماضيَ، اضطرب ملوك النصارى المجاورون للدولةِ العَلِيَّة، وطلبوا من البابا أوربانوس الخامس أن يتوسط لدى ملوك أوروبا الغربيين لِيُساعدوهم على محاربة المسلمين وإخراجِهم من أوروبا خوفًا من امتداد الفتحِ العُثماني إلى ما وراء جبال البلقان؛ إذ لو اجتازوها بدونِ مُعارضة ومقاومة في مضايقِها، لم يقوَ أحد بعد ذلك على إيقاف تيار فتوحاتِهم ويُخشى بعدها على جميعِ ممالك أوروبا من العثمانيين، فلبى البابا استغاثَتَهم وكتب لجميع الملوك بالتأهُّب لمحاربة المسلمين، وحَرَّضهم على محاربتهم محاربةً دينيَّةً؛ حفظًا للدين المسيحي من الفتوحات الإسلامية، لكن لم ينتظر أوروك الخامس الذي عيِّنَ مَلِكًا على الصرب بعد دوشان القوي وصولَ المدد إليه من أوروبا، بل استعان بأمراء بوسنة والفلاخ وبعَدَدٍ عظيم من فرسان المجر وسار بهم لمهاجمةِ مدينة أدرنة عاصِمةِ الممالك العثمانية مُعَلِّلينَ النفس بالانتصارِ على العثمانيين ومؤمِّلينَ النصر عليهم؛ لاشتغال الملك مراد الأول بمحاصرة مدينة بيجا بالقُربِ من بورصة بآسيا الصغرى، فلما وصل خبَرُ تقَدُّمِهم إلى العثمانيين قابلوهم على شاطئ نهر ماريتزا وفاجؤوهم في ليلة مظلمة بقُوَّة عظيمة ألقت الرعبَ في قلوبهم واوقعتهم في حيص بيص ولم يلبثوا إلا قليلا حتى وَلَّوا الأدبار تاركين الثرى مُخَضَّبًا بدمائِهم، وكان ذلك في سنة 766 (1363م) أمَّا السلطان مراد فكان في هذه الأثناء مشتغلًا بالقتال في بلاد آسيا الصغرى حيث فتح عِدَّة مدن، ثم عاد إلى مقر سلطنته لتنظيم ما فتَحَه من الأقاليم والبلدان كما هو شأن الفاتح الحكيم الذي لا يكتفي بفَتحِ البلاد وضَرْبِ الذلة والمسكنة على سكانها، بل كان ينسِجُ على منوالِ أبيه وجده، أي: يستريح بضع سنين من عَناءِ الفتح ليُرَتِّبَ جيوشِه ويُكمِل مَن نَقَص منها مستشهدًا في ساحة النصر، ولَمَّا عَظُمَ شأن الدولة خَشِيَها مجاوروها خصوصًا الضعفاء منهم، فأرسلت جمهورية راجوزه في سنة 1365 إلى السلطان مراد رسلًا أمضوا معه صلحًا."},{"id":3096,"title":"إسقاط المكوس عن سائر ما يحمل لمكة .","date":["العام الهجري :766","العام الميلادي :1364"],"text":"رسم السلطانُ المَلِكُ الأشرف شعبان صاحِبُ مصر بإسقاط ما على الحَجِّ مِن المكوسِ بمكَّةَ في سائِرِ ما يُحمَلُ إليها من المتاجر، سوى الكارم- الأحجار الكريمة- وتجَّار الهند وتجار العراق، وأسقط المكسَ المتعَلِّق بالمأكولات، وكان المَكسُ يؤخذ من المأكولات بمكَّةَ مد حب جدي، على كل حمل من التمر اللبان الذي يصل إلى مكة، وثلاثة دنانير مسعوديَّة على كلِّ حِملِ تمر محشي يصِلُ إلى مكة، وستة مسعودية على كلِّ شاة يصل إليها، وسُدس وثمن ما يباعُ بمكَّةَ مِن السَّمن والعسل والخُضَر؛ وذلك أنه يحصى ثمنها مسعودية، فإذا عُرِفَ أخذ على كل خمسة دنانير دينار مسعودية، ويؤخذ -أيضًا- دينار مسعودية من ثمن سلة التمر إذا بيعت بالسوق من الثمار الذي باعها ليعيش منها، والمأخوذُ على التمر أولًا مِن جالبه إلى مكة، ويؤخَذُ شَيءٌ مما يباع في السوق من غيرِ ما ذكرناه، وكان الناس يقاسونَ شِدَّةً، فأزال الله تعالى جميعَ هذا بأمرِ السُّلطانِ الأشرف شعبان صاحِبِ مِصرَ، بتنبيه بعضِ أهل الخير له على ذلك، وعَوَّضَ صاحب مكَّةَ عن ذلك ثمانية وستين ألف درهم من بيت المال المعمور بالقاهرة، وألفَ أردب قمح، وقُدِّرَ ذلك في ديوان السلطان الأشرف، وأمضى ذلك الولاةُ بالديار المصرية فيما بعد."},{"id":3097,"title":"احتلال الفرنج مدينة الإسكندرية بمصر بقيادة لابيردي لويزينانس .","date":["العام الهجري :767","الشهر القمري : محرم","العام الميلادي :1365"],"text":"ورد الخبَرُ في يوم السبت رابع عشر محرم بمنازلة الفرنج الإسكندرية، وأنهم قدموا يوم الأربعاء حادي عشر، فسُرِّح الطائِرُ بذلك إلى الأمير يلبغا، فتوهَّمَ أن تكون هذه مكيدةً يُكادُ بها، فبادَرَ ودخل إلى داره خارِجَ القاهرة، وتَبِعَه السلطان، فصَعِدَ القلعة في يوم الأحد خامس عشر، فلما تحقَّق الأمير يلبغا الخبَرَ، عدى النيلَ مِن ساعته إلى البر الغربي، وتلاحق به أصحابُه، ونودِيَ بالقاهرة: من تأخَّرَ مِن الأجناد غدًا حَلَّ دَمُه ومالُه، فخرج الناس أفواجًا، وسار السلطانُ بعساكره إلى الطرانة، وقَدَّمَ عسكرًا عليه الأمير قطلوبغا المنصوري والأمير كوكنداي، والأمير خليل بن قوصون ليُدرِكوا أهلَ الثَّغرِ، فقَدَّر الله تعالى في ذلك أنَّ أهلَ الثغر كان قد بلَغَهم منذ أشهر اهتمام الفرنج بغزوهم، فكتب بذلك الأميرُ صلاح الدين خليل بن عرام- متولي الثغر- إلى السلطان والأمير يلبغا، فلم يكُنْ مِن الدولة اهتمامٌ بأمْرِهم، فلمَّا توجه ابنُ عرام إلى الحج، واستناب عنه في الثغر الأمير جنغرا- أحد أمراء العشرات- وجاء أوان قدوم مراكب البنادقة من الفرنج، لاح للناظور عِدَّة قلاع في البحر، ثم قَدِمَ في عسكره يوم الأربعاء الحادي والعشرين إلى الميناء، ثمانية أغربة، وتلاها من الأغربة والقراقر ما بلَغَت عدَّتُها ما بين سبعين إلى ثمانين قطعة، فأغلق المسلمون أبواب المدينة، ورَكِبوا الأسوار بآلةِ الحرب، وخرجت طائفةٌ إلى ظاهر البلد، وباتُوا يتحارسون، وخرجوا بُكرةً يوم الخميس يريدونَ لِقاءَ العَدُو، فلم يتحَرَّك الفرنجُ لهم طولَ يَومِهم، وليلة الجمعة، فقَدِمَ بكرة يوم الجمعة طوايفُ من عربان البحيرة وغيرهم، ومضوا جهةَ المنار، وقد نزل من الفرنجِ جَماعةٌ في الليل بخيولهم، وكَمَنوا في الترب التي بظاهر المدينة، فلما تكاثر جمعُ المسلمين من العربان، وأهل الثغر، عند المنار، برز لهم غرابٌ إلى بحر السلسلة، حتى قارب السورَ، فقاتله المسلمون قتالًا شديدًا، قُتِلَ فيه عدة من الفرنج، واستُشهِدَ جماعةٌ من المسلمين، وخرج إليهم أهلُ المدينة وصاروا فرقَتَين، فرقة مضت مع العربان، نحو المنار، وفرقة وقفت تقاتل الفرنج بالغراب، وخرجت الباعةُ والصبيان وصاروا في لهوٍ، وليس لهم اكتراثٌ بالعدو، فضرب الفرنج عند ذلك نفيرَهم، فخرج الكمينُ وحملوا على المسلمينَ حملة منكرة، ورمى الفرنجُ من المراكب بالسِّهام، فانهزم المسلمون، وركب الفرنجُ أقفِيَتَهم بالسيف، ونزل بقيَّتُهم إلى البَرِّ فملكوه، بغير مانعٍ، وقَدَّموا مراكبهم إلى الأسوار، فاستُشهِدَ خَلقٌ كثير من المسلمين، وهلك منهم في الازدحامِ عند عبور باب المدينة جماعةٌ، وخلت الأسوارُ من الحماة، فنصب الفرنجُ سلالم ووضعوا السور، وأخذوا نحو الصناعة، فحرقوا ما بها، وألقَوا النار فيها، ومضوا إلى باب السدرة، وعَلَّقوا الصليب عليه، فانحشر الناسُ إلى باب رشيد، وأحرقوه، ومَرُّوا منه على وجوهم، وتركوا المدينةَ مفتوحة بما فيها للفرنج، وأخذ الأميرُ جنغرا ما كان في بيت المال، وقاد معه خمسين تاجرًا من تجارِ الفرنج كانوا مسجونينَ عنده، ومضى هو وعامَّةُ الناس، إلى جهةِ دمنهور، فدخل وقتَ الضحى من يوم الجمعة مَلِكُ قبرص- واسمه ربير بطرس بن ريوك- وشق المدينةَ وهو راكب، فاستلم الفرنجُ النَّاسَ بالسيف، ونهبوا ما وجدوه من صامتٍ وناطق، وأسَرُوا وسَبَوا خلائق كثيرة، وأحرقوا عِدَّة أماكن، وهلك في الزحام بباب رشيد ما لا يقع عليه حَصرٌ، فأعلن الفرنجُ بدينهم، وانضَمَّ إليهم من كان بالثغر من النصارى، ودلُّوهم على دُور الأغنياء، فأخذوا ما فيها، واستمَرُّوا كذلك يقتلون، ويأسرون، ويَسْبُون وينهبون ويحرقون، من ضَحوة نهار الجمعة إلى بكرة نهار الأحد، فرفعوا السيفَ، وخرجوا بالأسرى والغنائم إلى مراكبهم، وأقاموا بها إلى يوم الخميس الثامن والعشرين، ثم أقلعوا، ومعهم خمسة آلاف أسير، فكانت إقامتُهم ثمانية أيام، وكانوا عِدَّة طوائف، فكان فيهم من البنادقة أربعةٌ وعشرون غرابًا، ومن الجنوية غرابان، ومن أهل رودس عشرة أغربة، والفرنسيين في خمسة أغربة، وبقية الأغربة من أهل قبرص، وكان مسيرهم عند قدوم الأمير يلبغا بمن معه، فلمَّا قَدِمَ عليه الأمير قطلوبغا المنصوري، لم يجد معه سوى عشرين فارسًا، وعليه إقامة مائة فارس، فغَضِبَ عليه، ووجد الأمر قد فات، فكتب بذلك إلى السلطان، فعاد إلى القلعةِ، وبعث بابنِ عرام، نائب الإسكندرية على عادته، بأمر الأمير يلبغا، بموارة من استُشهِدَ من المسلمين، ورَمِّ ما احتَرَق، وغضب على جنغرا وهَدَّده، وعاد فأخذ في التأهُّبِ لغزو الفرنج، وتُتُبِّعَت النصارى، فقُبِضَ على جميع من بديار مصر، وبلادِ الشام وغيرهما من الفرنج، وأُحضِرَ البِطريقُ والنصارى، وأُلزِموا بحَملِ أموالهم، لفِكاكِ أسرى المسلمين من أيدي الفرنج، وكُتِبَ بذلك إلى البلاد الشامية، وتُتُبِّعَت ديارات النصارى التي بأعمال مصر كلِّها، وأُلزِمَ سُكَّانُها بإظهار أموالهم وأوانيهم، وعُوقبوا على ذلك، فكانت هذه الواقعةُ من أشنَعِ ما مرَّ بالإسكندرية من الحوادث، ومنها اختلت أحوالها، واتَّضَع أهلها، وقَلَّت أموالهم، وزالت نِعَمُهم، وكان الناس في القاهرة منذ أعوام كثيرة تجري على ألسنتهم جميعًا: في يوم الجمعةِ تُؤخَذُ الإسكندرية، فكان كذلك."},{"id":3098,"title":"فتنة أولاد الكنز العلويين بمدينة أسوان وسواكن .","date":["العام الهجري :767","الشهر القمري : ربيع الأول","العام الميلادي :1365"],"text":"كان الكنزُ أمير العرب بنواحي أسوان، وهو من الشيعة العَلَوية بمصر، فعصى الكنز الدولةَ واجتمَعَ إليه العرب والسودان، وطالت أيَّامُه واشتهر منذ أيام صلاح الدين، وفي هذا العام كثُرَ فسادُ أولاد الكنز وطائفة العكارمة بأسوان وسواكن، ومَنَعوا التجارَ وغَيرَهم من السفر؛ لِقَطعِهم الطريق، وأخْذِهم أموالَ الناس، وأنَّ أولاد الكنز قد غلبوا على ثغر أسوان، وصحراء عيذاب وبرية الواحات الداخلة، وصاهَروا ملوك النوبةِ، وأمراء العكارمة، واشتَدَّت شوكتُهم، ثم قَدِمَ ركن الدين كرنبس من أمراء النوبةِ، والحاج ياقوت ترجمانُ النوبة، وأرغون مملوك فارس الدين، برسالة متملك دنقلة بأن ابنَ أخته خرج عن طاعته، واستنجد ببني جعد من العرب، وقصدوا دنقلةَ فاقتتلا قتالًا كثيرًا، قُتِلَ فيه الملك وانهزم أصحابُه، ثم أقاموا عِوَضَه في المملكة أخاه، وامتَنَعوا بقلعة الدو فيما بين دنقلة وأسوان، فأخذ ابنُ أخت المقتول دنقلةَ، وجلس على سرير المملكة، وعمل وليمةً جمع فيها أمراء بني جعد وكبارَهم، وقد أعَدَّ لهم جماعةً مِن ثقاته ليفتِكوا بهم، وأمر فأُخلِيَت الدور التي حول دارِ مُضَيِّفِهم، وملأها حَطَبًا، فلما أكَلوا وشَرِبوا، خرجت جماعةٌ بأسلِحَتِهم، وقاموا على باب الدار، وأضرم آخرونَ النَّارَ في الحطب، فلما اشتعلت بادر العُربان بالخروج من الدار، فأوقع القومُ بهم، وقتلوا منهم تسعةَ عشر أميرًا في عِدَّةٍ مِن أكابرهم، ثم ركب إلى عَسكَرِهم، فقَتَل منهم مقتلةً كبيرة، وانهزم باقيهم، فأخذ جميعَ ما كان معهم واستخرج ذخائِرَ دنقلة وأموالها، وأخلاها من أهلِها، ومضى إلى قلعة الدو، وسألا أن ينجِدَهما السلطان على العَرَب، حتى يستردُّوا مُلكَهما، والتزما بحَملِ مال في كل سنة إلى مصر، فرسم السُّلطانُ بنجدتهم وأخَذَ في تجهيز العسكر من سادس عشر شهر ربيع الأول، وساروا في الرابعِ والعشرين، وهم نحوُ الثلاثة آلاف فارس، فأقاموا بمدينةِ قوص ستة أيام، واستدعوا أمراءَ أولاد الكنز من ثغر أسوان ورغَّبوهم في الطاعة، وخَوَّفوهم عاقِبةَ المعصية، وأمَّنوهم، ثم ساروا من قوص، فأتَتْهم أمراء الكنوز طائعينَ عند عقبة أدفو، فخلع عليهم الأميرُ أَقتمر عبد الغني وبالغَ في إكرامهم، ومضى بهم إلى أسوان، وسارت العساكِرُ تريدُ النوبة على محاذاتها في البَرِّ يومًا واحدًا، وإذا برُسُل متمَلِّك النوبة قد لاقَتْهم، وأخبروهم بأنَّ العَرَب قد نازلوا المَلِكَ وحصروه بقلعة الدو، فبادر الأمير أقتمر عبد الغني لانتقاء العسكر، وسار في طائفةٍ منهم جريدة، وترك البقيَّةَ مع الأثقال، وجَدَّ في سيره حتى نزل بقلعة أبريم، وبات بها ليلَتَه، وقد اجتمع بمَلِك النوبة وعرب العكارمة، وبقية أولاد الكنز، ووافاه بقية العسكر فدَبَّرَ مع مَلِكِ النوبة على أولاد الكنز، وأمراء العكارمة، وأمسكهم جميعًا، ورَكِبَ مُتَمَلِّك النوبة في الحالِ، ومعه طائفةٌ من المماليك، ومضى في البَرِّ الشَّرقيِّ إلى جزيرة ميكائيل؛ حيث إقامة العكارمة، وسار الأمير خليل بن قوصون في الجانب الغربي ومعه طائفة، فأحاطوا جميعًا بجزيرة ميكائيل عند طلوع الشمس، وأسَرُوا من بها من العكارمة، وقَتَلوا منهم عِدَّةً بالنشَّاب والنفط، وفَرَّ جماعة نجا بعضُهم وتعلق بالجبال وغرق أكثرهم، وساق ابن قوصون النساء والأولاد والأسرى والغنائم إلى عند الأمير أَقتمر، ففَرَّقَ عِدَّة من السَّبيِ في الأمراء، وأطلق عِدَّةً، وعين طائفةً للسُّلطانِ، ووقع الاتفاقُ على أن يكون كرسي ملك النوبة بقلعة الدو؛ لخراب دنقلة، ولأنَّه يخافُ من عرب بني جعد أيضًا إن نزل المَلِك بدنقلة أن يأخذوه، فكتب الأمير أقتمر عبد الغني محضرًا برضاء مَلِك النوبة بإقامته بقلعةِ الدو، واستغنائه عن النجدة، وأنَّه أذِنَ للعسكر في العود إلى مصر، ثم ألبَسَه التشريف السلطاني، وأجلسه على سرير الملك بقلعة الدو، وأقام ابنَ أخته بقلعة أبريم، فلمَّا تَمَّ ذلك جَهَّزَ مَلِكُ النوبة هديةً للسلطان، وهديةً للأمير يَلْبُغا الأتابك، ما بين خيل وهجن ورقيقٍ وتُحَف، وعاد العسكَرُ ومعهم أمراء الكنز، وأمراء العكارمة في الحديد، فأقاموا بأسوان سبعة أيام، ونودي فيها بالأمانِ والإنصاف من أولاد الكنز، فرُفِعَت عليهم عِدَّةُ مُرافعات، فقُبِضَ على عدة مِن عبيدهم وقُتلوا، ورحل العسكَرُ من أسوان، ومرُّوا إلى القاهرة، فقَدِموا في ثاني شهر رجب، ومعهم الأسرى، فعُرِضوا على السُّلطانِ، وقُيِّدوا إلى السجن، وخُلِعَ على الأمير عبد الغني، وقُبِلَت الهديَّةُ."},{"id":3099,"title":"وفاة الملك المجاهد سيف الدين علي صاحب اليمن .","date":["العام الهجري :767","الشهر القمري : جمادى الأولى","العام الميلادي :1366"],"text":"هو السُّلطانُ المَلِكُ المجاهد سيف الدين أبو يحيى علي ابن السلطان الملك المؤيد هزبر الدين داود ابن السلطان الملك المظفر يوسف ابن السلطان الملك المنصور عمر بن نور الدين علي بن رسول، التركماني الأصل، اليمني المولد والمنشأ والوفاة، صاحب اليمن. كان مولِدُ المجاهد سنة 701 بتعز، ونشأ بها وحَفِظَ التنبيه في الفقه وبحَثَه وتخَرَّج على المشايخ، منهم: الشيخ الإمام العلامة الصاغاني، وتأدب على الشيخ تاج الدين عبد الباقي، وغيرهما، وشارك في علوم، وكان جيِّدَ الفهم وله فَوقٌ في الأدب، وله نظْمٌ ونثر، وطالت مدَّةُ المجاهد في مملكة اليمن، وفعل الخيراتِ وله مآثِرُ: عَمَّر مدرسة عظيمة بتعز وزيادة أخرى وغير ذلك، وعمر مدرسة بمكة المشرفة بالمسجد الحرام بالجانب اليماني مُشرِفَة على الحرم الشريف، توفي بعدن في يوم السبت الخامس والعشرين من شهر جمادى الأولى من هذه السنة، وقيل سنة أربع وستين، وولِيَ بَعدَه ابنُه الملك الأفضل عباس."},{"id":3100,"title":"قدوم الفرنج إلى مصر يطلبون تجديد الصلح والنصرة على متملك قبرص .","date":["العام الهجري :767","الشهر القمري : رجب","العام الميلادي :1366"],"text":"في أوَّلِ شَهرِ رَجَب قَدِمَ الخَبَرُ بوصول رسل الفرنج إلى ميناء الإسكندرية، وأنهم طلبوا رهائِنَ عندهم، حتى يَنزِلوا من مراكِبِهم ويَرُدُّوا رسالتَهم، فلم تؤمَنْ مَكيدتُهم، واقتضى الحالُ إجابَتَهم، فأُخرِجَ مِن سجن الوافي- المعروف بخزانة شمايل- جماعةٌ وَجَب قَتْلُهم، وغُسلوا بالحمَّام، وأُلبِسوا ثيابًا جميلةً، وسافروا إلى الإسكندرية، فأكرَمَهم النائب، وأشاع أنَّهم من رُؤساء الثغر، وبَعَث بهم إلى الفرنجِ، وشَيَّعَ خَلفَهم نساءً وصِبيانًا يَصيحونَ ويَبكونَ، كأنَّهم عيالُهم، وهم يخافون الفِرنجَ عليهم، فمشى ذلك على الفِرنجِ، وعلى أهل الثَّغرِ لانتظامِ حالِ المملكة، ومُلَّاك أمرها، وجودة تدبيرها، فتسَلَّم الفرنجُ الجماعةَ ونَزَلت رسلُهم من المراكب، وقَدِموا إلى قلعةِ الجَبَل، وقد عدى السلطانُ إلى سرحة كوم برا بالجيزة، فحُملوا إلى هناك، وجلس لهم الأميرُ يلبغا الأتابك، وقام الأمراءُ والحُجَّاب بين يديه وأُدخِلوا عليه فهالهم مَجلِسُه، وظنُّوا أنه السُّلطانُ، فقيل لهم هذا مملوكُ السلطان، فكشفوا عن رؤوسِهم، وخَرُّوا على وجوهِهم يُقَبِّلون الأرض، ثم قاموا ودنوا إليه وناولوه كتابَ مَلِكِهم، وقدَّموا هديَّتَه إليه، ففَرَّقَ ذلك بحضرتِهم فيمن بين يديه، واختارَ منه طستًا وأبريقًا من ذهب، وصندوقًا لم يُعرَفْ ما فيه، وتضَمَّنَت رسالتُهم أنهم في طاعة السلطان ومساعِدُوه على متمَلِّك قبرص، حتى تُرَدَّ الأسرى التي أُخِذَت من الإسكندرية، ويُعَوَّض المال وسألوا تجديدَ الصلحِ، وأن يمَكِّنَ تجَّارَهم من قدوم الثغر، وأن تُفتَحَ كَنيسةُ القيامة بالقُدس، وكانت قد أُغلِقَت بعد واقعة الإسكندرية، فأجابهم بأنه لا بُدَّ مِن غزو قبرص وتخريبها، ثمَّ أُخرجوا، فأقاموا بالوطاق ثلاثةَ أيام، وحملوا إلى دار الضيافةِ بجوار قلعة الجبل، فلما عاد السلطانُ مِن السرحة وقَفوا بين يديه وقَدَّموا هديَّتَهم، وأدَّوا رسالتَهم، فلم يُجابوا وأعيدوا إلى بلادِهم خائبينَ."},{"id":3101,"title":"غزو قشتالة وفتح آشر .","date":["العام الهجري :768","العام الميلادي :1366"],"text":"كان الأميرُ محمد الخامس الغني بالله أميرُ غرناطة قد بدأ الغزوَ مِن السنة الماضية على قشتالة، وفي هذه السنة استمر على ما كان عليه، فزحف بقواتِه على ولاية إشبيلية وقشتالة، وفَتَح حِصنَ آشر وهو من معاقِلِ قشتالة المعروفة، كما استولى على كثيرٍ مِن الغنائم، وسبى الكثيرَ مِن أهلِها."},{"id":3102,"title":"فتنة يلبغا العمري ومحاولته خلع السلطان الأشرف شعبان .","date":["العام الهجري :768","الشهر القمري : ربيع الآخر","العام الميلادي :1367"],"text":"لَمَّا كان في مستهَلِّ شَهرِ ربيع الآخر نزل السلطانُ من قلعة الجبل وعَدَّى إلى بر الجيزة ليتوجه إلى الصيدِ بالبحيرة، بعد أن ألزم الأمراءَ أن يجعلوا- في الشواني التي نجز عملها برسم الغُزاة- العِدَد والسلاحَ والرجالَ على هيئة القِتالِ؛ لِيَنظُرَ السلطان والنَّاس، ثم سار السلطان والأتابك يلبغا بالعساكِرِ مِن بر الجيزة يريدون البحيرةَ حتى نزلوا في ليلة الأربعاء سادسَ شهر ربيع الآخر بالطرانة وباتوا بها، وكانت مماليكُ يلبغا قد نَفِرَت قلوبُهم منه؛ لكثرةِ ظُلمِه وعَسفِه وتنوُّعِه في العذاب لهم على أدنى جُرمٍ، فاتفق جماعةٌ من مماليك يلبغا تلك الليلة على قَتْلِه من غير أن يُعلِموا المَلِكَ الأشرفَ هذا بشَيءٍ مِن ذلك، وركبوا عليه نِصفَ الليل، ورؤوسُهم من الأمراء: آقبغا الأحمدي الجلب، وأسندمر الناصري، وقجماس الطازي، وتغري برمش العلائي، وآقبغا جاركس أمير سلاح، وقرابغا الصرغتمشي، في جماعةٍ مِن أعيان اليلبغاوية، ولَبِسوا آلة الحرب وكبَسوا في الليل على يلبغا بخيمتِه بغتةً وأرادوا قتله، فأحسَّ بهم قبل وصولِهم إليه، فركِبَ فَرَس النوبةِ بخواصِّه من مماليكه، وهرب تحت الليل، وعَدَّى النيل إلى القاهرة، ومنع سائرَ المراكب أن يعدُّوا بأحد، واجتمع عنده من الأمراء طيبغا حاجِبُ الحجَّاب، وأيبك البدري أمير آخور، وجماعة الأمراء المقيمين بالقاهرة، وأمَّا مماليك يلبغا فإنَّهم لَمَّا عَلِموا بأن أستاذهم نجا بنَفسِه وهرب، اشتدَّ تخَوُّفُهم من أنَّه إذا ظَفِرَ بهم بعد ذلك لا يُبقي منهم أحدًا، فاجتمع الجميعُ بمن انضاف إليهم من الأمراءِ وغيرِهم وجاؤوا إلى المَلِك الأشرَفِ شعبان وهو بمُخَيَّمِه أيضًا بمَنزِلِه بالطرانة وكَلَّموه في مُوافَقَتِهم على قتالِ يلبغا فامتنع قليلًا ثم أجاب لِما في نفسه من الحزازةِ مِن حَجْرِ يلبغا عليه، وعدم تصَرُّفه في المملكة، وركِبَ السلطان بمماليك يلبغا وخاصكيَّته، فأخذوه وعادوا به إلى جهة القاهرة، وقد اجتمع عليه خلائِقُ من مماليك يلبغا وعساكر مصر، وساروا حتى وصلوا إلى ساحِلِ النيل ببولاق التكروري تجاه بولاق والجزيرة الوسطى، فأقام المَلِكُ الأشرف ببولاق التكروري يوم الأربعاء ويوم الخميس ويوم الجمعة، فلم يجدوا مراكِبَ يعدون فيها، وأما يلبغا فإنَّه لما علم أن الملك الأشرف طاوع مماليكَه وقَرَّبهم، أنزل من قلعة الجبل آنوك ابنَ الملك الأمجد حسين أخي الملك الأشرف شعبان وسَلْطَنَه ولَقَّبَه بالملك المنصور، وذلك بمُخَيَّمِه بجزيرة أروى المعروفة بالجزيرة الوسطانيَّة تجاه بولاق التكروري، حيث الملك الأشرف نازلٌ بمماليك يلبغا بالبر الشرقي والأشرف بالبر الغربي، فسَمَّتْه العوامُ سُلطان الجزيرة، ثمَّ في يوم الجمعة حضر عند الأتابك يلبغا الأمير طغيتمر النظامي والأمير أرغون ططر، فإنهما كانا يتصَيَّدان بالعباسة وانضافا بمن معهما إلى يلبغا فقَوِيَ أمره بهما، وعَدَّى إليه أيضًا جماعة من عند الملك الأشرف، وهم: الأمير قرابغا البدري، والأمير يعقوب شاه، والأمير بيبغا العلائي الدوادار، والأمير خليل بن قوصون، وجماعة من مماليك يلبغا الذين أمَّرَهم مثل: آقبغا الجوهري، وكمشبغا الحموي، ويلبغا شقير، في آخرين، واستمَرَّ الأتابك يلبغا وآنوك بجزيرة الوسطى، والملك الأشرف ومماليك يلبغا ببولاق التكروري، إلى أن حضر إلى الأشرفِ شَخصٌ يُعرَفُ بمحمد ابن بنت لبطة رئيس شواني السلطان، وجَهَّز للسلطانِ مِن الغربان التي عَمَّرَها برسم الغزاة نحو ثلاثينَ غُرابًا برجالها وكَسَر بروقها، وجعلها مثل الفلاةِ لأجلِ التَّعدية، فنزل فيها جماعةٌ مِن الأمراء ومن مماليك يلبغا ليعَدُّوا فيها إلى الجزيرة، فرمى عليهم يلبغا بمكاحِلِ النفط، وصار هؤلاء يرمون على يلبغا بالسهام فيردونَهم على أعقابِهم، وأخذ يلبغا ومن معه يرمون أيضًا النِّفطَ والنشاب، والأشرفيَّة لا يلتفتون إلى ذلك، بل يزيدونَ في سب يلبغا ولَعْنه وقتاله، وأقاموا على ذلك إلى عَصرِ يوم السبت، وقد قَوِيَ أمر الملك الأشرف وضَعُفَ أمر يلبغا، ثم اتفق رأيُ عساكر الملك الأشرف على تعدية المَلِك الأشرف من الورَّاق، فعدى وقتَ العَصرِ من الوراق إلى جزيرة الفيل وتتابعَتْه عساكره، فلما صاروا الجميعُ في بر القاهرة، وبلغ ذلك يلبغا، هرب الأمراءُ الذين كانوا مع يلبغا بأجمعهم وجاؤوا إلى الملك الأشرف وقَبَّلوا الأرض بين يديه، فلمَّا رأى يلبغا ذلك رجع إلى جهة القاهرة، ووقف بسوقِ الخيل من تحت قلعة الجبل، ولم يبقَ معه غير طيبغا حاجِبِ الحجَّاب الذي كان أولًا أستاداره، فوقف يلبغا ساعةً ورأى أمْرَه في إدبار، فنزل عن فَرَسِه بسوق الخيل تجاه باب الميدان، وصلَّى العصر، وحلَّ سَيْفَه وأعطاه للأميرِ طيبغا الحاجب، ثم نزل وقصَدَ بَيتَه بالكبش فرجمته العوامُّ مِن رأس سويقة منعم إلى أن وصل حيثُ اتجه، وسار الملك الأشرف شعبان بعساكره، حتى طلع إلى قلعةِ الجَبَلِ في آخر نهار السبت، وأرسل جماعةً منِ الأمراء إلى يلبغا، فأخذوه من بيتِه ومعه طيبغا الحاجِبُ، وطلعوا به إلى القلعةِ بعد المغرب، فسُجِنَ بها إلى بعدِ عشاء الآخرة، فلما أُذِّنَ للعشاء جاء جماعةٌ من مماليك يلبغا مع بعض الأمراء، وأخذوا يلبغا من سجنه وأنزلوه من القلعةِ، فلما صار بحدرة القلعة أحضروا له فَرَسًا ليركَبَه، فلما أراد الركوب ضَرَبه مملوكٌ مِن مماليكه يسمَّى قراتمر فأرمى رأسَه، ثم نزلوا عليه بالسيوفِ حتى هَبَروه تهبيرًا، وأخذوا رأسَه وجعلوها في مِشعَلِ النار إلى أن انقَطَع الدم، فلما رآه بعضُهم أنكره وقال: أخفيتُموه، وهذه رأسُ غَيرِه فرفعوه من المِشعَل، ومَسَحوه ليُعَرِّفوه أنَّه رأس يلبغا بسلعةٍ كانت خلفَ أذنه، فعند ذلك تحقَّقَ كُلُّ أحد بقتله، وأخذوا جثَّتَه فغَيَّبوها بين العروستين، فجاء الأميرُ طشتمر الدوادار فأخذ الرأسَ منهم في الليل، واستقصى على الجثَّةِ حتى أخذها، وحَطَّ الرأس على الجثة، وغَسَّلها وكفَّنَها وصلى عليه في الليل، ودفنه بتربتِه التي أنشأها بالصحراء بالقربِ مِن تربة خوند طغاى أم آنوك زوجة الناصر محمد بن قلاوون."},{"id":3103,"title":"فتنة بين الأمراء في مصر .","date":["العام الهجري :768","الشهر القمري : شوال","العام الميلادي :1367"],"text":"لَمَّا كان يومُ الأحد سابع شوال بلغ الأميرَ أسندَمُر الناصريَّ أميرَ كبير أتابك العساكر ومُدَبِّر المملكة ونائِبَ السلطنة- وهو الذي أصبح المقَدَّمَ بعد قَتلِ يلبغا- أنَّ جماعةً من الأمراء قد اتَّفَقوا على الفتكِ به وبالأجلاب، وهم أعضادُه وبهم يصولُ، فخرج ليلًا من داره إلى دار الأمير قجماس الطازي، وبذل له مالًا كبيرًا حتى استماله إليه، ثم فارَقَه، وفي ظَنِّه أنه قد صار معه، ولم يكن كذلك، وعاد إلى مَنزِلِه بالكبش واستدعى خواصَّه من اليلبغاوية، وقَرَّرَ معهم أنه إذا ركب للحرب يَقتُل كُلُّ واحد منهم أميرًا، أو يَقبِض عليه، وبذل لهم مالًا كبيرًا حتى وافَقوه، وما هو إلا أن خرج أسنَدمر من عند قجماس ليُدَبِّرَ ما قد ذكَرَ مع الأجلاب، ركب قجماس إلى جماعة من الأمراء، وقَرَّر معهم القبضَ على أسنَدمُر، فركبوا معه للحرب، ووقَفوا تحت القلعة، فنزل السلطانُ في الحال إلى الإسطبل، ودُقَّت الكوسات حربيًّا، وأما أسندمر فإنَّه بات هذه الليلة في إسطبله، حتى طلعت الشمس، ركب من الكبش بمن معه من اليلبغاويَّة وغيرهم، ومضى نحو القرافة، ومَرَّ من وراء القلعة، حتى وافاهم من تحت دار الضيافة، ووقف تحت الطبلخاناه فالتقى مع الأمراء، واقتتلوا فهَزَمَهم بمن كان قد دبَّر معهم من اليلبغاوية في الليل قَبْضَ الأمراء أو قَتْلَهم، وثبت الأمير ألجَاي اليوسفي والأمير أرغون ططر، وقاتلا أسندمر إلى قبيل الظهر، فلما لم يجدا مُعينًا ولا ناصرًا انكسرا إلى قبة النصر، وانفَضَّ الجمع بعد ما قتل الأمير ضروط الحاجب، وجرح الأمير قجماس والأمير أقبغا الجلب، وكثيرٌ من الأجناد والعامة، فقَبَض الأمير أَسَندَمر على الأمير قجماس، والأمير أَقبغا الجلب والأمير أقطاي، والأمير قُطْلُوبغا جركس، وهؤلاء أمراءُ ألوف، وقبض من أمراء الطبلخاناه على قرابغا شاد الأحواش، واختفى كثيرٌ من الأمراء، ومرت مماليك أَسَندَمُر وطائفة من الأجلاب في خلقٍ كثير من العامة، فنَهَبوا بيوت الأمراء، فكانت هذه الواقعةُ من أشنع حوادث مصر وأعظَمِها فسادًا."},{"id":3104,"title":"نائبا حماة وطرابلس يخرجان عن طاعة الملك الأشرف .","date":["العام الهجري :768","الشهر القمري : ذي القعدة","العام الميلادي :1367"],"text":"اتَّفَق الأميرُ طيبغا الطويل نائِبُ حماة- وكان قد أصبح نائبها هذه السنة بعد فتنة يلبغا وقَتْلِه- والأمير أشقتمُر نائب طرابلس، على المخامرة والخروج عن طاعة السلطان، فتجَهَّز الأمير أسندمر الأتابك للسفر، وتقَدَّم بتهيؤ الأمراء، وبعث القُصَّاد للكشف عن ذلك على البريدِ، فعادوا باستمرار بقيَّة النواب على الطاعة، ما عدا المذكورين، فكتب بالقبضِ عليهما، فقُبِضَا وقبض معهما على إخوة طيبغا الطويل، وحُملوا إلى الإسكندرية مُقَيَّدين، واستقَرَّ أسندمر الزيني في نيابة طرابلس، وأُعيدَ عُمر شاه إلى نيابة حماة في أوائل ذي القعدة، واستقَرَّ أرغون الأزقي في نيابة صفد."},{"id":3105,"title":"الغزو الغرناطي على الإسبان .","date":["العام الهجري :769","العام الميلادي :1367"],"text":"استمر محمَّدٌ الخامس أمير غرناطة بالغزو, فحاصر مدينةَ جيَّان واقتحمها بعد معاركَ شَديدةٍ واستولى على ما فيها من أموالٍ وسلاح كما أسَرَ جُموعًا كثيرة، واقتحم أيضًا مدينة ياغة جنوب جيان ونهَبَها ودمَّرَ قَلعَتَها وتابع زَحفَه على مدينة أبده شمال شرق جيان واستولى عليها ودمر أسوارها، ثم عاد إلى غرناطة مكلَّلًا بالنصر، ثم توجه إلى الجزيرة الخضراء وحاصرها واستولى عليها بعد قتال مرير."},{"id":3106,"title":"فتنة الأمير أسندمر ومماليك يلبغا وقتالهم السلطان الأشرف .","date":["العام الهجري :769","الشهر القمري : صفر","العام الميلادي :1367"],"text":"اتَّفَقَت مماليكُ يلبغا الأجلاب يوم الجمعة سادس صفر على الأميرِ أسندَمُر الناصري أمير كبير أتابك العساكر ومدَبِّر المملكة ونائب السلطنة، وركبوا معهم الأمراء وقت صلاة الجمعة، ودخلوا على أسندمر الناصري وسألوه أن يُمسِكَ جماعة من الأمراء، فمَسَك أزدمر العزي أمير سلاح وجركتمر المنجكي أمير مجلس، وبيرم العزي الدوادار الكبير، وبيبغا القوصوني، والأمير آخور كبك الصرغتمشي الجوكندا، واستمَرَّ المماليك لابسين السلاح، وأصبحوا يوم السبت ومَسَكوا خليل بن قوصون ثم أطلقوه، وانكسرت الفتنةُ إلى عشية النهار وهي ليلة الأحد، وقالوا لأسندمر: نريد عَزْلَ الملك الأشرف، وكان أسندمر مقهورًا معهم، وبلغ الخبَرُ المَلِكَ الأشرف، فأرسل في الحال إلى خليل بن قوصون فحضر، ورَكِبَ الملك الأشرف وركب ابن قوصون ومماليك الأشرف الجميعُ مع أستاذهم، وكانوا نحو المائتين لا غير، وكان الذين اجتمعوا من مماليك يلبغا فوق الألف وخمسمائة، وركِبَ مع الملك الأشرف جماعةٌ مِن الأمراء الكبار مثل أسنبغا ابن الأبو بكري وقشتمر المنصوري في آخرين، وضُرِبَت الكوسات، واجتمع على السلطان خلقٌ كثير من العوام، ولَمَّا بلغ أسندمرَ الناصري ركوبُ الملك الأشرف، أخذ جماعةً من مماليك يلبغا، وطلع من خلف القلعةِ كما فعل أولًا في واقعة آقبغا الجلب، وتقَدَّمت مماليك يلبغا وصَدَموا المماليك الأشرفية وتقاتلوا، وبينما هم في ذلك جاء أسندمر بمن معه من تحت الطبلخاناه كما فعل تلك المرَّة، فعلم به الأشرفيَّة والأمراء، فمالوا عليه فكَسَروه أقبحَ كَسرةٍ وقرب أسندمر، ثم أُمسِكَ وتمَزَّقَت المماليك اليلبغاوية، فلما جيءَ للأشرف بأسندمر وحضر بين يديه شفع فيه الأمراءُ الكبار، فأطلقه السلطان ورسم له أن يكون أتابكًا على عادتِه، ورسم له بالنزول إلى بيتِه بالكبش، ورسم للأمير خليل بن قوصون أن يكون شريكَه في الأتابكية، فنزل أسندمر إلى بيتِه ليلة الاثنين، وأرسل السلطانُ معه الأمير خليل بن قوصون صفةَ الترسيم، وهو شريكُه في وظيفة الأتابكية، ليُحضِرَه في بكرة نهار الاثنين، فلما نزلا إلى الكبش، تحالفَا وخامرا ثانيًا على السلطانِ، واجتمع عند أسندمر وخليل بن قوصون في تلك الليلة جماعةٌ كبيرة من مماليك يلبغا، وصاروا مع أسندمر كما كانوا أولًا، وأصبحا يوم الاثنين وركبا إلى سوق الخيل، فركب السلطانُ بمن معه من الأمراء والمماليك الأشرفية وغيرهم، فالتَقَوا معهم وقاتلوهم وكسَروهم، وقتلوا جماعةً كبيرة من مماليك يلبغا، وهرب أسندمر وابن قوصون واشتغل مماليكُ السلطان والعوام بمَسكِ مماليك يلبغا، يمسِكونَهم ويحضرونهم عرايا مُكَشَّفي الرؤوس، وتوجه فِرقة  من السلطانية إلى أسندمر وابن قوصون فقَبَضوا عليهما وعلى ألطنبغا اليلبغاوي وجماعة أُخَر من الأمراء اليلبغاوية، فقُيِّدوا وأرسلوا إلى سجن الإسكندرية، ثم جَلَس الملك الأشرف شعبان في الإيوان وبين يديه أكابِرُ الأمراء، ورسم بتسميرِ جماعةٍ مِن مماليك يلبغا نحوَ المائة وتوسيطِهم- أي: قتلهم- ونفى جماعة منهم إلى الشام، وأخذ مال أسندمر وأنفق على مماليكِه لكُلِّ واحد مائة دينار، ولكُلِّ واحد من غير مماليكِه خمسون دينارًا، ورسم للأمير يلبغا المنصوري باستقراره أتابك العساكر هو والأمير ملكتمر الخازندار، وأنعم على كلٍّ منهما بتقدمة ألف، وأنعم على تلكتمر بن بركة بتقدمة ألفٍ عوضًا عن خليل بن قوصون، وكان ذلك في سادس عشر صفر، ثم أصبح السلطانُ من الغد يوم الثلاثاء سابع عشر صفر قبض على يلبغا المنصوري ورفيقه تلكتمر المحمدي؛ لأنَّهما أرادا الإفراج عن مماليك يلبغا العمري، وقَصَد يلبغا المنصوري أن يسكن بالكبش، فمسكهما الملكُ الأشرف وأرسلهما إلى الإسكندرية، ثم أرسل السلطانُ بطلب الأمير منكلي بغا الشمسي نائب حلب إلى الديار المصرية، فحضرها بعد مدَّة وخَلَع عليه السلطانُ خِلعةَ النيابة بديار مصر، فأبى أن يكون نائبًا، فأنعم عليه بتقدمة ألفٍ وجعله أتابك العساكر، وتولى نيابةَ حلب عِوَضَه طيبغا الطويلُ، وكان أخرجه من سِجنِ الإسكندرية قبل ذلك."},{"id":3107,"title":"الفرنج يغزون طرابلس .","date":["العام الهجري :769","الشهر القمري : صفر","العام الميلادي :1367"],"text":"وصلَ الفِرنجُ طرابلس في أول صفر في مائة وثلاثين مركبًا، ما بين شيني وقرقورة وغراب وطريدة، وشختور، عليها متمَلِّك قبرص، ومتمَلِّك رودس، والاسبتار، وكان نائِبُ طرابلس وأكثر عسكرها غائبين عنها، فاغتَنَمَت الفرنج الفرصةَ وخرجوا من مراكبهم إلى الساحل، فخرج لهم من طرابلس بقيَّةُ عَسكَرِها بجماعة من المسلمين، فترامَوا بالنبال ثم اقتتلوا أشدَّ قتال، وتقهقر المسلمون، ودخل المدينةَ طائفةٌ من الفرنج، فنَهَبوا بعض الأسواق، ثم إن المسلمين تلاحقوا، وحصل بينهم وبين الفرنج وقائع عديدة استُشهِدَ فيها من المسلمينَ نحوُ أربعين نفرًا، وقُتِل من الفرنج نحو الألف، وألقى الله تعالى الرُّعبَ في قلوب الفرنج فرجعوا خائبين، فمرُّوا بمدينة إياس في مائة قطعة، فسار إليهم الأميرُ منكلي بغا نائب حلب، وقد فَرَّ أهل إياس منها، فدخلها الفرنج، فلما قدم نائب حلب جلَوا عنها."},{"id":3108,"title":"وفاة ابن عقيل النحوي .","date":["العام الهجري :769","الشهر القمري : ربيع الأول","العام الميلادي :1367"],"text":"هو الإمامُ القاضي بهاء الدين أبو محمد عبد الله بن عبد الرحمن بن عَقيل المصري الشافعيُّ، قاضي قضاة الديار المصرية، وفقيه الشافعية، ولِدَ في المحرم سنة 698، ونسبه يتَّصِلُ إلى عقيل بن أبي طالب، ونشأ بالقاهرةِ، وقرأ على عُلَماءِ عَصرِه، وبرع في علوم كثيرة، وصنف التصانيفَ المُفيدةَ في الفقه والعربية والتفسير، منها شرح الألفية لابن مالك، وشرح التسهيل أيضًا، والجامع النفيس في فقه الشافعية، وباشر قضاء الديار المصرية مدة يسيرة، وباشر التداريس الجليلة والمناصب الشريفة، توفي بالقاهرة في ليلة الأربعاء الثالث والعشرين من شهر ربيع الأول، ودُفن بالقرافة بالقرب من قبَّة الإمام الشافعي."},{"id":3109,"title":"وفاة الملك إبراهيم الحفصي ملك تونس .","date":["العام الهجري :770","الشهر القمري : رجب","العام الميلادي :1369"],"text":"هو المَلِكُ أبو إسحاق إبراهيم بن أبي بكر بن يحيى بن إبراهيم بن يحيى، بعدما مَلَك تسع عشرة سنة وشهرين، وهو الملك الرابع عشر من ملوك الحفصيين بتونس، فقام بعدَه ابنه أبو البقاء خالد، وكان حاجِبُه ابن المالقي هو الذي يتولى أمورَ السلطة ويستبِدُّ بها. مات في العشرين من رجب."},{"id":3110,"title":"فتنة العامة في مصر ضد ظلم الوالي .","date":["العام الهجري :770","الشهر القمري : ذي القعدة","العام الميلادي :1369"],"text":"في يومِ الجمعة ثالثَ عَشرَ ذي القعدة تجمَّعَت الغوغاء من زعر العامة بأراضي اللوق خارج القاهرة للشلاق، فقُتِلَ بينهم واحد منهم، فركب والي القاهرة الشريفُ بَكتمُر، وأركب معه الأميرَ علاء الدين علي بن كَلَفت الحاجب، والأمير أقبغا اليوسفي الحاجب، وقصد المشالقينَ، ففروا منهم، وبَقِيَ من هناك من النظَّارة، فضرب عِدَّةً منهم بالمقارع، فتعَصَّبت العامة، ووقفوا تحت القلعةِ في يوم الثلاثاء، وأصبحوا يوم الأربعاء الثامن عشر كذلك، وهم يستغيثونَ ويضجُّون بالشكوى من الوالي، فأُجيبوا بأن السلطان يَعزِلُ عنكم هذا الواليَ فأبوا إلا أن يُسَلِّمَه إليهم هو والحاجبين، وكان الوالي قد ركب على عادته بُكرةَ النهار يريد القلعة، فرجمته العامَّةُ حتى كاد يَهلِكَ فالتجأ منهم بالإسطبل، وظَلَّ نهاره فيه، والعامَّةُ وقوفٌ تحت القلعة إلى قريب العصر، وكلما أمروا بأن يَمضُوا أبَوا ولَجُّوا، فركب إليهم الوالي في جمعٍ موفور من مماليك الأمير بَكتمُر المومني، أمير آخور، ومن الأوجاقية، فثارت العامَّةُ ورجمتهم رجمًا متداركًا حتى كَسَروهم كسرةً قبيحة، فركِبَت المماليك السلطانية، والأوجاقية وحَمَلوا على العامة، وقتلوا منهم جماعةً، وقَبَضوا على خلائِقَ منهم، وركب الأمير ألجاي اليوسفي، وقَسَّم الخطط والحارات على الأمراء والمماليك، وأمرهم بوضع السيف في الناس، فجرت خطوبٌ شنيعة، قتل فيها خلائِقُ ذهبت دماؤهم هدرًا، وأُودِعَت السجونَ منهم طوائِفُ، وامتدت أيدي الأجنادِ إلى العامَّةِ حتى إنَّه كان الجنديُّ يدخل إلى حانوت البياع من المتعَيِّشينَ ويَذبَحُه ويمضي، وحكى بعضُهم أنَّه قَتَل بيده في هذه الواقعة من العامة سبعة عشر رجلًا، وكانت ليلةُ الخميس التاسع عشر من ليالي السوءِ، وأصبح الناسُ وقد بلغ السلطانَ الخَبَرُ، فشَقَّ عليه وأنكره، وقال للأمير بكتمر المومني عَجَّلت بالأضحية على الناس وتوعَّده، فرجف فؤادُه ونَحَب قَلْبُه، وقام فلم يزَلْ صاحِبَ فراش حتى مات، وأمر السلطانُ بالإفراج عن المسجونين، ونُودِيَ بالأمان، وفَتْح الأسواق، ففُتِحَت وقد كان الناس قد أصبحوا على تخوفٍ شديدٍ لِما مَرَّ بهم في الليلِ."},{"id":3111,"title":"مقتل الأمير قشتمر المنصوري نائب حلب .","date":["العام الهجري :770","الشهر القمري : ذي الحجة","العام الميلادي :1369"],"text":"في هذه السَّنةِ قُتِلَ الأميرُ قشتمر المنصوري نائب حلب، وخبَرُه أنَّه لَمَّا وَلَيَ نيابة حلب في جمادى الآخرة من هذه السنة وتوجَّه إلى حلب، فلم يُقِمْ بها إلا يسيرًا، ثم إن بني كلاب كَثُر فسادُهم وقَطْعُهم الطريقَ فيما بين حماة وحلب، وأخذوا بعضَ الحُجَّاج، فخرج إليهم الأمير قشتمر نائِبُ حلب بالعسكر، حتى أتوا تلَّ السلطان بظاهر حلب، فإذا عدَّةٌ من مضارب عرب آل فضل، فاستاق العسكَرُ جمالَهم ومواشيَهم ومالوا على بيوت العَرَبِ فنهبوها، فثارت العَرَبُ بهم وقاتلوهم، واستنجدوا مَن قَرُب منهم من بنى مهنا، وأتاهم الأميرُ حيار وولده نعير بجمع كبيرٍ، فكانت معركة شنيعة، قُتِلَ فيها الأمير قشتمر النائب وولَدُه وعِدَّة من عسكره، وانهزم باقيهم، فركب العرَبُ أقفِيَتَهم، فلم ينجُ منهم عريانًا إلا من شاء الله، وكان ذلك يومَ الجمعة خامس عشر ذي الحجة، ولما بلغ الملك الأشرف ذلك عَظُمَ عليه، وأرسل تقليدًا للأمير اشقتمر المارديني بنيابة حلب على يد الأمير قطلوبغا الشعباني، وعزل حيارًا عن إمرة العَرَب وولاها لزامِل."},{"id":3112,"title":"الفرنج يحاولون النزول على الإسكندرية .","date":["العام الهجري :770","الشهر القمري : ذي الحجة","العام الميلادي :1369"],"text":"في يومِ الجمعة ثامِنَ ذي الحجة قَدِمَ الخبر بنزول أربع قطايعَ على الإسكندرية من الفرنج، وأنهم رمَوا على المدينة بمنجنيق، فخرج تلك الليلةَ ثلاثة وعشرون أميرًا، منهم ثلاثةٌ من الألوف وعشرة من الطبلخاناه وعشرة من أمراء العشرات، فقَدِمَ الخبر في عشية السبت أنَّ المغاربة والتركمان نزلوا في المراكب، وقاتلوا الفرنج، وقتلوا منهم نحوَ المائة، وغنِموا منهم مركبًا."},{"id":3113,"title":"ظهور دولة تيمورلنك وعاصمتها سمرقند .","date":["العام الهجري :771","العام الميلادي :1369"],"text":"كان مِن وَلَدِ جنكيز خان, جغطاي الذي استقَرَّ في تركستان وبَقِيَت أسرته تحكُمُ هذه المنطقةَ وكان توغلق تيمور أحدَ ملوك المغول واستقَرَّ في أعمال تركستان الشرقية عام 748 وأعلن أنَّه حفيدُ داود خان، وضَمَّ إليه بلادَ ما وراء النهر ودخلت في أيَّامِه أعدادٌ كبيرة من المغول إلى الإسلام، ثم إنَّ والي سمرقند تحرَّك نحو مدينة هراة واحتَلَّها، ثمَّ إنه اغتِيلَ واختلف الأهالي وعَمَّتهم الفوضى، فوصل الخبر إلى توغلق تيمور فسار بقوة نحو سمرقند، ففَرَّ مِن وجهه بعضُ الأمراء الذين كانوا يُظهِرون العصيان، ثم إنَّ تيمورلنك وخَوفًا من تهديم البلدة تقَدَّمَ إلى قائد طليعة جيش المغول وأكرَمَه، فأمر هذا القائد جُندَه ألَّا يمَسُّوا هذه البلدة بسوءٍ، كما طلب من تيمورلنك أن يسيرَ معه إلى الخان توغلق تيمور، فكافأه الخان وجعله واليًا على مدينة كش، وأعطى توغلق تيمور إمرة سمرقند إلى تيمورلنك على أنَّ قائد الجيش فيها هو إلياس ابن توغلق الذي أساء السيرة بسمرقند، فحدث الخلافُ بينهما فطلب إلياسُ من أبيه أن يَقتُلَ تيمورلنك الذي هرب بعد أن وصله الخبَرُ وجمع حوله الأنصارَ، وعاد فحارب المغولَ وصادف ذلك موتَ توغلق فانسحَبَ إلياس إلى تركستان ليتَسَلَّم المُلْكَ بعد أبيه، فترك ما وراء النهر فأصبَحَت كُلُّها في قَبضةِ تيمورلنك، واتخَذَ مِن سمرقند عاصمةً له."},{"id":3114,"title":"الغزو الغرناطي على الإسبان .","date":["العام الهجري :771","العام الميلادي :1369"],"text":"ما زال محمد الخامس الغني بالله يتابِعُ الغزو فزحف بقواتِه على مدينة قرمونه، واقتحم مدينةَ قشتالة، وكان محمَّد الخامس هذا قد استغَلَّ الأحداث الداخلية والفِتَن التي ثارت في قشتالة أيام ملكها بيدرو بعد وفاة أبيه الملك ألفونسو الحادي عشر، فكانت فترة قلاقل داخلية؛ حيث جرى بين بيدرو وأخيه هنري الذي استعان بالإنكليز وأما بيدرو فاستعان بالفرنسيين، فنشبت بينهما حروبٌ داخلية انتهت بقتل بيدرو وجلوس هنري على عرش الملك باسم هنري الثاني، فاستغل هذه الأحداثَ محمَّدٌ الخامس فقام بهذه الأعمال العسكريَّة."},{"id":3115,"title":"وفاة تاج الدين السبكي (الابن) الشافعي .","date":["العام الهجري :771","الشهر القمري : ذي الحجة","العام الميلادي :1370"],"text":"هو الإمامُ العالمُ الفقيه المحَدِّث النحوي الناظِمُ: تاج الدين أبو نصر عبد الوهاب ابن العلامة الفقيه قاضي القضاة تقي الدين علي بن عبد الكافي بن علي بن تمام بن يوسف بن موسى بن تمام الأنصاري السلمي السبكي الشافعي، قاضي قضاة دمشق بها، ولد بالقاهرة سنة 728. قال الصفدي: \"عُنِيَ تاج الدين بالرواية وسمع كثيرًا، وقرأ بنفسه على شيخنا شمس الدين الذهبي كثيرًا من مصنفاته وغيرها، وأفتى ودرَّس، ونظم الشعر وعمل الألغاز، وراسلني وراسلته، وبالجملة فعِلمُه كثيرٌ على سِنِّه\" جرت له مِحَنٌ فاتُّهِمَ بالكفر واستحلالِ الخَمرِ؛ قال ابن كثير: \" عُقِدَ مجلس بسبب قاضي القضاة تاج الدين السبكي، ولما كان يوم الاثنين الرابع والعشرين من ربيع الأول عُقِدَ مجلس حافل بدار السعادة بسَبَبِ ما رمي به قاضي القضاة تاج الدين الشافعي ابن قاضي القضاة تقي الدين السبكي، وكنت ممَّن طُلِب إليه، فحضرته فيمن حضر، وقد اجتمَع فيه القضاةُ الثلاثة، وخَلقٌ من المذاهب الأربعة، وآخَرون من غيرهم، بحضرة نائب الشام سيف الدين منكلي بغا، وكان قد كُتِبَ فيه محضران متعاكسانِ أحدهما له والآخر عليه، وفي الذي عليه خَطُّ القاضيين المالكي والحنبلي، وجماعةٍ آخرين، وفيه عظائِمُ وأشياء منكرة جدًّا ينبو السَّمعُ عن استماعه. وفي الآخَرِ خطوطُ جماعات من المذاهب بالثناء عليه، وفيه خَطِّي بأني ما رأيتُ فيه إلا خيًرا, وكثُرَ القول فيه وارتفعت الأصوات وكَثُر الجدال والمقال، وطال المجلِسُ، فأشار نائِبُ السلطنة بالصُّلحِ بينهم وبين قاضي القضاة تاج الدين، فأشار شيخ شرف الدين ابن قاضي الجبل وأشرت أنا أيضًا بذلك، فقُمْنا والأمر باقٍ على ما تقدم، ثم اجتَمَعْنا يوم الجمعة بعد العصر عند نائب السلطنةِ عن طلبه فتَراضَوا كيف يكونُ جواب الكتابات مع مطالعة نائب السلطنة، ففعل ذلك وسار البريدُ بذلك إلى الديار المصرية، ثم اجتمَعْنا أيضًا يوم الجمعةِ بعد الصلاة التاسِعَ عشر من ربيع الآخر بدار السعادة، وحضر القضاةُ الثلاثة وجماعة آخرون، واجتهد نائبُ السلطنة على الصلح بين القضاة وقاضي الشافعية وهو بمصر، فحصل خلافٌ وكلام طويل، ثم كان الأمرُ أن سكنت أنفُسُ جماعة منهم.\". لتاج الدين السبكي تصانيفُ، منها طبقات الشافعية الكبرى، وجمع الجوامع في أصول الفقه، والأشباه والنظائر، وشرح منهاج البيضاوي، وشرح مختصر ابن الحاجب، وكان درس بالعادلية والغزالية والأمينية والناصرية ودار الحديث الأشرفية والشامية البرانية، وباشر قضاءَ دمشقَ أربَعَ مَرَّات، وخطَبَ بالجامِعِ الأموي. توفِّيَ في عصر يوم الثلاثاء السابع من ذي الحجَّة مُتأثِّرًا بالطاعون، ودفِنَ بسفح قاسيون، عن أربعٍ وأربعين سنة."},{"id":3116,"title":"الفرنج يطلبون الصلح .","date":["العام الهجري :772","الشهر القمري : صفر","العام الميلادي :1370"],"text":"في أوَّلِ صَفَر قَدِمَت رُسُل الفِرنجَ لطَلَبِ الصلح، فحلَفوا على ألَّا يَغدِروا ولا يحزنوا، وخُلِع عليهم، وسافروا ومعهم من يُحلِّفُ مَلِكَهم، وأُخِذَت منهم رهائن بالقلعة، ثم في جمادى الأولى عادت رسلُ الفرنج ومعهم عِدَّة مِمَّن أسروهم من المسلمين نحو المائة، ثمَّ في جمادى الآخرة بعث الفرنج من بقي من أسرى المسلمين ببلادهم، وتم الصلحُ، وفُتِحَت كنيسةُ القيامة بالقدس."},{"id":3117,"title":"خلع الملك الحفصي أبي البقاء خالد وتولي ابن عمه المستنصر بالله .","date":["العام الهجري :772","الشهر القمري : ربيع الآخر","العام الميلادي :1370"],"text":"خُلِعَ أبو البقاء خالد بن إبراهيم بن أبي بكر متمَلِّك تونس، بعد إقامته في المُلْك سنة وتسعة أشهر تنقُصُ يومين، وهو الخامس عشر من ملوك الحفصيين بتونس، وكان صبيًّا والأمر بيد الحاجِبِ ابن المالقي، وقام بعدَه ابنُ عَمِّه أبو العباس أحمد بن محمد بن أبي بكر بن يحيى بن إبراهيم، وقد كان هذا أميرَ قُسنطينة وبجاية، فلما استطاع الزحفَ على تونس قَتَل الحاجي ابن المالقي وفَرَّ خالد المخلوع، لكِنَّه قبض عليه ونفِيَ إلى الغرب لكنَّه غَرِقَ في البحر، فتملك أبو العباس هذا وتلَقَّب بالمستنصر بالله في يوم السبت ثامن عشر ربيع الآخر."},{"id":3118,"title":"وفاة جمال الدين الإسنوي صاحب طبقات الشافعية .","date":["العام الهجري :772","الشهر القمري : جمادى الأولى","العام الميلادي :1370"],"text":"هو الشَّيخُ جمال الدين أبو محمد عبد الرحيم بن الحسن بن علي بن عمر بن علي بن إبراهيم الأرموي الإسنوي نزيلُ القاهرة، ولِدَ في العشر الأواخر من ذي الحجة سنة 704. وقدِمَ القاهرة سنة 721 وحَفِظَ التنبيه وسَمِعَ الحديث من الدبوسي والصابوني وغيرهما، وحدث بالقليل، وأخذ العلمَ عن الجلال القزويني، والقونوي، وغيرهما، وأخذ العربية عن أبى حيَّان، ثم لازم بعد ذلك التَّدريسَ والتصنيفَ, فدرَّسَ بالملكية والأقبغاوية والفاضلية، ودرس التفسير بالجامع الطولوني, وصنف التصانيف المفيدة منها: \"المهمات والتنقيح فيما يرد على الصحيح\" و\"الهداية إلى أوهام الكفاية\" و\"طبقات الشافعية\" وغير ذلك. كان فقيهًا ماهرًا، ومعلمًا ناصحًا، ومفيدًا صالحًا، مع البر والدين والتودد والتواضع، وكان يقَرِّبُ الضعيف المستهان به من طَلَبتِه، ويحرص على إيصال الفائدةِ إلى البليد، وله مثابرةٌ على إيصال البر والخير إلى كل محتاجٍ، مع فصاحةِ عبارة وحلاوة محاضرةٍ ومروءة بالغةٍ، كان بحرًا في الفروع والأصول محقِّقًا لِما يقول من النقول، تخرج به الفضلاءُ، وانتفع به العلماء, وقد ولِيَ وكالة بيت المال والحِسبة، ثم عزل نفسه عن الحِسبةِ؛ لكلام وقع بينه وبين الوزير في سنة 762 ثم عزَلَ نَفسَه من الوكالة في سنة 766، وكانت وفاتُه ليلة الأحد ثامن عشر من جمادى الأولى من هذه السنةِ."},{"id":3119,"title":"تآمر الأمير ساوجي ابن السلطان مراد الأول على أبيه .","date":["العام الهجري :773","العام الميلادي :1371"],"text":"تآمَرَ ساوجي ابنُ السلطان مرادِ الأوَّلِ مع الأمير أندرونيقوس ابنِ الإمبراطور البيزنطي يوانيس، وسارا على رأسِ جيشٍ مِن البيزنطيين وبعضِ المخدوعين من الجنودِ العثمانيين؛ لمحاربةِ جيش السلطانِ مراد, فكانت نتيجةُ المعركة هزيمةَ المتآمرين ووقوعَ الأمير ساوجي في الأسْر، فأصرَّ والده السلطان مراد أن يَعرِضَ أمره على علماء الشريعة وقضاتها، فحكموا عليه بعقوبة الموتِ جزاءَ خروجه على طاعةِ ولي الأمر وموالاته للأعداء، ومشاركته الفعلية إلى جانبهم في قتال المسلمين، وحين أشفق رجالُ الدولة أن يُفجَع السلطان مراد بولده ساوجي، رجَوه أن يعفوَ عنه، ويكتفيَ بنفيه، فما كان من السلطان مراد الا أن أصرَّ على تنفيذِ حُكم الشريعة في ولده."},{"id":3120,"title":"وفاة المهدي علي بن محمد إمام الزيدية باليمن .","date":["العام الهجري :773","العام الميلادي :1371"],"text":"هو المهديُّ لدينِ الله علي بن محمد بن علي بن منصور من سلالة الناصر بن الهادي إلى الحَقِّ من أئمة الزيدية في اليمن، ولِدَ في هجرة من قرى إلهان, وبويع بالإمامة بعد وفاة المؤيَّدِ بالله يحيى بن حمزة، افتَتَح صنعاء واستولى على صَعدة وذمار، وقاتل الباطنيَّةَ وخَرَّبَ قُراهم وأمَّن الطُّرُقات وأزال سَبعَ عَشرة إمارةً مستقِلَّةً، وكان فقيهًا مجتهدًا، وله تصانيفُ ومختصرات ورسائل. أُصيبَ بالفالج أو بعِلَّة في دماغه, وتوفِّيَ بذمار ونُقِلَ إلى صعدة، فتولى ابنه محمد الناصر شؤونَ الإمامة."},{"id":3121,"title":"انتصار السلطان العثماني مراد الأول على الصرب في (جرمن) .","date":["العام الهجري :773","العام الميلادي :1371"],"text":"أرسلَ سُلطانُ العُثمانيين مراد الأول جيشًا لاجتياح البلقان، فالتقى بالصرب في تشيرنوفو على نهر مارتيزا، فحدثت بينهم معركةٌ قوية، انهزم فيها أمراءُ الصِّرب، وكان من نتيجةِ هذه المعركة اعترافُ أمراء البلغار ومقدونيا والإمبراطورية البيزنطية بسيادةِ السَّلطنةِ العُثمانية في البُلقان."},{"id":3122,"title":"السلطان الأشرف يرسم للأشراف بعلامة خضراء ليعرفوا بها .","date":["العام الهجري :773","الشهر القمري : شعبان","العام الميلادي :1372"],"text":"رسم السلطانُ المَلِكُ الأشرَفُ أنَّ الأشرافَ بالديارِ المِصريَّة والبلاد الشامية كُلَّهم يَسِمونَ عمائِمَهم بعلامةٍ خَضراءَ بارزةٍ للخاصَّةِ والعامَّةِ؛ إجلالًا لحَقِّهم وتعظيمًا لقَدْرِهم؛ ليُقابَلوا بالقَبولِ والإقبالِ، ويَمتازوا عن غَيرِهم من المُسلِمينَ، فوقع ذلك ولَبِسَ الأشرافُ العمائِمَ الخُضرَ، فقال الأديبُ شَمسُ الدين محمد بن إبراهيم الشهير بالمزين، في هذا المعنى:أطرافُ تيجانٍ أتَت مِن سُندُسٍ خُضرٍ كأعلامٍ على الأشرافِوالأشرفُ السُّلطانُ خَصَّصَهم بهاشرفًا لنَعرِفَهم من الأطرافِ وقال في ذلك الأديبُ شمس الدين محمد بن أحمد بن جابر الأندلسي: جعلوا لأبناءِ الرَّسولِ علامةًإنَّ العلامةَ شأنُ مَن لم يُشهَرِنورُ النبُوَّةِ في كريمِ وُجوهِهميُغني الشَّريفَ عن الطرازِ الأخضَرِ"},{"id":3123,"title":"وفاة الإمام الحافظ ابن كثير .","date":["العام الهجري :774","الشهر القمري : شعبان","العام الميلادي :1373"],"text":"هو المُحَدِّث الإمامُ الفقيهُ الحافِظُ الأوحَدُ البارعُ: عماد الدين أبو الفداء إسماعيلُ بن الخطيب شهاب الدين أبي حفص عمر بن كثير القرشي البصروي ثم الدمشقي الشافعي، صاحِبُ التفسيرِ والتاريخِ، صِهْرُ الشيخِ أبي الحجَّاج المِزِّي، مَولِدُه بقريةٍ شرقيَّ بُصرى من أعمال دمشق في سنة 701 كان أبوه خطيبًا بها، ثم انتقل إلى دمشق في سنة 706. تفقه ابن كثير بالشيخ برهان الدين الفزاري وغيره، وصاهر الحافِظَ المزِّيَّ فأكثَرَ عنه، وأفتى ودرَّس، وناظر وبرع في الفقه والتفسير والنحو، وأمعَنَ النظر في الرجال والعِلَل، وولي مشيخةَ أم الصالح والتنكزية بعد الذهبي، ذكره الذهبيُّ في المعجم المختص فقال: \"هو فقيهٌ مُتقِنٌ، ومُحَدِّث مُحَقِّق، ومفَسِّر نقَّاد، وله تصانيفُ مُفيدة يدري الفِقهَ ويَفهَمُ العربيَّة والأصول، ويحفَظُ جملةً صالحة من المتونِ والتفسيرِ والرِّجال وأحوالهم، سَمِعَ مني، وله حِفظٌ ومَعرِفة \" كان قدوةَ العُلَماء والحُفَّاظ، وعُمدةَ أهلِ المعاني والألفاظ، وسَمِعَ وجَمَع، وصنف ودرَّس، وحدَّث وألَّف، وكان له اطلاعٌ عظيم في الحديث والتفسير والتاريخ، واشتهَرَ بالضبط والتحرير، وقد تتلمذ على شيخِ الإسلامِ ابنِ تيميَّة، وكان على عقيدتِه؛ قال ابنُ حجر: \"وقع بينَ ابنِ كثير وبين إبراهيم بن محمد بن أبي بكر بن أيوب بن قَيِّم الجوزية مُنازعةٌ في تدريس النَّاسِ، فقال له ابنُ كثيرٍ: أنت تكرهُني لأنَّني أشعريٌّ! فقال له: لو كان من رأسِك إلى قَدَمِك شعرٌ ما صَدَّقَك النَّاسُ في قَولِك أنَّك أشعريٌّ، وشَيخُك ابنُ تيميَّة!!\" انتهى إليه علمُ التاريخ والحديث والتفسير، وله مُصنَّفات عديدة مفيدة، ومن مصنفاته: تفسير القرآن الكريم، وكتاب طبقات الفقهاء، ومناقب الإمام الشافعي رضي الله عنه، والتاريخ المسمى بالبداية والنهاية، وخرج أحاديث مختصر ابن الحاجب، وكتب على البخاري ولم يكمله، وله التكميل في الجرح والتعديل، ومعرفة الثقات والضعفاء والمجاهيل، جمع فيه بين تهذيبِ الكمالِ للمِزِّي، وميزانِ الاعتدال لشيخهِ الذهبي، مع زياداتٍ وتحرير عليهما في الجرح والتعديل. قال ابن حجر: \" ولازم المزِّي وقرأ عليه تهذيب الكمال، وصاهره على ابنتِه، وأخذ عن ابن تيميَّةَ، ففُتِنَ بحُبِّه وامتُحِنَ لِسَبَبِه، وكان كثير الاستحضارِ، حَسَن المُفاكَهة، سارت تصانيفُه في البلاد في حياتِه، وانتفع بها الناسُ بعد وفاته \". توفي في يوم الخميس سادس عشرين شعبان، وكانت جنازته حافلة مشهودة، ودُفِنَ بوصية منه في تربة شيخِ الاسلام ابنِ تيميَّة بمقبرة للصوفيَّة، خارج باب النصر من دمشق. وهو غير عماد الدين أبو الفداء إسماعيل بن محمد بن بردس البعلبكي الحنبلي المتوفى سنة 786."},{"id":3124,"title":"اختلاف السلطان الأشرف مع زوج أمه بسبب التركة .","date":["العام الهجري :775","الشهر القمري : محرم","العام الميلادي :1373"],"text":"وقع بين المَلِك الأشرَفِ وبين زوج أمِّه ألجاي اليوسفي كلامٌ مِن أجل التَّرِكة المتعَلِّقة بخوند-السيدة- بركة والدة الأشرف, وكان ذلك يومَ الثلاثاء سادس المحرَّم مِن هذه السنة، وكَثُرَ الكلام بين السلطان وبين ألجاي اليوسفي، حتى غضب ألجاي، وخرج عن طاعةِ المَلِك الأشرف، ولبس هو ومماليكُه آلة الحرب، ولَبِسَت مماليلك السلطان أيضًا، وركِبَ السلطان بمن معه مِن أمرائه وخاصكيته، وباتوا الليلةَ لابسين السلاحَ إلى الصَّباحِ، فلمَّا كان نهارُ الأربعاء سابِعَ المحرم كانت الوقعةُ بينهما، فتواقعوا إحدى عشرة مرة، وعَظُمَ القتال بينهما حتى كانت الوقعةُ الحادية عشرة انكسر فيها ألجاي اليوسفي وانهزم إلى بركة الحبش، ثم تراجع أمرُه وعاد بمن معه مِن على الجبل الأحمر إلى قُبَّة النصر، فطلبه السلطانُ الملك الأشرف فأبى، فأرسل إليه خِلعةً بنيابة حماة فقال: أنا أروحُ بشرط أن يكونَ كُلُّ ما أملِكُه وجميعُ مماليكي معي، فأبى السلطانُ ذلك، وباتوا تلك الليلة، فهرب جماعةٌ من مماليك ألجاي في الليل وجاؤوا إلى المَلِك الأشرف، فلما كان صباحُ يوم الخميس ثامن المحرم، أرسل السلطان الأمراء والخاصكيَّة ومماليك أولادِه وبَعضَ المماليك السلطانية إلى قُبَّة النصر إلى حيث ألجاي، فلما رآهم ألجاي هرب، فساقوا خلْفَه إلى الخرقانيَّة، فلما رأى ألجاي أنه مُدرَكٌ رمى بنَفسِه وفرسه إلى البَحرِ؛ ظنًّا أنه يُعَدِّي به إلى ذلك البَرِّ، وكان ألجاي عوَّامًا، فثَقُل عليه لِبسُه وقماشه، فغرق في البَحرِ وخرج فرَسُه، وبلغ الخبَرُ السلطانَ الملك الأشرف فشَقَّ عليه موتُه وتأسَّفَ عليه، ثمَّ أمَرَ بإخراجه من النيل، فنزل الغوَّاصون وطَلَعوا به وأحضروه إلى القلعة في يوم الجمعة تاسع المحرم في تابوت وتحته لبادٌ أحمر، فغُسِّلَ وكُفِّن وصَلَّى عليه الشيخ جلال الدين التباني، ودفن في القبة التي أنشأها بمدرسته برأس سويقة العزي خارج القاهرة."},{"id":3125,"title":"خلع صاحب فاس وبلاد المغرب السعيد محمد بن عبدالعزيز .","date":["العام الهجري :775","الشهر القمري : ذي الحجة","العام الميلادي :1374"],"text":"خُلِعَ صاحبُ فاس وبلاد المغرب السعيد محمد بن عبد العزيز أبي الحسن، ومَلَك بعده السُّلطانُ أبو العباس أحمد بن أبي سالم إبراهيم ابن أبي الحسن."},{"id":3126,"title":"وفاة الوزير لسان الدين الخطيب القرطبي .","date":["العام الهجري :776","العام الميلادي :1374"],"text":"هو الوزيرُ العلَّامة أبو عبد الله محمد بن عبد الله بن سعيد بن عبد الله بن سعيد بن علي بن أحمد السلماني, قرطبي الأصل, نزل سلفة طليطلة ثم لوشة ثم غرناطة، كان سلفة قديمًا يُعرَفون ببني وزير، ثم صاروا يُعرَفون ببني الخطيب نسبةً إلى سعيد جده الأعلى، وكان قد ولِيَ الخَطابة بها وتحَوَّل جَدُّه الأدنى سعيد إلى غرناطة. ولِدَ لسان الدين سنة 713 في لوشة ونشأ في غرناطة، كان عالِمًا بالتاريخ والفلسفة والرياضيات، والفقه والأصول والطب، فألَّفَ في كلِّ ذلك, فله الإحاطة في أخبار غرناطة، وتاريخ ملوك غرناطة، ورسالة في الموسيقى، والحلل المرقومة في اللمع المنظومة، وهي منظومة في أصول الفقه، وله مؤلَّف في الطب ضخم، وعلاج السموم، وكتاب البيطرة. أخذ الطبَّ والمنطق والحساب عن يحيى بن هذيل الفيلسوف, وبرز في الطبِّ وتولَّع بالشعر، فنبغ فيه وترسل ففاق أقرانه، واتصل بالسلطان أبي الحجاج يوسف بن أبي الوليد بن نصر بن الأحمر فمدحه وتقرَّب منه واستكتبه من تحت يد أبي الحسن بن الجباب إلى أن مات أبو الحسَنِ، استقل بكتابة السر وأضاف إليه رسوم الوزارة واستعمله في السفارة إلى الملوك، واستنابه في جميع ما يملِكُه، فلما قُتِل أبو الحجاج سنة 755 وقام ابنُه محمد استمَرَّ لسان الدين الخطيب على وزارته، ثم أرسله إلى أبي عنان المريني بفاس ليستنجِدَه فمدحه فاهتزَّ له وبالغ في إكرامه، فلما خُلِعَ محمد وتغلب أخوه إسماعيل على السلطنة قُبِضَ على الخطيب بعد أن أمَّنَه واستؤصلت نِعمَتُه ولم يكن بالأندلس مِثلُها، فبيع جميعُ ما يَملِكُ, وشَمِلَ الطَّلَبُ جميعَ الأقارب واستمر مسجونًا إلى أن وردت شفاعةُ أبي سالم ابن أبي عنان فيه، ثم شفع له أبو سالم مرةً ثانية فرُدَّت عليه ضِياعُه بغرناطة وقُلِّدَ ما وراء باب السلطان، فباشره مقتصرًا على الكفاية راضيًا به هاجرًا للزُّخرف، صادِعًا بالحق في أسواق الباطل, وعَمَّر حينئذ زاوية ومدرسة وصَلَحت أمور سلطانه على يَدِه، فلم يزل في ذلك إلى أن وقع بينه وبين عثمان بن يحيى بن عمر شيخِ الغُزاة منافرةٌ أدت إلى نفي عُثمان سنة 764 فظَنَّ لسانُ الدين الخطيب أن الوقت صفا له وأقبل سلطانُه على اللهوِ، وانفرد هو بتدبير المملكة، فكَثُرت القالةُ فيه من الحَسَدة واستشعر في آخِرِ الأمر أنهم سَعَوا به, وخَشِيَ على نفسه, فأخذ في التحَيُّل في الخلاصِ، وراسل أبا سالم صاحب فاس في اللحاق به, فدخل مدينة فاس سنة 73 فتلقاه أبو سالم وبالغ في إكرامه وأجرى له الرواتِبَ فاشترى بها ضياعًا وبساتين، فبلغ ذلك أعداءه بالأندلس فسَعَوا به عند سلطانه حتى أذِنَ لهم في الدعوى عليه بمجلِسِ الحكم بكلماتٍ كانت تصدُرُ منه وتُنسَبُ إليه وأثبتوا ذلك وسألوه الحُكمَ به فحُكِمَ بزندقته وإراقةِ دَمِه، وأرسلوا صورة المكتوب إلى فاس، فامتنع أبو سالم فقال: هلا أثبتم ذلك عليه وهو عندكم، فأمَّا ما دام عندي فلا يُوصَلُ إليه، فاستمر على حالته بفاس إلى أن مات أبو سالم فلما تسلطَنَ بها أبو العباس بعده أغراه به بعضُ من كان يعادي الخطيبَ، فلم يزل إلى أن قُبِضَ عليه وحوكم فعَزَّرَه القاضي بالكلامِ ثم امتُحِنَ وعُذِّب، فسُجِنَ وقُتِلَ داخِلَ سِجنِه خَنقًا أوائلَ هذه السنة."},{"id":3127,"title":"وفاة أويس بهادر خان متملك توريز وبغداد .","date":["العام الهجري :776","العام الميلادي :1374"],"text":"هو أُوَيس بهادر خان ابن الشيخ الحسن الكبير بن حسين بن أقبغا بن أيلكان المغولي ثم التبريزي، سلطان بغداد وتوريز، استقَرَّ في سلطنة بغداد بعد سنة 760. خطب بمكَّة للخان أويس بعد أن وصلت منه قناديلُ حَسَنة للكعبة، وهديةٌ طائلة لأمير مكة عجلان، واستمرت الخُطبة له بمكَّة فترة من الزمن، مات عن نيِّف وثلاثين سنة، منها في السَّلطنة تسع عشرة سنة، وكان قد اعتزل قبلَ مَوتِه، وأقام عِوَضَه في المملكة ابنَه الشيخ حسينًا؛ لمنام رآه نُعِيَت إليه نفسُه، وعُيِّنَ له يوم موته، فتخلى عن الملك، وأقبل يتعَبَّدُ، فمات كما ذُكِرَ له في نَومِه!!"},{"id":3128,"title":"وباء وغلاء عام في مصر وهلاك الكثير من الناس بسببه .","date":["العام الهجري :776","الشهر القمري : جمادى الآخرة","العام الميلادي :1374"],"text":"ابتدأ الوباءُ في النَّاسِ في القاهرة ومِصرَ في نصف جمادى الآخر، وكَثُر مَوتُ الفقراء والمساكين بالجوع، وقد توقَّفَت أحوال الناس من قِلَّة المكاسب؛ لشِدَّة الغلاء وعَدَمِ وجودِ ما يُقتاتُ به، وشَحَّ الأغنياءُ وقَلَّت رَحمتُهم، فمن كان يكتَسِبُ في اليوم درهمًا يقومُ بحالِه ويَفضُلُ له منه شيء، صار الدِّرهَمُ لا يجدي شيئًا، فمات ومات أمثالُه من الأُجَراء والعُمَّال والصنَّاع والفلاحين والسُّؤَّال من الفقراء، وفي شَهرَي رجب وشعبان: اشتَدَّ الغلاء، وشَفَع الموت في الفُقَراءِ مِن شِدَّة البَردِ والجوعِ والعُري، وهم يَستغيثونَ فلا يُغاثُونَ، وأكَلَ أكثَرُ النَّاسِ خُبزَ الفولِ والنخال، عجزًا عن خبزِ القمح، وكَثُرَ الخَطفُ من أيدي النَّاسِ، ورُمِيَ طينٌ بالسجنِ لعمارة حائطٍ به، فأكله المسجونونَ مِن شِدَّةِ جُوعِهم، وعزَّ وجود الدوابِّ لِمَوتها جوعًا، وفي رابِع عشرين شعبان انتدب الأميرُ منجك نائب السلطان لتفرقةِ الفُقَراء على الأمراء وغيرهم، فجمع أهلَ الحاجة والمَسكَنة، وبعث إلى كلِّ أميرٍ مِن أمراء الألوف مائةَ فقير، وإلى مَن عدا أمراء الألوف على قَدرِ حالِه، وفَرَّق على الدواوين والتجَّار وأرباب الأموال كل واحدٍ عددًا من الفقراءِ، ثم نودي في القاهرة ومصر بألا يتصَدَّقَ أحَدٌ على حرفوش، وأيُّ حرفوش شَحَذ صُلِبَ، فآوى كلُّ أحدٍ فُقراءَه في مكانٍ، وقام لهم من الغِذاء بما يمُدُّ رَمَقَهم على قَدرِ هِمَّتِه وسَماح نفسِه، ومنعهم من التَّطوافِ لسُؤالِ النَّاسِ، فخَفَّت تلك الشناعات التي كانت بين النَّاسِ إلَّا أن الموات عَظُم، حتى كان يموتُ في كُلِّ يوم من الطُّرَحاء على الطرقات ما يزيدُ على خمسمائة نفر، ويُطلَقُ من ديوان المواريث ما يُنيفُ على مائتي نفس، وتزايَدَ في شهر رمضان مَرَضُ الناس وموتهم، ونَفِدَت الأقوات، واشتَدَّ الأمر، فبلغت عِدَّةُ مَن يرد اسمُه للديوان في كلِّ يوم خمسمائة، وبلغت عِدَّةُ الطرحاء زيادةً على خمسمائة طريح، فقام بمواراةِ الطُّرَحاء الأميرُ ناصر الدين محمد بن الأمير أقبغا آص، والأمير سودن الشيخوني، وغيرهما، وكان من أتى بميِّتٍ طريح أعطَوه درهمًا، فأتاهم الناسُ بالأموات، فقاموا بتغسيلِهم وتكفينِهم ودَفْنِهم- أحسَنَ قيامٍ، بعد ما شاهد النَّاسُ الكلابَ تأكل الموتى من الطُّرَحاء، فلما فَنِيَ مُعظَمُ الفقراء، وخَلَت دورٌ كثيرة خارج القاهرة ومصر لِمَوت أهلها، فَشَت الأمراضُ مِن أُخرَيات شهر رمضان في الأغنياءِ، ووقع الموتُ فيهم، فازداد سِعرُ الأدوية، واشتَدَّ الأمر في شوَّال إلى الغاية، وفي أوَّلِ ذي القعدة وصَلَت تراويج القمح الجديد، فانحَلَّ السِّعرُ، ثم تناقَصَت الأسعارُ."},{"id":3129,"title":"فتح سيس وإنهاء حكم الأرمن عليها .","date":["العام الهجري :776","الشهر القمري : ذي القعدة","العام الميلادي :1375"],"text":"توجَّه الأميرُ بيدمر نائِبُ الشام في تاسع عشر من ذي القعدة بعساكِرِ حَلَب إلى سيس، وهي كرسي الأرمن فنازلها، وحصر التكفور متمَلِّكَها مدةَ شهرين حتى طلب الأمانَ؛ مِن فَناءِ أزوِدَتِهم، وعَجْزِهم عن العسكر، فتسَلَّمَ الأمير أشَقتمُر قلعَتَها، وأعلن في مدينةِ سيس بكلمة التوحيد، ورتَّبَ بها عسكرًا، وأخذ التكفورَ وأمراءَه، من أجناد وعاد إلى حلب، وجَهَّزَهم إلى القاهرة، فبعث السلطانُ الأميرَ يعقوب شاه لنيابة سيس، وأزال الله منها دولة الأرمن عُبَّاد الصليب، وقال الأدباء في ذلك شعرًا كثيرا. وفي العشرين منه سقط الطائِرُ بالبشارة بفَتحِ سيس بعث به الأميرُ بيدمر نائب الشام، ثم قَدِمَ من الغد البريد من النوَّاب بذلك، فدُقَّت البشائر بقلعة الجبل ثلاثة أيامٍ بمِصرَ، وحُمِلَ إلى الأمير أشَقتمُر المارديني نائِبِ حلب تشريفٌ جليل."},{"id":3130,"title":"غلاء ووباء عظيم في الشام .","date":["العام الهجري :777","العام الميلادي :1375"],"text":"وقعَ غلاء الأسعار بدمشق حتى أكلت النَّاسُ المَيتاتِ والكلابَ والقِطَط، ومات خلقٌ كثير من المساكين، وانكشف عِدَّةٌ من الأغنياء، وعَمَّ الغلاء ببلاد الشام كلِّها، حتى أُكِلَت القطط وبِيعَت الأولادُ بحَلَب وأعمالِها."},{"id":3131,"title":"وفاة أمير مكة الشريف عجلان بن رميثة .","date":["العام الهجري :777","الشهر القمري : جمادى الأولى","العام الميلادي :1375"],"text":"هو أميرُ مَكَّة الشريفُ عَجلان بن رُمَيثة بن أبي نُمَي محمد بن أبي سعد علي بن الحسن بن قتادة بن إدريس بن مطاعن بن عبد الكريم بن موسى بن عيسى بن سليمان بن عبد الله بن موسى الجور بن عبد الله الكامل بن الحسن المثنى بن الحسن ابن أمير المؤمنين علي بن أبي طالب، وكان قبل موته نَزَل لوَلَدِه الشريف أحمد بن عجلان عن نِصفِ إمرةِ مَكَّة التي كانت بيده؛ فإنه كان قبل ذلك نزَل له عن النصفِ الأوَّلِ قديمًا، وكان وَلِيَ إمرةَ مَكَّة غير مرة نحو ثلاثين سنة، مستقِلًّا بها مدة، وشريكًا لأخيه ثُقبة مُدَّة، وشريكًا لابنه أحمد مُدَّة، وكانت وفاته في ليلة الاثنين الحادي عشر من شهر جمادى الأولى ودُفِنَ بالمُعَلَّاة وقد قارب السبعين سنة من العمر، وكان ذا عَقلٍ ودَهاء ومعرفة بالأمور وسياسةٍ حَسَنة، وكان بخلافِ آبائه وأقاربه؛ يحِبُّ أهل السنة ويَنصُرُهم على الشيعة، وربما كان يُذكَرُ أنَّه شافعيُّ المذهَب."},{"id":3132,"title":"وفاة الملك المظفر فخر الدين داود صاحب ماردين وتولى بعده ابنه .","date":["العام الهجري :778","العام الميلادي :1376"],"text":"هو السلطانُ المَلِكُ المظَفَّر فخر الدين داود ابن الملك الصالح صالح ابن الملك المنصور غازي بن ألبي بن تمرتاش بن إيل غازي بن أرتق الأرتقي، صاحِبُ ماردين وابنُ صاحبها بماردين، وكان الملك المظفَّر هذا وَلِيَ مُلكَ ماردين بعد ابن أخيه الملك الصالح محمود الذي أقام في سلطنة ماردين أربعة أشهر عوضًا عن والده الملك المنصور أحمد ابن الملك الصالح صالح، وخُلِعَ الملك الصالح محمود، وتسلطن الملِكُ المظفر، فأظهر العدلَ واقتفى أثر والده الملك الصالح في الإحسان إلى الرعية وإصلاح الأمور إلى أن مات، توفِّيَ في هذه السنة بعد أن حكمها نحو عشرين سنة، وتولى سلطنةَ ماردين من بعدِه ابنُه الملك الظاهر مجد الدين عيسى."},{"id":3133,"title":"وفاة الملك الأفضل عباس صاحب اليمن وتولي ابنه إسماعيل .","date":["العام الهجري :778","الشهر القمري : شعبان","العام الميلادي :1377"],"text":"هو السُّلطانُ المَلِك الأفضل عباسُ ابن الملك المجاهد علي ابن الملك المؤيد داود ابن الملك المظفر يوسف بن عمر بن علي بن رسول التركماني الأصل، اليمني صاحب اليمن وابنُ صاحِبِها، ولي الأفضَلُ السلطنة بعد موت أبيه المجاهد في شهر جمادى الأولى سنة 764، ولما ولي اليمَنَ خرج في أيامِه ابنُ ميكائيل فوقع له معه وقائِعُ، حتى أباده الأفضَلُ وزالت دولةُ ابن ميكائيل في أيامه، وكان الأفضَلُ شجاعًا مهابًا كريمًا، وله إلمامٌ بالعلوم والفضائل، ومشاركةٌ جيدة في عِدَّة علوم وتصانيف منها: كتاب العطايا السَّنِية في ذكر أعيان اليمنية، وكتاب نزهة العيون في تاريخ طوائف القرون، ومختصر تاريخ ابن خَلِّكان، وكتاب بغية ذوي الهمم في أنساب العرب والعجم، وكتاب آخر في الألغاز الفقهية، وغير ذلك، وكان بنى مدرسةً عظيمة بتعز، وله أيضًا بمكة مدرسة معروفة به بالصفا، وقيل: إن هذه التصانيف المذكورة إنما هي لقاضي تعز رضي الدين أبي بكر بن محمد بن يوسف الجرائي الصبري الناشري، عَمِلَها على لسان الأفضَلِ. توفي في شعبان، وتسَلْطَنَ بعده ولَدُه السلطان الملك الأشرفُ إسماعيل."},{"id":3134,"title":"اغتيال السلطان الأشرف شعبان وتولية ابنه علي .","date":["العام الهجري :778","الشهر القمري : ذي القعدة","العام الميلادي :1377"],"text":"هو السُّلطانُ الأشرف شعبان بن حسين الناصر بن المنصور قلاوون. بويِعَ للمَلِكِ الأشرف شعبان بعد عزل الملك المنصور، وله من العُمُرِ قَريبُ العشرين. كان الملِكُ الأشرف شعبان قد توعَّكَ، ومع ذلك أصر بالسَّفَرِ إلى الحج هذا العام وسافر وهو متوَعِّك، فلما كان يوم السبت ثالث ذي القعدة اتَّفق طشتمر اللفاف، وقرطاي الطازي، وأسندمر الصرغتمشي، وأينبك البحري، وجماعة من المماليك السلطانية، وجماعة من مماليك الأسياد أولادِ السلطان الملك الأشرف، وجماعةٌ من مماليك الأمراء المسافرين صحبة السلطان الملك الأشرف، ولَبِسوا السلاح، واتَّفَق معهم من بالأطباق من المماليك السلطانية، وهجم الجميعُ على القلعة، فدقُّوا الباب وقالوا: أعطونا سيدي أمير علي (هو ابنُ السلطان الأشرف) فقال لهم اللالا: مَن هو كبيرُكم حتى نسَلِّمَ لهم سيدي عليًّا وأبى أن يسَلِّمَهم سيدي عليًّا، وكثُرَ الكلام بينهم ومثقال الزمام يُصَمِّمُ على منع تسليم الأمير علي لهم، فقالوا له: السلطان الملك الأشرف مات، ونريد أن نُسلطِنَ وَلَدَه أمير علي، فلم يلتَفِتْ مثقال إلى كلامهم، فلما عَلِمَ المماليك ذلك، طلعوا جميعًا وكَسَروا شباك الزمام المطِلَّ على باب الساعات، ودخلوا منه ونهبوا بيتَ الزمام وقماشه، ثم نزلوا إلى رحبة باب الستارة ومسكوا مثقالًا الزَّمَّام وجلبان اللالا وفتحوا البابَ، فدخلت بقيَّتُهم وقالوا: أخرِجوا الأمير علي، حتى نُسلطِنَه؛ فإنَّ أباه توفِّيَ إلى رحمة الله تعالى فدخل الزمام على رَغمِ أنفه، وأخرج لهم الأميرَ عليًّا، فأُقعِدَ في باب الستارة، ثم أُحضِرَ الأمير أيدمر الشمسي فبوسوه الأرض للأمير علي، ثم أركبوا الأميرَ علي على بعض خيولهم وتوجَّهوا به إلى الإيوان الكبير، وأرسلوا خلفَ الأمراء الذين بالقاهرة، فركبوا إلى سوق الخيلِ، وأبوا أن يَطلَعوا إلى القلعة، فأنزلوا الأميرَ علي إلى الإسطبل السلطاني حتى رآه الأمراءُ، فلما رأوه طلعوا وقَبَّلوا له الأرض وحلفوا له، غيرَ أن الأمير طشتمر الصالحي وبلاط السيفي ألجاي الكبير وحطط رأس نوبة النوب لم يوافِقوا ولا طلعوا، فنزل إليهم المماليك ومسكوهم وحَبَسوهم بالقصر، وعَقَدوا للأمير علي بالسلطنةِ ولَقَّبوه بالملك المنصور، ثم نادوا بالديار المصرية بالأمان والبَيعِ والشراء، بعد أن أخذوا خُطوطَ سائر الأمراء المقيمين بمصر، فأقاموا ذلك النهارَ، وأصبحوا يوم الأحد رابع ذي القعدة من سنة 778 وهم لابسون آلة الحرب، واقفون بسوق الخيل، يتكَلَّمون في إتمامِ أمْرِهم، وأمَّا المَلِكُ الأشرف فإنه رجع إلى مصر بسَبَبِ كَسرتِه من مماليكه بالعقبة، حيث طلب المماليكُ السلطانية العليق، فقيلَ لهم اصبروا إلى منزلة الأزلم، فغَضِبوا وامتنعوا من أكلِ السماط عصرَ يوم الأربعاء واتفقوا على الركوبِ، فلما كانت ليلة الخميس ركبوا على السلطانِ ورؤوسُهم الأمير طشتمر العلائي، ومبارك الطازي، وصراي تمر المحمدي، وقطلقتمر العلائي الطويل، وسائر مماليك الأسياد، وأكثر المماليك السلطانية، فلما بلغ السلطانَ أمرُهم ركب بأمرائه وخاصكيته وتواقعوا فانكسر السلطان وهرب هو ومن كان معه من الأمراء، وصار السلطان بهؤلاء إلى قبة النصر خارج القاهرة، ثم توجه السلطان ويلبغا الناصري إلى القاهرةِ ليختفيَ بها، فقُتل الأمراء الذين كانوا معه في الحال، وحَزُّوا رؤوسهم، وأتَوا بها إلى سوق الخيل، ففرح بذلك بقيَّةُ الأمراء الذين هم أصلُ الفتنة، وعلموا أن الأشرف قد زال مُلكُه، فتوجه السلطان الأشرف تلك الليلة من عند أستادار يلبغا الناصري إلى بيت آمنة زوجة المشتولي فاختفى عندها، فقلق عند ذلك الأمراءُ الذين أثاروا الفتنة وخافوا عاقبةَ ظهور الأشرف، وبينما هم في ذلك في آخر نهار الأحد يوم قُتِلَ الأمراء المذكورين بقبة النصر، وقبل أن يمضِيَ النهار، جاءت امرأةٌ إلى الأمراء وذَكَرَت لهم أن السلطان مختفٍ عند آمنة زوجة المشتولي في الجودرية-إحدى الحارات- فقام ألطنبغا من فوره ومعه جماعةٌ وكبسوا بيت آمنة، فهرب السلطانُ واختفى في بادهنج البيت- المنفذ الذي يجيء منه الريح- فطلعوا فوجدوه في البادهنج وعليه قماش النساء، فمسكوه وألبَسُوه عُدَّة الحرب، وأحضروه إلى قلعة الجبل، فتسَلَّمه الأمير أينبك البدري وخلا به، وأخذ يقَرِّرُه على الذخائر، فأخبره الملك الأشرف بها، وقيل: إن أينبك ضربه تحت رجليه عِدَّةَ عِصِيٍّ، ثم أصبحوا في يوم الاثنين وخَنَقوه، وتولى خَنْقَه جاركس شاد عمائر ألجاي اليوسفي، فأعطى جاركس إمرة عشرة واستقَرَّ شاد عمائر السلطان، ثم بعد خنق الملك الأشرف لم يدفنوه، بل أخذوه ووضعوه في قُفَّة وخيطوا عليها ورَمَوه في بئر، فأقام بها أيامًا إلى أن ظَهَرت رائحته، فاطلع عليه بعضُ خُدَّامه من الطواشية، ثم أخرجوه ودفنوه عند كيمان السيدة نفيسة، وذلك الخادِمُ يَتبَعُهم مِن بُعدٍ حتى عرف المكان، فلما دخل الليلُ أخذ جماعة من إخوته وخَدَمِه ونقلوه في تلك الليلة من موضع دفنه ودفنوه بتربة والدته خوند بركة بمدرستها التي بخط التبانة في قُبَّةٍ وحده، بعد أن غسلوه وكفَّنوه وصلوا عليه، وكانت مدة سلطنة الملك الأشرف أربع عشرة سنة وشهرين وعشرين يومًا، ومات وعمره أربع وعشرون سنة، فلما كان يوم الخميس ثامِنَ ذي القعدة وذلك بعد قتل الملك الأشرف شعبان بثلاثة أيام، اجتمع الأمراءُ القائمون بهذا الأمر بالقلعة، واستدعوا الخليفةَ ومن كان بمصر من القضاة ونوَّاب من هو غائب من القضاة بالقدس، وحضر الأميرُ آقتمر الصاحبي نائب السلطنة بالديار المصرية، وقعد الجميعُ بباب الآدر الشريفة من قلعة الجبل، وجدَّدوا البيعة بالسلطنة للملك المنصور علي ابن الأشرف شعبان بعد قَتْلِ أبيه، وقَبِلَ له البيعة آقتمر الصاحبي، ولَبَّسوه السوادَ؛ خِلعةَ السلطنة، وكان عمرُ السلطان الملك المنصور يوم تَسَلْطَنَ نحو سبع سنين تخمينًا."},{"id":3135,"title":"نواب الشام وأمراء مصر يعصون على أيبك البدري لسوء أفعاله .","date":["العام الهجري :779","الشهر القمري : ربيع الأول","العام الميلادي :1377"],"text":"بينما أيبك البدريُّ في أمْرِه ونَهْيِه بمصرَ، ورد عليه الخبَرُ بعصيان نوَّاب الشامِ، ففي الحال علَّق أيبك جاليش السفر في التاسع عشر من ربيع الأوَّل ورسم للعساكر بالتجهيز إلى سفر الشام وأسرع بالنفقةِ على العساكر وتجهَّزَ في أسرع وقت وخرج الجاليش من القاهرة إلى  الريدانية في السادس والعشرين من ربيع الأول، وهم خمسةٌ من أمراء الألوف ومائةُ مملوك من المماليك السلطانية، ومائةُ مملوك من مماليك الأتابك أيبك، وفي التاسِعِ والعشرين من ربيع الأول خرج طلَبُ السلطان الملك المنصور، ثم استقَلُّوا بالمسير قاصدينَ البلاد الشامية، وساروا حتى وصلوا بلبيس، ثم رجعوا على أعقابِهم بالعساكر إلى جهة الديار المصرية، وخبَرُ ذلك أن قطلوخجا أخا أيبك مُقَدَّم الجاليش بلغه أنَّ الجماعة الذين معه مخامِرون، وأنهم أرادوا أن يكبِسوا عليه، فاستقَصَّ الخبَرَ حتى تحققه، فرَكِبَ مِن وقته وساعته وهرب في الحال، وهو في ثلاثةِ أنفس، عائدًا إلى أخيه أيبك فاجتمع به وعَرَّفه الخبر، ففي الحال أخذ أيبك السلطانَ ورجع به إلى نحو القاهرة حتى وصلها في يوم الاثنين ثالث شهر ربيع الآخر، وطلع به إلى قلعةِ الجبل، وأنزل الأتابك أيبك السلطانَ المَلِكَ المنصور إلى الإسطبل السلطاني، وجاءه بعض أمراء من أصحابه، ثم أخذ أيبك في إصلاحِ أمْرِه، وبينما هو في فلك بلَغَه أنَّ الأمير قطلقتمر العلائي الطويل والأمير ألطنبغا السلطاني، وكانا رجَعا معه من بلبيس، ركبا بجماعَتِهما في نصف الليل، ومعهما عِدَّة من الأمراء وسائر المماليك السلطانية، وخرج الجميعُ إلى قبة النصر موافَقةً لِمن كان من الأمراءِ بالجاليش، فجهز أيبك الأمير قطلوخجا في مائتي مملوك لقتال هؤلاء، فخرج بهم قطلوخجا إلى قبة النصر، فتلقَّاه القوم وحملوا عليه، فانكسر ومُسِكَ، فلما بلغ أيبكَ ذلك، جهَّز الأمراء الذين كانوا بقلعة الجبل، وأرسلهم إلى قُبَّةِ النصر، هذا وقد ضعف أمر أيبك وخارت قواه؛ فإنه بلغه أنَّ جميع العساكر اتَّفَقَت على مخالفته، حتى إنَّه لم يعلم من هو القائِمُ بهذا الأمر لكثرةِ من خرج عليه، فلما رأى أمرَه في إدبار، ركب فَرَسَه ونزل من الإسطبل السلطاني من غير قتال، وهرب إلى ناحيةِ كيمان مصر، ولما استولت الأمراءُ على القلعة ألزموا واليَ القاهرة ومصر بإحضاره، فنُودِيَ عليه بالقاهرة ومصر، وهدِّدَ من أخفاه بأنواعِ النَّكال، فخاف كلُّ أحد على نفسه من تقريبه، فلم يجِدْ أيبك بدًّا من طلب الأمان من الأميرِ يلبغا الناصري فأمَّنَه بعد مدة، فطلع أيبك إليه، فحالَ وقَعَ بَصَرُ القوم عليه قبضوه، وأرسلوه مقَيَّدًا إلى سجن الإسكندرية، وكان ذلك آخِرَ العهد به، أما الأمراءُ فإنهم لما بلَغَهم هروب أيبك من قلعة الجبل رَكِبَ الجميع من قبة النصر وطلعوا إلى الإسطبلِ السلطاني من القلعة، وصار المتحدث فيهم قطلقتمر العلائي الطويل، وضرب رنكه على إسطبل شيخون بالرميلة تجاه باب السلسلة، وأقام ذلك اليومَ مُتحَدِّثًا، فأشار عليه مَن عنده من أصحابه أن يسلطنَ سلطانًا كبيرًا يرجِعُ الناس إلى أمْرِه ونهيه، فلم يفعَلْه وقال: حتى يأتيَ إخوانُنا- يعني الأمراء الذين كانوا بالجاليش مع قطلوبغا- ثم حضرت الأمراءُ الذين كانوا بالجاليش إلى الإسطبل السلطاني، وهم جمعٌ كبير ممن أنشأه أيبك وغيرُهم، وتكَلَّموا فيمن يكون إليه تدبيرُ الملك، واشتوروا في ذلك، فاختلفوا في الكلام، وظهر للقادمينَ الغَدرُ مِمَّن كان بالإسطبل السلطاني، فقبضوا على جماعة منهم وقَيَّدوا الجميع، وأُرسلوا إلى الإسكندرية صحبة جمال الدين عبد الله بن بكتمر الحاجب، واتفقوا على أن يكون المتكَلِّم في المملكة الأمير يلبغا الناصري، فصار هو المتحَدِّثَ في أحوال الملك، وسكن الإسطبلُ السلطاني، وأُرسِلَ بإحضار الأمير طشتمر العلائي الدوادار نائب الشام، ثمَّ في يوم الأحد تاسع شهر ربيع الآخر، لما تزايد الفَحصُ على أيبك حضر أيبك بنفسه إلى عند الأمير بلاط، فطلع به بلاط إلى يلبغا الناصري بعد أن أخذ له منه الأمانَ حَسَب ما تقدَّمَ ذِكرُه، ولم تطُلْ أيام يلبغا الناصري في التحدث، وظهر منه لِينُ جَنب، فاتفق برقوق وبركة- وهما حينذاك من أمراء الطبلخانات، لهما فيها دون الشهرين - مع جماعةٍ أُخَرَ وركبوا في سادس عشر شهر ربيع الآخر، وركبت معهم خشداشيتهم- زملاء المهنة- من المماليك اليلبغاوية، ومسكوا دمرداش اليوسفي، وتمرباي الحسني، وآقبغا آص الشيخوني، وقطلوبغا الشعباني، ودمرداش التمان تمري المعلم، وأسندمر العثماني، وأسنبغا تلكي، وقُيِّدوا وأرسلوا إلى سجن الإسكندرية فسُجِنوا بها، فصار برقوق العثماني هو متولي السَّلطنةِ، فسكن القصر وكان هذا بدايةَ التمَكُّن للماليك الشَّراكِسةِ."},{"id":3136,"title":"أيبك البدري أمير العساكر يخلع الخليفة المتوكل .","date":["العام الهجري :779","الشهر القمري : ربيع الأول","العام الميلادي :1377"],"text":"صار الأمرُ في المملكة لأيبك البدري وَحْدَه من غير منازع، وأخذ أيبك في المملكة وأعطى، وحكم بما اختاره وأراده، فمِن ذلك أنَّه في رابع شهر ربيع الأول رَسَم بنفي الخليفة المتوكِّل على الله إلى مدينة قوص، فخرج المتوكِّلُ على الله، ثم شُفِعَ فيه فعاد إلى بيته، ومن الغَدِ طَلَب أيبك نجم الدين زكريا بن إبراهيم ابن الخلفية الحاكمِ بأمر الله وخَلَع عليه واستقَرَّ به في الخلافة عِوَضًا عن المتوكل على الله من غير مبايعةٍ ولا خَلعِ المتوكِّلِ مِن الخلافةِ نَفسَه، ولُقِّبَ زكريا بالمعتصم بالله، ثم في العشرين من شهر ربيع الأول تكلَّم الأمراء مع أيبك فيما فعله مع الخليفةِ، ورَغَّبوه في إعادته، فطلبه وأخلع عليه على عادتِه بالخلافةِ، وعزل زكريَّا, ومن الناس من لم يُثبِتْ خلافة زكريا؛ فإنَّه لم يخلَع المتوكِّلُ نَفسَه من الخلافة حتى يبايَعَ زكريا!"},{"id":3137,"title":"وفاة الرحالة ابن بطوطة  .","date":["العام الهجري :779","الشهر القمري : رجب","العام الميلادي :1377"],"text":"هو أبو عبدِ الله محمَّدُ بن محمد بن عبد الله بن إبراهيم الطنجي اللواتي المغربي من أسرة بطوطة، وُلِدَ بطنجة سنة 703 اشتُهِرَ برحلته التي دامت ثمانية وعشرين سنة على ثلاثة رحلات: الأولى بدأها من طنجة سنة 725 طاف فيها المغرب إلى مصر، ثم مكة ثم العراق وإيران والمشرق، ثم بلاد الأناضول، ثم إلى الحجاز ثم مكة ثم إلى اليمن وبلاد الخليج العربي، ثم مصر والشام، ثم القسطنطينية، ثم مكة ثم عاد إلى المغرب، كُلُّ ذلك يكتب ويُدَوِّن ما يراه ويَصِفُه، والرحلة الثانية: كانت إلى الأندلس وغرناطة، والثالثة: كانت إلى إفريقيا سنة 754، ودَوَّن رحلته في كتاب بعنوان: تحفة النظار في غرائب الأمصار وعجائب الأسفار؛ قال ابن حجر: \"رحل إلى المشرق في رجب سنة 25 فجال البلاد وتوغَّل في عراق العجم، ثم دخل الهند والسند والصين، ورجع على اليمن فحج سنة 26 ولقي من الملوك والمشايخ خلقًا كثيرًا وجاور، ثم رجع إلى الهند فولاه مَلِكُها القضاءَ، ثم خلص فرجع إلى المغرب فحكى بها أحوالَه وما اتفق له وما استفاد من أهلها، قال شيخنا أبو البركات ابن البلفيقي: حدثنا بغرائب مما رآه؛ فمن ذلك أنه زعم أنه دخل القسطنطينية فرأى في كنيستها اثني عشر ألف أسقف ثم انتقل إلى العدوة ودخل بلاد السودان ثم استدعاه صاحب فاس السلطان أبو عنان المريني وأمره بتدوين رحلته، وقرأت بخط ابن مرزوق وكان البلفيقي رماه بالكذب، فبرأه ابن مرزوق، وقال: إنه بقي إلى سنة سبعين ومات وهو متولي القضاء ببعض البلاد، قال ابن مرزوق: ولا أعلم أحدًا جال البلاد كرحلته، وكان مع ذلك جوادًا مُحسِنًا\" كان ابن بطوطة يُملي ما يراه على السلطانِ أبي عنان، وكان له كاتب يكتب ذلك. توفي ابن بطوطة في فاس عن 76 عامًا."},{"id":3138,"title":"عصيان الأمير إينال اليوسفي على الأمير برقوق وما جرى بينهما .","date":["العام الهجري :780","الشهر القمري : شعبان","العام الميلادي :1378"],"text":"لما كان يومُ الرابع والعشرين شعبان ركب الأتابكُ برقوق من الإسطبل السلطاني في حواشيه ومماليكه للتسير على عادته، وكان الأميرُ بركة الجوباني مسافرًا بالبحيرة للصيد، فلما بلغ إينال اليوسفي أمير سلاح ركوبُ برقوق من الإسطبل السلطاني، انتهز الفرصة لركوبِ برقوق وغَيبة بركة، وركب بمماليكِه وهجم الإسطبلَ السلطانيَّ ومَلَكَه، ومسَكَ الأميرَ جركس الخليلي، وكان مع إينال جماعةٌ من الأمراء ولما طلع إينال إلى باب السلسلة وملكها، أرسل الأميرَ قماري ليَنزِلَ بالسلطان الملك المنصور إلى الإسطبل، فأبى السلطانُ من نزوله ومنعه، ثم كبس إينال زردخاناه-خزانة السلاح- برقوق، وأخرج منها اللَّبوسَ وآلة الحرب، وأخذ مماليكَ برقوق الذين كانوا وافقوه وألبسهم السلاحَ وأوقفهم معه وأوعدهم بمالٍ كبير وإمريات، وبلغ برقوقًا الخبَرُ فعاد مسرعًا، وجاء إلى بيت الأمير أيتمش البجاسي بالقرب من باب الوزير وألبس مماليكَه هناك، وجاءه جماعةٌ من أصحابه، فطلع بالجميع إلى تحت القلعة وواقعوا إينال اليوسفي، وأرسل برقوقٌ الأميرَ قرط في جماعة إلى باب السلسلة الذي من جهةِ باب المدرج، فأحرَقَه، ثم تسَلَّقَ قرط من عند باب سر قلعة الجبل، ونزل ففتح لأصحابِه الباب المتَّصِلَ إلى الإسطبل السلطاني، فدخلت أصحابُ برقوق منه وقاتلت إينال، وصار برقوقٌ بمن معه يقاتل من الرميلة، فانكسَرَ إينال ونزل إلى بيته جريحًا من سَهمٍ أصابه في رقبَتِه من بعض مماليك برقوق، وطلع برقوقٌ إلى الإسطبل وملكه، وأرسل إلى إينال من أحضره، فلما حضَرَ قَبَض عليه وحَبَسه بالزردخاناه، وقَرَّره بالليل فأقَرَّ أنه ما كان قصده إلَّا مَسْكَ بركة لا غير، ثم إن برقوق مسك جماعةً من الأمراء وغيرِهم من أصحاب إينال اليوسفي، ما خلا سودون النوروزي، جمق الناصري وشَخصًا جنديًّا يسمى أزبك كان يدعي أنه من أقارب برقوق، ثمَّ حُمِلَ إينال في تلك الليلة إلى سجن الإسكندرية ومعه سودون جركس، ثمَّ أخذ برقوق في القبض على مماليك إينال اليوسفي، ونودِيَ عليهم بالقاهرة ومصر، ثم في الثامن والعشرين من شعبان حضر الأمير بركة من السرحة، فركب الأتابك برقوق وتلقَّاه من السحر وأعلمه بما وقع من إينال اليوسفي في حَقِّه، ثم اتفقا على طلب الأمير يلبغا الناصري من نيابة طرابلس، فحضر وأنعم عليه بإقطاع إينال اليوسفي ووظيفته إمرة سلاح، وكانت وظيفةُ يلبغا قبل إينال، وتولَّى مكانَه في نيابة طرابلس منكلي بغا الأحمدي البلدي، ثم استقَرَّ بلوط الصرغتمشي في نيابة الإسكندرية."},{"id":3139,"title":"واقعة كنيسة ناحية بو النمرس من الجيزة .","date":["العام الهجري :780","الشهر القمري : رمضان","العام الميلادي :1379"],"text":"في يوم الأربعاء الثامِنَ مِن رمضان كانت واقعةُ كنيسة ناحية بو النمرس من الجيزة؛ وذلك أنَّ رجلًا من فُقَراء الزيلع بات بناحية بو النمرس، فسَمِعَ لنواقيس كنيسَتِها صوتًا عاليًا، وقيل له إنَّهم يضربون بنواقيسهم عند خُطبةِ الإمام للجمعة، بحيث لا تكادُ تُسمَعُ خُطبة الخطيب، فوقف للسُّلطان الملك الأشرف شعبان، فلم يَنَل غَرَضًا، فتوجه إلى الحجاز وعاد بعد مدة طويلة، وبيده أوراق تتضَمَّنُ أنه تشفع برسول الله وهو نائم عند قبره المقَدَّس في هدم كنيسة بو النمرس، ووقف بها إلى الأميرِ الكبير برقوق الأتابك، فرسم للمُحتَسِب جمال الدين محمود العجمي أن يتوجَّه إلى كنيسة بو النمرس، وينظُرَ في أمرها، فسار إليها وكشف عن أمرها، فبَلَغه من أهل الناحية ما اقتضى عنده غَلْقَها، فأغلقها وعاد إلى الأمير الكبير وعَرَّفه ما قيل عن نصارى الكنيسة، فطلب متَّى بِطريقَ النصارى اليعاقبة وأهانه، فسعى النصارى في فَتحِ الكنيسة، وبذلوا مالًا كبيرًا، فعَرَّف المحتَسِبُ الأميرَ الكبير بذلك، فرسَمَ بهَدمِها بتحسين المحتَسِب له ذلك، فسار إليها وهَدَمها، وعمِلَها مَسجدًا."},{"id":3140,"title":"حدوث إصلاحات بمكة والحرم .","date":["العام الهجري :780","الشهر القمري : ذي الحجة","العام الميلادي :1379"],"text":"أجرى الأميرُ باشاه- دوادار الأمير بركة- عينَ الأزرق المستمَدَّة من عين ثقبة، وعين ابنَ رَخَم من عرفة إلى البركتين خارج باب المعلَّاة بمكة المشَرَّفة, وجدد الميضأةَ عند باب بني شيبة، والرَّبع والحوانيت، وأصلح زمزمَ والحِجرَ والميزابَ، وسَطْح الكعبة."},{"id":3141,"title":"فتنة الحائط الذي يتكلم بمصر .","date":["العام الهجري :781","الشهر القمري : رجب","العام الميلادي :1379"],"text":"في هذه السَّنةِ كانت بالدِّيارِ المصرية واقعةٌ غريبة من كلامِ الحائط، وخبَرُه أنَّ في أوائل شهر رجب من هذه السنة ظهر كلامُ شَخصٍ مِن حائط في بيت العدلِ شهاب الدين أحمد الفيشي الحنفي بالقُربِ مِن الجامع الأزهر، فصار كلُّ من يأتي إلى هذا الحائط ويسألُه عن شيء يرُدُّ عليه الجوابَ ويُكَلِّمُه بكلام فصيح، فجاءته الناسُ أفواجًا، وتردَّدَت إلى الحائِطِ أكابِرُ الدولةِ، وتكلموا معه!! وافتتن الناس بذلك المكان وتركوا معايشَهم وازدحموا على حائط هذا الدار، وأكثَرَ أربابُ العقول الفحصَ عن ذلك، فلم يَقِفوا له على خبر، وتحيَّرَ الناسُ في هذا الأمر العجيب، إلى أن حضر إلى هذا الدار القاضي جمال الدين محمود القيصري العجمي محتَسِبُ القاهرة، وفحص عن أمره بكُلِّ ما يمكنُ القدرة إليه، حتى إنَّه أخرب بعضَ الحائطِ، فلم يُؤَثِّر ذلك شيئًا، واستمَرَّ الكلام في كل يوم إلى ثالث شعبان، وقد كادت العامَّةُ أن تتعَبَّدَ بمكانِه، وأكثروا من قولهم: يا سلام سَلِّم، الحيطة بتتكَلِّم!! وخاف أهلُ الدولة من إفساد الحال، وقد أعياهم أمرُ ذلك، حتى ظهر أن الذي كان يتكَلَّمُ هي زوجةُ صاحِبِ المنزل، فأُعلِمَ بذلك الأتابِكُ برقوق، فاستدعى بها مع زَوجِها، فحضرا، فأنكرت المرأةُ فضربها فأقَرَّت، فأمر بتَسميرِها وتَسميرِ شَخصٍ آخر معها يسمى عمر، وهو الذي كان يجمَعُ الناس إليها، بعد أن ضرب برقوقٌ الزَّوجَ وعُمَر بالمقارع، وطِيفَ بهما في مصر والقاهرة، ثم أُفرِجَ عنهم بعد أن حُبِسوا مُدَّةً!!"},{"id":3142,"title":"ظهور رجل يدعي النبوة بمصر .","date":["العام الهجري :781","الشهر القمري : شوال","العام الميلادي :1380"],"text":"في يوم الثلاثاء خامس عشر شوال قُبِضَ على رجل ادَّعى النبوة، وأنه النبيُّ صلَّى الله عليه وسلم الأميُّ، وأنه مُصَدِّقٌ بنبُوَّة نبيِّنا، وزعم أنَّ حروف القرآن تَنطِقُ له مع أنه أمي، وأن الذي يأتيه بالوحيِ جبرائيل وميكائيل وإسرافيل وعزرائيل، ورضوان ومالك ودرديائيل، وزعم أنه عربيٌّ من مصر، وأنه أُرسِلَ بقَتلِ الكفرة، وأن الترك يحَكِّمونه ويملكونه عليهم، وأنَّه أُنزِلَ عليه القرآن فسُجِنَ عند المجانين بالمارستان، ثم أخرجه الأميرُ بركة وسأله عن نبوَّتِه، فأخبره، فأمَرَ به فضُرِبَ حتى رجع عن قوله، ثم أُفرِجَ عنه بعد أياَّم، وقد كان يتلو من قرآنِه لنَفسِه به، ثمَّ فُقِدَ بعد ذلك."},{"id":3143,"title":"مقتل عدد ممن ارتدوا عن الإسلام وعادوا للنصرانية .","date":["العام الهجري :781","الشهر القمري : ذي الحجة","العام الميلادي :1380"],"text":"حضر إلى القاهرة طائفةٌ ما بين رجال ونساء، ذكروا أنهم ارتَدُّوا عن الإسلامِ، وقد كانوا قبل ذلك على النصرانية، يريدونَ بارتدادِهم التقَرُّبَ إلى المسيح بسَفكِ دمائهم، فعُرِضَ عليهم الإسلام مرارًا فلم يقبلوا، وقالوا: \"إنما جئنا لنتطَهَّر ونتقَرَّب بنفوسنا إلى السيد المسيحِ\" فقُدِّمَ الرجال تحت شباك المدرسة الصالحية بين القصرين، وضُرِبَت أعناقهم، وعُرِضَ الإسلام على النساء، فأبَيْنَ أن يُسلِمْن، فأخذَهنَّ القاضي المالكي إلى تحت القلعة، وضَرَب أعناقَهنَّ، كما قَدَّمَ أيضًا راهبًا نصرانيًّا قدح في الإسلام، وأصر على قبيحِه، فضُرِبَت عنقه، وكان هناك ثلاث نسوة، فرفعن أصواتَهنَّ بلقلقة ألسِنَتِهن، كما تفعَلُ النساء عند فَرَحِهنَّ؛ استبشارا بقتل الراهب، وأظهرن شغفًا به، وهيامًا لِما جرى له، وصَنَعْنَ كصنيعه من القدح في الإسلام، وأرَدْنَ تطهيرَهنَّ بالسَّيفِ أيضًا، ثم ضُرِبَت رقبة رفيق الراهب في يوم الجمعة الثاني والعشرين منه تحت شباك الصالحية، وضُرِبَت رقاب النسوة الثلاث من الغد يوم السبت تحت القلعة بيد الأمير سودن الشيخوني الحاجب، وأُحرِقَت جُثَثُهن بحُكمِ أنَّهن ارتَدَدْن عن الإِسلامِ، وأظهَرْنَ أنهنَّ فعَلْنَ هذا لعِشقِهنَّ الراهب، وكان يُعرَفُ بأبي نفيفة، ولم يُسمَعْ في أخبار العُشَّاق خبرًا أغرب من هذا، ثم جاء بعد ذلك رجلٌ من الأجناد على فرس، وقال للقاضي: طهرني بالسيف، فإني مرتَدٌّ عن الإسلامِ، فضُرِبَ وسُجِنَ."},{"id":3144,"title":"الفتنة بين الأمير بركة والأمير برقوق .","date":["العام الهجري :782","الشهر القمري : صفر","العام الميلادي :1380"],"text":"في ليلةِ الجمعة تاسِعَ عَشَر صفر لَبِسَ الأمير بركة السلاحَ هو ومماليكه، ولبس الأمراءُ أيضًا وباتوا في إسطبلاتهم على احتراز، فلما أصبح نهارُ يوم الجمعة، طلب الأميرُ الكبير برقوق القضاةَ ومشايخَ العلم وندبهم للدخول بينه وبين الأمير بركة في الصُّلحِ؛ مكيدةً منه ودَهاءً، فما زالوا يتردَّدونَ بينهما عِدَّة مرار، حتى وقع الصلحُ على دَخَن، وحلف كلٌّ منهم لصاحبه، ونزعوا عنهم السلاحَ، فبعث الأميرُ برقوق بالأمير أَيْتَمِش إلى الأمير بركة، فنزل إليه وفي عُنُقِه منديل، ليفعل ما يريدُ مِن قتل أو حبس أو غير ذلك، وخضع له خضوعًا زائدًا، فلم يجِدْ بركةُ بدًّا من الإغضاءِ عنه وقبول معذرته، وخلع عليه، وأعاده إلى الأميرِ برقوق، والقلوبُ ممتلئةٌ حَنَقًا، ونودي في القاهرة بالأمان وفَتْح الأسواق، فسكن انزعاجُ الناس، فلما أصبح نهارُ الأربعاء تاسع شهر ربيع الأول أنزل برقوق السلطانَ المَلِكَ المنصور إلى عنده بالإسطبل السلطاني، ونادى للمماليكِ السُّلطانية بالحضور، فحضروا فأخرجَ جماعةً كبيرة من الأمراء ومعهم المماليك السلطانية ونَدَبَهم لقتال بركة بعد أن بلَغَه أنَّه يريدُ أن يقتُلَه غِيلةً يوم الجمعة في الصلاة، ودُقَّت الكوسات بقلعة الجبل، هذا وقد جَهَّز بركة أيضًا جماعةً كبيرة أيضًا من أصحابِه؛ لملتقى من ندبه برقوق لقتالِه، وسار كل من الفريقينِ إلى الآخر حتى تواجَها على بُعدٍ، فلم يتقَدَّمْ أحد من العسكرين إلى غريمِه، فلما كان بعد الظهر بعث الأميرُ بركة أمير آخوره سيف الدين طغاي يقول لبرقوق: ما هذا العَمَلُ، هكذا كان الاتفاق بيننا؟ فقال برقوق: هكذا وقع، قل لأستاذك: يتوجه نائبًا في أيِّ بلد شاء، فرجع أميرُ آخور بركة إليه بهذا القَولِ، فلم يوافِقْ بركة على خروجه من مصر أصلًا، فركب بركةُ بأصحابه ومماليكه من وَقتِه، وساقوا فرقتين: فرقةٌ من الطريق المعتادة، وفرقةٌ من طريق الجبل، وكان بركةُ في الفرقة التي بطريق الجَبَل، وبلغ برقوقًا ذلك فأرسل الأمراءَ والمماليك في الوَقتِ لِمُلتقاه، فلما أقبل بركةُ هرب أكثَرُ عساكر برقوق ولم يَثبُتْ إلَّا الأميرُ علان الشعباني في نحو مائة مملوك، والتقى مع بركة، وكان يلبغا الناصري بمن معه من أصحابِ بركة توجَّه من الطريق المعتادة، فالتقاه أيتمش البجاسي بجماعةٍ وكسره، وضَرَبَه بالطبر، وأخذ جاليشَه وطبلخاناتِه، ورجع مكسورًا بعد أن وقع بينهم وقعةٌ هائلة جُرِحَ فيها من الطائفتين خلائق، وأما بركة فإنه لما التقى مع علان صَدَمَه عَلَّان صدمةً تقنطَرَ فيها عن فَرَسِه، وركب غَيرَه، فلما تقنطر انهزم عنه أصحابُه، فصار في قِلَّة، فثبت ساعة جيدةً ثم انكسر وانهزم إلى جهةِ قُبَّة النصر، وأقام به إلى نِصفِ الليل، فلم يجسُرْ أحد من البرقوقيَّة على التوجه إليه وأخْذِه، فلما كانت نصفُ ليلة الخميس رأى بركة أصحابَه في قلة، وقد تخَلى عنه أكثَرُ مماليكه وحواشيه، وهرب من قُبَّة النصر هو والأمير آقبغا صيوان إلى جامع المقسي خارج القاهرة، فغُمِزَ عليه في مكانه فمُسِكَ هو وآقبغا من هناك، وطُلِعَ بهما إلى برقوق، وتتَبَّعَ برقوق أصحابَ بركة ومماليكه فمسك منهم جماعةً كبيرة مع من مُسِك مع بركة من الأمراء، وبَقِيَت القاهرة ثلاثة أيام مغلقة والنَّاسُ في وَجَل بسبب الفتنة، فنادى برقوقٌ عند ذلك بالأمان والاطمئنان، وأمَّا أمرُ بركة فإنه لما كان شهر رجب من هذه السنة ورد الخبَرُ من الأمير صلاح الدين خليل بن عرام نائب الإسكندرية بموت الأمير زين الدين بركة الجوباني اليلبغاوي بسِجنِ الإسكندرية، فلما بلغ الأتابك برقوقًا ذلك بعث بالأميرِ يونس النوروزي الدوادار بالإسكندرية لكَشفِ خَبَرِ الأمير بركة وكيف كانت وفاتُه، فتوجه يونُسُ إلى الإسكندرية، ثم عاد إلى مصر ومعه ابنُ عرام نائب الإسكندرية، وأخبر برقوقًا بأنَّ الأمرَ صَحيحٌ، وأَّنه كشف عن موته وأخرجه من قَبرِه فوجد به ضرباتٍ: إحداها في رأسِه، وأنه مدفون بثيابِه مِن غير كفن، وأن يونُسَ أخرجه وغَسَّله وكَفَّنه ودفنه وصلَّى عليه خارج باب رشيد، وبنى عليه تربة، وأن الأمير صلاح الدين خليل بن عرام هو الذي قتَلَه، فحَبَس برقوقٌ ابنَ عرام بخزانة شمائل وهي السِّجنُ المخصَّص لأصحاب الجرائم، ثم عصره وسأله عن فصوصٍ تركها بركة عنده، فأنكرها وأنكر أنَّه رآها، فلما كان يوم الخميس خامس عشرين شهر رجب طلع الأمراءُ للخدمة على العادة، وطُلِبَ ابن عرام من خزانة شمائل، فطلعوا به إلى القلعةِ على حمار، فرَسَم برقوق بتسميره، فخرج الأميرُ مأمور القلمطاوي حاجب الحجاب، وجلس بباب القلة هو وأميرُ جاندار، وطلب ابن عرام بعد خدمةِ الإيوان، فعُريَ وضُرِبَ بالمقارع ستة وثمانين شيبًا، ثم سفر على جمل بلعبة تسمير عطب، وأنزل من القلعة إلى سوق الخيل بالرميلة بعد نزول الأمراء، وأوقفوه تجاه الإسطبل السلطاني ساعةً، فنزل إليه جماعةٌ من مماليك بركة وضَرَبوه بالسيوف والدبابيس حتى هَبَروه وقطَّعوه قطَعًا عديدة، ثم إنَّ بَعضَهم قَطَع أذنه وجعل يَعَضُّها صفة الأكل، وأخذ آخَرُ رجله، وآخر قَطَعَ رأسَه وعَلَّقَها بباب زويلة، وبقيت قِطَعٌ منه مرمية بسوق الخيل، وذُكِرَ أن بعض مماليك بركة أخذ من لحمه قطعةً شواها، والله أعلم بصحة ذلك، ثم جُمِعَ ابن عرام بعد ذلك ودُفِنَ بمدرسته خارج القاهرة عند جامع أمير حسين بن جندر بحكر جوهر النوبي."},{"id":3145,"title":"كثر الوباء بالإسكندرية .","date":["العام الهجري :782","الشهر القمري : رمضان","العام الميلادي :1380"],"text":"كثر الوباء بالإسكندرية، فمات في كل يوم ما ينيف على مائة وخمسين إنسانًا، وتمادى إلى ذي الحِجَّة."},{"id":3146,"title":"غزو المغول الروس ودخول توقتاميش خان موسكو .","date":["العام الهجري :783","العام الميلادي :1381"],"text":"بعد وفاةِ محمد بردي بك أمير أذربيجان سنة 762 وقد كان ولَدُه توقتاميش صغيرًا على الملك فعَمَّت الفوضى البلاد فاستقَلَّ الحاج جركس بمنطقة استراخان، واستقَلَّ ماماي بمنطقة القرم، وأما منطقة سراي فحَكَمَها خضر بك وهرب توقتاميش إلى سمرقند إلى تيمورلنك، فاستغَلَّ الروس هذا الاختلاف فانقَضُّوا على التتار والتَقَوا مع ماماي وانتصروا عليه، فقام توقتاميش بالرجوع إلى سراي وحكَمَها بمساعدة تيمورلنك، ثم في هذه السنة 783 بعد أن استطاع توقتاميش خان السيطرةَ على أمور التتار والجلوس على عرش الحكم فيها، حيث استقَلَّ بسلطنة دشت القفجاق وسراي، بعد أن قتل تيمر ملك خان في حدود سنة 780 فأرسل إلى حكام الروسية ليدينوا له بالطاعةِ، ولكن حصل منهم تباطؤ وممالأة، فسار إليهم توقتاميش إلى موسكو في أوائل سنة 783 من طريقِ البلغار وعبَرَ نَهرَ أدل (أولغا) ففَرَّ منها حاكمُها ديمتري وهرب معه كثيرٌ مِن أهل موسكو، وبَقِيَ مَن بقي للمدافعة والقتال مغترين بسور المدينة العظيم، ثم وصل التتار وبدؤوا الحصار والرمي ثلاثة أيام، ثم بدأت المحاربة في اليوم الرابع وقال لهم توقتاميش: إن همه هو ديمتري ثم استقَرَّ رأي أهل البلد أن يفتحوا الأبوابَ، فلما فعلوا دخل التتار وقتلوا كلَّ من رأوا أمامَهم من الأهالي ونَهَبوا الأموال وأسَروا من أسَروا ثم عادوا إلى بلادهم بما حصَّلوه من أموال."},{"id":3147,"title":"وقوع الوباء بالطاعون في الناس بالقاهرة ومصر .","date":["العام الهجري :783","الشهر القمري : محرم","العام الميلادي :1381"],"text":"في المحرَّم من هذا العام بدأ انتشارُ وباء الطاعون في الناس بالقاهرة ومصر، وتزايد حتى بلغ عِدَّةُ من يموت في اليوم ثلاثمائة مَيِّت!"},{"id":3148,"title":"وفاة السلطان المنصور علي بن شعبان وتولي أخيه حاجي .","date":["العام الهجري :783","الشهر القمري : صفر","العام الميلادي :1381"],"text":"هو السُّلطانُ المَلِكُ المنصور علي ابن الأشرف شعبان بن حسين الناصر بن المنصور قلاوون. مَرِضَ السلطان المنصور ولزم الفراش، حتى مات بين الظُّهرِ والعصر من يوم الأحد الثالث والعشرين صفر، ودفن من ليلته بعد عشاء الآخرة في تربةِ جَدَّتِه لأبيه خوند بركة بالقُبَّة التي بمدرستها بالتبانة، وكان الذي تولَّى تجهيزه وتغسيلَه ودَفْنَه الأميرَ قطلوبغا الكوكائي، وكانت مُدَّة سلطنته على ديار مصر خمس سنين وثلاثة أشهر وعشرين يومًا، ومات وعُمُرُه اثنتا عشرة سنة، ولم يكن في سلطنته سوى مجرَّد الاسم فقط، وإنما كان أمرُ المملكة في أيام سلطنته إلى قرطاي أولًا ثم إلى برقوق آخِرًا، وهو كالآلة معهم لصِغَرِ سنه ولغَلَبَتِهم عليه، وتسَلْطَنَ مِن بعده أخوه أمير حاج ابن الملك الأشرف شعبان بن حسين، ولم يَقدِرْ برقوق- مع ما كان عليه من العظمة- أن يتسلطَنَ، وتلَقَّبَ بالمَلِك الصالح، ولما تمَّ أمرُ الملك الصالح هذ،ا ألبسوه خِلعةَ السلطنة، وركب من باب الستارة بأُبَّهة الملك، وبرقوقٌ والأمراءُ مُشاةٌ بين يديه، إلى أن نزل إلى الإيوان بقلعة الجبل، وجلس على كرسيِّ المُلك، وقَبَّلَت الأمراءُ الأرض بين يديه، ثم مُدَّ السِّماطُ وأكَلَت الأمراء، ثم قام السلطانُ الملك الصالح ودخل القصر، وخلع على الخليفةِ المتوكِّلِ على اللهِ خِلعةً جميلة، ونودي بالقاهرةِ ومصر بالأمانِ والدعاء للملك الصالح حاجي، وخلع السُّلطانُ على الأتابك برقوق، واستقر على عادته أتابكَ العساكِرِ ومُدَبِّرَ الممالك؛ لصغر سن السلطان، وكان سن السلطان يوم تسلطن نحو تسع سنين تخمينًا."},{"id":3149,"title":"وفاة الإمام العالم شهاب الدين الأذرعي الشافعي .","date":["العام الهجري :783","الشهر القمري : جمادى الآخرة","العام الميلادي :1381"],"text":"هو الشَّيخُ الإمامُ العالم شهابُ الدين أبو العباس أحمد بن حمدان بن أحمد بن عبد الواحد بن عبد الغني بن محمد بن أحمد بن سالم بن داود الأذرعي الشافعي، نزيلُ حَلَب، وُلِدَ سنة 707، وتفَقَّه بدمشق قليلًا، وناب في بعض النواحي في الحُكمِ بها، ثم تحوَّل إلى حلب فقَطَنَها، وناب في الحُكم بها، ثم ترك وأقبَلَ على الاشتغال والتصنيف والفتوى والتدريس، وجمع الكتبَ حتى اجتمع عنده منها ما لم يحصُلْ عند غيره، وظَفِرَ من النقولِ ما لم يحصُلْ لأهل عصره، وذلك بيِّنٌ في تصانيفه، وتعَقَّب \"المهمات\" للإسنوي بقدر حَجمِها، والذي بيَّضَه منها إلى النكاح في أربع مجلداتٍ، وهو ثَبْتٌ في النقل وسَطٌ في التصرفات، قاصِرٌ في غير الفقهِ، وأجاز له القاسم بن عساكر والحجَّار وغيرهما، وسمع من الكمال بن عبد وطائفة، وجمع له شهاب الدين بن حجي مشيخة، وتفقه بشيوخ عصره ومهر في الفن، وكان اشتغالُه على كِبَر، وكان عديمَ النَّظِير، فقيهًا عالِمًا، وسأل السبكي أسئلةً شهيرة اسمها الحلبية، وصنف شرحين على المنهاج، وجمع على الروضة كتابًا سماه التوسط والفتح بين الروضة والشرح، أكثَرَ فيه من النقولاتِ المفيدة، وانتهت إليه رئاسةُ العلم بحلب، مات بها في نصف جمادى الآخرة عن نيف وسبعين سنة بعد أن حصل له عَرَجٌ وقليلُ صَمَمٍ وضَعفُ بَصَر، وله شِعرٌ، فمنه ما حكاه ابنه عبد الرحمن عنه."},{"id":3150,"title":"عصيان الأمير علاء الدين ألطنبغا على السلطان برقوق .","date":["العام الهجري :784","العام الميلادي :1382"],"text":"سار الأميرُ يلبغا الناصري نائِبُ حلب بعسكر حلب إلى إلبيرة، يريدُ تعدية الفرات، فجاءه الخبر بعصيانِ الأمير علاء الدين ألطنبغا السلطاني نائب الأبلستين، وأنه لم يحلِفْ للسلطان برقوق واستولى على قلعةِ درندة وطلع إليها، وأمسك بعض أمرائِها، وأطلع إليها ذخيرة وميرة، فركب العسكَرُ الذي بالمدينة عليه، وأمسكوا رجالَه، فطلب الأمان منهم، وفَرَّ مِن القلعة إلى الأبلستين، فكتب إليه الأميرُ يلبغا الناصري يهَدِّدُه ويُخيفه، فلم يَرجِعْه إليه، ومَرَّ هاربًا على وجههِ إلى بلاد التتر، فعاد الأمير يلبغا إلى حلب."},{"id":3151,"title":"وفاة السلطان الملك حسين الجلائري المغولي ملك بغداد وتبريز .","date":["العام الهجري :784","العام الميلادي :1382"],"text":"هو السُّلطانُ المَلِكُ المعِزُّ حسين بن أويس ابن الشيخ حسن بن حسين بن آقبغا بن أيلكان، المنعوت بالشيخ حسين، سلطان بغداد وتبريز وما والاهما، وكان سبط القان أرغون بن بوسعيد ملك التتار، ولِيَ سلطنة بغداد في حياة أبيه؛ لأنَّ والده أويسًا كان رأى منامًا يدُلُّ على موته في يومٍ مُعَيَّن، فاعتزل المُلْكَ وسَلْطَنَ ولَدَه هذا، ودام الشيخُ حسين هذا في الملك إلى أن قتَلَه أخوه السلطان أحمد بن أويس وملك بغداد بإشارة الشيخ خجا الكجحاني في هذه السنة، ولقد كانت العراقُ في أيامه مطمئنَّةً معمورة إلى أن مَلَكَها أخوه أحمد بعده، فاضطربت أحوالُها إلى أن قُتِلَ، ثمَّ مَلَكَها قرا يوسف وأولادُه، فكان خراب العراق على أيديهم، وبالجملةِ فكان الشيخ حسين شَهمًا شُجاعًا حَسَن السياسة, وهو آخِرُ ملوك بغداد والعراق من المغول."},{"id":3152,"title":"العثمانيون يفتحون صوفيا عاصمة البلغار .","date":["العام الهجري :784","العام الميلادي :1382"],"text":"تأخَّرَ الصِّربُ والبلغار في دفع الجزية، ويبدو أنَّ ذلك عن اتفاق بينهم، فتوجَّهَت الجيوش العثمانية إلى بلادِهم، ففتحت بعضَ المدن الصربية التي تقع اليومَ جنوبي يوغسلافيا، كما حاصرت عاصمة البلغار صوفيا، وفتحتها بعد حصار دام ثلاث سنواتٍ، فكان في هذه السَّنةِ الفَرَجُ بفَتحِها، كما فُتِحَت مدينة سلانيك المدينة اليونانية المشهورة والواقعة على بحر إيجه."},{"id":3153,"title":"خلع السلطان الصالح حاجي وتولي برقوق أول مماليك الشراكسة .","date":["العام الهجري :784","الشهر القمري : رمضان","العام الميلادي :1382"],"text":"حاوَلَ بَعضُ الأمراء القضاءَ على برقوق وقَتْلَه، لكنَّه استطاع أن يقبِضَ عليهم ويسجِنَهم، ولكنه استمَرَّ بعد مَسْك هؤلاء في تخوف عظيم، واحترز على نفسه من مماليكِه وغيرِهم غايةَ الاحتراز، فأشار عليه بعد ذلك أعيانُ خشداشيته- زملاء مهنته- وأصحابه مثل أيتمش البجاسي، وألطنبغا الجوباني أمير مجلس، وقردم الحسني، وجركس الخليلي ويونس النوروزي الدوادار وغيرهم أن يتسلطَنَ ويحتَجِبَ عن الناس ويستريح ويُريحَ مِن هذا الذي هو فيه من الاحترازِ مِن قيامه وقعودِه، فجَبُنَ عن الوثوب على السلطنةِ وخاف عاقبةَ ذلك، فاستحَثَّه الأمراء، فاعتذر بأنه يهابُ قُدَماءَ الأمراء بالديار المصرية والبلاد الشامية، فركِبَ سودون الفخري الشيخوني حاجِبُ الحُجَّاب ودارَ على الأمراء سرًّا حتى استرضاهم، وما زال بهم حتى كلَّموا برقوقًا في ذلك وهَوَّنوا عليه الأمرَ وضَمِنوا له أصحابَهم من أعيان النواب والأمراء بالبلاد الشامية، وساعدهم في ذلك موتُ الأمير آقتمر عبد الغني؛ فإنَّه كان من أكابر الأمراء، وكان برقوقٌ يجلس في الموكِبِ تحتَه لِقِدَم هِجرتِه، وكذلك بموتِ الأمير أيدمر الشمسي؛ فإنه كان أيضًا من أقران اقتمر عبد الغني، فماتا في سنة واحدة، فعند ذلك طابت نفسُه وأجاب، وصار يقَدِّمُ رِجلًا ويؤخر أخرى، حتى كان يوم الأربعاء تاسع عشر شهر رمضان من هذه السنة طلع الأمير قطلوبغا الكوكائي أمير سلاح وألطنبغا المعلم رأس نوبة إلى السلطان الملك الصالح أمير حاج فأخذاه من قاعة الدهيشة وأدخلاه إلى أهلِه بالدور السلطانيَّة، وأخذا منه النمجاة- سيف خاص بالملك أو السلطان- وأحضراها إلى الأتابك برقوقٍ العثماني، وقام بقيَّةُ الأمراء من أصحابه على الفور وأحضروا الخليفةَ والقُضاة وسَلْطَنوه، وخُلِعَ الملك الصالح من السلطنة، فكانت مُدَّة سلطنته على الديار المصرية سنة واحدة وسبعة أشهر تنقُصُ أربعة أيام، على أنَه لم يكن له في السلطنة من الأمر والنهي لا كثيرٌ ولا قليل، أما السلطان المَلِكُ الظاهر فهو أبو سعيدٍ سَيفُ الدين برقوق بن آنص العثماني اليلبغاوي الشركسي، القائم بدولة الشراكسة بالدِّيارِ المصرية، وهو السلطان الخامس والعشرون من ملوك الترك بالديار المصرية، والثاني من الشراكِسة، إن كان المَلِكُ المظَفَّر بيبرس الجشنكير شركسيًّا؛ فقد قيل إن أصله تركي، وعليه فبرقوق هذا هو الأول من ملوك الشراكسة، وهو الأصحُّ، جلس على تخت الملك في وقت الظهر من يوم الأربعاء تاسع عشر شهر رمضان بعد أن اجتمع الخليفةُ المتوكل على الله أبو عبد الله محمد والقضاة وشيخُ الإسلام سراج الذين عمر البلقيني، وخطب الخليفة المتوكل على الله خطبة بليغة، ثم بايعه على السَّلطنةِ وقَلَّدَه أمورَ المملكة، ثم بايعه من بعدِه القضاة والأمراء، ثم أُفيضَ على برقوق خِلعة السلطنة، وهي سوداء خليفتية على العادة، وأشار السراجُ البلقيني أن يكون لَقَبُه الملك الظاهر؛ فإنَّه وقت الظهيرة والظهور، وقد ظهر هذا الأمرُ بعد أن كان خافيًا، فتلَقَّبَ بالملك الظاهر، وبه يبدأُ عهد المماليك البُرجية وينتهي عهدُ المماليك البحريَّة، ويُذكَرُ أن أصله من بلاد الشركس، ثمَّ أُخِذَ من بلاده وبِيعَ بمدينة قرم، فاشتراه خواجا عثمان بن مسافر وجلبه إلى مصر فاشتراه منه الأتابك يلبغا العمري الخاصكي الناصري في حدود سنة 764 وقبلها بيسير وأعتَقَه وجعله من جملة مماليكِه، واستمَرَّ أمره حتى صار أتابكَ العساكِرِ. والشراكسة شعب مسلم موطنه الأصلي مرتفعات القوقاز بين البحر الأسود وبحر قزوين."},{"id":3154,"title":"بعض النصارى يضربون مؤذنًا بسبب العرس .","date":["العام الهجري :785","الشهر القمري : جمادى الأولى","العام الميلادي :1383"],"text":"في شَهرِ جمادى الأولى اتَّفَق بناحية برما من الغربية أنَّ طائفة من مُسلِمةِ النصارى، صَنَعوا عُرسًا جمعوا فيه عِدَّةً من أرباب الملاهي، فلما صَعِدَ المؤذن ليسَبِّحَ الله تعالى في الليل على العادة، سَبُّوه وأهانوه، ثم صَعِدوا إليه وأنزلوه، بعدما ضربوه، فثار خطيب الجامِعِ بهم؛ ليُخَلِّصَه منهم، فأوسعوه سبًّا ولعنًا وهَمُّوا بقتله وقَتْلِ من معه، فقَدِمَ إلى القاهرة في طائفة، وشكَوا أمرهم إلى الأمير سودن النائب، فبعث بهم إلى الأمير جركس الخليلي؛ من أجل أن ناحية برما من جملة إقطاعه، فلم يَقبَلْ أقوالهم، وسَجَن عِدَّةً منهم، فمضى من بَقِيَ منهم إلى أعيان الناس، كالبلقيني وأمثاله، وتوجَّهَ الحافظ المعتمد ناصر الدين محمد فيق إلى الخليلي، وأغلَظَ عليه حتى أفرج عمَّن سَجَنَه، فغضب كثيرٌ من أهل برما واستغاثوا بالسلطانِ، فأنكر على الخليلي ما وقع منه، وبعث الأميرَ أبدكار الحاجِبَ للكشف عما جرى في برما، فتبين له قُبحُ سيرة المسألة فحمَلَهم معه إلى السلطان، فأمر بهم وبغُرَمائِهم أن يتحاكموا إلى قاضي القضاة المالكية، فادعى عليهم بقوادِحَ، وأُقيمَت البَيِّنات بها فسجَنَهم، واتفق أن الخليلي وقعت في شونة قصب له نارٌ أحرقتها كلها، وفيها جملة من المال، وحدث به وَرَمٌ في رجله، اشتد ألمه فلم يزل به حتى مات؛ وذلك عقوبة له لمساعدةِ أهل الزندقة!"},{"id":3155,"title":"السلطان برقوق يخلع الخليفة العباسي المتوكل ويولي محمد بن الواثق الخلافة .","date":["العام الهجري :785","الشهر القمري : رجب","العام الميلادي :1383"],"text":"في أوَّلِ شَهرِ رَجَب من هذه السنة طلع الأميرُ صلاح الدين محمد بن محمد بن تنكز نائب الشام إلى السلطانِ ونقل له عن الخليفة المتوكل على الله أبي عبد الله محمد أنَّه اتفق مع الأمير قرط بن عمر التركماني المعزول عن الكشوفيَّة ومع إبراهيم بن قطلوقتمر العلائي أمير جاندار ومع جماعةٍ من الأكراد والتركمان، وهم نحو من ثمانمائة فارس، أنَّهم يَثِبون على السلطان إذا نزل من القَلعةِ إلى الميدان في يوم السَّبتِ لِلَّعِبِ بالكرة يقتلونَه ويمكنون الخليفةَ مِن الأمرِ والاستبدادِ بالمُلكِ، فحَلَّف السلطانُ ابن تنكز على صِحَّة ما نقل، فحلف له، وطلب أن يحاقِقَهم على ذلك، فبعث السلطانُ إلى الخليفة وإلى قرط وإلى إبراهيم بن قطلقتمر، فأحضرهم وطلب سودون النائب وحَدَّثه بما سمع، فأخذ سودون ينكِرُ ذلك ويستبعد وقوعَه منهم، فأمر السلطان بالثلاثة فحضروا بين يديه وذكر لهم ما نُقِلَ عنهم فأنكروا إلا قرط، فإنه خاف من تهديد السلطان، فقال: الخليفةُ طَلَبني وقال: هؤلاء ظَلَمةٌ وقد استولوا على هذا المُلكِ بغير رضائي، وإني لم أقلِّدْ بَرقوقًا السلطنةَ إلَّا غصبًا، وقد أخذ أموال الناسِ بالباطل، وطلب مني أن أقومَ معه وأنصُرَ الحَقَّ، فأجبْتُه إلى ذلك ووعدتُه بالمساعدة، وأن أجمع له ثمانمائة واحد من الأكراد والتركمان وأقوم بأمره، فقال السلطان للخليفة: ما قولُك في هذا؟ فقال: ليس لِما قاله صحة، فسأل إبراهيم بن قطلقتمر عن ذلك، فقال: ما كنت حاضرًا هذا الاتِّفاق، لكِنَّ الخليفة طلبني إلى بيته بجزيرة الفيل وأعلمني بهذا الكلامِ وقال لي: إن هذا مصلحةٌ، ورغَّبني في موافقته والقيام لله تعالى ونُصرة الحق، فأنكر الخليفةُ ما قاله إبراهيم أيضًا، وصار إبراهيمُ يذكُرُ له أمارات والخليفةُ يَحلِفُ أن هذا الكلام ليس له صِحَّة، فاشتَدَّ حَنَق الملك الظاهر وسَلَّ السيف ليضرَبَ عنق الخليفة، فقام سودون النائب وحال بينه وبين الخليفةِ، وما زال به حتى سكَنَ بعضُ غضبه، فأمر الملك الظاهِرُ بقرط وإبراهيم يسفرا، واستدعى القضاة ليُفتُوه بقتل الخليفة، فلم يُفتُوه بقتله، وقاموا عنه، فأخذ برقوق الخليفةَ وسَجَنَه بموضع في قلعة الجبل وهو مقَيَّد، وسَمَرَ قرط وإبراهيم وشُهِرَا في القاهرة ومصر، ثم أُوقِفا تحت القلعة بعد العصر، فنزل الأمير أيدكار الحاجب وسار بهما ليوسَّطا خارج باب المحروق من القاهرة، فابتدأ بقرط فوُسِّط، وقبل أن يُوسَّط إبراهيم جاءت عدَّةٌ من المماليك بأن الأمراء شَفَعوا في إبراهيم، ففُكَّت مساميره وسُجِنَ بخزانة شمائل، وطَلَب السلطانُ زكريا وعمر ابني إبراهيم عم المتوكل، فوقع اختيارُه على عمر بن الخليفة المستعصم بالله أبي إسحاق إبراهيم بن المستمسك بالله أبي عبد الله محمد بن الإمام الحاكم بأمر الله أبي العباس أحمد بن الحسن بن أبي بكر بن أبي علي إسحاق ابن علي القبي، فولَّاه الخلافة، وخلع عليه، فتلقَّبَ بالواثق بالله، ثم في يوم الثلاثاء تاسع ذي القعدة أفرج السلطانُ عن الخليفة المتوكل على الله، ونُقِلَ من سجنه بالبرج إلى دار بالقلعةِ وأحضَرَ إليه عيالَه."},{"id":3156,"title":"الفرنج يغزون بيروت .","date":["العام الهجري :785","الشهر القمري : شعبان","العام الميلادي :1383"],"text":"سار الأميرُ يلبغا الناصري نائب حلب من حلب بالعسكر للقاءِ الفرنج، وقد وردت شوانيهم في البَحرِ لِقَصدِ إياس، ونزوله بالعمق لقربه من البحر، فورد عليه كِتابُ نائب اللاذقية بوصول الفرنج إلى بيروت، وأنهم نزلوا إلى البر، وملكوا بعض أبراجِها، فأدركهم العسكرُ الشامي في طائفةٍ مِن رجَّالة الأكراد، وقاتلوهم، فأيَّدَ الله المسلمين، حتَى قتلوا من الفرنج نحو خمسمائة رجل، وانهزم باقيهم إلى مراكبهم، وساروا وعادت العساكِرُ إلى الشام."},{"id":3157,"title":"محاربة التركمان المتمردين في سيس .","date":["العام الهجري :785","الشهر القمري : ذي القعدة","العام الميلادي :1384"],"text":"كُتِبَ بتَجريدِ عَسكَرِ دمشق وطرابلس وحماة وحلب، ونواب الثغور وتركمان الطاعة وأكرادها، إلى جهة التركمان العصاة بالبلاد السيسية، كالصارم بن رمضان نائب أدنه وبني أوزر، وابن برناص من طائفة الأجقية؛ لمقاتلتهم على تعديهم طريقَهم، وقطْعِهم الطرقات، ونهْبِهم حُجَّاج الروم، ولاتفاقهم مع الأمير علاء الدين علي بك بن قرمان صاحب لارندة على اقتلاع بلاد سيس، فتأهَّبت العساكِرُ لذلك ووافت حلب، فتقَدَّمها الأميرُ يلبغا الناصري نائب حلب، وركب من حَلَب في ثاني ذي القعدة يريد العُمقَ، وكتب إلى بني أوزر وبقية التركمان العصاة، ينذرهم ويحذرهم التخَلُّفَ عن الحضور إلى الطاعة، ويخَوِّفهم بأس العساكر، وإنَّهم إن أذعنوا وأطاعوا كانوا آمنينَ على أنفُسِهم وأموالِهم، ومن تخَلَّف كان غنيمةً للعساكرِ، وسار حتى نزل تحتَ عُقبة بغِراسٍ، فعرض العساكِرَ، وتَرَك الثِّقلَ وتوجَّه مُخِفًّا، وجاوز عقبةَ بغراس، وترك بها نائبي عينتاب وبغراس بخيَّالتهما ورجالهما؛ حِفظًا للدربند إلى أن تصل العساكِرُ الشاميَّة، ثم ركب في الثلث الأول من ليلة الأحد الخامس عشر وسار مجِدًّا، فوصل المصيصة عصرَ نهار الأحد فوجد الأميرين قد ملكا الجسرَ بعد أنْ هدم التركمانُ بَعضَه، وقطعوا منه جانبًا لا يمنع الاجتيازَ، وتوقَّدَت بينهم نارُ الحرب، وعَدت العساكر نهر جاهان إلى جانِبِ بلاد سيس، واقتَفَوا آثار من كان بالمصيصة من التركمان، فأدركوا بعض البيوت فانتهبوها، فتعلق الرِّجالُ بشعف الجبال، ثم حضرت قصاد التركمان على اختلاف طوائفِهم يسألون الأمان، فأجاب الأميرُ يلبغا الناصري سؤالَهم، وكتب لهم أمانًا، ولما أحس الصارمُ بن رمضان بالعساكر، ترك أذنة وفَرَّ إلى الجبال التي لا تُسلَك، ووصلت الأطلابُ والثقل إلى المصيصة في السابع عشر، فقَدِمَ من الغد الثامن عشر قاصد الأمير طَشبغا العزي نائب سيس بخبر وصول ابن رمضان إلى أطراف البلاد السيسية، وأنه ركب في أثَرِه ومعه طائفةٌ من التركمان القرمانيين، فأدركوا بيوتَه فانتهبوها، وأمسكوا أولادَه وحريمه ونجا بنفسه، ولَحِقَ بالتركمان البياضية مستجيرًا بهم، فأجمعت الآراءُ على التوجه بالعساكر إلى جهتهم وإمساكِه، فقَدِمَ الخبر من نائب سيس في آخر النهار بأنه استمَرَّ في طلب ابن رمضان إلى أن أدركه وأمسَكَه، وأمسك معه أخاه قرا محمد وأولاده وأمه وجماعته وعاد إلى سيس، فسُرَّت العساكر بذلك سرورًا زائدًا، ورحلت في التاسع عشر تريد سيس، وأحاطت بطائفةٍ من التراكمين اليراكية، فانتهبت كثيرًا من خيل ومتاع وأثاث، ثم أمنوهم بسؤالهم ذلك وتفَرَّقت جموع التركمان بالجبال، ومرت العساكر إلى جهة سيس، وأُحضِرَ ابنُ رمضان وأخوه قرا محمد ومن أُمسِك معهما، فوُسِّطوا، وعاد العسكرُ يريد المصيصة، وركبَ الأمير يلبغا الناصري بعسكرِ حلب وسَلَبِهم جَبلًا يُسَمَّى صاروجا شام، وهو مكانٌ ضَيِّقٌ حَرَجٌ وَعْرٌ به جبالٌ شوامخ وأودية عِظام، مُغَلَّقة بالأشجار والمياه والأوحال، وبه دربندات خطرة، لا يكادُ الراجل يسلُكُه، فكيف بالفارِسِ وفَرَسِه الموفرين حملًا باللَّبوس؟! وإذا هم بطائفةٍ مِن التركمان اليراكية، فجرى بينهم القتال الشديد، فقُتِلَ بين الفريقين جماعةٌ، وفُقِدَ الأمير يلبغا الناصري وجماعة من أمراء حلب، وإذا بهم قد تاهوا في تلك الأودية، ثم تراجع الناسُ وقد فُقِدَ منهم طائفة، ووصل الخبر بأن التركمان قد أحاطوا بدربند باب الملك، فالتجؤوا إلى مدينة إياس، ثم قَدِمَ يلبغا الناصري إلى إياس بعد انقطاع خبره، فتباشروا بقدومِه، وأقاموا عليها أيامًا ثم رحلوا، فلقيهم التركمان في جمع كبير، فكانت بينهم وقعةٌ لم يمُرَّ لهم مثلُها، قُتِلَ فيها خلق كثير، وانجَلَت عن كسرة التركمان بعد ما أبلى فيها الناصريُّ بلاء عظيمًا، وارتحل العسكرُ يوم عيد الأضحى إلى جهة بإياس، فما ضُرِبَت خيامهم بها حتى أحاط بهم التركمان وأنفذوا فرقةً منهم إلى باب الملك، فوقَفوا على دربندة ومنعوا عنهم الميرة، فعَزَّت الأقوات عند العسكر، وجاعت الخيولُ، وكَثُرَ الخوف وأشرفوا على الهلاك، إلَّا أن الله تداركهم بخَفِيِّ لُطفِه؛ فقَدِمَ عليهم الخبر بوصول الأمير سودن المظفري حاجِبِ الحجَّاب بحلب في عِدَّة من الأمراء، وقد استخدم من أهل حَلَبٍ ألفَ راجلٍ من شبان بانقوسا، ودفعوا لكل واحد منهم مائة درهم، وخرج العُلَماء والصلحاء وغالِبُ الناس، وقد بلغهم ما نزل بالعسكر، ونودي بالنفيرِ العام، فتَبِعَهم كثير من الرجَّالة والخيَّالة والأكراد ببلد القصير والجبل الأقرع وغيره من أعمال حلب، فقام بمؤنتهم الحاجِبُ ومن معه من الأمراء، وهجموا على باب الملك، فمَلَكوه وقتلوا طائفةً ممن كان به من التركمان، وهزموا بقيَّتَهم، ففرح العسكرُ بذلك فرحًا كبيرًا، وساروا إلى باب الملك حتى جاوزوا دربنده ونزلوا بغراس، ثم رحلوا إلى أنطاكية وقدموا حلب، فكانت سفرةً شديدةَ المشقةِ؛ بُلُوا فيها من كثرةِ تتابع الأمطار الغزيرة، وتوالي هبوب الرياح العاصفة، وكثرة الخوف، ومقاساة آلام الجوع- ما لا يمكِنُ وَصفُه."},{"id":3158,"title":"وفاة عماد الدين ابن بردس البعلبكي .","date":["العام الهجري :786","العام الميلادي :1384"],"text":"هو الشَّيخُ الإمام العالم المقرئُ عماد الدين أبو الفداء إسماعيل بن محمد بن بردس بن نصر بن بردس بن رسلان البعلبكي الحنبلي. ولِدَ ببعلبك سنة720، ودرس على والده، وأبي الفتح اليونيني، وسَمِعَ جمعًا من مُسنِدِي عصره، وحَدَّث عنهم، واشتهر باختصارِه لجملة من الكتب ونَظْمها. له بُغية الأريب في اختصار التهذيب، أكمل مسودته في المحرم سنة 779 وهو اختصار ليس فيه إضافات تُذكَر، ولم يحذف من رجال التهذيب أحدًا، لكنه حذف بعض أنساب المشهورين، وذكر الجرح والتعديل مختصرًا، كما حذف الأسانيدَ."},{"id":3159,"title":"تنظيم الخيالة العثمانيين سياه .","date":["العام الهجري :786","العام الميلادي :1384"],"text":"نظَّمَ القائِدُ الوزير تيمور طاش باشا فِرَق الخيَّالة العثمانيين المسمَّاة سياهيه أو سياه- على نظام جديد، واختار أن تكون أعلامهم باللون الأحمر الذي لا يزال شعارَ الدَّولة التركية حتى الآن، وأقطع كلَّ نَفَرٍ منهم جزءًا من الأرض يزرعه أصحابه الأصليون مسيحيين كانوا أو مسلمين في مقابلة دَفعِ جُعْلْ مُعَيَّن لصاحب الإقطاع، وذلك بشرط أن يسكنَ الجنديُّ في أرضه وقت السلمِ ويستَعِدَّ للحرب عند الاقتضاءِ على نفقَتِه، وأن يُقَدِّمَ أيضًا جنديًّا آخر معه، وكان كل إقطاع لم يتجاوزْ إيراده السنوي عشرين ألف غرش، يسمى تيمار، وما زاد إيراده على ذلك يسمى زعامت، وكانت هذه الإقطاعات لا يرثها إلَّا الذكور من الأعقابِ، وإذا انقرضت الذرية من الذكور ترجِعُ إلى الحكومة، وهي تُقطِعُها إلى جندي آخر بنفس هذه الشروط"},{"id":3160,"title":"خلع أبي العباس ملك بني مرين ومبايعة أبي فارس .","date":["العام الهجري :786","الشهر القمري : ربيع الأول","العام الميلادي :1384"],"text":"خُلِعَ السُّلطانُ أبو العباس أحمد المستنصر بن إبراهيم بن أبي الحسن المريني مَلِكُ المغرب صاحب فاس ونُفي إلى غرناطة، وبُويع بدلًا منه أبو فارس موسى بن أبي عنان المتوكل على الله، وكان مقيمًا بالأندلس، وتولى الوزير مسعود بن ماساي الأمورَ."},{"id":3161,"title":"نزول مركبين من مراكب الفرنج على رشيد .","date":["العام الهجري :786","الشهر القمري : ربيع الآخر","العام الميلادي :1384"],"text":"نزل مركبانِ مِن مراكِبِ الفرنج على رشيدٍ، فخرج الأميرُ يونس الدوادار، والأمير ألطنبغا المعلم، فلم يُدركوهم."},{"id":3162,"title":"العثمانيون يقاتلون أمير القرمان  .","date":["العام الهجري :787","العام الميلادي :1385"],"text":"قام أميرُ دولة القرمان علاءُ الدين وبعضُ الأمراء المستقلين بحَربِ الدَّولةِ العثمانية فأرسل لهم مرادٌ الأول جيشًا انتصر عليهم في سهل قونية، وأخذ الأميرَ علاء الدين أسيرًا، غير أنَّ ابنته زوجةَ السلطان قد توسطت له فأطلَقَ سَراحَه وأبقى له إمارتَه، ولكنه فرض عليه دفع مبلغٍ من المال سنويًّا."},{"id":3163,"title":"الظفر بمراكب للفرنج مقابل دمياط .","date":["العام الهجري :787","الشهر القمري : جمادى الآخرة","العام الميلادي :1385"],"text":"في يوم الأربعاء سابعَ عشر جمادى الآخرة قَدِمَ الخبر بأن شواني الأمير ألطنبغا الجوباني سارت من ثغر دمياط في بحرِ الملح، فوجدوا مركبًا فيه الفرنج الجنوية، فأخذوه وأسَروا منهم خمسة وثلاثين رجلًا، وقتلوا منهم جماعةً، ثم قدمت الشواني إلى شاطئ النيل ببولاق خارج القاهرة بالأسرى والغنيمة، فعُرِضَت الأسرى من الغدِ على السلطان."},{"id":3164,"title":"تيمورلنك يستولي على خراسان وسراي وغيرها من البلاد .","date":["العام الهجري :788","العام الميلادي :1386"],"text":"في المدَّة ما بين782 إلى 786, استولى تيمورلنك على خراسان وجرجان ومازندران وسجستان وأفغانستان، وفارس وأذربيجان وكردستان، ثمَّ في هذا العام دَبَّ الخلاف بين تيمورلنك وبين توقتاميش؛ إذ هاجم الأخيرُ ضواحيَ سمرقند ولم يكُنْ تيمورلنك فيها، فلما عاد تيمورلنك إلى قاعدة حكمه في سمرقند رجع توقتاميش إلى بلاده، ولم يمضِ طويلُ وقت حتى عاد توقتاميش للإغارةِ مَرَّةً أخرى على سمرقند؛ ممَّا شجع خوارزم على إعلان العصيان على تيمورلنك وتراجع توقتاميش بنيَّة استدراج تيمورلنك إلى سيبريا؛ لينقَضَّ عليه هناك، فسار تيمورلنك نحوَ الجرجانية إحدى مدن خوارزم، وفعل بأهلها الأفاعيل ليُرهِبَ به الأعداء، ثم إن تيمورلنك وتوقتاميش التقَيَا على نهر أورال وانتصر تيمورلنك في هذه المعركة، وتابع تيمورلنك مسيرَه ففتح مدينة سراي عاصمة مغول الشمال أو القبيلة الذهبية."},{"id":3165,"title":"هزيمة الشريف جماز بن هبة بالمدينة النبوية .","date":["العام الهجري :788","العام الميلادي :1386"],"text":"حضر الشَّريفُ جماز بن هبة المدينةَ النبوية بحشده، فحاربه عليُّ بن عطية، وهزمه عنها."},{"id":3166,"title":"هجوم الصرب على أراضي العثمانيين .","date":["العام الهجري :788","العام الميلادي :1386"],"text":"استغل الصِّربُ انشغال الجيوش العثمانية بحروبها مع الأمير علاء الدين أمير القرمان، فهاجموا القواتِ العُثمانية في جنوب الصرب من ألبانيا، وحصلوا على بعض النجاحِ سنة 788."},{"id":3167,"title":"وفاة السلطان موسى بن أبي عنان ملك المغرب وتولي الواثق محمد .","date":["العام الهجري :788","العام الميلادي :1386"],"text":"هو السُّلطانُ موسى ابن السلطان أبي عنان فارس بن أبي الحسن المريني مَلِك المغرب صاحب مدينة فاس وما والاها، توفي في جمادى الآخرة، وأقيم بعده المستنصر محمد بن أبي العباس أحمد المخلوع، ابن أبي سالم فلم يَتِمَّ أمرُه وخُلِعَ بعد قليل، وأقيم الواثق محمد بن السلطان أبي الحسن، كل ذلك بتدبير الوزير ابن مسعود، وهو يوم ذاك صاحب أمر فاس."},{"id":3168,"title":"نشوب قتال بين عساكر الشام والتركمان .","date":["العام الهجري :788","الشهر القمري : ربيع الآخر","العام الميلادي :1386"],"text":"في أولِ جمادى الآخرة سار عساكر الشام لمحاربة التركمان، وكانت بينهم وقعةٌ عظيمة، قُتِلَ فيها سبعةَ عشر أميرًا، منهم سودن العلائي نائب حماة، وقتل من الأجناد خلق كثير، وانكسر بقية العسكر."},{"id":3169,"title":"وفاة الخليفة العباسي الواثق عمر وتولية أخيه المستعصم زكريا .","date":["العام الهجري :788","الشهر القمري : شوال","العام الميلادي :1386"],"text":"هو الخليفةُ العباسي الواثِقُ عُمَرُ ابن الخليفة المستعصم بالله أبي إسحاق إبراهيم بن المستمسك بالله أبي عبد الله محمد بن الإمام الحاكم بأمر الله أبي العباس أحمد بن الحسن بن أبي بكر بن أبي علي إسحاق بن علي القبي. في يوم الاثنين الخامس والعشرين من شوال استدعى السلطانُ برقوق زكريَّا ابنَ الخليفة المعتصم بالله وأعلمه أنَّه يريد أن ينصِبَه في الخلافةِ بعد وفاة أخيه الواثق بالله عمر، ثم استدعى السلطانُ القضاة والأمراء والأعيان، فلما اجتمعوا أظهر زكريا المذكور عَهدَ عَمِّه المعتضد له بالخلافة، فخلع السلطانُ عليه خِلعةً غير خلعة الخلافةِ ونزل إلى داره، فلما كان يوم الخميس الثامن والعشرين منه طلع الخليفة زكريا إلى القلعةِ وأحضر أعيانَ الأمراء والقضاة والشيخ سراج الدين عمر البلقيني، فبدأ البلقينيُّ بالكلام مع السلطان في مبايعة زكريا على الخلافةِ، فبايعه السلطان أولًا، ثم بايعه من حضر على مراتِبِهم، ونُعِتَ بالمستعصم بالله، وخُلِعَ عليه خِلعةُ الخلافة على العادة، ونزل إلى داره وبين يديه القضاة وأعيان الدولة، ثم طلع زكريا في يوم الاثنين ثاني ذي القعدة وخلع عليه السلطان ثانيًا بنَظَرِ المشهد النفيسي على عادة من كان قبلَه مِن الخلفاء."},{"id":3170,"title":"اغتيال أمير مكة الشريف محمد بن عجلان وتولي أبي عنان مكانه .","date":["العام الهجري :788","الشهر القمري : ذي الحجة","العام الميلادي :1387"],"text":"كان جركس الخليلي أميرًا على الحاج، وكان السلطانُ أوصاه بعَزلِ الصبي المنصوب الشريف محمد أحمد بن عجلان وأن يستبدلَ به الشَّريفَ أبي عنان بن مغامس، والقبض على عمِّ الصبي كبيش بن عجلان، ولما وصل الحاجُّ إلى مكة وخرج الصبيُّ لتلَقِّي المَحمَل الخلافي، وقد أرصد الرجال للبطش بكبيشٍ وأميره المنصوبِ، فقعد كبيش عن الحضور، وجاء الصبي وترجَّلَ عن فَرَسِه لتقبيلِ خُفِّ الجَمَل الذي عليه المحمل كالعادة، وثب به أولئك المُرصَدون طعنًا بالخناجر يظنونَه كبيشًا, وفَطِنَ كبيش لذلك فجمع عساكِرَه وخرج من مكة بهم خوفًا على نفسِه وخوفًا على الحاجِّ من النهب, وحجَّ النَّاسُ آمنين، وأقام الأمراءُ لابسين السلاح سبعة أيام؛ خوفًا من الفتنة، فلم يتحَرَّكْ أحد، وقرر جركس الخليلي الشريف أبي عنان خِلعَتَه، وتسَلَّم مكة، وخطب له بها. ثم التقى كبيش بن عجلان ببطا الخاصكي رأس المبشرين، فقال له: أعلِمِ السلطانَ أنني طائعٌ، وأنني منعت العَرَبَ مِن نهب الحاجِّ، وأنني لا أرجع عن طَلَبِ ثأري من غريمي الشَّريفِ أبي عنان، وفَرَّقَ الخليلي بمكة صدقاتٍ كثيرةً جدًّا."},{"id":3171,"title":"السلطان الظاهر برقوق يستجلي أخبار تيمورلنك .","date":["العام الهجري :789","الشهر القمري : ربيع الآخر","العام الميلادي :1387"],"text":"أرسل السلطانُ الظاهر برقوق من يستجلي أخبارَ تيمورلنك، فجاءت الأخبار وورد البريد بأنَّ تيمورلنك كبس قرا محمد وكَسَره، ففَرَّ منه في نحو مائتي فارس، ونزل قريب ملطية، ونزل تيمورلنك على آمد، فاستدعى السلطانُ القضاة والفقهاء والأمراء وتحدث في أخذ الأوقافِ من الأراضي الخراجيَّة، فكَثُر النِّزاعُ، وآل الأمر إلى أنه يأخُذُ مُتحَصَّل الأوقاف لسنةٍ، ورسم السلطانُ بتجهيز أربعة من الأمراء الألوف، وهم الأميرُ ألطنبغا المعلم أمير سلاح، والأمير قردم الحسني، والأمير يونس الدوادار، والأمير سودن باق، وسبعة من أمراء الطبلخاناه، وخمسة من أمراء العشرات، فتجهزوا وعُيِّنَ معهم من أجناد الحلقة ثلاثمائة فارس، وخرجوا من القاهرة في أول رجب، فساروا إلى حلب، وبها يومئذٍ في نيابة السلطنة سودن المظفري، وقَدِمَ الخبَرُ بوقعة بين قرا محمد وولد تيمورلنك انكسَرَ فيها ابن تيمورلنك، وفي تاسع عشر رجب رُسِمَ للقاضي جمال الدين محمود محتَسِبِ القاهرة بطلبِ التجَّار وأرباب الأموال، وأخْذِ زكَوات أموالهم، وأن يتولى قاضي القضاة الحنفية شمس الدين محمد الطرابلسي تحليفَهم على ما يدَّعونَ أنَّه مِلكُهم، فعُمِلَ ذلك يومًا واحدًا، ثم رد عليهم ما أُخِذَ منهم وبَطَل، فإنَّ الخبَرَ ورد برجوع تيمورلنك إلى بلادِه."},{"id":3172,"title":"خلع الواثق محمد ملك بني مرين وتولية أبي العباس المخلوع سابقا .","date":["العام الهجري :789","الشهر القمري : رمضان","العام الميلادي :1387"],"text":"خُلع الواثِقُ محمد بن أبي الفضل بن أبي الحسن، وأعيد السلطانُ المخلوع أبو العباس أحمد بن أبي سالم إبراهيم بن أبي الحسن، وكان منفيًّا في غرناطة بعد أن خلع سنة 786، فملك فاس في خامس رمضان، وحُمِلَ الواثق إلى طنجة، فسُجِنَ بها ثم قتل، وكلُّ هذه الأمور حدثت بتدبير الوزير بن ماساي؛ مما دعا أبا العباس أحمد إلى قَتْلِه."},{"id":3173,"title":"عصيان نائب حلب يلبغا الناصري على السلطان برقوق .","date":["العام الهجري :790","الشهر القمري : جمادى الأولى","العام الميلادي :1388"],"text":"خرج الأميرُ يلبغا الناصري نائِبُ حلب عن طاعة السلطان برقوق؛ وذلك لأن السلطان أصلًا كان من مماليكِه، فأبى أن يكونَ مِن تابعيه، وخاصةً أنَّ السُّلطانَ كان يقبض على الكثير من الأمراء بأدنى ريبةٍ؛ مِمَّا أوغر صدورَهم تجاهه، وانضمَّ إلى يلبغا أمير ملطية الأمير تمربغا الأفضلي المعروف باسم منطاش، فأرسل السلطان العساكِرَ لإعادتهم إلى الطاعة، ثمَّ في حادي عشر من جمادى الأولى ورد صراي تَمُر- دوادار الأمير يونس الدوادار، ومملوك نائب حلب - على البريد بأن العسكَرَ توجَّه إلى سيواس، وقاتل عسكَرَها، وقد استنجدوا بالتترِ، فأتاهم منهم نحو الستين ألفًا، فحاربوهم يومًا كاملًا وهزموهم، وحصروا سيواس بعدما قُتِلَ كثير من الفريقين وجُرح معظمهم، وأنَّ الأقواتَ عندهم عزيزةٌ، فجهَّز السلطان إلى العسكر مبلغ خمسين ألف دينار مصرية، وسار بها تُلَكتمُر الدوادار في السابع والعشرين، ثم إن العسكر تحركوا للرحيلِ عن سيواس، فهجم عليهم التتار من ورائهم، فبرز إليهم الأمير يلبغا الناصري نائب حلب، وقَتَل منهم خلقًا كثيرًا، وأسر نحو الألف، وأخذ منهم العسكرُ نحو عشرة آلاف فرس، وعادوا سالمين إلى جهة حلب."},{"id":3174,"title":"وفاة الشاطبي المالكي الأندلسي صاحب الموافقات .","date":["العام الهجري :790","الشهر القمري : شعبان","العام الميلادي :1388"],"text":"هو الإمامُ العلَّامة أبو إسحاق إبراهيم بن موسى بن محمد اللخمي الغرناطي الشاطبي، نسبةً إلى شاطبة بالأندلس، ولد بغرناطة ونشأ بها, كان من علماء الأصول والحديث، بارعًا في العلوم وخاصة الأصول، كان من علماء المالكية، له تصانيف أشهرُها: كتاب الموافقات، وهو في أصول الفقه، وكتاب الاعتصام الذي عالج فيه موضوع البِدَع، وله الإفادات والإنشادات، ورسالة في الأدب والطرف، وشرح الألفية، وأصول النحو، وغيرها."},{"id":3175,"title":"وفاة الشيخ بهاء الدين النقشبندي مؤسس الطريقة النقشبندية .","date":["العام الهجري :791","الشهر القمري : ربيع الأول","العام الميلادي :1389"],"text":"هو الشَّيخُ بهاءُ الدين محمد بن محمد البخاري النقشبندي، مؤسِّسُ الطريقةِ النقشبندية الصوفية المعروفة، يزعُمُ أنَّ مدارَها تصحيح العبودية ودوام العبادة لله ودوام الحضور مع الحَقِّ سُبحانَه، وأنَّ الطريقَ إلى هذا هو الذِّكرُ والمراقبة والرابطة بالشيخ والتخلي عن كلِّ شَيءٍ إلَّا عن محبته، وتتَّبِعُ هذه الطريقةُ التخلِّيَ أو الخلوة، وتوجيه الباطن إلى الله عن طريق الرابطة بالشيخ، وهي ما يسمُّونه الرابطة الشريفة، ولهم أورادٌ يتداولونها حَسَبَ طريقتِهم هذه، وحضرات كما لغيرهم من الصوفية، وقد تفَرَّع عن هذه الطريقة عِدَّةُ طُرُق مثل المحمدية والأحمدية، والزبيرية والمظهرية، وغيرها."},{"id":3176,"title":"إعادة الخليفة العباسي المتوكل للخلافة بدلا من المستعصم زكريا .","date":["العام الهجري :791","الشهر القمري : جمادى الأولى","العام الميلادي :1389"],"text":"قام السُّلطانُ الظاهر برقوق بإعادةِ الخليفة المتوكِّل للخلافة بعدما كان قد خلعه عام 785, وسجنه بقلعة الجبل وقتَها، ولَمَّا أحَسَّ بالخطر الذي حَوْلَه من عصيان الناصري عليه والأمراء الذين معه؛ لعله أراد بذلك كسب الرضا أكثر، ففي يوم الجمعة عاشر جمادى الأولى من هذه السنة خُطِبَ للخليفة المتوكل على الله أبي عبد الله محمد، فإنَّه أعيد إلى الخلافة ثم قرئ تقليدُه في الثاني عشر بالمشهد النفيسي، وحضره القضاةُ ونائب السلطنة."},{"id":3177,"title":"عصيان الأمراء على السلطان برقوق وخلعه وإعادة السلطان حاجي .","date":["العام الهجري :791","الشهر القمري : جمادى الآخرة","العام الميلادي :1389"],"text":"عصى الأميرُ يلبغا الناصريُّ نائِبُ حَلَب على السلطان برقوق، وأمر السلطانُ بخروج العسكر إليه، ولكن الأمير قرابغا فرج الله والأمير بزلار العمري الناصري والأمير دمرداش اليوسفي والأمير كمشبغا الخاصكي الأشرفي وآقبغا قبجق، اجتمع معهم عدَّةٌ كثيرة من المماليك المنفيِّين بطرابلس، وثبوا على نائبها الأمير أسندمر المحمدي وقبضوا عليه، وقتلوا من أمراءِ طرابلس الأميرَ صلاح الدين خليل بن سنجر وابنه، وقبضوا على جماعةٍ كبيرة من أمراء طرابلس، ثمَّ دخل الجميعُ في طاعة الناصري، وكاتبوه بذلك ومَلَكوا مدينة طرابلس، ثمَّ إنَّ مماليك الأمير سودون العثماني نائِبِ حماة اتَّفَقوا على قتله، ففر منهم إلى دمشق، وأنَّ الأمير بيرم العزي حاجِبَ حجَّاب حماة سَلَّم حماة إلى الأمير يلبغا الناصري ودخل تحت طاعته، ثم تواترت الأخبار على السلطان بدخول سائر الأمراء بالبلاد الشاميَّة والمماليك الأشرفيَّة واليلبغاوية في طاعة الناصري، وكذلك الأميرُ سولي بن دلغادر أمير التركمان، ونعير أمير العربان، وغيرهما من التركمان والأعراب، دخل الجميعُ في طاعة الناصري على محاربة السلطانِ الملك الظاهر برقوق، وأنَّ الناصري أقام أعلامًا خليفتيَّة، وأخذ جميعَ القلاع بالبلاد الشاميَّة، واستولى عليها ما خلا قلعةَ الشام وبعلبك والكرك، ثم في يوم الثلاثاء أول ربيع الآخر قَدِمَ البريد بأنَّ الأمير كمشبغا المنجكي نائِبَ بعلبك دخل تحت طاعة يلبغا الناصري، وكذلك في خامِسِه قَدِمَ البريد بأن ثلاثة عشر أميرًا من أمراء دمشق ساروا إلى حلب ودخلوا في طاعة الناصري، وأما العسكر المصري الظاهري فإنه سار من غزَّةَ حتى دخل دمشق في يوم الاثنين سابع شهر ربيع الآخر، ودخلوا دمشق بعد أن تلقَّاهم نائبها الأمير حسام الدين طرنطاي، ودخلوا دمشق قبل وصول الناصري بعساكره إليها بمدة، وأقبل المماليكُ السلطانية على الفَسادِ بدمشق، واشتغلوا باللَّهوِ، وأبادوا أهلَ دمشق، حتى سَئِمَتهم أهل الشام وانطلقت الألسنةُ بالوقيعة فيهم وفي مُرسِلِهم، وبينما هم في ذلك جاءهم الخبَرُ بنزول يلبغا الناصري بعساكره على خان لاجين خارج دمشق في يوم السبت تاسع عشر شهر ربيع الآخر، فعند ذلك تهيَّأ الأمراء المصريون والشاميون إلى قتالِهم، وخرجوا من دمشق في يوم الاثنين في الحادي والعشرين إلى برزة، والتقوا بالناصري على خان لاجين، وتصافُّوا ثم اقتَتَلوا قتالًا شديدًا ثَبَت فيه كلٌّ من الفريقين ثباتًا لم يُسمَعْ بمِثلِه، ثم تكاثر العسكَرُ المصري وصَدَقوا الحملة على الناصري ومن معه، فهزموهم وغيَّروه عن موقفه، ثم تراجع عسكر الناصري وحمل بهم، والتقى العسكَرُ السلطاني ثانيًا واصطدما صدمةً هائلة ثبت فيها أيضًا الطائفتانِ وتقاتلا قتالًا شديدًا، قُتلَ فيها جماعة من الطائفتين، حتى انكسر الناصريُّ ثانيًا، ثم تراجع عسكَرُه وعاد إليهم والتقاهم ثالثَ مَرَّة، فعندما تنازلوا في المرة الثالثة والتحم القتالُ لَحِقَ الأمير أحمد بن يلبغا بعساكِرِ الناصري بمن معه من مماليكه وحواشيه، ثم تَبِعَه الأمير أيدكار العمري حاجِبُ الحجاب أيضًا بطَلَبِه ومماليكه، ثم الأمير فارس الصرغتمشي ثم الأمير شاهين أمير آخور بمن معهم، وعادوا قاتلوا العسكر المصري، فعند ذلك ضَعُفَ أمرُ العساكر المصرية وتقهقروا وانهزموا أقبحَ هزيمة، فلما ولَّوا الأدبار في أوائل الهزيمة، هَجَم مملوكٌ من عسكر الناصري يقال له يلبغا الزيني الأعور وضرب الأميرَ جاركس الخليلي بالسيف فقتَلَه وأخَذَ سَلَبَه، وترك رمَّتَه عاريةً، إلى أن كفَّنَتْه امرأة بعد أيام ودفنته، ثم مَدَّت التركمان والعرب أيديَهم ينهبون من انهزم من العسكر المصري ويقتُلون ويأسرون من ظَفِروا به، وساق الأميرُ الكبير أيتمش البجاسي حتى لحق بدمشق وتحصَّن بقلعتها، وتمزَّق العسكر المصري وذهب كأنَّه لم يكن، ودخل الناصريُّ من يومه إلى دمشق بعساكره، ونزل بالقَصرِ من الميدان، وتسَلَّم القلعة بغير قتال، وأوقع الحوطةَ على سائر العسكر، وأنزل بالأميرِ الكبير أيتمش وقَيَّده هو والأمير طرنطاي نائب الشام وسجَنَهما بقلعة دمشق، وتتبَّعَ بقيَّةَ الأمراء والمماليك حتى قبض من يومِه أيضًا على الأمير بكلمش العلائي في عدة من أعيان المماليك الظاهرية، فاعتقلهم أيضًا بقلعة دمشق، ثم مَدَّت التركمان والأجناد أيديَهم في النهب، فما عَفَوا ولا كفُّوا وتمادَوا على هذا عدة أيام، وقَدِمَ هذا الخبر على الملك الظاهر برقوق من غزة في يوم السابع والعشرين من شهر ربيع الآخر، فاضطرب الناسُ اضطرابًا عظيمًا، لا سيَّما لما بلغهم قتل الأمير جاركس الخليلي والقبض على الأمير الكبير أيتمش البجاسي، وغُلِّقَت الأسواق، وانتُهِبَت الأخباز، وتشغبت الزعر، وطغى أهلُ الفساد، هذا مع ما للنَّاسِ فيه من الشغل بدفن موتاهم، وعِظَم الطاعون بمصر، وأما السلطان الملك الظاهر برقوق فإنه لما بلغه ما وقع لعسكره وَجَمَ وتحَيَّرَ في أمره، وعَظُم عليه قتلُ جاركس الخليلي والقبض على أيتمش أكثَرَ من انهزام عسكره، فإنَّهما ويونس الدوادار كانوا هم القائمينَ بتدبير مُلكِه، وأخذ يفحصُ عن أخبار يونس الدوادار فلم يقِفْ له على خبر؛ لسرعة مجيء خبَرِ الوقعة له من مدينةِ غزة، ولم يأتِه أحَدٌ ممن باشر الواقعة، غيرَ أنَّه صَحَّ عنده ما بلغه، وبقَتلِ يونس الدوادار استشعر كلُّ أحد بذهاب مُلْك المَلِك الظاهر، ثم قدم الخبر بدخول الأمير مأمور القلمطاوي نائب الكرك في طاعة الناصري، وأنَّه سَلَّم له الكرك بما فيها من الأموال والسلاح، ثم أخذ السلطان ينقلُ إلى قلعة الجبل المناجيقَ والمكاحل والعُدَد، وأمر السلطانُ سُكَّان قلعةِ الجَبَلِ من الناس بادِّخار القوتِ بها لشهرينِ، وسار الناصريُّ بمن معه من العساكر يريد الديارَ المصريَّة، وهو يظُنُّ أنه يلقى العساكِرَ المصرية بالقرب من الشام، واستمَرَّ في سَيرِه على هِينةٍ إلى أن وصل إلى غزَّة، فتلقَّاه نائبها حسام الدين بن باكيش بالتقادُم والإقامات، فسأله الناصري عن أخبار عسكر مِصرَ، فقال: لم يَرِدْ خَبَرٌ بخروج عسكر من مصر، ثم سار الناصري من الغد يريد ديار مصر، وأرسل أمامَه جماعة كبيرة من أمرائه ومماليكِه كَشَّافة، واستمَرَّ في السير إلى أن نزلَ مدينة قطيا، وجاء الخبَرُ بنزول الناصري بعساكِرِه على قطيا، فلم يتحرك السلطان بحركة، وفي ليلة وصول الخبَرِ فَرَّ من أمراء مصر جماعة كبيرة إلى الناصري، وهي ليلةُ الثلاثاء ثامن عشرين جمادى الأولى، ثم في يوم الجمعة نزلت عساكِرُ الناصري بالبئر البيضاء، فأخذ عند ذلك عسكَرُ السلطان يتسَلَّلُ إلى الناصري شيئًا بعد شيءٍ، ثمَّ نَصَب السلطان السناجق السلطانية على أبراج القلعة، ودُقَّت الكوسات الحربية، فاجتمعت العساكِرُ جميعها، وعليهم آلةُ الحرب والسلاح، ثم ركِبَ السلطان والخليفة المتوكل على الله معه من قلعة الجبلِ بعد العصر، وسار السلطانُ بمن معه حتى وقفا خلفَ دار الضيافة، وقد اجتمع حولَ السلطان من العامَّةِ خلائِقُ لا تُحصى كثرةً، فوقف هناك ساعة، ثم عاد وطلع إلى الإسطبل السلطاني، وجلس فيه مِن غير أن يلقى حَربًا، ثم ركب السلطان ثانيًا من القلعةِ، ومعه الخليفةُ المتوكل على الله، ونزل إلى دار الضيافة، فقدم عليه الخبَرُ بأن طليعة الناصري وصلت إلى الخراب طرف الحسينية، فلقيتهم كشافة السلطان فكسَرَتهم، ثم ندب السلطانُ الأمراء فتوجَّهوا بالعساكر إلى جهة قبَّة النصر، ونزل السلطانُ ببعض الزوايا عند دار الضيافة إلى آخر النهار، ثم عاد إلى الإسطبل السلطاني وصحبته الأمراء الذين توجَّهوا لقبة النصر، والكوسات تُدَقُّ، وهم على أُهبة اللقاء وملاقاة العدو، وخاصكية السلطان حوله، والنفوطُ لا تفتُرُ، والرميلة قد امتلأت بالزعر، والعامة ومماليك الأمراء، ولم يزالوا على ذلك حتى أصبحوا يوم الاثنين، وإذا بالأمير آقبغا المارديني حاجب الحجاب والأمير جمق بن أيتمشر البجاسي والأمير إبراهيم بن طشتمر العلائي الدوادار قد خرجوا في الليل ومعهم نحو خمسمائة مملوك من المماليك السلطانية ولحِقوا بالناصري، ثم أصبح السلطانُ من الغد، وهو يوم خامس جمادى الآخرة، فَرَّ الأمير قرقماس الطشتمري الدوادار الكبير، وقرا دمرداش الأحمدي أتابك العساكر بالديار المصرية، والأمير سودون باق، أمير مجلس ولحقوا بالناصري، ولما بلغ السلطان نفاقُ هؤلاء الأمراء عليه بعد أن أنعم عليهم بهذه الأشياء، علم أن دولته قد زالت، فأغلق في الحالِ باب زويلةَ وجميع الدروب، وتعطَّلَت الأسواق، وامتلأت القاهرةُ بالزعر، واشتدَّ فسادَهم، وتلاشت الدولةُ الظاهرية وانحَلَّ أمرُها، وخاف والي القاهرة حسام الدين بن الكوراني على نفسِه، فقام من خلف باب زويلة وتوجَّه إلى بيته واختفى، وبَقِيَ الناس غوغاء، وقطع المسجونون قيودَهم بخزانة شمائل، وكَسَروا باب الحبس وخرجوا على حميةٍ جملةً واحدة، فلم يرُدَّهم أحدٌ؛ لشُغلِ كُلِّ واحد بنفسه، وكذلك فعَلَ أهل حبس الديلم، وأهلُ سجن الرحبة، هذا والسلطان إلى الآن بقلعة الجبل، والنفوطُ عَمَّالة، والكوسات تُدَقُّ حربيًّا، ثم أمر السلطان مماليكَه فنزلوا ومنعوا العامَّةَ من التوجه إلى يلبغا الناصري، فرجمهم العامَّةُ بالحجارة، فرماهم المماليكُ بالنشَّاب، وقتلوا منهم جماعةً تزيد عِدَّتُهم على عشر أنفس، ثم أقبلت طليعة الناصري مع عِدَّة من أعيان الأمراء من أصحابِه، فبَرَز لهم الأمير قجماس ابن عم السلطان في جماعة كبيرة وقاتلهم، وأكثر الرمي عليهم من فوق القلعة بالسهام والنفوط والحجارة بالمقاليع، وهم يوالون الكَرَّ والفَرَّ غَيرَ مَرَّة، وثبتت المماليك السلطانية ثباتًا جيدًا، غير أنهم في عِلمٍ بزوال دولتهم، هذا وأصحابُ السلطان تتفَرَّقُ عنه شيئًا بعد شيء، فمنهم من يتوجه إلى الناصري، ومنهم من يختفي خوفًا على نفسه، حتى لم يبقَ عند السلطان إلا جماعةٌ يسيرة ممن ذكرنا من الأمراء، فلما كان آخِرُ النهار أراد السلطان أن يسَلِّمَ نفسَه، فمنعه من بقِيَ عنده من الأمراء وخاصكيته، ثم بعد العصر من اليوم قَدِمَ جماعة من عسكر الناصري عليهم الطواشي طقطاي الرومي الطشتمري، والأمير بزلار العمري الناصري، وكان من الشجعان، والأمير ألطنبغا الأشربي، في نحو الألف وخمسمائة مقاتل يريدون القلعة، فبرز لهم الأمير بطا الطولوتمري الظاهري الخاصكي، والأمير شكر باي العثماني الظاهري، وسودون شقراق في نحو عشرين مملوكًا من الخاصكية الظاهرية، وتلاقوا مع عسكر الناصري فصدموهم صدمةً واحدة كسروهم فيها وهزموهم إلى قبة النصر، ولم يُقتَلْ منهم غير سودون شقراق؛ فإنَّه أُمسِكَ وأُتي به إلى الناصري فوسَّطه، ولم يَقتُل الناصريُّ في هذه الوقعة أحدًا غيره، لا قبله ولا بعده- يعني صَبرًا- غيرَ أن جماعة كبيرة قُتِلوا في المعركة، وورد الخبَرُ بنصرتهم على الملك الظاهر، فلم يغتَرَّ بذلك، وعلم أنَّ أمرَه قد زال، فأخذ في تدبيرِ أمره مع خواصه، فأشار عليه من عنده أن يستأمِنَ من الناصري، فعند ذلك أرسل الملك الظاهر الأمير أبا بكر بن سنقر الحاجب والأمير بيدمر المنجكي شاد القصر بالنمجاة إلى الأمير يلبغا الناصري أنْ يأخذا له أمانًا على نفسِه، ويترققا له، فسارا من وقتهما إلى قبة النصر، ودخلا على الناصري وهو بمخَيَّمه، واجتمعا به في خلوةٍ، فأمَّنَه على نفسه، وأخذَ منهما منجاة الملك- سيف خاص بالملك أو السلطان- وقال: الملك الظاهر أخونا وخشداشنا- زميلنا في المهنة- ولكِنَّه يختفي بمكان إلى أن تُخمَدَ الفتنة، فإنَّ الآن كل واحد له رأي وكلام، حتى ندَبِّرَ له أمرًا يكون فيه نجاتُه، فعادا بهذا الجواب إلى الملك الظاهر برقوق، وأقام السلطانُ بعد ذلك في مكانه مع خواصِّه إلى أن صلى عشاء الآخرة، وقام الخليفةُ المتوكل على الله إلى منزله بالقلعةِ على العادة في كلِّ ليلة، وبقي الملك الظاهر في قليل من أصحابه، وأذِنَ لسودون النائب في التوجُّه إلى حال سبيله والنظَرِ في مصلحة نفسه، فودَّعَه وقام ونزل من وقته، ثم فَرَّق الملك الظاهر بقيَّة أصحابه، فمضى كلُّ واحد إلى حال سبيله، ثم استتر الملك الظاهر وغيَّرَ صِفَتَه، حتى نزل من الإسطبل إلى حيث شاء ماشيًا على قَدَمَيه، فلم يَعرِفْ له أحد خبرًا، وانفَضَّ ذلك الجمع كلُّه في أسرع ما يكون، وسكَنَ في الحال دَقُّ الكوساتِ ورَمْيُ مدافع النفط، ووقعَ النَّهبُ في حواصل الإسطبل، حتى أخذوا سائِرَ ما كان فيه من السروج واللجم وغيرها والعبي، ونهبوا أيضًا ما كان بالميدان من الغَنَمِ الضأن، وكان عِدَّتُها نحو الألفي رأس، ونُهِبَت طباق المماليك بالقلعة، وطار الخبَرُ في الوقت إلى الناصري، فلم يتحَرَّك من مكانه، ودام بمخَيَّمه، وأرسل جماعةً من الأمراء من أصحابه، فسار من عسكره عِدَّةٌ كبيرة واحتاطوا بالقلعة، وأصبح الأمير يلبغا الناصري بمكانه، وهو يوم الاثنين خامس جمادى الآخرة، وندب الأمير منطاش في جماعة كبيرة إلى القلعة، فسار منطاش إلى قلعة الجبل في جموعه، وطلع إلى الإسطبل السلطاني، فنزل إليه الخليفةُ المتوكل على الله أبو عبد الله محمد، وسار مع منطاش إلى الناصري بقبَّة النصر، حتى نزل بمخَيَّمه، فقام الناصري إليه وتلقَّاه وأجلسه بجانبه ووانسه بالحديث، وأمَّا الناصري فإنه لَمَّا نزل إليه الخليفة وأكرمه، وحضَرَ قضاة القضاة والأعيان للهناء، أمَرَهم الناصري بالإقامة عنده، وأنزل الخليفةَ بمُخَيَّم، وأنزل القضاةَ بخَيمةٍ أخرى ثم طلب الناصريُّ مَن عنده من الأمراء والأعيان وتكَلَّم معهم فيما يكون، وسألهم فيمن يُنصَب في السلطنةِ بعد الملك الظاهر برقوق، فأشار أكابِرُهم بسلطنة الناصري، فامتنع الناصريُّ مِن ذلك أشدَّ امتناع، وهم يُلِحُّونَ عليه ويقولون له: ما المصلحةُ إلَّا ما ذكَرْنا، وهو يأبى، وانفَضَّ المجلس من غير طائل، ثم استدعى الأميرُ الكبير يلبغا الناصري الأمراءَ واستشارهم فيمن ينصِبُه في سلطنة مصر، فكَثُر الكلام بينهم، وكان غَرَضُ غالب الأمراء سلطنة الناصري ما خلا منطاش وجماعة من الأشرفية، حتى استقَرَّ الرأي على إقامة الملك الصالح أمير حاج ابن الملك الأشرف شعبان في السلطنة ثانيًا، بعد أن أعيا الأمراءَ أمرُ الناصري في عدم قبوله السلطنةِ، وهو يقول: المصلحةُ سَلطنةُ الملك الصالح أمير حاج؛ فإن الملك الظاهر برقوقًا خلَعَه من غير مُوجِبٍ، فطلعوا في الحال من الإسطبل إلى القلعة، واستدعَوا الملك الصالح وسَلْطَنوه، وغيَّروا لَقَبَه بالملك المنصور، وأما الملك الظاهر برقوق فإنه دام في اختفائِه إلى أن قُبِضَ عليه بعد أيام متخفيًا في بيت مملوك له، ثم رُسِمَ بسجنه إلى الكرك، فأخرج إليها وسُجِنَ هناك بعد أن حَكَم مصر أميرًا كبيرًا وسُلطانًا إحدى عشرة سنة وخمسة أشهر وسبعة وعشرين يومًا، وزالت دولةُ الملك الظاهر كأن لم تكن، فكانت مُدَّة تحَكُّمه منذ قُبِض على الأمير طَشْتَمُر الدوادار في تاسع ذي الحجة سنة 779، إلى أن جلس على تخت الملك وتلقَّب بالملك الظاهر في تاسع عشر شهر رمضان سنة 784، أربع سنين وتسعة أشهر وعشرة أيام، ويقال له في هذه المدة الأمير الكبير أتابك العساكر، ومن حين تسلطَنَ إلى أن اختفي ست سنين، وثمانية أشهر، وسبعة عشر يومًا، فيكون مدة حكمه أميرًا وسلطانًا إحدى عشرة سنة وخمسة أشهر وسبعة وعشرين يومًا، وترك مُلْكَ مِصرَ وله نحو الألفي مملوك اشتراهم، سوى المُستخدَمينَ."},{"id":3178,"title":"انتصار العثمانيين في موقعة قوص أوه (إقليم كوسوفو)  .","date":["العام الهجري :791","الشهر القمري : جمادى الآخرة","العام الميلادي :1389"],"text":"بعد محاربة الصربِ للعثمانيين سنة 788, وحصولِهم على بعض النجاحِ نتيجةَ انشغال العثمانيين بالحرب مع علاء الدين أمير القرمان، ثم إنَّ أمير البلغار سيسمان تأهَّب للقيام بدوره في محاربة القوات العثمانيةِ، غيرَ أنَّه تفاجأ بها وقد داهمَتْه واحتلَّت بعضَ أجزاء بلاده، ففَرَّ إلى الشمالِ واعتصم في مدينة نيكوبلي القريبة من الحدود الرومانية، وجمع فلولَه مَرَّة أخرى وحارب العثمانيِّينَ إلَّا أنه باء بالهزيمةِ مَرَّة أخرى، ووقع أسيرًا، لكِنِ السلطانُ مراد الأولُ أحسَنَ إليه فأبقاه أميرًا على نصف بلاده، وضَمَّ الباقيَ إلى الدولة العثمانيَّةِ، فلما علم ملك الصرب لازار بهذا، انسحب بجيوشه نحو الغرب منضَمًّا إلى الألبانيين لمحاربة العثمانيينَ معهم، غيرَ أن الجيوش العثمانية أدركَتْه قبل وصوله إلى مبتغاه، والتقت معه في هذه السنة في معركة وسط سهل قوص أوه- إقليم كوسوفو- جنوبي يوغسلافيا، وكان القتالُ سِجالًا بين الطرفين، ثمَّ إنَّ صِهرَ لازار انضَمَّ إلى جانب العثمانيين بفرقته المؤلَّفة من عشرة آلاف مقاتل، فانهزم الصرب ووقع مَلِكُهم لازار أسيًرا جريحًا فقتلوه جزاءَ بما فعله بأسرى المسلمين، وبينما السلطان مراد الأول يتفقد الجرحى في أرض المعركة طَعَنه جريحٌ صِربي فقَتَله!"},{"id":3179,"title":"وفاة مراد الأول بن أورخان وتولي ابنه بايزيد .","date":["العام الهجري :791","الشهر القمري : جمادى الآخرة","العام الميلادي :1389"],"text":"هو السُّلطانُ الغازي أبو الفتح غيَّاث الدنيا والدين: مراد الأول بن أورخان بن عثمان القايوي المعروف بغازي خداوندكار، التُركماني، ولِدَ سنة 726 (1326م). لَمَّا توفِّيَ والده الغازي أورخان سنة 761 جلس على سرير السلطنة, ووُلِدَ ابنُه السلطان يلدرم بايزيد خان عقيب جلوسِه على سرير السلطنة, ولما استَقَرَّ على سرير الملك كان الغزاةُ في روم إيلي منتظرينَ قُدومَه إليهم، فسار وجاوز البحر فاحتَلَّ مدينة أنقرة مقَرَّ سلطنة القرمان، ثم افتتح مدينة أدرنه في أوروبا في هذه السنة، ونقل إليها عاصمته واستمَرَّت عاصمة للدولة العثمانية إلى أن فتح محمد الفاتح مدينة القُسطنطينية سنة 853 (1453م) وفتح أيضًا مراد الأول مدينةَ فيلبه عاصمة الرومللي الشرقية، وفتح القائد أفرينوس بك مدينتي وردار وكلجمينا باسم سلطان العثمانيين، وبذلك صارت مدينة القسطنطينية محاطةً مِن جهة أوروبا بأملاك آلِ عُثمان منذ عَهْدِ مراد الأول, وصارت الدولة العَليَّة متاخمةً لإمارات الصرب والبلغار وألبانيا المستقلة, ولَمَّا دخل الربيع في شعبان سنة 791 خرج السلطان مراد الأول بجيشٍ عَرَمرم فالتقى في أول شهر رمضان بالصِّربِ، وانتصر عليهم, فبينما كان السلطان يتفرج بين القتلى مع أصحابه إذ نهض من بين الصرعى رجلٌ من الصرب، وكان من أمرائِهم، فقصد السلطان، فهَمَّ الحواشي أن يمنَعُوه فنهاهم السلطانُ فجاء كأنَّه يُظهِرُ الطاعة، فضربه بخنجر كان قد خبَّأه في كمِّه فجَرحَه جُرحًا مُنكرًا فلَحِقَ القوم ذلك الصربي فقَتَلوه، ثم خَيَّموا على السلطان طاقةً، فأنزلوه فيها، فلم يمض عليه يوم حتى توفي, فتكون مدةُ سلطنته إحدى وثلاثون سنة، وعمره خمس وستون. وكان قد بنى لنفسِه تربة في قرب جامعه بقبلوجه، فحملوه إلى بروسا –بورصة- مع تابوت ابنه يعقوب جلبي، فدفنوهما في تلك القبَّة، وبنيت قبة في موضع شهادته. قال حاجي خليفة: \"كان مرادُ الأول من أجلِّ الملوك قَدْرًا ودِينًا، وكان دائِمَ الغَزوِ بحيث أفنى عمُرَه في الجهاد، وكان منصورًا في حروبه كثيرَ الخير، مواظِبًا على الجماعات في الصَّلَواتِ\" ثم جلس على سرير السلطنة بعده ابنُه السلطان بايزيد الأول."},{"id":3180,"title":"الفتنة بين الأمير الكبير يلبغا الناصري والأمير تمربغا الأفضلي .","date":["العام الهجري :791","الشهر القمري : شعبان","العام الميلادي :1389"],"text":"استطاع الأميرُ يلبغا الناصري إزالةَ مُلكِ السلطان برقوق، وكان من أعوانه منطاش الأفضلي ولكن لم يكن ما بينهما صافيًا، فلما كان سادس عشر شعبان أشيعَ في القاهرة بتنكُّر منطاش على الناصري، وانقطع منطاش عن الخدمة، وأظهر أنَّه مريض، ففَطِنَ الناصري بأنه يريد أن يعمل مكيدةً، فلم ينزل لعيادتِه، وبعث إليه الأمير ألطنبغا الجوباني رأس نوبة كبيرًا في يوم الاثنين سادس عشر شعبان ليعودَه في مرضه، فدخل عليه وسَلَّم عليه، وقضى حقَّ العيادة وهَمَّ بالقيام، فقَبَض عليه منطاش وعلى عشرين من مماليكِه، وضرب قرقماس دوادار الأمير الجوباني ضربًا مبَرِّحًا، مات منه بعد أيام، ثم رَكِبَ منطاش حالَ مَسْكِه للجوباني في أصحابِه إلى باب السلسلة، وأخذ جميعَ الخيول التي كانت واقفةً على باب السلسلة، وأراد اقتحامَ الباب ليأخُذَ الناصريَّ على حين غفلة، فلم يتمكَّنْ من ذلك وأُغلقَ الباب، ورمى عليه مماليكُ الناصري من أعلى السور بالنشَّاب والحجارة، فعاد إلى بيته ومعه الخيول، وتلاحقت المماليكُ الأشرفية خشداشيته- زملاء مهنته- والمماليك الظاهرية بمنطاش، فعَظُم بهم أمرُه، وقَوِيَ جأشُه، وانضمت اليلبغاوية على الناصريِّ، وهم يوم ذاك أكابِرُ الأمراء وغالِبُ العسكر المصري، وتجمَّعَت المماليك على منطاش حتى صار في نحو خمسمائة فارس معه، بعدما كان في سبعين فارسًا في أوَّلِ ركوبه، ثم أتاه من العامةِ عالمٌ كبيرٌ، فترامى الفريقان واقتتلا، ونزل الأميرُ حسام الدين حسين بن الكوراني والي القاهرة، والأمير مأمور حاجب الحجاب من عند الناصري، ونودي في الناس بنهب مماليكِ منطاش، والقَبضِ على من قَدَروا عليه منهم، وإحضاره إلى الناصري، فخرج عليهما طائفةٌ من المنطاشية فضربوهما وهزموهما، فعادوا إلى الناصريِّ وسار الوالي إلى القاهرة، وأغلَقَ أبوابها، واشتَدَّت الحرب، ثم أتى منطاش طوائِفُ من مماليك الأمراء والبطالة وغيرهم شيئًا بعد شيءٍ، فحَسُنَ حاله بهم، واشتد بأسُه، وعَظُمَت شوكته بالنسبة لما كان فيه أولًا، لا بالنسبة لحواشي الناصري ومماليكِه، هذا وقد انزعج الناصريُّ وقام بنفسه وهيَّأ أصحابه لقتال منطاش، ونَدَب من أصحابه من أكابر الأمراء جماعةً لقتاله، واستمر القتالُ بينهما، وكل ذلك يزداد أمرُ منطاش بهروب الأمراء الناصرية إليه، حتى إن منطاش أمر فنادى بالقاهرة بالأمان والاطمئنان، وإبطال المكس والدعاء للأمير الكبير منطاش بقبَّة النصر، هذا وقد أخذ أمر الناصري في إدبار، وتوجَّه جماعة كبيرة من أصحابِه إلى منطاش، فلما رأى الناصري عَسكَرَه في قِلَّة، وقد نفر عنه غالبُ أصحابه، بعث بالخليفةِ المتوكل على الله إلى منطاش يسأله في الصلحِ وإخماد الفتنة، فنزل الخليفة إليه وكَلَّمه في ذلك، فقال له منطاش: أنا في طاعة السلطانِ، وهو أستاذي وابن أستاذي، والأمراء إخوتي، وما غريمي إلا الناصري؛ لأنَّه حلف لي وأنا بسيواس ثم بحلب ودمشق أيضًا بأننا نكون شيئًا واحدًا، وأن السلطانَ يحكُمُ في مملكَتِه بما شاء، فلما حصَلَ لنا النصر وصار هو أتابك العساكر، استبَدَّ بالأمر، ومنع السلطانَ من التحكم، وحَجَر عليه، وقَرَّب خشداشيَّتَه اليلبغاوية، وأبعدني أنا وخشداشيتي الأشرفيَّة، ثم ما كفاه ذلك حتى بعثني لقتالِ الفلاحين، وكان الناصريُّ أرسله من جملة الأمراء إلى جهة الشرقية لقتال العربان، لَمَّا عَظُم فساد فلاحيها، ثم قال منطاش: ولم يُعطِني الناصريُّ شيئًا من المال سوى مائة ألف درهم، وأخذ لنفسِه أحسَنَ الإقطاعاتِ، وأعطاني أضعفها، والإقطاعُ الذي قرره لي يعمل في السنة ستمائة ألف درهم، واللهِ ما أرجع عنه حتى أقتُلَه أو يقتُلَني، ويتسلطن ويستبِدَّ بالأمر من غير شريكٍ، فأخذ الخليفةُ يلاطِفُه، فلم يرجع له وقام الخليفة من عنده وهو مُصَمِّمٌ على مقالته، وطلع إلى الناصري وأعاد عليه الجوابَ، فعند ذلك ركب الناصري بسائِرِ مماليكه وأصحابه، ونزل بجمعٍ كبير لقتال منطاش، وصَفَّ عساكِرَه تجاه باب السلسلة، وبرز إليه منطاش أيضًا بأصحابِه، وتصادما واقتتلا قتالًا شديدًا، وثَبَت كُلٌّ من الطائفتين ثباتًا عظيمًا، حتى انكسر الناصري وأصحابُه، وطلع إلى باب السلسلة، وندم الناصري على خَلعِ الملك الظاهر برقوق وحَبْسِه؛ لَمَّا عَلِمَ أن الأمر خرج من اليلبغاوية وصار في الأشرفية حيث لا ينفعه الندم، وأما منطاش فركب بمن معه بعد أن انهزم الناصري عدة مرات وترَكَه أكثَرُ أمرائه، وطلع إلى الإسطبل السلطاني ومَلَكَه، ووقع النهب فيه، فأخذوا من الخيل والقماش شيئًا كثيرًا، وتفَرَّق الزعر والعامة إلى بيوت المنهزمين، فنَهَبوا وأخذوا ما قدروا عليه، ومنعهم الناسُ من عدة مواضع، وبات منطاش بالإسطبل، وأصبح من الغدِ، وهو يوم الخميس تاسع عشر شعبان، وطلع إلى السلطان الملك المنصور حاجي، وأعلمه بأنَّه في طاعته، وأنَّه هو أحقُّ بخدمتِه؛ لكونِه من جملة المماليك الذين لأبيه الأشرَفِ شعبان، وأنه يمتَثِلُ مَرسومَه فيما يأمُرُه به، وأنه يريدُ بما فعله عمارةَ بيت الملك الأشرف، فسُرَّ المنصور بذلك هو وجماعة الأشرفية؛ فإنهم كانوا في غاية ما يكون من الضِّيقِ مع اليلبغاوية من مُدَّة سنين."},{"id":3181,"title":"خروج الظاهر برقوق من السجن بالكرك .","date":["العام الهجري :791","الشهر القمري : رمضان","العام الميلادي :1389"],"text":"خرج المَلِكُ الظاهر برقوق مِن سجن الكرك، واستولى على مدينتِها ووافقه نائِبُها الأمير حسام الدين حسن الكجكني، وقام بخِدمتِه، وقد حضر إلى الملك الظاهر برقوق ابنُ خاطر أمير بني عقبة من عرب الكَركِ، ودخل في طاعته، وقَدِمَ هذا الخبر من ابن بأكيش نائب غزة، فلمَّا سمعه منطاش- الذي تغلب على الناصري وأصبح هو نائِبَ السلطنة- أرسل من يقتُلُ الظاهر برقوق في سجنه، واضطربت الديارُ المصرية، وكَثُرَت القالة بين الناس، واختلفت الأقاويلُ، وتشَغَّب الزعر، وكان مِن خَبَرِ الملك الظاهر برقوق أنَّ منطاش لَمَّا وثب على الأمر وقهر الأتابك يلبغا الناصري وحبسه وحَبَس عِدَّةً من أكابر الأمراء، عاجَلَ في أمر الملك الظاهر برقوق بأن بعث إليه شخصًا يُعرَفُ بالشهاب البريدي، ومعه كتُبٌ للأمير حسام الدين الكجكني نائب الكرك وغيره بقَتلِ الملك الظاهر برقوق من غير مراجَعةٍ، ووعده بأشياءَ غيرِ نيابة الكرك، وكان الشهابُ البريدي أصلُه من الكرك، فجَهَّزه منطاش لذلك سرًّا، فلما وصل الشهاب إلى الكرك أخرج الشهابُ إلى نائبها كتابَ منطاش الذي بقَتلِ برقوق، فأخذه الكجكني منه ليكونَ له حُجَّةً عند قَتْلِه السلطان برقوق، ووعَدَه بقضاء الشُّغلِ وأنزل الشهابَ بمكان قلعة الكرك قريبًا من الموضِعِ الذي فيه الملك الظاهر برقوق، بعد أن استأنَسَ به، ثم قام الكجكني من فَورِه ودخل إلى الملك الظاهر برقوق ومعه كتاب منطاش الذي بقَتلِه، فأوقفه على الكتابِ، فلمَّا سمعه الملك الظاهر كاد أن يَهلِكَ من الجزع، فحَلَف له الكجكني بكلِّ يمين أنَّه لا يُسَلِّمُه لأحد ولو مات، وأنَّه يطلِقُه ويقومُ معه، وما زال به حتى هدأ ما به، وطابت نفسُه، واطمأنَّ خاطِرُه، وقد اشتهر في مدينة الكرك مجيءُ الشهاب بقتل الملك الظاهر برقوق، وكان في خدمةِ الملك الظاهر غلامٌ مِن أهل الكرك يقال له عبد الرحمن، فنزل إلى جماعةٍ في المدينة وأعلَمَهم أن الشهابَ قد حضر لقَتلِ أستاذه الملك الظاهر، فلمَّا سمعوا ذلك اجتمعوا في الحال، وقَصَدوا القلعة وهجموها حتى دخَلوا إلى الشهاب وهو بسَكَنِه من قلعة الكرك، ووثَبوا عليه وقَتَلوه، ثم جَرُّوه برجله إلى الباب الذي فيه المَلِك الظاهر برقوق، وكان نائِبُ الكرك الكجكني عند الملك الظاهر، وقد ابتدؤوا في الإفطار بعد أذان المغرب، وهي ليلة الأربعاء عاشر شهر رمضان من سنة 791 فلم يشعر الملك الظاهر والكجكني إلَّا وجماعة قد هجموا عليهم، وهم يدعون للملك الظاهر بالنَّصرِ، وأخذوا الملك الظاهِرَ بيَدِه حتى أخرجوه من البرجِ الذي هو فيه، وقالوا له: دُسْ بقدمك عند رأس عدُوِّك، وأروه الشهابَ مقتولًا، ثم نزلوا به إلى المدينةِ فدُهِشَ النائب مما رأى، ولم يجِدْ بدًّا من القيامِ في خدمة الملك الظاهر وتجهيزِه، وانضَمَّ على الملك الظاهِرِ أقوام الكرك وأجنادُها، وتسامع به أهلُ البلاد، فأتَوه من كُلِّ فَجٍّ بالتقادم والخيول، كل واحدٍ بحَسَبِ حالِه، وأخذ أمرُ الملك الظاهر برقوق من يومِ ذلك في استظهارٍ، وأما أمر منطاش فإنه لما سَمِعَ هذا الخبر وتحقَّقَه، علم أنه وقع في أمرٍ عظيم، فأخذ في تدبيرِ أحوالِه، فأول ما ابتدأ به أن قَبَض على جماعةٍ كبيرة من المماليك الظاهرية، وسجنهم وقَتَل بَعْضَهم."},{"id":3182,"title":"منطاش الأفضلي يهرب من دمشق بعد أن استحوذ عليها  .","date":["العام الهجري :792","الشهر القمري : محرم","العام الميلادي :1390"],"text":"بعد أن قام الظَّاهِرُ برقوق بالاستيلاء على مِصرَ وعودَتِه إليها، بقي منطاش في دمشق عاصيًا على السلطان برقوق، وأخَذَ منطاش بعلبكَّ بعد أن حاصرها محمد بن بيدمر أربعةَ أشهر، ثم إنَّ الظاهر برقوقًا جَهَّز العساكِرَ إلى دمشق لأخْذِها من منطاش، فلما بلغ منطاش قدومُ العساكر برز من دمشق، وأقام بقبَّة يلبغا، ثم رحل نصفَ ليلة الأحد ثالث عشر جمادى الآخرة بخواصِّه، وهم نحو الستمائة فارس، ومعه نحو السبعينَ حملًا ما بين ذَهَبٍ ودراهم وقماش، وتوجه نحو قارا والنبك، بعد أن قَتَل المماليك الظاهرية، والأميرُ ناصر الدين محمد بن المهمندار، وإن الأمير الكبير أيتمش خرج من سجنه بقلعة دمشق وأفرجَ عَمَّن بها، ومَلَك القلعة، وبعث إلى النوابِ يُعلِمُهم، وسَيَّرَ كتابه إلى السلطان بذلك، فسار النوابُ إلى دمشق ومَلَكوها بغير حرب، ثمَّ إن منطاش توجه إلى الأمير نعير، ومعه عنقا بن شطى أمير آل مرا، ثم قدم البريدُ بأن منطاش ونعيرًا جمعَا جمعًا كبيرًا من العُربان والأشرفية والتركمان، وساروا لمحاربة النواب، فخرج الأمير يلبغا الناصري والأمير ألطبغا الجوباني بالعساكر من دمشق إلى سليمة، ثم اجتمع البَيْدَمرية والطازية والجنتمرية في طوائف من العامة بدمشق يريدون أخْذَها، فسَرَّح الأمير الكبير أيتمش الطائر من القلعةِ إلى سليمة يُعلِمُ الأمير يلبغا الناصري بذلك، فركب ليلًا في طائفةٍ مِن العسكر، وقَدِمَ دمشق وقاتَلَهم ومعه ألابغا العثماني حاجب الحجاب بدمشق، فقُتِلَ بينهما خلقٌ كثير من الأتراك والعوام وكَسَرَهم، وقَبَض على جماعة ووسَّطَهم تحت قلعة دمشق، وحَبَس جماعة، وقَطَع أيديَ سبعمائة رجل، وعاد إلى سليمة، وافترقت جمائِعُ منطاش وعساكر الشام ثلاث فرق، وتولى الأميرُ يلبغا الناصري محاربةَ الأمير نعير، فكسَرَه، وقتل جمعًا مِن عُرْبانه، وركب قفا نعيرٍ إلى مَنازِلِه، وحارب الأميرُ قرا دمرداش منطاشَ ومَن معه من التركمان، فضرَبَ كُلٌّ منهما الآخر، فوقعت الضربةُ بكَتِفِ منطاش، وقُطِعَت أصابع قرا دمرداش، وخامَرَ جماعة من الأشرفية على منطاش وصاروا في جملةِ الأمير ألطبغا الجوباني، فأحسن إليهم وقرَّبَهم، فلما وقعت الحربُ اتفق الأشرفيَّةُ مع بعض مماليكِه وقَتَلوه، وقبضوا على الأمير مأمور ووسَّطوه- قتلوه- وقتلوا الأمير أقبغا الجوهري وعِدَّةً من الأمراء، فكانت حروبًا شديدة، قُتِلَ فيها بين الفِرَق الثلاث خَلقٌ لا يُحصي عددَهم إلا خالقُهم سبحانه وتعالى, ونَهَبَت العربُ والعشير جميعَ ما كان مع العسكَرينِ، وقَدِمَ البريد بذلك، وأن منطاش انكسر، فأقام الأشرفيَّةُ بدله ألطبغا الأشرفي، فحضر منطاش من الغَدِ وأراد قتْلَه، فلم تمَكِّنْه الأشرفية من ذلك، وإنَّ الناصري لَمَّا رجع من محاربة نعير جمع العساكِرَ وعاد إلى دمشق، ثم خرج بعد يومين وأغار على آل علي، ووسَّط- قتل- منهم مائتي نفس، ونهب كثيرًا من جِمالِهم، وعاد إلى دمشق، ثم قَدِمَ البريد من دمشق بأن الأمير قَشْتَمُر الأشرفي، الحاكِمَ بطرابلس من جهة منطاش، سَلَّمَها من غير قتال، وأنَّ حماة وحمص أيضًا استولت العساكرُ السلطانية عليهما، ثم قَدِمَ البريد من دمشق بفرار منطاش عن أرض حَلَب، ومعه عنقاءُ بن شطي، خوفًا على نَفسِه مِن نعير، وأنَّه توجَّهَ في نحو سبعمائة فارس من العَرَبِ، أخذهم على أنَّه يكبس التركمان ويأخذ أعناقَهم، فلما قطع الدربند أخذَ خُيولَ العرب، وسار إلى مرَعش، وترك العربَ مُشا، فعادوا."},{"id":3183,"title":"الحرب بين الظاهر برقوق وعساكر السلطان حاجي المنصور .","date":["العام الهجري :792","الشهر القمري : صفر","العام الميلادي :1390"],"text":"بعد أن خرج الظاهِرُ برقوق السلطانُ المخلوعُ مِن سجن الكرك واجتمَعَ له أهلُ الكرك ونصروه، وما زال أمرُه في ظهور حتى العُربان اجتمعت عليه، وأخلاطُ أهل مدينة الكرك، فخرج من الكرك يريد الشَّامَ فأقام بالثنية خارج الكرك يومين، ورحل في الثامِنِ والعشرين من شوال، وسار بهم يريد دمشقَ، وبها الأمير جَنتمُر أخو طاز، متولِّي نيابتها وقد وصل إليه الأمير ألطنبغا الحلبي الدوادار من مصر نائبًا على حلب بحُكم عصيان كمشبغا الحموي، فاستعَدَّا لقتال الظاهر، وتوجَّه إليهما الأميرُ حسام الدين حسين بن باكيش نائب غزة بعساكرها وعشيرها، وأقبل الظاهِرُ بمن معه، فخرجوا إليه وقاتلوه بشقحب قريبًا من دمشق قتالًا شديدًا، كسَروه فيه غيرَ مرة، وهو يعودُ إليهم ويقاتِلُهم، إلى أن كسرهم وانهزموا منه إلى دمشق، وقَتَل منهم ما ينيفُ على الألف، فيهم خمسةَ عشر أميرًا، وقُتِلَ من أصحابه نحو الستين، ومن أمرائِه سَبعةٌ، وركب أقفيةَ المنهزمين، فامتنع جَنتمر بالقلعة، وتوجَّه بالقلعة وتوجَّهَ من أمراء دمشق ستة وثلاثون أميرًا، ومعهم نحو الثلاثمائة وخمسين فارسًا، قد أُثخِنوا بالجراحات، وأخَذوا نائِبَ صفد، وقَصَدوا ديار مصر، فلم يمضِ غيرُ يوم واحد حتى وصل ابنُ باكيش بجمائعه، فقاتله الظاهِرُ وهَزَمَه، وأخذ جميعَ ما كان معه، فقَوِيَ به قوة كبيرة، وأتاه عِدَّةٌ من مماليكه، ومن أمراء الشام، فصار في عسكرٍ كبير، وأقبل إليه الأميرُ جبرائيل حاجِبُ الحجاب بدمشق، وأمير علي بن أسندمر الزيني، وجَقمَق، ومقبل الرومي، طائعين له، فصاروا في جملته، ونزل السلطان برقوق على قبة يلبغا ظاهر دمشق، وقد امتنع أهلُها بها، وبالغوا في تحصينِها، فحصرها وأحرق القبيبات وخربها، وأهلك في الحريق خلقًا كثيرًا، وجَدَّ أهل المدينة في قتالِه، وأفحشوا في سَبِّه، وهو لا يفتُرُ عن قتالهم، فأمَدَّه الأمير كمشبغا من حلب بثمانين فارسًا من المماليك الظاهريَّة، فأخرج إليهم الأمير جَنتمر خمسمائة فارس من دمشق، ليَحُولوا بينهم وبين الظاهر، فقاتلوهم فكسَرَهم الظاهرية، واستولوا على جميعِ ما معهم، وأتَوا إلى الظاهر فأقبل الأمير نعير بعُربانه يريدُ محاربته، فحاربه وكَسَرَه فانهزم عنه، وتقوى ممَّا صار إليه في هذه الوقائع، واستمَرَّ الظاهرُ برقوق على حصار دمشق وقتال أهلها، فورد الخبَرُ بذلك إلى منطاش في خامس عشر ذي القعدة، فتقَدَّم في السابع عشر منه إلى الصاحب موفق الدين أبي الفرج بتجهيز المَلِك المنصور حاجي للسَّفَر، فلم يجِدْ في الخزائن ما يجَهِّزُه به، فأخذ أموال اليتامى التي في الخزائِنِ وأخذ كذلك من اليهود والنصارى أموالًا، واستصدر فتوى بحلِّ قَتلِ الظَّاهِرِ برقوق بسَبَبِ ما قام به من خَلعِ الخليفة والسلطان السابق وغيرها من الأمور، ثمَّ جُهِّزَت العساكر من مصر للسير لقتال الظاهر برقوق، ففي ثاني محرم من سنة 792 وصل السلطانُ الملك المنصور إلى مدينة غزَّةَ بعساكرِ مِصرَ، وبلغ ذلك المَلِكَ الظاهر فترك قتالَ أهل دمشق، وأقبل نحوَهم، فنزل العسكَرُ المصري على قرية المليحة، وهي تبعد عن شقحب بنحو بريدٍ، وأقاموا بها يومَهم، وبعثوا كشافَتَهم، فوجدوا الظاهِرَ برقوق على شقحب، فكان اللقاءُ يوم الأحد الرابع عشر، وقد وافاهم الظاهِرُ برقوق، فوقف الأمير منطاش في الميمنةِ وحمل على ميسرة الظاهر، فحمل أصحابُ ميمنة الظاهر على ميسرة المنصور، وبذل كلٌّ من الفريقين جُهدَه، وكانت حروبًا شديدة، انهزمت فيها ميمنةُ الظاهر وميسرتُه، وتَبِعَهم منطاش بمن معه، وثبت الظاهرُ في القلب، وقد انقطع عنه خبَرُ أصحابه، وأيقَنَ بالهلاك، ثم حمل على المنصورِ بمن بقي معه، فأخذ المنصورَ والخليفةَ المتوكِّلَ والقُضاة والخزائِنَ، ومالت الطائفةُ التي ثبتت معه على الأثقال، فأخَذَتْها عن آخرها، وكانت شيئًا يخرُجُ عن الحَدِّ في الكثرة، ووقع الأميرُ قجماس ابن عم الظاهر في قبضةِ منطاش، ومَرَّ في أثر المنهزمين حتى وصل إلى دمشق، وأما الظاهر وأصحابه، فإن الأمير كمشبغا نائب حلب كان ممن انهزم على شَقْحب، فتَمَّ في الهزيمة إلى حلب، وتَبِعَه الأمير حسام الدين حسن الكجكني نائب الكرك، ومن بَقِي من عساكر حلب، فاستولى عليها، وانهزم أهلُ الكرك إليها، فلم يَصِلوا حتى مرَّت بهم شدائد، ولم يتأخَّرْ مع الظاهر إلا نحو الثلاثين، وقد تمَزَّقت عساكره وعساكِرُ مصر، فلم يقصِدْ إلا المنصور، فأخذه بمن معه فصار السلطانُ حاجي والخليفةُ المتوكل في قبضة الظاهر، ثم في يوم الاثنين أقبل منطاش في عالمٍ كبير من عوام دمشقَ وعساكرها ومن كان معه، فدارت بينه وبين الظاهِرِ في هذا اليوم منذ شروق الشمسِ إلى آخره حروبٌ لم يُعهَدْ بمصر والشام في هذه الأعصُرِ مِثلُها، وبعث الله ريحًا ومطرًا في وجهِ منطاش ومن معه، فكانت من أكبَرِ أسبابِ خِذلانه، ولم تغرُب الشمس حتى فَنِيَ من الفريقين خلقٌ كثير من الفرسان والعامة، وانهزم منطاش إلى دمشق، وعاد الظاهِرُ إلى منزلته فأقام بها سبعة أيام، وعَزَّت عنده الأقواتُ، وفي أثناء إقامته أمر الظاهر فجَمَع كُلَّ من معه من الأعيان، وأشهد على المنصور حاجي أنَّه خلع نفسه، وحَكم بذلك القضاة، ثم بويع الظاهِرُ، وأثبت القضاةُ بَيعَتَه، فولَّى الظَّاهِرُ الأميرَ فخر الدين إياس الجرجاوي نيابة صفد، والأمير سيف الدين قديد القَمطاي الكرك، والأمير علاء الدين أقبغا الصغير غزة، ورحل الظاهِرُ فأتاه عند رحيله منطاش بعَسكرِ الشام، ووقف على بُعدٍ فاستعد الظاهر إلى لقائه، فولى عنه وعاد إلى دمشق، وسار الملك الظاهِرُ ومن معه يريدُ ديار مصر، وبعث إلى غزة يأمرُ منصور الحاجب بالقبضِ على حسام الدين حسن بن باكيش، فقُبِض عليه واستولى على غزة، وبعث بابن باكيش إلى السلطان الظاهر برقوق فضربه بالمقارع وهو بالرملة، وسار الظاهر إلى غزة فضربه بها ضربًا مبَرِّحًا يوم دخلها مستهَلَّ صفر، ثم في بكرة نهار يوم الثلاثاء رابع عشر صفر نزل الملك الظاهر بالريدانية خارج القاهرة، فخرج إلى لقائِه الأشرفُ مع السيد علي نقيب الأشراف، وخرجت طوائِفُ الفقراء بصناجِقِها، وخرجت العساكِرُ بلبوسِها الحربية، وكانت العساكِرُ منذ خرج بطا وأصحابه لابسةً السلاح ليلًا ونهارًا، وخرجت اليهودُ بالتوراة، والنصارى بالإنجيل، ومعهم شموعٌ كثيرةٌ مُشعَلة، وخرج من عامةِ الناس رجالُهم ونساؤهم ما لا يحصيه إلا الله، وعندهم من الفَرَحِ والسرور شيءٌ زائد، وهم يضجُّون بالدعاء للسلطان، حتى لَقُوه وأحاطوا به، وقد فُرِشَت الشُّقَق الحريرُ من الترب إلى باب السلسة، فلما وصل إليها تنحى بفَرَسِه عنها، وقَدَّمَ المَلِكَ المنصور حاجي بن الأشرف حتى مشى بفَرَسِه عليها، ومشى بجانِبِه، فصار كأنَّ الموكِبَ للمنصور، فوقع هذا من الناسِ مَوقعًا عظيمًا، ورفعوا أصواتَهم بالدعاء والابتهال له؛ لتواضعه مع المنصور في حال غَلَبتِه وقَهْرِه له، وأنَّه معه أسيرٌ! وعُدَّ هذا من فضائله، واستَدعى الخليفةَ وشيخَ الإسلام وقضاة القضاة وأهل الدولة، وهو بالإسطبل، وجدد عقد السلطنة وتجديد التفويض الخليفتية، فشهد بذلك القضاةُ على الخليفة ثانيًا، وأُفيضَت التشاريف الخليفتيَّة على السلطان، ثم أُفيضَت التشاريف السلطانية على الخليفة، وركب السلطانُ مِن الإسطبل وصَعِدَ القلعة، وتسَلَّمَ قُصوره، وقد عاد إليها حَرَمُه وجواريه، فحقت البشائرُ."},{"id":3184,"title":"هجوم الفرنجة على طرابلس الغرب .","date":["العام الهجري :792","الشهر القمري : شوال","العام الميلادي :1390"],"text":"قَدِمَ البريدُ بنُزولِ عِدَّةِ مراكب للإفرنج على طرابلس، فعندما أشرفوا على الميناءِ بَعَث الله عليهم ريحًا أغرَقَت مركبًا، وفَرَّقَت البقية، وكانت نحو السبعين، فرُدُّوا خائبين، قَدِم الخبَرُ من الإسكندرية بأنَّ الفرنج الذين مَزَّقَت الريحُ مراكِبَهم على طرابلس ساروا إلى إفريقيَّة وحاصروا المهدية، وبها وَلَدُ أبي العباس صاحِبُ تونس، فكانت حروبًا شديدةً، انتصر فيها المسلمونَ على الفرنج، وقَتَلوا كثيرًا منهم."},{"id":3185,"title":"عدوان الفرنج على المهدية  .","date":["العام الهجري :793","العام الميلادي :1390"],"text":"إن الفِرنجَ قَدِموا إلى المهدية وساعَدَهم هذه السَّنةَ أسطول فرنسيٌّ؛ عونًا لأسطول جنوة، فقام الأميرُ الحفصي أبو فارس عبد العزيز ابن السلطان أبي العباس أحمد المستنصر بصَدِّهم؛ مِمَّا اضطرهم إلى الانسحابِ؛ مما عَزَّزَ مكانة مركز أبي العباس أحمد، وأعيد إلى السلطنة الحفصية كما كانت سالِفَ عَهدِها."},{"id":3186,"title":"السلطان العثماني بايزيد الأول يضم عدة مدن في آسيا الصغرى .","date":["العام الهجري :793","العام الميلادي :1390"],"text":"بعد أن تسَلَّمَ بايزيد بن مراد السلطةَ بعد مقتل أبيه، بَقِيَ على ما كان عليه من الجهادِ، فكان ينتَقِلُ من أوروبا إلى الأناضول ثم يعود مُسرعًا إلى أوروبا، يحقِّقُ فيها نصرًا جديدًا أو تنظيمًا حديثًا، حتى لُقِّبَ باسم يلدرم- يعني الصاعقة، وفي هذه السنة انتقل إلى الأناضول فضَمَّ إمارة منتشا، وإمارة آيدين، وإمارة صاروخان دون قتالٍ، وفَرَّ أبناء حكَّامها إلى أمير قسطموني مركز ولاية أسفنديار, كما تنازل أميرُ دولة القرمان عن جزء من أملاكِه إلى السلطان مقابِلَ بقاء الجزء الباقي بيَدِه."},{"id":3187,"title":"السلطان بايزيد الأول يطهر آسيا الصغرى من الوجود البيزنطي .","date":["العام الهجري :793","العام الميلادي :1390"],"text":"فتح بايزيد الأوَّلُ مدينةَ الأشهر بقُربِ أزمير، وهي آخِرُ مدينة كانت قد بَقِيَت للروم في غرب بلادِ الأناضول وهي المعروفةُ بفلادلفيا، وهي آخِرُ مَعقِل بيزنطي بآسيا الصغرى، وبذا يكون قد أمِنَ خلفه؛ إذ كان حُكَّامُ هذه الإمارات يمكِنُ أن يتعاونوا مع أيِّ قُوَّة في سبيل المحافظةِ على إمارتِهم."},{"id":3188,"title":"وفاة السلطان محمد الخامس ملك بني الأحمر في غرناطة وتولي ابنه .","date":["العام الهجري :793","العام الميلادي :1390"],"text":"هو السُّلطانُ أبو عبد الله محمد الخامس الغني بالله بن يوسف الأول إسماعيل بن فرج بن إسماعيل بن يوسف بن نصر ملك دولة بني نصر أو بني الأحمر في غرناطة، الذى ساعده ملك البرتغال وسلطان بنى مرين على استرداد مُلكِه، وقام بالأمرِ بعده ابنُه أبو الحجَّاج يوسف الثاني، الذي أبرم معاهدةَ سلم مع ملك قشتالة بعد الحروبِ التي كانت بين أبيه وبين قشتالة. وبعد وفاةِ محمد الخامس تعاقَبَ على حكم غرناطة عددٌ من السلاطين الضِّعافِ، وتعَرَّضَت دولة بني الأحمر في الأندلس لكثيرٍ مِن الفتن والدسائس والمؤامرات وتحالفات مع ملوك النصارى، وبلغ الاضطراب حدًّا تعاقب فيه على مملكةِ غرناطة اثنا عشر سُلطانًا خلال القرن التاسع الهجري الخامس عشر الميلادي."},{"id":3189,"title":"اجتياح تيمورلنك تركستان وقتاله لتوقتاميش .","date":["العام الهجري :793","الشهر القمري : رجب","العام الميلادي :1391"],"text":"زادت الوَحشةُ بين تيمورلنك وتوقتاميش حاكِمِ تُركستان، وكان تيمورلنك قد حاول أن يستثير غضَبَ توقتاميش؛ حيث اجتاح بعضَ أطراف بلاده مثل سيرام على أطراف تركستان، وحصلت مناوشات حربية بين جيوشِ الطرفين خلال ثلاث سنوات، واستولى تيمورلنك على خوارزم ثم انتزعها منه توقتاميش، ثمَّ إن تيمورلنك كان في قوشون من بلاد تركستان، فسمع بعصيان خراسان عليه، فأرسل من يوقِفُ عصيانَهم، ثم عاد في أواخر سنة 792 وتوجَّهَ من سمرقند فسار إلى توقتاميش ومعه عساكر خراسان، ثم وصل في أول صفر من سنة 793 إلى بقرا أسمان ووقف بها لتوالي هطول الأمطار والثلوج، وجاءه رسلٌ من توقتاميش للصلحِ فرفَضَ،ثم وصل في جمادى الآخرة إلى نهر بايق، ثم وصل إلى نهر صقمار، ثم في رجب وصل إلى أينك، ثم بعد أيام بدأت المناوشات حتى كان التقاءُ الطرفين في قراغول، واشتَدَّ القتال بينهما، ثم توقف القتال بسبب الأمطارِ أسبوعًا، ثم عاد القتالُ على أشُدِّه في أواخر رجب، حتى اشتد الحالُ إلى أن انهزم توقتاميش واستولى تيمورلنك على بلادِه يقتُلُ وينهَبُ ويأسِرُ، بقي على ذلك ستة وعشرين يومًا، ثم عاد إلى بلاده."},{"id":3190,"title":"عصيان يلبغا الناصري ومنطاش على السلطان برقوق .","date":["العام الهجري :793","الشهر القمري : ذي الحجة","العام الميلادي :1391"],"text":"في أوَّلِ شَهرِ رَجَب قَدِمَ منطاش دمشق، وسار إليها من مرعش على العُمق، حتى قارب من حماة، فانهزم منه نائِبُها إلى جهة طرابلس من غيرِ لقاء، ودخلها منطاش، ولم يُحدِثْ حدثًا، وتوجَّه منها إلى حمص، ففَرَّ منه أيضًا نائِبُها إلى دمشق، ومعه نائِبُ بعلبك، فخرج الأميرُ يلبغا الناصري يريد لقاءه من طريق الزبداني، فثار أحمد شكر بجماعة البيدمرية، ودخل دمشقَ من باب كيسان، وأخذ ما في الإسطبلاتِ من الخيول، وخرج في يوم الأحد التاسع والعشرين جمادى الآخرة، وقدم منطاش في يوم الاثنين أولَ رَجَب من طريق أخرى، ونزل القصرَ الأبلق، ونزل جماعتُه حوله، وقد أَحضر إليه أحمد شكر من الخيول التي نهبها ثمانمائة فرس، وندبه ليدخُلَ المدينة ويأخذ من أسواقها المالَ، فبينا هو كذلك إذ قَدِمَ الناصري بعساكر دمشقَ فاقتتلا قتالًا كبيرًا مدَّةَ أيام، ثم إن منطاش انكسر وقُتِلَ كثيرٌ مِمَّن معه، وفَرَّ معظم التركمان الذين قَدِمَ بهم، وصار محصورًا بالقَصرِ الأبلق، ثم إنَّ السلطان برقوق سار بنفسِه إلى دمشق ثم سار إلى حلب وفي ذي القعدة قَبَض سالم الذكرى على منطاش، وإن صاحب ماردين قبض على جماعةٍ مِن المنطاشية حَضَروا إليه، فبعث السلطانُ قرا دمرداش نائِبَ حلب على عسكر، والأميرَ يلبغا الناصري نائب دمشق على عسكرٍ، والأميرَ أينال اليوسفي أتابك العساكر على عسكر، فساروا لإحضارِ منطاش ومن معه، فنودِيَ في القاهرة بالأمان، وقد حصل غريمُ السلطان. وقَدِمَ البَريدُ مِن حَلَب بِأَن الأمير قرا دمرداش وصل بعسكر حلب إلى أبيات سالم الذكرى، وأقام أربعة أيام يطالِبُه بتسليم منطاش وهو يماطِلُه، فحنق منه وركب بمن معه ونهب بيوته، وقتل عِدَّة من أصحابه، ففَرَّ سالم بمنطاش إلى سنجار وامتنع بها، ثم إنَّ الأميرَ يلبغا الناصري حضر بعساكر دمشق بعد ذلك، فأنكر على قرا دمرداش ما وقع منه وأغلَظَ في القول وهَمَّ بضَربِه، فكادت تكون فتنةٌ كبيرة وعادا، وإن الأمير أدينال وصل بعسكرِ مِصرَ إلى رأس عين، وتسَلَّمَ من صاحب ماردين الذين قَبَضَهم من المنطاشية، وكبيرهم قشتمر الأشرفي، وحضر بهم وبكتاب صاحب ماردين، وهو يعتذر ويَعِدُ تحصيل غريم السلطان، وفي يوم الاثنين أول ذي الحجة خرج السلطان من حلب يريد دمشق، وفي سادسه قدم البريد بأن السلطان لما بلغه ما جرى من قرا دمرداش وما وقع بينه وبين الناصري من الفتنة، وأنهما عادا بغير طائل، غَلَب على ظَنِّه صِحَّةُ ما نُقِلَ عن الناصري مِن أنَّ قَصْدَه مطاولةُ الأمر مع منطاش، وأنه لم يحضُرْ إلى دمشق إلا بمكاتبَتِه له بذلك، وأَنه قَصَّر في أخذه بدمشق، وأنَّ سالم الذكرى لم يرحَلْ بمنطاش إلى سنجار إلا بكتابِ الناصري إليه بذلك، فلما قَدِمَ إلى حلب قُبِضَ عليه وعلى شهاب الدين أحمد بن المهمندار نائب حماة، وكشلي أمير أخور الناصري، وشيخ حسن رأس نوبته، وقَتَلَهم في ليلة قَبْضِهم، ويُذكَرُ أن يلبغا الناصري هذا هو الذي تمالأ مع منطاش أولًا على برقوق، وسَعَيَا حتى خلعاه، ثم فسد الحالُ بينهما وفاز منطاش بالنيابةِ فسَجَنَ يلبغا، وعندما تسلَّم برقوق السلطنة مرة أخرى أخرج يلبغا وعفا عنه رغم ما فعَلَه ضِدَّه وأنعم عليه بنيابةِ دمشق، ثمَّ إنه تمالأ مرةً أخرى مع منطاش، فكان عاقبته القتل!"},{"id":3191,"title":"حجاج يقعون في قبضة ملك صقلية في طريقهم إلى الحج .","date":["العام الهجري :794","العام الميلادي :1391"],"text":"خرج جَماعةٌ مِن بلاد المغرب يريدون أرضَ مِصرَ لأداء فريضة الحجِّ، وساروا في بحر الملح، فألقَتْهم الريحُ إلى جزيرة صقلية، فأخذهم النصارى وما معهم، وأتَوا بهم إلى مَلِك صقلية، فأوقَفَهم بين يديه وسألهم عن حالِهم، فأخبروه أنَّهم خرجوا يريدون الحَجَّ، فألقَتْهم الريحُ إلى هنا، فقال: أنتم غنيمةٌ قد ساقكم الله إليَّ، وأمَرَ بهم أن يُقَيَّدوا حتى يُباعُوا ويُستَخدَموا في مِهَنِهم! وكان من جُملَتِهم رجلٌ شَريفٌ، فقال له على لسانِ تَرجُمانه: أيُّها المَلِكُ، إذا قَدِمَ عليك ابنُ ملك ماذا تَصنَعُ به؟ قال: أُكرِمُه, قال: وإن كان على غيرِ دينِك؟ قال: وما كرامتُه إلَّا إذا كان على غيرِ ديني! وإلَّا فأهلُ ديني واجِبٌ كرامَتُهم، قال: فإني ابنُ أكبَرِ ملوك الأرضِ، قال: ومَن أبوك؟ قال: عليُّ بنُ أبى طالب رَضِىَ الله عنه، قال: ولم لا قُلتَ: أبي محمَّدٌ صلَّى الله عليه وسلم، قال: خشيتُ أن تَشتُموه، قال: لا نَشتُمُه أبدًا. قال: بيِّنْ لي صِدْقَ ما ادَّعَيْتَ به، فأخرَجَ له نِسْبَتَه وكانت معه في رَقٍّ، فأمر بتخليتِه وتخليةِ مَن معه لسَبيلِهم، وجَهَّزَهم!!"},{"id":3192,"title":"السلطان العثماني بايزيد يحاصر القسطنطينية ويفتح بلغاريا .","date":["العام الهجري :794","الشهر القمري : ربيع الأول","العام الميلادي :1392"],"text":"قام السلطانُ بايزيد بن مراد الأوَّل بالاتجاه إلى الغَربِ ومحاصرة القُسطنطينية وضَيَّقَ عليها الحصار، لكنَّه لم يستمِرَّ هو في الحصار، بل تركها محاصَرةً مِن قِبَل بعض الجيش، وتوجه هو إلى الأفلاق، وهي الجزء الجنوبي من رومانيا اليوم، وأجبر حاكِمَها على توقيع معاهدة يعتَرِفُ فيها بسيادة العُثمانيين على بلاده، ويدفع كذلك جِزيةً سَنَوية على أن يُبقِيَه حاكِمًا على بلاده بقوانينِه وأنظِمَتِه الخاصة، ولكنَّ بايزيد اضطر للعودةِ إلى الأناضول مسرعًا؛ لأن أمير دولة القرمان علاء الدين لَمَّا وجد السلطان العثماني مشغولًا، وكان قد نَدِمَ على إعطاء جزء من بلاده له، فاستغل الظرفَ وعَبَّأ جنوده وأثار خصومَ السلطان من بعضِ الأمراءِ وهاجم العثمانيِّينَ وأحرز بعض النصر، وأسَرَ أميرَ قُوَّاد العثمانيين في الأناضول، ولكِنَّ السلطان أسرع وهزمه ولاحَقَه حتى أخذه ووليدَه أسرى، وأنهى بذلك دولة القرمان، أمَّا القُسطنطينية فما زالت محاصرةً، وسار السلطانُ إلى البلغار وقد قُتِلَ أميرها سيسمان، فجعل تلك البلاد ولايةً عُثمانية، وأسلم ابنُ الأمير المقتول، فأخذه السلطانُ وجعله واليًا على صامسون."},{"id":3193,"title":"وفاة الإمام العلامة الزركشي .","date":["العام الهجري :794","الشهر القمري : رجب","العام الميلادي :1392"],"text":"هو الإمامُ العلَّامة بدرُ الدين أبو عبد الله محمد بن بهادر بن عبد الله الزركشي المنهاجي، تركي الأصل، ولد بمصر سنة 745, وتعلَّمَ الفِقَه فيها، عُنِيَ بالاشتغال مِن صِغَرِه، فحَفِظَ كُتبًا وأخذ عن الشيخ جمال الدين الإسنوي والشيخ سراج الدين البلقيني ولازمه، حتى أصبح من كبار علماء الشافعيَّة في مصر، وبرع في الأصول، له تصانيفُ عديدة أشهرها: (البرهان في علوم القرآن)، (البحر المحيط في الأصول)، (إعلام الساجد بأحكام المساجد)، (الإجابة لإيراد ما استدركته عائشة على الصحابة)، (المنثور في القواعد الفقهية والأصولية)، (التنقيح لألفاظ الجامع الصحيح)، وغيرها من الكتب. قال ابن حجر: \"رحل إلى دمشقَ فأخذ عن ابن كثير في الحديثِ وقرأ عليه مُختَصَره ومَدَحَه ببيتين، ثم توجه إلى حلب فأخذ عن الأذرعي، ثم جمع الخادم على طريق المهمات، فاستمد من التوسط للأذرعي كثيرًا، لكنه شحنه بالفوائد الزوائد من المطلب وغيره، وجمع في الأصول كتابًا سماه البحر في ثلاثة أسفار، وشرح علوم الحديث لابن الصلاح، وجمع الجوامع للسبكي، وشرع في شرح البخاري فتركه مُسَوَّدة وقفت على بعضها، ولخص منه التنقيح في مجلد، وشرح الأربعين للنووي، وولي مشيخة كريم الدين، وكان منقطعًا في منزله لا يتردَّدُ إلى أحدٍ إلا إلى سوق الكتبِ، وإذا حضره لا يشتري شيئًا، وإنما يطالِعُ في حانوت الكُتبي طول نهارِه ومعه ظهورُ أوراقٍ يُعَلِّقُ فيها ما يُعجِبُه، ثم يرجع فينقِلُه إلى تصانيفِه، وخرَّج أحاديث الرافعي، ومشى فيه على جمع ابن الملَقِّن، لكنه سلك طريق الزيلعي في سَوق الأحاديث بأسانيد خرَّجها، فطال الكتاب بذلك\" ولَمَّا ولي البلقيني قضاءَ الشام استعار منه نُسختَه من الروضة مجلدًا بعد مجلدٍ، فعَلَّقَها على الهوامش من الفوائِدِ؛ فهو أول من جمع حواشي الروضة للبُلقيني، توفي في الثالث من رجب في القاهرة عن 50 عامًا."},{"id":3194,"title":"احتلال بني مرين تلمسان  .","date":["العام الهجري :795","العام الميلادي :1392"],"text":"بعدَ وفاة أبو تاشفين الثاني عبد الرحمن بن أبي حمو موسى سلطان بني زيان، قام بالأمرِ بَعدَه ابنُه أبو ثابت يوسف، ولكِنَّ عَمًّا لأبي تاشفين يدعى أبا الحجَّاج يوسف قام فنزع السُّلطةَ من ابن أخيه، واحتل تلمسان عاصمةَ دولة بني زيان، فكان هذا الاختلافُ أكبَرَ فُرصة لبني مرين الذين لم يتركوا الفرصةَ تَمُرُّ عليهم، بل قاموا باحتلالِ تلمسان وإلحاق الدولة الزيانية بدولتِهم، وقاموا بتولية أبي محمد عبد الله بن أبي حمو الزياني عاملًا لهم على تلمسان."},{"id":3195,"title":"مقتل شاه منصور آل مظفر آخر حكام دولة آل المظفر ببلاد فارس .","date":["العام الهجري :795","العام الميلادي :1392"],"text":"هو شاه منصور بن محمد بن مظفر: أخو شاه شجاع آخر حكام دولة آل المظفر، وثب على زين العابدين ابن أخيه فكحَلَه، واستقَلَّ بالحكم, فبلغ ذلك تيمورلنك فجعله سبيلًا إلى قصد بلاد فارس، فسار تيمورلنك ومعه ابنه شاه رخ إلى جهة فارس التي كان يحكمُها منصور شاه، فنازلَها ودافع شاه منصور عن بلاده، وظهرت منه شجاعةٌ عظيمة حتى هزمه تيمورلنك واحتلَّ بلاده وقتَلَه، وبمقتَلِه قضى تيمورلنك على دولةِ آل المظفر في أصفهان، وقد اشتهر المظفريون بحبِّهم للعلم وأهلِه طيلةَ عمرِ دولتِهم من النشأةِ حتى السُّقوطِ."},{"id":3196,"title":"وفاة الحافظ ابن رجب الحنبلي .","date":["العام الهجري :795","الشهر القمري : رمضان","العام الميلادي :1393"],"text":"هو الحافظُ زيْنُ الدين أبو الفرج عبدالرحمن بن شِهاب الدِّين أحمد ابن رجَب الحنبلي، ولد ببغداد سنة 736هـ، وسافر إلى دمشق وهو صغير واستقر بها، كان محدثًا بارعًا على طريقة المتقدمين، وفقيهًا حنبليَّا، وواعظًا زاهدًا، له مصنفاتٌ عديدة أشهرُها: شرح الأربعين النَّوويَّة، وشرح سنن الترمذي، والقواعد الفقهية، وطبقات الحنابلة، وشَرَحَ صحيح البخاري وأسماه ((فتح الباري في شرح البخاري)) ولم يُكمِله، وغيرها من المصنفات. توفي رحمه الله في اليوم الرابع من شهر رمضان وقيل رجب"},{"id":3197,"title":"مقتل الأمير منطاش الأشرفي .","date":["العام الهجري :795","الشهر القمري : رمضان","العام الميلادي :1393"],"text":"هو منطاش الأشرفي نسبةً إلى الأشرف شعبان بن حسين، كان اسمُه تمربغا، ويقال له أخو تمربيه، وكانت لتمربيه منزلةٌ من الأشرف، وتنقل منطاش إلى أنْ ولاه الظاهر برقوق نيابةَ السلطنة بملطية في سنة 788 فجمع كثيرًا من التركمان وأظهر العِصيانَ وانضوى إليه كثيرٌ مِن الأشرفيَّة الذين شَرَّدَهم برقوق لَمَّا تسَلْطَنَ في البلادِ، فلما بلغ الظاهِرَ ذلك جهَّزَ إليه عسكَرَ حلب مع أربعة أمراء من مقَدَّمي الألوف بالقاهرة، فانضوى منطاش إلى برهان الدين صاحب سيواس فحوصر، ثم آل الأمر إلى رجوع العسكر وقد فر منطاش، واتفق أنَّ الناصريَّ عصى على برقوق وكاتبَ نواب البلاد، فوافقوه فراسَلَ منطاش فجمع من أطاعَه، وحضر إلى حلب وذلك سنة 91 فجهَّزَه الناصري إلى حماة فمَلَكَها إلى أن قَدِمَ الناصري بالعسكر، فتوجهوا إلى القاهرة واستولى الناصريُّ على المملكة وأعاد السلطان حاجي، واستقر منطاش أميرًا كبيرًا، ثم استولى منطاش على المملكة، فطاش وكان أهوجَ كثيرَ العطايا، كما قيل نهابًا وهَّابًا، فاعتقل الناصِرَ والجوباني وغيرَهما بالإسكندرية، وفي غضون ذلك بعد دخول سنة 92 بلغه أن الظاهرَ برقوق خلَصَ مِن سجن الكرك وانضَمَّ إليه جماعة، فجهز العسكر وتوجَّه إلى جهته، فوقعت لهم الوقعة الشهيرة، فانهزم منطاش واحتوى الظاهِرُ على المملكةِ وعلى غالب من كان معه مِن رؤوس المملكة, وفي سنة 93 توجه منطاش من جهة العمق إلى أن وصل إلى قربِ دمشق، ولما لم يحصُلْ للعسكر السلطاني منه غَرَضٌ رجعوا إلى أوطانهم، ونازل منطاش دمشقَ فجَهَّزَ له الناصريُّ من هزمه، فتوجه إلى بلاد نعير فأقام عنده ثم راسَلَ الظاهِرُ نعيرًا في أمر منطاش واسترضاه ورَدَّ عليه إمرتَه، وأوسَعَ له في الوعدِ، فغدر بمنطاش وقَبَضَ عليه وجَهَّزَه إلى حلب فاعتقل بقلعَتِها إلى أن جاء الأمرُ بقَتلِه وتجهيز رأسِه، ففُعِلَ به ذلك في سنة 795 وطِيفَ برأسِه بالقاهرةِ، ثم عُلِّقَ على باب زويلة، وكان شجاعًا قَتَّالًا عاليَ الهِمَّة كثيرَ البَذلِ، أهلك جميعَ ما كان الظاهِرُ حَصَّلَه من الأموال في أيسَرِ مُدَّةٍ."},{"id":3198,"title":"تيمورلنك يحتل بغداد ويستبيح دماء أهلها وأموالهم .","date":["العام الهجري :795","الشهر القمري : شوال","العام الميلادي :1393"],"text":"في التاسع عشر من شوال قَدِمَ رسول الملك الظاهر مَجْد الدين عيسى صاحب ماردين بأن تَيْمورلنك أخذ تبريز، وبعث إليه يستدعيه إلى عنده بها، فاعتذر بمشاورة سلطان مصر، فلم يقبل منه، وقال: ليس لصاحب مصر عليك حكم، ولأسلافك دهر بهذا الإقليم، وأرسل إليه خِلعةً وصكة ينقُشُ بها الذهبَ والدنانير، ثم قدم رسول صاحب بسطام بأن تيمور قتل شاه منصور متملك أصفهان، وبعث برأسه إلى بغداد، وبعث بالخلعة والصكة إلى السلطان أحمد بن أويس متملك بغداد، فلبس الخِلعة وضرب الصكة، ثم إن تيمور مَلَكَ بغداد في يوم السبت الحادي والعشرين منه؛ وذلك أنَّ ابن أويس كان قد أسرف في قتل أمراء دولته، وبالغ في ظلم رعيته، وانهمك في الفجور؛ فكاتب أهلُ بغداد تيمور بعد استيلائه على تبريز يحثُّونه على المسير إليهم، فتوجه إليها بعساكره حتى بلغ الدربند، وهو عن بغداد مسيرة يومين، فبعث إليه ابن أويس بالشيخ نور الدين الخراساني، فأكرمه تيمور وقال: أنا أترك بغداد لأجلك, ورحل يريد السلطانية، فبعث الشيخ نور الدين كتُبَه بالبشارة إلى بغداد، وقَدِمَ في إثرها، وكان تيمور قد سار يريد بغداد من طريق آخر، فلم يشعر ابن أويس -وقد اطمأن- إلا تيمور قد نزل غربي بغداد، قبل أن يَصِلَ إليها الشيخ نور الدين، فدهش عند ذلك ابن أويس وأمر بقطع الجسر، ورحل بأمواله وأولاده وقت السَّحَر من ليلة السبت، وترك البلاد، فدخلها تيمور، وأرسل ابنه في إثر ابن أويس، فأدركه بالحلة، ونهب ماله، وسبى حريمه، وقتل وأسر كثيرًا ممن معه، ونجا ابن أويس في طائفةٍ وهم عراة، فقصد حلب وتلاحق به من تبقى من أصحابه، وأمَّا تيمور فإنه لما مَلَك بغداد صادر أهلها ثلاثَ مرات؛ في كل مرة منهم ألف تومان، وخمسمائة تومان، وكل تومان مبلغ ثلاثين ألف دينار عراقي، والدينار العراقي بقدر درهم مصر الفضة، حتى أفقرهم كلهم، وكان جملة ما أخذ منهم نحو مائة ألف ألف وخمسة وثلاثين ألف ألف درهم، بعد أن تنوَّع في عقوبتهم، وسقاهم المِلحَ والماء، وشواهم على النار، ولم يُبقِ لهم ما يستر عوراتهم، وصاروا يخرجون فيلتقطون الخِرَق من الطرقات حتى تُستَرَ عوراتهم وتُغطى رؤوسهم، ثم إنه بعث ابنه إلى الحلَّة، فوضع في أهلها السيف يومًا وليلة، وأضرم فيها النار حتى احترقت، وفني معظم أهلها ويقال: إنه قتل في العقوبة من أهل بغداد ثلاثة آلاف نفس، وبعث تيمور من بغداد العساكر إلى البصرة، فلَقِيَهم صاحبها الأمير صالح بن جولان، وحاربهم وأسر ابن تيمور، وقتل منهم خلقًا كثيرًا، فبعث إليه عسكرًا آخر في دجلة، فظفر بهم ابن جولان أيضًا، وفي التاسع عشر ذي الحجة أمر السلطان في القاهرة ومصر بتجهيز الناس للسفر لقتال تيمورلنك."},{"id":3199,"title":"مقتل أربعة رهبان بالقدس بسبب ذمهم الملة الإسلامية .","date":["العام الهجري :795","الشهر القمري : ذي الحجة","العام الميلادي :1393"],"text":"خرج أربعةٌ من رهبان النصارى بمدينة القدس، ودَعَوا الفقهاء لِمناظرتهم، فلما اجتمع الناس لهم جهَروا بالسوء من القول، وصرَّحوا بذم الملة الإسلامية، والإزراء على القائم بها، وأنَّه كذابٌ وساحر، وما الحق إلا في دين عيسى! فقُبِض عليهم وقُتِلوا وحُرقوا بالنار، فكان من الأيام المشهورة بالقدس."},{"id":3200,"title":"تيمورلنك يتوعد السلطان برقوق والسلطان يجهز جيشًا للقائه .","date":["العام الهجري :796","العام الميلادي :1393"],"text":"قام تيمورلنك بإرسال رسُلٍ مع هدايا إلى السلطان الظاهر برقوق صاحب الديار المصرية، ولكِنَّ السلطان قتَلَهم، فلما بلغ تيمورلنك ما فعله السلطان قام بكتابة رسالة كلها تهديد ووعيد، فأجابه السلطان بما يناسب رسالته من قوة وعدم خوف، وأمر السلطان برقوق بتجهيز العساكر حتى أخذ من خزانة أموال اليتامى؛ لتجهيز العسكر، وخرج من مصر في الرابع عشر من ربيع الآخر، ثم رحل عن غزة في الثاني عشر من جمادى الأولى، وقدم إلى مدينة دمشق رسل طقتمش خان، صاحب كرسي أزبك خان ببلاد القبجاق، بأنَّه يكون عونًا مع السلطان على تيمورلنك، ثم في العشرين منه دخل السلطان إلى دمشق، ثم في السابع عشر من رجب برزت العساكِرُ من دمشق تريد حلب، ولكن قدم الخبر أن تيمورلنك قد عاد إلى بلادِه."},{"id":3201,"title":"وفاة الملك أبو العباس أحمد صاحب فاس وتولي ابنه أبي فارس .","date":["العام الهجري :796","الشهر القمري : محرم","العام الميلادي :1393"],"text":"صاحب مملكة فاس من بلاد الغرب السلطان أبو العباس أحمد بن أبي سالم بن إبراهيم بن أبي الحسن على بن عثمان بن يعقوب بن عبد الحق المريني ملك الغرب، تولى حكم بلاد المغرب بعد خلع السعيد محمد بن عبد العزيز أبي الحسن في ذي الحجة 774. توفي أبو العباس أحمد في المحرَّم، وأقيم بعده ابنه أبو فارس عبد العزيز، وهو غير متملِّك تونس المتوكل على الله أبو العباس أحمد الحفصي صاحب تونس مع أنَّ اسمهما يكاد يتطابق."},{"id":3202,"title":"وفاة السلطان أبي العباس أحمد سلطان الحفصيين وتولي ابنه .","date":["العام الهجري :796","الشهر القمري : شعبان","العام الميلادي :1394"],"text":"هو السلطانُ أبو العباس أحمد بن محمد بن أبي بكر بن يحيى بن إبراهيم بن يحيى عبد الواحد بن أبي  حفص عمر بن ونودين الهنتاتي المغربي أبو العباس، ويلقَّبُ أبا السباع سلطان الحفصيين. ولي تونسَ وما معها من بلاد المغرب في سنة 772، وكان شهمًا شجاعًا ولي كلَّ من ذُكِر في عمود نسبه المملكة إلا أباه وجدَّ أبيه, وكانت وفاتُه في شعبان، توفي في ليلة الخميس رابع شعبان بمحل ملكه مدينة تونس من بلاد المغرب بعد أن حكمها أربعًا وعشرين سنة وثلاثة أشهر ونصفًا، وقام من بعده على ملك تونس ابنه السلطان أبو فارس عبد العزيز، وكان من أجَلِّ ملوك الغرب."},{"id":3203,"title":"استعادة حكم بغداد بعد طرد نائب تيمورلنك منها  .","date":["العام الهجري :796","الشهر القمري : شعبان","العام الميلادي :1394"],"text":"لَمَّا تيقَّن السلطان برقوق من عودة تيمورلنك إلى بلاده وجَّه في يوم الاثنين أول شعبان القان غياث الدين أحمد بن أويس من دمشق إلى بغداد، بعد أن قدم له جميع ما يحتاج إليه، وعند وداعه خلع عليه أطلسين بشاش متمر، وسيف بسقط ذهب، وأعطى تقليدًا بنيابة السلطنة ببغداد، ولما وصل إلى ظاهر بغداد خرج إليه نائب تيمور بها، وقاتله فانكسر النائب، ودخل بغداد، وأطلق المياه على عسكر ابن أويس ليُغرقه، فأعانه الله وتخلَّص منها بعد يومين، وعبر أويس بغداد، وقد هرب نائب تيمورلنك منها، فاستولى عليها ابن أويس، واستخدم جماعةً من التركمان والعربان، فلما بلغ ذلك تيمور جهَّز أمراءه بالأموال إلى سمرقندي."},{"id":3204,"title":"وفاة أبي الحجاج يوسف الثاني ملك بني نصر  وقيام ابنه محمد السابع .","date":["العام الهجري :797","العام الميلادي :1394"],"text":"هو أبو الحجَّاج يوسف الثاني بن محمد الخامس الغني بالله بن يوسف بن إسماعيل بن فرج بن إسماعيل بن يوسف ملك بني نصر ابن الأحمر المنحَدِر من قبيلة الخزرج القحطانية, فقام بالأمر بعده ابنُه محمد السابع متجاوزًا أخاه الأكبر يوسف؛ حيث قبَض عليه وسَجَنه."},{"id":3205,"title":"طقتمش المغولي يحارب قوات تيمورلنك في بلاد فارس .","date":["العام الهجري :797","الشهر القمري : جمادى الآخرة","العام الميلادي :1395"],"text":"قام طقتمش زعيم القبيل الأبيض والأزرق المغولي الذي كان انتصر على الروس فاغتَرَّ بقوته فأراد أن يحارب تيمورلنك فأغار على فارس التي مع تيمورلنك حتى حاصر بخارى، وهذا الذي اضطر تيمورلنك لملاقاته في معركة جرت في جمادى الآخرة وانتهت بهزيمة طقتمش."},{"id":3206,"title":"مقتل الشريف علي بن عجلان أمير مكة في معركة مع بني حسن .","date":["العام الهجري :797","الشهر القمري : شوال","العام الميلادي :1395"],"text":"هو الشريف أبو الحسن علي بن عجلان بن رميثة، واسمُ رُميثة منجد بن أبي نمي بن أبي سعد حسن بن علي بن قتادة بن إدريس بن مطاعن بن عبد الكريم بن عيسى بن عيسى بن حسين بن سليمان بن علي بن عبد الله بن محمد بن موسى بن عبد الله المحض بن موسى بن الحسن السبط بن الحسن بن علي بن أبي طالب المكي الحسني، أمير مكة المشرفة، وَلِيَها ثماني سنين ونحو ثلاثة أشهر مستقلًّا بالإمارة، غير سنتين أو نحوهما؛ فإنه كان فيهما شريكًا لِعَنان بن مغامس بن رميثة، ووقع له أمورٌ بمكة مع الأشراف ووقائع، وآخِرَ الأمر توجَّه أخوه الشريف حسن بن عجلان إلى القاهرة يريد إمرة مكة، فقبض عليه السلطان وحبسه، وبعث إلى أخيه علي هذا باستمراره على إمرة مكة، فاستمَرَّ على إمرتها إلى أن وقع بينه وبين بعض القوَّاد، وخرج إليهم عليٌّ، فبدره بعضُهم وسايرَه وهو راكب على راحلته، والشريف عليٌّ على الفرس، فرمى القائد بنفسه على الشريف عليٌّ وضربَه بجنبية كانت معه، فوقعا جميعًا على الأرض، فوثب عليه عليٌّ وضربه بالسيف ضربةً كاد منها يهلك، وولى عليٌّ راجعًا إلى الحلة، فأغرى به شخصٌ يقال له أبو نمي غلام لصهره حازم بن عبد الكريم جنديًّا، وعتبة وحمزة وقاسمًا، فوثبوا عليه وقتلوه وقطَّعوه وبعثوا به إلى مكة، فدُفِن بالمعلَّاة مع أبيه عجلان، وكان قتلُه يوم الأربعاء سابع شوال، ووَلِيَ إمرة مكة بعده أخوه حسن بن عجلان."},{"id":3207,"title":"تيمورلنك يهزم الأمير طولو بن علي شاه ويحتل بلاد القرم .","date":["العام الهجري :797","الشهر القمري : ذي الحجة","العام الميلادي :1395"],"text":"قدم الأمير طولو بن علي شاه المتوجِّه إلى طَقتمش خان، وأنه بعد ما اتفق معه على محاربة تيمورلنك توجَّه تيمورلنك لمحاربته، فسار إليه وقاتله ثلاثةَ أيام، فانكسر من تيمور، ومَرَّ إلى بلاد الروس؛ فخرج طولو من سراي إلى القرم، ومضى إلى الكفا، فعوَّقه متمَلِّكُها ليتقرَّبَ به إلى تيمور، حتى أخذ منه خمسين ألف درهم، فملك تيمور القرم والكفا وخرَّبَها."},{"id":3208,"title":"وفاة السلطان أبي فارس عبدالعزيز المريني صاحب فاس وتولي أخيه .","date":["العام الهجري :798","العام الميلادي :1395"],"text":"هو السلطانُ أبو فارس عبد العزيز بن السلطان أبي العباس أحمد بن أبي سالم بن إبراهيم بن أبي الحسن المريني ملك الغرب وصاحب فاس، أبو فارس، أقيم بعده على سلطنة فاس أخوه أبو عامر عبد الله. وهو يختلف عن السلطان أبي فارس عبد العزيز بن أبي العباس أحمد الحفصي ملك بلاد المغرب الذي توفي سنة 837."},{"id":3209,"title":"أخبار تيمورلنك وقتاله مع صاحب ماردين  .","date":["العام الهجري :799","العام الميلادي :1396"],"text":"حضر الأمير علاء الدين ألطبغا نائب الملك الظاهر مجد الدين عيسى صاحب ماردين، فأنعم عليه وعلى من معه، وكان سببُ قدومه أنَّ الظاهِرَ عيسى لما قبض عليه تيمورلنك وأقام في أسْرِه، قام ألطبغا بأمر ماردين ومنع تيمورلنك منها، وكان الظاهر قد أقام في مملكة ماردين الملك الصاع شهاب الدين أحمد بن إسكندر بن الملك الصالح صالح، وهو ابنُ أخيه وزوجُ ابنته، فقاتل أصحاب تيمورلنك قتالًا شديدًا، وقتل منهم جماعة، فشقَّ هذا على تيمورلنك، ثم أفرج عن الظاهر بعد أن أقام في أسره سنتين وسبعة أشهر، وحَلَّفه على الطاعة له وإقامة الخُطبة باسمه، وضَرْب السكة له، والقَبْض على ألطبغا وحَمْله، فعندما حضر إلى ماردين فرَّ منه ألطبغا إلى مصر، فرتَّب له السلطان ما يليقُ به، وقَدِمَت رسل تيمور إلى دمشق فعُوِّقوا بها، وحُمِلت كتُبُهم إلى السلطان فإذا فيها طلب أطلمش، فأمر أن يُكتَب إلى أطلمش بما هو فيه ورفيقه من إحسان السلطان، وكتب جوابه بأنه متى أرسل من عنده من أصحاب السلطان خبر إليه أطلمش."},{"id":3210,"title":"دخول تيمورلنك أزرنكان .","date":["العام الهجري :799","العام الميلادي :1396"],"text":"دخلت عساكر تيمورلنك إلى أزرنكان من بلاد الروم، وقُتِلَ كثير من التركمان، فتوجَّه الأمير تمربغا المنجكي على البريد؛ لتجهيز عساكر الشام إلى أرزنكان."},{"id":3211,"title":"اشتداد الغلاء بدمشق .","date":["العام الهجري :799","الشهر القمري : جمادى الآخرة","العام الميلادي :1397"],"text":"اشتدَّ الغلاء بدمشق، فخرج الناسُ يستسقون، وثاروا برجلٍ يُعرَف بابن النشو، كان يحتكِرُ الغِلالَ، وقتلوه شرَّ قِتلةٍ، وأحرقوه بالنار."},{"id":3212,"title":"وفاة أبي عامر المريني ملك المغرب وتولي أخيه أبي سعيد .","date":["العام الهجري :800","العام الميلادي :1397"],"text":"هو أبو عامر عبد الله بن السلطان أبي العباس أحمد بن أبي سالم إبراهيم بن أبي الحسن المريني ملك المغرب صاحب فاس، وأقيم بعده أخوه أبو سعيد عثمان بن أبي العباس، والشيخ أبو العباس أحمد بن علي القبايلي هو القائم بتدبير الدولة على عادته منذ موت السلطان أبي العباس أحمد في أيام أبي فارس عبد العزيز، وأبي عامر عبد الله."},{"id":3213,"title":"تيمورلنك يتجه إلى الهند ويستولي على دلهي وكشمير .","date":["العام الهجري :800","العام الميلادي :1397"],"text":"بلغ تيمورلنك موتُ محمد بن فيروز شاه تغلق ملك الهند وقيام صراع عنيف بين أمراء الولايات الهندية في عهد ابنه إسكندر، وأنَّ الحُكمَ استقَرَّ أخيرًا لابنه الآخر محمود، فتوجَّه تيمورلنك إلى الهند بجيش كبير مزوَّد بآلات الحرب الهائلة، فحاول السلطان محمود أن يقاتلَه، ولكنَّه انهزم فاحتَلَّ تيمورلنك دلهي وهرب السلطان محمود إلى كجرات، وأمعن تيمورلنك في القتل والنهب والتخريب، واستولى كذلك على كشمير، ثم عاد إلى بلاده تاركًا في هذه المناطق عاملًا له مِن قِبلِه."},{"id":3214,"title":"وقوع وباء بالوجه البحري وفشو الأمراض بالقاهرة ومصر .","date":["العام الهجري :800","الشهر القمري : ربيع الأول","العام الميلادي :1397"],"text":"وقع وباءٌ بالوجه البحري، وفَشَت الأمراض بالقاهرة ومصر. وكان قد خرج جماعةٌ من الأمراء إلى الصعيد، فمَرِضَ أكثرهم، وعاد الأمير قَلْمطاي الدوادار يوم الثلاثاء رابع ربيع الآخر، وهو مريض لا يثبُتُ على الفَرسِ."},{"id":3215,"title":"العثمانيون ينتصرون على ملوك أوروبا في موقعة نيقوبوليس .","date":["العام الهجري :800","الشهر القمري : ذي القعدة","العام الميلادي :1398"],"text":"لما أحرز العثمانيون الانتصاراتِ العديدةَ في المُدَد القصيرة، خاف ملوك أوروبا وخاصة ملك المجر الذي استغاث بالبابا والملوك، فأعلنها البابا حربًا صليبية دعا إليها الملوكَ؛ فاستجاب دوق بورغونيا شرق فرنسا، وأمراء النمسا وبافاريا قرب ألمانيا، وفرسان القديس يوحنا الذين كانوا يومها بمالطة، فسار الجميع يقودُهم ملك المجر \"سيجموند الأول\"، وبلغ قوامهم 120 ألف جندي مجتازين نهر الدانوب، وحاصروا مدينة نيكوبلي شمالي بلغاريا، وفاجأهم الجيش العثماني بقيادة السلطان بايزيد الأول ومعه مائتا ألف مقاتل، ومعه أيضًا أمير الصرب اصطفان بن لازار، ومعه كثير من الشعوب النصرانية الخاضعة للحماية العثمانية، فكان اللقاءُ بين الجيشين يوم 23 ذي القعدة سنة 800 (27 سبتمبر سنة 1396)، وقاتلهم قتالًا عنيفًا كانت نتيجتها انتصار العثمانيين على الجيوش المتألِّبة عليهم، وأسر كثير من أشراف فرنسا، منهم الكونت دي نيفر نفسه، وقُتِل أغلبهم وأُطلِقَ سراح الباقي، والكونت دي نيفر بعد دفع فداء اتُّفِق على مقداره. ويُقال إن السلطان بايزيد لما أطلق سراح الكونت دي نيفر وكان قد ألزم بالقَسَم على ألا يعود لمحاربته قال له: إني أجيز لك ألَّا تحفظ هذا اليمين؛ فأنت في حِلٍّ من الرجوع لمحاربتي؛ إذ لا شيء أحب إلي من محاربة جميع مسيحيي أوروبا والانتصار عليهم!! هذا وقد شدَّد الحصار بعد ذلك على مدينة القسطنطينية، ولولا إغارة تيمورلنك المغولي على بلاد آسيا الصغرى لتمكَّن السلطان بايزيد من فتحها، لكن الأمور مرهونة بأوقاتها، فاكتفى بإبرام الصلح مع ملكها هذه المرة بشرط دفع عشرة آلاف ذهب سنويًّا من عملة وقتها، وأن يجيز للمسلمين أن يبنوا بها جامعًا لإقامة شعائر الدين الحنيف، وأن تُقام لهم محكمة شرعية للنظر في قضايا المستوطِنين بها منهم."},{"id":3216,"title":"محاولة اغتيال السلطان الظاهر برقوق .","date":["العام الهجري :800","الشهر القمري : ذي القعدة","العام الميلادي :1398"],"text":"ركِبَ السلطان الظاهر برقوق بعد صلاة الظهر يريد المقياسَ من شهر ذي القعدة، وفتح الخليج على العادة، ومعه الأمراء إلا الأمير ألي باي الخازندار؛ فإنه كان قد انقطع في داره أيامًا لمرض نزل به فيما أظهره، وفي باطن أمره أنَّه قصد الفتك بالسلطان؛ فإنه علم أنَّه إذا نزل الخليج يدخل إليه ويعودُه على ما جرت به عادتُه مع الأمراء، فدبَّر اغتَيال السلطان، وأخلى إسطبله وداره من حريمه وأمواله، وأعدَّ قومًا اختارهم لذلك، وكان سبب هذا فيما يظهرُ أن بعض مماليكه المختصِّين به وكان شاد شراب خاناته تعرَّض لجارية من جواري الأمير أقباي الطرنطاي، يريد منها ما يريدُه الرجل من المرأة، وصار بينهما مُشاكلةٌ، فبلغ ذلك أقباي، فقَبَض عليه وضربه ضربًا مبرِّحًا، فحنق ألي باي وشكاه للسلطان فلم يلتفِت إلى قولِه، وأعرض عن ذلك، وكان ألي باي في زعمه أن السلطان يزيل نعمة أقباي لأجله، فغضِبَ من ذلك وحرَّك ما عنده من البغي الكامن، فلما فتح السلطان الخليجَ وركب إلى جهة القلعة اعترضه مملوكٌ من خشداشيته -زملاء عمله- اليلبغاوية، يُعرَف بسودن الأعور، وأسَرَّ إليه أنَّ دارَه التي يسكنها تُشرِفُ على إسطبل الأمير ألي باي، وأنَّه شاهد مماليك ألي باي وقد لبسوا بدلةَ الحرب، ووقفوا عند بوائك الخيل، وستروا البوائِكَ بالأنخاخ لِيَخفى أمرهم، فكتم السلطانُ الخبر، وأمر الأميرَ أرسطاي رأس نوبة أن يتوجَّه إلى دار الأمير ألي باي، ويُعلِمَهم أنَّ السلطانَ يدخل لعيادته، فلما أُعلِمَ بذلك اطمأنُّوا، ووقف أرسطاي على باب ألي باي ينتظر قدوم السلطان، وعندما بعث السلطان أرسطاي أمير الجاويشية بالسكوتِ، وأخذ العصابةَ السلطانية التي تُرفَعُ على رأس السلطان فيُعلَم بها مكانه، يريد بذلك تعميةَ خبرِه، وسار إلى تحت الكبش، وهو تجاه دار ألي باي، والناس من فوقه قد اجتمعوا لرؤية السلطان، فصاحت به امرأةٌ: لا تدخُل؛ فإنهم قد لبسوا آلة القتال، فحرَّك فرسه وأسرع في المشيِ ومعه الأمراء، ومن ورائه المماليكُ، يريد القلعة، وأما ألي باي فإنَّ بابه كان مردودَ الفردتين، وضبته مطرفة ليمنَعَ من يدخل حتى يأتيَ السلطان، فلما أراد اللهُ مَرَّ السلطان حتى تعدَّى بابه، وكان في طريقِه، فلم يعلموا بمروره حتى تجاوزَهم بما دبرَّه من تأخير العصائب وسكوت الجاويشية، وخرج أحد أصحاب ألي باي يريد فتح الضبة فأغلقها، وإلى أن يحضر مفتاح الضبة ويفتح فاتهم السلطان، وصار بينهم وبينه سدٌّ عظيم من الجمدارية، قد ملؤوا الشارع بعرضه، فخرج ألي باي بمن معه لابسين السلاح، وعمدهم نحو الأربعين فارسًا يريد السلطان، وقد ساق ومعه الأمراء حتى دخل باب السلسلة، وامتنع بالإسطبل، فوقف ألي باي تجاه الإسطبل بالرميلة تحت القلعة، ونزل إليه طائفةٌ من المماليك السلطانية لقتاله، فثبت لهم وجُرح جماعة، وقُتِل من السلطانية بيسق المصارِع ثم انهزم ألي باي، وتفرَّق عنه من معه، هذا وقد ارتجَّت مصر والقاهرة، وجفل الناسُ من مدينة مصر، وكانوا بها للفرجة على العادة في يوم الوفاء، وطلبوا مساكِنَهم خوفًا من النهابة، وركب يلبغا المجنون ومعه مماليكه لابسين بدلة القتال يريد القلعة، واختلف الناسُ في السلطان، وأرجفوا بقتله وبفراره، وتباينت الأقوالُ فيه، واشتد الخوفُ وعَظُم الأمر، وبات السلطانُ بالإسطبل، وقد نَهَبت العامة بيت ألي باي وخرَّبوه، ونهبوا دار الأمير يلبغا المجنون وخربوها، وأما ألي باي فإنه لما تفرَّق عنه أصحابه اختفى في مستوقد حمام، فقُبِض عليه، وحُمِل إلى السلطان فقَيَّده وسجنه بقاعة الفضة من القلعة، فلما أصبح نهار الأحد نزع العسكر آلةَ الحرب وتفرَّقوا، وعُصر ألي باي، فلم يُقِرَّ على أحد، وأُحضر يلبغا المجنون فحلف أنه لم يوافقْه، ولا عِلمَ بشيء من خبره، وأنه كان مع الوزير بمصر."}]
